INSERT INTO `aportaciones_destacadas` VALUES (1, 1, 'Son las acciones realizadas por iniciativa de la persona Servidora Pública Evaluada, cuyos resultados puedan ser verificados y documentados; que contribuyan a mejorar el desempeño de sus funciones o que impliquen una contribución al desarrollo de capital humano en otras personas servidoras públicas, en su caso, contribuyan en la mejora de la CONANP o aporten beneficios a la población. Deben cumplir con cada uno de los siguientes requisitos.', 2025, 1, '1744326171_reporte_1_1_20250410_230044.pdf', '2025-04-24 09:29:56', '2025-04-24 09:29:56', NULL, NULL, NULL, 0);
