INSERT INTO `sed_individuales` VALUES (2, 'AABC900525', 'CONCENTRAR LA INFORMACIÓN TRIMESTRAL Y SUS MEDIOS DE VERIFICACIÓN, DEL PROGRAMA OPERATIVO ANUAL 2024. ASÍ COMO SU CAPTURA EN EL SISTEMA GENERAL DE PROGRAMAS OPERATIVOS ANUALES SGPOA.', '10', '20', '0.9', '0.7', '0.5', '90', 'IMPLEMENTAR RECORRIDOS DE VIGILANCIA EN COORDINACIÓN CON PROFEPA, POLICÍA DE MONTAÑA Y SEGURIDAD PUBLICA PARA TRATAR DE INHIBIR Y PREVENIR ILÍCITOS AMBIENTALES EN EL PARQUE NACIONAL IZTACCÍHUATL POPOCATÉPETL Y SU ZONA DE INFLUENCIA.', '10', '20', '0.9', '0.7', '0.5', '90', 'REALIZAR LAS OPINIONES TÉCNICAS Y DENUNCIAS AMBIENTALES ANTE LAS INSTITUCIONES CORRESPONDIENTES, POR ACTIVIDADES ILÍCITAS EN EL PARQUE NACIONAL IZTACCÍHUATL POPOCATÉPETL.', '10', '20', '0.9', '0.7', '0.5', '90', 'APOYAR A LA DIRECCIÓN DEL ANP EN EL SEGUIMIENTO ADMINISTRATIVO Y TÉCNICO DE PROYECTOS EXTERNOS IMPLEMENTADOS EN EL ANP, PARA CONTINUAR CON LAS ACCIONES DE CONSERVACIÓN, PROTECCIÓN Y MANEJO DE SUS ECOSISTEMAS.', '10', '20', '0.9', '0.7', '0.5', '90', 'ATENDER LAS SOLICITUDES DE INFORMACIÓN, EVENTOS Y REUNIONES RELACIONADOS CON EL TEMA DE VIGILANCIA, PARA LA ADECUADA OPERACIÓN DEL ANP Y EL CUMPLIMIENTO DEL PROGRAMA DE MANEJO.', '10', '20', '0.9', '0.7', '0.5', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
