INSERT INTO `sed_individuales` VALUES (27, 'AERK860102', 'REVISAR EL 100% DE LOS ANEXOS DE PROYECTOS AUTORIZADOS DEL PROCODES QUE ENVÍAN LAS ANP EN MANERA DIGITAL PARA AGILIZAR TIEMPO DE RECEPCIÓN Y ASÍ MISMO REALIZAR LAS OBSERVACIONES CORRESPONDIENTES.', '05', '30', 'QUE SE REVISE EL 100% DE LOS ANEXOS DE PROYECTOS PROCODES APROBADOS Y SE RESPONDA DE MANERA OPORTUNA.', 'QUE SE REVISE EL 90% DE LOS ANEXOS DE PROYECTOS PROCODES APROBADOS Y SE REALICEN LAS OBSERVACIONES A DESTIEMPO.', 'QUE SE REVISE EL 80% DE LOS ANEXOS DE PROYECTOS PROCODES APROBADOS Y SE REALICEN LAS OBSERVACIONES A DESTIEMPO.', '90', 'GESTIONAR EL 100% DE LOS PAGOS DE LOS PROYECTOS APROBADOS DEL PROCODES A TIEMPO Y BRINDAR SEGUIMIENTO A LOS MISMOS', '05', '30', 'QUE SE GESTIONEN EL 100% DE LOS PAGOS DE LOS PROYECTOS APROBADOS A TIEMPO Y SE BRINDE UN SEGUIMIENTO HASTA LA CONCLUSIÓN DE LOS PROYECTOS PROCODES.', 'QUE SE GESTIONEN EL 90% DE LOS PAGOS DE LOS PROYECTOS APROBADOS FUERA DEL TIEMPO ESTABLECIDO EN LINEAMIENTOS Y SE BRINDE UN SEGUIMIENTO HASTA LA CONCLUSIÓN DE LOS PROYECTOS PROCODES.', 'QUE SE GESTIONEN EL 80% DE LOS PAGOS DE LOS PROYECTOS APROBADOS FUERA DEL TIEMPO ESTABLECIDO EN LINEAMIENTOS Y QUE NO SE BRINDE UN SEGUIMIENTO HASTA LA CONCLUSIÓN DE LOS PROYECTOS PROCODES.', '90', 'CAPACITAR Y ACTUALIZAR A EL 100% DE LOS TÉCNICOS OPERATIVOS DE LAS ANPS ADSCRITAS A LA DIRECCIÓN REGIONAL EL LA NORMATIVIDAD, Y OPERACIÓN DE LOS PROGRAMAS DE SUBSIDIO, SISTEMAS DE INFORMACIÓN Y CONTRALORIA SOCIAL', '04', '15', 'CAPACITAR Y ACTUALIZAR AL 100% DE LOS TÉCNICOS OPERATIVOS DE LAS ANP´S ADSCRITAS A LA DIRECCIÓN REGIONAL SOBRE LA NORMATIVIDAD Y CORRECTA APLICACION DE LOS PROGRAMAS DE SUBSIDIO', 'CAPACITAR Y ACTUALIZAR AL 90% DE LOS TECNICOS OPERATIVOS DE LAS ANP ADSCRITAS A LA DIRECCION REGIONAL, SOBRE LA NORMATIVIDAD Y CORRECTA APLICACIÓN DE LOS PROGRAMAS DE SUBSIDIO', 'CAPACITAR AL 80% DE LOS TÉCNICOS OPERATIVOS DE LAS ANP ADSCRITAS A LA DIRECCIÓN REGIONAL Y NO BRINDAR LA ACTUALIZACIÓN DE LA NORMATIVIDAD DE LOS PROGRAMAS DE SUBSIDIOS.', '70', 'RESPONDER EN TIEMPO Y FORMA A LAS SOLICITUDES DE INFORMACIÓN QUE SE RECIBEN SOBRE LOS PROGRAMAS DE SUBSIDIO OPERADOS POR LAS ÁREAS ADSCRITAS A LA DIRECCIÓN REGIONAL', '02', '10', 'RESPONDER A LAS SOLICITUDES DE INFORMACIÓN QUE SE RECIBEN SOBRE LA OPERACIÓN DE LOS PROGRAMAS DE SUBSIDIO DE LAS ÁREAS ADSCRITAS A LA DIRECCIÓN REGIONAL', 'QUE SE RESPONDA FUERA DE TIEMPO A LAS SOLICITUDES DE INFORMACIÓN RECIBIDAS SOBRE LA OPERACIÓN DE LOS PROGRAMAS DE SUBSIDIO DE LAS ÁREAS ADSCRITAS A LA DIRECCIÓN REGIONAL', 'QUE NO SE BRINDE UNA RESPUESTA A LAS SOLICITUDES DE INFORMACIÓN RECIBIDAS SOBRE LA OPERACIÓN DE LOS PROGRAMAS DE SUBSIDIOS DE LAS ANP ADSCRITAS A LA DIRECCIÓN REGIONAL', '90', 'REALIZAR 2 SUPERVISIONES EN CAMPO Y GABINETE DE LOS PROYECTOS APROBADOS DE LOS DIFERENTES PROGRAMAS DE SUBSIDIOS, QUE SEAN DEFINIDOS DENTRO DEL PROGRAMA ANUAL DE SUPERVISIÓN.', '04', '15', 'REALIZAR 2 SUPERVISIONES DE LOS PROGRAMAS DE SUBSIDIOS DEFINIDAS EN EL PROGRAMA ANUAL DE SUPERVISION', 'REALIZAR 1 SUPERVISION DE LOS PROGRAMAS DE SUBSIDIOS DEFINIDAS EN EL PROGRAMA ANUAL DE SUPERVISION', 'QUE NO SE REALICE LA SUPERVISION DE LOS PROGRAMAS DE SUBSIDIOS DE LAS ANP DEFINIDAS EN EL PROGRAMA ANUAL DE SUPERVISION', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
