INSERT INTO `sed_individuales` VALUES (29, 'AESD850527', 'COADYUVAR EN LA ELABORACIÓN, IMPLEMENTACIÓN Y SEGUIMIENTO DEL PROGRAMA OPERATIVO ANUAL DEL COMPLEJO XCALAK- CHINCHORRO PARA FORTALECER EL PROCESO EFECTIVO DE LA PLANEACIÓN Y CUMPLIMIENTO DE SUS OBJETIVOS.', '10', '20', 'SE CUMPLEN EN TIEMPO Y FORMA AL 100% LAS ACTIVIDADES PROGRAMAS EN EL POA DEL COMPLEJO XCALAK-CHINCHORRO', 'SE CUMPLEN EN UN 80% LAS ACTIVIDADES PROGRAMADAS EN EL POA DEL COMPLEJO XCALAK-CHINCHORRO', 'SE CUMPLEN EN UN 50% LAS ACTIVIDADES PROGRAMADAS EN EL POA DEL COMPLEJO XCALAK-CHINCHORRO', '90', 'PROMOVER LA OBSERVANCIA DEL PROGRAMA DE CONSERVACIÓN Y MANEJO DEL PARQUE NACIONAL ARRECIFES DE XCALAK Y DE LA RESERVA DE LA BIOSFERA BANCO CHINCHORRO, ASÍ COMO DE LAS REGLAS ADMINISTRATIVAS DEL MISMO PARA EL CUMPLIMIENTO DE LAS DISPOSICIONES LEGALES APLICABLES Y GARANTIZAR LA CONSERVACIÓN DE AMBAS ANP.', '10', '20', 'SE REALIZAN EN UN 100% ACCIONES QUE PERMITAN EL CUMPLIMIENTO DE LAS REGLAS ADMINISTRATIVAS DE LOS PROGRAMAS DE MANEJO DE AMBAS ANP', 'SE REALIZAN EN UN 80% ACCIONES QUE PERMITAN EL CUMPLIMIENTO DE LAS REGLAS ADMINISTRATIVAS DE LOS PROGRAMAS DE MANEJO DE AMBAS ANP', 'SE REALIZAN EN UN 50% ACCIONES QUE PERMITAN EL CUMPLIMIENTO DE LAS REGLAS ADMINISTRATIVAS DE LOS PROGRAMAS DE MANEJO DE AMBAS ANP', '90', 'COORDINAR EL DESARROLLO DE ACCIONES Y PROYECTOS RELACIONES CON ORDENAMIENTO PRODUCTIVO, DESARROLLO COMUNITARIO Y TURÍSTICOS, SUPERVISIÓN Y VIGILANCIA, EDUCACIÓN AMBIENTAL, COMUNICACIÓN, CONSERVACIÓN, MONITOREO, INVESTIGACIÓN CIENTÍFICA Y RESTAURACIÓN DE AMBAS ANP PARA CUMPLIR CON LOS OBJETIVOS PLANTEADOS EN LAS DECLARATORIAS CORRESPONDIENTES, ASÍ COMO EN SU PROGRAMA DE MANEJO.', '10', '20', 'SE COORDINAN AL 100% DIVERSAS ACCIONES Y PROYECTOS QUE PERMITAN CUMPLIR CON LOS OBJETOS DE CREACIÓN DE AMBAS ANP.', 'SE COORDINAN AL 80% DIVERSAS ACCIONES Y PROYECTOS QUE PERMITAN CUMPLIR CON LOS OBJETOS DE CREACIÓN DE AMBAS ANP.', 'SE COORDINAN AL 50% DIVERSAS ACCIONES Y PROYECTOS QUE PERMITAN CUMPLIR