INSERT INTO `sed_individuales` VALUES (30, 'AIAJ670428', 'ELABORAR LA NORMATIVIDAD ESPECÍFICA PARA LOS PROGRAMAS DE SUBSIDIO A CARGO DE LA DIRECCIÓN GENERAL DE OPERACIÓN REGIONAL.', '01', '30', 'SE ELABORAN LAS REGLAS DE OPERACIÓN DEL PROCODES Y LINEAMIENTOS INTERNOS PARA LA EJECUCIÓN DE 2 PROGRAMAS DE SUBSIDIO.', 'SE ELABORAN LAS REGLAS DE OPERACIÓN DEL PROCODES Y LINEAMIENTOS INTERNOS PARA LA EJECUCIÓN DE 1 PROGRAMA DE SUBSIDIO.', 'SOLO SE ELABORAN LAS REGLAS DE OPERACIÓN DEL PROCODES', '90', 'CAPACITAR AL PERSONAL TÉCNICO DE LAS ÁREAS NATURALES PROTEGIDAS Y DE LAS DIRECCIONES REGIONALES SOBRE LA NORMATIVIDAD Y OPERACIÓN DE LOS PROGRAMAS DE SUBSIDIO.', '01', '10', 'SE REALIZAN 1 CURSO NACIONAL PARA LA CAPACITACIÓN DE LA UNIDADES DE ENLACE REGIONAL Y AL PERSONAL TÉCNICO DE LAS ANP.', 'SE REALIZA 1 CURSO REGIONAL DE CAPACITACIÓN A LA UNIDADES DE ENLACE REGIONAL DE PROGRAMAS DE SUBSIDIO.', 'NO SE REALIZAN CURSOS DE CAPACITACIÓN AL PERSONAL TÉCNICO DE LAS ANP Y DE DIRECCIONES REGIONALES.', '90', 'ELABORAR LAS MATRICES DE INDICADORES DE RESULTADOS DE LOS PROGRAMAS DE SUBSIDIO Y SE ELABORAN LOS REPORTES TRIMESTRALES DE AVANCE DE LOS INDICADORES DE LOS PROGRAMAS.', '01', '40', 'SE ELABORAN LAS MATRICES DE INDICADORES DE RESULTADOS DE DOS PROGRAMAS DE SUBSIDIO Y SE REALIZAN 3 REPORTES TRIMESTRALES DE SU AVANCE.', 'SE ELABORAN LA MATRIZ DE INDICADORES DE RESULTADOS DE UN PROGRAMA DE SUBSIDIO Y SE REALIZA UN REPORTE TRIMESTRAL DE AVANCE.', 'SE ELABORAN LA MATRIZ DE INDICADORES DE RESULTADOS DE UN PROGRAMA DE SUBSIDIO Y NO SE LOS REPORTES TRIMESTRAL DE AVANCE.', '90', 'COORDINAR Y EJECUTAR EL PROGRAMA ANUAL DE SUPERVISIÓN Y CONTROL DE LOS PROGRAMAS DE SUBSIDIO A CARGO DE LA DIRECCIÓN GENERAL DE OPERACIÓN REGIONAL.', '01', '20', 'SE ELABORA EL PROGRAMA ANUAL DE SUPERVISIÓN Y CONTROL DE LOS PROGRAMAS DE SUBSIDIO Y SE REALIZAN TRES VISITAS DE SUPERVISIÓN.', 'SE ELABORA EL PROGRAMA ANUAL DE SUPERVISIÓN Y CONTROL DE LOS PROGRAMAS DE SUBSIDIO Y NO SE REALIZAN VISITAS DE SUPERVISIÓN.', 'NO SE ELABORA EL PROGRAMA ANUAL DE SUPERVISIÓN Y CONTROL DE LOS PROGRAMAS DE SUBSIDIO Y NO SE LLEVA A CABO NINGUNA VISITA DE SUPERVISIÓN.', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
