INSERT INTO `sed_individuales` VALUES (47, 'AUMJ750831', 'COORDINAR LA ELABORACIÓN EN EL SISTEMA DE LOS PROGRAMAS OPERATIVOS ANUALES Y DE LOS INFORMES TRIMESTRALES DE CADA UNA DE LAS ANP DE LA REGIÓN NORESTE.', '01', '20', '17 ÁREAS PROTEGIDAS CON PROGRAMA OPERATIVO ANUAL E INFORMES TRIMESTRALES', '15 REAS PROTEGIDAS CON PROGRAMA OPERATIVO ANUAL E INFORMES TRIMESTRALES', '13 REAS PROTEGIDAS CON PROGRAMA OPERATIVO ANUAL E INFORMES TRIMESTRALES', '90', 'COADYUVAR EN LA EJECUCIÓN DE LOS PROGRAMAS DE SUBSIDIO DE PROCODES Y PROREST, EN EL PARQUE NACIONAL EL SABINAL.', '01', '25', '2 PROGRAMAS DE SUBSIDIO OPERANDO EN EL ANP.', '1 PROGRAMA DE SUBSIDIO OPERANDO EN EL ANP', '0 PROGRAMAS DE SUBSIDIO OPERANDO EN EL ANP.', '90', 'ELABORAR LAS RESPUESTAS EN MATERIA DE ACCESO A LA INFORMACIÓN QUE SOLICITE EL ÁREA COMPETENTE.', '10', '15', '100 PORCIENTO DE LAS SOLICITUDES CONTESTADAS EN TIEMPO Y FORMA', '90 PORCIENTO DE LAS SOLICITUDES CONTESTADAS EN TIEMPO Y FORMA', '80 PORCIENTO DE LAS SOLICITUDES CONTESTADAS EN TIEMPO Y FORMA', '90', 'COADYUVAR EN LA EJECUCIÓN DEL PROYECTO CUMBRES RESILIENTES.', '01', '25', '4 ANP INTEGRADAS AL PROYECTO DE CUMBRES RESILIENTES', '3 ANP INTEGRADAS AL PROYECTO DE CUMBRES RESILIENTES', '2 ANP INTEGRADAS AL PROYECTO DE CUMBRES RESILIENTES', '90', 'MANTENER ACTUALIZADA LA BASE DE DATOS GEOGRÁFICA DE LAS ANP DE LA REGIÓN NORESTE.', '01', '15', '1 BASE DE DATOS CON DATOS GEOGRÁFICOS DE 19 ÁREAS NATURALES PROTEGIDAS', '1 BASE DE DATOS CON DATOS GEOGRÁFICOS DE 15 ÁREAS NATURALES PROTEGIDAS', '1 BASE DE DATOS CON DATOS GEOGRÁFICOS DE 10 ÁREAS NATURALES PROTEGIDAS', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidenci