INSERT INTO `sed_individuales` VALUES (48, 'AUVE710804', 'ELABORAR Y COORDINAR LA EJECUCIÓN DEL PROGRAMA OPERATIVO ANUAL DEL ÁREA DE PROTECCIÓN DE LOS RECURSOS NATURALES, CUENCA HIDROGRÁFICA RÍO NECAXA; CON BASE EN SU DECRETO Y ORDENAMIENTOS LEGALES APLICABLES EN LA MATERIA. ASÍ COMO ELABORAR Y ENTREGAR EN TIEMPO Y FORMA 4 INFORMES TRIMESTRALES DE LAS ACCIONES Y AVANCES OBTENIDOS.', '08', '20', 'SE GENERA PROGRAMA OPERATIVO ANUAL Y SE ENTREGAN 4 INFORMES TRIMESTRALES QUE INTEGRAN TODAS LAS ACTIVIDADES PROGRAMADAS Y AL FINAL DEL AÑO SE ENTREGA EL ANÁLISIS DE LOS IMPACTOS OBTENIDOS EN BENEFICIO DE LA CONSERVACIÓN DEL ÁREA', 'SE ELABORA EL POA DEL ANP Y SE CUMPLE PARCIALMENTE LAS ACTIVIDADES PROGRAMAS', 'NO SE PRESENTA EL POA DEL ANP', '90', 'EMITIR OPINIONES TÉCNICAS DE SOPORTE A LA DIRECCIÓN REGIONAL PLANICIE COSTERA Y GOLFO DE MÉXICO, PARA EL OTORGAMIENTO, MODIFICACIÓN, PRORROGA, RESCATE, SUSPENSIÓN, REVOCACIÓN O ANULACIÓN DE CONCESIONES, PERMISOS Y LICENCIAS.', '08', '20', 'SE ENTREGAN EN TIEMPO Y FORMA EL 100 % DE OPINIONES TÉCNICAS SOLICITADAS POR LA DIRECCIÓN REGIONAL PLANICIE COSTERA Y GOLFO DE MÉXICO', 'SE ENTREGAN LAS OPINIONES TÉCNICAS FUERA DEL TIEMPO ESTABLECIDO POR LA DIRECCIÓN REGIONAL PLANICIE COSTERA Y GOLFO DE MÉXICO', 'NO SE CUMPLE CON LA ENTREGA DE OPINIONES TÉCNICAS', '90', 'COORDINAR, SUPERVISAR Y ASEGURAR QUE LOS PROGRAMAS DE SUBSIDIO DEL ÁREA DE PROTECCIÓN DE RECURSOS NATURALES CUENCA HIDROGRÁFICA RÍO NECAXA, SE REALICEN DE ACUERDO A LAS REGLAS DE OPERACIÓN, LOS LINEAMIENTOS Y NORMATIVIDAD APLICABLE EN LA MATERIA.', '10', '20', 'EL TOTAL DE LOS PROGRAMAS DE SUBSIDIO QUE OPERAN EN EL ANP CUMPLEN CON LAS REGLAS DE OPERACIÓN, LINEAMIENTOS Y NORMATIVIDAD EN LA MATERIA.', 'SE OPERAN PROGRAMAS DE SUBSIDIO CON OBSERVACIONES AL CUMPLIMIENTO DE LAS REGLAS DE OPERACIÓN, LINEAMIENTOS Y NORMATIVIDAD EN LA MATERIA', 'NO SE OPERAN PROGRAMAS DE SUBSIDIOS', '90', 'SUPERVISAR QUE LAS ACCIONES QUE SE REALICEN DENTRO DEL ANP Y QUE ESTÉN SUJETAS A ORDENAMIENTOS JUR