INSERT INTO `sed_individuales` VALUES (73, 'CACG871010', 'AUMENTAR EL CONOCIMIENTO DE LA POBLACIÓN LOCAL DE LAS Y LO VISITANTES, ASÍ COMO EL PÚBLICO EN GENERAL SOBRE EL PN ISLA CONTOY Y LOS SERVICIOS AMBIENTALES QUE PRESTAN', '10', '20', 'SE ATIENDEN ENTRE EL 80 Y EL 100% LOS EVENTOS Y ACCIONES DE DIFUSIÓN PROGRAMADAS', 'SE ATIENDEN ENTRE EL 74 Y EL 60% LOS EVENTOS Y ACCIONES DE DIFUSIÓN PROGRAMADAS', 'SE ATIENDEN MENOS DEL 60% DE LOS EVENTOS Y ACCIONES DE DIFUSIÓN PROGRAMADAS', '90', 'ASEGURAR LA PARTICIPACIÓN ACTIVA DE LAS PERSONAS VINCULADAS A LA REALIZACIÓN DE ACTIVIDADES TURÍSTICAS EN EL PNIC (TRIPULACIÓN. CONDUCTORES, AGENCIAS DE VIAJES, ETC) PARA EL CUIDADO DE LOS RECURSOS NATURALES', '10', '20', 'SE REALIZAN ENTRE EL 90 Y EL 80% DE LOS CURSOS DE CAPACITACIÓN PROGRAMADOS ASÍ COMO LOS RECORRIDOS PARA VERIFICAR LA FORMA EN QUE LAS Y LOS CONDUCTORES ASÍ COMO LA TRIPULACIÓN DE LAS EMBARCACIONES, SOCIALIZAN LA INFORMACIÓN BRINDADA EN LA CAPACITACIÓN', 'SE REALIZAN ENTRE EL 70 Y EL 65% DE LOS CURSOS DE CAPACITACIÓN PROGRAMADOS ASÍ COMO LOS RECORRIDOS PARA VERIFICAR LA FORMA EN QUE LAS Y LOS CONDUCTORES ASÍ COMO LA TRIPULACIÓN DE LAS EMBARCACIONES, SOCIALIZAN LA INFORMACIÓN BRINDADA EN LA CAPACITACIÓN', 'SE REALIZAN MENOS DEL 50 % DE LOS CURSOS DE CAPACITACIÓN PROGRAMADAS ASI COMO LOS RECORRIDOS PARA VERIFICAR LA FORMA EN QUE LAS Y LOS CONDUCTORES ASÍ COMO LA TRIPULACIÓN DE LAS EMBARCACIONES', '90', 'SE REALIZARAN EN COORDINACIÓN CON OTRAS DEPENDENCIAS, Y CON EL APOYO DE VOLUNTARIAS (O), PRESTADORES DE SERVICIOS TURISTICOS Y PESCADORES, CAMPAÑAS DE LIMPIEZA DE PLAYA, MAGLAR Y SENDEROS INTERPRETATIVOS, EN EL MARCO DE FECHAS CONMEMORATIVAS MEDIOAMBIENTALES, ENTRE ELLASEL DÍA DE LA EDUCACIÓN, EL DÍA DE LOS HUMEDALES, EL DÍA MUNDIAL DEL AMEDIO AMBIENTE, EL DÍA NACIONAL DE LA LIMPIEZA DE PLAYAS Y LA SEMANA POR LA CONSERVACIÓN', '10', '20', 'REALIZAR 2 CAMPAÑAS DE LIMPIEZA EN EL ANP Y ÁREAS ALEDAÑAS', 'REALIZAR 1 CAMPAÑA DE LIMPIEZA EN EL ANP Y ALEDAÑAS', 'REALIZAR 1 CAMPAÑA DE LIMPIEZA EN EL ANP Y ALEDAÑAS', '90', 'PROMOVER LA CONSOLIDACIÓN DEL CONSEJO ASESOR DEL PN ISLA CONTOY', '10', '20', 'SE REALIZARAN ENTRE EL 70 Y EL 80% DE LAS REUNIONES PROGRAMADAS DE CONSEJO ASESOR Y DE LAS COORDINACIONES O SUBCONSEJO QUE LO INTEGRAN', 'SE REALIZARAN ENTRE EL 70 Y 75 % DE LAS REUNIONES PROGRAMADAS DE CONSEJO ASESOR Y DE LAS COORDINACIONES O SUBCONSEJO QUE LO INTEGRAN', 'SE REALIZAN MENOS DEL 50% DE LOS CURSOS DE CAPACITACIÓN PROGRAMADOS.', '90', 'PROMOVER QUE LAS PRACTICAS DE APROVECHAMIENTO DE LOS RECURSOS MARINOS SEAN ATENDIDAS Y APROPIADAS POR LOS PESCADORES PARA QUE SE REALICEN DE MANERA SUSTENTABLE.', '10', '20', 'SE REALIZAN ENTRE EL 75 Y EL 85% DE LAS PLATICAS Y CURSO DE CAPACITACIÓN PROGRAMADAS', 'SE REALIZAN ENTRE EL 70Y 60% DE LAS PLATICAS Y CURSOS DE CAPACITACIÓN PROGRAMADOS', 'SE REALIZAN MENOS DEL 50% DE LAS PLATICAS Y CURSOS DE CAPACITACIÓN PROGRAMADOS', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (74, 'CACJ700613', 'ORGANIZAR, OPERAR, SUPERVISAR Y DAR SEGUIMIENTO A LOS PROYECTOS DE SUBSIDIOS EN SU EJERCICIO FISCAL DE 2024 QUE SE AUTORICEN PARA EL ANP, APEGÁNDOSE A LAS REGLAS DE OPERACIÓN Y LINEAMIENTOS DE LOS PROGRAMA DE SUBSIDIOS Y REALIZAR EL CIERRE DE LOS PROYECTOS AUTORIZADOS EN EL MES DE DICIEMBRE DEL PRESENTE AÑO.', '04', '20', '81-90%', '71-80%', '0-70%', '90', 'COADYUVAR Y PARTICIPAR CON PERSONAL DE LA PROFEPA EN LAS ACCIONES DE DETECCIÓN, ATENCIÓN Y SEGUIMIENTO A DELITOS AMBIENTALES QUE SE DETECTEN DENTRO DEL ANP.', '04', '20', '81-90%', '71-80%', '0-70%', '70', 'ACTUALIZAR TRES BASES DE DATOS CON INFORMACIÓN GENERADO POR LOS MONITOREOS BIOLÓGICOS QUE SE REALIZAN EN EL ANP.', '04', '20', '81-90%', '71-80%', '0-70%', '90', 'COORDINAR, OPERAR Y SUPERVISAR LAS ACCIONES DE PREVENCIÓN, CONTROL Y COMBATE DE INCENDIOS FORESTALES QUE SE DETECTEN DENTRO DEL ANP', '04', '30', '81-90%', '71-80%', '0-70%', '90', 'COORDINAR Y PARTICIPAR CON PERSONAL DE OTRAS INSTITUCIONES QUE REALICEN ACCIONES DE PREVENCIÓN, CONTROL Y SEGUIMIENTO DE ESPECIES INVASORAS Y EXÓTICAS QUE SE DEN DENTRO EL ANP', '04', '10', '81-90%', '71-80%', '0-70%', '70', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (75, 'CADD780219', '\"SUPERVISAR DURANTE EL EJERCICIO 2024 LAS ACTIVIDADES QUE REALIZAN LOS USUARIOS DENTRO DEL POLÍGONO DE PROTECCIÓN DEL PARQUE NACIONAL COSTA OCCIDENTAL DE ISLA MUJERES PUNTA CANCÚN PUNTA NIZÚC (PNCOIMPCPN) PARA VERIFICAR QUE CUMPLAN CON LAS REGLAS ESTABLECIDAS EN EL PROGRAMA DE MANEJO VIGENTE Y NORMATIVIDAD APLICABLE EN MATERIA DE ÁREAS NATURALES PROTEGIDAS (ANP). \"', '10', '40', '\"\"\"QUE SE LLEVE A CABO EL 100% DE LOS RECORRIDOS DE SUPERVISIÓN DESIGNADOS DURANTE EL EJERCICIO 2023 DENTRO DEL POLÍGONO DE PROTECCIÓN DEL (PNCOIMPCPN) PARA VERIFICAR QUE LOS PRESTADORES DE SERVICIOS TURÍSTICOS, VISITANTES Y USUARIOS EN GENERAL CUMPLAN CON LAS REGLAS ESTABLECIDAS EN EL PROGRAMA DE MANEJO VIGENTE Y NORMATIVIDAD APLICABLE EN MATERIA DE ANPS \"\" \"', '\"\"\"QUE SE LLEVE A CABO EL 50% DE LOS RECORRIDOS DE SUPERVISIÓN DESIGNADOS DURANTE EL EJERCICIO 2023 DENTRO DEL POLÍGONO DE PROTECCIÓN DEL (PNCOIMPCPN) PARA VERIFICAR QUE LOS PRESTADORES DE SERVICIOS TURÍSTICOS, VISITANTES Y USUARIOS EN GENERAL CUMPLAN CON LAS REGLAS ESTABLECIDAS EN EL PROGRAMA DE MANEJO VIGENTE Y NORMATIVIDAD APLICABLE EN MATERIA DE ANPS \"\" \"', '\"\"\"QUE SOLO SE LLEVE A CABO EL 30% DE LOS RECORRIDOS DE SUPERVISIÓN DESIGNADOS DURANTE EL EJERCICIO 2023 DENTRO DEL POLÍGONO DE PROTECCIÓN DEL (PNCOIMPCPN) PARA VERIFICAR QUE LOS PRESTADORES DE SERVICIOS TURÍSTICOS, VISITANTES Y USUARIOS EN GENERAL CUMPLAN CON LAS REGLAS ESTABLECIDAS EN EL PROGRAMA DE MANEJO VIGENTE Y NORMATIVIDAD APLICABLE EN MATERIA DE ANPS \"\" \"', '90', '\"\"\"APOYAR DURANTE EL EJERCICIO 2024 LOS OPERATIVOS DE VIGILANCIA Y CONTROL QUE REALIZA EL PARQUE NACIONAL COSTA OCCIDENTAL DE ISLA MUJERES PUNTA CANCÚN PUNTA NIZÚC (PNCOIMPCPN) DENTRO DEL POLÍGONO DE PROTECCIÓN Y ÁREA DE INFLUENCIA EN COORDINACIÓN CON DEPENDENCIAS Y ENTIDADES GUBERNAMENTALES DE LOS DIFERENTES ÓRDENES DE GOBIERNO PARA DESALENTAR, PREVENIR Y SUSPENDER EN SU CASO LA COMISIÓN DE ILÍCITOS AMBIENTALES DENTRO DEL ANP. \"\" \"', '10', '30', '\"\"\"QUE SE APOYE EL 100% DE LOS OPERATIVOS DE VIGILANCIA Y CONTROL DURANTE EL EJERCICIO 2023 QUE REALIZA EL (PNCOIMPCPN) DENTRO DEL POLÍGONO DE PROTECCIÓN Y ÁREA DE INFLUENCIA EN COORDINACIÓN CON DEPENDENCIAS Y ENTIDADES GUBERNAMENTALES DE LOS DIFERENTES ÓRDENES DE GOBIERNO PARA DESALENTAR, PREVENIR Y SUSPENDER EN SU CASO LA COMISIÓN DE ILÍCITOS AMBIENTALES DENTRO DEL ANP. \"\" \"', '\"\"\"QUE AL MENOS SE APOYE EL 50% DE LOS OPERATIVOS DE VIGILANCIA Y CONTROL DURANTE EL EJERCICIO 2023 QUE REALIZA EL (PNCOIMPCPN) DENTRO DEL POLÍGONO DE PROTECCIÓN Y ÁREA DE INFLUENCIA EN COORDINACIÓN CON DEPENDENCIAS Y ENTIDADES GUBERNAMENTALES DE LOS DIFERENTES ÓRDENES DE GOBIERNO PARA DESALENTAR, PREVENIR Y SUSPENDER EN SU CASO LA COMISIÓN DE ILÍCITOS AMBIENTALES DENTRO DEL ANP. \"\" \"', '\"\"\"QUE SOLO SE APOYE EL 30% DE LOS OPERATIVOS DE VIGILANCIA Y CONTROL DURANTE EL EJERCICIO 2023 QUE REALIZA EL (PNCOIMPCPN) DENTRO DEL POLÍGONO DE PROTECCIÓN Y ÁREA DE INFLUENCIA EN COORDINACIÓN CON DEPENDENCIAS Y ENTIDADES GUBERNAMENTALES DE LOS DIFERENTES ÓRDENES DE GOBIERNO PARA DESALENTAR, PREVENIR Y SUSPENDER EN SU CASO LA COMISIÓN DE ILÍCITOS AMBIENTALES DENTRO DEL ANP. \"\" \"', '90', '\"\"\"LLEVAR A CABO DURANTE EL EJERCICIO 2024 LA SUPERVISIÓN Y MANTENIMIENTO DE LAS BOYAS DE AMARRE DEL PARQUE NACIONAL COSTA OCCIDENTAL DE ISLA MUJERES PUNTA CANCÚN PUNTA NIZÚC PNCOIMPCPN QUE SE UTILIZA PARA LAS EMBARCACIONES QUE REALIZAN ACTIVIDADES TURÍSTICO - RECREATIVAS EN LAS UNIDADES ARRECIFALES AUTORIZADAS EN EL PROGRAMA DE MANEJO. \"\" \"', '10', '10', '\"\"\"QUE SE LLEVE A CABO EL 100% LA SUPERVISIÓN Y MANTENIMIENTO DE LAS BOYAS DE AMARRE DEL PNCOIMPCPN PARA LAS EMBARCACIONES QUE REALIZAN ACTIVIDADES TURÍSTICO - RECREATIVAS EN LAS UNIDADES ARRECIFALES AUTORIZADAS EN EL PROGRAMA DE MANEJO. \"\" \"', '\"\"\"QUE SE LLEVE A CABO EL 50% LA SUPERVISIÓN Y MANTENIMIENTO DE LAS BOYAS DE AMARRE DEL PNCOIMPCPN PARA LAS EMBARCACIONES QUE REALIZAN ACTIVIDADES TURÍSTICO - RECREATIVAS EN LAS UNIDADES ARRECIFALES AUTORIZADAS EN EL PROGRAMA DE MANEJO. \"\" \"', '\"\"\"QUE SE LLEVE A CABO EL 30% LA SUPERVISIÓN Y MANTENIMIENTO DE LAS BOYAS DE AMARRE DEL PNCOIMPCPN PARA LAS EMBARCACIONES QUE REALIZAN ACTIVIDADES TURÍSTICO - RECREATIVAS EN LAS UNIDADES ARRECIFALES AUTORIZADAS EN EL PROGRAMA DE MANEJO. \"\" \"', '90', '\"\"\"VERIFICAR DURANTE EL EJERCICIO 2024 EL ESTADO FÍSICO, BUEN FUNCIONAMIENTO Y OPERACIÓN DE LOS VEHÍCULOS TERRESTRES Y EMBARCACIONES A CARGO DEL PNCOIMPC PARA GARANTIZAR LA OPERACIÓN DEL ANP. \"\" \"', '10', '20', '\"\"\"QUE SE LLEVE A CABO EL 100% DE LAS ACCIONES ASIGNADAS PARA LA VERIFICACIÓN DEL ESTADO FÍSICO, BUEN FUNCIONAMIENTO Y OPERACIÓN DE LOS VEHÍCULOS TERRESTRES A CARGO DEL PNCOIMPCPN QUE PARA GARANTIZAR LA OPERACIÓN DEL ANP. \"\" \"', '\"\"\"QUE SOLO SE LLEVE A CABO EL 50% DE LAS ACCIONES ASIGNADAS PARA LA VERIFICACIÓN DEL ESTADO FÍSICO, BUEN FUNCIONAMIENTO Y OPERACIÓN DE LOS VEHÍCULOS TERRESTRES A CARGO DEL PNCOIMPCPN QUE PARA GARANTIZAR LA OPERACIÓN DEL ANP. \"\" \"', '\"\"\"QUE ÚNICAMENTE SE LLEVE A CABO EL 30% DE LAS ACCIONES ASIGNADAS PARA LA VERIFICACIÓN DEL ESTADO FÍSICO, BUEN FUNCIONAMIENTO Y OPERACIÓN DE LOS VEHÍCULOS TERRESTRES A CARGO DEL PNCOIMPCPN QUE PARA GARANTIZAR LA OPERACIÓN DEL ANP. \"\" \"', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (76, 'CAEI890907', 'COADYUVAR EN LA ELABORACIÓN, IMPLEMENTACIÓN Y SEGUIMIENTO DEL PROGRAMA OPERATIVO ANUAL DEL COMPLEJO XCALAK- CHINCHORRO PARA FORTALECER EL DESARROLLO EFECTIVO DE LA PLANEACIÓN Y CUMPLIMIENTO DE SUS OBJETIVOS.', '10', '20', 'SE CUMPLEN EN TIEMPO Y FORMA AL 100% LAS ACTIVIDADES PROGRAMAS EN EL POA DEL COMPLEJO XCALAK-CHINCHORRO', 'SE CUMPLEN EN UN 80% LAS ACTIVIDADES PROGRAMADAS EN EL POA DEL COMPLEJO XCALAK-CHINCHORRO', 'SE CUMPLE MENOS DEL 50% LAS ACTIVIDADES PROGRAMADAS EN EL POA DEL COMPLEJO XCALAK-CHINCHORRO', '90', 'PROMOVER LA OBSERVANCIA DE LOS PROGRAMAS DE MANEJO DEL PARQUE NACIONAL ARRECIFES DE XCALAK Y DE LA RESERVA DE LA BIOSFERA BANCO CHINCHORRO, ASÍ COMO DE LAS REGLAS ADMINISTRATIVAS DEL MISMO PARA EL CUMPLIMIENTO DE LAS DISPOSICIONES LEGALES APLICABLES Y GARANTIZAR LA CONSERVACIÓN DE AMBAS ANP.', '10', '20', 'SE REALIZAN EN UN 100% ACCIONES QUE PERMITAN EL CUMPLIMIENTO DE LAS REGLAS ADMINISTRATIVAS DE LOS PROGRAMAS DE MANEJO DE AMBAS ANP', 'SE REALIZAN EN UN 80% ACCIONES QUE PERMITAN EL CUMPLIMIENTO DE LAS REGLAS ADMINISTRATIVAS DE LOS PROGRAMAS DE MANEJO DE AMBAS ANP', 'SE REALIZA EN UN 50% ACCIONES QUE PERMITAN EL CUMPLIMIENTO DE LAS REGLAS ADMINISTRATIVAS DE LOS PROGRAMAS DE MANEJO DE AMBAS ANP', '90', 'COADYUVAR PARA LA PLANEACIÓN E IMPLEMENTACIÓN DE ACCIONES COORDINADAS PARA LA CONSERVACIÓN, PROTECCIÓN Y DE SUPERVISIÓN DE LAS ANP EN COORDINACIÓN CON DIVERSAS INSTANCIAS COMO PROFEPA, SEMAR, FGR, CONAPESCA Y GUARDIA NACIONAL PARA ASEGURAR EL CUMPLIMIENTO DE LAS LEYES Y NORMAS AMBIENTALES VIGENTES EN PRO DE LOS PRINCIPALES OBJETOS DE CONSERVACIÓN Y EN ATENCIÓN A LAS PROBLEMÁTICAS AMBIENTALES ACTUALES.', '10', '20', 'SE REALIZAN EN UN 100% DIVERSAS ACCIONES DE CONSERVACIÓN, PROTECCIÓN, SUPERVISIÓN Y VIGILANCIA EN COORDINACIÓN CON OTRAS INSTANCIAS PARA EL CUMPLIMIENTO DE LA NORMATIVIDAD VIGENTE DE AMBAS ANP.', 'SE REALIZAN EN UN 80% DIVERSAS ACCIONES DE CONSERVACIÓN, PROTECCIÓN, SUPERVISIÓN Y VIGILANCIA EN COORDINACIÓN CON OTRAS INSTANCIAS PARA EL CUMPLIMIENTO DE LA NORMATIVIDAD VIGENTE DE AMBAS ANP.', 'SE REALIZAN EN UN 50% DIVERSAS ACCIONES DE CONSERVACIÓN, PROTECCIÓN, SUPERVISIÓN Y VIGILANCIA EN COORDINACIÓN CON OTRAS INSTANCIAS PARA EL CUMPLIMIENTO DE LA NORMATIVIDAD VIGENTE DE AMBAS ANP.', '90', 'DESARROLLAR CON INSTITUCIONES, ORGANIZACIONES DE LA SOCIEDAD CIVIL, MIEMBROS DE LAS COMUNIDADES, SECTORES PRODUCTIVOS LOCALES, ENTRE OTROS; LA INSTRUMENTACIÓN E IMPLEMENTACIÓN DE MECANISMOS DE PARTICIPACIÓN SOCIAL (CONSEJOS ASESORES), ASÍ COMO EN EL DESARROLLO DE ACCIONES Y PROYECTOS DE CONSERVACIÓN, DE APROVECHAMIENTO SUSTENTABLE DE LOS ECOSISTEMAS Y ESPECIES SILVESTRES PARA PROCURAR LA INTEGRALIDAD ECOLÓGICA Y EL MEJORAMIENTO DE LA CALIDAD DE VIDA DE LOS HABITANTES DE AMBAS ANP.', '10', '20', 'SE DESARROLLAN AL 100% DIVERSOS MECANISMOS QUE AYUDAN A MANTENER LA INTEGRALIDAD ECOLÓGICA Y MEJORAMIENTO DE LA CALIDAD DE VIDA DE AMBAS ANP.', 'SE DESARROLLAN AL 80% DIVERSOS MECANISMOS QUE AYUDAN A MANTENER LA INTEGRALIDAD ECOLÓGICA Y MEJORAMIENTO DE LA CALIDAD DE VIDA DE AMBAS ANP', 'SE DESARROLLAN AL 50% DIVERSOS MECANISMOS QUE AYUDAN A MANTENER LA INTEGRALIDAD ECOLÓGICA Y MEJORAMIENTO DE LA CALIDAD DE VIDA DE AMBAS ANP', '90', 'COORDINAR EL DESARROLLO DE ACCIONES Y PROYECTOS RELACIONES CON ORDENAMIENTO PRODUCTIVO, CONFORMACIÓN Y FORTALECIMIENTO DE GRUPOS COMUNITARIOS PARA LA ATENCIÓN A CONTINGENCIAS AMBIENTALES, ASÍ COMO PROMOVER EL DESARROLLO COMUNITARIO, EL ECOTURISMO, LA SUPERVISIÓN, EDUCACIÓN AMBIENTAL, COMUNICACIÓN, CONSERVACIÓN, MONITOREO, INVESTIGACIÓN CIENTÍFICA Y RESTAURACIÓN DE AMBAS ANP PARA CUMPLIR CON LOS OBJETIVOS PLANTEADOS EN LAS DECLARATORIAS CORRESPONDIENTES, ASÍ COMO EN SU PROGRAMA DE MANEJO.', '10', '20', 'SE COORDINAN Y PROMUEVEN AL 100% DIVERSAS ACCIONES Y PROYECTOS QUE PERMITAN CUMPLIR CON LOS OBJETOS DE CREACIÓN DE AMBAS ANP.', 'SE COORDINAN Y PROMUEVEN 80% DIVERSAS ACCIONES Y PROYECTOS QUE PERMITAN CUMPLIR CON LOS OBJETOS DE CREACIÓN DE AMBAS ANP.', 'SE COORDINAN Y PROMUEVEN 50% DIVERSAS ACCIONES Y PROYECTOS QUE PERMITAN CUMPLIR CON LOS OBJETOS DE CREACIÓN DE AMBAS ANP.', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (77, 'CAFC870919', 'GESTIONAR EL SEGUIMIENTO DE LOS CONSEJOS ASESORES DE LAS TRES ÁREAS NATURALES PROTEGIDAS', '10', '20', 'SE GESTIONA EL SEGUIMIENTO DEL CONSEJO ASESOR DE TRES AREAS NATURALES PROTEGIDAS', 'SE GESTIONA EL SEGUIMIENTO DEL CONSEJO ASESOR DE UN AREA NATURAL PROTEGIDA', 'NO GESTIONAR EL SEGUIMIENTO DEL CONSEJO ASESOR DE LAS ÁREAS NATURALES PROTEGIDAS', '90', 'COADYUVAR EN LA GESTIÓN DEL SEGUIMIENTO DE LOS PROGRAMAS DE MANEJO DE TRES ÁREAS NATURALES PROTEGIDAS', '10', '20', 'SE COADYUVA EN LA GESTION DEL SEGUIMIENTO DE LOS PROGRAMAS DE MANEJO DE TRES AREAS NATURALES PROTEGIDAS', 'SE COADYUVA EN LA GESTION DEL SEGUIMIENTO DEL PROGRAMA DE MANEJO DE UN AREA NATURAL PROTEGIDA', 'NO SE COADYUVA EN LA GESTION DEL SEGUIMIENTO DE LOS PROGRAMAS DE MANEJO', '90', 'PROMOVER Y COORDINAR LA IMPLEMENTACIÓN DE PROGRAMAS DE SUBSIDIO EN TRES ÁREAS NATURALES PROTEGIDAS', '10', '20', 'SE PROMUEVE Y COORDINA LA IMPLEMENTACION DE PROGRAMAS DE SUBSIDIO EN TRES ÁREAS NATURALES PROTEGIDAS', 'SE PROMUEVE Y COORDINA LA IMPLEMENTACION DE PROGRAMAS DE SUBSIDIO EN UN AREA NATURAL PROTEGIDA', 'NO SE PROMUEVE NI COORDINA LA IMPLEMENTACION DE PROGRAMAS DE SUBSIDIO EN LAS AREAS NATURALES PROTEGIDAS', '90', 'COORDINAR LA EJECUCIÓN DEL PROGRAMA OPERATIVO ANUAL DE TRES ÁREAS NATURALES PROTEGIDAS', '10', '20', 'SE COORDINA LA EJECUCIÓN DEL PROGRAMA OPERATIVO ANUAL DE TRES ÁREAS NATURALES PROTEGIDAS', 'SE COORDINA LA EJECUCIÓN DEL PROGRAMA OPERATIVO ANUAL DE UN ÁREA NATURAL PROTEGIDA', 'NO SE COORDINA LA EJECUCIÓN DEL PROGRAMA OPERATIVO ANUAL DE LAS ÁREAS NATURALES PROTEGIDAS', '90', 'GESTIONAR LA COORDINACIÓN INTER E INTRA INSTITUCIONAL PARA LA IMPLEMENTACIÓN DE ACCIONES EN LAS ÁREAS NATURALES PROTEGIDAS', '10', '20', 'SE GESTIONA LA COORDINACION INTERINSTITUCIONAL CON TRES DEPENDECIAS GUBERNAMENTALES', 'SE GESTIONA LA COORDINACION INTERINSTITUCIONAL CON UNA DEPENDENCIA GUBERNAMENTAL', 'NO SE GESTIONA LA COORDINACIÓN INTER E INTRA INSTITUCIONAL PARA LA IMPLEMENTACIÓN DE ACCIONES EN LAS AREAS NATURALES PORTEGIDAS', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (78, 'CAGC730131', 'CELEBRAR Y ASEGURAR LOS CONVENIOS CON DIFERENTES ASOCIACIONES E INSTITUCIONES PÚBLICAS Y PRIVADAS, NACIONALES E INTERNACIONALES QUE COMPARTAN OBJETIVOS DIRIGIDOS A LA CONSERVACIÓN DE LAS POLÍTICAS PÚBLICAS EN LAS ÁREAS.', '02', '20', '81 AL 90%', '71 AL 80%', '0 AL 70%', '90', 'ASEGURAR LOS INSTRUMENTOS LEGALES DE ACCIONES Y PROYECTOS DE CONSERVACIÓN, PARA EL APROVECHAMIENTO SUSTENTABLE DE LOS ECOSISTEMAS Y ESPECIES SILVESTRES CON LOS USUARIOS DE LAS ÁREAS NATURALES PROTEGIDAS, NÚCLEOS AGRARIOS Y RIBEREÑOS, AFÍN DE MEJORAR LA CALIDAD DE VIDA DE LOS HABITANTES DE LAS ANP Y GENERAR FLUJOS DE SERVICIOS AMBIENTALES.', '02', '20', '81 AL 90%', '71 AL 80%', '0 AL 70%', '90', 'EMITIR OPINIÓN RESPECTO A LOS APROVECHAMIENTOS, SERVICIOS, OBRAS Y ACTIVIDADES QUE SE PRETENDAN AUTORIZAR POR PARTE DE LAS AUTORIDADES COMPETENTES, EN LAS ÁREAS NATURALES PROTEGIDAS COMPETENCIA DE LA FEDERACIÓN Y SUS ZONAS DE INFLUENCIA, PARA SU AUTORIZACIÓN.', '02', '20', '81 AL 90%', '71 AL 80%', '0 AL 70%', '90', 'VIGILAR LAS ACCIONES RELACIONADAS CON LA COORDINACIÓN INSTITUCIONALMENTE, EN LA REGIÓN CON LOS TRES ÓRDENES DE GOBIERNO, ASÍ COMO CONVENIOS DE CONCERTACIÓN CON LOS SECTORES SOCIAL Y PRIVADO, AFÍN DE EJECUTAR ACCIONES DE PROTECCIÓN, MANEJO, RESTAURACIÓN, CULTURA Y GESTIÓN, PARA LA CONSERVACIÓN DE LOS RECURSOS NATURALES EN EL ANP. \"', '02', '20', '81 AL 90%', '71 AL 80%', '0 AL 70%', '90', 'DISEÑAR Y DESARROLLAR PROYECTOS Y PROGRAMAS DE DESARROLLO SUSTENTABLE Y PRESERVACIÓN DE ECOSISTEMAS REGIONALES PARA LA MIGRACIÓN Y FLUJO DE ESPECIES DE FAUNA SILVESTRE Y PARA SU REFUGIO Y ALIMENTACIÓN.', '02', '20', '81 AL 90%', '71 AL 80%', '0 AL 70%', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (79, 'CAGD720324', 'PARTICIPAR EN LA FORMULACIÓN DE LOS PROGRAMAS DE MANEJO DE LAS NUEVAS ANP SANTUARIO PLAYAS DEL TOTONACAPAN Y SANTUARIO PLAYA LECHUGUILLAS Y DAR SEGUIMIENTO HASTA SU PUBLICACIÓN; APOYAR Y ASESORAR EN LA FORMULACIÓN Y POSTERIOR REVISIÓN DEL PROGRAMA DE MANEJO DE LA RB WANHÁ Y DAR SEGUIMIENTO HASTA SU PUBLICACIÓN; PARTICIPAR EN LA FORMULACIÓN DE LOS PROGRAMAS DE MANEJO DEL APFF LAGUNA DE TÉRMINOS Y RB PANTANOS DE CENTLA QUE SE ENCUENTRAN EN PROCESO DE MODIFICACIÓN; DAR SEGUIMIENTO AL PROCESO DE FORMULACIÓN Y PUBLICACIÓN DEL NUEVO PROGRAMA DE MANEJO DE LA RB SIERRA DE TAMAULIPAS.', '10', '60', '100% DE CADA UNO DE LOS PROGRAMAS DE MANEJO NUEVOS Y EN MODIFICACIÓN, REVISADOS Y TURNADOS PARA SU REVISIÓN FINAL Y POSTERIOR PUBLICACIÓN', '95% DE CADA UNO DE LOS PROGRAMAS DE MANEJO NUEVOS Y EN MODIFICACIÓN, REVISADOS Y TURNADOS PARA SU REVISIÓN FINAL Y POSTERIOR PUBLICACIÓN', '90% DE CADA UNO DE LOS PROGRAMAS DE MANEJO NUEVOS Y EN MODIFICACIÓN, REVISADOS Y TURNADOS PARA SU REVISIÓN FINAL Y POSTERIOR PUBLICACIÓN', '90', 'DAR SEGUIMIENTO, PROPORCIONAR ASESORÍA Y REALIZAR LA REVISIÓN DE LA DOCUMENTACIÓN SOBRE EL PROCESO DE EVALUACIÓN DE EFECTIVIDAD DE LOS PROGRAMAS DE MANEJO APFF LAGUNA MADRE Y DELTA DEL RÍO BRAVO, PN SISTEMA ARRECIFAL VERACRUZANO, APFF CAÑÓN DEL USUMACINTA Y APFF SISTEMA ARRECIFAL LOBOS TUXPAN.', '10', '15', '100% DE LAS CÉDULAS REVISADAS Y TURNADAS PARA SU VALIDACIÓN Y AUTORIZACIÓN', '90% DE LAS CÉDULAS REVISADAS Y TURNADAS PARA SU VALIDACIÓN Y AUTORIZACIÓN', '80% DE LAS CÉDULAS REVISADAS Y TURNADAS PARA SU VALIDACIÓN Y AUTORIZACIÓN', '90', 'INTEGRACIÓN DE EXPEDIENTES DE SOLICITUDES DE ADVC QUE INGRESEN A LA DIRECCIÓN REGIONAL PLANICIE COSTERA Y GOLFO DE MÉXICO, ASI COMO PROPORCIONAR ASESORÍA, DAR SEGUIMIENTO Y APOYO TÉCNICO A SOLICITANTES DE CERTIFICACIÓN DE ADVC, INCLUIDAS VISITAS DE CAMPO REQUERIDAS POR LA DGC.', '10', '20', '80% DE LAS SOLICITUDES DE ADVC CON EXPEDIENTES INTEGRADOS COMPLETAMENTE Y TURNADOS PARA SU CERTIFICACIÓN Y CON SEGUIMIENTO', '75% DE LAS SOLICITUDES DE ADVC CON EXPEDIENTES INTEGRADOS COMPLETAMENTE Y TURNADOS PARA SU CERTIFICACIÓN Y CON SEGUIMIENTO', '70% DE LAS SOLICITUDES DE ADVC CON EXPEDIENTES INTEGRADOS COMPLETAMENTE Y TURNADOS PARA SU CERTIFICACIÓN Y CON SEGUIMIENTO', '90', 'DAR SEGUIMIENTO AL REGISTRO Y ACTUALIZACIÓN DEL SIRCA POR PARTE DE DIRECCIONES DE ANP EN MATERIA DE CONSEJOS ASESORES, DE ACUERDO A PROCEDIMIENTOS Y REQUERIMIENTOS DE LA DGC Y PARTICIPAR Y DAR SEGUIMIENTO A LA CONCENTRACIÓN Y REVISIÓN DE INFORMACIÓN QUE SE REGISTRA EN EL SIPOT SOBRE CONSEJOS ASESORES Y PARTICIPACIÓN CIUDADANA.', '10', '5', '100% DE ANP CON CONSEJOS ASESORES QUE ACTUALIZARON EL SIRCA CON INFORMACIÓN DE LAS SESIONES REALIZADAS PARA ALIMENTAR EL SIPOT', '90% DE ANP CON CONSEJOS ASESORES QUE ACTUALIZARON EL SIRCA CON INFORMACIÓN DE LAS SESIONES REALIZADAS PARA ALIMENTAR EL SIPOT', '85% DE ANP CON CONSEJOS ASESORES QUE ACTUALIZARON EL SIRCA CON INFORMACIÓN DE LAS SESIONES REALIZADAS PARA ALIMENTAR EL SIPOT', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
