INSERT INTO `sed_individuales` VALUES (86, 'CAMM850613', 'FORTALECER LA OPERACIÓN DE LAS ANP DE LA REGIÓN CENTRO Y EJE NEOVOLCÁNICO A TRAVÉS DE LA IMPLEMENTACIÓN DEL COBRO DE DERECHOS.', '01', '20', '1', '0.75', '0.5', '90', 'REALIZAR LA CONSULTA PÚBLICA DEL ESTUDIO PREVIO JUSTIFICATIVO PARA EL CAMBIO DEL DECRETO DE LA RESERVA DE LA BIOSFERA SIERRA GORDA DE GUANAJUATO.', '01', '20', '1', '0.75', '0.5', '90', 'ATENDER EN TIEMPO Y FORMA LAS SOLICITUDES DE OPINIONES TÉCNICAS EN MATERIA DE IMPACTO AMBIENTAL FORESTAL, CAMBIO DE USO DEL SUELO Y VIDA SILVESTRE, ASÍ COMO LAS AUTORIZACIONES Y PERMISOS DE COMPETENCIA DE LA CONANP PARA LA REALIZACIÓN DE PROYECTOS Y ACTIVIDADES QUE SE PRETENDEN LLEVAR A CABO EN LAS ÁREAS NATURALES PROTEGIDAS DE LA REGIÓN CENTRO Y EJE NEOVOLCÁNICO.', '01', '20', '0.9', '0.75', '0.5', '90', 'IMPLEMENTAR LOS PROGRAMAS DE SUBSIDIO PROCODES Y PROREST (VIGILANCIA, MONITOREO, FORTALECIMIENTO, ESPECIES EN RIESGO Y RESTAURACIÓN) EN LAS ÁREAS NATURALES PROTEGIDAS QUE FORMAN PARTE DE LA REGIÓN CENTRO Y EJE NEOVOLCÁNICO, ASÍ COMO GARANTIZAR SU ADECUADO MANEJO Y APLICACIÓN DE LOS RECURSOS POR PARTE DE LOS BENEFICIARIOS DE LOS PROGRAMAS.', '01', '20', '0.9', '0.75', '0.5', '90', 'FORTALECER LOS PROGRAMAS DE MANEJO DE LAS ÁREAS NATURALES PROTEGIDAS DE LA REGIÓN CENTRO Y EJE NEOVOLCÁNICO A TRAVÉS DE LA FORMULACIÓN Y ACTUALIZACIÓN.', '01', '20', '0.9', '0.75', '0.5', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-