INSERT INTO `sed_individuales` VALUES (87, 'CAMP880723', 'OPERAR Y DAR EL SEGUIMIENTO A LAS ACCIONES DEL CAMPAMENTO TORTUGUERO IXPALBARCO.', '10', '20', 'CUMPLIR DEL 80 AL 100% DE LAS ACTIVIDADES', 'CUMPLIR DEL 50 AL 79% DE LAS ACTIVIDADES', 'CUMPLIR CON MENOS DEL 49%', '90', 'ACTUALIZAR Y DAR SEGUIMIENTO A LAS ACCIONES DEL PROGRAMA PARA LA CONSERVACIÓN DE TORTUGAS MARINAS EN LAS ANP.', '10', '20', 'CUMPLIR DEL 80 AL 100% DE LAS ACTIVIDADES', 'CUMPLIR DEL 50 AL 79% DE LAS ACTIVIDADES', 'CUMPLIR CON MENOS DEL 49%', '90', 'REALIZAR OPINIONES TÉCNICAS A LAS SOLICITUDES DE COLECTAS DE ESPECIES DE LAS AUTORIDADES COMPETENTES, EN APEGO AL DECRETO Y PROGRAMA DE MANEJO DEL ANP.', '10', '20', 'CUMPLIR DEL 80 AL 100% DE LAS ACTIVIDADES', 'CUMPLIR DEL 50 AL 79% DE LAS ACTIVIDADES', 'CUMPLIR CON MENOS DEL 49%', '90', 'DAR SEGUIMIENTO A LA EJECUCIÓN DE LOS PROGRAMAS DE SUBSIDIO MEDIANTE LA ASESORÍA, VERIFICACIÓN, INTEGRACIÓN Y REVISIÓN DE EXPEDIENTES EN APEGO A LAS REGLAS DE OPERACIÓN Y LINEAMIENTOS ESTABLECIDOS.', '10', '20', 'CUMPLIR DEL 80 AL 100% DE LAS ACTIVIDADES', 'CUMPLIR DEL 50 AL 79% DE LAS ACTIVIDADES', 'CUMPLIR CON MENOS DEL 49%', '90', 'EJECUTAR ACCIONES QUE LE CONFIERAN Y/O INSTRUYA EL JEFE INMEDIATO SUPERIOR, EL DIRECTOR DE ANP, EL DIRECTOR REGIONAL, LA UNIDAD ADMINISTRATIVA, LA UNIDAD TÉCNICA O JURÍDICA, ASÍ COMO LAS QUE SEÑALEN LAS DISPOSICIONES LEGALES Y REGLAMENTARIAS VIGENTES DENTRO DEL ALCANCE Y MARCO DE ACTUACIÓN DEL PERFIL DE PUESTO Y DEL PROGRAMA OPERATIVO ANUAL DEL ANP', '10', '20', 'CUMPLIR DEL 80 AL 100% DE LAS ACTIVIDADES', 'CUMPLIR DEL 50 AL 79% DE LAS ACTIVIDADES', 'CUMPLIR CON MENOS DEL 49%', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será est