INSERT INTO `sed_individuales` VALUES (88, 'CAPA611229', 'ELABORAR EL BORRADOR DEL PROGRAMA DE MANEJO DEL PARQUE NACIONAL GENERAL JUAN ÁLVAREZ CON FORME A LOS LINEAMIENTOS QUE PARA TAL EFECTO EMITAN LAS UNIDADES ADMINISTRATIVAS DE LA COMISIÓN Y PROPONERLO A LA DIRECCIÓN REGIONAL CENTRO Y EJE NEOVOLCÁNICO Y DEMÁS DIRECCIONES GENERALES QUE LES ATRIBUYE EXPRESAMENTE EL COMISIONADO NACIONAL, ASÍ COMO LAS QUE LES CONFIERAN LAS DISPOSICIONES JURÍDICAS APLICABLES.', '10', '20', '1', '0.75', '0.5', '60', 'SUPERVISAR LOS PROGRAMAS DE SUBSIDIOS Y PROYECTOS DE CONSERVACIÓN PARA EL DESARROLLO DEL PARQUE NACIONAL GENERAL JUAN ÁLVAREZ, ASI COMO PARTICIPAR EN LOS PROGRAMAS, PROYECTOS Y ACCIONES DE ESPECIES Y POBLACIONES EN RIESGO EN EL PARQUE NACIONAL.', '10', '20', '1', '0.75', '0.5', '70', 'FORMULAR, ELABORAR Y EJECUTAR EL PROGRAMA OPERATIVO ANUAL DEL PARQUE NACIONAL GENERAL JUAN ÁLVAREZ CON FORME A LOS LINEAMIENTOS Y PROPÓSITOS DE CONSERVACIÓN Y MANEJO DE ESTA ANP, CON LA COLABORACIÓN DE LAS COMUNIDADES DERECHOSAS DE ESTE PARQUE NACIONAL.', '10', '20', '1', '0.75', '0.5', '90', 'EMITIR DICTÁMENES TÉCNICOS DE SOPORTE ANTE EL COMISIONADO NACIONAL, LA DIRECCIÓN GENERAL DE OPERACIÓN REGIONAL O LA DIRECCIÓN REGIONAL CENTRO Y EJE NEOVOLCÁNICO, PARA EL OTORGAMIENTO MODIFICACIÓN PRORROGA, RESCATE, SUSPENSIÓN, EXTENSIÓN, REVOCACIÓN O ANULACIÓN DE CONCESIONES, PERMISOS, LICENCIAS O AUTORIZACIONES EN MATERIA DE INVESTIGACIONES, IMPACTO AMBIENTAL, FORESTAL, VIDA SILVESTRE, ASÍ COMO PARA LOS DIFERENTES INSTRUMENTOS DE PLANEACIÓN QUE INVOLUCREN AL PARQUE NACIONAL.', '10', '20', '1', '0.75', '0.5', '70', 'INSTALAR EL CONSEJO ASESOR DEL PARQUE NACIONAL GENERAL JUAN ÁLVAREZ, COMO LA PRINCIPAL PLATAFORMA DE PARTICIPACIÓN SOCIAL Y DE LOS TRES ÓRDENES DE GOBIERNO, ASI COMO LOS SUBCONSEJOS, QUE POR SU IMPORTANCIA, SE REQUIERAN PARA GARANTIZAR UNA BUENA PARTICIPACIÓN EN EL MANEJO EFECTIVO DEL PARQUE NACIONAL.', '10', '20', '1', '0.75', '0.5', '90', NULL, NULL, 1, '2024', 'Será establecido y demostra