INSERT INTO `sed_individuales` VALUES (91, 'CAPJ610912', 'DIRIGIR LAS ACCIONES PARA LA CONSERVACIÓN DE LOS RECURSOS NATURALES Y LA CONTINUIDAD DE LOS PROCESOS ECOLÓGICOS EN EL ECOSISTEMA INSULAR DE ISLA ISABEL E ISLAS MARIETAS.', '10', '50', 'CUMPLIÓ CON EL 90% - 71% DE LAS METAS ESTABLECIDAS EN EL POA.', 'CUMPLIÓ CON EL 70% - 61% DE LAS METAS ESTABLECIDAS EN EL POA.', 'CUMPLIÓ CON 60% O MENOS DE LAS METAS DEL POA.', '90', 'PROMOVER Y OPERAR PROYECTOS DE CONSERVACIÓN Y USO SUSTENTABLE DE LOS RECURSOS NATURALES, CON LA PARTICIPACIÓN DE USUARIOS Y COMUNIDADES ASENTADAS EN LA ZONA DE INFLUENCIA DEL ANP, CON APOYO DE LOS PROGRAMAS DE SUBSIDIO DE LA CONANP.', '01', '25', 'EJECUTAR DE 3 A 4 PROYECTOS CON GRUPOS ORGANIZADOS PERTENECIENTES A LAS COMUNIDADES DE INFLUENCIA DEL ANP EN ACCIONES DE CONSERVACIÓN Y USO SUSTENTABLE DE LA BIODIVERSIDAD DEL ANP.', 'EJECUTAR DE 2 PROYECTOS CON GRUPOS ORGANIZADOS PERTENECIENTES A LAS COMUNIDADES DE INFLUENCIA DEL ANP EN ACCIONES DE CONSERVACIÓN Y USO SUSTENTABLE DE LA BIODIVERSIDAD DEL ANP.', 'EJECUTAR DE 1 PROYECTO CON GRUPOS ORGANIZADOS PERTENECIENTES A LAS COMUNIDADES DE INFLUENCIA DEL ANP EN ACCIONES DE CONSERVACIÓN Y USO SUSTENTABLE DE LA BIODIVERSIDAD DEL ANP. .', '90', 'DIRIGIR LAS ACCIONES PARA LA APLICACIÓN DE LA LEY FEDERAL DE DERECHOS EN MATERIA DE COBRO DE DERECHOS Y PERMISOS PARA LA REALIZACIÓN DE ACTIVIDADES EN LAS ANP.', '10', '25', 'ATENCIÓN Y SEGUIMIENTO AL 90 - 100% DE LAS SOLICITUDES.', 'ATENDER EL 89% - 80% DE LAS SOLICITUDES.', 'ATENDER MENOS DEL 80% DE LAS SOLICITUDES.', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NU