INSERT INTO `sed_individuales` VALUES (92, 'CAPM671224', 'COORDINAR LA OPERATIVIDAD DEL PERSONAL DE LA RB LA SEPULTURA, EN LAS ACCIONES DE MANEJO Y CONSERVACIÓN DEL PROGRAMA OPERATIVO 2024 DEL ANP.', '04', '30', 'SE COORDINA AL 90% LA OPERATIVIDAD DEL PERSONAL DEL ANP EN RELACIÓN A LAS ACTIVIDADES EMPRENDIDAS PARA EL CUMPLIMIENTO DE LAS ACCIONES DEL POA', 'SE COORDINA AL 70% LA OPERATIVIDAD DEL PERSONAL DEL ANP EN RELACIÓN A LAS ACTIVIDADES EMPRENDIDAS PARA EL CUMPLIMIENTO DE LAS ACCIONES DEL POA', 'SE COORDINA AL 50% LA OPERATIVIDAD DEL PERSONAL DEL ANP EN RELACIÓN A LAS ACTIVIDADES EMPRENDIDAS PARA EL CUMPLIMIENTO DE LAS ACCIONES DEL POA', '90', 'COADYUVAR EN LA APLICACIÓN DE INSTRUMENTOS DE REGULACIÓN Y NORMATIVIDAD SOBRE OBRAS O ACTIVIDADES QUE SE EJECUTAN EN EL ANP.', '01', '25', 'SE REALIZAN VISITAS Y OPINIONES TÉCNICAS DE AL MENOS TRES PROYECTOS U OBRAS QUE SE REQUIEREN REALIZAR AL INTERIOR DEL ANP', 'SE REALIZAN VISITAS Y OPINIONES TÉCNICAS DE AL MENOS DOS PROYECTOS U OBRAS QUE SE REQUIEREN REALIZAR AL INTERIOR DEL ANP', 'SE REALIZAN VISITAS Y OPINIONES TÉCNICAS DE AL MENOS UN PROYECTOS U OBRAS QUE SE REQUIEREN REALIZAR AL INTERIOR DEL ANP', '90', 'COLABORAR EN LA INSTRUMENTACIÓN DE ACCIONES Y PROYECTOS DE CONSERVACIÓN DE OTRAS INSTANCIAS QUE SE IMPLEMENTAN EN LA RESERVA DE LA BIOSFERA LA SEPULTURA.', '01', '20', 'AL MENOS 6 COMUNIDADES INCORPORAN Y APLICAN CRITERIOS DE CONSERVACIÓN DE LA BIODIVERSIDAD CON TEMAS, SOBRE GANADERÍA SILVOPASTORIL, AGROBIODIVERSIDAD Y PAISAJES PRODUCTIVOS EN EL ANP.', 'AL MENOS 4 COMUNIDADES INCORPORAN Y APLICAN CRITERIOS DE CONSERVACIÓN DE LA BIODIVERSIDAD CON TEMAS, SOBRE GANADERÍA SILVOPASTORIL, AGROBIODIVERSIDAD Y PAISAJES PRODUCTIVOS EN EL ANP.', 'AL MENOS 2 COMUNIDADES INCORPORAN Y APLICAN CRITERIOS DE CONSERVACIÓN DE LA BIODIVERSIDAD CON TEMAS, SOBRE GANADERÍA SILVOPASTORIL, AGROBIODIVERSIDAD Y PAISAJES PRODUCTIVOS EN EL ANP.', '90', 'MANTENER LA PARTICIPACIÓN DE LA POBLACIÓN LOCAL EN LOS ESPACIOS QUE LA RB LA SEPULTURA HA DESARROLLADO PARA SU INCLUSIÓN EN LAS ACCIONES DE CONSERVACIÓN.', '01', '15', 'SE LOGRA LA PARTICIPACIÓN DE AL MENOS EL 80% DE LOS VOCALES DEL CONSEJO ASESOR DE FORMA CONSTANTE EN LAS REUNIONES Y ACCIONES DE CONSERVACIÓN, QUE EL CONSEJO ASESOR ESTABLEZCA.', 'SE LOGRA LA PARTICIPACIÓN DE AL MENOS EL 60% DE LOS VOCALES DEL CONSEJO ASESOR DE FORMA CONSTANTE EN LAS REUNIONES Y ACCIONES DE CONSERVACIÓN, QUE EL CONSEJO ASESOR ESTABLEZCA.', 'SE LOGRA LA PARTICIPACIÓN DE AL MENOS EL 50% DE LOS VOCALES DEL CONSEJO ASESOR DE FORMA CONSTANTE EN LAS REUNIONES Y ACCIONES DE CONSERVACIÓN, QUE EL CONSEJO ASESOR ESTABLEZCA.', '90', 'COADYUVAR EN LA INSTRUMENTACIÓN DE LA ESTRATEGIA DE EDUCACIÓN AMBIENTAL EN LA RB LA SEPULTURA, DONDE PARTICIPAN DIVERSOS ALIADOS EN LA CONSERVACIÓN DEL ANP.', '01', '10', 'SE IMPLEMENTA AL MENOS CUATRO EVENTOS DE EDUCACIÓN AMBIENTAL Y DIFUSIÓN SOBRE LA IMPORTANCIA Y ACTIVIDADES EN EL MANEJO DE LA RB LA SEPULTURA.', 'SE IMPLEMENTA AL MENOS TRES EVENTOS DE EDUCACIÓN AMBIENTAL Y DIFUSIÓN SOBRE LA IMPORTANCIA Y ACTIVIDADES EN EL MANEJO DE LA RB LA SEPULTURA.', 'SE IMPLEMENTA AL MENOS DOS EVENTOS DE EDUCACIÓN AMBIENTAL Y DIFUSIÓN SOBRE LA IMPORTANCIA Y ACTIVIDADES EN EL MANEJO DE LA RB LA SEPULTURA.', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (93, 'CAPM790407', 'ELABORAR, REVISAR Y DAR DE ALTA UNA BASE DE DATOS DE BECARIOS DEL PROGRAMA JÓVENES CONSTRUYENDO EL FUTURO Y VOLUNTARIOS QUE REALIZAN ACTIVIDADES DENTRO DE LAS ANP CORRESPONDIENTES A LA DIRECCIÓN REGIONAL PENÍNSULA DE BAJA CALIFORNIA Y PACIFICO NORTE APOYANDO A LA CONSERVACIÓN Y SUS ECOSISTEMAS.', '10', '40', 'REGISTRAR EN LA BASE DE DATOS DEL 99 AL 100% DE LOS VOLUNTARIOS Y BECARIOS QUE SE REGISTRAN PARA LAS ACTIVIDADES DE CONSERVACIÓN EN LAS ANP DE LA REGIÓN PENÍNSULA DE BAJA CALIFORNIA Y PACIFICO NORTE', 'REGISTRAR EN LA BASE DE DATOS DEL 85 AL 98% DE LOS VOLUNTARIOS Y BECARIOS QUE SE REGISTRAN PARA LAS ACTIVIDADES DE CONSERVACIÓN EN LAS ANP DE LA REGIÓN PENÍNSULA DE BAJA CALIFORNIA Y PACIFICO NORTE.', 'REGISTRAR EN LA BASE DE DATOS MENOS 85% DE LOS VOLUNTARIOS Y BECARIOS QUE SE REGISTRAN PARA LAS ACTIVIDADES DE CONSERVACIÓN EN LAS ANP DE LA REGIÓN PENÍNSULA DE BAJA CALIFORNIA Y PACIFICO NORTE.', '90', 'ELABORAR UN REGISTRO DE MONITOREOS BIOLÓGICOS QUE SE LLEVAN A CABO DENTRO DE LAS ANP APOYANDO A LA CONSERVACIÓN Y SUS ECOSISTEMAS', '10', '30', 'ELABORAR BASE DE DATOS DE MONITOREO BIOLÓGICO QUE SE LLEVAN A CABO EN LAS ANP DE ENTRE EL 99 AL 100% ACTIVIDADES QUE REALIZAN DENTRO DE LOS POLÍGONOS ESTABLECIDOS, PARA LA TOMA DE DECISIONES EN LA REGIÓN.', 'ELABORAR BASE DE DATOS DE MONITOREO BIOLÓGICO QUE SE LLEVAN A CABO EN LAS ANP DE ENTRE EL 95 AL 98% ACTIVIDADES QUE REALIZAN DENTRO DE LOS POLÍGONOS ESTABLECIDOS, PARA LA TOMA DE DECISIONES EN LA REGIÓN.', 'ELABORAR BASE DE DATOS DE MONITOREO BIOLÓGICO QUE SE LLEVAN A CABO EN LAS ANP MENOR AL 95% ACTIVIDADES QUE REALIZAN DENTRO DE LOS POLÍGONOS ESTABLECIDOS, PARA LA TOMA DE DECISIONES EN LA REGIÓN.', '90', 'APOYAR EN OFICINA AL PROGRAMA DE COMUNICACIÓN Y CULTURA PARA LA CONSERVACIÓN EN LAS DIFERENTES ACTIVIDADES QUE IMPLIQUEN ORGANIZACIÓN, GESTIÓN Y SEGUIMIENTO SOBRE ACTIVIDADES DE EDUCACIÓN AMBIENTAL, SEGUIMIENTO DE NOTAS PERIODÍSTICAS REFERENTES A TEMAS AMBIENTALES, DE CONSERVACIÓN, CONTAMINACIÓN, EXPLOTACIÓN Y USO DE RECURSOS NATURALES PRINCIPALMENTE EN LAS ANP`S QUE INTEGRAN LA REGIÓN PENÍNSULA DE BAJA CALIFORNIA Y PACIFICO NORTE.', '10', '30', 'APOYAR LAS ACTIVIDADES DE OFICINA EN UN RANGO DEL 90 AL100%', 'APOYAR LAS ACTIVIDADES DE OFICINA EN UN RANGO DEL 80 AL100%', 'APOYAR LAS ACTIVIDADES DE OFICINA MENOS DEL 70%', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
