INSERT INTO `sed_individuales` VALUES (95, 'CARA871203', 'EJECUTAR ACCIONES Y ESTRATEGIAS DE PROTECCIÓN, MANEJO, RESTAURACIÓN, INVESTIGACIÓN Y HUMANAS EN EL ANP.', '04', '20', 'EJECUCIÓN POR LO MENOS DE 95% DE ACCIONES CONCLUIDAS', 'EJECUCIÓN POR LO MENOS DE 85% DE ACCIONES CONCLUIDAS', 'EJECUCIÓN POR LO MENOS DE 80% DE ACCIONES CONCLUIDAS', '90', 'REVISAR LA INFORMACIÓN BIOLÓGICA, GEOGRÁFICA Y SOCIAL DISPONIBLE DEL ANP PARA ANALIZAR LAS PROPUESTAS DE LOS PROYECTOS SOLICITADOS Y AUTORIZADOS, COMPATIBLES CON LAS ESTRATEGIAS DE MANEJO DEL ANP, ALINEADOS A LA NORMATIVIDAD AMBIENTAL VIGENTE.', '08', '20', 'ANALIZAR EL 95% DE LAS PROPUETAS', 'ANALIZAR EL 85% DE LAS PROPUETAS', 'ANALIZAR EL 80% DE LAS PROPUETAS', '90', 'APOYAR CON LA ASESORÍA NECESARIA A LAS DEPENDENCIAS INVOLUCRADAS, EN LAS ACCIONES DE PLANEACIÓN, CONSERVACIÓN Y DESARROLLO DEL ÁREA NATURAL PROTEGIDA, ASEGURANDO QUE SE DISEÑEN Y AUTORICEN ACCIONES COMPATIBLES CON LAS ESTRATEGIAS DE MANEJO DEL ANP.', '04', '20', '95% DE ASESORIAS EN LAS ESTRATEGIAS DE MANEJO DEL ANP', '85% DE ASESORIAS EN LAS ESTRATEGIAS DE MANEJO DEL ANP', '75% DE ASESORIAS EN LAS ESTRATEGIAS DE MANEJO DEL ANP', '90', 'APOYAR EN LA IMPLEMENTACIÓN DE ESTRATEGIAS QUE HAGAN COMPATIBLE EL APROVECHAMIENTO, LA CONSERVACIÓN Y LA PROTECCIÓN DE LOS RECURSOS NATURALES DEL ÁREA, ESTRATEGIAS CON PROYECTOS DE DIVERSIFICACIÓN PRODUCTIVA SUSTENTABLE, COMPATIBLES CON LAS ESTRATEGIAS DE MANEJO DEL ÁREA NATURAL PROTEGIDA.', '05', '20', '0.95', '0.85', '0.75', '90', 'REALIZAR ACTIVIDADES ADMINISTRATIVAS Y DE LOGÍSTICA, ASÍ COMO DE GESTIÓN DE RECURSOS MATERIALES, HUMANOS, TECNOLÓGICOS, FINANCIEROS Y/O JURÍDICOS QUE SE REQUIERAN, DENTRO DE SU ÁMBITO DE APLICACIÓN, ASEGURANDO EL CUMPLIMIENTO NORMATIVO Y LA CONSECUCIÓN DE LOS OBJETIVOS DEL ÁREA NATURAL PROTEGIDA.', '06', '20', 'CONTAR CON EL 100% DE LAS METAS ESTABLECIDAS EN EL POA', 'CONTAR CON EL 90% DE LAS METAS ESTABLECIDAS EN EL POA', 'CONTAR CON EL 80% DE LAS METAS ESTABLECIDAS EN EL POA', '90', NULL, NUL