INSERT INTO `sed_individuales` VALUES (96, 'CARA891027', 'DAR SEGUIMIENTO A LA EJECUCIÓN DE LOS PROGRAMAS DE SUBSIDIO MEDIANTE LA ASESORÍA, VERIFICACIÓN, INTEGRACIÓN Y REVISIÓN DE LOS EXPEDIENTES EN APEGO A LAS REGLAS DE OPERACIÓN Y LINEAMIENTOS ESTABLECIDOS EN EL ARCHIPIÉLAGO DE CORONADO, ARCHIPIÉLAGO TODOS SANTOS, ISLA SAN MARTÍN Y ARCHIPIÉLAGO DE SAN JERÓNIMO DE LA RESERVA DE LA BIOSFERA ISLAS DEL PACÍFICO DE LA PENÍNSULA DE BAJA CALIFORNIA.', '10', '20', 'ATENDER Y DAR SEGUIMIENTO AL 90 Y 100% LA EJECUCIÓN DE LOS PROGRAMAS DE SUBSIDIOS AL AÑO.', 'ATENDER Y DAR SEGUIMIENTO AL 70 Y 89 % LA EJECUCIÓN DE LOS PROGRAMAS DE SUBSIDIOS AL AÑO.', 'ATENDER Y DAR SEGUIMIENTO AL 70 % LA EJECUCIÓN DE LOS PROGRAMAS DE SUBSIDIOS AL AÑO.', '90', 'REALIZAR Y DAR SEGUIMIENTO AL COBRO DE DERECHOS PARA EL ACCESO DE LAS ANP DENTRO DEL ARCHIPIÉLAGO DE CORONADO, ARCHIPIÉLAGO TODOS SANTOS, ISLA SAN MARTÍN Y ARCHIPIÉLAGO DE SAN JERÓNIMO DE LA RESERVA DE LA BIOSFERA ISLAS DEL PACÍFICO DE LA PENÍNSULA DE BAJA CALIFORNIA.', '10', '20', 'ATENDER Y DAR SEGUIMIENTO AL 90 Y 100 % AL COBRO DE DERECHOS DURANTE EL AÑO.', 'ATENDER Y DAR SEGUIMIENTO AL 70 Y 89 % AL COBRO DE DERECHOS DURANTE EL AÑO.', 'ATENDER Y DAR SEGUIMIENTO AL 70 % AL COBRO DE DERECHOS DURANTE EL AÑO.', '90', 'APOYAR EN LA EJECUCIÓN DE PROCEDIMIENTOS ADMINISTRATIVOS, GESTIÓN DE RECURSOS MATERIALES Y DE SERVICIOS BÁSICOS EN ZONA NORTE DE LA RESERVA DE LA BIOSFERA ISLAS DEL PACÍFICO DE LA PENÍNSULA DE BAJA CALIFORNIA.', '10', '20', 'ATENDER Y DAR SEGUIMIENTO AL 90 Y 100 % LOS PROCEDIMIENTOS ADMINISTRATIVOS DURANTE EL AÑO.', 'ATENDER Y DAR SEGUIMIENTO AL 70 Y 89 % LOS PROCEDIMIENTOS ADMINISTRATIVOS DURANTE EL AÑO.', 'ATENDER Y DAR SEGUIMIENTO AL 70 % LOS PROCEDIMIENTOS ADMINISTRATIVOS DURANTE EL AÑO.', '90', 'REALIZAR RECORRIDOS DE SUPERVISIÓN Y VIGILANCIA EN EL ARCHIPIÉLAGO DE CORONADO, ARCHIPIÉLAGO TODOS SANTOS, ISLA SAN MARTÍN Y ARCHIPIÉLAGO DE SAN JERÓNIMO DE LA RESERVA DE LA BIOSFERA ISLAS DEL PACÍFICO DE LA PENÍNSULA DE BAJA C