INSERT INTO `sed_individuales` VALUES (109, 'CEBE880212', 'REALIZAR ACTIVIDADES ADMINISTRATIVAS Y DE LOGÍSTICA, ASÍ COMO DE GESTIÓN DE RECURSOS MATERIALES, HUMANOS, TECNOLÓGICOS, FINANCIEROS Y/O JURÍDICOS QUE SE REQUIERAN, DENTRO DE SU ÁMBITO DE APLICACIÓN, ASEGURANDO EL CUMPLIMIENTO NORMATIVO Y LA CONSECUCIÓN DE LAS ACTIVIDADES Y LA ADECUADA OPERACIÓN DEL ANP Y LA DIRECCIÓN REGIONAL', '01', '30', '2 O MÁS EXPEDIENTES INTEGRADOS', '1 EXPEDIENTE INTEGRADO', '0 EXPEDIENTE INTEGRADO', '90', 'DAR SEGUIMIENTO A LA CORRECTA EJECUCIÓN DE LOS PROGRAMAS DE SUBSIDIOS MEDIANTE LA ASESORÍA, VERIFICACIÓN, INTEGRACIÓN Y REVISIÓN DE LOS ESPEDIENTES EN APEGO A LAS REGLAS DE OPERACIÓN Y LINEAMIENTOS ESTABLECIDOS, CONTRIBUIR AL CUMPLIMIENTO DE OBJETIVOS Y METAS INSTITUCIONALES EN LA DIRECCIÓN REGIONAL', '01', '25', '2 O MÁS EXPEDIENTES INTEGRADOS', '1 EXPEDIENTE INTEGRADO', '0 EXPEDIENTE INTEGRADO', '90', 'GENERAR INFORMACIÓN BIOLÓGICA Y BASES DE DATOS DE LAS ESPECIES MUESTREADAS, ASÍ COMO PROMOVER LA PARTICIPACIÓN DE COMUNIDADES LOCALES DEL ANP EN PROYECTOS DE MONITOREO NECESARIOS PARA EL MANEJO DE LOS RECURSOS NATURALES EN LA MISMA.', '10', '15', 'ENTRE 80 A 100% PROYECTOS O BASES GENERADOS', 'ENTRE 60 A 79% PROYECTOS O BASES GENERADOS', 'MENOS DEL 59% PROYECTOS O BASES GENERADOS', '90', 'REVISAR INFORMACIÓN BIOLÓGICA, GEOGRÁFICA Y SOCIAL DISPONIBLE DEL ANP PARA ANALIZAR LAS PROPUESTAS DE LOS PROYECTOS SOLICITADOS Y AUTORIZADOS, COMPATIBLES CON LAS ESTRATEGÍAS DE MANEJO DEL ANP, ALINEADOS A LA NORMATIVIDAD AMBIENTAL VIGENTE.', '10', '15', 'ENTRE 80 A 100% PROPUESTAS ANALIZADAS', 'ENTRE 60 A 79% PROPUESTAS ANALIZADAS', 'MENOS DEL 59 % PROPUESTAS ANALIZADAS', '90', 'APOYAR EN EL DISEÑO Y OPERACIÓN DE LA ESTRATEGIA DE EDUCACIÓN AMBIENTAL Y COMUNICACIÓN SOCIAL, CON LA FINALIDAD DE LOGRAR INTERIORIZAR LOS VALORES DE CONSERVACIÓN DE LA ANP EN LA POBLACIÓN QUE HABITA EN SU INTERIOR Y ZONA DE INFLUENCIA, ASÍ COMO DE LA POBLACIÓN EN GENERAL', '10', '15', 'ENTRE 80 A 100% ACCIONES REALIZADAS', 'ENTRE 60 A 79% ACCIONES REALIZADAS', 'MENOS DEL 59 % ACCIONES REALIZADAS', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (110, 'CEBO640108', 'DIRIGIR, COORDINAR Y SUPERVISAR LA ELABORACIÓN Y EJECUCIÓN DEL PROGRAMA OPERATIVO ANUAL JUNTO CON EL EQUIPO DE TRABAJO PARA ASEGURAR EL CUMPLIMIENTO DE LOS OBJETIVOS DEL PROGRAMA DE MANEJO DE LA RESERVA DE LA BIOSFERA SELVA EL OCOTE', '04', '30', 'SE REALIZAN Y EJECUTAN PROYECTOS ESTRATÉGICOS DE MANEJO A TRAVÉS DE 12 A 15 ACCIONES', 'SE REALIZAN Y EJECUTAN PROYECTOS ESTRATÉGICOS DE MANEJO A TRAVÉS DE 9 A 11 ACCIONES', 'SE REALIZAN Y EJECUTAN PROYECTOS ESTRATÉGICOS DE MANEJO A TRAVÉS DE 6 A 8 ACCIONES', '90', 'PROMOVER LA COORDINACIÓN INTERINSTITUCIONAL DE LOS TRES ÓRDENES DE GOBIERNO, CON LOS SECTORES SOCIALES Y PRIVADOS, CON LA FINALIDAD DE EJECUTAR ACCIONES DE PROTECCIÓN, MANEJO, RESTAURACIÓN, CULTURA AMBIENTAL PARA LA CONSERVACIÓN DE LOS RECURSOS NATURALES DE LA RESERVA DE LA BIOSFERA SELVA EL OCOTE', '04', '25', 'SE TOMAN AL MENOS 5 ACUERDOS DE PARTICIPACIÓN EN ACCIONES DE MANEJO', 'SE TOMAN AL MENOS 3 ACUERDOS DE PARTICIPACIÓN EN ACCIONES DE MANEJO', 'SE TOMA AL MENOS 1 ACUERDO DE PARTICIPACIÓN EN ACCIONES DE MANEJO', '90', 'DIRIGIR Y SUPERVISAR LA CORRECTA EJECUCIÓN DE PROYECTOS DE DESARROLLO SUSTENTABLE CON EL APOYO DE SUBSIDIOS Y PROYECTOS DE CONSERVACIÓN EN LA RESERVA DE LA BIOSFERA SELVA EL OCOTE', '04', '25', 'SE EJECUTAN SATISFACTORIAMENTE AL MENOS 12 PROYECTOS', 'SE EJECUTAN SATISFACTORIAMENTE AL MENOS 10 PROYECTOS', 'SE EJECUTAN SATISFACTORIAMENTE AL MENOS 8 PROYECTOS', '90', 'PROMOVER MECANISMOS DE PARTICIPACIÓN SOCIAL QUE CONTRIBUYAN A LAS ACCIONES DE MANEJO Y CONSERVACIÓN DE LA RESERVA DE LA BIOSFERA SELVA EL OCOTE', '04', '20', 'SE REALIZAN AL MENOS 3 REUNIONES DEL CONSEJO ASESOR, SUBCONSEJOS Y RED DE ASESORES', 'SE REALIZAN AL MENOS 2 REUNIONES DEL CONSEJO ASESOR, SUBCONSEJOS Y RED DE ASESORES', 'SE REALIZAN AL MENOS 1 REUNIÓN DEL CONSEJO ASESOR, SUBCONSEJOS Y RED DE ASESORES', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidenc