INSERT INTO `sed_individuales` VALUES (112, 'CEMF581010', 'AUXILIAR EN EL CUIDADO Y MANTENIMIENTO DEL PARQUE VEHICULAR PARA QUE ESTE EN BUENAS CONDICIONES DE OPERATIVILIDAD EN LAS OFICINAS CENTRALES DE LA CONANP.', '10', '25', 'DEL 100 AL 80 % DEL PARQUE VEHICULAR', 'DEL 79 AL 69 % DEL PARQUE VEHICULAR', 'MENOS DEL 69 % DEL PARQUE VEHICULAR', '90', 'AUXILIAR EN LA MENSAJERIA LOCAL PARA SU RECOLECCIÓN Y ENVIO, ASÍ COMO ESTAR AL PENDIENTE PARA ENTREGAR TODOS LOS ACUSES FIRMADOS EN TIEMPO Y FORMA A LOS USUARIOS DE OFICINAS CENTRALES DE LA CONANP.', '10', '25', 'DEL 100 AL 80 % DE SOLICITUDES DE MENSAJERIA LOCAL', 'DEL 79 AL 69 % DE SOLICITUDES DE MENSAJERIA LOCAL', 'MENOS DEL 68 % DE SOLICITUDES DE MENSAJERIA LOCAL', '90', 'AUXILIAR EN EL TEMA DE MENSAJERIA FORANEA, RECIBIENDO TODOS LOS ENVIOS Y DARLOS DE ALTA EN EL SISTEMA PARA GENERARLES SU NÚMERO DE GUÍA Y ASÍ ENVIARLOS A LOS DIFERENTES DESTINOS SOLICITADOS.', '10', '25', 'DEL 100 AL 80 % DE SOLICITUDES DE MENSAJERIA FORÁNEA', 'DEL 79 AL 69 % DE SOLICITUDES DE MENSAJERIA FORÁNEA', 'MENOS DEL 68 % DE SOLICITUDES DE MENSAJERIA FORÁNEA', '90', 'APOYO EN EL CONTROL DE AGUA DE GARRAFÓN PURIFICADA EN PRESENTACIÓN DE 20 LITROS, PARA QUE SEA DISTRIBUIDA EN LAS DIFERENTES ÁREAS DE LOS PISOS ONCE ALA \"A\" Y ALA \"B\", Y PISO DOCE ALA \"A\" Y ALA \"B\", EN LAS OFICINAS CENTRALES DE LA CONANP, PARA CONSUMO DE TODO EL PERSONAL.', '10', '25', 'DEL 100 AL 80 % DE ABASTECIMIENTO DE AGUA PURIFICADA PARA CONSUMO DEL PERSONAL DE LA CONANP', 'DEL 79 AL 69 % DE ABASTECIMIENTO DE AGUA PURIFICADA PARA CONSUMO DEL PERSONAL DE LA CONANP', 'MENOS DEL 69 % DE ABASTECIMIENTO DE AGUA PURIFICADA PARA CONSUMO DEL PERSONAL DE LA CONANP', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostr