INSERT INTO `sed_individuales` VALUES (128, 'CURM790117', 'ELABORAR DISEÑOS GRÁFICOS PARA DISTINTOS MATERIALES ACORDE A LA IDENTIDAD INSTITUCIONAL, EN COORDINACIÓN CON LAS ÁREAS NATURALES PROTEGIDAS DE LA REGIÓN FRONTERA SUR, ISTMO Y PACÍFICO SUR PARA SU INSTRUMENTACIÓN EN CAMPAÑAS DE COMUNICACIÓN, DIFUSIÓN Y EDUCACIÓN AMBIENTAL.', '10', '60', 'SATISFACTORIO: ELABORAR EL 100% DE LOS MATERIALES GRÁFICOS REQUERIDOS POR Y PARA LAS ÁREAS NATURALES PROTEGIDAS DE LA REGIÓN FRONTERA SUR, ISTMO Y PACÍFICO SUR.', 'NO SATISFACTORIO: ELABORAR EL 70% DE LOS MATERIALES GRÁFICOS REQUERIDOS POR Y PARA LAS ÁREAS NATURALES PROTEGIDAS DE LA REGIÓN FRONTERA SUR, ISTMO Y PACÍFICO SUR.', 'DEFICIENTE: ELABORAR MENOS DEL 70% DE LOS MATERIALES GRÁFICOS.', '90', 'PRODUCIR Y POSTPRODUCIR VÍDEOS DE CARÁCTER INFORMATIVO ACORDE A LA IDENTIDAD INSTITUCIONAL, EN SOLICITUD Y COORDINACIÓN CON LAS ÁREAS NATURALES PROTEGIDAS DE LA REGIÓN FRONTERA SUR, ISTMO Y PACÍFICO SUR PARA SU INSTRUMENTACIÓN EN CAMPAÑAS DE COMUNICACIÓN, DIFUSIÓN Y EDUCACIÓN AMBIENTAL.', '10', '20', 'SATISFACTORIO: PRODUCIR Y POSTPRODUCIR EL 100% DE VÍDEOS DE CARÁCTER INFORMATIVO ACORDE A LA IDENTIDAD INSTITUCIONAL, EN SOLICITUD Y COORDINACIÓN CON LAS ÁREAS NATURALES PROTEGIDAS PARA SU INSTRUMENTACIÓN EN CAMPAÑAS DE COMUNICACIÓN, DIFUSIÓN Y EDUCACIÓN.', 'NO SATISFACTORIO: PRODUCIR Y POSTPRODUCIR EL 70% DE VÍDEOS DE CARÁCTER INFORMATIVO ACORDE A LA IDENTIDAD INSTITUCIONAL, EN SOLICITUD Y COORDINACIÓN CON LAS ÁREAS NATURALES PROTEGIDAS PARA SU INSTRUMENTACIÓN EN CAMPAÑAS DE COMUNICACIÓN, DIFUSIÓN Y EDUCACIÓN.', 'DEFICIENTE: PRODUCIR Y POSTPRODUCIR MENOS DEL 70% DE VÍDEOS.', '90', 'CREAR Y EDITAR UN BANCO DE 50 IMÁGENES FOTOGRÁFICAS EN ALTA RESOLUCIÓN PARA EL USO EN MATERIALES DE DIVULGACIÓN Y 6 CLIPS DE VÍDEO EN RESOLUCIÓN HD, EN COORDINACIÓN CON LAS ÁREAS NATURALES PROTEGIDAS DE LA REGIÓN FRONTERA SUR, ISTMO Y PACÍFICO SUR PARA SU INSTRUMENTACIÓN EN CAMPAÑAS DE COMUNICACIÓN, DIFUSIÓN Y EDUCACIÓN AMBIENTAL.', '10', '10', 'SATISFACTO