INSERT INTO `sed_individuales` VALUES (137, 'DIQJ691001', 'IMPULSAR LA IMPLEMENTACIÓN DE ACTIVIDADES PRODUCTIVAS SUSTENTABLES EN LAS COMUNIDADES MEDIANTE EL FORTALECIMIENTO EN LA APLICACIÓN DEL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE, PROCODES Y PROGRAMA PARA LA PROTECCIÓN Y RESTAURACIÓN DE ECOSISTEMAS Y ESPECIES PRIORITARIAS, PROREST EN LA ZONA DE INFLUENCIA Y AL INTERIOR DEL COMPLEJO SIAN KA\'AN', '01', '25', '20 PROYECTOS, 3 CURSO DE CAPACITACIÓN, 1 ESTUDIO TÉCNICO', '10 PROYECTOS, 2 CURSOS DE CAPACITACIÓN, 1 ESTUDIO TÉCNICO', '8 PROYECTOS, 1 CURSO DE CAPACITACIÓN, 1 ESTUDIO TÉCNICO', '90', 'REALIZAR REUNIONES DE INSTALACIÓN DE COMITÉS DE CONTRALORÍA SOCIAL, COMITÉS DE SEGUIMIENTO, ASÍ COMO INTEGRAR LOS EXPEDIENTES EN TIEMPO Y FORMA DE LOS PROYECTOS QUE SE IMPLEMENTARÁN EN EL COMPLEJO SIAN KA\'AN, DEL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE, PROCODES Y DEL PROGRAMA PARA LA PROTECCIÓN Y RESTAURACIÓN DE ECOSISTEMAS Y ESPECIES PRIORITARIAS, PROREST', '01', '25', 'INTEGRAR 20 COMITÉS DE SEGUIMIENTO Y DE CONTRALORÍA SOCIAL, INTEGRAR TODOS LOS EXPEDIENTES DE LOS PROYECTOS QUE SE IMPLEMENTARÁN EN EL COMPLEJO SIAN KA\'AN DEL PROCODES Y DEL PROREST', 'INTEGRAR 10 COMITÉS DE SEGUIMIENTO Y DE CONTRALORÍA SOCIAL, INTEGRAR TODOS LOS EXPEDIENTES DE LOS PROYECTOS QUE SE IMPLEMENTARÁN EN EL COMPLEJO SIAN KA\'AN DEL PROCODES Y DEL PROREST', 'INTEGRAR 8 COMITÉS DE SEGUIMIENTO Y DE CONTRALORÍA SOCIAL, INTEGRAR TODOS LOS EXPEDIENTES DE LOS PROYECTOS QUE SE IMPLEMENTARÁN EN EL COMPLEJO SIAN KA\'AN DEL PROCODES Y DEL PROREST', '90', 'REALIZAR LAS RESPECTIVAS VISITAS DE SUPERVISIÓN Y SEGUIMIENTO EN CAMPO DE LOS PROYECTOS APROBADOS PARA SU EJECUCIÓN DE PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE, PROCODES Y DEL PROGRAMA PARA LA PROTECCIÓN Y RESTAURACIÓN DE ECOSISTEMAS Y ESPECIES PRIORITARIAS Y VERIFICAR SU CORRECTA EJECUCIÓN DE LAS ACCIONES PLASMADAS EN LOS EXPEDIENTES TÉCNICOS Y/O TÉRMINOS DE REFERENCIA, ASÍ COMO REALIZAR LOS AVANCES TANTO FÍSIC