INSERT INTO `sed_individuales` VALUES (138, 'DITC830407', 'ATENDER Y DIRIGIR LOS ASUNTOS JURÍDICOS DE LA DIRECCIÓN REGIONAL PENÍNSULA DE BAJA CALIFORNIA Y PACÍFICO NORTE, REPRESENTAR LEGALMENTE AL TITULAR DE LA DIRECCIÓN REGIONAL Y UNIDADES ADMINISTRATIVAS, ATENDER CONTROVERSIAS CONSTITUCIONALES O ACCIONES DE INCONSTITUCIONALIDAD, CERTIFICACIÓN DE DOCUMENTOS Y DEMÁS QUE DERIVEN EN OBLIGACIONES PARA LA DIRECCIÓN REGIONAL PENÍNSULA DE BAJA CALIFORNIA Y PACÍFICO NORTE', '10', '30', 'ATENDER DEL 90 AL 100% DE LAS SOLICITUDES RECIBIDAS DE LA DIRECCIÓN REGIONAL PENÍNSULA DE BAJA CALIFORNIA Y PACÍFICO NORTE', 'ATENDER DEL 70 AL 89% DE LAS SOLICITUDES RECIBIDAS DE LA DIRECCIÓN REGIONAL PENÍNSULA DE BAJA CALIFORNIA Y PACÍFICO NORTE', 'ATENDER MENOS DEL 70% DE LAS SOLICITUDES RECIBIDAS DE LA DIRECCIÓN REGIONAL PENÍNSULA DE BAJA CALIFORNIA Y PACÍFICO NORTE', '90', 'PROPORCIONAR ASESORÍA JURÍDICA QUE REQUIERAN LAS UNIDADES ADMINISTRATIVAS DE LA DIRECCIÓN REGIONAL PENÍNSULA DE BAJA CALIFORNIA Y PACÍFICO NORTE, SOBRE EL OTORGAMIENTO DE LAS CONCESIONES, PERMISOS, LICENCIAS, Y DEMÁS AUTORIZACIONES EN MATERIA DE ÁREAS NATURALES PROTEGIDAS, PREVISTAS EN LAS DISPOSICIONES JURÍDICAS Y DEMÁS QUE DERIVEN EN OBLIGACIONES, ASÍ COMO EN INAIS, DE LA DIRECCIÓN REGIONAL PENÍNSULA DE BAJA CALIFORNIA Y PACÍFICO NORTE', '10', '20', 'ATENDER DEL 90 AL 100% DE LAS ASESORÍAS JURÍDICAS RECIBIDAS EN LA DIRECCIÓN REGIONAL PENÍNSULA DE BAJA CALIFORNIA Y PACÍFICO NORTE', 'ATENDER DEL 70 AL 89% DE LAS ASESORÍAS JURÍDICAS RECIBIDAS EN LA DIRECCIÓN REGIONAL PENÍNSULA DE BAJA CALIFORNIA Y PACÍFICO NORTE', '\"ATENDER MENOS DEL 70% DE LAS ASESORÍAS JURÍDICAS RECIBIDAS EN LA DIRECCIÓN REGIONAL PENÍNSULA DE BAJA CALIFORNIA Y PACÍFICO NORTE \"', '90', 'ASESORAR A LAS DIRECCIONES DE ÁREAS NATURALES PROTEGIDAS Y LAS DEMÁS UNIDADES ADMINISTRATIVAS DE LA DIRECCIÓN REGIONAL PENÍNSULA DE BAJA CALIFORNIA Y PACÍFICO NORTE EN LA FORMULACIÓN DE DOCUMENTACIÓN E INSTRUMENTOS JURÍDICOS , CERTIFICAR DOCUMENTOS RELACIONADOS CON