INSERT INTO `sed_individuales` VALUES (139, 'DIVR690126', 'COORDINAR LAS OPERACIONES Y LA ESTRATEGIAS DE MANEJO DE LAS ÁREAS DESTINADAS VOLUNTARIAS A LA CONSERVACIÓN, A TRAVÉS DEL PROYECTO DE LOS DOS PROGRAMAS DE SUBSIDIOS QUE EJECUTA LA CONANP.', '10', '20', 'COORDINAR Y OPERAR ESTRATEGÍAS DE MANEJO AL 100 %', 'COORDINAR Y OPERAR ESTRATEGÍAS DE MANEJO AL 80 %', 'COORDINAR Y OPERAR ESTRATEGÍAS DE MANEJO AL 50 %', '90', 'COORDINAR QUE LOS PROGRAMAS Y PROYECTOS SE EJECUTEN DENTRO DE LAS TERRENOS EJIDALES DEL ADVC Y SE REALICE DE ACUERDO A LOS LINEAMIENTOS Y ORDENAMIENTOS LEGALES APLICABLES EN MATERIA DE PROTECCIÓN, ECONOMÍA DE LA CONSERVACIÓN Y RESTAURACIÓN; PARA LA CONSERVACIÓN DE LOS ECOSISTEMAS Y SU BIODIVERSIDAD.', '10', '20', 'SUPERVISAR AL 100 %, LOS PROGRAMAS Y PROYECTOS EN EL ADVC, QUE CUMPLAN CON LAS NORMATIVIDAD Y LEGISLACIÓN AMBIENTAL.', 'SUPERVISAR AL 80 %, LOS PROGRAMAS Y PROYECTOS EN EL ADVC, QUE CUMPLAN CON LAS NORMATIVIDAD Y LEGISLACIÓN AMBIENTAL.', 'SUPERVISAR AL 50 %, LOS PROGRAMAS Y PROYECTOS EN EL ADVC , QUE CUMPLAN CON LAS NORMATIVIDAD Y LEGISLACIÓN AMBIENTAL.', '90', 'PLANEAR QUE LOS RECURSOS GESTIONADOS Y EJECUTADOS EN LAS ADVC, POR FUENTES DE FINANCIAMIENTO INTERNO Y EXTERNOS; SEAN REALIZADOS EN BASE A LA NORMATIVIDAD AMBIENTAL APLICABLE PARA LAS ADVC.', '10', '20', 'VERIFICAR AL 100 %, QUE LOS RECURSOS SEAN EJERCIDOS EN EL ÁREA DE LAS ADVC; EN BASE A LA NORMATIVIDAD VIGENTE Y QUE LOS EJIDATARIOS Y COMUNEROS, SEAN LOS BENEFICIARIOS DIRECTOS, GENERANDO GOBERNANZA COMUNITARIA.', 'VERIFICAR AL 80 %, QUE LOS RECURSOS SEAN EJERCIDOS EN EL ÁREA DE LAS ADVC; EN BASE A LA NORMATIVIDAD VIGENTE Y QUE LOS EJIDATARIOS Y COMUNEROS, SEAN LOS BENEFICIARIOS DIRECTOS, GENERANDO GOBERNANZA COMUNITARIA.', 'VERIFICAR AL 50 %, QUE LOS RECURSOS SEAN EJERCIDOS EN EL ÁREA DE LAS ADVC; EN BASE A LA NORMATIVIDAD VIGENTE Y QUE LOS EJIDATARIOS Y COMUNEROS, SEAN LOS BENEFICIARIOS DIRECTOS, GENERANDO GOBERNANZA COMUNITARIA.', '90', 'ESTABLECER PROPUESTAS DE TRABAJO Y PROYEC