INSERT INTO `sed_individuales` VALUES (149, 'DUPG691215', 'ACTIVIDADES DE COORDINACIÓN E IMPARTICIÓN DE CURSOS DE SENSIBILIZACIÓN A PRESTADORES DE SERVICIOS TURÍSTICOS LOCALES Y EXTRANJEROS PARA DIFUNDIR LA NORMATIVIDAD DEL PROGRAMA DE MANEJO, ASÍ COMO LA IMPORTANCIAS Y PROBLEMÁTICA ACTUAL DE LOS OBJETOS DE CONSERVACIÓN.', '10', '25', 'SE COORDINARÁN E IMPARTIRÁN EL 100% DE LOS CURSOS PROGRAMADOS DE MANERA PRESENCIAL Y/O VIRTUAL', 'SE COORDINARÁN E IMPARTIRÁN EL 80% DE LOS CURSOS PROGRAMADOS DE MANERA PRESENCIAL Y/O VIRTUAL', 'SE COORDINARÁN E IMPARTIRÁN EL 60% DE LOS CURSOS PROGRAMADOS DE MANERA PRESENCIAL Y/O VIRTUAL', '90', 'SE LLEVARÁ A CABO ACCIONES DE EDUCACIÓN Y CULTURA PARA LA CONSERVACIÓN, CONFORME AL PROGRAMA DE MANEJO Y SE ATENDERÁN EVENTOS DEL CALENDARIO AMBIENTAL, EN LA POBLACIÓN LOCAL DEL PARQUE NACIONAL.', '10', '25', 'SE LLEVARÁN A CABO EL 100% DE LAS ACCIONES DE EDUCACIÓN Y CULTURA PARA LA CONSERVACIÓN (PLATICAS, VISITAS AL ANP, LIMPIEZAS DE ZONAS COSTERAS, PARTICIPACIÓN EN EVENTOS) Y PARTICIPACIÓN EN REUNIONES CON INSTANCIAS DE EDUCACIÓN AMBIENTAL.', 'SE LLEVARÁN A CABO EL 80% DE LAS ACCIONES DE EDUCACIÓN Y CULTURA PARA LA CONSERVACIÓN (PLATICAS, VISITAS AL ANP, LIMPIEZAS DE ZONAS COSTERAS, PARTICIPACIÓN EN EVENTOS) Y PARTICIPACIÓN EN REUNIONES CON INSTANCIAS DE EDUCACIÓN AMBIENTAL,', 'SE LLEVARÁN A CABO EL 60% DE LAS ACCIONES DE EDUCACIÓN Y CULTURA PARA LA CONSERVACIÓN (PLATICAS, VISITAS AL ANP, LIMPIEZAS DE ZONAS COSTERAS, PARTICIPACIÓN EN EVENTOS) Y PARTICIPACIÓN EN REUNIONES CON INSTANCIAS DE EDUCACIÓN AMBIENTAL,', '90', 'SE REALIZARÁN ACTIVIDADES DE DIFUSIÓN, IDENTIDAD Y DIVULGACIÓN CONFORME AL PROGRAMA DE MANEJO Y AL COMPONENTE DE DIFUSIÓN', '10', '10', 'SE REALIZARÁN 100% LAS ACCIONES DE COMUNICACIÓN Y DIFUSIÓN DE MATERIALES IMPRESOS DE HABITATS ARTIFICIALES Y LA GUÍA DE ESPECIES MARINAS. ADEMAS DE REALIZAR LA REVISIÓN DE LA SEÑALIZACIÓN EN EL ANP', 'SE REALIZARÁN 80% LAS ACCIONES DE COMUNICACIÓN Y DIFUSIÓN DE MATERIALES IMPRESOS DE HABITATS ARTIFICIALES Y LA GUÍA DE ESPECIES MARINAS. ADEMAS DE REALIZAR LA REVISIÓN DE LA SEÑALIZACIÓN EN EL ANP', 'SE REALIZARÁN 60% LAS ACCIONES DE COMUNICACIÓN Y DIFUSIÓN DE MATERIALES IMPRESOS DE HÁBITATS ARTIFICIALES Y LA GUÍA DE ESPECIES MARINAS. ADEMAS DE REALIZAR LA REVISIÓN DE LA SEÑALIZACIÓN EN EL ANP', '90', 'ACTIVIDADES PARA LA COORDINACIÓN DE LAS REUNIONES DE CONSEJO ASESOR Y SUBCONSEJO DEL ANP, DANDO SEGUIMIENTO A LOS ACUERDOS QUE GENEREN.', '10', '20', 'COORDINACIÓN DE UNA REUNIÓN DE CONSEJO ASESOR Y UNA DE SUBCONSEJO Y DAR SEGUIMIENTO A 100% DE LOS ACUERDOS QUE SE GENEREN DURANTE LAS REUNIONES.', 'COORDINACIÓN DE UNA REUNIÓN DE CONSEJO ASESOR Y UNA DE SUBCONSEJO Y DAR SEGUIMIENTO A 70% DE LOS ACUERDOS QUE SE GENEREN DURANTE LAS REUNIONES.', 'COORDINACIÓN DE UNA REUNIÓN DE CONSEJO ASESOR Y UNA DE SUBCONSEJO Y DAR SEGUIMIENTO A 50% DE LOS ACUERDOS QUE SE GENEREN DURANTE LAS REUNIONES.', '90', 'SEGUIMIENTO AL PROGRAMA DE VOLUNTARIADO, PRÁCTICAS PROFESIONALES O SERVICIOS SOCIALES COMO LO ESTABLECE LA CONANP', '10', '20', 'SEGUIMIENTO AL 100% DEL PROGRAMA DE VOLUNTARIADO, PRACTICANTES Y SERVICIOS SOCIALES', 'SEGUIMIENTO AL 80% DEL PROGRAMA DE VOLUNTARIADO, PRACTICANTES Y SERVICIOS SOCIALES', 'SEGUIMIENTO AL 60% DEL PROGRAMA DE VOLUNTARIADO, PRACTICANTES Y SERVICIOS SOCIALES', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (150, 'DUPS790706', 'PROMOVER EL DESARROLLO COMUNITARIO PARTICIPATIVO EN EL ÁREA EN LO RELATIVO A LOS PROGRAMAS DE SUBSIDIOS Y PROYECTOS DE CONSERVACIÓN PARA EL DESARROLLO Y DE MANEJO PARA EL USO Y APROVECHAMIENTO DE LOS ECOSISTEMAS', '02', '20', '100% - 75%', '74% - 50%', '49% - 0%', '90', 'ORGANIZAR, OPERAR, ADMINISTRAR, ASESORAR Y CULMINAR EN TIEMPO Y FORMA LOS PROYECTOS PROCODES QUE SE AUTORICEN EN EL ANP CONFORME A LAS REGLAS DE OPERACIÓN DEL PROCODES 2024', '01', '40', '100% - 75%', '74% - 50%', '40% - 0%', '90', 'ORGANIZAR, OPERAR, ADMINISTRAR Y CULMINAR EN TIEMPO Y FORMA EL SISTEMA DE CONTRALORÍA SOCIAL EN EL PROGRAMA DEL PROCODES 2024', '02', '15', '100% - 75%', '74% - 50%', '49% - 0%', '90', 'COADYUVAR, OPERAR Y ADMINISTRAR LAS ACCIONES CORRESPONDIENTES AL SISTEMA DE PORTALES DE OBLIGACIONES DE TRANSPARENCIA CORRESPONDIENTE A SUBSIDIOS Y APOYO EN OTRA ÁREAS DENTRO DEL ANP', '02', '15', '100% - 75%', '74% - 50%', '49% - 0%', '90', 'COADYUVAR EN LAS ACCIONES EN LA REALIZACIÓN DEL PROGRAMA DE MANEJO DEL APFF BAVISPE, ASÍ COMO EN LAS ACCIONES DE CONOCIMIENTO CONTEMPLADAS EN EL POA 2024 DEL ANP', '01', '10', '100% - 75%', '74% - 50%', '49% - 0%', '70', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (151, 'EALR640607', 'IMPLEMENTAR LAS ACTIVIDADES PROGRAMADAS EN EL PROGRAMA OPERATIVO ANUAL 2024 DEL PARQUE NACIONAL CAÑÓN DEL SUMIDERO.', '10', '50', 'SE IMPLEMENTA ENTRE EL 90 AL 100 % DE LAS ACTIVIDADES PROGRAMAS EN EL PROGRAMA OPERATIVO ANUAL 2024.', 'SE IMPLEMENTA ENTRE EL 60 AL 89 % DE LAS ACTIVIDADES PROGRAMAS EN EL PROGRAMA OPERATIVO ANUAL 2024.', 'SE IMPLEMENTA MENOS DEL 60 % DE LAS ACTIVIDADES DEL PROGRAMA OPERATIVO ANUAL 2024.', '90', 'FORTALECER LA COORDINACIÓN OPERATIVA DEL EQUIPO DE TRABAJO DE LAS 9 LÍNEAS ESTRATÉGICAS QUE OPERAN EN EL PARQUE NACIONAL CAÑÓN DEL SUMIDERO.', '01', '25', 'SE FORTALECE LA COORDINACIÓN OPERATIVA DEL EQUIPO DE TRABAJO DE 8 A 9 LÍNEAS ESTRATÉGICAS.', 'SE FORTALECE LA COORDINACIÓN OPERATIVA DEL EQUIPO DE TRABAJO DE 6 A 7 LÍNEAS ESTRATÉGICAS.', 'SE FORTALECE LA COORDINACIÓN OPERATIVA DEL EQUIPO DE TRABAJO DE 4 A 5 LÍNEAS ESTRATÉGICAS.', '90', 'SE IMPLEMENTAN CINCO PROYECTOS DE PROTECCIÓN, RESTAURACIÓN Y CONSERVACIÓN CON LA PARTICIPACIÓN DE OTRAS INSTANCIAS DE GOBIERNO, ORGANIZACIONES DE LA SOCIEDAD CIVIL E INICIATIVA PRIVADA EN EL PARQUE NACIONAL CAÑÓN DEL SUMIDERO.', '01', '25', 'SE IMPLEMENTAN 5 PROYECTOS DE PROTECCIÓN, RESTAURACIÓN Y CONSERVACIÓN EN EL PARQUE NACIONAL CAÑÓN DEL SUMIDERO.', 'SE IMPLEMENTAN 4 PROYECTOS DE PROTECCIÓN, RESTAURACIÓN Y CONSERVACIÓN EN EL PARQUE NACIONAL CAÑÓN DEL SUMIDERO.', 'SE IMPLEMENTAN 3 PROYECTOS DE PROTECCIÓN, RESTAURACIÓN Y CONSERVACIÓN EN EL PARQUE NACIONAL CAÑÓN DEL SUMIDERO.', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2