INSERT INTO `sed_individuales` VALUES (152, 'EAVJ820416', 'COLECTAR Y PROTEGER UN TOTAL DE 3700 NIDOS DE TORTUGA MARINA GOLFINA (LEPIDOCHELYS OLIVACEA) EN LA TEMPORADA 2024', '10', '25', '3400', '2000', '1500', '90', 'COLECTAR Y PROTEGER UN TOTAL DE 260000 HUEVOS DE TORTUGA MARINA GOLFINA (LEPIDOCHELYS OLIVACEA) EN LA TEMPORADA 2024', '10', '25', '240000', '180000', '130000', '90', 'AVIVAR 250000 CRÍAS DE TORTUGA MARINA GOLFINA (LEPIDOCHELYS OLIVACEA) EN LA TEMPORADA 2024', '10', '25', '200000', '150000', '100000', '90', 'REALIZAR VINCULACIÓN Y COADYUVAR CON 3 ASOCIACIONES PRIVADAS EN PRO DE LA CONSERVACIÓN DE TORTUGAS MARINAS EN LA TEMPORADA 2024', '10', '25', '3', '2', '1', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (153, 'EICI790426', 'REALIZARA ACTIVIDADES DE VIGILANCIA EN EL INTERIOR DE LA RESERVA DE LA BIOSFERA VOLCÁN TACANA Y SU ÁREA DE INFLUENCIA PARA PREVENIR ILÍCITOS AMBIENTALES, ASÍ COMO DAR SEGUIMIENTO A DENUNCIAS CIUDADANAS Y REALIZAR LAS DENUNCIAS CORRESPONDIENTES ANTE LA PROCURADURÍA FEDERAL DE PROTECCIÓN AL AMBIENTE (PROFEPA), O EN SU CASO A LA FISCALÍA GENERAL DE LA REPÚBLICA (FGR)', '02', '30', 'REALIZAR ACCIONES DE VIGILANCIA EN LAS COMUNIDADES QUE CONFORMAN EL ANP Y SU ÁREA DE INFLUENCIA, DANDO SEGUIMIENTO A LAS DENUCIAS CIUDADANAS Y REALIZANDO LAS DENUNCIAS CORRESPONDIENTES ANTE LA PROCURADURÍA FEDERAL DE PROTECCIÓN AL AMBIENTE (PROFEPA), O A LA FISCALÍA GENERAL DE LA REPÚBLICA (FGR).', 'SEGUIMIENTO PARCIAL A LAS DENUNCIAS INTERPUESTAS, YA SEA POR NO RECABAR EVIDENCIAS O POR NO ACUDIR AL SITIO DONDE SE LLEVÓ A CABO EL ILÍCITO.', 'TRÁMITE DEFICIENTE O NULO A LAS DENUNCIAS DE ILÍCITOS AMBIENTALES DETECTADAS DENTRO DEL ÁREA NATURAL PROTEGIDA O SU ÁREA DE INFLUENCIA.', '90', 'REALIZAR ACTIVIDADES DE MONITOREO DE AVES Y MAMÍFEROS JUNTO A LA RED DE MONITORES COMUNITARIOS PAVÓN - PAVO DE CACHO DENTRO DE LA RESERVA DE LA BIOSFERA VOLCÁN TACANA Y SU ÁREA DE INFLUENCIA, ACTUALIZANDO LA BASE DE DATOS DE PRESENCIA DE ESPECIES Y RECABANDO LAS EVIDENCIAS FOTOGRÁFICAS Y EN VIDEO DE LAS MISMAS.', '02', '30', 'SEGUIMIENTO OPORTUNO A LAS ACTIVIDADES DE MONITOREO COMUNITARIO, ATENCIÓN A LAS NECESIDADES DE LOS MONITORES, INTEGRACIÓN Y ANÁLISIS DE LA INFORMACIÓN OBTENIDA DURANTE LAS ACTIVIDADES DE MONITOREO.', 'SEGUIMIENTO PARCIAL A LAS ACTIVIDADES DE MONITOREO, NO ATENDER DE MANERA EFECTIVA LAS NECESIDADES DEL GRUPO DE MONITORES, RETRASO EN LA INTEGRACIÓN Y/O ENVÍO DE INFORMACIÓN OBTENIDA DURANTE LAS ACTIVIDADES DE MONITOREO.', 'SIN SEGUIMIENTO A LAS ACTIVIDADES DE MONITOREO, ATENCIÓN DEFICIENTE O NULA A LAS NECESIDADES EXPRESADAS POR EL GRUPO DE MONITORES.', '90', 'COORDINAR LAS ACTIVIDADES A REALIZAR POR LAS BRIGADAS DE CONTINGENCIAS AMBIENTALES (INCENDIOS FORESTALES Y SANEAMIENTO), TANTO AL INTERIOR DEL ÁREA NATURAL PROTEGIDA COMO EN APOYO A OTRAS ANP DE LA REGIÓN, LLEVANDO A CABO ACCIONES QUE AYUDEN A SALVAGUARDAR LA INTEGRIDAD DE LOS BRIGADISTAS MIENTRAS DESARROLLAN SUS ACTIVIDADES.', '02', '20', 'COORDINACIÓN EFICIENTE DE ACTIVIDADES, REALIZAR ACCIONES QUE PERMITAN QUE LOS BRIGADISTAS LLEVEN A CABO SUS ACTIVIDADES DE MANERA SEGURA, PROPORCIONANDOLES HERRAMIENTAS ADECUADAS Y EN BUEN ESTADO, ASÍ COMO LA CAPACITACIÓN NECESARIA PARA REALIZAR SUS ACTIVIDADES.', 'MALA COORDINACIÓN DE LAS ACTIVIDADES A REALIZAR, PROPORCIONAR HERRAMIENTAS EN ESTADO NO OPTIMO PARA REALIZAR SUS ACTIVIDADES', 'NULA COORDINACIÓN DE ACTIVIDADES, BRIGADISTAS SIN HERRAMIENTAS PARA DESEMPEÑAR SUS ACTIVIDADES.', '90', 'REALIZAR EL SEGUIMIENTO DE LOS PROYECTOS ASIGNADOS EN TIEMPO Y FORMA, TANTO DE LOS PROGRAMAS PROCODES Y PROREST COMO DEL PROYECTO PAISAJES SOSTENIBLES DE GEF-CI-CONANP, CON RAINFOREST ALLIANCE Y/O CON OTRAS INSTITUCIONES Y ONG\'S, A TRAVÉS DE VISITAS DE CAMPO, REUNIONES PROGRAMADAS Y EN SU CASO PROPORCIONANDO LA INFORMACIÓN QUE SEA REQUERIDA.', '02', '20', 'DAR SEGUIMIENTO Y FINIQUITO A LOS PROYECTOS DE SUBSIDIOS EN EL TIEMPO PROGRAMADO Y CON LAS CONDICIONES ESTABLECIDAS EN EL EXPEDIENTE TÉCNICO DE LOS MISMOS; EN EL CASO DE PROYECTOS CON ORGANIZACIONES NO GUBERNAMENTALES, DAR SEGUIMIENTO DE PROYECTOS EN CAMPO, PROPORCIONAR INFORMACIÓN CUANDO SEA REQUERIDA.', 'EN EL CASO DE LOS PROYECTOS DE SUBSIDIOS, RETRASO EN LAS ACTIVIDADES PROGRAMADAS; EN EL CASO DE LOS PROYECTOS CON ORGANIZACIONES NO GUBERNAMENTALES, DAR SEGUIMIENTO PARCIAL A LAS ACTIVIDADES DE LOS PROYECTOS QUE REALIZAN DENTRO DEL ANP', 'EN EL CASO DE LOS PROYECTOS DE SUBSIDIOS, REALIZAR EL FINIQUITO O FINALIZACIÓN DE LOS MISMOS CON RETRASOS Y QUEJAS DE LOS GRUPOS ORGANIZADOS Y SUS COMITPES DE CONTRALORÍA SOCIAL; EN EL CASO DE LOS PROYECTOS CON ORGANIZACIONES NO GUBERNAMENTALES, TENER NULA PARTICIPACIÓN Y/O SEGUIMIENTO DE LOS MISMOS ASÍ COMO NO PROPORCIONAR LA INFORMACIÓN REQUERIDA EN TIEMPO Y FORMA, LO QUE PUDIERA OCASIONAR RETRASO DE LOS PROYECTOS REALIZADOS DENTRO DEL ANP.', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
