INSERT INTO `sed_individuales` VALUES (166, 'FIVV941211', '1. REALIZAR EL MONITOREO DE LA CALIDAD DEL AGUA, DURANTE EL AÑO, DENTRO DEL APRN LA FRAILESCANA. CON EL KIT DE MONITOREO ALABAMA WATER QUALITY, DONDE SE PODRÁ MEDIR 6 PARÁMETROS FÍSICO-QUÍMICOS: PH, TEMPERATURA, TURBIDEZ, OXÍGENO DISUELTO, ALCALINIDAD TOTAL, DUREZA TOTAL.', '01', '20', 'DESARROLLAR 2 MONITOREOS', 'DESARROLLAR 1 MONITOREO', 'NO SE REALIZAN MONITOREOS', '90', 'APOYAR A LA OPERACIÓN DEL PROGRAMA PARA LA PROTECCIÓN Y RESTAURACIÓN DE ECOSISTEMAS Y ESPECIES PRIORITARIAS (PROREST) QUE SE DESARROLLARÁ EN EL APRN LA FRAILESCANA Y SU ZONA DE INFLUENCIA, MEDIANTE LA INTEGRACIÓN DE EXPEDIENTES DE PROPUESTAS DE PROYECTOS, SUPERVISIÓN DE ACTIVIDADES, ENTREGA Y CIERRE DE ACTIVIDADES.', '01', '20', 'OPERAR 3 PROYECTOS DE CONSERVACIÓN COMUNITARIA DEL PROREST.', 'OPERAR 2 PROYECTOS DE CONSERVACIÓN COMUNITARIA DEL PROREST.', 'OPERAR, AL MENOS, 1 PROYECTO DE CONSERVACIÓN COMUNITARIA DEL PROREST.', '90', 'IMPULSAR LA PARTICIPACIÓN DE LOS BENEFICIARIOS DEL PROREST A LA TOMA DE DECISIONES DENTRO DE LAS ACTIVIDADES DE LOS PROYECTOS CAPTURANDO SU PARTICIPACIÓN EN EL SISTEMA DE CONTRALORÍA SOCIAL VALIDADA POR LA SECRETARÍA DE LA FUNCIÓN PÚBLICA.', '01', '20', 'REGISTRAR 3 PROYECTOS EN EL SISTEMA DE CONTRALORÍA SOCIAL (SICS-FUNCIÓN PÚBLICA).', 'REGISTRAR 2 PROYECTOS EN EL SISTEMA DE CONTRALORÍA SOCIAL (SICS-FUNCIÓN PÚBLICA).', 'REGISTRAR 1 PROYECTOS EN EL SISTEMA DE CONTRALORÍA SOCIAL (SICS-FUNCIÓN PÚBLICA).', '90', 'SENSIBILIZAR, SOCIALIZAR Y DIFUNDIR LA VISIÓN ESTRATÉGICA DEL APRN LA FRAILESCANA DENTRO DE LAS COMUNIDADES QUE SE ENCUENTRAN EN EL POLÍGONO DE PROTECCIÓN DEL ANP.', '01', '20', 'PLANEAR Y DESARROLLAR 8 PLÁTICAS EN TEMÁTICA DE EDUCACIÓN AMBIENTAL Y FUNCIONES DEL ANP EN EJIDOS, COMUNIDADES Y CABECERA MUNICIPAL DE VILLA CORZO, CHIAPAS', 'PLANEAR Y DESARROLLAR DE 5 A 7 PLÁTICAS EN TEMÁTICA DE EDUCACIÓN AMBIENTAL Y FUNCIONES DEL ANP EN EJIDOS, COMUNIDADES Y CABECERA MUNICIPAL DE VILLA CORZO, CHIAPAS', 'PLANEAR Y DESARROLLAR, AL MENOS, 4 PLÁTICAS EN TEMÁTICA DE EDUCACIÓN AMBIENTAL Y FUNCIONES DEL ANP EN EJIDOS, COMUNIDADES Y CABECERA MUNICIPAL DE VILLA CORZO, CHIAPAS', '90', 'FORTALECER LA CAMPAÑA DE DIFUSIÓN DIGITAL DE LAS ACCIONES DESARROLLADAS DENTRO DEL APRN LA FRAILESCANA HACIA EL PÚBLICO EN GENERAL.', '01', '20', 'ADMINISTRAR LA PÁGINA OFICIAL DEL APRN LA FRAILESCANA, REALIZANDO 10 PUBLICACIONES EN EL AÑO.', 'ADMINISTRAR LA PÁGINA OFICIAL DEL APRN LA FRAILESCANA, REALIZANDO ENTRE 7 Y 9 PUBLICACIONES EN EL AÑO.', 'ADMINISTRAR LA PÁGINA OFICIAL DEL APRN LA FRAILESCANA, REALIZANDO MENOS DE 6 PUBLICACIONES EN EL AÑO.', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (167, 'FOAA760818', 'REVISAR Y ANALIZAR LA INTEGRACIÓN Y SISTEMATIZACIÓN DE LOS PROGRAMAS OPERATIVOS ANUALES (POA) DE LAS UNIDADES ADMINISTRATIVAS DE LA COMISIÓN NACIONAL DE ÁREAS NATURALES PROTEGIDAS (CONANP).', '10', '25', 'REVISIÓN Y ANÁLISIS DE LA INTEGRACIÓN Y SISTEMATIZACIÓN DEL 90% O MÁS DE LOS POA 2024 CAPTURADOS EN EL SGPOA POR LAS UNIDADES ADMINISTRATIVAS ASIGNADAS.', 'REVISIÓN Y ANÁLISIS DE LA INTEGRACIÓN Y SISTEMATIZACIÓN DEL 80% AL 89% DE LOS POA 2024 CAPTURADOS EN EL SGPOA POR LAS UNIDADES ADMINISTRATIVAS ASIGNADAS.', 'REVISIÓN Y ANÁLISIS DE LA INTEGRACIÓN Y SISTEMATIZACIÓN DEL 79% O MENOS DE LOS POA 2024 CAPTURADOS EN EL SGPOA POR LAS UNIDADES ADMINISTRATIVAS ASIGNADAS.', '90', 'MONITOREAR Y DAR SEGUIMIENTO AL AVANCE DEL CUMPLIMIENTO DE LAS METAS OPERATIVAS ANUALES DE LAS UNIDADES ADMINISTRATIVAS DE LA COMISIÓN NACIONAL DE ÁREAS NATURALES PROTEGIDAS (CONANP) QUE ELABORAN PROGRAMA OPERATIVO ANUAL (POA) E INTEGRAN SUS INFORMES TRIMESTRALES.', '10', '25', 'MONITOREO Y SEGUIMIENTO DEL AVANCE DE CUMPLIMIENTO DE METAS DEL 90% O MÁS DE LOS INFORMES TRIMESTRALES DE EJECUCIÓN DE LOS POA 2024 CAPTURADOS EN EL SGPOA POR LAS UNIDADES ADMINISTRATIVAS ASIGNADAS.', 'MONITOREO Y SEGUIMIENTO DEL AVANCE DE CUMPLIMIENTO DE METAS DEL 80% AL 89% DE LOS INFORMES TRIMESTRALES DE EJECUCIÓN DE LOS POA 2024 CAPTURADOS EN EL SGPOA POR LAS UNIDADES ADMINISTRATIVAS ASIGNADAS.', 'MONITOREO Y SEGUIMIENTO DEL AVANCE DE CUMPLIMIENTO DE METAS DEL 79% O MENOS DE LOS INFORMES TRIMESTRALES DE EJECUCIÓN DE LOS POA 2024 CAPTURADOS EN EL SGPOA POR LAS UNIDADES ADMINISTRATIVAS ASIGNADAS.', '90', 'ELABORAR REPORTES ANUALES DE SEGUIMIENTO AL CUMPLIMIENTO DE LAS METAS OPERATIVAS ANUALES DE LAS UNIDADES ADMINISTRATIVAS DE LA COMISIÓN NACIONAL DE ÁREAS NATURALES PROTEGIDAS (CONANP) QUE ELABORAN PROGRAMA OPERATIVO ANUAL E INTEGRAN SUS INFORMES TRIMESTRALES.', '10', '15', 'ELABORACIÓN DEL 90% O MÁS DE REPORTES ANUALES DE SEGUIMIENTO AL CUMPLIMIENTO DE LAS METAS OPERATIVAS ANUALES DE LAS UNIDADES ADMINISTRATIVAS ASIGNADAS.', 'ELABORACIÓN DEL 80% AL 89% DE REPORTES ANUALES DE SEGUIMIENTO AL CUMPLIMIENTO DE LAS METAS OPERATIVAS ANUALES DE LAS UNIDADES ADMINISTRATIVAS ASIGNADAS.', 'ELABORACIÓN DEL 79% O MENOS DE REPORTES ANUALES DE SEGUIMIENTO AL CUMPLIMIENTO DE LAS METAS OPERATIVAS ANUALES DE LAS UNIDADES ADMINISTRATIVAS ASIGNADAS.', '90', 'SEGUIMIENTO A LA OPERACIÓN, INTEGRACIÓN Y ACTUALIZACIÓN DEL SISTEMA GENERAL DE PROGRAMAS OPERATIVOS ANUALES (SGPOA).', '10', '15', 'CONTAR CON EL SGPOA ACTUALIZADO Y OPERANDO AL 90% O MÁS.', 'CONTAR CON EL SGPOA ACTUALIZADO Y OPERANDO DEL 80% AL 89%.', 'CONTAR CON EL SGPOA ACTUALIZADO Y OPERANDO DEL 79% O MENOS', '90', 'SEGUIMIENTO A LAS ACTIVIDADES REFERENTES A LA IMPLEMENTACIÓN DE LA HERRAMIENTA PARA EL INFORME Y MONITOREO ESPACIAL (SMART) EN LAS ANP.', '10', '20', 'SEGUIMIENTO Y SISTEMATIZACIÓN DE LA INFORMACIÓN GENERADA MEDIANTE SMART POR EL 90% O MÁS DE LAS ANP ASIGNADAS.', 'SEGUIMIENTO Y SISTEMATIZACIÓN DE LA INFORMACIÓN GENERADA MEDIANTE SMART POR EL 80% AL 89% DE LAS ANP ASIGNADAS.', 'SEGUIMIENTO Y SISTEMATIZACIÓN DE LA INFORMACIÓN GENERADA MEDIANTE SMART POR EL 79% O MENOS DE LAS ANP ASIGNADAS.', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
