INSERT INTO `sed_individuales` VALUES (174, 'FOSO580727', 'ELABORAR, COORDINAR, SUPERVISAR E INSTRUMENTAR LA EJECUCIÓN DEL PROGRAMA OPERATIVO ANUAL (POA) DE LAS ANPS CON BASE EN EL DECRETO Y ELABORAR Y ENTREGAR EN TIEMPO Y FORMA LOS CUATRO INFORMES TRIMESTRALES DE LAS ACCIONES Y AVANCES REALIZADOS.', '04', '50', 'EL POA Y LOS INFORMES TRIMESTRALES FUERON ELABORADOS Y ENTREGADOS EN TIEMPO Y FORMA Y LOS OBJETIVOS Y METAS FUERON CUMPLIDOS EN UN 90%.', 'EL POA Y LOS INFORMES TRIMESTRALES FUERON ELABORADOS Y ENTREGADOS EN TIEMPO Y FORMA Y LOS OBJETIVOS Y METAS FUERON CUMPLIDOS EN UN 70%.', 'EL POA Y LOS INFORMES TRIMESTRALES FUERON ELABORADOS Y ENTREGADOS EN TIEMPO Y FORMA Y LOS OBJETIVOS Y METAS FUERON CUMPLIDOS MENOS DEL 70%.', '90', 'ADMINISTRAR, ORGANIZAR, INSTRUMENTAR, ASESORAR Y CULMINAR PROYECTOS DE INCENTIVOS FISCALES MEDIANTE EL PROCODES Y PROREST, QUE SE EJECUTEN EN LAS ANPS CONFORME A LAS REGLAS DE OPERACIÓN Y LINEAMIENTOS.', '04', '20', 'ADMINISTRAR, INSTRUMENTAR Y CONCLUIR 5 PROYECTOS PROCODES Y PROREST, QUE SE EJECUTEN EN LAS ANPS CONFORME A LAS REGLAS DE OPERACIÓN Y LINEAMIENTOS, TENIENDO COMO FECHA EL 31 DE DICIEMBRE DEL 2024.', 'ADMINISTRAR, INSTRUMENTAR Y CONCLUIR 3 UN PROYECTO PROCODES Y PROREST, QUE SE EJECUTE EN LAS ANP´S CONFORME A LAS REGLAS DE OPERACIÓN Y LINEAMIENTOS, TENIENDO COMO FECHA EL 31 DE DICIEMBRE DE 2024.', 'ADMINISTRAR, INSTRUMENTAR Y CONCLUIR UN PROYECTO PROCODES Y PROREST, QUE SE EJECUTE EN LAS ANP´S CONFORME A LAS REGLAS DE OPERACIÓN Y LINEAMIENTOS, TENIENDO COMO FECHA EL 31 DE DICIEMBRE DE 2024.', '90', 'PARTICIPAR EN LA INTEGRACIÓN DE BRIGADAS COMUNITARIAS DE INCENDIOS FORESTALES EN LAS ANPS PARA REALIZAR ACCIONES DE PREVENCIÓN Y COMBATE DE INCENDIOS FORESTALES CON EL FIN DE PROTEGER LOS RECURSOS NATURALES EN EL ANP Y SU ZONA DE INFLUENCIA.', '04', '20', 'CONFORMAR 2 BRIGADAS COMUNITARIAS DE INCENDIOS FORESTALES EN LAS ANPS PARA REALIZAR ACCIONES DE PREVENCIÓN Y COMBATE DE INCENDIOS FORESTALES CUBRIENDO UNA SUPERFICIE DE 100 HECTÁREAS.', 'CONFORMAR 1 BRIGADAS COMUNITARIAS DE INCENDIOS FORESTALES EN LAS ANPS PARA REALIZAR ACCIONES DE PREVENCIÓN Y COMBATE DE INCENDIOS FORESTALES CUBRIENDO UNA SUPERFICIE DE 50 HECTÁREAS.', 'NO CONFORMAR NINGUNA BRIGADA COMUNITARIA DE INCENDIOS FORESTALES EN LAS ANP´S PARA REALIZAR ACCIONES DE PREVENCIÓN Y COMBATE DE INCENDIOS FORESTALES.', '90', 'COORDINAR Y EJECUTAR ACCIONES DE INSPECCIÓN Y VIGILANCIA CON EL FIN DE PROTEGER LOS RECURSOS NATURALES EN EL ANP Y SU ZONA DE INFLUENCIA.', '04', '10', 'SE CUMPLE EN MÁS DEL 90 % CON LAS METAS DEL PROGRAMA DE INSPECCIÓN Y VIGILANCIA.', 'SE CUMPLE DE 70% AL 90% CON LAS METAS DEL PROGRAMA DE INSPECCIÓN Y VIGILANCIA.', 'SE CUMPLE EN MENOS DE 70% CON LAS METAS DEL PROGRAMA DE INSPECCIÓN Y VIGILANCIA.', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
