INSERT INTO `sed_individuales` VALUES (176, 'FULA651027', 'INTEGRACIÓN DE GRUPOS DE TRABAJO EN EL MARCO DEL PROGRAMA PARA LA PROTECCIÓN Y RESTAURACIÓN DE ECOSISTEMAS Y ESPECIES EN RIESGO, COMPONENTE VIGILANCIA Y MONITOREO COMUNITARIA, LOCALIZADOS EN EL ÁREA DE INFLUENCIA DEL PARQUE NACIONAL, ASÍ COMO PARTICIPAR EN LA IMPARTICIÓN DE CURSOS DE CAPACITACIÓN EN MATERIA AMBIENTAL PARA 4 COMITÉS. REALIZAR RECORRIDOS CON CADA UNO DE LOS COMITÉS.', '01', '15', 'ELABORACIÓN EN TIEMPO Y FORMA DEL POA DEL ANP, CON 4 INFORMES QUE INTEGREN TODAS LAS ACTIVIDADES REALIZADAS DENTRO DEL PNPO.', 'ELABORACIÓN DEL POA DEL ANP, Y SUS 4 INFORMES EN TIEMPO PERO FUERA DE FORMA.', 'ELABORACIÓN DEL POA DEL ANP Y SUS 4 INFORMES FUERA DE TIEMPO Y FORMA.', '90', 'INSTRUMENTAR Y BRINDAR SEGUIMIENTO AL PROGRAMA OPERATIVO ANUAL PARA ASEGURAR EL CUMPLIMIENTO DE LOS OBJETIVOS DEL MISMO.', '02', '15', 'EL POA FUE ELABORADO EN TIEMPO Y FORMA Y LOS OBJETIVOS Y METAS FUERON CUMPLIDOS EN UN 90 %.', 'EL POA FUE ELABORADO EN TIEMPO Y FORMA Y LOS OBJETIVOS Y METAS FUERON CUMPLIDOS EN UN 70%.', 'EL POA NO FUE ELABORADO EN TIEMPO Y FORMA Y LOS OBJETIVOS Y METAS FUERON CUMPLIDOS EN UN 70 %.', '90', 'INTEGRACIÓN DE GRUPOS DE TRABAJO EN EL MARCO DEL PROGRAMA PARA LA PROTECCIÓN Y RESTAURACIÓN DE ECOSISTEMAS Y ESPECIES EN RIESGO, COMPONENTE VIGILANCIA Y MONITOREO COMUNITARIO, LOCALIZADOS EN EL ÁREA DE INFLUENCIA DEL PARQUE NACIONAL, ASÍ COMO PARTICIPAR EN LA IMPARTICIÓN DE CURSOS DE CAPACITACIÓN EN MATERIA AMBIENTAL PARA 4 COMITÉS. REALIZAR RECORRIDOS CON CADA UNO DE LOS COMITÉS.', '01', '20', 'IMPARTICIÓN DE 3 TALLERES Y/O PLÁTICAS SOBRE LA IMPORTANCIA DEL LOS SERVICIOS ECOSISTÉMICOS DEL PARQUE NACIONAL PICO DE ORIZABA.', 'IMPARTICIÓN DE 2 TALLERES Y/O PLÁTICAS SOBRE LA IMPORTANCIA DEL LOS SERVICIOS ECOSISTÉMICOS DEL PARQUE NACIONAL PICO DE ORIZABA.', 'IMPARTICIÓN DE UN TALLER Y/O PLÁTICAS SOBRE LA IMPORTANCIA DE LOS SERVICIOS ECOSISTÉMICOS DEL PARQUE NACIONAL PICO DE ORIZABA.', '90', 'INTEGRACIÓN DE GRUPOS DE TR