INSERT INTO `sed_individuales` VALUES (177, 'GAAE841220', 'FORMULAR Y PROPONER LAS ACCIONES DE SUPERVISION Y VIGILANCIA DEL PARQUE CONFORME EL POA DEL PNAPM.', '05', '25', 'SE FORMULA Y COORDINAN EN UN 100% LAS ACCIONES.', 'SE FORMULA Y COORDINAN ENTRE UN 99 Y 85% LAS ACCIONES.', 'SE FORMULA Y COORDINA EN MENOS DEL 84% LAS ACCIONES.', '90', 'CONFORMAR LOS EXPEDIENTES DE ILICITOS Y DENUNCIAS INTERPUESTAS POR LA DIRECCION DEL ANP Y DARLES SEGUIMIENTO.', '04', '25', 'MENSUALMENTE SE CONFORMAN E INTEGRAN LOS EXPEDIENTES AL 100% TENIENDO ERRORES DE MENOS DEL 15%.', 'MENSUALMENTE SE CONFORMAN E INTEGRAN LOS EXPEDIENTES AL 100% TENIENDO ERRORES ENTRE EL 15 Y EL 19%.', 'MENSUALMENTE SE CONFORMAN E INTEGRAN LOS EXPEDIENTES AL 100% TENIENDO ERRORES MAYORES AL 20%.', '90', 'COORDINAR EL USO DE LOS VEHÍCULOS ADSCRITOS AL PNAPM INTEGRAR MENSUALMENTE LAS BITÁCORAS DE GASOLINA.', '05', '25', 'SE COORDINA EL 100% DEL USO DE VEHÍCULOS Y SE INTEGRAN AL 100% LAS BITÁCORAS DE COMBUSTIBLE.', 'SE COORDINA ENTRE EL 99% Y 85% EL USO DE VEHÍCULOS Y SE INTEGRAN ENTRE EL 99 Y 85% LAS BITÁCORAS DE COMBUSTIBLE.', 'SE COORDINA MENOS DEL 85% EL USO DE VEHÍCULOS Y SE INTEGRAN MENOS DEL 85% LAS BITÁCORAS DE COMBUSTIBLE.', '90', 'ASISTIR A LA UNIDAD ADMINISTRATIVA REGIONAL EN LA EJECUCIÓN DE TRABAJOS DE INVENTARIO DE LOS BIENES MUEBLES E INMUEBLES ASIGNADOS AL PNAPM.', '05', '25', 'SE ASISTE EN UN 100%.', 'SE ASISTE ENTRE UN 99% Y 85%.', 'SE ASISTE EN MENOS DEL 84%.', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2