INSERT INTO `sed_individuales` VALUES (178, 'GABC880503', 'PARTICIPAR EN LA ELABORACIÓN Y CUMPLIMENTO DEL PROGRAMA OPERATIVO ANUAL DEL ÁREA NATURAL PROTEGIDA', '10', '20', 'SE PARTICIPO EN LA TOTALIDAD DE LOS RECORRIDOS DE VIGILANCIA REALIZADOS EN EL ANP', 'SE PARTICIPO DE MANERA PARCIAL EN LOS RECORRIDOS DE VIGILANCIA REALIZADOS EN EL ANP', 'NO SE PARTICIPÓ EN LOS RECORRIDOS DE VIGILANCIA EN EL ANP', '90', 'CONTRIBUIR CON LA IMPLEMENTACION DE LOS CONCEPTOS DE APOYO FINANCIADOS POR PROGRAMAS DE SUBSIDIOS, EN LAS COMUNIDADES RURALES INVOLUCRADAS EN LAS ANPS Y LA CONSERVACION DE LAS MISMAS, DENTRO DE SU ZONA DE INFLUENCIA.', '10', '30', 'EL PROGRAMA OPERATIVO ANUAL FUE REALIZADO Y SE CUMPLIO EN TIEMPO Y FORMA EN LA PROGRAMACION DEL EJERCICIO EN SU TOTALIDAD', 'EL PROGRAMA OPERATIVO ANUAL FUE ELABORADO Y SE CUMPLIO EN TIEMPO Y FORMA CON LA PROGRAMACION DEL EJERCICIO DE MANERA PARCIAL', 'EL PROGRAMA OPERATIVO ANUAL NO FUE ELABORADO PARA EL PRESENTE EJERCICIO', '90', 'PARTICIPAR EN RECORRIDOS DE VIGILANCIA DEL ANP', '10', '30', 'DAR SEGUIMIENTO EN SU TOTALIDAD A LA EJECUCION DE PROYECTOS Y CONCEPTOS DE APOYO AUTORIZADOS EN LOS PROGRAMAS DE SUBSIDIO', 'DAR SEGUIMIENTO DE MANERA PARCIAL A LA EJECUCION DE PROYECTOS Y CONCEPTOS DE APOYO AUTORIZADOS EN LOS PROGRAMAS DE SUBSIDIO', 'DAR SEGUIMIENTO DE MANERA NULA A LA EJECUCION DE PROYECTOS Y CONCEPTOS DE APOYO AUTORIZADOS EN LOS PROGRAMAS DE SUBSIDIO', '90', 'PARTICIPAR EN LAS ACCIONES DE MANEJO INTEGRAL DEL FUEGO REALIZADAS EN EL ANP', '09', '20', 'SE PARTICIPO EN LA TOTALIDAD DE LAS ACCIONES DE MANEJO INTEGRAL DEL FUEGO REALIZADAS EN EL ANP', 'SE PARTICIPO DE MANERA PARCIAL EN LAS ACCIONES DE MANEJO INTEGRAL DEL FUEGO REALIZADAS EN EL ANP', 'NO SE PARTICIPO EN LAS ACCIONES DE MANEJO INTEGRAL DEL FUEGO REALIZADAS EN EL ANP', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (179, 'GABM540302', 'FORMULAR Y PROPONER LAS ACTIVIDADES Y ACCIONES DEL POA DEL ANP CONFORME A LAS FUNCIONES DEL PUESTO Y EL PROGRAMA DE MANEJO. DAR SEGUIMIENTO ADMINISTRATIVO AL PROGRAMA OPERATIVO ANUAL DEL COMPLEJO SIAN KA’AN QUE SE DESARROLLA CON RECURSOS DEL FONDO DE ÁREAS NATURALES PROTEGIDAS. ENTRE LAS ACTIVIDADES ADMINISTRATIVAS DE ESTE POA ESTÁ LA DE INFORMAR EL ESTADO DE AVANCE FINANCIERO A ESTA DIRECCIÓN DE ÁREA EN COORDINACIÓN CON LA ORGANIZACIÓN ADMINISTRADORA DE LOS RECURSOS (ENDESU A.C.)., ALIMENTAR EL SISTEMA INFORMÁTICO QUE EXISTE PARA EL SEGUIMIENTO DE LAS ACTIVIDADES DE ESTE POA, SERVIR DE ENLACE ENTRE DIVERSOS PROVEEDORES Y LA ORGANIZACIÓN ADMINISTRADORA DE LOS RECURSOS, CONCILIAR LOS INFORMES DE AVANCE ADMINISTRATIVO ENTRE LA ORGANIZACIÓN ADMINISTRADORA Y LA DIRECCIÓN DE ÁREA.', '04', '25', 'REALIZAR DEL 100 AL 95% DE LAS ACTIVIDADES Y ACCIONES DEL POA DEL ANP, CONFORME A LAS FUNCIONES DEL PUESTO Y DEL PROGRAMA DE MANEJO.', 'CUMPLIR DEL 94 AL 90% DE LAS ACTIVIDADES Y ACCIONES DEL POA DEL ANP, CONFORME A LAS FUNCIONES DEL PUESTO Y DEL PROGRAMA DE MANEJO.', 'CUMPLIR DEL 89 AL 85% DE LAS ACTIVIDADES Y ACCIONES DEL POA DEL ANP, CONFORME A LAS FUNCIONES DEL PUESTO Y DEL PROGRAMA DE MANEJO.', '90', 'MANTENER ACTUALIZADA LA INFORMACIÓN DEL CONSEJO ASESOR Y SUBCONSEJOS DEL COMPLEJO SIAN KA’AN EN EL SIRCA-CONSEJOS ASESORES DE ESTA CONANP. ESTO INCLUYE ALIMENTAR BASES DE DATOS, SUBIR AL SISTEMA ARCHIVOS ELECTRÓNICOS DE MINUTAS, LISTAS DE ASISTENCIA, CAPTURAR INFORMACIÓN QUE REQUIERE EL SISTEMA.', '08', '25', 'REALIZAR DEL 100 AL 95% DE LAS ACTIVIDADES Y ACCIONES DEL POA DEL ANP, CONFORME A LAS FUNCIONES DEL PUESTO.', 'CUMPLIR DEL 94 AL 90% DE LAS ACTIVIDADES Y ACCIONES DEL POA DEL ANP, CONFORME A LAS FUNCIONES DEL PUESTO.', 'CUMPLIR DEL 89 AL 85% DE LAS ACTIVIDADES Y ACCIONES DEL POA DEL ANP, CONFORME A LAS FUNCIONES DEL PUESTO.', '70', 'DAR SEGUIMIENTO ADMINISTRATIVO A LAS ACTIVIDADES DE MANTENIMIENTO VEHICULAR Y DE INFRAESTRUCTURA QUE SE REALIZAN CON RECURSOS DEL POA FANP, SERVIR DE VÍNCULO ADMINISTRATIVO ENTRE LA ORGANIZACIÓN ADMINISTRADORA DE LOS RECURSOS Y EL PROVEEDOR DEL SERVICIO DE MANTENIMIENTO.', '04', '25', 'REALIZAR DEL 100 AL 95% DE LAS ACTIVIDADES Y ACCIONES DEL POA DEL ANP, CONFORME A LAS FUNCIONES DEL PUESTO Y DEL PROGRAMA DE MANEJO.', 'CUMPLIR DEL 94 AL 90% DE LAS ACTIVIDADES Y ACCIONES DEL POA DEL ANP, CONFORME A LAS FUNCIONES DEL PUESTO Y DEL PROGRAMA DE MANEJO.', 'CUMPLIR DEL 89 AL 85% DE LAS ACTIVIDADES Y ACCIONES DEL POA DEL ANP, CONFORME A LAS FUNCIONES DEL PUESTO Y DEL PROGRAMA DE MANEJO.', '90', 'MANTENER ACTUALIZADA LA BASE DE DATOS DE LOS PROYECTOS QUE ORGANIZACIONES DE LA SOCIEDAD CIVIL DESARROLLAN EN EL COMPLEJO SIAN KA’AN Y APOYAR EN LA ELABORACIÓN DE REPORTES ADMINISTRATIVOS A LA DIRECCIÓN DE ÁREA.', '08', '25', 'REALIZAR DEL 100 AL 95% DE LAS ACTIVIDADES Y ACCIONES DEL POA DEL ANP, CONFORME A LAS FUNCIONES DEL PUESTO.', 'CUMPLIR DEL 94 AL 90% DE LAS ACTIVIDADES Y ACCIONES DEL POA DEL ANP, CONFORME A LAS FUNCIONES DEL PUESTO.', 'CUMPLIR DEL 89 AL 85% DE LAS ACTIVIDADES Y ACCIONES DEL POA DEL ANP, CONFORME A LAS FUNCIONES DEL PUESTO.', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (180, 'GACC631110', 'EMITIR LOS DICTÁMENES TÉCNICOS Y OPINIONES QUE CORRESPONDAN A LA COMISIÓN Y QUE LE SOLICITEN LAS UNIDADES ADMINISTRATIVAS DE LA SECRETARÍA DENTRO DE LOS PROCEDIMIENTOS PARA EL OTORGAMIENTO DE LAS AUTORIZACIONES, PERMISOS Y CONCESIONES EN MATERIA DE IMPACTO AMBIENTAL, FORESTAL, ZONA FEDERAL MARÍTIMO TERRESTRE, VIDA SILVESTRE, CAMBIO DE USO DEL SUELO EN TERRENOS FORESTALES Y CUALQUIER OTRA RELATIVA A LAS ÁREAS NATURALES PROTEGIDAS Y SUS ZONAS DE INFLUENCIA ADSCRITAS A LA DRNYAGC', '10', '20', 'SE ATENDIÓ IGUAL O MAYOR AL 90% DE LAS SOLICITUDES RECIBIDAS PARA EMITIR DICTÁMENES Y OPINIONES TÉCNICAS EN LAS ÁREAS NATURALES PROTEGIDAS ADSCRITAS A LA DRNYAGC', 'SE ATENDIÓ DEL 70 AL 89% DE LAS SOLICITUDES RECIBIDAS PARA EMITIR DICTÁMENES Y OPINIONES TÉCNICAS EN LAS ÁREAS NATURALES PROTEGIDAS ADSCRITAS A LA DRNYAGC', 'SE ATENDIÓ MENOS DEL 70% DE LAS SOLICITUDES RECIBIDAS PARA EMITIR DICTÁMENES Y OPINIONES TÉCNICAS EN LAS ÁREAS NATURALES PROTEGIDAS ADSCRITAS A LA DRNYAGC', '90', 'ATENDER LAS SOLICITUDES DE PERMISOS, AUTORIZACIONES, PRÓRROGAS PARA LA PRESTACIÓN DE SERVICIOS TURÍSTICOS Y COMERCIALES QUE DESARROLLAN CON FINES ECONÓMICOS O LUCRATIVOS EN LAS ÁREAS NATURALES PROTEGIDAS ADSCRITAS A LA DRNYAGC', '10', '20', 'SE ATENDIÓ IGUAL O MAYOR AL 90% DE LAS SOLICITUDES RECIBIDAS PARA EMITIR PERMISOS, AUTORIZACIONES, PRÓRROGAS PARA LA PRESTACIÓN DE SERVICIOS TURÍSTICOS Y COMERCIALES EN LAS ÁREAS NATURALES PROTEGIDAS ADSCRITAS A LA DRNYAGC', 'SE ATENDIÓ ENTRE 70 Y 89% DE LAS SOLICITUDES RECIBIDAS PARA EMITIR PERMISOS, AUTORIZACIONES, PRÓRROGAS PARA LA PRESTACIÓN DE SERVICIOS TURÍSTICOS Y COMERCIALES EN LAS ÁREAS NATURALES PROTEGIDAS ADSCRITAS A LA DRNYAGC', 'SE ATENDIÓ MENOS DEL 70% DE LAS SOLICITUDES RECIBIDAS PARA EMITIR PERMISOS, AUTORIZACIONES, PRÓRROGAS PARA LA PRESTACIÓN DE SERVICIOS TURÍSTICOS Y COMERCIALES EN LAS ÁREAS NATURALES PROTEGIDAS ADSCRITAS A LA DRNYAGC', '90', 'PROMOVER Y SUPERVISAR LA APLICACIÓN DE LOS P