INSERT INTO `sed_individuales` VALUES (182, 'GAEO780305', 'SEGUIMIENTO Y ATENCIÓN TÉCNICA ADMINISTRATIVA DEL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE (PROCODES), AUTORIZADO PARA EL ÁREA NATURAL PROTEGIDA PN EL TEPOZTECO', '01', '20', '100', '75', '50', '90', 'REALIZAR RECORRIDOS DE VIGILANCIA INTERINSTITUCIONAL (PROFEPA, AYUNTAMIENTO DE TEPOZTLÁN Y BIENES COMUNALES) EN CAMPO PARA INHIBIR Y PREVENIR LA INCIDENCIA DE ILICITOS AMBIENTALES EN EL ÁREA NATURAL PROTEGIDA PARQUE NACIONAL EL TEPOZTECO', '01', '20', '100', '75', '50', '90', 'ATENCIÓN DE SOLICITUDES DE POSICIONAMIENTO Y GEORREFERENCIACIÓN PARA ORIENTAR ACCIONES DE USO DEL TERRITORIO EN CONGRUENCIA CON EL PROGRAMA DE MANEJO DEL PARQUE NACIONAL EL TEPOZTECO Y SU ZONA DE INFLUENCIA.', '01', '20', '100', '75', '50', '90', 'SEGUIMIENTO, ASISTENCIA TÉCNICA Y SUPERVISIÓN DE PROYECTOS PRODUCTIVOS QUE PROMUEVAN PRÁCTICAS SUSTENTABLES Y LA SUSTITUCIÓN GRADUAL DE QUÍMICOS NOCIVOS PARA EL MEDIO AMBIENTE.', '01', '20', '100', '75', '50', '90', 'SEGUIMIENTO Y ACOMPAÑAMIENTO TÉCNICO A LAS INICIATIVAS QUE SE GENEREN EN CONTEXTO AL PROYECTO COSMOS (CONSERVACIÓN DE SIERRAS Y MONTAÑAS)', '01', '20', '100', '75', '50', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
