INSERT INTO `sed_individuales` VALUES (184, 'GAGO670320', 'ESTABLECER Y ASEGURAR DURANTE EL EJERCICIO 2024 LAS PREVISIONES LOGÍSTICAS Y ADMINISTRATIVAS A FIN DE LLEVAR A CABO LA EJECUCIÓN Y CUMPLIMIENTO DE LAS METAS FÍSICO-FINANCIERAS DEL PROGRAMA OPERATIVO ANUAL (POA) DEL PARQUE NACIONAL ARRECIFE DE PUERTO MORELOS.', '10', '5', 'LLEVAR A CABO EL 100% DE LAS ACCIONES LOGÍSTICAS Y ADMINISTRATIVAS PARA LA EJECUCIÓN Y CUMPLIMIENTO DE LAS METAS FÍSICO-FINANCIERAS DEL POA.', 'LLEVAR A CABO EL 80% DE LAS ACCIONES LOGÍSTICAS Y ADMINISTRATIVAS PARA LA EJECUCIÓN Y CUMPLIMIENTO DE LAS METAS FÍSICO-FINANCIERAS DEL POA.', 'LLEVAR A CABO EL 50% DE LAS ACCIONES LOGÍSTICAS Y ADMINISTRATIVAS PARA LA EJECUCIÓN Y CUMPLIMIENTO DE LAS METAS FÍSICO-FINANCIERAS DEL POA.', '90', 'ESTABLECER Y ASEGURAR DURANTE EL EJERCICIO 2024 LAS PREVISIONES ADMINISTRATIVAS Y OPERATIVAS PARA LA SUPERVISIÓN DE ACTIVIDADES PARA EL MANEJO DE SARGAZO QUE SE REALIZA DENTRO DE LOS LÍMITES DEL PARQUE NACIONAL ARRECIFE DE PUERTO MORELOS CONFORME A LINEAMIENTOS, VERIFICACIONES EN CAMPO Y REUNIONES DE TRABAJO CON LOS REPRESENTANTES DE LOS SECTORES GUBERNAMENTALES Y HOTELEROS.', '10', '20', 'COORDINAR Y EJECUTAR EL 100 POR CIENTO DE LAS ACCIONES ADMINISTRATIVAS Y OPERATIVAS DE LA SUPERVISIÓN DE ACTIVIDADES PARA EL MANEJO DE SARGAZO CONFORME A LA NORMATIVIDAD ESTABLECIDA.', 'COORDINAR Y EJECUTAR EL 80 POR CIENTO DE LAS ACCIONES ADMINISTRATIVAS Y OPERATIVAS DE LA SUPERVISIÓN DE ACTIVIDADES PARA EL MANEJO DE SARGAZO CONFORME A LA NORMATIVIDAD ESTABLECIDA.', 'COORDINAR Y EJECUTAR AL MENOS EL 70 POR CIENTO DE LAS ACCIONES ADMINISTRATIVAS Y OPERATIVAS DE LA SUPERVISIÓN DE ACTIVIDADES PARA EL MANEJO DE SARGAZO CONFORME A LA NORMATIVIDAD ESTABLECIDA.', '70', 'PARTICIPAR Y COADYUVAR DURANTE EL EJERCICIO 2024 PARA QUE SE LLEVEN A CABO LAS ACTIVIDADES DE SUPERVISIÓN Y VIGILANCIA QUE REALIZA EL PERSONAL DEL PARQUE NACIONAL ARRECIFE DE PUERTO MORELOS DENTRO DE LOS LÍMITES DE PROTECCIÓN.', '10', '15', 'VERIFICAR Y DAR SEGUIMIENTO AL 100% DE LAS ACCIONES DE SUPERVISIÓN Y VIGILANCIA QUE REALIZA EL PERSONAL DEL PARQUE NACIONAL ARRECIFE DE PUERTO MORELOS EN CAMPO.', 'VERIFICAR Y DAR SEGUIMIENTO AL 80% DE LAS ACCIONES DE SUPERVISIÓN Y VIGILANCIA QUE REALIZA EL PERSONAL DEL PARQUE NACIONAL ARRECIFE DE PUERTO MORELOS EN CAMPO.', 'VERIFICAR Y DAR SEGUIMIENTO AL 60% DE LAS ACCIONES DE SUPERVISIÓN Y VIGILANCIA QUE REALIZA EL PERSONAL DEL PARQUE NACIONAL ARRECIFE DE PUERTO MORELOS EN CAMPO.', '90', 'ESTABLECER Y OPERAR DURANTE EL EJERCICIO 2024 EL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE (PROCODES) ASÍ COMO EL PROGRAMA PARA LA PROTECCIÓN Y RESTAURACIÓN DE ECOSISTEMAS Y ESPECIES PRIORITARIAS (PROREST).', '10', '50', 'DAR SEGUIMIENTO AL 100% DE LOS PROGRAMAS DE CONSERVACIÓN Y PROTECCIÓN QUE SE DESARROLLAN EN EL PNAPM EN COORDINACIÓN CON LA DIRECCIÓN DEL ÁREA NATURAL PROTEGIDA.', 'DAR SEGUIMIENTO AL 75% DE LOS PROGRAMAS DE CONSERVACIÓN Y PROTECCIÓN QUE SE DESARROLLAN EN EL PNAPM EN COORDINACIÓN CON LA DIRECCIÓN DEL ÁREA NATURAL PROTEGIDA.', 'DAR SEGUIMIENTO AL 60% DE LOS PROGRAMAS DE CONSERVACIÓN Y PROTECCIÓN QUE SE DESARROLLAN EN EL PNAPM EN COORDINACIÓN CON LA DIRECCIÓN DEL ÁREA NATURAL PROTEGIDA.', '90', 'OPERAR Y ALIMENTAR OPORTUNAMENTE DURANTE EL EJERCICIO 2024 LOS SISTEMAS DE INFORMACIÓN PARA EL SEGUIMIENTO Y CONTROL DE LOS APOYOS AUTORIZADOS DE LOS PROGRAMAS DE SUBSIDIO: PROCODES, PROREST ASÍ COMO EL SICS DE LA SECRETARÍA DE LA FUNCIÓN PÚBLICA.', '10', '10', 'ALIMENTAR CON EL 100% DE INFORMACIÓN LOS SISTEMAS SISPROCODES, SISPROREST Y SICS DE LOS PROYECTOS AUTORIZADOS EN EL ANP.', 'ALIMENTAR CON EL 75% DE INFORMACIÓN LOS SISTEMAS SISPROCODES, SISPROREST Y SICS DE LOS PROYECTOS AUTORIZADOS EN EL ANP.', 'HABER ALIMENTADO SÓLO CON EL 50% DE INFORMACIÓN LOS SISTEMAS SISPROCODES, SISPROREST Y SICS DE LOS PROYECTOS AUTORIZADOS EN EL ANP.', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será estableci