INSERT INTO `sed_individuales` VALUES (217, 'GOMN711022', 'TRAMITAR ANTE LA ORGANIZACIÓN LOCAL LEGALMENTE CONSTITUIDA (OLLC) ADMINISTRADORA, LAS SOLICITUDES DE PAGO CORRESPONDIENTES A LAS ADQUISICIÓN DEL EQUIPO AUTORIZADO, LAS CONSULTORÍAS Y EN SU CASO LAS TRANSFERENCIAS PRESUPUESTALES NECESARIAS PARA SU REVISIÓN Y AUTORIZACIÓN RESPECTIVA PARA LA PROGRAMACIÓN DEL PRESUPUESTO Y SU EJECUCIÓN EN TIEMPO Y FORMA DEL PROYECTO COSMOS ASÍ COMO LA GENERACIÓN DE LOS REPORTES ADMINISTRATIVOS EN EL SISTEMA DE SEGUIMIENTO A PROYECTOS (SISEP) PARA EL CUMPLIMIENTO DE METAS DEL PROGRAMA OPERATIVO ANUAL CORRESPONDIENTE.', '10', '15', '1', '0.75', '0.5', '90', 'VALIDAR LOS APARTADOS FINANCIEROS DE LOS EXPEDIENTES TÉCNICOS Y/O TÉRMINOS DE REFERENCIA DE LOS PROYECTOS DE PROGRAMAS DE SUBSIDIOS AUTORIZADOS EN EL EJERCICIO FISCAL, ASÍ COMO REVISAR LOS AVANCES RESPECTIVOS EN LOS INFORMES DE SUPERVISIÓN DE CAMPO VERIFICANDO ANTE LA PÁGINA DEL SAT LA VIGENCIA DE LAS COMPROBACIONES FISCALES CORRESPONDIENTES.', '10', '30', '1', '0.75', '0.5', '90', 'ELABORAR LAS SOLICITUDES DE PAGO CORRESPONDIENTES A LA ADQUISICIÓN DE BIENES, A LA PRESTACIÓN DE SERVICIOS BÁSICOS Y A LOS VIÁTICOS Y GASTOS DE CAMPO DEL PERSONAL DE ESTA ANP DE MANERA CORRECTA Y OPORTUNA PARA EL CORRECTO EJERCICIO DEL GASTO FISCAL Y/O GASTOS DE OPERACIÓN ASÍ COMO ELABORAR LOS OFICIOS DE SOLICITUD DE RECURSOS DE LOS PROYECTOS AUTORIZADOS DE LOS DIFERENTES PROGRAMAS DE SUBSIDIO QUE MANEJA EL ANP PARA VIGILAR LA CORRECTA APLICACIÓN DE LOS RECURSOS Y TENER EL CONTROL DEL EJERCICIO DE LOS MISMOS MEDIANTE LA OBTENCIÓN DE LA DOCUMENTACIÓN COMPROBATORIA.', '10', '15', '1', '0.75', '0.5', '90', 'ADMINISTRAR LOS DIFERENTES SISTEMAS DE INFORMACIÓN DE CADA PROGRAMA DE SUBSIDIO Y DEL SISTEMA DE INFORMACIÓN DE COBRO DE DERECHOS PARA OBTENER LOS REPORTES RESPECTIVOS Y MANTENER UN CONTROL ADMINISTRATIVO TANTO DE LOS AVANCES FÍSICOS FINANCIEROS DE TODOS LOS PROYECTOS AUTORIZADOS DE DICHOS PROGRAMAS, ASÍ COMO DEL COBRO DE DERECHOS.', '10', '30', '1