INSERT INTO `sed_individuales` VALUES (218, 'GONA761115', 'IMPLEMENTAR Y EJECUTAR LOS PROGRAMAS DE SUBSIDIOS QUE MANEJA LA CONANP ELEGIBLES DENTRO DEL APFF CAMPO VERDE Y EL SANTUARIO COTORRA SERRANA OCCIDENTAL (PROCODES, PROCODES-CONTINGENCIA, PROCODES AGROBIODIVERSIDAD, PROCODES TERRITORIAL, PROREST VMC, PROREST CC, ETC.) DURANTE EL EJERCICIO 2024, PARA LA CONSERVACIÓN DE LOS ECOSISTEMAS Y SU BIODIVERSIDAD.', '10', '25', 'EJECUCIÓN DEL 100% DE LOS PROGRAMAS DE SUBSIDIOS ELEGIBLES DENTRO DE LAS ANPS.', 'EJECUCIÓN DEL 80% DE LOS PROGRAMAS DE SUBSIDIOS ELEGIBLES DENTRO DE LAS ANPS.', 'EJECUCIÓN DEL 60% DE LOS PROGRAMAS DE SUBSIDIOS ELEGIBLES DENTRO DE LAS ANPS.', '90', 'IMPLEMENTAR EL MONITOREO BIOLÓGICO DE ESPECIES PRIORITARIAS DEL APFF CAMPO VERDE Y SANTUARIO COTORRA SERRANA OCCIDENTAL (OSO NEGRO, COTORRA SERRANA OCCIDENTAL, LOBO MEXICANO, ÁGUILA REAL, JAGUAR, NUTRIA DE RÍO, PEQUEÑOS MAMÍFEROS, AJOLOTES, SERPIENTES DE CASCABEL, ETC,), A TRAVÉS DE PROGRAMAS DE SUBSIDIO, RECURSOS FISCALES Y/O FINANCIAMIENTO EXTERNO DURANTE EL EJERCICIO 2024.', '10', '25', 'SE CUMPLIÓ AL 100% CON LA IMPLEMENTACIÓN DEL MONITOREO BIOLÓGICO DE ESPECIES PRIORITARIAS DENTRO DE LAS ANPS.', 'SE CUMPLIÓ AL 50% CON LA IMPLEMENTACIÓN DEL MONITOREO BIOLÓGICO DE ESPECIES PRIORITARIAS DENTRO DE LAS ANPS.', 'NO SE CUMPLIÓ CON LA IMPLEMENTACIÓN DEL MONITOREO BIOLÓGICO DE ESPECIES PRIORITARIAS DENTRO DE LAS ANPS.', '90', 'ELABORAR Y EJECUTAR EL PROGRAMA OPERATIVO ANUAL (POA) 2024 DEL APFF CAMPO VERDE Y EL SANTUARIO COTORRA SERRANA OCCIDENTAL, POR MEDIO DE LA ELABORACIÓN Y ENTREGA EN TIEMPO Y FORMA LOS 4 INFORMES TRIMESTRALES Y/O INFORMES ALTERNATIVOS SOLICITADOS DE LAS ACCIONES Y AVANCES OBTENIDOS PARA LA CONSECUCIÓN DE LOS LOGROS ANUALES.', '10', '25', 'EL POA 2024 Y LOS 4 INFORMES TRIMESTRALES FUERON ELABORADOS EN TIEMPO Y FORMA.', 'EL POA 2024 Y 3 INFORMES TRIMESTRALES FUERON ELABORADOS EN TIEMPO Y FORMA.', 'EL POA 2024 Y 2 INFORMES TRIMESTRALES FUERON ELABORADOS EN TIEMPO Y FORMA.', '90', 'PARTICI