INSERT INTO `sed_individuales` VALUES (224, 'GOVR860204', 'INTEGRAR LOS EXPEDIENTES DE LOS BENEFICIARIOS APOYADOS EN LOS DIFERENTES PROGRAMAS DE SUBSIDIOS PROCODES Y PROREST DE LA CONANP APLICADOS A LA RESERVA DE LA BIÓSFERA BARRANCA DE METZTITLÁN.', '10', '25', 'INTEGRAR DEL 80 AL 100% DE LOS EXPEDIENTES DE LOS BENEFICIARIOS APOYADOS EN LOS DIFERENTES PROGRAMAS DE SUBSIDIOS DE LA CONANP', 'INTEGRAR DEL 60 AL 79% DE LOS EXPEDIENTES DE LOS BENEFICIARIOS APOYADOS EN LOS DIFERENTES PROGRAMAS DE SUBSIDIOS DE LA CONANP', 'INTEGRAR MENOS DEL 59% DE LOS EXPEDIENTES DE LOS BENEFICIARIOS APOYADOS EN LOS DIFERENTES PROGRAMAS DE SUBSIDIOS DE LA CONANP', '90', 'BRINDAR LA ATENCIÓN OPORTUNA A LOS REPORTES DE ILÍCITOS AMBIENTALES U OBRAS DETECTADAS QUE IMPLIQUEN CAMBIO DE USO DE SUELOS EN LA POLIGONAL DE LA RESERVA DE LA BIÓSFERA BARRANCA DE METZTITLÁN.', '10', '25', 'DAR OPORTUNA ATENCIÓN DEL 75 AL 100% DE LOS REPORTES DE ILÍTOS AMBIENTALES DENTRO DE LA RBBM', 'ATENDER DEL 50 AL 75% LA ATENCIÓN AL REPORTE DE ILÍTOS AMBIENTALES DENTRO DE LA RBBM', 'ATENDER MENOS DEL 40% LA ATENCIÓN AL REPORTE DE ILÍTOS AMBIENTALES DENTRO DE LA RBBM', '90', 'ATENDER Y PARTICIPAR EN LAS ACTIVIDADES DE PROTECCIÓN FORESTAL, PRINCIPALMENTE EN LA ATENCIÓN OPORTUNA Y COMBATE DE INCENDIOS FORESTALES, ASI COMO LAS MEDIDAS DE PREVENCIÓN; TAMBIÉN EN EL SEGUIMIENTO Y DETECCIÓN DE PLAGAS O ENFERMEDADES.', '10', '20', 'DAR OPORTUNA ATENCIÓN DEL 75 AL 100% DE LOS REPORTES DE INCENDIOS FORESTALES DENTRO DE LA RBBM', 'ATENDER DEL 50 AL 75% LA ATENCIÓN AL REPORTE DE INCENDIOS FORESTALES DENTRO DE LA RBBM', 'ATENDER MENOS DEL 40% DEL REPORTE DE INCENDIOS FORESTALES DENTRO DE LA RBBM', '90', 'PARTICIPAR Y DAR SEGUIMIENTO A LAS ACCIONES RELACIONADAS CON EL TEMA DE MANEJO INTEGRADO DEL PAISAJE MIP, PRINCIPALMENTE EN LOS TRABAJOS DE PROYECTOS PRODUCTIVOS, TURISMO, AGROECOLOGÍA Y EL ACOMPAÑAMIENTO DE LAS DIFERENTES UMAS DENTRO DEL ANP.', '01', '15', 'DAR SEGUIMIENTO E IMPULSAR AL MENOS 3 PROYECTOS PROYECTOS PRODUCTIVOS, TURÍSTICOS, DE AGROECOLOGÍA O SANEAMIENTO DENTRO DE LA RBBM', 'DAR SEGUIMIENTO E IMPULSAR AL MENOS 2 PROYECTOS PROYECTOS PRODUCTIVOS, TURÍSTICOS, DE AGROECOLOGÍA O SANEAMIENTO DENTRO DE LA RBBM', 'DAR SEGUIMIENTO E IMPULSAR AL MENOS 1 PROYECTOS PROYECTOS PRODUCTIVOS, TURÍSTICOS, DE AGROECOLOGÍA O SANEAMIENTO DENTRO DE LA RBBM', '70', 'ATENDER, DAR RESPUESTA O SEGUIMIENTO A LAS SOLICITUDES U OPINIONES TÉCNICAS RELACIONADAS CON EL MANEJO DEL ÁREA NATURAL PROTEGIDA EN MATERIA AMBIENTAL.', '01', '15', 'ATENDER, DAR RESPUESTA O SEGUIMIENTO A TRES SOLICITUDES U OPINIONES TÉCNICAS RELACIONADAS CON EL MANEJO DEL ÁREA NATURAL PROTEGIDA EN MATERIA AMBIENTAL.', 'ATENDER, DAR RESPUESTA O SEGUIMIENTO A DOS SOLICITUDES U OPINIONES TÉCNICAS RELACIONADAS CON EL MANEJO DEL ÁREA NATURAL PROTEGIDA EN MATERIA AMBIENTAL.', 'ATENDER, DAR RESPUESTA O SEGUIMIENTO A UNA SOLICITUD U OPINIONES TÉCNICAS RELACIONADAS CON EL MANEJO DEL ÁREA NATURAL PROTEGIDA EN MATERIA AMBIENTAL.', '70', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (225, 'GOVY820615', 'COORDINAR LAS ACTIVIDADES RELACIONADAS CON LA EJECUCIÓN DEL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE (PROCODES) Y PROGRAMA PARA LA PROTECCIÓN Y RESTAURACIÓN DE ECOSISTEMAS Y ESPECIES PRIORITARIAS (PROREST) CON LA FINALIDAD DE PROMOVER EL APROVECHAMIENTO SUSTENTABLE DE LOS RECURSOS NATURALES Y LA GENERACIÓN DE ALTERNATIVAS PARA EL BIENESTAR DE LAS POBLACIONES HUMANAS LOCALES.', '10', '30', '100', '75', '50', '90', 'COORDINAR LAS ACTIVIDADES DE ECONOMIA DE LA CONSERVACIÓN CON EL PROPÓSITO DE FORTALECER EMPREDIMIENTOS Y PROYECTOS PRODUCTIVOS DEL ANP, ASI COMO PARTICIPAR EN PROCESOS DE CAPACITACIÓN Y REGULACIÓN TURISTICA EN COORDINACIÓN CON PRESTADORES DE SERVICIOS TURISTICOS, AUTORIDADES COMUNALES E INSTANCIAS GUBERNAMENTALES', '10', '20', '100', '75', '50', '90', 'FOMENTAR LA PARTICIPACIÓN DE LA POBLACIÓN Y USUARIOS DEL ÁREA, EN ACTIVIDADES DE EDUCACIÓN AMBIENTAL QUE PROMUEVAN ACCIONES PARA EL DESARROLLO SUSTENTABLE Y LA CONSERVACIÓN DE LOS SERVICIOS ECOSISTÉMICOS', '10', '15', '100', '75', '50', '90', 'APOYAR EN LA CONSECUCIÓN Y CUMPLIMIENTO DE METAS DE LOS PROGRAMAS OPERATIVOS ANUALES, EN LOS CUALES SE DESCRIBEN Y SUSTENTAN LAS ESTRATEGIAS Y ACCIONES QUE FORTALECEN LA OPERACIÓN TÉCNICA Y ADMINISTRATIVA DEL ANP (POA FISCAL, POA FANP Y POA COSMOS).', '10', '20', '100', '75', '50', '90', 'COADYUVAR EN ACTIVIDADES DE PREVENCIÓN Y ATENCIÓN DE ILICITOS AMBIENTALES (INCENDIOS FORESTALES, CAMBIO DE USO DE SUELO, TALA CLANDESTINA) DENTRO DEL APFF COBIO CHICHINAUTZIN, EN COORDINACIÓN CON INSTANCIAS DE LOS TRES NIVELES DE GOBIERNO.', '10', '15', '100', '75', '50', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (226, 'GOZF890124', 'CUMPLIR INFORMACIÓN DE ESPECIES EN RIESGO (FAUNA) DE LAS ÁREAS DESTINADAS AL VOLUNTARIAMENTE A LA CONSERVACIÓN, PARA LA GENERACIÓN DE BASES DE DATOS PARA LA IDENTIFICACIÓN DE ESPECIES EN RIESGO DEL ÁREA NATURAL PROTEGIDA.', '04', '30', '80-90 %', '60-80 %', 'MENOR A 60%', '90', 'APOYAR EN EL DISEÑO Y OPERACIÓN DE LA ESTRATEGIA DE EDUCACIÓN AMBIENTAL Y COMUNICACIÓN SOCIAL, CON LA FINALIDAD DE LOGRAR INTERIORIZAR LOS VALORES DE CONSERVACIÓN DEL ANP EN LA POBLACIÓN QUE HABITA EN SU INTERIOR Y ZONA DE INFLUENCIA, ASÍ COMO DE LA POBLACIÓN EN GENERAL.', '04', '30', '80-90%', '60-80%', 'MENOR A 60%', '90', 'REALIZAR ACTIVIDADES ADMINISTRATIVAS Y DE LOGÍSTICA, ASÍ COMO LA GESTIÓN DE RECURSOS MATERIALES, HUMANOS, TECNOLÓGICOS, FINANCIEROS Y/O JURÍDICOS QUE SE REQUIERAN, DENTRO DE SU ÁMBITO DE APLICACIÓN, ASEGURANDO EL CUMPLIMIENTO NORMATIVO Y LA CONSERVACIÓN DE LAS ACTIVIDADES Y LA ADECUADA OPERACIÓN DEL ANP Y DIRECCIÓN REGIONAL.', '04', '20', '80-90%', '60-80%', 'MENOR A 60%', '90', 'LAS DEMÁS QUE LE CONFIERE Y/O INSTRUYA SU JEFE INMEDIATO, EL DIRECTOR DEL ANP, EL DIRECTOR REGIONAL, LA UNIDAD ADMINISTRATIVA, LA UNIDAD TÉCNICA O LA UNIDAD JURÍDICA DE LA DIRECCIÓN REGIONAL, ASÍ COMO LAS QUE SEÑALA LAS DISPOSICIONES LEGALES Y REGLAMENTARIAS VIGENTES DENTRO DE SU ALCANCE Y MARCO DE ACTUACIÓN ORIENTADAS A ASEGURAR LA ADECUADA OPERACIÓN DEL ANP, LA DIRECCIÓN REGIONAL Y LA CONSERVACIÓN DEL MEDIO AMBIENTE.', '04', '20', '80-90%', '60-80%', 'MENOR A 60%', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplica