INSERT INTO `sed_individuales` VALUES (232, 'GUMM780810', 'COORDINAR LAS ACCIONES PARA LLEVAR A CABO LA INTEGRACIÓN DE EXPEDIENTES, EVALUACIÓN Y CONTROL PARA EL OTORGAMIENTO DE LAS LICENCIAS, PERMISOS Y AUTORIZACIONES QUE EXPIDE LA COMISIÓN NACIONAL DE ÁREAS NATURALES PROTEGIDAS PARA LA PRESTACIÓN DE SERVICIOS TURÍSTICOS Y COMERCIALES EN EL ÁREA PROTEGIDA.', '10', '30', 'DEL 90-100% DE LOS EXPEDIENTES SON INTEGRADOS Y EVALUADOS PARA DAR TRÁMITE A LAS SOLICITUDES DE AUTORIZACIÓN RECIBIDAS PARA LA PRESTACIÓN DE SERVICIOS TURÍSTICOS Y COMERCIALES EN EL ÁREA.', 'DEL 71- 89% DE LOS EXPEDIENTES SON INTEGRADOS Y EVALUADOS PARA DAR TRÁMITE A LAS SOLICITUDES DE AUTORIZACIÓN RECIBIDAS PARA LA PRESTACIÓN DE SERVICIOS TURÍSTICOS Y COMERCIALES EN EL ÁREA.', 'DEL 0-70% DE LOS EXPEDIENTES SON INTEGRADOS Y EVALUADOS PARA DAR TRÁMITE A LAS SOLICITUDES DE AUTORIZACIÓN RECIBIDAS PARA LA PRESTACIÓN DE SERVICIOS TURÍSTICOS Y COMERCIALES EN EL ÁREA.', '90', 'PARTICIPAR EN RECORRIDOS DE VIGILANCIA Y MONITOREO BIOLOGICO EN EL APFF-IGC EN SINALOA, CONTRIBUYENDO A LA CONSERVACIÓN Y PROTECCIÓN DE LOS RECURSOS NATURALES, MIENTRAS SE MANTIENE ACTUALIZADO EL SISTEMA DE INFORMACIÓN, MONITOREO Y EVALUACIÓN PARA LA CONSERVACIÓN (SIMEC) DE ACUERDO CON LA INFORMACIÓN GENERADA CON LOS RECORRIDOS REALIZADOS EN EL ÁREA PROTEGIDA.', '01', '25', 'PARTICIPAR DE 8 A 10 RECORRIDOS DE VIGILANCIA Y MONITOREO', 'PARTICIPAR DE 5 A 7 RECORRIDOS DE VIGILANCIA Y MONITOREO', 'PARTICIPAR DE 1 A 4 RECORRIDOS DE VIGILANCIA Y MONITOREO', '90', 'APOYAR A LA DIRECCIÓN DEL ANP EN LA GENERACIÓN DE DICTÁMENES Y OPINIONES TÉCNICAS DE SOPORTE EN MATERIA DE ZONA FEDERAL MARÍTIMO TERRESTRE, VIDA SILVESTRE, USO Y APROVECHAMIENTO DE ECOSISTEMAS Y SU BIODIVERSIDAD, SOBRE SOLICITUDES PRESENTADAS PARA AUTORIZACIÓN DE OBRAS Y ACTIVIDADES QUE SE REALIZAN EN EL ANP.', '10', '25', 'SE DA RESPUESTA AL 90-100% DE LAS SOLICITUDES', 'SE DA RESPUESTA AL 71-89% DE LAS SOLICITUDES', 'SE DA RESPUESTA AL 0-70% DE LAS SOLICITUDES', '90', 'COORDINAR, PROMOVER Y OPERAR PROYECTOS DE CONSERVACIÓN DE LOS RECURSOS NATURALES, A TRAVÉS DEL PROGRAMA PARA LA PROTECCIÓN Y RESTAURACIÓN DE ECOSISTEMAS Y ESPECIES PRIORITARIAS (PROREST).', '10', '20', 'REALIZAR EL SEGUIMIENTO DEL 90% AL 100% DE ACCIONES ASIGNADAS AL PROGRAMA PARA LA PROTECCIÓN Y RESTAURACIÓN DE ECOSISTEMAS Y ESPECIES PRIORITARIAS (PROREST) EN AL ÁREA NATURAL PROTEGIDA.', 'REALIZAR EL SEGUIMIENTO DEL 71% AL 89% DE ACCIONES ASIGNADAS AL PROGRAMA PARA LA PROTECCIÓN Y RESTAURACIÓN DE ECOSISTEMAS Y ESPECIES PRIORITARIAS (PROREST) EN AL ÁREA NATURAL PROTEGIDA.', 'REALIZAR EL SEGUIMIENTO DEL 0% AL 70% DE ACCIONES ASIGNADAS AL PROGRAMA PARA LA PROTECCIÓN Y RESTAURACIÓN DE ECOSISTEMAS Y ESPECIES PRIORITARIAS (PROREST) EN AL ÁREA NATURAL PROTEGIDA.', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
