INSERT INTO `sed_individuales` VALUES (237, 'HARM611222', '1.- ASISTIR A LA DIRECCIÓN DEL ANP PARA LOGRAR LA CORRECTA EJECUCIÓN Y SUPERVISIÓN DE LOS PROYECTOS PROGRAMADOS EN EL PROGRAMA OPERATIVO ANUAL (POA), ASÍ COMO REPORTAR EN TIEMPO Y FORMA EL SISTEMA GENERAL DEL POA, LAS METAS ALCANZADAS PARA CADA TRIMESTRE CORRESPONDIENTE.', '10', '20', '100', '80', '50', '90', '2.- PARTICIPAR Y COORDINAR LOS OPERATIVOS, LOS RECORRIDOS Y SUPERVISIONES DE VIGILANCIA EN COADYUVANCIA CON LAS INSTANCIAS CORRESPONDIENTES QUE SE REALIZAN EN EL ANP.', '10', '20', '100', '80', '50', '90', '3.- REVISAR, EVALUAR Y EMITIR LOS DICTÁMENES TÉCNICOS DE LAS MANIFESTACIONES DE IMPACTO AMBIENTAL (MIA) QUE INCIDAN EN EL ANP, ASÍ COMO LA SUPERVISIÓN DEL CUMPLIMIENTO DE LAS CONDICIONANTES DE LOS RESOLUTIVOS APROBADOS.', '10', '20', '100', '80', '50', '90', '4.- COADYUVAR LA ORGANIZACIÓN Y ATENCIÓN DE LAS REUNIONES DE TRABAJO, EVENTOS, CURSOS Y LAS ACTIVIDADES QUE SON DIRECTAMENTE DEL INTERÉS DEL ANP, PROGRAMADAS POR LA DIRECCIÓN DEL LA RESERVA DE LA BIOSFERA.', '10', '20', '100', '80', '50', '90', '5.- COORDINAR, COADYUVAR Y SUPERVISAR LA IMPLEMENTACIÓN DE LOS PROGRAMAS QUE DESARROLLAN LOS DEPARTAMENTOS DE CULTURA CONSERVACIONISTA, MONITOREO BIOLÓGICO Y SUBSIDIOS, APLICADOS POR EL PERSONAL TÉCNICO DEL ANP.', '10', '20', '100', '80', '50', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
