INSERT INTO `sed_individuales` VALUES (240, 'HEBJ830415', 'COADYUVAR CON LAS INSTANCIAS DEL ORDEN FEDERAL, SEMAR, PROFEPA, GUARDIA NACIONAL, EN LA EJECUCIÓN DEL PROGRAMA DE INSPECCIÓN Y VIGILANCIA EN EL ANP PLAYÓN DE MISMALOYA PLAYA CHALACATEPEC, REALIZANDO ALREDEDOR DE 4 RECORRIDOS DE VIGILANCIA PARA DETECTAR Y/O PREVENIR ILÍCITOS AMBIENTALES DE PERSONAS SAQUEADORAS DE PRODUCTOS O SUBPRODUCTOS DE TORTUGA MARINA.', '10', '20', 'REALIZAR 4 RECORRIDOS DE INSPECCION Y VIGILANCIA EN PLAYÓN DE MISMALOYA PLAYA CHALACATEPEC', 'REALIZAR 2 RECORRIDOS DE INSPECCIÓN Y VIGILANCIA EN PLAYÓN DE MISMALOYA PLAYA CHALACATEPEC', 'NO REALIZAR RECORRIDOS DE INSPECCIÓN Y VIGILANCIA EN PLAYÓN DE MISMALOYA PLAYA CHALACATEPEC', '90', 'IMPULSAR LA RECUPERACIÓN DE LAS POBLACIONES LAS 3 ESPECIES DE TORTUGAS MARINAS QUE ANIDAN EN EL SANTUARIO PLAYÓN DE MISMALOYA, PLAYA CHALACATEPEC, MEDIANTE LA IMPLEMENTACIÓN DE TÉCNICAS DE MANEJO SEGÚN LA NOM-SEMARNAT-2012, RESGUARDANDO EN CORRAL DE INCUBACIÓN 6,500 NIDOS DE TORTUGA MARINA.', '10', '20', 'COLECTAR EN PLAYA CHALACATEPEC 6500 NIDOS DE TORTUGA MARINA, Y SEMBRARLOS EN EL CORRAL DE INCUBACIÓN.', 'COLECTAR EN PLAYA CHALACATEPEC 3000 NIDOS DE TORTUGA MARINA, Y SEMBRARLOS EN EL CORRAL DE INCUBACIÓN.', 'COLECTAR EN PLAYA CHALACATEPEC 1000 NIDOS DE TORTUGA MARINA, Y SEMBRARLOS EN EL CORRAL DE INCUBACIÓN.', '90', 'REALIZAR 7 CAMPAÑAS DE EDUCACIÓN AMBIENTAL PARA LA SENSIBILIZACIÓN Y CONCIENTIZACIÓN SOBRE EN LA IMPORTANCIA DE LAS TORTUGAS MARINAS EN LAS ESCUELAS DE LAS POBLACIONES CERCANAS AL CT CHALACATEPEC, ASÍ COMO LIBERACIONES DE TORTUGAS EN PLAYA CON LOS GRUPOS DE ESTUDIANTES Y VOLUNTARIOS.', '10', '20', 'REALIZAR 7 CAMPAÑAS DE EDUCACIÓN AMBIENTAL EN LAS ESCUELAS DE LA REGIÓN Y EL CT CHALACATEPEC.', 'REALIZAR 4 CAMPAÑAS DE EDUCACIÓN AMBIENTAL EN LAS ESCUELAS DE LA REGIÓN Y EL CT CHALACATEPEC.', 'REALIZAR 2 CAMPAÑAS DE EDUCACIÓN AMBIENTAL EN LAS ESCUELAS DE LA REGIÓN Y EL CT CHALACATEPEC.', '90', 'DISMINUIR A MENOS DEL 10% EL SAQUEO DEL TOTAL DE NIDAD