INSERT INTO `sed_individuales` VALUES (241, 'HECC891004', 'COORDINAR LA EJECUCIÓN DE LOS PROGRAMAS DE SUBSIDIO APLICABLES AL ANP MEDIANTE LA ASESORÍA, VERIFICACIÓN, INTEGRACIÓN Y REVISIÓN DE EXPEDIENTES EN APEGO A LAS REGLAS DE OPERACIÓN Y LINEAMIENTOS ESTABLECIDOS CON EL FIN DE CONTRIBUIR AL CUMPLIMIENTO DE OBJETIVOS Y METAS INSTITUCIONALES EN EL ANP.', '10', '20', 'EJECUCIÓN DEL 100 % DE LOS PROGRAMAS DE SUBSIDIO APLICABLES AL ANP', 'EJECUCIÓN DEL 80 % DE LOS PROGRAMAS DE SUBSIDIO APLICABLES AL ANP', 'EJECUCIÓN DEL 60 % DE LOS PROGRAMAS DE SUBSIDIO APLICABLES AL ANP', '90', 'COMPILAR INFORMACIÓN DE LAS ESPECIES EN RIESGO (FAUNA Y FLORA) DEL ANP PARA LA GENERACIÓN Y ACTUALIZACIÓN DE LAS BASES DE DATOS Y CON ELLO LA IDENTIFICACIÓN DE ESPECIES (RIESGO, PRIORITARIAS, ETC.) DEL ÁREA NATURAL PROTEGIDA.', '10', '20', 'COMPILACIÓN Y ACTUALIZACIÓN AL 100% DE LA INFORMACIÓN DE LAS ESPECIES EN RIESGO (FAUNA Y FLORA) DEL ANP.', 'COMPILACIÓN Y ACTUALIZACIÓN AL 80% DE LA INFORMACIÓN DE LAS ESPECIES EN RIESGO (FAUNA Y FLORA) DEL ANP.', 'COMPILACIÓN Y ACTUALIZACIÓN AL 60% DE LA INFORMACIÓN DE LAS ESPECIES EN RIESGO (FAUNA Y FLORA) DEL ANP.', '90', 'CONTRIBUIR Y PROVEER LOS ELEMENTOS NECESARIOS PARA LA ELABORACIÓN DEL PROGRAMA DE MANEJO DEL ANP CORRESPONDIENTE, ASÍ COMO PROMOVER LA PARTICIPACIÓN DE ACTORES CLAVES CON EL FIN DE CONTAR CON EL DOCUMENTO PUBLICADO QUE PERMITA DIRIGIR LOS PROGRAMAS Y ACTIVIDADES A DESARROLLAR DENTRO DEL ANP Y SU ZONA DE INFLUENCIA.', '10', '20', 'CONTRIBUIR Y PROVEER LOS ELEMENTOS NECESARIOS PARA LA ELABORACIÓN DEL PROGRAMA DE MANEJO DEL ANP AL 100%', 'CONTRIBUIR Y PROVEER LOS ELEMENTOS NECESARIOS PARA LA ELABORACIÓN DEL PROGRAMA DE MANEJO DEL ANP 80%', 'CONTRIBUIR Y PROVEER LOS ELEMENTOS NECESARIOS PARA LA ELABORACIÓN DEL PROGRAMA DE MANEJO DEL ANP 60%', '90', 'EJECUTAR ACCIONES ESPECIALIZADAS PARA LA PROTECCIÓN, CONSERVACIÓN Y RESTAURACIÓN DEL ANP COMO: ATENCIÓN A ESPECIES EXÓTICAS E INVASORAS, PROGRAMAS DE SANIDAD VEGETAL, PROGRAMA DE MANEJO DE FUEGO Y DE CONTINGENCIAS AMBIENTALES EN EL ANP (INCENDIOS FORESTALES) CON PERSONAL CAPACITADO.', '10', '20', 'EJECUCIÓN DE ACCIONES ESPECIALIZADAS PARA LA PROTECCIÓN, CONSERVACIÓN Y RESTAURACIÓN DEL ANP AL 100%', 'EJECUCIÓN DE ACCIONES ESPECIALIZADAS PARA LA PROTECCIÓN, CONSERVACIÓN Y RESTAURACIÓN DEL ANP AL 80%', 'EJECUCIÓN DE ACCIONES ESPECIALIZADAS PARA LA PROTECCIÓN, CONSERVACIÓN Y RESTAURACIÓN DEL ANP AL 60%', '90', 'COORDINAR LA PROMOCIÓN Y PROCESO DE DECRETO DE NUEVAS ANPS Y LA CERTIFICACIÓN DE ADVC EN LOS CORREDORES BIOLÓGICOS Y ZONA DE INFLUENCIA DEL ANP MEDIANTE LA FORMULACIÓN Y ACTUALIZACIÓN DE EPJ, INTEGRACIÓN DE SOLICITUDES DE CERTIFICACIÓN DE PREDIOS COMO ADVC, DANDO SEGUIMIENTO A LA RESOLUCIÓN DE LAS OBSERVACIONES CON EL FIN DE INCREMENTAR LA SUPERFICIE BAJO CONSERVACIÓN EN EL TERRITORIO NACIONAL.', '10', '20', 'COORDINACIÓN DE LA PROMOCIÓN Y DE LOS PROCESOS DE DECRETO DE NUEVAS ANPS Y LA CERTIFICACIÓN DE ADVC AL 100%', 'COORDINACIÓN DE LA PROMOCIÓN Y DE LOS PROCESOS DE DECRETO DE NUEVAS ANPS Y LA CERTIFICACIÓN DE ADVC AL 80%', 'COORDINACIÓN DE LA PROMOCIÓN Y DE LOS PROCESOS DE DECRETO DE NUEVAS ANPS Y LA CERTIFICACIÓN DE ADVC AL 60%', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (242, 'HEGN870725', 'IMPLEMENTAR Y DAR SEGUIMIENTO A PROYECTOS DE LOS PROGRAMAS DE SUBSIDIO. REALIZAR ACTIVIDADES ADMINISTRATIVAS, TÉCNICAS Y DE SUPERVISIÓN, LO QUE INCLUYE LA ELABORACIÓN Y FIRMA DE DOCUMENTACIÓN PROPIA DE LOS PROGRAMAS, SUPERVISIONES DE CAMPO PARA DAR SEGUIMIENTO OPORTUNO Y PUNTUAL A CADA PROYECTO.', '10', '35', 'CERRAR PROYECTOS EN CAMPO Y TENER EXPEDIENTES COMPLETOS EN UN 95%', 'CERRAR PROYECTOS EN CAMPO Y TENER EXPEDIENTES COMPLETOS EN UN 80%', 'CERRAR PROYECTOS EN CAMPO Y TENER EXPEDIENTES COMPLETOS 70%', '90', 'PLANEACIÓN, ELABORACIÓN Y SEGUIMIENTO DEL POA DEL PARQUE NACIONAL CAÑÓN DEL RÍO BLANCO, DE ACUERDO A LAS ACCIONES DE MANEJO DE DICHA ANP.', '10', '10', 'POA ELABORADO Y EJECUTADO AL 100%', 'POA ELABORADO Y EJECUTADO AL 85%', 'POA ELABORADO Y EJECUTADO AL 70%', '90', 'ATENDER Y DAR SEGUIMIENTO TÉCNICO A LAS SOLICITUDES DE LOS DICTÁMENES TÉCNICOS EN SUS DIFERENTES MODALIDADES, SOLICITADOS AL ANP PARQUE NACIONAL CAÑON DEL RIO BLANCO, REALIZANDO ACTIVIDADES DE ANÁLISIS DE LA INFORMACIÓN QUE APORTA EL PROMOVENTE, VISITAS DE CAMPO Y ELABORACIÓN DEL DICTAMEN TÉCNICO PARA APORTAR ELEMENTOS A LA DRPCGM EN LA ELABORACIÓN DE SU OPINIÓN TÉCNICA.', '10', '10', 'ELABORAR LOS DT SOLICTADOS POR LA DIRECCION REGIONAL PCGM EN UN 100%', 'ELABORAR LOS DT SOLICTADOS POR LA DIRECCION REGIONAL PCGM EN UN 85%', 'NO REALIZAR LOS DT SOLICITADOS POR LA DIRECCIÓN REGIONAL PCGM.', '90', 'PLANEAR, ELABORAR Y EJECUTAR EL PROGRAMA DE PROTECCIÓN CONTRA INCENDIOS FORESTALES DEL ANP, MEDIANTE LA BRIGADA DE CONTINGENCIAS AMBIENTALES (PROCODESCA) EN EL PARQUE NACIONAL CAÑÓN DEL RIO BLANCO, INCLUYENDO ACTIVIDADES ADMINISTRATIVAS, TÉCNICAS Y DE CAMPO, ELABORACIÓN Y FIRMA DE DOCUMENTACIÓN PROPIA DEL PROGRAMA.', '10', '35', 'REALIZAR 15 RECORRIDOS DE PREVENCION Y ATENCION A CONTINGENCIAS (INCENDIOS)', 'REALIZAR 5 RECORRIDOS DE PREVENCION Y ATENCION A CONTINGENCIAS (INCENDIOS)', 'NO REALIZAR RECORRIDOS DE PREVENCION Y ATENCION A CONTINGENCI