INSERT INTO `sed_individuales` VALUES (247, 'HELB750330', 'APOYAR EN EL PROCESO DE DIFUSIÓN, RECEPCIÓN DE SOLICITUDES Y EJECUCIÓN DE PROYECTOS RELACIONADOS CON EL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE (PROCODES).', '10', '30', '1', '0.75', '0.5', '90', 'SEGUIMIENTO Y ATENCIÓN DE REUNIONES DE TRABAJO Y RECORRIDOS DE CAMPO, PARA LA IDENTIFICACIÓN Y ATENCIÓN DE BROTES DE PLAGAS Y ENFERMEDADES FORESTALES EN COORDINACIÓN CON LOS DUEÑOS DEL TERRITORIO, INSTANCIAS DE LOS TRES NIVELES DE GOBIERNO Y PRESTADORES DE SERVICIOS FORESTALES, DENTRO DEL APFF COBIO CHICHINAUTZIN Y SU ZONA DE INFLUENCIA', '10', '20', '1', '0.75', '0.5', '90', 'PARTICIPAR EN ACTIVIDADES Y PROCESOS DE CAPACITACIÓN Y REGULACIÓN TURÍSTICA EN COORDINACIÓN CON PRESTADORES DE SERVICIOS TURÍSTICOS, AUTORIDADES COMUNALES E INSTANCIAS GUBERNAMENTALES.', '10', '10', '1', '0.75', '0.5', '90', 'PREPARAR DOCUMENTACIÓN DE SOPORTE PARA LA EMISIÓN DE OPINIONES TÉCNICAS RESPECTO A APROVECHAMIENTOS, SERVICIOS, OBRAS, Y ACTIVIDADES QUE SE PRETENDAN AUTORIZAR POR PARTE DE LAS AUTORIDADES COMPETENTES, DENTRO DE LA POLIGONAL DEL ANP APFF COBIO CHICHINAUTZIN.', '10', '30', '1', '0.75', '0.5', '90', 'FOMENTAR LA PARTICIPACIÓN DE LA POBLACIÓN Y USUARIOS DEL ÁREA, EN ACTIVIDADES DE EDUCACIÓN AMBIENTAL QUE PROMUEVAN ACCIONES PARA EL DESARROLLO SUSTENTABLE Y LA CONSERVACIÓN DE LOS SERVICIOS ECOSISTÉMICOS.', '10', '10', '1', '0.75', '0.5', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NUL