INSERT INTO `sed_individuales` VALUES (255, 'HETR780327', 'PROPORCIONAR NÚMERO Y FECHA A LOS OFICIOS QUE FIRMA ÉL DIRECTOR DE ADMINISTRACIÓN Y FINANZAS, ASÍ COMO ESCANEAR LOS ACUSES ORIGINALES DE LOS OFICIOS FIRMADOS Y REGISTRARLOS EN LA BASE DE DATOS, ARCHIVARLOS EN CARPETA FÍSICA Y ELECTRÓNICA.', '05', '40', 'LLEVAR UN CONTROL DE LOS NÚMEROS DE OFICIOS CONTANDO CON UN ARCHIVO EN PDF DE LOS MISMOS YA FIRMADOS POR ÉL DIRECTOR DE ADMINISTRACIÓN Y FINANZAS.', 'CUMPLIR EN UN 50% CON EL CONTROL DE LOS NÚMEROS DE OFICIOS, ARCHIVO Y ESCANEO, QUE FIRMA ÉL DIRECTOR DE ADMINISTRACIÓN Y FINANZAS.', 'NO LLEVAR AL 100% EL CONTROL DE LOS OFICIOS QUE YA FIRMÓ ÉL DIRECTOR DE ADMINISTRACIÓN Y FINANZAS.', '90', 'LLEVAR A CABO EL CORRECTO SEGUIMIENTO DE LA ATENCIÓN Y DE LAS RESPUESTAS DE LA CORRESPONDENCIA QUE SE TURNA A LAS ÁREAS DE LA DIRECCIÓN DE ADMINISTRACIÓN Y FINANZAS, A TRAVÉS DE LA PÁGINA DEL SISTEMA DE CONTROL DE GESTIÓN DE LA CONANP.', '04', '40', 'DAR UN CORRECTO SEGUIMIENTO Y CIERRE DE LOS ASUNTOS QUE SE TURNAN A LAS ÁREAS DE LA DIRECCIÓN DE ADMINISTRACIÓN Y FINANZAS A TRAVÉS DE LA PÁGINA DEL SISTEMA DE CONTROL DE GESTIÓN DE LA CONANP, A UN 95%', 'DAR UN SEGUIMIENTO Y CIERRE DE LOS ASUNTOS EN UN 60%', 'NO DAR EL SEGUIMIENTO Y CIERRE DE LOS ASUNTOS EN TIEMPO Y FORMA.', '90', 'RECIBIR LA CORRESPONDENCIA DE LA DIRECCIÓN DE ADMINISTRACIÓN Y FINANZAS, CON EL OBJETO DE TURNARLA A TRAVÉS DE LA PÁGINA DEL SISTEMA DE CONTROL DE GESTIÓN DE LA CONANP, A TODAS LAS ÁREAS DE LA DIRECCIÓN DE ADMINISTRACIÓN Y FINANZAS.', '05', '20', 'TURNAR LA CORRESPONDENCIA EN TIEMPO Y FORMA DE LAS DISTINTAS ÁREAS DE LA DIRECCIÓN DE ADMINISTRACIÓN Y FINANZAS EN UN 95%.', 'TURNAR EN UN TIEMPO MINIMO DE 2 HORAS LA CORRESPONDENCIA.', 'NO TURNAR LA CORRESPONDENCIA A TRÁVES DEL SISTEMA DE CONTROL DE GESTIÓN DE LA CONANP.', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de