INSERT INTO `sed_individuales` VALUES (258, 'IACJ770325', 'COORDINAR PROYECTOS DE RESTAURACIÓN Y CONSERVACIÓN DE LOS ECOSISTEMAS REPRESENTATIVOS DEL ANP, CON COMUNIDADES DE LA ZONA DE INFLUENCIA Y CON SOCIOS EXTERNOS A TRAVÉS DEL PROGRAMA PARA LA PROTECCIÓN Y RESTAURACIÓN DE ECOSISTEMAS Y ESPECIES PRIORITARIAS (PROREST).', '08', '20', '90', '70', '50 HACIA ABAJO', '90', 'SEGUIMIENTO EN LA OPERACIÓN DE PROYECTOS EN EL ANP Y SU ZONA DE INFLUENCIA QUE SE REALICEN EN COLABORACIÓN CON ORGANISMOS DE LA SOCIEDAD CIVIL Y ORGANIZACIONES INTERNACIONALES PARA LA IMPLEMENTACIÓN DE ACCIONES DE PROTECCIÓN, CONSERVACIÓN Y RESTAURACIÓN DE ECOSISTEMAS.', '08', '20', '90', '70', '50 HACIA ABAJO', '70', 'OPERACIÓN DEL VIVERO EL CASTILLO Y SEGUIMIENTO DE LA PRODUCCIÓN DE PLANTA FORESTAL PARA SU POSTERIOR UTILIZACIÓN EN ACCIONES DE CONSERVACIÓN Y RESTAURACIÓN DENTRO DEL PARQUE NACIONAL Y SUS ZONAS DE INFLUENCIA.', '08', '20', '90', '70', '50 HACIA ABAJO.', '70', 'COLABORAR Y APOYAR EN LAS DIVERSAS ACTIVIDADES DE TURISMO, DIFUSIÓN, EDUCACIÓN Y ADMINISTRATIVAS QUE SE REALIZAN EN LAS OTRAS ÁREAS QUE COMPONEN AL ANP, CON EL FIN DE DAR CUMPLIMIENTO AL PROGRAMA DE MANEJO DEL PARQUE NACIONAL IZTACCÍHUATL POPOCATÉPETL.', '08', '20', '90', '70', '50 HACIA ABAJO.', '70', 'PARTICIPAR CON EL SECTOR AMBIENTAL FEDERAL, ESTATAL Y MUNICIPAL EN ACCIONES DE SEGUIMIENTO ENFOCADAS A LA RESTAURACIÓN EN ZONAS AFECTADAS POR ACTIVIDADES ANTRÓPICAS.', '08', '20', '90', '70', '50 HACIA ABAJO.', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al mom