INSERT INTO `sed_individuales` VALUES (275, 'LEAD810409', 'REALIZAR RECORRIDOS DE VIGILANCIA EN EL SANTUARIO PLAYA DE PUERTO ARISTA Y ZONA DE INFLUENCIA (SITIO RAMSAR) PARA LA DETECCIÓN DE CONTINGENCIAS E ILÍCITOS AMBIENTALES.', '01', '25', 'REALIZAR DEL 90% AL 100%.', 'REALIZAR DEL 50% AL 89%.', 'REALIZAR MENOS DEL 50%.', '90', 'PARTICIPAR EN LAS ACCIONES DE PROTECCIÓN CONTRA INCENDIOS FORESTALES U QUEMAS PARA PREVENIR, CONTROLAR Y COMBATIR ESTAS PROBLEMÁTICAS QUE AFECTAN LOS ECOSISTEMAS EN EL ÁREA NATURAL PROTEGIDA Y SITIO RAMSAR.', '01', '25', 'PARTICIPAR EN LA ATENCION DEL 90% AL 100% DE CONTINGENCIAS QUE SE PRESENTEN EN EL SANTUARIO Y SITIO RAMSAR PUERTO ARISTA.', 'PARTICIPAR EN LA ATENCION DEL 50% AL 89% DE LAS CONTINGENCIAS QUE SE PRESENTEN EN EL SANTUARIO Y SITIO RAMSAR PUERTO ARISTA.', 'PARTICIPAR EN LA ATENCIÓN MENOR AL 50% DE CONTINGENCIAS QUE SE PRESENTEN EN EL SANTUARIO Y SITIO RAMSAR PUERTO ARISTA.', '90', 'RECOPILAR, VERIFICAR, VALIDAR LA INFORMACIÓN TÉCNICA DE LOS PROGRAMAS DE SUBSIDIOS (PROCODES Y PROREST) Y CUALQUIER SISTEMA (CONTRALORIA SOCIAL) QUE ESTE RELACIONADO CON LOS SUBSIDIOS PARA IMPLEMENTAR Y FORTALECER LAS ACCIONES DE CONSERVACIÓN, PROTECCIÓN DEL SANTUARIO Y SITIO RAMSAR.', '01', '25', 'REVISAR DEL 90% AL 100% LOS PROYECTOS DE PROGRAMAS DE SUBSIDIOS AUTORIZADOS AL ÁREA NATURAL PROTEGIDA.', 'REVISAR DEL 50% AL 89% LOS PROYECTOS DE PROGRAMAS DE SUBSIDIOS AUTORIZADOS AL ÁREA NAURAL PROTEGIDA.', 'REVISAR MENOS DEL 50% LOS PROYECTOS DE PROGRAMAS DE SUBSIDIOS AUTORIZADOS AL ÁREA NATURAL PROTEGIDA.', '90', 'FORTALECER Y PROMOVER LA PARTICIPACIÓN SOCIAL EN LA PROTECCIÓN Y CONSERVACIÓN DE LA TORTUGA MARINA QUE ARRIBA EN LA PLAYA DEL SANTUARIO PUERTO ARISTA.', '01', '25', 'PROMOVER LA PARTICIPACION DE TRES GRUPOS COMUNITARIOS EN ACCIONES DE PROTECCIÓN, VIGILANCIA Y EDUCACIÓN AMBIENTAL PARA LA PROTECCIÓN Y CONSERVACION DE LA TORTUGA MARINA EN EL SANTUARIO PLAYA DE PUERTO ARISTA.', 'PROMOVER LA PARTICIPACION DE DOS GRUPOS COMUNITARIOS EN ACCIONES DE PROTECCIÓN, VIGILANCIA Y EDUCACIÓN AMBIENTAL PARA LA PROTECCIÓN Y CONSERVACION DE LA TORTUGA MARINA EN EL SANTUARIO PLAYA DE PUERTO ARISTA', 'PROMOVER LA PARTICIPACION DE UN GRUPO COMUNITARIO EN ACCIONES DE PROTECCIÓN, VIGILANCIA Y EDUCACIÓN AMBIENTAL PARA LA PROTECCIÓN Y CONSERVACION DE LA TORTUGA MARINA EN EL SANTUARIO PLAYA DE PUERTO ARISTA', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (276, 'LEAL660116', 'ELABORAR Y COORDINAR LA EJECUCIÓN DEL PROGRAMA OPERATIVO ANUAL (POA) DEL ANP CON BASE EN EL DECRETO Y EL PROGRAMA DE MANEJO, ASÍ COMO ELABORAR Y ENTREGAR EN TIEMPO Y FORMA LOS 4 INFORMES TRIMESTRALES DE LAS ACCIONES Y AVANCES OBTENIDAS ASÍ COMO LOS LOGROS ANUALES OBTENIDOS CON LAS ACTIVIDADES REALIZADAS DENTRO DEL ANP.', '05', '40', 'SE GENERA EL POA DEL ANP, CON 4 INFORMES QUE INTEGRAN TODAS LAS ACTIVIDADES REALIZADAS DENTRO DE LA RESERVA Y AL FINAL DEL AÑO SE ENTREGARA LOS LOGROS OBTENIDOS EN LA CONSERVACIÓN DE LAS ACTIVIDADES DESARROLLADAS', 'SE ELABORA UN PROGRAMA OPERATIVO ANUAL (POA)', 'NO ELABORAR EL PROGRAMA OPERATIVO (POA)', '90', 'GESTIONAR, PROMOVER Y CONCRETAR LA OBTENCIÓN DE APOYOS CON INSTANCIAS OFICIALES PARA LA CONSERVACIÓN DEL ANP A TRAVÉS DE LA OPERACIÓN Y SEGUIMIENTO DE 4 PROYECTOS DEL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO (PROCODES) Y 4 DE PROREST A FIN DE CONTRIBUIR AL CUMPLIMIENTO DE LOS OBJETIVOS DEL APFF SIERRA LA MOJONERA (CONANP)', '04', '30', 'OBTENER APOYOS CON LAS DIFERENTES INSTANCIA DEL GOBIERNO FEDERAL PARA LLEVAR A CABO 8 PROYECTOS DEL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO (PROCODES Y PROREST)', 'OBTENER APOYOS CON LAS DIFERENTES INSTANCIA DEL GOBIERNO FEDERAL PARA LLEVAR A CABO 3 PROYECTOS DEL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO (PROCODES Y PROREST)', 'OBTENER APOYOS CON LAS DIFERENTES INSTANCIA DEL GOBIERNO FEDERAL PARA LLEVAR A CABO1 PROYECTO DEL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO (PROCODES)', '90', 'IMPLEMENTAR PROTOCOLOS DE MONITOREO DE ESPECIES EMBLEMÁTICAS CON LA PARTICIPACIÓN DE ORGANIZACIONES DE LA SOCIEDAD CIVIL, INSTITUCIONES ACADÉMICAS Y/O POBLADORES LOCALES', '05', '30', 'DOS PROTOCOLOS DE MONITOREO (DOS ESPECIES DE FLORA O FAUNA) IMPLEMENTADOS CON LA PARTICIPACIÓN DE ORGANIZACIONES DE LA SOCIEDAD CIVIL, INSTITUCIONES ACADÉMICAS Y/O POBLADORES LOCALES', 'UN PROTOCOLO DE MONITOREO IMPLEMENTADOS CON LA PARTICIPACIÓN DE ORGANIZACIONES DE LA SOCIEDAD CIVIL, INSTITUCIONES ACADÉMICAS Y/O POBLADORES LOCALES', 'NINGÚN PROTOCOLO DE MONITOREO IMPLEMENTADOS CON LA PARTICIPACIÓN DE ORGANIZACIONES DE LA SOCIEDAD CIVIL , INSTITUCIONES ACADÉMICAS Y/O POBLADORES LOCALES', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (277, 'LECE690302', 'TRAMITAR Y GESTIONAR LOS PAGOS PARA LAS NECESIDADES DE LA OPERACION DEL PARQUE NACIONAL PICO DE ORIZABA EN COORDINACION CON LA DIRECCIÓN REGIONAL, A FIN DE ASEGURAR LA OPORTUNA Y CORRECTA OPERACION DEL POA Y PROGRAMAS DE SUBSIDIOS, ASI COMO SU ADECUADA ASMINISTRACION.', '02', '25', 'SE ASEGURA AL MENOS EL 90% DE LA OPERACIÓN Y ADMINISTRACION DEL ANP DE MANERA CORRECTA Y OPORTUNA.', 'SE ASEGURO DE 90% A 70% LA OPERACIÓN Y ADMINISTRACION DEL ANP DE MANERA CORRECTA Y OPORTUNA.', 'SE ASEGURO MENOS DEL 70% LA OPERACIÓN Y ADMINISTRACION DEL ANP DE MANERA CORRECTA Y OPORTUNA.', '90', 'DAR SEGUIMINETO ADMINISTRATIVO, TECNICO, OPERATIVO Y DE SUPERVSION EN CAMPO A TODAS LAS SOLICITUDES DEL PROGRAMA DE SONSERVACION PARA EL DESARROLLO SOSTENIBLE (PROCODES) EN DISTINTAS MODALIDADES DE APOYO Y ETAPAS, AUTORIZADAS PARA EL AREA NATURAL PROTEGIDA,', '04', '25', '90% DE LOS PROYECTOS CONCLUIDOS', '75% DE LOS PROYECTOS CONCLUIDOS', 'MENOS DEL 60% DE LOS PROYECTOS CONCLUIDOS', '90', 'APOYAR EN LA CAPTURA DE INFORMACION EN LAS PLATAFORMAS DE LOS PROGRAMAS DE SUBSIDIOS DE CONANP Y DE LAS PLATAFORMAS DE RECURSOS EXTERNOS AUTORIZADOS', '07', '20', 'CAPTURA DEL 90 AL 100% DE LA INFORMACIÓN SOLICITADA POR LA OFICINA REGIONAL', 'CAPTURAR DE MENOS DEL 70% DE LA INFORMACIÓN SOLICITADA POR LA OFICINA REGIONAL', 'NO SE REALIZA NINGUNA CAPTURA DE LA INFORMACIÓN SOLICITADA POR LA OFICINA REGIONAL', '90', 'ACTUALIZAR INVENTARIOS Y RESGUARDOS VIGENTES DE MUEBLES DEBIDAMENTE ETIQUETADOS Y RESGISTRADOS EN EL SISTEMA INTEGRAL DE RECURSOS MATERIALES (SIREM), DE ACUERDO A LA INFORMACIÓN ENVIADA POR LA DIRECCIÓN REGIONAL PLANICIE COSTERA Y GOLFO DE MÉXICO. REGISTRAR BIENES DONADOS DE OTRAS INSTITUCIONES, ELABORAR ACTAS DE CIERRE E INICIO DE TOMA DE INVENTARIOS.', '08', '15', 'CUMPLIR DEL 90 AL 100% CON LA ACTUALIZACIÓN DE INVENTARIOS Y RESGUARDOS DE ACUERDO AL SIREM', 'CUMPLIR CON MENOS DEL 70% CON LA ACTUALIZACION DE INVENTARIOS Y RESGUARDOS DE ACUERDO AL SIREM', 'CUMPLIR CON MENOS DEL 50% CON LA ACTUALIZACIÓN DE INVENTARIOS Y RESGUARDOS DE ACUERDO AL SIREM', '90', 'TRAMITAR Y SUMINISTRAR DE MATERIALES Y ÚTILES DE OFICINA, CONSUMIBLES, SALDOS EN TARJETAS DE MONEDEROS ELECTRONICOS DE GASOLINA, ASÍ COMO LLEVAR EL CONTROL DE CADA CONCEPTO.', '04', '15', 'SE LOGRA EL 90% DE LA PLIACIÓN DE LOS RECURSOS', 'SE LOGRA DEL 60% AL 85% DE LA APLIACIÓN DE LOS RECURSOS', 'SE CUMPLE CON MENOS DEL 50% DE LA APLIACIÓN DE LOS RECURSOS', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (278, 'LECM851226', 'ATENDER LAS SOLICITUDES Y ELABORAR LOS PROYECTOS DE RESPUESTA, PARA AUTORIZACIONES DE VISITAS GUIADAS INCLUYENDO EL APROVECHAMIENTO NO EXTRACTIVO DE VIDA SILVESTRE DENTRO DEL ARCHIPIÉLAGO DE CORONADO, ARCHIPIÉLAGO TODO SANTOS, ISLA SAN MARTÍN Y ARCHIPIÉLAGO DE SAN JERÓNIMO DE LA RESERVA DE LA BIOSFERA ISLAS DEL PACIFICO DE LA PENÍNSULA DE BAJA CALIFORNIA Y ENVIARLAS A LA UNIDAD JURÍDICA DE LA DIRECCIÓN REGIONAL PENÍNSULA DE BAJA CALIFORNIA Y PACIFICO NORTE.', '10', '25', 'ATENDER LAS SOLICITUDES Y ELABORAR DEL 90 AL 100% LOS PROYECTOS DE RESPUESTA AL AÑO.', 'ATENDER LAS SOLICITUDES Y ELABORAR DEL 70 AL 89% LOS PROYECTOS DE RESPUESTA AL AÑO.', 'ATENDER Y ELABORAR MENOS DEL 70 LAS SOLICITUDES AL AÑO.', '90', 'ATENDER Y ELABORAR LAS RESPUESTAS DE LOS AVISOS PARA DESARROLLAR ACTIVIDADES DENTRO DEL ARCHIPIÉLAGO DE CORONADO, ARCHIPIÉLAGO TODO SANTOS, ISLA SAN MARTÍN Y ARCHIPIÉLAGO DE SAN JERÓNIMO DE LA RESERVA DE LA BIOSFERA ISLAS DEL PACIFICO DE LA PENÍNSULA DE BAJA CALIFORNIA, REFERENTES AL ARTÍCULO 105 DEL REGLAMENTO DE LA LGEEPA.', '10', '25', 'ATENDER Y ELABORAR DEL 90 AL 100% DE LAS RESPUESTA AL AÑO.', 'ATENDER Y ELABORAR DEL 70 AL 89% DE LAS RESPUESTA AL AÑO.', 'ATENDER Y ELABORAR MENOS DEL 70 AL 89% DE LAS RESPUESTA AL AÑO.', '90', 'ATENDER, EVALUAR Y ELABORAR OPINIONES TÉCNICAS EN MATERIA DE IMPACTO AMBIENTAL, ACTIVIDADES CIENTÍFICAS Y ACTIVIDADES TURÍSTICAS QUE SE PRETENDEN REALIZAR DENTRO DEL ARCHIPIÉLAGO DE CORONADO, ARCHIPIÉLAGO TODO SANTOS, ISLA SAN MARTÍN Y ARCHIPIÉLAGO DE SAN JERÓNIMO DE LA RESERVA DE LA BIOSFERA ISLAS DEL PACIFICO DE LA PENÍNSULA DE BAJA CALIFORNIA.', '10', '25', 'ATENDER Y ELABORAR DEL 90 AL 100% DE LAS RESPUESTAS A LAS SOLICITUDES DE OPINIONES TÉCNICAS AL AÑO.', 'ATENDER Y ELABORAR DEL 70 AL 89% DE LAS RESPUESTAS A LAS SOLICITUDES DE OPINIONES TÉCNICAS AL AÑO', 'ATENDER Y ELABORAR MENOS DEL 70 LAS SOLICITUDES AL AÑO.', '90', 'DAR SEGUIMIENTO A LA ELABORACIÓN DEL PROGRAMA DE MANEJO DE LA RESERVA, MEDIANTE LA REVISIÓN E INTEGRACIÓN DE LA INFORMACIÓN DE LOS POLÍGONOS ARCHIPIÉLAGO DE CORONADO, ARCHIPIÉLAGO TODO SANTOS, ISLA SAN MARTÍN Y ARCHIPIÉLAGO DE SAN JERÓNIMO DE LA RESERVA DE LA BIOSFERA ISLAS DEL PACIFICO DE LA PENÍNSULA DE BAJA CALIFORNIA.', '10', '25', 'ATENDER Y DAR SEGUIMIENTO DEL 90 AL 100% DE LA INFORMACIÓN SOLICITADA.', 'ATENDER Y DAR SEGUIMIENTO DEL 70 AL 89% DE LA INFORMACIÓN SOLICITADA.', 'ATENDER Y DAR SEGUIMIENTO AL 70 DE LA INFORMACIÓN SOLICITADA.', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (279, 'LEDR890615', 'REGISTRAR Y RECOPILAR INFORMACIÓN BIOLÓGICA DISPONIBLE PARA LA IMPLEMENTACIÓN DE PROYECTOS AUTORIZADOS COMPATIBLES CON LA PLANEACIÓN ESTRATÉGICA Y LA NORMATIVIDAD VIGENTE EN EL ÁREA NATURAL PROTEGIDA.', '02', '20', '80', '70', '60', '90', 'APOYAR Y DAR SEGUIMIENTO EN LA IMPLEMENTACIÓN DE ESTRATEGIAS DE CONSERVACIÓN Y APROVECHAMIENTO SOSTENIBLE DE LOS RECURSOS NATURALES DEL ÁREA NATURAL PROTEGIDA ASÍ COMO EN LA OPERATIVIDAD DE PROYECTOS DE DIVERSIFICACIÓN PRODUCTIVA.', '02', '20', '80', '70', '60', '90', 'IMPLEMENTAR ACCIONES DE CONSERVACIÓN EN LOS ECOSISTEMAS ASÍ COMO GENERAR ESTRATEGIAS PARA LA INVESTIGACIÓN Y MONITOREO DE ESPECIES PRIORITARIAS EN EL ÁREA NATURAL PROTEGIDA.', '02', '20', '80', '70', '60', '90', 'APOYAR EN LA EJECUCIÓN DE EVENTOS DE EDUCACIÓN AMBIENTAL ENFOCADAS EN LA CONSERVACIÓN DE LOS ECOSISTEMAS, SU CONOCIMIENTO Y EL APROVECHAMIENTO SUSTENTABLE DE LOS RECURSOS NATURALES EN EL ÁREA NATURAL PROTEGIDA.', '02', '20', 'SE REALIZAN 5 EVENTOS DE DIFUSIÓN Y/O SENSIBILIZACIÓN.', 'SE REALIZAN 3 EVENTOS DE DIFUSIÓN Y/O SENSIBILIZACIÓN.', 'NO SE REALIZAN EVENTOS DE DIFUSIÓN Y/O SENSIBILIZACIÓN.', '90', 'APOYAR EN LA EJECUCIÓN Y SEGUIMIENTO DE PROYECTOS DE VIGILANCIA Y MONITOREO COMUNITARIO ASÍ COMO PROMOVER Y DAR CUMPLIMIENTO A LAS ESTRATEGIAS ENFOCADAS EN LA REDUCCIÓN DE LA PERDIDA DE LA BIODIVERSIDAD EN EL ÁREA NATURAL PROTEGIDA.', '02', '20', '80', '70', '60', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
