INSERT INTO `sed_individuales` VALUES (281, 'LEMJ830113', 'DISEÑAR Y COORDINAR LA EJECUCIÓN DE LOS PROGRAMAS OPERATIVOS ANUALES (POA) Y PROYECTOS ESPECÍFICOS DE CONSERVACIÓN Y APROVECHAMIENTO DE LOS RECURSOS NATURALES DEL ANP CON BASE EN EL DECRETO Y EL PROGRAMA DE MANEJO ASÍ COMO EL CUMPLIMIENTO DE LOS OBJETIVOS DEL MISMO EN EL PARQUE NACIONAL LAGUNAS DE MONTEBELLO.', '04', '30', 'SE REALIZAN Y EJECUTAN PROYECTOS ESTRATÉGICOS DE MANEJO A TRAVÉS DE 10 A 15 ACCIONES', 'SE REALIZAN Y EJECUTAN PROYECTOS ESTRATÉGICOS DE MANEJO A TRAVÉS DE 6 A 9 ACCIONES', 'SE REALIZAN Y EJECUTAN PROYECTOS ESTRATÉGICOS DE MANEJO A TRAVÉS DE 1 A 5 ACCIONES', '90', 'PROMOVER Y CONCERTAR APOYOS CON INSTANCIAS OFICIALES DE LOS TRES ÓRDENES DE GOBIERNO Y CON LOS SECTORES SOCIALES Y PRIVADOS, PARA EJECUTAR ACCIONES DE PROTECCIÓN, MANEJO, RESTAURACIÓN, GENERACIÓN DE CONOCIMIENTO, CULTURA Y GESTIÓN PARA LA CONSERVACIÓN DEL ÁREA NATURAL PROTEGIDA A FIN DE CONTRIBUIR AL CUMPLIMIENTO DE LOS OBJETIVOS DE LA COMISIÓN DE ÁREAS NATURALES PROTEGIDAS.', '04', '30', 'SE TOMAN AL MENOS 3 ACUERDOS DE PARTICIPACIÓN EN ACCIONES DE MANEJO', 'SE TOMAN AL MENOS 2 ACUERDOS DE PARTICIPACIÓN EN ACCIONES DE MANEJO', 'SE TOMAN AL MENOS 1 ACUERDO DE PARTICIPACIÓN EN ACCIONES DE MANEJO', '90', 'PROMOVER Y/O PARTICIPAR EN MECANISMOS DE PARTICIPACIÓN SOCIAL QUE CONTRIBUYAN A LAS ACCIONES DE MANEJO Y CONSERVACIÓN DEL PARQUE NACIONAL LAGUNAS DE MONTEBELLO.', '04', '20', 'SE REALIZAN AL MENOS 3 REUNIONES DEL CONSEJO ASESOR, SUBCONSEJOS, COMISIONES O COMITÉS DE PARTICIPACIÓN SOCIAL', 'SE REALIZAN AL MENOS 2 REUNIONES DEL CONSEJO ASESOR, SUBCONSEJOS, COMISIONES O COMITÉS DE PARTICIPACIÓN SOCIAL', 'SE REALIZAN AL MENOS 1 REUNIÓN DEL CONSEJO ASESOR, SUBCONSEJOS, COMISIONES O COMITÉS DE PARTICIPACIÓN SOCIAL', '90', 'DIRIGIR Y SUPERVISAR LA CORRECTA EJECUCIÓN DE PROYECTOS DE DESARROLLO SUSTENTABLE CON EL APOYO DE SUBSIDIOS Y PROYECTOS DE CONSERVACIÓN EN EL PARQUE NACIONAL LAGUNAS DE MONTEBELLO.', '04', '20', 'SE EJECUTAN SATISFACTORIAMENTE ENTRE 8 A 10 PROYECTOS', 'SE EJECUTAN SATISFACTORIAMENTE ENTRE 5 A 7 PROYECTOS', 'SE EJECUTAN SATISFACTORIAMENTE ENTRE 1 A 4 PROYECTOS', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (282, 'LEOA720726', 'CONSOLIDAR EL SISTEMA DE INFORMACIÓN GEOGRÁFICA (SIG) DE LA DIRECCIÓN REGIONAL PENÍNSULA DE YUCATÁN Y CARIBE MEXICANO (DR PYCM), INTEGRANDO Y ACTUALIZANDO LA INFORMACIÓN REGIONAL, SOBRE ASPECTOS FÍSICOS; BIOLÓGICOS; SOCIOECONÓMICOS; ESTADO DE CONSERVACIÓN Y MANEJO DE LOS ECOSISTEMAS EN LAS ÁREAS NATURALES PROTEGIDAS.', '10', '25', 'IGUAL O MAYOR A 85', 'IGUAL O MAYOR A 75 Y MENOR A 85', 'MENOR A 75', '90', 'ATENDER LAS SOLICITUDES DE INFORMACIÓN O DE APOYO QUE, EN MATERIA DE SIG, REALICEN LOS TITULARES DE LAS DIRECCIONES Y SUBDIRECCIONES DE ÁREA NATURAL PROTEGIDA ADSCRITAS A LA DR PYCM.', '10', '25', 'IGUAL O MAYOR A 85', 'IGUAL O MAYOR A 75 Y MENOR A 85', 'MENOR A 75', '90', 'BRINDAR APOYO TÉCNICO Y LOGÍSTICO PARA LA ELABORACIÓN DE OPINIONES TÉCNICAS SOBRE LA VIABILIDAD DE OBRAS Y ACTIVIDADES QUE, SE PRETENDAN REALIZAR EN LAS ÁREAS NATURALES PROTEGIDAS, Y SU ZONA DE INFLUENCIA QUE FORMEN PARTE DE LA DIRECCIÓN REGIONAL PYCM.', '10', '25', 'IGUAL O MAYOR A 85', 'IGUAL O MAYOR A 75 Y MENOR A 85', 'MENOR A 75', '90', 'REALIZAR LOS DICTÁMENES PERICIALES EN MATERIA DE SISTEMAS DE INFORMACIÓN GEOGRÁFICA Y AFINES QUE SE REQUIERAN PRESENTAR EN LOS DIVERSOS PROCESOS JUDICIALES DONDE LA COMISIÓN NACIONAL DE ÁREAS NATURALES PROTEGIDAS Y/O LA DIRECCIÓN REGIONAL PENÍNSULA DE YUCATÁN Y CARIBE MEXICANO ES PARTE INTERESADA O RESPONSABLE.', '10', '15', 'IGUAL O MAYOR A 85', 'IGUAL O MAYOR A 75 Y MENOR A 85', 'MENOR A 75', '90', 'ATENDER LAS SOLICITUDES DE LAS DIRECCIONES DE ÁREAS NATURALES PROTEGIDAS QUE FORMAN PARTE DE LA DIRECCIÓN REGIONAL PENÍNSULA DE YUCATÁN Y CARIBE MEXICANO, PARA REALIZAR LEVANTAMIENTOS TOPOGRÁFICOS Y VUELOS CON DRON QUE PERMITAN UBICAR Y ANALIZAR ÁREAS DE INTERÉS BIOLÓGICO O QUE SE REQUIEREN EVALUAR PARA DETERMINAR ALGÚN IMPACTO POR ACTIVIDADES ANTROPOGÉNICAS.', '10', '10', 'IGUAL O MAYOR A 85', 'IGUAL O MAYOR A 75 Y MENOR A 85', 'MENOR A 75', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
