INSERT INTO `sed_individuales` VALUES (286, 'LOCI751228', 'ATENDER CURSO DE CAPACITACIÓN Y/O ACTUALIZACIÓN DE LAS REGLAS DE OPERACIÓN Y LINEAMIENTOS OPERATIVOS DE LOS PROGRAMAS DE SUBSIDIOS APLICABLES EN LAS ANP Y UN CURSO DEL SISTEMA DE INFORMACIÓN DE CONTRALORÍA SOCIAL.', '01', '10', 'QUE SE ATIENDAN LOS DOS CURSOS', 'QUE SE ATIENDAN LOS DOS CURSOS', 'QUE NO SE ATIENDA NINGÚN CURSO', '70', '2 IMPARTIR CURSO DE CAPACITACIÓN Y/O ACTUALIZACIÓN DE LAS REGLAS DE OPERACIÓN Y LINEAMIENTOS OPERATIVOS DE PROGRAMAS DE SUBSIDIOS AL PERSONAL DE LAS ANP ADSCRITAS A LA DIRECCIÓN REGIONAL NORTE Y SIERRA MADRE OCCIDENTAL Y LLENADO DE ANEXOS AL 100% DEL PERSONAL DE LAS ANP ADSCRITOS A LA DIRECCIÓN REGIONAL NORTE Y SIERRA MADRE OCCIDENTAL', '01', '10', 'QUE SE CAPACITE AL 100% DEL PERSONAL DE LAS ANP', 'QUE SE CAPACITE AL 80% DEL PERSONAL DE LAS ANP', 'QUE SE CAPACITE AL 60% DEL PERSONAL DE LAS ANP', '90', '3 SUPERVISAR EL 100% DE LA INTEGRACIÓN DE EXPEDIENTES DE LOS PROYECTOS APROBADOS EN LAS ANP ADSCRITAS A LA DIRECCIÓN REGIONAL NORTE Y SIERRA MADRE OCCIDENTAL, QUE SE PRESENTAN PARA LA GESTIÓN DE PAGOS DEL PROGRAMA PARA LA PROTECCIÓN Y RESTAURACIÓN DE ECOSISTEMAS Y ESPECIES PRIORITARIAS (PROREST)', '01', '40', 'QUE SE SUPERVISE LA INTEGRACIÓN DEL 100% DE LOS EXPEDIENTES', 'QUE SE SUPERVISE LA INTEGRACIÓN DEL 95% DE LOS EXPEDIENTES', 'QUE SE SUPERVISE LA INTEGRACIÓN DEL 90% DE LOS EXPEDIENTES', '90', '4 REALIZAR LA SUPERVISIÓN EN CAMPO Y GABINETE DE LOS PROYECTOS DE 2 ANP ADSCRITAS A LA DIRECCIÓN REGIONAL NORTE Y SIERRA MADRE OCCIDENTAL DEL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE (PROCODES) Y DEL PROGRAMA PARA LA PROTECCIÓN Y RESTAURACIÓN DE ECOSISTEMAS Y ESPECIES PRIORITARIAS (PROREST) APROBADOS Y QUE SEAN DEFINIDOS POR LA DIRECCIÓN GENERAL DE OPERACIÓN REGIONAL, EN EL PROGRAMA ANUAL DE SUPERVISIÓN.', '01', '10', 'QUE SE REALICE LA SUPERVISIÓN DE 2 ANP', 'QUE SE REALICE LA SUPERVISIÓN DE 1 ANP', 'QUE NO SE REALICE LA SUPERVISIÓN EN NINGÚN ANP', '90', '5 REVISAR AL 