INSERT INTO `sed_individuales` VALUES (287, 'LOCM740117', 'OBTENER LA INFORMACIÓN NECESARIA PARA LA EVALUACIÓN Y SEGUIMIENTO DE LAS ACTIVIDADES PROGRAMADAS EN LOS PROGRAMAS OPERATIVOS ANUALES DE LA ANP APFF ISLAS DEL GOLFO DE CALIFORNIA SONORA Y RB ISLA SAN PEDRO MÁRTIR QUE LA CONFORMAN.', '02', '30', 'DAR CUMPLIMIENTO CON EL 100% EN TIEMPO Y FORMA CON TODOS LOS INFORMES QUE SE REQUIEREN DURANTE LA EJECUCIÓN DEL PROGRAMA OPERATIVO ANUAL.', 'DAR CUMPLIMIENTO EN TIEMPO Y FORMA CON AL MENOS EL 75% DE LOS INFORMES QUE SE REQUIEREN DURANTE LA EJECUCIÓN DEL PROGRAMA OPERATIVO ANUAL.', 'DAR CUMPLIMIENTO EN TIEMPO Y FORMA CON AL MENOS EL 50% DE LOS INFORMES QUE SE REQUIEREN DURANTE LA EJECUCIÓN DEL PROGRAMA OPERATIVO ANUAL.', '90', 'MANTENER ACTUALIZADA LA BASE DE DATOS CON LOS RESULTADOS DE CADA RECORRIDO DE INSPECCIÓN Y VIGILANCIA CON PROFEPA Y LOS RESULTADOS DE LOS RECORRIDOS DE VIGILANCIA LLEVADOS A CABO POR EL PERSONAL DE LA RESERVA. EN CASO DE QUE SE HAYAN ENCONTRADO ILÍCITOS, APOYAR EN EL EVIDENCIAS DE ACTAS DE HECHO Y SE INCORPORARAN A LA BASE DE DATOS PARA PODER DAR SEGUIMIENTO EN EL PROCEDIMIENTO QUE SE LLEVE, DENTRO DE LA ANP APFF ISLAS DEL GOLFO DE CALIFORNIA SONORA Y RB ISLA SAN PEDRO MÁRTIR QUE LA CONFORMAN.', '05', '15', 'ACTUALIZADA LA BASE DE DATOS DE LOS RECORRIDOS CON LA INFORMACIÓN DE 90 % DE ACUERDO A LOS RECORRIDOS DE INSPECCIÓN Y VIGILANCIA DE LA ANP APFF ISLAS DEL GOLFO DE CALIFORNIA SONORA Y RB ISLA SAN PEDRO MÁRTIR.', 'ACTUALIZADA LA BASE DE DATOS DE LOS RECORRIDOS CON LA INFORMACIÓN AL MENOS DEL 70-80 % DE ACUERDO A LOS RECORRIDOS DE LA ANP APFF ISLAS DEL GOLFO DE CALIFORNIA SONORA Y RB ISLA SAN PEDRO MÁRTIR.', 'ACTUALIZADA LA BASE DE DATOS DE LOS RECORRIDOS CON LA INFORMACIÓN AL MENOS DEL 50 % DE ACUERDO A LOS RECORRIDOS DE LA ANP APFF ISLAS DEL GOLFO DE CALIFORNIA SONORA Y RB ISLA SAN PEDRO MÁRTIR.', '90', 'MANTENER ACTUALIZADA LA PLATAFORMA DE SIRCA EN EL TEMA DE LOS CONSEJOS ASESORES DE ANP APFF ISLAS DEL GOLFO DE CALIFORNIA SONORA Y RB ISLA S