INSERT INTO `sed_individuales` VALUES (300, 'LORG781102', 'SUPERVISAR, ASESORAR Y DAR SEGUIMIENTO ADMINISTRATIVO A LA OPERACIÓN Y EJECUCIÓN DE LOS PROGRAMAS DE SUBSIDIO EN 18 ÁREAS NATURALES PROTEGIDAS ADSCRITAS A LA DIRECCIÓN REGIONAL PLANICIE COSTERA Y GOLFO DE MÉXICO, DE ACUERDO CON LAS ATRIBUCIONES Y COMPETENCIA DE LA DIRECCIÓN REGIONAL Y CON BASE EN LA NORMATIVIDAD VIGENTE ESTABLECIDA.', '10', '60', '100% DE LOS PROGRAMAS SUPERVISADOS Y ASESORADOS Y DEL 90 AL 100% DE LOS EXPEDIENTES INTEGRADOS CONFORME A LA NORMATIVIDAD VIGENTE Y APLICABLE A LA DIRECCIÓN REGIONAL.', '100% DE LOS PROGRAMAS SUPERVISADOS Y ASESORADOS Y DEL 80 AL 89% DE LOS EXPEDIENTES INTEGRADOS CONFORME A LA NORMATIVIDAD VIGENTE Y APLICABLE A LA DIRECCIÓN REGIONAL.', '100% DE LOS PROGRAMAS SUPERVISADOS Y ASESORADOS Y MENOS DE 79% DE LOS EXPEDIENTES INTEGRADOS CONFORME A LA NORMATIVIDAD VIGENTE Y APLICABLE A LA DIRECCIÓN REGIONAL.', '90', 'COADYUVAR EN LA ATENCIÓN A SOLICITUDES DE INFORMACIÓN A LA DIRECCIÓN REGIONAL PLANICIE COSTERA Y GOLFO DE MÉXICO DE INSTANCIAS INTERNAS COMO EXTERNAS TALES COMO: PLATAFORMA DE ACCESO A LA INFORMACIÓN, OFICINAS CENTRALES DE CONANP, ENTRE OTRAS; SOLICITANDO LA INFORMACIÓN, EN SU CASO, COMPILANDO, REVISANDO Y ENVIANDO A LA INSTANCIA CORRESPONDIENTE.', '01', '15', '2 ACCIONES REALIZADAS.', '1 ACCIÓN REALIZADA.', 'NINGUNA ACCIÓN REALIZADA', '90', 'COADYUVAR EN LA INTEGRACIÓN DEL PROGRAMA OPERATIVO ANUAL (POA) DEL EJERCICIO FISCAL 2024 DE LA DIRECCIÓN REGIONAL EN LO CONCERNIENTE A LAS ACTIVIDADES REALIZADAS CON PROGRAMAS DE SUBSIDIO, ASÍ COMO PROPORCIONAR INFORMACIÓN PARA LA INTEGRACIÓN DE LOS INFORMES TRIMESTRALES Y MEDIOS DE VERIFICACIÓN QUE SE REGISTRAN EN EL SISTEMA GENERAL DE PROGRAMAS OPERATIVOS ANUALES (SGPOA).', '01', '10', 'APORTACIÓN DE INFORMACIÓN PARA EL POA 2024 Y 4 INFORMES TRIMESTRALES CON SUS RESPECTIVOS MEDIOS DE VERIFICACIÓN', 'APORTACIÓN DE INFORMACIÓN PARA EL POA 2024 Y 4 INFORMES TRIMESTRALES SIN MEDIOS DE VERIFICACIÓN', 'NINGUNA ACCIÓN REALIZADA', '90', 'ATENDER LAS AUDITORÍAS DIRIGIDAS A LOS PROGRAMAS DE SUBSIDIO DE CONFORMIDAD CON ATRIBUCIONES, RESPONSABILIDADES DE LA DIRECCIÓN REGIONAL PLANICIE COSTERA Y GOLFO DE MÉXICO POR LOS DIFERENTES ÓRGANOS FISCALIZADORES (AUDITORÍA SUPERIOR DE LA FEDERACIÓN, ÓRGANO INTERNO DE CONTROL, ENTRE OTROS.)', '01', '15', '100% DE LAS AUDITORÍAS ATENDIDAS', '90% DE LAS AUDITORÍAS ATENDIDAS', 'MENOS DEL 89% DE LAS AUDITORÍAS ATENDIDAS', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
