INSERT INTO `sed_individuales` VALUES (302, 'LOVA670312', 'DISEÑAR, IMPLEMENTAR Y EVALUAR LA PLANEACIÓN DEL PROGRAMA OPERATIVO ANUAL 2024, INCORPORANDO LAS ACCIONES DE MEJORA PROPUESTAS EN EL INFORME DE I-EFECTIVIDAD 2022, EL PROYECTO FANP Y EL PROYECTO COSMOS DEL PARQUE NACIONAL LAGUNAS DE ZEMPOALA Y EL AREA DESTINADA VOLUNTARIAMENTE PARA LA CONSERVACIÓN (ADVC) ATZINGO EN EL MUNICIPIO DE OCUILAN.', '04', '20', '100', '75', '50', '90', 'COORDINAR LAS ACCIONES PARA LA ATENCIÓN DE LA PROBLEMÁTICA DE LA TALA CLANDESTINA, INCENDIOS Y PLAGAS FORESTALES Y ESPECIES EXÓTICAS E INVASORAS EN EL PARQUE NACIONAL LAGUNAS DE ZEMPOALA Y SU ZONA DE INFLUENCIA ASÍ COMO EL ÁREA DESTINADA VOLUNTARIAMENTE PARA LA CONSERVACIÓN (ADVC) ATZINGO, CON LOS 3 ÓRDENES DE GOBIERNO EN LOS ESTADOS MORELOS Y ESTADO DE MÉXICO Y CON LA GUARDIA NACIONAL ESTABLECIDA EN ZEMPOALA, QUE PERMITAN REDUCIR EL IMPACTO A LOS ECOSISTEMAS FORESTALES Y ACUÁTICOS DEL PARQUE, ASÍ COMO A LAS ESPECIES PRIORITARIAS.', '04', '20', '100', '75', '50', '70', 'SUPERVISAR LA EJECUCIÓN DE LOS PROGRAMAS DE SUBSIDIOS QUE SE IMPLEMENTAN EN EL PARQUE NACIONAL LAGUNAS DE ZEMPOALA Y EL ÁREA DESTINADA VOLUNTARIAMENTE PARA LA CONSERVACIÓN (ADVC) ATZINGO EN LOS PROCESOS DE RESTAURACIÓN, VIGILANCIA Y MONITOREO COMUNITARIO, CONSERVACIÓN DE ESPECIES PRIORITARIAS, ASÍ COMO EN LOS PROCESOS PRODUCTIVOS CON LA PARTICIPACIÓN COMUNITARIA EN LOS ESTADOS DE MORELOS Y ESTADO DE MÉXICO.', '04', '20', '100', '75', '50', '70', 'ACTUALIZAR LA CÉDULA DE EFECTIVIDAD Y EL BORRADOR DEL PROGRAMA DE MANEJO DEL PARQUE NACIONAL LAGUNAS DE ZEMPOALA EN COORDINACIÓN Y ASESORÍA CON LA DIRECCIÓN REGIONAL CENTRO Y EJE NEOVOLCÁNICO Y LA DIRECCIÓN GENERAL DE CONSERVACIÓN DE OFICINAS CENTRALES.', '04', '20', '100', '75', '50', '70', 'CONCLUIR LA RESTRUCTURACIÓN DEL CONSEJO ASESOR DEL PARQUE NACIONAL LAGUNAS DE ZEMPOALA CON LA CONFORMACIÓN DE LOS SUBCONSEJOS FORESTAL, CAMBIO CLIMÁTICO Y TURISMO Y RECREACIÓN AL AIRE LIBRE EN EL PARQUE NACIONAL LAGUNAS DE ZEMPOALA.', '04', '20', '3', '2', '1', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
