INSERT INTO `sed_individuales` VALUES (307, 'MAAM810305', 'COORDINARSE CON LA DIRECCIÓN REGIONAL NOROESTE Y ALTO GOLFO DE CALIFORNIA COMO ENLACE ADMINISTRATIVO DEL ANP. CON LOS DEPARTAMENTOS DE RECURSOS HUMANOS, RECURSOS MATERIALES Y RECURSOS FINANCIEROS.', '01', '20', 'LA ANP ESTA COORDINADA CON LOS 3 DEPARTAMENTOS DE LA DIRECCIÓN REGIONAL.', 'LA ANP ESTA COORDINADA CON 1 DE LOS 3 DEPARTAMENTOS DE LA DIRECCIÓN REGIONAL.', 'LA ANP ESTA COORDINADA CON NINGUNO DE LOS 3 DEPARTAMENTOS DE LA DIRECCIÓN REGIONAL.', '90', 'RESPONSABLE ADMINISTRATIVO DEL COBRO DE DERECHOS DEL ANP.', '01', '20', 'REALIZAR LOS CORTES Y REPORTES DEL COBRO DE DERECHOS DEL ANP, DEPOSITO DEL INGRESO POR FORMAS VALORADAS, CARGA EN SISTEMA SICDE 2.0 LA INFORMACIÓN CORRESPONDIENTE A EL ANP.', 'REALIZAR LOS CORTES Y REPORTES DEL COBRO DE DERECHOS DEL ANP , SIN DEPOSITAR EN TIEMPO Y FORMA EL INGRESO POR FORMAS VALORADAS Y SU RESPECTIVA CARGA EN SISTEMA SICDE 2.0 LA INFORMACIÓN CORRESPONDIENTE A EL ANP.', 'NO REALIZAR LOS CORTES Y REPORTES DEL COBRO DE DERECHOS , ESTO SIEMPRE Y CUANDO SE CUENTE CON LAS FORMAS VALORADAS CORRESPONDIENTES Y CONDICIONES DE ACCESOS DEL ANP ABIERTOS.', '90', 'EJECUTAR EL GASTO LOS RECURSOS EXTERNOS FMCN FANP- POA 2024 DE ACUERDO A LA PLATAFORMA SESAMO DE ENDESU AC, CORRESPONDIENTES A EL ANP.', '04', '20', 'EJERCER LOS RECURSOS POA FANP 2024 ATENDIENDO LAS NECESIDADES EN RELACIÓN A LAS ACTIVIDADES DEL MARCO LOGICO Y POA ANUAL.', 'QUE NO SE ATIENDAN LAS NECESIDADES DEL ANP AL EJERCER LOS RECURSOS FANP POA 2024', 'NO EJERCER LOS RECURSOS FANP POA DEL ANP.', '90', 'RESPONSABLE DE ATENDER LAS NECESIDADES ADMINISTRATIVAS DEL CENTRO DE VISITANTES DEL ANP, SOLICITUDES DE RECURSOS, RECURSOS HUMANOS PERSONAL ENDESU SUBPROYECTO FANP, INFORMES SEMESTRALES DE PERSONAL , DEL SUBPROYECTO FANP-POA 2024 .', '04', '20', 'CUMPLIR CON LOS COMPROMISOS ADMINISTRATIVOS PARA LA OPERACIÓN DEL CENTRO DE VISITANTES DE CADA MES.', 'NO CUMPLIR CON LOS COMPROMISOS ADMINISTRATIVOS PARA LA OPERACIÓN DEL CENTRO DE VISITANTES DE CADA MES.', 'NO ATENDER LOS COMPROMISOS ADMINISTRATIVOS DEL CENTRO DE VISITANTES.', '90', 'COORDINAR ELABORACIÓN Y CARGA DE PROGRAMA OPERATIVO ANUAL FANP-FMCN (INCLUYE PRESUPUESTO) , COORDINADOR DE LA ELABORACIÓN DE REPORTES SEMESTRALES POA-FANP, (EN PLATAFORMA SISTEMA DE SEGUIMIENTO A PROYECTOS SISEP DEL FMCN).', '04', '20', 'ELABORACIÓN DE POA ANUAL ,REPORTES SEMESTRALES Y PRESUPUESTOS ANUALES.', 'NO CUMPLIR CON LAS LIBERACIONES ADMINISTRATIVAS CORRESPONDIENTES EN LA ELABORACIÓN DE POAS Y SUS REPORTES SEMESTRALES.', 'NO ELABORAR POA ANUAL Y SUS REPORTES SEMESTRALES.', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
