INSERT INTO `sed_individuales` VALUES (310, 'MACG771202', 'ELABORACIÓN DE SOLICITUDES DE PAGO(GASTOS FIJOS, PAGO A PROVEEDORES, ENTRE OTROS), ORDENES DE SERVICIOS/ COMPRAS,CAPTURA EN EL SISTEMA DE CONTABILIDAD Y PRESUPUESTO( SICOP) , REGISTRO,CONTROL DE GASTO POR PARTIDA DE LOS MISMOS DE ACUERDO AL POA DE LOS RECURSOS FINANCIEROS DEL ÁREA DE PROTECCIÓN DE FLORA Y FAUNA ISLAS DEL GOLFO DE CALIFORNIA SUR, SINALOA, APFF SANTUARIO PLAYA CUETA, APFF MESETA DE CACAXTLA , APFF SANTUARIO EL VERDE CAMACHO Y HUIZACHE PLAYA CAIMANERO', '08', '30', '100% AL 75%', '74% AL 50%', '49% AL 25%', '90', 'APOYO A FACTURAR DE PAGO MENSUAL DE IMPUESTOS SOBRE NOMINA DEL PERSONAL EN EL ESTADO DE SINALOA( MAZATLAN Y CULIACÁN, APOYO EN EL CONTROL, REGISTROS POR PARTIDA DEL GASTO DE OPERACIÓN, TRAMITE Y CAPTURA DE COMPROBACIONES DE VIATICOS EN EL SISTEMA DE CONTABILIDAD Y PRESUPUESTO( SICOP) EN PROCODES. DE LAS SIGUIENTES AREAS: ÁREA DE PROTECCIÓN DE FLORA Y FAUNA ISLAS DEL GOLFO DE CALIFORNIA SUR, SINALOA,SANTUARIO PLAYA CUETA, MESETA DE CACAXTLA Y SANTUARIO EL VERDE CAMACHO EN MAZATLÁN SINALOA, HUIZACHE PLAYA CAIMANERO', '04', '30', '100% AL 75%', '74% AL 50%', '49% AL 25%', '90', 'SOLICITAR COTIZACIONES A PROVEEDORES , CUESTIONARIOS DE ESTUDIOS DE MERCADOS PARA EL PROCESO DE LICITACIÓN, SOLICITUD DE FIANZA, RECABAR FIRMAS DE CONTRATO( MANTENIMIENTO DE VEHICULOS,MANTENIMIENTO DE SERVICIO DE LIMPIEZA, SERVICIO DE VIGILANCIA) Y COMPRAS DE O PRODUCTOS DE OTRAS PARTIDAS.', '04', '30', '100% AL 75%', '74% AL 50%', '49% AL 25%', '70', 'CAPTURAR EL ARTICULO Y FRACCION A VENDER EN FORMATO DE PAGO EN VENTANILLA REGISTRO DE E5CINCO SEMARNAT, LLENADO DE CONTROL DE CANJE DE BRAZALETES AL FORMATO DEL AÑO VIGENTE, IDA AL BANCO A PAGAR EN VENTANILLA, ESCANEO DE FORMATOS Y REGISTRO DE LA VENTA EN EL SICDE DE COBROS DE DERECHOS, DANDOLE SEGUIMIENTO HASTA QUE EN SISTEMA QUEDE CERTIFICAD PARA FINALLIZAR EL PROCESO DE LA VENTA.', '05', '5', '100% AL 75%', '74% AL 50%', '74% AL 50%', '70', 'APOYAR EN LLENADO DE