INSERT INTO `sed_individuales` VALUES (311, 'MACJ690810', 'ATENDER, DAR RESPUESTA Y SEGUIMIENTO A SOLICITUDES DE INFORMACIÓN DERIVADAS DE OFICINAS CENTRALES, ORGANIZACIONES DE LA SOCIEDAD CIVIL Y DEPENDENCIAS DE GOBIERNO FEDERAL, ESTATAL Y MUNICIPAL RELATIVAS A LAS ANP DE LA DIRECCIÓN REGIONAL.', '10', '30', 'SE ATENDIÓ MÁS DEL 90% DE LAS SOLICITUDES DE INFORMACIÓN', 'SE ATENDIÓ ENTRE EL 70 Y 90% DE LAS SOLICITUDES DE INFORMACIÓN', 'SE ATENDIÓ MENOS DEL 70% DE LAS SOLICITUDES DE INFORMACIÓN', '90', 'COADYUVAR CON LA DIRECCIÓN REGIONAL EN EL SEGUIMIENTO DE ÁREAS NATURALES PROTEGIDAS ADSCRITAS A ESTA REGIONAL, QUE NO CUENTEN CON UN TITULAR ASIGNADO A LA DIRECCIÓN DEL ANP.', '01', '15', 'ATENCIÓN DE 3 O MÁS ANP', 'ATENCIÓN DE 2 ANP', 'ATENCIÓN DE 1 ANP', '90', 'ATENDER LAS NECESIDADES DE LA DIRECCIÓN REGIONAL EN CUANTO A COMISIONES, INFORMES DE COMISIÓN, REUNIONES DE TEMAS ESTRATÉGICOS, MINUTAS DE REUNIONES, FIRMA DE OFICIOS Y ARCHIVO DE OFICIOS RECIBIDOS Y ENVIADOS.', '02', '30', 'SE ATENDIERON TODAS LAS NECESIDADES DE LA OFICINA DE LA DIRECCIÓN REGIONAL CON ALTA CALIDAD.', 'SE ATENDIERON TODAS LAS NECESIDADES DE LA OFICINA DE LA DIRECCIÓN REGIONAL CON MODERADA CALIDAD.', 'SE ATENDIERON TODAS LAS NECESIDADES DE LA OFICINA DE LA DIRECCIÓN REGIONAL CON MALA CALIDAD.', '90', 'SUPERVISAR EL CUMPLIMIENTO DE ACCIONES Y OBJETIVOS DE PERSONAL SINDICALIZADO QUE LABORA PARA LA OFICINA DE LA DIRECTORA REGIONAL.', '08', '5', 'SUPERVISA CON BUENA CALIDAD EL CUMPLIMIENTO DE ACCIONES Y OBJETIVOS', 'SUPERVISA CON MODERADA CALIDAD EL CUMPLIMIENTO DE ACCIONES Y OBJETIVOS', 'SUPERVISA CON MALA CALIDAD EL CUMPLIMIENTO DE ACCIONES Y OBJETIVOS', '70', 'REALIZAR ACCIONES RELACIONADAS CON LA CONSERVACIÓN, PROTECCIÓN Y MANEJO DE LOS SITIOS RAMSAR ADSCRITOS A LA DIRECCIÓN REGIONAL NOROESTE Y AGC, ASÍ COMO ATENDER SOLICITUDES DE INFORMACIÓN RELATIVAS A ESTE TEMA', '04', '20', 'SE REALIZARON 2 O MÁS ACCIONES Y/O GESTIONES ORIENTADAS A PROMOVER LA CONSERVACIÓN, PROTECCIÓN Y MANEJO DE LOS SITIOS RAMSAR ADSCRITOS A LA DIRECCIÓN REGIONAL.', 'SE REALIZARON 1 ACCIÓN Y/O GESTIONES ORIENTADAS A PROMOVER LA CONSERVACIÓN, PROTECCIÓN Y MANEJO DE LOS SITIOS RAMSAR ADSCRITOS A LA DIRECCIÓN REGIONAL.', 'SE REALIZARON 0 ACCIONES Y/O GESTIONES ORIENTADAS A PROMOVER LA CONSERVACIÓN, PROTECCIÓN Y MANEJO DE LOS SITIOS RAMSAR ADSCRITOS A LA DIRECCIÓN REGIONAL.', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (312, 'MAEG630324', 'VALIDAR EL PROCESO DE LA NÓMINA PARA GENERAR EL PAGO DE LAS REMUNERACIONES Y PRESTACIONES AL PERSONAL DE LA CONANP, DE ACUERDO AL CALENDARIO ESTABLECIDO.', '08', '50', 'EFECTUAR EL PAGO DE LAS REMUNERACIONES CON UN RANGO DEL 95 AL 100% DE TODOS LOS EMPLEADOS DE LA COMISIÓN, APLICANDO DE MANERA CORRECTA LOS MOVIMIENTOS E INCIDENCIAS QUE AFECTEN SUS PERCEPCIONES.', 'EFECTUAR EN UN RANGO DEL 90 AL 94% EL PAGO DE NÓMINA A LOS EMPLEADOS, POSPONIENDO DICHO PAGO DE NUEVOS INGRESOS Y OMITIENDO INCIDENCIAS O MOVIMIENTOS QUE PUEDAN CREAR RETROACTIVIDADES POR CAUSAS IMPUTABLES AL DEPARTAMENTO DE NÓMINA.', 'EFECTUAR EL PAGO DE NÓMINA A MENOS DEL 90% DE LOS EMPLEADOS, CON UNA DEFICIENCIA DE VALIDACIÓN DE INCIDENCIAS Y MOVIMIENTOS DE LOS CUALES PERJUDIQUEN EL SALARIO QUINCENAL DEL PERSONAL DE LA COMISIÓN.', '90', 'VALIDAR EL ENVÍO DE LA INFORMACIÓN PARA LOS TERCEROS INSTITUCIONALES CON EL FIN DE CUMPLIR CON LAS OBLIGACIONES LABORALES, FISCALES Y DE SEGURIDAD SOCIAL QUE CORRESPONDEN A LA CONANP.', '08', '15', 'CUMPLIR ANTE LAS INSTITUCIONES CORRESPONDIENTES DEL 95 AL 100% CON ÉL ENVIÓ DE LA INFORMACIÓN DE CADA QUINCENA GENERADA POR LAS APORTACIONES Y DESCUENTOS DE LOS EMPLEADOS DE LA COMISIÓN, ESTO CON EL FIN DE AGILIZAR CUALQUIER TRÁMITE QUE SOLICITEN LOS TRABAJADORES.', 'ENTREGAR LOS TERCEROS QUE SE GENERAN EN UNA QUINCENA, UN MES DESPUÉS DEL PAGO DE NÓMINA O HACERLO DE MANERA PARCIAL, CON UN PORCENTAJE DEL 90 AL 94% DEL ENVIÓ DE LA INFORMACIÓN.', 'OMITIR DE MANERA FRECUENTE EL ENVÍO DE LA INFORMACIÓN DE TERCEROS A LAS INSTITUCIONES CORRESPONDIENTES EN UN PORCENTAJE MENOR AL 90%, CAUSANDO EL PAGO DE RECARGOS A LA COMISIÓN.', '90', 'SUPERVISAR LA GENERACIÓN DE LOS COMPROBANTES ELECTRÓNICOS (CFDI) DE LOS PAGOS GENERADOS DE CADA QUINCENA PARA LOS EMPLEADOS DE LA CONANP DE ACUERDO A LA NORMATIVIDAD EMITIDA POR EL SAT, CONSIDERANDO QUE ES UN DOCUMENTO OBLIGATORIO PARA CUALQUIER TRAMITE.', '08', '20', 'EN UN RANGO DEL 95 AL 100% CUMPLIR CON LA GENERACIÓN Y ENVÍO DE LOS COMPROBANTES ELECTRÓNICOS (CFDI) EN LOS TIEMPOS ESTABLECIDOS.', 'EFECTUAR EN UN RANGO DEL 90 AL 94 EL TIMBRADO DE LOS COMPROBANTES ELECTRÓNICOS, FUERA DE LOS TIEMPOS ESTABLECIDOS.', 'EFECTUAR LA GENERACIÓN Y ENVÍO EN UN RANGO MENOR DEL 90% LOS COMPROBANTES ELECTRONICOS, OCASIONANDO RETRASO PARA LOS TRAMITES DEL PERSONAL DE LA CONANP.', '90', 'SUPERVISAR Y VALIDAR LA ACTUALIZACIÓN DE LA BASE DE DATOS DEL SISTEMA DE NÓMINA META4, CON LOS ARCHIVOS, CATÁLOGOS, TABULADORES, TABLAS DE IMPUESTOS E HISTÓRICOS DE SUELDOS DE ACUERDO A NORMAS Y LINEAMIENTOS ESTABLECIDOS POR LAS INSTITUCIONES CORRESPONDIENTES.', '08', '15', 'MANTENER ACTUALIZADO AL DÍA LOS CATÁLOGOS, TABULADORES Y TABLAS DE IMPUESTO PARA EFECTUAR EL PAGO CORRECTO DE LA NÓMINA, DE ACUERDO A LO ESTABLECIDO.', 'ACTUALIZAR 15 DÍAS POSTERIORES A LO ESTABLECIDO CATÁLOGOS Y TABULADORES, CAUSANDO PAGOS O DESCUENTOS RETROACTIVOS INNECESARIOS PARA LOS EMPLEADOS Y PARA LA COMISIÓN.', 'REALIZAR ACTUALIZACIONES UN MES O MÁS POSTERIOR AL TIEMPO ESTABLECIDO POR LAS INSTITUCIONES CORRESPONDIENTES, OCASIONANDO RECARGOS A LA COMISIÓN.', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
