INSERT INTO `sed_individuales` VALUES (314, 'MAGE930829', 'SUPERVISAR LAS ACCIONES QUE SE REALICEN DENTRO DEL ÁREA NATURAL PROTEGIDA SE AJUSTEN A LOS PROPÓSITOS DE LOS ORDENAMIENTOS LEGALES APLICABLES EN MATERIA DE PROTECCIÓN, MANEJO Y RESTAURACIÓN PARA LA CONSERVACIÓN DE LOS ECOSISTEMAS Y SU BIODIVERSIDAD.', '02', '40', '100 % AL 75 %', '74 % AL 50 %', '49 % AL 25 %', '90', 'PROMOVER EL DESARROLLO COMUNITARIO EN EL ÁREA EN LO RELATIVO A LOS PROGRAMAS DE SUBSIDIOS Y PROYECTOS DE CONSERVACIÓN PARA EL DESARROLLO Y DE MANEJO PARA EL USO DE APROVECHAMIENTO DE LOS ECOSISTEMAS Y SU BIODIVERSIDAD. RECIBIR SOLICITUDES E INTEGRAR LOS EXPEDIENTES PARA EL OTORGAMIENTO DE LICENCIAS, PERMISOS, AUTORIZACIONES Y CONCESIONES.', '02', '30', '100 % AL 75 %', '74 % AL 50 %', '49 % AL 25 %', '90', 'PARTICIPAR EN LOS PROGRAMAS, PROYECTOS Y ACCIONES DE ESPECIES Y POBLACIONES CONSIDERADAS COMO PRIORITARIAS PARA LA CONSERVACIÓN EN LAS ÁREAS NATURALES PROTEGIDAS DE SU COMPETENCIA. DIRIGIR Y EJECUTAR LOS PROGRAMAS PARA LA ATENCIÓN DE CONTINGENCIAS AMBIENTALES.', '02', '30', '100 % AL 75 %', '74 % AL 50 %', '49 % AL 25 %', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (315, 'MAGF780719', 'LLEVAR A CABO LAS ACCIONES PARA VERIFICAR QUE LAS ACTIVIDADES QUE SE REALICEN EN EL ÁREA PROTEGIDA SE AJUSTEN A LOS ORDENAMIENTOS LEGALES APLICABLES EN MATERIA DE CONSERVACIÓN DE LOS ECOSISTEMAS Y SU BIODIVERSIDAD.', '10', '20', 'LLEVAR A CABO LA VERIFICACIÓN DE LAS ACTIVIDADES EN EL 100-90% DEL ÁREA PROTEGIDA.', 'LLEVAR A CABO LA VERIFICACIÓN DE LAS ACTIVIDADES EN EL 89-70% DEL ÁREA PROTEGIDA.', 'LLEVAR A CABO LA VERIFICACIÓN DE LAS ACTIVIDADES EN EL 69-0% DEL ÁREA PROTEGIDA.', '90', 'INTEGRAR, CAPACITAR Y COORDINAR A BRIGADAS COMUNITARIAS Y/O COMITÉS DE VIGILANCIA PARTICIPATIVA INVOLUCRANDO A LAS COMUNIDADES LOCALES, PROPORCIONANDO LA CAPACITACIÓN SOBRE LA NORMATIVIDAD APLICABLE Y PROMOCIÓN DE SU ACREDITACIÓN.', '10', '20', 'INVOLUCRAR A 3 COMUNIDADES EN LAS BRIGADAS COMUNITARIAS Y/O LOS COMITÉS DE VIGILANCIA PARTICIPATIVA', 'INVOLUCRAR A 2 COMUNIDADES EN LAS BRIGADAS COMUNITARIAS Y/O LOS COMITÉS DE VIGILANCIA PARTICIPATIVA', 'INVOLUCRAR A 1 COMUNIDADES EN LAS BRIGADAS COMUNITARIAS Y/O LOS COMITÉS DE VIGILANCIA PARTICIPATIVA', '90', 'LLEVAR A CABO LAS ACCIONES PARA LA CONSERVACIÓN Y RECUPERACIÓN DE ESPECIES PRIORITARIAS Y EN RIESGO SEGÚN LA NOM-059-SEMARNAT-2010 EN EL ÁREA PROTEGIDA INVOLUCRANDO A LAS COMUNIDADES LOCALES.', '10', '20', 'LLEVAR A CABO EL 100-90% DE LAS ACCIONES PARA LA CONSERVACIÓN Y RECUPERACIÓN DE ESPECIES PRIORITARIAS Y EN RIESGO SEGÚN LA NOM-059-SEMARNAT-2010 EN EL ÁREA PROTEGIDA INVOLUCRANDO A LAS COMUNIDADES LOCALES.', 'LLEVAR A CABO EL 89-70% DE LAS ACCIONES PARA LA CONSERVACIÓN Y RECUPERACIÓN DE ESPECIES PRIORITARIAS Y EN RIESGO SEGÚN LA NOM-059-SEMARNAT-2010 EN EL ÁREA PROTEGIDA INVOLUCRANDO A LAS COMUNIDADES LOCALES.', 'LLEVAR A CABO EL 69-0% DE LAS ACCIONES PARA LA CONSERVACIÓN Y RECUPERACIÓN DE ESPECIES PRIORITARIAS Y EN RIESGO SEGÚN LA NOM-059-SEMARNAT-2010 EN EL ÁREA PROTEGIDA INVOLUCRANDO A LAS COMUNIDADES LOCALES.', '90', 'APOYAR A LA DIRECCIÓN DEL ANP EN LAS ACCIONES PARA L