INSERT INTO `sed_individuales` VALUES (325, 'MAUD880216', 'DAR APOYO A LA DIRECCIÓN DE LA RESERVA DE LA BIOSFERA ISLA GUADALUPE EN LAS ACCIONES PROGRAMADAS EN EL PROGRAMA OPERATIVO ANUAL 2024 (POA-2024), ATENDIENDO AL DECRETO DEL ÁREA NATURAL PROTEGIDA Y A SU PROGRAMA DE MANEJO Y SUPERVISIÓN DE CAMPO.', '05', '30', 'REALIZAR Y REPORTAR ACTIVIDADES DURANTE 5 DÍAS AL TRIMESTRE DEL 2024 DENTRO DE LA POLIGONAL DE LA RESERVA DE LA BIOSFERA ISLA GUADALUPE DE ACUERDO CON LAS ACCIONES PROGRAMADAS EN EL POA-2024.', 'REALIZAR Y REPORTAR ACTIVIDADES DURANTE 3 DÍAS AL TRIMESTRE DEL 2024 DENTRO DE LA POLIGONAL DE LA RESERVA DE LA BIOSFERA ISLA GUADALUPE DE ACUERDO CON LAS ACCIONES PROGRAMADAS EN EL POA-2024.', 'NO REALIZAR ALGUNA ACTIVIDAD DENTRO DE LA POLIOGONAL DE LA RESERVA DE LA BIOSFERA ISLA GUADALUPE DE ACUERDO CON LAS ACCIONES PROGRAMADAS EN EL POA-2024', '90', 'REALIZAR ACTIVIDADES DE SUPERVISIÓN EN LA RESERVA DE LA BIOSFERA ISLA GUADALUPE DURANTE EL 2024.', '05', '20', 'APOYAR EN LA IMPLEMENTACIÓN DE LOS OPERATIVOS DE SUPERVISIÓN A PARTIR DEL PRIMER TRIMESTRE DEL EJERCICIO 2024 EN LA RESERVA DE LA BIOSFERA ISLA GUADALUPE', 'APOYAR EN LA IMPLEMENTACIÓN DE LOS OPERATIVOS DE SUPERVISIÓN A PARTIR DEL TERCER TRIMESTRE DEL EJERCICIO 2024 EN LA RESERVA DE LA BIOSFERA ISLA GUADALUPE', 'NO APOYAR EN LA IMPLEMENTACIÓN DE LOS OPERATIVOS DE SUPERVISIÓN DURANTE EL EJERCICIO 2024 EN LA RESERVA DE LA BIOSFERA ISLA GUADALUPE', '90', 'DAR APOYO LOGÍSTICO A LA DIRECCIÓN DEL ÁREA NATURAL PROTEGIDA EN LA REALIZACIÓN DE CONFERENCIAS, REUNIONES Y TALLERES QUE REALICE LA RESERVA DE LA BIOSFERA ISLA GUADALUPE.', '01', '10', 'DAR APOYO LOGÍSTICO A LA DIRECCIÓN DE LA RESERVA Y LA FORMACIÓN DE EVIDENCIA (MINUTAS, LISTAS DE ASISTENCIA, FOTOGRAFÍAS, ETC.) DE 2 REUNIONES, CONFERENCIAS O TALLERES QUE SE REALICEN DURANTE EL 2024.', 'DAR APOYO LOGÍSTICO A LA DIRECCIÓN DE LA RESERVA Y LA FORMACIÓN DE EVIDENCIA (MINUTAS, LISTAS DE ASISTENCIA, FOTOGRAFÍAS, ETC.) DE 1 REUNIÓN, CONFERENCIA O TALLER QUE SE R