INSERT INTO `sed_individuales` VALUES (329, 'MAZM721224', 'DAR SEGUIMIENTO A LA EJECUCIÓN DE LOS PROGRAMAS DE SUBSIDIO MEDIANTE LA ASESORÍA, VERIFICACIÓN, INTEGRACIÓN Y REVISIÓN DE EXPEDIENTES EN APEGO A LAS REGLAS DE OPERACIÓN Y LINEAMIENTOS ESTABLECIDOS Y CON ELLO CONTRIBUIR AL CUMPLIMIENTO DE OBJETIVOS Y METAS INSTITUCIONALES EN LA DIRECCIÓN REGIONAL.', '06', '20', '80 A 100%', '60 A 79%', 'MENOR DE 60%', '90', 'REVISAR LA INFORMACIÓN BIOLÓGICA, GEOGRÁFICA Y SOCIAL DISPONIBLE DEL ANP PARA ANALIZAR LAS PROPUESTAS DE LOS PROYECTOS SOLICITADOS Y AUTORIZADOS, COMPATIBLES CON LAS ESTRATEGIAS DE MANEJO DEL ANP, ALINEADOS A LA NORMATIVIDAD AMBIENTAL VIGENTE.', '04', '20', '80 A 100%', '60 A 79%', 'MENOR DE 60%', '90', 'REALIZAR ACTIVIDADES ADMINISTRATIVAS, DE COORDINACIÓN DE PERSONAL OPERATIVO Y DE LOGÍSTICA, ASÍ COMO DE GESTIÓN DE RECURSOS MATERIALES, HUMANOS, TECNOLÓGICOS, FINANCIEROS Y/O JURÍDICOS QUE SE REQUIERAN, DENTRO DE SU ÁMBITO DE APLICACIÓN , ASEGURANDO EL CUMPLIMIENTO NORMATIVO Y LA CONSECUCIÓN DE LAS ACTIVIDADES Y LA ADECUADA OPERACIÓN DEL ANP Y LA DIRECCIÓN REGIONAL.', '06', '20', '80 A 100%', '60 A 79%', 'MENOR DE 60%', '90', 'LAS DEMÁS QUE LE CONFIERA Y/O INSTRUYA SU JEFE INMEDIATO, EL DIRECTOR DEL ANP, EL DIRECTOR REGIONAL, LA UNIDAD ADMINISTRATIVA, LA UNIDAD TÉCNICA O LA UNIDAD JURÍDICA DE LA DIRECCIÓN REGIONAL, ASÍ COMO LAS QUE SEÑALEN LAS DISPOSICIONES LEGALES Y REGLAMENTARIAS VIGENTES DENTRO DE SU ALCANCE Y MARCO DE ACTUACIÓN ORIENTADAS A ASEGURAR LA ADECUADA OPERACIÓN DEL ANP, DE LA DIRECCIÓN REGIONAL Y DE LA CONSERVACIÓN DEL MEDIO AMBIENTE.', '04', '20', '80 A 100%', '60 A 79%', 'MENOR DE 60%', '90', 'DAR SEGUIMIENTO A LAS ACTIVIDADES DE SUPERVISIÓN, INSPECCIÓN Y VIGILANCIA EN LA ANP ALINEADAS CON LA NORMATIVIDAD AMBIENTAL VIGENTE.', '04', '20', '80 A 100%', '60 A 79%', 'MENOR DE 60%', '100', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demost