INSERT INTO `sed_individuales` VALUES (346, 'MOCG831230', 'EJECUTAR EL PROTOCOLO DE MONITOREO DE MARIPOSA MONARCA (DANAUS PLEXIPPUS) MEDIANTE LA REALIZACIÓN DE RECORRIDOS EN CAMPO PARA LA UBICACIÓN, GEORREFERENCIACIÓN Y MEDICIÓN DE SUPERFICIE FORESTAL OCUPADA POR MARIPOSAS DURANTE EL PERIODO DE HIBERNACIÓN DENTRO Y FUERA DEL POLÍGONO DEL ÁREA NATURAL PROTEGIDA.', '07', '20', '1', '0.75', '0.5', '90', 'APLICAR EL PROTOCOLO DE MONITOREO COMUNITARIO DE CALIDAD DEL AGUA MEDIANTE 3 VISITAS DE CAMPO DE MANERA MENSUAL, PARA LA TOMA DE DATOS FISICOQUÍMICOS Y BACTERIOLÓGICOS EN DOS MICROCUENCAS DENTRO DE LA RESERVA DE LA BIOSFERA MARIPOSA MONARCA, ASÍ COMO EL EJECUTAR EL PROTOCOLO DE MONITOREO DEL AJOLOTE (AMBYSTOMA RIVULARE) DE MANERA TRIMESTRAL, LLEVANDO A CABO LAS METODOLOGÍAS DE OBSERVACIÓN Y CAPTURA EN DOS SITIOS CON PRESENCIA DENTRO DE LA RBMM.', '07', '20', '1', '0.75', '0.5', '90', 'RECIBIR SOLICITUDES, INTEGRAR EXPEDIENTES DE LOS PROGRAMAS DE PROTECCIÓN Y RESTAURACIÓN DE ECOSISTEMAS Y ESPECIES EN RIESGO (PROREST) Y DEL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE (PROCODES).', '07', '20', '1', '0.75', '0.5', '70', 'APOYO AL MONITOREO DE FAUNA SILVESTRE E IMPLEMENTAR ACCIONES PARA SU CONSERVACIÓN.', '07', '20', '1', '0.75', '0.5', '70', 'APOYO A LA DIRECCIÓN PARA EL SEGUIMIENTO DE LOS PROGRAMAS PARA ATENDER AMENAZA POR LA POSIBLE PRESENCIA DE PLAGAS, CONTINGENCIAS AMBIENTALES Y MANEJO DEL FUEGO EN LA RESERVA DE LA BIOSFERA MARIPOSA MONARCA Y SUS ZONAS DE INFLUENCIA.', '07', '20', '1', '0.75', '0.5', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será