INSERT INTO `sed_individuales` VALUES (349, 'MOGS891101', 'COMPILAR Y ANALIZAR INFORMACIÓN DE ESPECIES EN RIESGO DE FLORA Y FAUNA DE LA RESERVA, PARA LA GENERACIÓN DE BASES DE DATOS ASÍ COMO SISTEMATIZAR LA INFORMACIÓN COMO UNA HERRAMIENTA DE MANEJO DE LA BIODIVERSIDAD; ADEMÁS DE MONITOREAR Y EVALUAR LOS CAMBIOS DE USO DE SUELO Y VEGETACIÓN MEDIANTE LOS SISTEMAS DE INFORMACIÓN GEOGRÁFICA.', '10', '30', '80 A 100', '60 A 79', '59 O MENOS DE 59', '90', 'CONTRIBUIR EN EL DISEÑO Y OPERACIÓN DE LA ESTRATEGIA DE EDUCACIÓN PARA LA CONSERVACIÓN Y COMUNICACIÓN SOCIAL, CON LA FINALIDAD DE SENSIBILIZAR A LOS USUARIOS Y HABITANTES DE LA ZONA DE INFLUENCIA DE LA RESERVA.', '10', '30', '80 A 100', '60 A 79', '59 O MENOS DE 59', '90', 'EJECUTAR ACTIVIDADES ADMINISTRATIVAS Y DE LOGÍSTICA, ASÍ COMO LA GESTIÓN DE RECURSOS MATERIALES, HUMANOS, TECNOLÓGICOS, FINANCIEROS Y/O JURÍDICOS, QUE SE REQUIERAN DENTRO DE SU ÁMBITO DE APLICACIÓN ASEGURANDO EL CUMPLIMIENTO NORMATIVO Y LA CONSECUCIÓN DE LAS ACTIVIDADES Y LA ADECUADA OPERACIÓN DEL ANP Y LA DIRECCIÓN REGIONAL.', '10', '20', '80 A 100', '60 A 79', '59 O MENOS DE 59', '90', 'LA DEMÁS QUE LE CONFIERA Y/O INSTRUYA SU JEFE INMEDIATO, EL DIRECTOR DEL ANP, EL DIRECTOR REGIONAL, LA UNIDAD ADMINISTRATIVA, LA UNIDAD TÉCNICA O LA UNIDAD JURÍDICA DE LA DIRECCIÓN REGIONAL, ASÍ COMO LAS QUE SEÑALEN LAS DISPOSICIONES LEGALES Y REGLAMENTARIAS VIGENTES DENTRO DE SU ALCANCE Y MARCO DE ACTUACIÓN ORIENTADAS A ASEGURAR LA ADECUADA OPERACIÓN DEL ANP, DE LA DIRECCIÓN REGIONAL Y DE LA CONSERVACIÓN DEL MEDIO AMBIENTE.', '10', '20', '80 A 100', '60 A 79', '59 O MENOS DE 59', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
