INSERT INTO `sed_individuales` VALUES (358, 'MOQS710926', 'ELABORAR EL PROGRAMA OPERATIVO ANUAL EN CONJUNTO CON EQUIPO DE TRABAJO DEL APRN LA FRAILESCANA, INCORPORANDO DE FORMA TRASVERSAL EL TEMA DE GÉNERO, ESTABLECIENDO LAS LÍNEAS PRIORITARIAS DE MANEJO, CONSERVACIÓN Y LAS METAS A CUMPLIR, ASÍ COMO LA REALIZACIÓN DE 4 EVALUACIONES TRIMESTRALES A TRAVÉS DE LA PLATAFORMA SGPOA.', '10', '20', 'SE IMPLEMENTAN AL 100% DE LAS METAS PLANTEADAS EN EL POA', 'SE IMPLEMENTAN AL 90% DE LAS METAS PLANTEADAS EN EL POA', 'SE IMPLEMENTAN AL 80% DE LAS METAS PLANTEADAS EN EL POA', '90', 'REALIZAR REUNIONES DE CARÁCTER INTERINSTITUCIONAL CON EL SECTOR AMBIENTAL A NIVEL FEDERAL, ESTATAL Y MUNICIPAL; ASÍ COMO ORGANIZACIONES DE LA SOCIEDAD CIVIL PARA LOGRAR LA COORDINACIÓN EN DESARROLLO DE ACCIONES Y ESTRATEGIAS PARA LA CONSERVACIÓN DEL APRN FRAILESCANA.', '01', '20', 'PARTICIPAR EN 7 REUNIONES INTERINSTITUCIONALES Y SE ESTABLECEN ACUERDOS PARA BENEFICIO DEL ANP', 'PARTICIPAR EN 5 REUNIONES INTERINSTITUCIONALES Y SE ESTABLECEN ACUERDOS PARA BENEFICIO DEL ANP', 'PARTICIPAR EN 2 REUNIONES INTERINSTITUCIONALES Y SE ESTABLECEN ACUERDOS PARA BENEFICIO DEL ANP', '90', 'PROMOVER LA PARTICIPACIÓN SOCIAL PARA EL DISEÑO Y EVALUACIÓN DE LAS ACCIONES DE CONSERVACIÓN, MEDIANTE LA REALIZACIÓN DE DOS REUNIONES DE CONSEJO ASESOR QUE INVOLUCRAN ACTORES DE LA ACADEMIA, LAS LOCALIDADES, LAS INSTITUCIONES Y LA SOCIEDAD CIVIL DEL APRN LA FRAILESCANA.', '01', '20', 'DOS REUNIONES DEL CONSEJO ASESOR CON EL ESTABLECIMIENTO DE ACUERDOS DE TRABAJO.', 'UNA REUNIÓN DEL CONSEJO ASESOR CON EL ESTABLECIMIENTO DE ACUERDOS DE TRABAJO.', 'NO SE REALIZAN REUNIONES DEL CONSEJO ASESOR CON EL ESTABLECIMIENTO DE ACUERDOS DE TRABAJO.', '90', 'REALIZAR REUNIONES CON LAS COMUNIDADES Y EJIDOS ESTABLECIDOS LEGALMENTE DENTRO Y EN LA ZONA DE INFLUENCIA DEL APRN FRAILESCANA, ESTABLECIENDO ACUERDOS PARA EL DESARROLLO DE PROYECTOS EN TEMAS DE INCENDIOS FORESTALES, VIGILANCIA COMUNITARIA Y DESARROLLO SUSTENTABLE.', '01', '20', '20 REUNIONES COMUNITARIAS REALIZADAS', '10 REUNIONES COMUNITARIAS REALIZADAS', '5 REUNIONES COMUNITARIAS REALIZADAS', '90', 'DESARROLLAR PROYECTOS DE DESARROLLO COMUNITARIO QUE PERMITAN LA UTILIZACIÓN RACIONAL DE LOS RECURSOS NATURALES Y REDUCIR LOS IMPACTOS SOBRE LOS ECOSISTEMAS, A LA VEZ QUE SE GENERAN OPCIONES ECONÓMICAS PARA LOS POBLADORES LOCALES.', '01', '20', '17 PROYECTOS COMUNITARIOS CON TÉCNICAS AGROECOLÓGICAS APLICADOS', '12 PROYECTOS COMUNITARIOS CON TÉCNICAS AGROECOLÓGICAS APLICADOS', '10 PROYECTOS COMUNITARIOS CON TÉCNICAS AGROECOLÓGICAS APLICADOS', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
