INSERT INTO `sed_individuales` VALUES (375, 'NUGL831026', 'RECEPCIÓN, TURNO Y ENVÍO DE RESPUESTA DE LAS SOLICITUDES DE ACCESO A LA INFORMACIÓN RECIBIDAS A TRAVÉS DE LA PLATAFORMA NACIONAL DE TRANSPARENCIA.', '07', '20', 'ENVIAR A TRAVÉS DE LA PLATAFORMA NACIONAL DE TRANSPARENCIA EN UN TÉRMINO DE 20 DÍAS HÁBILES CONTADOS A PARTIR DE LA RECEPCIÓN DE LAS SOLICITUDES, LA RESPUESTA QUE CORRESPONDA.', 'ENVIAR A TRAVÉS DE LA LA PLATAFORMA NACIONAL DE TRANSPARENCIA EN UN TÉRMINO MAYOR DE 20 DÍAS HÁBILES CONTADOS A PARTIR DE LA RECEPCIÓN DE LAS SOLICITUDES, LA RESPUESTA QUE CORRESPONDA.', 'NO ENVIAR LAS RESPUESTAS A LAS SOLICITUDES INGRESADAS A TRAVÉS DE LA PLATAFORMA NACIONAL DE TRANSPARENCIA.', '90', 'ATENCIÓN A LOS RECURSOS DE REVISIÓN DERIVADOS DE LAS RESPUESTAS A LAS SOLICITUDES DE ACCESO A LA INFORMACIÓN.', '07', '20', 'ENVIAR A TRAVÉS DEL SISTEMA DE HERRAMIENTA DE COMUNICACIÓN DEL INAI EN UN TÉRMINO DE 7 DÍAS HÁBILES CONTADOS A PARTIR DE LA RECEPCIÓN DE LAS SOLICITUDES, LOS ALEGATOS CORRESPONDIENTES.', 'ENVIAR A TRAVÉS DEL SISTEMA DE HERRAMIENTA DE COMUNICACIÓN DEL INAI EN UN TÉRMINO MAYOR DE 7 DÍAS HÁBILES CONTADOS A PARTIR DE LA RECEPCIÓN DE LAS SOLICITUDES, LOS ALEGATOS CORRESPONDIENTES.', 'NO ENVIAR LOS ALEGATOS CORRESPONDIENTES.', '90', 'ELABORAR RESPUESTAS DE CUMPLIMIENTO A LAS RESOLUCIONES RECAÍDAS A LOS RECURSOS DE REVISIÓN, EMITIDAS POR EL INSTITUTO NACIONAL DE TRANSPARENCIA, ACCESO A LA INFORMACIÓN Y PROTECCIÓN DE DATOS PERSONALES (INAI).', '07', '20', 'ENVIAR A TRAVÉS DEL SISTEMA DE HERRAMIENTA DE COMUNICACIÓN DEL INAI EN UN TÉRMINO DE 10 DÍAS HÁBILES CONTADOS A PARTIR DE LA RECEPCIÓN DEL REQUERIMIENTO, EL CUMPLIMIENTO A LA RESOLUCIÓN CORRESPONDIENTE.', 'ENVIAR A TRAVÉS DEL SISTEMA DE HERRAMIENTA DE COMUNICACIÓN DEL INAI EN UN TÉRMINO MAYOR A 10 DÍAS HÁBILES CONTADOS A PARTIR DE LA RECEPCIÓN DEL REQUERIMIENTO, EL CUMPLIMIENTO A LA RESOLUCIÓN CORRESPONDIENTE.', 'NO REALIZAR EL CUMPLIMIENTO A LA RESOLUCIONES CORRESPONDIENTES.', '90', 'EMITIR RESPUESTA A LOS REQUERIMIENTOS DEL INSTITUTO NACIONAL DE TRANSPARENCIA, ACCESO A LA INFORMACIÓN Y PROTECCIÓN DE DATOS PERSONALES (INAI).', '07', '20', 'DAR CUMPLIMIENTO A LOS REQUERIMIENTOS DEL INAI EN EL TIEMPO SOLICITADO.', 'DAR CUMPLIMIENTO A LOS REQUERIMIENTOS DEL INAI EN UN TIEMPO MAYOR AL SOLICITADO.', 'NO DAR CUMPLIMIENTO A LOS REQUERIMIENTOS DEL INAI', '90', 'REALIZAR LAS ACCIONES CORRESPONDIENTES PARA LA ACTUALIZACIÓN DEL SISTEMA DE ÍNDICE DE EXPEDIENTES RESERVADOS.', '07', '20', 'INFORMAR AL INAI LA ACTUALIZACIÓN DEL ÍNDICE DE EXPEDIENTES RESERVADOS DURANTE LOS PRIMERO DIEZ DÍAS HÁBILES DE LOS MESES DE ENERO Y JULIO DE 2024.', 'INFORMAR AL INAI LA ACTUALIZACIÓN DEL ÍNDICE DE EXPEDIENTES RESERVADOS FUERA DEL TÉRMINO PREVISTO POR EL REGLAMENTO DE LA LEY FEDERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA.', 'NO REALIZAR LAS ACCIONES CORRESPONDIENTES A LA ACTUALIZACIÓN DEL SISTEMA DE ÍNDICE DE EXPEDIENTES RESERVADOS.', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (376, 'NACA860108', 'REVISAR Y ANALIZAR LAS OBRAS Y/O ACCIONES CONTENIDAS EN LAS MANIFESTACIONES DE IMPACTO AMBIENTAL (MIA) QUE SE ENVÍAN PARA OPINIÓN TÉCNICA DE CONANP, REALIZANDO LA VERIFICACIÓN EN CAMPO Y ELABORANDO LAS PROPUESTAS DE OPINIONES TÉCNICAS CORRESPONDIENTES.', '10', '50', 'SE REVISÓ Y ANALIZÓ EL 100-90% DE LAS MIA RECIBIDAS, ELABORANDO LAS PROPUESTAS DE OPINIONES TÉCNICAS EN TIEMPO.', 'SE REVISÓ Y ANALIZÓ EL 89-71% DE LAS MIA RECIBIDAS, ELABORANDO LAS PROPUESTAS DE OPINIONES TÉCNICAS', '\"SE REVISÓ Y ANALIZÓ EL 70-0% DE LAS MIA RECIBIDAS, ELABORANDO LAS PROPUESTAS DE OPINIONES TÉCNICAS. \"', '90', '\"RECIBIR LAS SOLICITUDES E INTEGRAR LOS EXPEDIENTES PARA EMITIR OPINIONES TÉCNICAS SOBRE LAS SOLICITUDES PARA EL OTORGAMIENTO DE CONCESIONES EN MATERIA DE ZONA FEDERAL MARÍTIMO TERRESTRE, REALIZANDO LA VERIFICACIÓN EN CAMPO Y ELABORANDO LAS PROPUESTAS DE OPINIONES TÉCNICAS CORRESPONDIENTES. \"', '10', '20', 'SE REVISÓ Y ANALIZÓ EL 100-90% DE LAS SOLICITUDES DE ZONA FEDERAL RECIBIDAS, ELABORANDO LAS PROPUESTAS DE OPINIONES TÉCNICAS EN TIEMPO Y FORMA.', 'SE REVISÓ Y ANALIZÓ EL 89-71% DE LAS SOLICITUDES DE ZONA FEDERAL RECIBIDAS, ELABORANDO LAS PROPUESTAS DE OPINIONES TÉCNICAS EN TIEMPO Y FORMA', 'SE REVISÓ Y ANALIZÓ EL 70-0% DE LAS SOLICITUDES DE ZONA FEDERAL RECIBIDAS, ELABORANDO LAS PROPUESTAS DE OPINIONES TÉCNICAS EN TIEMPO Y FORMA', '90', '\"APOYAR EN VIGILAR QUE EN LOS INMUEBLES UBICADOS EN LA ZFMT Y PLAYA MARÍTIMA, OTORGADOS EN DESTINO EN EL ANP SE REALICEN LOS USOS QUE SEAN COMPATIBLES CON SUS OBJETIVOS, ASÍ COMO DAR SEGUIMIENTO A LAS SOLICITUDES DE ACUERDOS DE DESTINO EN TRÁMITE. \"', '01', '20', '\"SE APOYÓ VIGILAR Y/O DAR SEGUIMIENTO A 5-4 ADD OTORGADOS Y/O EN TRÁMITE EN EL ANP Y QUE LOS USOS QUE SEAN COMPATIBLES CON SUS OBJETIVOS \"', '\"SE APOYÓ VIGILAR Y/O DAR SEGUIMIENTO A 3-2 ADD OTORGADOS Y/O EN TRÁMITE EN EL ANP Y QUE LOS USOS QUE SEAN COMPATIBLES CON SUS OBJETIVOS \"', '\"SE APOYÓ VIGILAR Y/O DAR SEGUIMIENTO A 1-0 ADD OTORGADOS Y/O EN TRÁMITE EN EL ANP Y QUE LOS USOS QUE SEAN COMPATIBLES CON SUS OBJETIVOS \"', '90', '\"REALIZAR RECORRIDOS EN LAS ISLAS PARA: GEORREFERENCIACIÓN DE PREDIOS DONDE EXISTAN PROBABLES ACTIVIDADES IRREGULARES Y/O APOYAR EN LAS ACTIVIDADES DE SUPERVISIÓN EN TEMPORADAS DE ALTA VISITA. \"', '01', '10', 'REALIZAR DE 5-4 RECORRIDOS PARA LA GEORREFERENCIACIÓN DE PREDIOS DONDE EXISTAN PROBABLES ACTIVIDADES IRREGULARES Y/O APOYAR EN LAS ACTIVIDADES DE SUPERVISIÓN EN TEMPORADAS DE ALTA VISITA.', '\"REALIZAR DE 3-2 RECORRIDOS PARA LA GEORREFERENCIACIÓN DE PREDIOS DONDE EXISTAN PROBABLES ACTIVIDADES IRREGULARES Y/O APOYAR EN LAS ACTIVIDADES DE SUPERVISIÓN EN TEMPORADAS DE ALTA VISITA. \"', '\"REALIZAR DE 1-0 RECORRIDOS PARA LA GEORREFERENCIACIÓN DE PREDIOS DONDE EXISTAN PROBABLES ACTIVIDADES IRREGULARES Y/O APOYAR EN LAS ACTIVIDADES DE SUPERVISIÓN EN TEMPORADAS DE ALTA VISITA. \"', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
