INSERT INTO `sed_individuales` VALUES (380, 'OEBB750720', 'ACTUALIZAR LAS ESTADÍSTICAS, BASES DE DATOS, DIRECTORIOS, MAPAS, HERRAMIENTAS, EQUIPOS Y OTROS MATERIALES E INSUMOS REQUERIDOS PARA EL COMBATE DE INCENDIOS FORESTALES, EN EL PROGRAMA DE MANEJO DEL FUEGO PARA EL APFF CUATROCIÉNEGAS, ADEMÁS DE DARLO A CONOCER Y COMPARTIRLO CON LAS DEPENDENCIAS Y PERSONAL ENCARGADO DEL MANEJO DEL FUEGO.', '04', '25', 'UN DOCUMENTO ACTUALIZADO Y COMPARTIDO AL 100%.', 'UN DOCUMENTO ACTUALIZADO Y COMPARTIDO AL 80%.', 'UN DOCUMENTO CON MENOS DEL 80% DE ACTUALIZACIÓN Y NO COMPARTIDO.', '90', 'DESARROLLAR Y ACTIVAR EL SISTEMA DE COMANDO DE INCIDENTES EN EL COMBATE DE INCENDIOS FORESTALES DEL APFF CUATROCIENEGAS.', '01', '25', 'UN DOCUMENTO DEL SISTEMA DE COMANDO DE INCIDENTES DESARROLLADO Y ACTIVADO EN EL COMBATE DE INCENDIOS FORESTALES, INTEGRANDO UNA GUÍA QUE CONTENGA LA ESTRATEGIA, FUNCIONES Y RESPONSABILIDADES DE CADA DEPARTAMENTO Y SU RESPONSABLE.', 'UN SISTEMA DE COMANDO DE INCIDENTES DESARROLLADO Y ACTIVADO AL 80%.', 'NO SE APLICA EL SISTEMA DE COMANDO DE INCIDENTES EN EL CONTROL DE INCENDIOS FORESTALES.', '90', 'CAPACITAR Y REALIZAR INTERCAMBIOS DE EXPERIENCIAS CON LAS BRIGADAS COMUNITARIAS PARA EL COMBATE DE INCENDIOS FORESTALES.', '04', '25', '2 EVENTOS DE CAPACITACIÓN O VISITAS DE INTERCAMBIO DE EXPERIENCIAS A LA BRIGADA COMUNITARIA DE INCENDIOS FORESTALES.', '1 EVENTOS DE CAPACITACIÓN O VISITAS DE INTERCAMBIO DE EXPERIENCIAS A LA BRIGADA COMUNITARIA DE INCENDIOS FORESTALES.', 'NO EXISTEN EVENTOS.', '90', 'MANTENER ACTUALIZADA LA BASE DE DATOS DEL SISTEMA DEL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE Y BASES DE DATOS COMPLEMENTARIAS CON INFORMACIÓN DE LOS PROCODES, TALES COMO INVERSIONES, COORDENADAS GEOGRÁFICAS, NÚMERO DE BENEFICIARIOS Y LOCALIDADES; ADEMAS DE LOGRAR LA PARTICIPACIÓN DE LA MUJER.', '04', '25', '1 BASE DE DATOS ACTUALIZADA DONDE PARTICIPE AL MENOS EL 35% DE MUJERES.', '1 BASE DE DATOS ACTUALIZADA AL 80% DONDE PARTICIPE AL MENOS EL 25% DE MUJER