INSERT INTO `sed_individuales` VALUES (385, 'OEMV590517', 'ADMINISTRAR, COORDINAR, SUPERVISAR Y CONTROLAR LOS RECURSOS HUMANOS, FINANCIEROS, MATERIALES E INFORMATICOS DE LA DIRECCIÓN REGIONAL OCCIDENTE Y PACIFICO CENTRO Y SUS AREAS NATURALES PROTEGIDAS, CON BASE DISPOSICIONES DE AUSTERIDAD REPUBLICANA Y DISCIPLINA PRESUPUESTARIA.', '05', '20', 'DAR LA ATENCIÓN Y APOYO A UN 95% DE LAS ÁREAS NATURALES PROTEGIDAS ASI COMO DE LA OFICINA REGIONAL', 'DAR LA ATENCIÓN Y APOYO A UN 80% DE LAS ÁREAS NATURALES, ASÍ COMO DE LA OFICINA REGIONAL', 'DAR ATENCION Y APOYO A UN 65% DE LAS AREAS NATURALES, ASÍ COMO DE LA OFICINA REGIONAL', '90', 'ADMINISTRAR Y SUPERVISAR LA SISTEMATIZACIÓN Y ANALISIS DE LA INFORMACIÓN PROGRAMATICA PRESUPUESTAL Y FINANCIERA DE LA DROPC Y LAS ÁREAS NATURALES PROTEGIDAS, ASÍ COMO LA GESTIÓN ANTE OFICINAS CENTRALES DE LA AUTORIZACIÓN, ASIGNACIÓN Y MODIFICACIÓN DE PRESUPUESTO DEL GASTO.', '03', '20', 'QUE SE REFREJE UN 95% DEL PRESUPUESTO EJERCIDO CONTRA EL AUTORIZADO.', 'QUE SE REFLEJE UN 85% DEL PRESUPUESTO EJERCIDO CONTRA EL AUTORIZADO', 'QUE SE GENEREN SUBEJERCICIOS POR NO EJERCER EN TIEMPO Y FORMA LOS RECUROS PRESUPUESTALES', '90', 'COORDINAR Y SUPERVISAR LA CORRECTA ADMINISTRACIÓN DE LOS BIENES MUEBLES E INMUEBLES, ASÍ COMO BRINDAR EL APOYO EN EL MANTENIMIENTO PREVENTIVO Y CORRECTIVO DE LOS BIENES MUEBLES DE LA DROPC Y SUS ANP´S ASÍ LA DICTAMINACIÓN DE BAJAS, DONACIONES Y TRASPASOS ETC.', '04', '20', 'QUE LA COORDINACION Y SUPERVISIÓN SE DE POR LO MENOS EN UN 95% DE LOS BIENES MUEBLES E INMUEBLES PARA SU BUEN FUNCIONAMIENTO', 'QUE LA COORDINANCIÓN Y SUPERVISIÓN SE DE POR LO MENOS A UN 85% DE LOS BIENES MUEBLES E INMUEBLES PARA SU BUEN FUNCIONAMIENTO', 'QUE LA COORDINACION Y SUPERVISION NO SE DE EN TIEMPO Y FORMA Y EL PORCENTAJE SEA INFERIOR AL 70%', '90', 'OTORGAR UNA ASESORÍA ADMINISTRATIVA EFICIENTE A LAS ANP´S PARA LA BUENA OPERACIÓN DE LA MISMA.', '04', '20', 'QUE LAS ASESORÍAS QUE SE DEN A LAS ANP´S SEAN DE UTILIDAD PARA EL BUEN FUNCIONAMIENTO ADMINISTRATIVO Y OPERATIVO LOGRANDO POR LO MENOS EL 95% DE APOYO', 'QUE LAS ASESORÍAS QUE SE DEN A LAS ANP´S SEA DE UTILIDAD PARA EL BUEN FUNCIONAMIENTO ADMINISTRATIVO Y OPERATIVO Y NO SE LOGRE POR LO MENOS EL 80% DE APOYO', 'QUE NO SE DEN ASESORIAS DE CALIDAD EN TIEMPO Y FORMA A LA SANP´S, Y NO APOYAR EN EL BUEN FUNCIONAMIENTO DE LAS MISMAS', '90', 'ADMINISTRAR, SUMINISTRAR Y OTORGAR DE FORMA EFICIENTE LOS BIENES Y SERVICIÓS GENERALES A LAS ANP´S PARA QUE LLEVEN A CABO SUS OBJETIVOS Y METAS.OPEREATIVAS.', '03', '20', 'QUE EL ORTORGAMIENTO DE LOS BIENES Y SERVICIOS GENERALES SEAN EFICIENTES EN UN 100% PARA EL BUEN FUNCIONAMIENTO DE LA ANP´S Y EL LOGRO DE SUS OBJETIVOS', 'QUE LAS ASESORÍAS QUE SE DEN A LAS ANP´S SEA DE UTILIDAD PARA EL BUEN FUNCIONAMIENTO ADMINISTRATIVO Y OPERATIVO Y SE LOGRE SOLO EL 80% DE APOYO', 'QUE LAS ASESORÍAS QUE SE DEN A LAS ANP´S SEA DE UTILIDAD PARA EL BUEN FUNCIONAMIENTO ADMINISTRATIVO Y OPERATIVO, PERO NO SE APOYE EFICNTEMENTE Y SOLO SE OGRE EL 60% DEL APOYO', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (386, 'OEOL710720', 'GESTIONAR LAS SUFICIENCIAS PRESUPUESTALES, ADECUACIONES, Y MOVIMIENTOS DE CALENDARIO DEL PRESUPUESTO ASIGNADO A LA DIRECCIÓN, CON LA FINALIDAD DE ATENDER LAS NECESIDADES PRESUPUESTARIAS EN CUMPLIMIENTO A SUS FUNCIONES Y EJERCER LOS RECURSOS FINANCIEROS EN EL TIEMPO ESTABLECIDO.', '07', '30', 'CUMPLIR CON EL 100% AL 95% DE LAS ACTIVIDADES', 'CUMPLIR CON EL 94% AL 90% DE LAS ACTIVIDADES', 'CUMPLIR CON EL 89% AL 85% DE LAS ACTIVIDADES', '90', 'TRAMITAR VIÁTICOS Y PASAJES NACIONALES E INTERNACIONALES PARA EL PERSONAL ADSCRITO A LA DIRECCIÓN, CON BASE EN LA NORMATIVIDAD Y PROCEDIMIENTOS ESTABLECIDOS POR LA LEGISLACIÓN VIGENTE EN LA MATERIA.', '07', '30', 'CUMPLIR CON EL 100% AL 95% DE LAS ACTIVIDADES', 'CUMPLIR CON EL 94% AL 90% DE LAS ACTIVIDADES', 'CUMPLIR CON EL 89% AL 85% DE LAS ACTIVIDADES', '90', 'RECABAR INFORMACIÓN DEL PERSONAL DE ESTRUCTURA DE LA DIRECCIÓN, CON LA FINALIDAD DE DAR CUMPLIMIENTO A TODOS LOS REQUERIMIENTOS SOLICITADOS POR EL ÁREA DE RECURSOS HUMANOS.', '07', '40', 'CUMPLIR CON EL 100% AL 95% DE LAS ACTIVIDADES', 'CUMPLIR CON EL 94% AL 90% DE LAS ACTIVIDADES', 'CUMPLIR CON EL 89% AL 85% DE LAS ACTIVIDADES', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (387, 'OIEC830815', 'REALIZAR RECORRIDOS DE VIGILANCIA Y COADYUVAR CON PERSONAL DE PROFEPA EN LAS ACCIONES DE DETECCIÓN, ATENCIÓN Y SEGUIMIENTO DE DELITOS AMBIENTALES QUE SE DETECTEN DENTRO DEL ÁREA NATURAL PROTEGIDA', '10', '20', '81 A 90%', '71 A 80 %', '0 A 70%', NULL, 'IMPLEMENTAR Y EJECUTAR EL PROGRAMA DE ERRADICACIÓN DE ESPECIES EXÓTICAS DENTRO DEL ANP EN COORDINACIÓN CON OTRAS INSTITUCIONES DEL SECTOR.', '10', '20', '81 A 90%', '71 A 80 %', '0 A 70%', NULL, 'RECIBIR SOLICITUDES DE PERMISOS Y AUTORIZACIONES, ASÍ COMO SUS PRORROGAS, SUSTITUCIONES Y FUSIONES Y EMITIR LAS OPINIONES TÉCNICAS PARA SU VIABILIDAD EN ESTRECHA COLABORACIÓN CON LA DIRECCIÓN Y SUBDIRECCIÓN DEL ÁREA Y MANTENER ACTUALIZADO EL SIRCA P-A CON EL PADRÓN DE PERMISIONARIOS QUE REALIZAN ACTIVIDADES TURÍSTICAS COMERCIALES EN EL ANP.', '10', '20', '81 A 90%', '71 A 80 %', '0 A 70%', NULL, 'COADYUVAR EN EL MONITOREO BIOLÓGICO Y ACTUALIZAR LAS BASES DE DATOS CON INFORMACIÓN GENERADO POR LOS MONITOREOS BIOLÓGICOS QUE SE REALIZAN EN EL ANP.', '10', '20', '81 A 90%', '71 A 80 %', '0 A 70%', NULL, 'PARTICIPAR EN ACCIONES DE PREVENCIÓN Y COMBATE DE INCENDIOS FORESTALES DENTRO DEL ANP EN COORDINACIÓN CON OTRAS DEPENDENCIAS DEL SECTOR.', '10', '20', '81 A 90%', '71 A 80 %', '0 A 70%', NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (388, 'OIHS720220', 'SUPERVISAR Y COORDINAR LAS ACCIONES Y PROYECTOS DE CONSERVACIÓN DE LOS RECURSOS NATURALES DEL MN CERRO DE LA SILLA Y DEL PN CUMBRES DE MONTERREY, DE CONFORMIDAD CON LOS PROGRAMAS Y DECRETOS CORRESPONDIENTES', '04', '20', 'SE COORDINARON Y SUPERVISARON EL 100% DE LOS PROYECTOS REALIZADOS POR LAS DIRECCIONES DEL PN CUMBRES DE MONTERREY Y MN CERRO DE LA SILLA', 'SE COORDINARON Y SUPERVISARON EL 70% DE LOS PROYECTOS REALIZADOS POR LAS DIRECCIONES DEL PN CUMBRES DE MONTERREY Y MN CERRO DE LA SILLA', 'SE COORDINARON Y SUPERVISARON EL 30% DE LOS PROYECTOS REALIZADOS POR LAS DIRECCIONES DEL PN CUMBRES DE MONTERREY Y MN CERRO DE LA SILLA', '90', 'ORGANIZAR Y PARTICIPAR EN REUNIONES DE LOS CONSEJOS ASESORES DEL PN CUMBRES DE MONTERREY Y DEL MN CERRO DE LA SILLA, FUNGIENDO EN AMBOS CASOS COMO SECRETARIO TÉCNICO', '04', '20', 'SE REALIZARON EL 100% DE LAS REUNIONES CONTEMPLADAS EN EL PROGRAMA OPERATIVO ANUAL (POA)', 'SE REALIZARON EL 70% DE LAS REUNIONES CONTEMPLADAS EN EL PROGRAMA OPERATIVO ANUAL (POA)', 'SE REALIZARON EL 30% DE LAS REUNIONES CONTEMPLADAS EN EL PROGRAMA OPERATIVO ANUAL (POA)', '90', 'INTEGRAR Y REMITIR DENUNCIAS ANTE LAS AUTORIDADES CORRESPONDIENTES ANTE PRESUNTOS ILÍCITOS QUE SE REALICEN EN EL PN CUMBRES DE MONTERREY Y MN CERRO DE LA SILLA', '04', '20', 'SE DENUNCIARON TODOS LOS ILÍCITOS DETECTADOS EN EL MN CERRO DE LA SILLA Y DEL PN CUMBRES DE MONTERREY', 'SE DENUNCIÓ EL 70% DE LOS ILÍCITOS DETECTADOS EN EL MN CERRO DE LA SILLA Y DEL PN CUMBRES DE MONTERREY', 'SE DENUNCIÓ MENOS DEL 30% DE LOS ILÍCITOS DETECTADOS EN EL MN CERRO DE LA SILLA Y DEL PN CUMBRES DE MONTERREY', '90', 'INTEGRACIÓN Y EMISIÓN DE DICTÁMENES TÉCNICOS DE SOPORTE EN MATERIA DE IMPACTO AMBIENTAL, FORESTAL Y PRESTACIÓN DE SERVICIOS TURÍSTICOS, DE CONFORMIDAD CON LOS LINEAMIENTOS Y NORMATIVA APLICABLE AL PN CUMBRES DE MONTERREY Y MN CERRO DE LA SILLA', '05', '20', 'SE EMITIERON TODOS LOS DICTÁMENES TÉCNICOS SOLICITADOS POR LA DIRECCIÓN REGIONAL NORESTE Y SMO, EN TIEMPO Y FORMA', 'SE EMITIÓ UN 70% DE LOS DICTÁMENES TÉCNICOS DE SOPORTE SOLICITADOS POR LA DIRECCIÓN REGIONAL NORESTE Y SMO, EN TIEMPO Y FORMA', 'SE EMITIÓ UN 30% DE LOS DICTÁMENES TÉCNICOS DE SOPORTE SOLICITADOS POR LA DIRECCIÓN REGIONAL NORESTE Y SMO, EN TIEMPO Y FORMA', '90', 'COORDINACIÓN Y SUPERVISIÓN EN LA OPERACIÓN DE PROGRAMAS DE SUBSIDIOS EN EL MN CERRO DE LA SILLA Y EL PN CUMBRES DE MONTERREY.', '04', '20', 'SE REALIZAN TODOS LOS PROYECTOS DENTRO DE LOS PROGRAMAS DE SUBSIDIOS, DE CONFORMIDAD CON LOS LINEAMIENTOS Y NORMATIVA CORRESPONDIENTE', 'SE REALIZA EL 70% DE LOS PROYECTOS DENTRO DE LOS PROGRAMAS DE SUBSIDIUOS, DE CONFORMIDAD CON LOS LINEAMIENTOS Y NORMATIVA CORRESPONDIENTE', 'SE REALIZA EL 30% DE LOS PROYECTOS DENTRO DE LOS PROGRAMAS DE SUBSIDIUOS, DE CONFORMIDAD CON LOS LINEAMIENTOS Y NORMATIVA CORRESPONDIENTE', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (389, 'OOBJ710318', 'APOYAR, EJECUTAR A SI COMO ELABORAR OFICIOS Y TODAS LAS INDICACIONES POR MI DIRECTOR PARA CUMPLIR CON LAS ASIGNACIONES AL 100%, LLEGAR EN COORDINACIÓN CON LAS 3 SUBDIRECCIONES A FINALIZAR Y CUMPLIR LAS METAS, ORDENANDO, ASIGNANDO Y CAPTURANDO LA INFORMACIÓN CORRESPONDIENTE A CADA TEMA SOLICITADO.', '02', '50', 'REALIZAR ENTRE EL 90% AL 100% DE ASIGNACIONES', 'REALIZAR ENTRE EL 80% AL 90% DE ASIGNACIONES', 'REALIZAR MENOS DE 50% AL 79% DE ASIGANCIONES', '90', 'ELABORAR, REVISAR, ASÍ COMO ASIGNAR Y DAR SEGUIMIENTO EN EL SISTEMA DE GESTIÓN DEL 100 % DE TODAS LAS SOLICITUDES ATENDIDAS POR LAS SUBDIRECCIONES (PLANEACIÓN, GEOMÁTICA Y MONITOREO); ASÍ COMO EL ENVÍO DE INFORMACIÓN POR MENSAJERÍA HASTA CONCLUIR SU RESPUESTA, ARCHIVANDO EN ELECTRÓNICO Y EL DOCUMENTO DE TODAS LAS SOLICITUDES Y ACUSES DE OFICIOS ELABORADOS Y SOLICITUDES ASIGNADAS A LA DES', '02', '25', 'REALIZAR ENTRE EL 90% AL 100% DE ASIGNACIONES', 'REALIZAR ENTRE EL 80% AL 90% DE ASIGNACIONES', 'REALIZAR MENOS DE 50% AL 79% DE ASIGANCIONES', '90', 'APOYAR ADMINISTRATIVAMENTE A TODA LA DIRECCIÓN, EN CONTESTACIÓN DE OFICIOS, ELABORACIÓN DE TARJETAS PARA EL COMISIONADO, INVESTIGACIÓN DE INFORMACIÓN, APOYO PARA RECOPILAR INFORMACIÓN PARA LAS 225 ANP EN DIFERENTES TEMAS ASIGNADOS A LA DES ELABORACIÓN Y CAPTURA DE REPORTES DE INFORMACIÓN SOBRE LOS REQUERIMIENTOS DEL INAI HASTA QUE ESTÉN ATENDIDOS.', '02', '15', 'REALIZAR ENTRE EL 90% AL 100% DE ASIGNACIONES', 'REALIZAR ENTRE EL 80% AL 90% DE ASIGNACIONES', 'REALIZAR MENOS DE 50% AL 79% DE ASIGANCIONES', '90', 'APOYO Y ELABORACIÓN PARA LOS TALLERES, REUNIONES O VIDEO CONFERENCIAS SOLICITADAS POR LAS 3 SUBDIRECCIONES; YA SEA POR VIDEO CONFERENCIAS O PRESENCIALES, ASÍ COMO APOYO EN LA PREPARACIÓN Y ELABORACIÓN DE CONSTANCIAS DE TALLERES IMPARTIDOS, ENVIÓ DE LAS MISMAS A TODOS LOS PARTICIPANTES VÍA CORREO O MENSAJERÍA, DE ACUERDO A LAS METAS ESTABLECIDAS POR LA DIRECCIÓN.', '01', '10', 'REALIZAR ENTRE EL 90% AL 100% DE ASIGNACIONES', 'REALIZAR ENTRE EL 80% AL 90% DE ASIGNACIONES', 'REALIZAR MENOS DE 50% AL 79% DE ASIGANCIONES', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (390, 'OORR840623', 'SUPERVISAR LAS ACCIONES QUE SE REALICEN DENTRO DEL ÁREA NATURAL PROTEGIDA, PARA QUE SE AJUSTEN A LOS PROPOSITOS DE LOS ORDENAMIENTOS LEGALES APLICABLES EN LA MATERIA DE PROTECCIÓN, MANEJO Y RESTAURACIÓN PARA LA CONSERVACIÓN DE LOS ECOSISTEMAS Y SU BIODIVERSIDAD', '10', '25', '75 O MAS', '75 - 50', '50 - 0', '90', 'PROMOVER EL DESARROLLO COMUNITARIO PARTICIPATIVO EN EL ÁREA EN LO RELATIVO A LOS PROGRAMAS DE SUBSIDIO Y PROYECTO DE CONSERVACIÓN PARA EL DESARROLLO, Y DE MANEJO PARA EL USO Y APROVECHAMIENTO DE LOS ECOSISTEMAS Y SU BIODIVERSIDAD.', '10', '25', '75 O MAS', '75 - 50', '50 - 0', '90', 'INTERVENIR EN LA FORMULACIÓN Y EJECUCIÓN DE LOS PROGRAMAS DE ORDENAMIENTO ECOLOGICO QUE INDICAN EN EL ÁREA NATURAL PROTEGIDA Y SUS ZONAS DE INFLUENCIA, CONFORMAR EL SISTEMA DE INFORMACIÓN DE LOS DATOS BIOLÓGICOS, SOCIALES, ECONÓMICOS Y CARTOGRÁFICOS DEL ÁREA NATURAL PROGIDA CORRESPONDIENTE', '10', '25', '75 O MAS', '75 - 50', '50 - 0', '90', 'PARTICIPAR EN LOS PROGRAMAS, PROYECTOS Y ACCIONES DE ESPECIES Y POBLACIONES CONSIDERADAS COMO PRIORITARIAS PARA LA CONSERVACIÓN, EN LAS ÁREAS NATURALES PROTEGIDAS DE SU COMPETENCIA, COLABORAR, DIRIGIR Y EJECUTAR LOS PROGRAMAS DE ATENCIÓN DE CONTINGENCIAS AMBIENTALES.', '10', '25', '75 O MAS', '75 - 50', '50 - 0', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (391, 'OULC721213', 'ELABORAR Y COORDINAR LA EJECUCION DEL PROGRAMA OPERATIVO ANUAL (POA) DEL ANP CON BASE EN EL DECRETO, EN LAS METAS DE LA ESTRATEGIA REGIONAL Y PROGRAMA NACIONAL, ASI COMO ELABORAR Y ENTREGAR EN TIEMPO Y FORMA LOS INFORMES TRIMESTRALES DE LAS ACCIONES Y AVANCES OBTENIDOS DENTRO DEL ANP', '04', '25', 'EL POA Y LOS INFORMES TRIMESTRALES FUERON ELABORADOS Y ENTREGADOS EN TIEMPO Y FORMA, LOS OBJETIVOS Y METAS FUERON CUMPLIDOS EN UN 96-100%', 'EL POA Y LOS INFORMES FUERON ELABORADOS Y ENTREGADOS EN TIEMPO Y FORMA, LOS OBJETIVOS Y METAS FUERON CUMPLIDOS EN UN 85-95%', 'EL POA Y LOS INFORMES TRIMESTRALES FUERON ELABORADOS Y ENTREGADOS EN TIEMPO Y FORMA, LOS OBJETIVOS Y METAS FUERON CUMPLIDOS EN MENOS DEL 85%', '90', 'SEGUIMIENTO A LOS RECURSOS ASIGNADOS PARA CADA ANP CORRESPONDIENTES A LOS PROGRAMAS ASISTENCIALES, PROCODES, PROREST', '05', '25', 'MAS DE 90% DE LOS RECURSOS ASIGNADOS', 'DEL 80 A 90% DE LOS RECURSOS ASIGNADOS', 'MENOS DEL 80% DE LOS RECURSOS ASIGNADOS', '90', 'DAR RESPUESTA A LAS SOLICITUDES DE OPINIONES TECNICAS SOBRE PROYECTOS, LICENCIAS, PERMISOS, AUTORIZACIONES Y DEMAS RESOLUCIONES ADMINISTRATIVAS EN EL AREA NATURAL PROTEGIDA A FIN DE CONTRIBUIR AL CUMPLIMIENTO DE LOS OBJETIVOS DE LA COMISION NACIONAL DE AREAS NATURALES PROTEGIDAS', '04', '20', 'ATENDER EN TIEMPO Y FORMA DEL 90 AL 100% DE SOLICITUDES INGRESADAS', 'ATENDER EN TIEMPO Y FORMA EL 80 A 89% DE SOLICITUDES INGRESADAS', 'ATENDER EN TIEMPO Y FORMA MENOS DE 80% DE SOLICITUDES INGRESADAS', '90', 'REALIZAR ACTIVIDADES ADMINISTRATIVAS, DE COORDINACIÓN DE PERSONAL OPERATIVO Y DE LOGÍSTICA, ASÍ COMO DE GESTIÓN DE RECURSOS MATERIALES, HUMANOS, TECNOLÓGICOS, FINANCIEROS Y/O JURÍDICOS QUE SE REQUIERAN, DENTRO DE SU ÁMBITO DE APLICACIÓN, ASEGURANDO EL CUMPLIMIENTO NORMATIVO Y LA CONSECUCIÓN DE LAS ACTIVIDADES Y LA ADECUADA OPERACIÓN DEL ANP.', '04', '20', '80 A 100%', '60 A 80%', 'MENOR DE 60%', '90', 'LAS DEMÁS QUE LE CONFIERA Y/O INSTRUYA SU JEFE INMEDIATO, EL DIRECTOR REGIONAL, LA UNIDAD ADMINISTRATIVA, LA UNIDAD TÉCNICA O LA UNIDAD JURÍDICA DE LA DIRECCIÓN REGIONAL, ASÍ COMO LAS QUE SEÑALEN LAS DISPOSICIONES LEGALES Y REGLAMENTARIAS VIGENTES DENTRO DE SU ALCANCE Y MARCO DE ACTUACIÓN ORIENTADAS A ASEGURAR LA ADECUADA OPERACIÓN DEL ANP, DE LA DIRECCIÓN REGIONAL Y DE LA CONSERVACIÓN DEL MEDIO AMBIENTE.', '04', '10', '80 A 100%', '60 A 80%', 'MENOR DE 60%', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
