INSERT INTO `sed_individuales` VALUES (397, 'PEAI900810', 'ATENCIÓN A LAS SOLICITUDES DE AUTORIZACIONES Y PERMISOS, ELABIRACIÓN DE LOS PROYECTOS DE RESPUESTA Y DE OPINIÓN PARA AUTORIZACIONES DE ACTIVIDADES TURÍSTICO RECREATIVAS Y LAS REFERENTES AL ARTÍCULO 105 DEL REGLAMENTO DE LA LGEEPA ,DENTRO DEL ARCHIPIÉLAGO DE BAHÍA MAGDALENA E ISLA ALIJOS, DE LA RESERVA DE LA BIOSFERA ISLAS DEL PACIFICO DE LA PENÍNSULA DE BAJA CALIFORNIA Y ENVIARLAS A LA UNIDAD JURÍDICA DE LA DIRECCIÓN REGIONAL PENÍNSULA DE BAJA CALIFORNIA Y PACIFICO NORTE.', '10', '20', 'ATENCIÓN DE LAS SOLICITUDES Y ELABORACIÓN DEL 90 AL 100% LOS PROYECTOS DE RESPUESTA AL AÑO.', 'ATENCIÓN DE LAS SOLICITUDES Y ELABORACIÓN DEL 70 AL 89% LOS PROYECTOS DE RESPUESTA AL AÑO.', 'ATENCIÓN DE LAS SOLICITUDES Y ELABORACIÓN MENOR AL 70% LOS PROYECTOS DE RESPUESTA AL AÑO.', '90', 'ELABORACIÓN, APOYO Y SEGUIMIENTO DE PROCEDIMIENTOS/TRÁMITES ADMINISTRATIVOS, SOLICITUDES DE PAGOS DE PROVEEDORES DE LA ZONA SUR DE LA RESERVA DE LA BIOSFERA ISLAS DEL PACIFICO DE LA PENÍNSULA DE BAJA CALIFORNIA, ASÍ COMO EMITIRLAS A LA UNIDAD ADMINISTRATIVA DE LA DIRECCIÓN REGIONAL PENÍNSULA DE BAJA CALIFORNIA Y PACIFICO NORTE, PARA SU DEBIDA ATENCIÓN.', '10', '20', 'ATENCIÓN Y ELABORACIÓN DEL 90 AL 100% DE TRÁMITES ADMINISTRATIVOS AL AÑO', 'ATENCIÓN Y ELABORACIÓN DEL 70 AL 89% DE TRÁMITES ADMINISTRATIVOS AL AÑO', 'ATENCIÓN Y ELABORACIÓN MENOR AL 70% DE TRÁMITES ADMINISTRATIVOS AL AÑO', '90', 'APOYO EN LA DIFUSIÓN, SEGUIMIENTO Y SUPERVISIÓN ADMINISTRATIVA Y DE CAMPO DE LOS PROYECTOS DE SUBSIDIOS APROBADOS EN EL ARCHIPIÉLAGO DE BAHÍA MAGDALENA E ISLA ALIJOS, DE LA RESERVA DE LA BIOSFERA ISLAS DEL PACIFICO DE LA PENÍNSULA DE BAJA CALIFORNIA.', '10', '20', 'APOYO Y SEGUIMIENTO DEL 40 AL 50% DE PROYECTOS OTORGADOS EN ZONA SUR DEL ANP', 'APOYO Y SEGUIMIENTO DEL 20 AL 39% DE PROYECTOS OTORGADOS EN ZONA SUR DEL ANP', 'APOYO Y SEGUIMIENTO AL MENOS DEL 10% DE PROYECTOS OTORGADOS EN ZONA SUR DEL ANP', '90', 'REALIZAR RECORRIDOS DE SUPERVISIÓN Y VIGILANC