INSERT INTO `sed_individuales` VALUES (398, 'PECC930131', 'ELABORAR Y MANTENER ACTUALIZADA LA INFORMACIÓN CARTOGRÁFICA DE LA DIRECCIÓN REGIONAL NOROESTE Y ALTO GOLFO DE CALIFORNIA.', '10', '20', 'ATENDER EN TIEMPO Y FORMA MÁS DEL 80% DE LAS SOLICITUDES Y REQUERIMIENTOS EN MATERIA DE INFORMACIÓN CARTOGRÁFICA DE LA DIRECCIÓN REGIONAL NOROESTE Y ALTO GOLFO DE CALIFORNIA.', 'ATENDER ENTRE EL 60% Y 79% LAS SOLICITUDES Y REQUERIMIENTOS EN MATERIA DE INFORMACIÓN CARTOGRÁFICA DE LA DIRECCIÓN REGIONAL NOROESTE Y ALTO GOLFO DE CALIFORNIA.', 'ATENDER EN TIEMPO Y FORMA MENOS DEL 59% LAS SOLICITUDES Y REQUERIMIENTOS EN MATERIA DE INFORMACIÓN CARTOGRÁFICA DE LA DIRECCIÓN REGIONAL NOROESTE Y ALTO GOLFO DE CALIFORNIA.', '90', 'ATENDER Y BRINDAR APOYO TÉCNICO EN TEMAS DE LAS ÁREAS DESTINADAS VOLUNTARIAMENTE A LA CONSERVACIÓN, ASÍ COMO ORIENTACIÓN A PROPIETARIOS Y VISITAS A PREDIOS SOLICITANTES.', '10', '20', 'ATENDER EN TIEMPO Y FORMA MÁS DEL 80% DE ASUNTOS RELACIONADOS A LAS ÁREAS DESTINADAS VOLUNTARIAMENTE A LA CONSERVACIÓN DE LA DRNYAGC.', 'ATENDER ENTRE EL 65% Y 79% LOS ASUNTOS RELACIONADOS A LAS ÁREAS DESTINADAS VOLUNTARIAMENTE A LA CONSERVACIÓN.', 'ATENDER MENOS DEL 64% LOS ASUNTOS RELACIONADOS A LAS ÁREAS DESTINADAS VOLUNTARIAMENTE A LA CONSERVACIÓN.', '90', 'ELABORACIÓN DE PLANOS OFICIALES Y DE UBICACIÓN DE LAS ANP\'S, SITIOS RAMSAR, ACUERDOS DE DESTINO, TERRENOS NACIONALES Y ÁREAS DESTINADAS VOLUNTARIAMENTE A LA CONSERVACIÓN.', '10', '20', 'ATENDER EN TIEMPO Y FORMA MÁS DEL 90% LA ELABORACIÓN DE PLANOS DE LAS ANP\'S Y ÁREAS DE INTERÉS DE LA DIRECCIÓN REGIOAN NOROESTE Y ALTO GOLFO DE CALIFORNIA.', 'ATENDER ENTRE EL 70% Y 89% DE ELABORACIONES DE PLANOS DE LAS ANPS\'S Y ÁREAS DE INTERÉS DE LA DIRECCIÓN REGIONAL NOROESTE Y ALTO GOLFO DE CALIFORNIA.', 'ATENDER MENOS DEL 69% DE ELABORACIONES DE PLANOS DE LAS ANP´S Y ÁREAS DE INTERES DE LA DIRECCIÓN REGIONAL NOROESTE Y ALTO GOLFO DE CALIFORNIA.', '90', 'ATENDER Y BRINDAR APOYO TÉCNICO EN TEMAS RELACIONADOS A INCENDIOS FORESTALES E