INSERT INTO `sed_individuales` VALUES (403, 'PEHA971110', 'COLABORAR EN LA FORMULACIÓN DEL PROGRAMA DE MANEJO DEL PARQUE NACIONAL LOS MÁRMOLES, MEDIANTE LA REVISIÓN DOCUMENTAL, RECOPILACIÓN DE INFORMACIÓN Y LA ELABORACIÓN DE TABLAS Y MAPAS TEMÁTICOS.', '10', '30', '1', '0.8', '0.5', '70', 'PARTICIPAR EN EL PROCESO DE DIFUSIÓN, RECEPCIÓN DE SOLICITUDES, INTEGRACIÓN DE EXPEDIENTES, DICTAMINACIÓN DE LOS PROGRAMAS DE SUBSIDIOS PROCODES Y PROREST. ASÍ COMO EN LA EJECUCIÓN DE LOS PROYECTOS EN APEGO A LA NORMATIVIDAD APLICABLE E IMPULSANDO ACCIONES CON PERSPECTIVA DE GÉNERO.', '10', '20', '1', '0.8', '0.5', '90', 'DAR SEGUIMIENTO A LAS ACTIVIDADES DE VIGILANCIA Y MONITOREO BIOLÓGICO COMUNITARIO; ASESORAR A LAS BRIGADAS EN EL USO CORRECTO DEL LAS HERRAMIENTAS, APLICACIONES MOVILES, APOYO EN LA IDENTIFICACIÓN DE ESPECIES DE FLORA Y FAUNA, Y REPORTE EN CASO DE LA DETECCIÓN DE ALGÚN ILÍCITO AMBIENTAL.', '10', '20', '1', '0.8', '0.5', '90', 'LLEVAR A CABO ACTIVIDADES DE EDUCACIÓN AMBIENTAL EN CORDINACIÓN CON LOS MIEMBROS DE LAS BRIGADAS DE VIGILANCIA Y MONITOREO BIOLÓGICO COMUNITARIO ASÍ COMO LOS GRUPOS QUE TRABAJEN EN CONSERVACIÓN DE ESPECIES, EN DIFERENTES LOCALIDADES DEL PARQUE, CON TEMATICAS SOBRE: CONSERVACIÓN, BIODIVERSIDAD, AMENAZAS A LA BIODIVERSIDAD Y ECOSISTEMAS.', '10', '15', '1', '0.8', '0.5', '90', 'DAR ATENCIÓN EN LA RECECPCIÓN DE GRUPOS TURISTICOS O CON FINES DE INVESTIGACIÓN. APOYAR CON EL COBRO DE DERECHOS EN LAS DIFERENTES LOCALIDADES DENTRO DEL PNLM.', '10', '15', '1', '0.8', '0.5', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demo