INSERT INTO `sed_individuales` VALUES (404, 'PEJX870630', 'DAR SEGUIMIENTO LAS ACCIONES ENCAMINADAS A LA RESTAURACIÓN DE LOS ECOSISTEMAS DEL EN EL ÁREA DE PROTECCIÓN DE FLORA Y FAUNA SISTEMA ARRECIFAL LOBOS TUXPAN Y SU ZONA DE INFLUENCIA, ASÍ COMO A LAS ESPECIES EN ALGUNA CATEGORÍA DE RIESGO PARA EL CAMPAMENTO TORTUGUERO TOTONACAPAN', '10', '30', 'CUMPLIR CON EL 80 AL 84.9% DE LAS METAS ESTABLECIDAS EN LOS PROYECTOS DE RESTAURACIÓN, CONOCIMIENTO, CULTURA Y GESTIÓN CONTEMPLADAS EN EL PROGRAMA OPERATIVO ANUAL.', 'CUMPLIR CON EL 75 AL 79.9% DE LAS METAS ESTABLECIDAS EN LOS PROYECTOS DE RESTAURACIÓN, CONOCIMIENTO, CULTURA Y GESTIÓN CONTEMPLADAS EN EL PROGRAMA OPERATIVO ANUAL.', 'CUMPLIR CON EL 0 AL 74.9% DE LAS METAS ESTABLECIDAS EN LOS PROYECTOS DE RESTAURACIÓN, CONOCIMIENTO, CULTURA Y GESTIÓN CONTEMPLADAS EN EL PROGRAMA OPERATIVO ANUAL', '90', 'DAR SEGUIMIENTO A LOS PROGRAMAS DE SUBSIDIOS QUE SE IMPLEMENTAN EN LAS COMUNIDADES ALEDAÑAS AL ÁREA DE PROTECCIÓN SISTEMA ARRECIFAL LOBOS TUXPAN, SU ZONA DE INFLUENCIA Y LA ZONA DEL CAMPAMENTO TORTUGUERO TOTONACAPAN.', '10', '30', 'CUMPLIR CON EL 80 AL 89.9% DE LAS METAS DE LOS PROYECTOS REALIZADOS A LA APLICACIÓN DE SUBSIDIOS.', 'CUMPLIR CON EL 70 AL 79.9% DE LAS METAS DE LOS PROYECTOS REALIZADOS A LA APLICACIÓN DE SUBSIDIOS.', 'CUMPLIR CON EL 0 AL 69.9% DE LAS METAS DE LOS PROYECTOS REALIZADOS A LA APLICACIÓN DE SUBSIDIOS.', '90', 'REALIZAR Y COORDINAR ACCIONES DE VIGILANCIA AMBIENTAL EN EL ÁREA DE PROTECCIÓN DE FLORA Y FAUNA SISTEMA ARRECIFAL LOBOS TUXPAN Y SU ZONA DE INFLUENCIA.', '10', '30', 'CUMPLIR CON EL 80 AL 89.9% DE LAS ACCIONES DE VIGILANCIA EN EL ÁREA DE PROTECCIÓN DE FLORA Y FAUNA SISTEMA ARRECIFAL LOBOS TUXPAN', 'CUMPLIR CON EL 70 AL 79.9% DE LAS ACCIONES DE VIGILANCIA EN EL ÁREA DE PROTECCIÓN DE FLORA Y FAUNA SISTEMA ARRECIFAL LOBOS TUXPAN', 'CUMPLIR CON EL 0 AL 69.9% DE LAS ACCIONES DE VIGILANCIA EN EL ÁREA DE PROTECCIÓN DE FLORA Y FAUNA SISTEMA ARRECIFAL LOBOS TUXPAN', '90', 'PROMOVER Y REALIZAR DIVERSAS ACTIV