INSERT INTO `sed_individuales` VALUES (405, 'PELG630318', 'EJECUTAR ACCIONES Y ESTRATEGIAS DE PROTECCIÓN, MANEJO, RESTAURACIÓN, INVESTIGACIÓN Y ACTIVIDADES HUMANAS EN EL ANP', '04', '20', 'EJECUCION POR LO MENOS DE 95 % DE ACCIONES CONCLUIDAS', 'EJECUTAR MENOS 85 % DE ACCIONES CONCLUIDAS', 'EJECUTAR MENOS DEL 80 % DE ACCIONES CONCLUIDAS', '90', 'DAR SEGUIMIENTO A LA EJECUCIÓN DE LOS PROGRAMAS DE SUBSIDIO MEDIANTE LA ASESORÍA, VERIFICACIÓN, INTEGRACIÓN Y REVISIÓN DE EXPEDIENTES EN APEGO A LAS REGLAS DE OPERACIÓN Y LINEAMIENTOS ESTABLECIDOS Y CON ELLO CONTRIBUIR AL CUMPLIMIENTO DE OBJETIVOS Y METAS INSTITUCIONALES EN LA DIRECCIÓN REGIONAL.', '02', '20', '90 % DE ASESORIA A LOS GRUPOS BENEFICIARIOS EM PROGRAMAS DE SUBSIDIOS', '85 % DE ASESORÍA A LOS GRUPOS BENEFICIARIOS EN PROGRAMAS DE SUBSIDIOS', '80 % DE ASESORIA A LOS GRUPOS BENEFICIARIOS EM PROGRAMAS DE SUBSIDIOS', '90', 'REVISAR LA INFORMACIÓN BIOLÓGICA, GEOGRÁFICA Y SOCIAL DISPONIBLE DEL ANP PARA ANALIZAR LAS PROPUESTAS DE LOS PROYECTOS SOLICITADOS Y AUTORIZADOS, COMPATIBLES CON LAS ESTRATEGIAS DE MANEJO DEL ANP, ALINEADOS A LA NORMATIVIDAD AMBIENTAL VIGENTE.', '08', '20', 'ANALIZAR EL 95% DE LA PROPUESTAS', 'ANALIZAR EL 85% DE LA PROPUESTAS', 'ANALIZAR MENOS DEL 80 % DE LA PROPUESTAS', '90', 'REALIZAR ACCIONES DE ASESORARIA A LAS DEPENDENCIAS INVOLUCRADAS EN ACCIONES DE PLANEACIÓN, CONSERVACIÓN Y DESARROLLO DEL ÁREA NATURAL PROTEGIDA, ASEGURANDO QUE SE DISEÑEN Y AUTORICEN ACCIONES COMPATIBLES CON LAS ESTRATEGIAS DE MANEJO DEL ANP.', '08', '20', '95 % DE ASESORÍA EN LAS ESTRATEGIAS DE MANEJO DE ANP', '85 % DE ASESORÍA EN LAS ESTRATEGIAS DE MANEJO DE ANP', '75 % DE ASESORÍA EN LAS ESTRATEGIAS DE MANEJO DE ANP', '90', 'REALIZAR ACTIVIDADES ADMINISTRATIVAS, DE COORDINACIÓN DE PERSONAL OPERATIVO Y DE LOGÍSTICA, ASÍ COMO DE GESTIÓN DE RECURSOS MATERIALES, HUMANOS, TECNOLÓGICOS, FINANCIEROS Y/O JURÍDICOS QUE SE REQUIERAN, DENTRO DE SU ÁMBITO DE APLICACIÓN , ASEGURANDO EL CUMPLIMIENTO NORMATIVO Y LA CONSECUCIÓN DE LAS ACTIVIDADES Y LA ADECUADA OPERACIÓN DEL ANP Y LA DIRECCIÓN REGIONAL.', '08', '20', 'CONTAR CON EL 100 % DE LAS META ESTABLECIDA EN EL POA', 'CONTAR CON EL 90 % DE LAS META ESTABLECIDA EN EL POA', 'CONTAR CON EL 90 % DE LAS META ESTABLECIDA EN EL POA', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (406, 'PEMA680601', 'OPERAR LOS PROGRAMAS DE SUBSIDIOS (PROCODES Y PROREST) EN APEGO A LA NORMATIVIDAD DE APLICACIÓN DE LOS RECURSOS (REGLAS DE OPERACIÓN Y LINEAMIENTOS INTERNOS), CON EL FIN DE LOGRAR LOS OBJETIVOS PROPUESTOS PARA CADA UNA DE LOS PROGRAMAS Y FORTALECER LAS LÍNEAS ESTRATÉGICAS ESTABLECIDOS EN LOS PROGRAMAS DE CONSERVACIÓN Y MANEJO DEL ANP.', '05', '30', '80 AL 100 % DE LOS RECURSOS ASIGNADOS SON EJERCIDOS.', '60 AL 80 % DE LOS RECURSOS ASIGNADOS SON EJERCIDOS.', 'MENOS DEL 60% DE LOS RECURSOS ASIGNADOS SON EJERCIDOS.', '90', 'SEGUIMIENTO DE LOS PROYECTOS Y/O ACCIONES QUE SE EJECUTAN MEDIANTE LA APLICACIÓN DE LOS PROGRAMAS DE SUBSIDIOS, EN APEGO A SUS REGLAS DE OPERACIÓN Y LINEAMIENTOS INTERNOS PARA SU OPERACIÓN.', '05', '30', 'ENTREGA DE INFORMES DE LOS PROGRAMAS DE SUBSIDIOS EN TIEMPO Y FORMA, ADEMÁS DE QUE EN CAMPO SE APLIQUE DE ACUERDO A LAS REGLAS DE OPERACIÓN Y LINEAMIENTOS INTERNOS.', 'ENTREGA DE INFORMES DE LOS PROGRAMAS DE SUBSIDIOS EN TIEMPO Y FORMA, ADEMÁS DE QUE EN CAMPO NO SE EJECUTEN DE ACUERDO A LAS REGLAS DE OPERACIÓN Y LINEAMIENTOS INTERNOS.', 'NO ENTREGAR INFORMES NI VISITAS DE SUPERVISIONES DE CAMPO', '90', 'PROMOVER QUE LOS PROGRAMAS DE SUBSIDIOS Y PROYECTOS SE APLIQUEN DE ACUERDO A LOS REORDENAMIENTOS DE LAS ACTIVIDADES PRODUCTIVAS QUE SE REALIZAN EN EL ANP Y SU ZONA DE INFLUENCIA, DE TAL MANERA QUE CONTRIBUYA A LA CONSERVACIÓN DE LOS ECOSISTEMAS Y ESPECIES PRIORITARIAS DE ACUERDO AL PROGRAMA DE CONSERVACIÓN Y MANEJO DEL ÁREA.', '05', '20', 'ASEGURAR QUE LOS PROGRAMAS DE SUBSIDIOS SE APLIQUEN DE ACUERDO A LAS ACTIVIDADES PRODUCTIVAS QUE SE REALIZAN EN LAS ANP´S Y SU ZONA DE INFLUENCIA.', 'QUE EXISTAN INCUMPLIMIENTO EN LA EJECUCIÓN DE LOS PROYECTOS EN MAS DE UN PROGRAMA QUE SE OPERA.', 'QUE EN MAS DE DOS PROGRAMAS O PROYECTOS EXISTAN INCUMPLIMIENTO.', '90', 'APOYAR EN LA ELABORACIÓN Y SEGUIMIENTO DEL PROGRAMA OPERATIVO ANUAL (POA) EN BASE A SU DECRETO Y PROGRAMA DE MANEJO DEL ANP, ASÍ COMO COADYUVAR EN LA ELABORACIÓN DE LOS CUATRO INFORMES TRIMESTRALES DE LAS ACCIONES Y AVANCES OBTENIDAS.', '05', '20', 'SE ELABORA EL POA, CON CUATRO INFORMES QUE INTEGRAN TODAS LAS ACTIVIDADES REALIZADAS EN EL ANP Y ZONA DE INFLUENCIA.', 'SE ELABORA UN PROGRAMA OPERATIVO ANUAL (POA)', 'NO ELABORAR EL PROGRAMA OPERATIVO ANUAL (POA)', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
