INSERT INTO `sed_individuales` VALUES (412, 'PIPR790626', 'ELABORAR Y EJECUTAR DOS PROGRAMAS OPERATIVOS ANUALES, CORRESPONDIENTES A LAS ÁREAS NATURALES PROTEGIDAS, RESERVA DE LA BIOSFERA BALAM KÚ Y ÁREA DE PROTECCIÓN DE FLORA Y FAUNA BALAM KIN,', '01', '20', 'ELABORAR Y OPERAR DOS PROGRAMAS OPERATIVOS ANUALES', 'ELABORAR Y EJECUTAR UN PROGRAMA OPERATIVO ANUAL.', 'NO OPERAR NINGUN PROGRAMA OPERATIVO ANUAL', '90', 'DAR SEGUIMIENTO A DOS PROGRAMA DE SUBSIDIO, EN LAS ÁREAS NATURALES PROTEGIDAS, BAJO MI RESPONSABILIDAD, (EL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE Y EL PROGRAMA PARA LA RECUPERACIÓN DE ESPECIES EN RIESGO).', '01', '20', 'DAR SEGUIMIENTO A DOS PROGRAMAS DE SUBSIDIO', 'DAR SEGUIMIENTO A UN PROGRAMA DE SUBSIDIO', 'NO DAR SEGUIMIENTO A NINGÚN PROGRAMA DE SUBSIDIO FEDERAL.', '90', 'DAR SEGUIMIENTO AL PROCESO DE ELABORACIÓN DE DOS PROGRAMAS DE CONSERVACIÓN Y MANEJO, PARA LAS ÁREAS NATURALES PROTEGIDAS:, RESERVA DE LA BIOSFERA BALAM KU Y ÁREA DE PROTECCIÓN DE FLORA Y FAUNA BALAM KIN.', '01', '20', 'DAR SEGUIMIENTO A LA ELABORACIÓN DE DOS PROGRAMAS DE CONSERVACIÓN Y MANEJO', 'DAR SEGUIMIENTO A UN PROGRAMA DE CONSERVACIÓN Y MANJEJO', 'NO DAR SEGUMIENTO A LOS PROGRAMAS DE CONSERVACIÓN Y MANJEO DE LAS ANPS, A MI CARGO.', '90', 'PARTICIPAR EN 10 REUNIONES CON AUTORIDADES ESTATALES Y FEDERALES, TANTO DEL SECTOR AMBIENTAL COMO EL SECTOR ECONÓMICO Y PRODUCTIVO, PARA DAR ATENCIÓN Y SEGUIMIENTOS A TEMAS INHERENTES A LAS ANPS: RESERVA DE LA BIOSFERA BALAM KÚ Y ÁREA DE PROTECCIÓN DE FLORA Y FAUNA BALAM KIN,', '01', '30', 'PARTICIPAR EN 9 REUNIONES CON AUTORIDADES FEDERALES Y MUNICIPALES', 'PARTICIPAR EN 5 REUNIONES CON AUTORIDADES FEDERALES Y MUNICIPALES', 'PARTICIPAR EN 2 REUNIONES CON AUTORIDADES FEDERALES Y MUNICIPALES', '90', 'CONVOCAR Y FORMAR EL CONSEJO ASESOR DE LAS ÁREAS NATURALES PROTEGIDAS, RESERVA DE LA BIOSFERA BALAM KÚ Y ÁREA DE PROTECCIÓN DE FLORA Y FAUNA BALAM KIN,', '01', '10', 'CONVOCAR Y FORMAR EL CONSEJO ASESOR DE LAS ANPS, BAJO MI ADMINISTR