INSERT INTO `sed_individuales` VALUES (413, 'PISI571215', 'REALIZAR UN CONTROL DE LAS CÉDULAS CORRESPONDIENTES A EVALUACIÓN DEL DESEMPEÑO Y METAS INDIVIDUALES PARA LOS SERVIDORES PUBLICOS DE CARRERA', '07', '25', 'CONCLUIR DEL 100 AL 80% DE LA INFORMACION', '79-60 DE LA INFORMACION', 'MENOS DEL 50%', '90', 'APOYAR EN LOS INFORMES TRIMESTRALES SOBRE LOS PROCESOS DEL SERVICIO PROFESIONAL DE CARRERA EN MATERIA DE CAPACITACIÓN', '07', '25', 'CONCLUIR EL 100 AL 80%DE LOS REGISTROS DE ACCIONES DE CAPACITACION', 'CONCLUIR DEL 76 AL 60% DE LOS REGISTROS DE ACCIONES DE CAPACITACIÓN.', 'CONCLUIR MENOS DEL 59% DE LOS REGISTROS DE ACCIONES DE CAPACITACIÓN', '90', 'APOYAR EN EL REGISTRO ANTE LA SFP A LOS SERVIDORES PUBLICOS QUE SE TIENEN QUE CERTIFICAR CADA CINCO AÑOS', '07', '25', 'REGISTRAR DEL 100 AL 80 % DE LAS CERTIFICACIONES DE TODOS LOS SPC.', 'REGISTRAR LAS CERTIFICACIONESDE TODOS LOS SPC, DESPUÉS DE LA FECHA ESTABLECIDA POR LA SFP', 'NO REGISTRAR LAS CERTIFICACIONES DE TODOS LOS SPC.', '90', 'ACTUALIZAR Y MODIFICAR LOS DATOS DE LOS USUARIOS EN EL SISTEMA DE EVALUACION DEL DESEMPEÑO PARA SERVIDORES PUBLICOS DE CARRERA TITULARES CON BASE A LAS SOLICITUDES RECIBIDAS EN EL ÁREA', '07', '25', 'ATENDER DEL 100 AL 80% DE LAS SOLICITUDES', 'APOYO DEL 79 AL 60% DE LAS SOLICITUDES', 'APOYO DE MENOS DEL 59% DE LAS SOLICITUDES', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (414, 'PITA801001', 'ELABORAR Y EJECUTAR EL PROGRAMA OPERATIVO ANUAL DEL ÁREA NATURAL PROTEGIDA VINCULADO A LOS SUBPROGRAMAS DEL PROGRAMA DE MANEJO, ASÍ TAMBIÉN ELABORAR EN TIEMPO Y FORMA LOS INFORMES TRIMESTRALES DE LAS ACCIONES REALIZADAS Y CAPTURARLAS EN EL SISTEMA INFORMÁTICO DISEÑADO PARA TAL FIN.', '01', '20', 'UN PROGRAMA OPERATIVO ANUAL ELABORADO Y EJECUTADO, CON SUS CUATRO INFORMES TRIMESTRALES CAPTURADOS VÍA SISTEMA INFORMÁTICO.', 'UN PROGRAMA OPERATIVO ANUAL ELABORADO Y EJECUTADO, CON DOS INFORMES TRIMESTRALES CAPTURADOS VÍA SISTEMA INFORMÁTICO.', 'UN PROGRAMA OPERATIVO ANUAL ELABORADO Y EJECUTADO, CON UN INFORME TRIMESTRAL CAPTURADO VÍA SISTEMA INFORMÁTICO.', '90', 'FUNGIR COMO SECRETARÍA TÉCNICA DEL CONSEJO ASESOR DEL ÁREA NATURAL PROTEGIDA Y COORDINAR AL MENOS DOS REUNIONES AL AÑO, ASÍ COMO DAR SEGUIMIENTO A LAS ACTIVIDADES QUE SE DERIVEN DE LOS ACUERDOS DEL MISMO.', '01', '20', 'FUNGIR COMO SECRETARÍA TÉCNICA DEL CONSEJO ASESOR DEL ÁREA NATURAL PROTEGIDA, COORDINAR AL MENOS DOS REUNIONES AL AÑO Y DAR SEGUIMIENTO AL 100% DE LAS ACTIVIDADES QUE SE DERIVEN DE LOS ACUERDOS DEL MISMO.', 'FUNGIR COMO SECRETARÍA TÉCNICA DEL CONSEJO ASESOR DEL ÁREA NATURAL PROTEGIDA, COORDINAR AL MENOS UNA REUNIÓN AL AÑO Y DAR SEGUIMIENTO AL 50% DE LAS ACTIVIDADES QUE SE DERIVEN DE LOS ACUERDOS DEL MISMO.', 'NO CELEBRAR NINGUNA REUNIÓN DE CONSEJO ASESOR AL AÑO.', '90', 'PROMOVER Y EJECUTAR LOS PROGRAMAS DE SUBSIDIOS Y PROYECTOS DE CONSERVACIÓN PARA EL DESARROLLO DEL ÁREA NATURAL PROTEGIDA, ASÍ COMO PARTICIPAR EN LOS PROGRAMAS, PROYECTOS Y ACCIONES DE CONSERVACIÓN DE ESPECIES Y POBLACIONES EN RIESGO Y ESPECIES PRIORITARIAS PARA LA CONSERVACIÓN DEL ÁREA NATURAL PROTEGIDA.', '10', '20', 'SE PROMOVIERON Y EJECUTARON EL 100% DE LOS PROGRAMAS DE SUBSIDIOS Y PROYECTOS DE CONSERVACIÓN PARA EL DESARROLLO DEL ÁREA NATURAL PROTEGIDA, ASÍ COMO LOS PROGRAMAS, PROYECTOS Y ACCIONES DE CONSERVACIÓN DE ESPECIES Y POBLACIONES EN RIESGO Y ESPECIES PRIORITARIAS PARA LA CONSERVACIÓN DEL ÁREA NATURAL PROTEGIDA.', 'SE PROMOVIERON Y EJECUTARON EL 50% DE LOS PROGRAMAS DE SUBSIDIOS Y PROYECTOS DE CONSERVACIÓN PARA EL DESARROLLO DEL ÁREA NATURAL PROTEGIDA, ASÍ COMO LOS PROGRAMAS, PROYECTOS Y ACCIONES DE CONSERVACIÓN DE ESPECIES Y POBLACIONES EN RIESGO Y ESPECIES PRIORITARIAS PARA LA CONSERVACIÓN DEL ÁREA NATURAL PROTEGIDA.', 'SE PROMOVIERON Y EJECUTARON EL 10% DE LOS PROGRAMAS DE SUBSIDIOS Y PROYECTOS DE CONSERVACIÓN PARA EL DESARROLLO DEL ÁREA NATURAL PROTEGIDA, ASÍ COMO LOS PROGRAMAS, PROYECTOS Y ACCIONES DE CONSERVACIÓN DE ESPECIES Y POBLACIONES EN RIESGO Y ESPECIES PRIORITARIAS PARA LA CONSERVACIÓN DEL ÁREA NATURAL PROTEGIDA.', '90', 'EMITIR DICTÁMENES TÉCNICOS DE SOPORTE ANTE LA PERSONA TITULAR DE LA COMISIÓN, LA DIRECCIÓN GENERAL DE OPERACIÓN REGIONAL O LA DIRECCIÓN REGIONAL QUE CORRESPONDA, PARA EL OTORGAMIENTO, MODIFICACIÓN, PRÓRROGA, RESCATE, SUSPENSIÓN, EXTINCIÓN, REVOCACIÓN O ANULACIÓN DE CONCESIONES, PERMISOS, LICENCIAS O AUTORIZACIONES EN MATERIA DE INVESTIGACIÓN, USO Y APROVECHAMIENTO DE LOS ECOSISTEMAS Y SU BIODIVERSIDAD, ASÍ COMO PARA EMITIR LA OPINIÓN QUE CORRESPONDA EN MATERIA DE EVALUACIÓN DEL IMPACTO AMBIENTAL, FORESTAL, VIDA SILVESTRE, CAMBIO DE USO DE SUELO EN TERRENOS FORESTALES, PRESTACIÓN DE SERVICIOS Y EJECUCIÓN DE OBRAS Y ACTIVIDADES QUE SE REALICEN EN EL ÁREA NATURAL PROTEGIDA, ASÍ COMO PARA EL ORDENAMIENTO ECOLÓGICO CORRESPONDIENTE.', '10', '20', 'SE EMITIÓ EL 100% DE LAS SOLICITUDES DE DICTÁMENES TÉCNICOS.', 'SE EMITIÓ EL 50% DE LAS SOLICITUDES DE DICTÁMENES TÉCNICOS.', 'SE EMITIÓ EL 10% DE LAS SOLICITUDES DE DICTÁMENES TÉCNICOS.', '90', 'ATENDER LAS CONTINGENCIAS AMBIENTALES QUE SUCEDAN EN EL ÁREA NATURAL PROTEGIDA Y SU ZONA DE INFLUENCIA, EN COORDINACIÓN CON LAS AUTORIDADES COMPETENTES.', '10', '20', 'SE ATENDIÓ EL 100% DE LAS CONTINGENCIAS AMBIENTALES QUE SE PRESENTARON EN EL ÁREA NATURAL PROTEGIDA Y SU ZONA DE INFLUENCIA, EN COORDINACIÓN CON LAS AUTORIDADES COMPETENTES.', 'SE ATENDIÓ EL 50% DE LAS CONTINGENCIAS AMBIENTALES QUE SE PRESENTARON EN EL ÁREA NATURAL PROTEGIDA Y SU ZONA DE INFLUENCIA, EN COORDINACIÓN CON LAS AUTORIDADES COMPETENTES.', 'SE ATENDIÓ EL 10% DE LAS CONTINGENCIAS AMBIENTALES QUE SE PRESENTARON EN EL ÁREA NATURAL PROTEGIDA Y SU ZONA DE INFLUENCIA, EN COORDINACIÓN CON LAS AUTORIDADES COMPETENTES.', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
