INSERT INTO `sed_individuales` VALUES (425, 'RAED900427', 'GENERAR, ANALIZAR Y SISTEMATIZAR BASES DE DATOS E INFORMACIÓN COMO HERRAMIENTA PARA EL MANEJO DE LA BIODIVERSIDAD QUE ALBERGA EL ÁREA NATURAL PROTEGIDA.', '10', '30', '80 A 100', '60 A 79', '59 O MENOS DE 59', '90', 'APOYAR EN LA PLANEACIÓN Y EJECUCIÓN DE LOS PROGRAMAS DE SUBSIDIO ASEGURANDO EL CUMPLIMIENTO NORMATIVO Y LA CONSECUCIÓN DE LAS ACTIVIDADES Y LA ADECUADA OPERACIÓN DEL ANP.', '10', '30', '80 A 100', '60 A 79', '59 O MENOS DE 59', '90', 'CONTRIBUIR EN EL DISEÑO Y OPERACIÓN DE LA ESTRATEGIA DE EDUCACIÓN PARA LA CONSERVACIÓN Y COMUNICACIÓN SOCIAL, CON LA FINALIDAD DE SENSIBILIZAR A LOS USUARIOS Y HABITANTES DE LA ZONA DE INFLUENCIA DE LA RESERVA.', '10', '20', '80 A 100', '60 A 79', '59 O MENOS DE 59', '90', 'LA DEMÁS QUE LE CONFIERA Y/O INSTRUYA SU JEFE INMEDIATO, EL DIRECTOR DEL ANP, EL DIRECTOR REGIONAL, LA UNIDAD ADMINISTRATIVA, LA UNIDAD TÉCNICA O LA UNIDAD JURÍDICA DE LA DIRECCIÓN REGIONAL, ASÍ COMO LAS QUE SEÑALEN LAS DISPOSICIONES LEGALES Y REGLAMENTARIAS VIGENTES DENTRO DE SU ALCANCE Y MARCO DE ACTUACIÓN ORIENTADAS A ASEGURAR LA ADECUADA OPERACIÓN DEL ANP, DE LA DIRECCIÓN REGIONAL Y DE LA CONSERVACIÓN DEL MEDIO AMBIENTE.', '10', '20', '80 A 100', '60 A 79', '59 O MENOS DE 59', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
