INSERT INTO `sed_individuales` VALUES (438, 'ROAI790404', 'ELABORACIÓN Y CONTROL DE LISTAS DE ASISTENCIAL DEL PERSONAL QUE LABORA EN LA OFICINA DE LA DIRECCIÓN REGIONAL OCCIDENTE Y PACIFICO CENTRO, CONSOLIDACIÓN DE FORMATOS DE CONTROL DE LISTAS DE ASISTENCIA E INCIDENCIAS DE ÁREAS ADSCRITAS A LA DIRECCIÓN REGIONAL OCCIDENTE Y PACÍFICO CENTRO, ENVÍO DE SOLICITUDES', '02', '20', 'ARCHIVO DE REGISTRO DE LISTAS DE ASISTENCIA FIRMADAS CON INCIDENCIAS IDENTIFICADAS AL 100%, ENVIAR LAS LICENCIAS MÉDICAS Y FORMATOS DE VACACIONES A TIEMPO.', 'ARCHIVO DE REGISTRO DE LISTAS DE ASISTENCIA FIRMADAS Y CON INCIDENCIAS IDENTIFICADAS AL 90 %, ENVIAR LAS LICENCIAS MÉDICAS Y SOLICITUDES DE VACACIONES EN FECHAS POSTERIORES', 'ARCHIVO DE REGISTRO DE LISTA DE ASISTENCIA FIRMADAS CON INCIDENCIAS AL 70%, NO ENVIAR LAS LICENCIAS Y SOLICITUDES DE VACACIONES Y DÍAS ECONÓMICOS A OFICINAS CENTRALES', '90', 'RECEPCIÓN Y ENTREGA DE DOCUMENTOS COMO CONSTANCIAS DE NOMBRAMIENTO, CONSTANCIAS DE SERVICIO ACTIVO Y ALTAS AL ISSSTE, DEL PERSONAL QUE ELABORA EN LA DIRECCIÓN REGIONAL OCCIDENTE Y PACIFICO CENTRO, APOYO EN LA APLICACIÓN EVALUACIONES EN LOS CONCURSOS DE PLAZAS QUE SE ESTÁN CONCURSANDO Y ENVIÓ POR CORREO ELECTRÓNICO Y EN FÍSICO DE LA DOCUMENTACIÓN, CONTROL DE LOS MINUTARIOS DE OFICIOS ENTREGA DE NÚMEROS DE OFICIOS Y ARCHIVAR ACUSES DE RECIBIDO.', '02', '20', 'ENTREGA DE DOCUMENTACIÓN A INTERESADOS PARA FIRMAR Y ENVÍO A OFICINAS CENTRALES CON UNA ANTIGÜEDAD NO MAYOR A 15 DÍAS, ENVIAR POR CORREO ELECTRONICO LA DOCUMENTACION DE LOS PARTICIPANTES EN EL MISMO DÍA QUE SE PRESENTAN A REALIZAR SUS EVALUACIONES.', 'ENTREGA DE DOCUMENTACIÓN A LOS INTERESADOS PARA FIRMAR Y ENVÍO A OFICINAS CENTRALES CON UNA ANTIGÜEDAD NO MAYOR A 10 DÍAS, ENVIAR LA DOCUMENTACIÓN DE LOS PARTICIPANTES DOS DÍAS DESPUÉS DE SU PARTICIPACIÓN.', 'ENTREGA DE DOCUMENTACIÓN A LOS INTERESADOS PARA FIRMAR Y ENVÍO A OFICINAS CENTRALES CON UNA ANTIGÜEDAD MAYOR A 10 DÍAS, ENVIAR LA DOCUMENTACIÓN DE LOS PARTICIPANTES 3 DESPUÉS DE SU PARTICIPACIÓN.', '100', 'APOYO EN EL SEGUIMIENTO A LAS CAPACITACIONES DEL PERSONAL QUE LABORA EN LA DIRECCIÓN REGIONAL OCCIDENTE DURANTE EL AÑO 2024, PARA EL CUMPLIMIENTO DE LAS 40 HORAS, Y DAR SEGUIMIENTO EN EL ENVÍO DE CONSTANCIAS DE LOS CURSOS TOMADOS DURANTE EL AÑO POR CORREO ELECTRÓNICO A OFICINAS CENTRALES, Y APOYAR AL PERSONAL SI TIENEN DUDAS O PROBLEMAS PARA INSCRIBIRSE EN LA PLATAFORMA.', '02', '20', 'MANTENER LA BASE DE DATOS ACTUALIZADA Y ENVIAR POR CORREO ELECTRÓNICO A OFICINAS CENTRALES LAS CONSTANCIAS DE LOS CURSOS RECIBIDOS DEL PERSONAL Y ORIENTAR AL PERSONAL PARA QUE LOS SUBAN A LA PLATAFORMA EN LOS TIEMPOS ESTABLECIDO.', 'NO ACTUALIZAR BASE DE DATOS CON EL ENVÍO DE LOS CORREOS ELECTRÓNICOS DE LAS CONSTANCIAS DE LOS CURSOS DEL PERSONAL EN LOS TIEMPOS ESTABLECIDOS POR OFICINAS CENTRALES.', 'NO REALIZAR EL SEGUIMIENTO Y NO ENVIAR LAS CONSTANCIAS DE LOS CURSOS DEL PERSONAL QUE LABORA EN LA DIRECCIÓN REGIONAL OCCIDENTE Y PACÍFICO CENTRO.', '90', 'ENVÍO DE CEDULAS DE METAS Y EVALUACIÓN DE DESEMPEÑO DEL PERSONAL OPERATIVO NIVELES 5 AL 11, Y ENLACES NIVEL DE P12 A HASTA NIVEL MANDOS MEDIOS, ENVÍO DE CEDULAS DEL EMPLEADO DEL MES, POR SEMESTRES, SOLICITUDES DE APOYO DE LENTES, ENVIÓ DE FORMATOS DE DÍAS ECONÓMICOS, SOLICITUD DE VACACIONES , FORMATOS DEL SEGURO DE VIDA Y DESIGNACIÓN DE BENEFICIARIOS, ENVÍO DE PROPUESTAS DE PREMIO DE PRODUCTIVIDAD, TRIMESTRALES Y DE PUNTUALIDAD Y ASISTENCIA, ACUSES DE LA DECLARACIÓN PATRIMONIAL DE MODIFICACIÓN 2023, ELABORACIÓN Y ENVÍO DE FORMATOS DEL PADRÓN DE DÍA DEL NIÑO, DÍA DE LA MADRE, DÍA DEL PADRE Y DÍA DE REYES, ENTREGA DE VALES DE DISPENSA O TARJETAS DE DESPENSA POR OBSEQUIO Y FESTEJO DE FIN DE AÑO, Y VALES POR MEDIDAS DE FIN DE AÑO, ENVIAR ACUSES DE RECIBIDO A OFICINAS CENTRALES', '02', '20', 'ENVIAR LAS SOLICITUDES DEL PERSONAL RELACIONADAS AL ÁREA A CARGO, EN LAS FECHAS ESTABLECIDAS O ANTES DEL VENCIMIENTO.', 'ENVIAR LAS SOLICITUDES DEL PERSONAL RELACIONADA AL ÁREA A CARGO, 2 DÍAS HÁBILES DESPUÉS DE FECHA ESTABLECIDA.',