INSERT INTO `sed_individuales` VALUES (446, 'ROII690831', 'DIFUNDIR INFORMACIÓN SOBRE LAS ACTIVIDADES EN LAS ÁREAS NATURALES PROTEGIDAS ADSCRITAS A LA REGIONAL NOROESTE Y ALTO GOLFO, SOCIALIZANDO LA LABOR DE LA CONANP, LA IMPORTANCIA DE LAS ÁREAS NATURALES PROTEGIDAS, FLORA, FAUNA Y LOS SERVICIOS AMBIENTALES, IMPACTOS ANTROPOGÉNICOS, EN DIVERSOS FOROS DONDE PARTICIPAMOS COMO ORGANIZADORES O CO-ORGANIZADORES O INVITADOS, DANDO SEGUIMIENTO AL CONVENIO SIGANADO ENTRE SEMARNAT Y SEP, COMO CONGRESOS, FERIAS AMBIENTALES,Y OTROS FOROS Y/O APOYAR A LAS ANPS EN LA CONCEPCIÓN DE IDEAS Y DIFUSIÓN DE SUS EVENTOS Y/O GENERAR DIVERSAS COLABORACIONES PARA LAS PLATAFORMAS DE DIFUSIÓN Y COMUNICACIÓN DE CONANP COMO EL AULLADOR, EL BLOG, COMUNICADOS DE PRENSA, CONTENIDO PARA FACEBOOK CONANP, ENTRE OTROS Y/O PARTICIPANDO CON OTRAS INSTITUCIONES EN FORTALECIMIENTO DE LA EDUCACIÓN AMBIENTAL', '01', '25', 'LLEVAR A CABO MÁS DE 12 ACCIONES ABORDANDO UNO DE ESTOS TEMAS RELACIONADOS CON DIFUSIÓN, COMUNICACIÓN, IDENTIDAD Y CULTURA PARA LA CONSERVACIÓN', 'LLEVAR A CABO MÁS DE ENTRE 8 Y 11 ACCIONES ABORDANDO UNO DE ESTOS TEMAS RELACIONADOS CON DIFUSIÓN, COMUNICACIÓN, IDENTIDAD Y CULTURA PARA LA CONSERVACIÓN', 'LLEVAR A CABO MENOS DE 7 ACCIONES ABORDANDO UNO DE ESTOS TEMAS RELACIONADOS CON DIFUSIÓN, COMUNICACIÓN, IDENTIDAD Y CULTURA PARA LA CONSERVACIÓN', '90', 'COMO ENLACE DEL TEMA DE TURISMO EN ÁREAS NATURALES PROTEGIDAS, DAR SEGUIMIENTO A LAS SOLICITUDES DE INFORMACIÓN POR PARTE DE OFICINAS CENTRALES EN ESTE TEMA, DAR INFORMACIÓN A LOS PRESTADORES DE SERVICIO SOBRE LA REGULARIZACIÓN DE SUS ACTIVIDADES DENTRO DE LAS ANPS, SOCIALIZAR LAS BUENAS PRÁCTICAS Y EL TURISMO RESPONSABLE EN DIVERSOS FOROS Y EVENTOS ORGANIZADOS POR CONANP O COMO INVITADOS PARA, ASI COMO CONCIENTIZAR SOBRE LA IMPORTANCIA DEL PAGO DE DERECHOS COMO USUARIO /VISITANTE DE LAS ANPS.', '01', '20', 'LLEVAR A CABO MÁS DE 5 ACCIONES ABORDANDO UNO DE ESTOS TEMAS RELACIONADOS EL TEMA DE TURISMO EN ANPS', 'LLEVAR A CABO ENTRE 3 Y 5 ACCIONES ABORDANDO UNO DE ESTOS TEMAS RELACIONADOS EL TEMA DE TURISMO EN ANPS', 'LLEVAR A CABO MENOS DE 3 ACCIONES AABORDANDO UNO DE ESTOS TEMAS RELACIONADOS EL TEMA DE TURISMO EN ANPS', '90', 'DAR SEGUIMIENTO AL PROGRAMA OPERATIVO ANUAL EN TIEMPO Y FORMA, ASÍ COMO LOS INFORMES DE AVANCES PARCIALES TRIMESTRALES ALCANZADOS POR LOS DEPARTAMENTOS QUE INTEGRAN ESTA DIRECCIÓN Y APOYO Y SEGUIMIENTO AL AVANCE EN LA CAPTURA DE LAS ANPS ADSCRITAS A ESTA DR DE SUS RESPECTIVOS POAS, O EN SU CASO DAR SEGUIMIENTO A LA PRESENTACIÓN DE INDICADORES GO13 PARA REPORTES RESPECTIVOS EN CASO DE QUE LA PLATAFORMA DE SGPOA NO ESTE DISPONIBLE', '10', '20', 'POR ENCIMA DEL 95% DE RESPUESTA Y/O SEGUIMIENTO A LA PLATAFORMA DE CAPTURA SGPOA', 'ENTRE EL 80 AL 94% DE RESPUESTA Y/O SEGUIMIENTO A LA PLATAFORMA DE CAPTURA SGPOA', 'MENOS DEL 79% DE RESPUESTA Y/O SEGUIMIENTO A LA PLATAFORMA DE CAPTURA SGPOA', '90', 'DAR SEGUIMIENTO Y RESPUESTA EN TIEMPO Y FORMA A SOLICITUDES REQUERIDAS POR LA DIRECCIÓN DE OPERACIÓN REGIONAL Y OTROS DEPARTAMENTOS DE OFICINAS CENTRALES Y/O LAS AREAS NATURALES PROTEGIDAS COMO ENLACE DE CONSEJOS ASESORES , TURISMO EN ANPS, SIRENASE, PROGRAMA JÓVENES CONSTRUYENDO EL FUTURO, PROGRAMA OPERATIVO ANUAL, DECRETO GLIFOSATO, INDICE DE PARTICIPACIÓN CIUDADANA, LOGROS ANUALES, ENTRE OTROS', '10', '15', 'POR ENCIMA DEL 90% DE RESPUESTA Y/O SEGUIMIENTO A LAS SOLCITUDES DE PARTE DE OFICINAS CENTRALES', 'ENTRE EL 60 AL 89% DE RESPUESTA Y/O SEGUIMIENTO A LA PLATAFORMA DE CAPTURA SGPOA', 'MENOS DEL 60% DE RESPUESTA Y/O SEGUIMIENTO A LA PLATAFORMA DE CAPTURA SGPOA', '90', 'PARTICIPAR EN DIVERSAS REDES DE EDUCADORES AMBIENTALES COMO CECADESU Y LA RED SONORENSE DE EDUCACIÓN AMBIENTAL (REDSEA) Y/O ESTABLECER UNA RED DE EDUCACIÓN AMBIENTAL DE LA REGIONAL NO Y AGC PARA COMPARTIR AGENDA, PLANES DE TRABAJO Y MATERIALES EDUCATIVOS Y/O COORDINAR LOS INTERCAMBIOS DE EXPERIENCIA DE LA REGIONAL NOROESTE Y ALTO GOLFO PARA CONTINUAR CON EL PROCESO DE CAPACITACIÓN CONTINUA DEL PERSONAL ADSCRITO A ESTA REGIONAL Y/O INVITAR EXPERTOS EXTERNOS PARA IMPARTIR CHARLAS AL PERSONAL Y/O PROMOVER Y DAR A CONOCER LOS EVENTOS ORGANIZADOS POR OTRAS INSTITUCIONES CON TEMAS DE INTERÉS Y FORMATIVOS PARA EL PERSONAL DE CONANP Y7O BRINDAR APOYO Y/O ASESORÍA A LAS ANPS EN TEMAS RELACIONADOS CON DIFUSIÓN Y CULTURA PARA LA CONSERVACIÓN, ATENCIÓN A MEDIOS DE COMUNICACIÓN', '01', '20', 'LLEVAR A CABO MÁS DE 6 ACCIONES RELACIONADAS CON LOS TEMAS DE ESTA META', 'LLEVAR A CABO MÁS DE ENTRE 3 Y 5 ACCIONES RELACIONADAS CON LOS TEMAS DE ESTA META', 'LLEVAR A CABO MENOS DE 2 ACCIONESS RELACIONADAS CON LOS TEMAS DE ESTA META', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (447, 'ROLA820530', 'LLEVAR A CABO LOS CONTROLES ADMINISTRATIVOS DE RECURSOS HUMANOS DEL ANP CONFORME A LOS PROCEDIMIENTOS Y REGISTROS DOCUMENTALES ESTABLECIDOS POR LA CONANP ( NUEVO INGRESO, REGISTRO DE ASISTENCIA, SEGUROS, ETC), ASÍ COMO DE LAS ACTIVIDADES DE LOS VOLUNTARIOS, PRESTADORES DE SERVICIO SOCIAL Y PASANTIAS QUE COLABORAN EN LAS ACCIONES DE CONSERVACIÓN DEL ÁREA PROTEGIDA', '10', '40', 'SE REALIZARON DEL 100 AL 90% DE LOS CONTROLES ADMINISTRATIVOS DE RECURSOS HUMANOS DEL ANP CONFORME A LOS PROCEDIMIENTOS Y REGISTROS DOCUMENTALES ESTABLECIDOS POR LA CONANP, ASÍ COMO DE LAS ACTIVIDADES DE LOS VOLUNTARIOS, PRESTADORES DE SERVICIO SOCIAL Y PASANTIAS QUE COLABORAN EN LAS ACCIONES DE CONSERVACIÓN DEL ÁREA PROTEGIDA', 'SE REALIZARON DEL 89 AL 70% DE LOS CONTROLES ADMINISTRATIVOS DE RECURSOS HUMANOS DEL ANP CONFORME A LOS PROCEDIMIENTOS Y REGISTROS DOCUMENTALES ESTABLECIDOS POR LA CONANP, ASÍ COMO DE LAS ACTIVIDADES DE LOS VOLUNTARIOS, PRESTADORES DE SERVICIO SOCIAL Y PASANTIAS QUE COLABORAN EN LAS ACCIONES DE CONSERVACIÓN DEL ÁREA PROTEGIDA', 'SE REALIZARON MENOS 70% DE LOS CONTROLES ADMINISTRATIVOS DE RECURSOS HUMANOS DEL ANP CONFORME A LOS PROCEDIMIENTOS Y REGISTROS DOCUMENTALES ESTABLECIDOS POR LA CONANP, ASÍ COMO DE LAS ACTIVIDADES DE LOS VOLUNTARIOS, PRESTADORES DE SERVICIO SOCIAL Y PASANTIAS QUE COLABORAN EN LAS ACCIONES DE CONSERVACIÓN DEL ÁREA PROTEGIDA', '90', 'APOYAR A LA DIRECCIÓN EN LOS CONTROLES ADMINISTRATIVOS REQUERIDOS PARA LA APLICACIÓN DE RECURSOS EXTERNOS (FANP) ASIGNADOS AL ANP', '10', '40', 'SE REALIZARON DEL 100 AL 90% LOS CONTROLES ADMINISTRATIVOS REQUERIDOS PARA LA APLICACIÓN DE RECURSOS EXTERNOS (FANP) ASIGNADOS AL ANP', 'SE REALIZARON DEL 89 AL 70% , LOS CONTROLES ADMINISTRATIVOS REQUERIDOS PARA LA APLICACIÓN DE RECURSOS EXTERNOS (FANP) ASIGNADOS AL ANP', 'SE REALIZARON MENOS 70% , LOS CONTROLES ADMINISTRATIVOS REQUERIDOS PARA LA APLICACIÓN DE RECURSOS EXTERNOS (FANP) ASIGNADOS AL ANP', '90', 'ATENCIÓN DE VENTANILLA PARA ORIENTACIÓN A USUARIOS Y RECEPCIÓN DE DOCUMENTOS INGRESADOS PARA ATENCIÓN DE LA DIRECCIÓN DEL ANP ISLAS DEL GOLFO DE CALIFORNIA, DE LA DIRECCIÓN ENCARGADA DEL DESPACHO DE SANTUARIO PLAYA CEUTA, ASÍ COMO DE LA DIRECCIÓN REGIONAL NORORESTE Y ALTO GOLFO DE CALIFORNIA', '10', '20', 'SE ATENDIÓ AL 100-90% DE LOS USUARIOS Y RECEPCIÓN DE DOCUMENTOS INGRESADOS PARA ATENCIÓN DE LA DIRECCIÓN DEL ANP ISLAS DEL GOLFO DE CALIFORNIA, DE LA DIRECCIÓN ENCARGADA DEL DESPACHO DE SANTUARIO PLAYA CEUTA, ASÍ COMO DE LA DIRECCIÓN REGIONAL NORORESTE Y ALTO GOLFO DE CALIFORNIA', 'SE ATENDIÓ AL 89-70% DE LOS USUARIOS Y RECEPCIÓN DE DOCUMENTOS INGRESADOS PARA ATENCIÓN DE LA DIRECCIÓN DEL ANP ISLAS DEL GOLFO DE CALIFORNIA, DE LA DIRECCIÓN ENCARGADA DEL DESPACHO DE SANTUARIO PLAYA CEUTA, ASÍ COMO DE LA DIRECCIÓN REGIONAL NORORESTE Y ALTO GOLFO DE CALIFORNIA', 'SE ATENDIÓ MENOS 70% DE LOS USUARIOS Y RECEPCIÓN DE DOCUMENTOS INGRESADOS PARA ATENCIÓN DE LA DIRECCIÓN DEL ANP ISLAS DEL GOLFO DE CALIFORNIA, DE LA DIRECCIÓN ENCARGADA DEL DESPACHO DE SANTUARIO PLAYA CEUTA, ASÍ COMO DE LA DIRECCIÓN REGIONAL NORORESTE Y ALTO GOLFO DE CALIFORNIA', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (448, 'ROLV530728', 'PROPORCIONAR EN LA EJECUCIÓN Y APOYO EN LA OPERACIÓN DE LOS PROGRAMAS DE PROCODES Y PROREST DE LA REGIÓN OCCIDENTE Y PACIFICO CENTRO CON FUNDAMENTO EN LA NORMATIVIDAD DE DICHOS PROGRAMAS', '01', '50', '100 AL 90 %', '89 AL 60 %', '59 AL 0.00 %', '90', 'SUPERVISAR Y VERIFICAR LOS AVANCES FÍSICO- FINANCIEROS ,QUE SE ENVÍAN MENSUAL Y TRIMESTRAL MENTE DE LAS ANP EN EL SISTEMA DE PROCODES DE LA DROPC ( DIRECCIÓN REGIONAL OCCIDENTE Y PACIFICO CENTRO)', '01', '30', '100 AL 90 %', '89 AL 60 %', '59 AL 0.00 %', '90', 'APOYO EN LA INTEGRACIÓN DE TODA LA INFORMACIÓN QUE SE REQUIERE PARA RESPONDER A LOS ÓRGANOS FISCALIZADORES EN LOS REQUERIMIENTOS DE LOS PROYECTOS DE APOYO EN LA DIRECCIÓN REGIONAL OCCIDENTE Y PACIFICO CENTRO', '02', '20', '100 AL 90 %', '89 AL 60%', '59 AL 0.00 %', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (449, 'ROMP700407', 'PARTICIPAR EN RECURRIDOS DE VIGILANCIA EN EL ANP', '10', '25', 'SE COLAVORO EN LA TOTALIDAD EN LOS RECORRIDOS REALIZADOS', 'SE COLABORO PARCIALMENTE EN LOS RECORRIDOS REALIZADOS', 'NO SE TUBO COLABORACIÓN EN LOS RECORRIDOS REALIZADOS', '90', 'PARTICIPAR EN EL CONTROL Y/O ERRADICACIÓN DEL CERDO ASILVESTRADO (SUSCROFA) EN EL ANP', '10', '25', 'SE PARTICIPO EN LAS ACCIONES DE CONTROL Y/O ERRADICACIÓN DEL CERDO ASILVESTRADO EN UN 90%', 'SE PARTICIPO EN ACCIONES DE CONTROL Y/O ERRADICACIÓN DE CERDO ASILVESTRADO EN UN 50%', 'EXISTIO UNA NULA PARTICIPACIÓN EN LAS ACCIONES DE CONTROL Y/O ERRADICACIÓN DEL CERDO ASILVESTRADO', '90', 'EJECUCIÓN DE LAS ACCIONES DE MANEJO INTEGRAL DEL FUEGO REALZADAS EN EL ANP', '04', '25', 'SE PARTICIPO EN EL TOTAL DE LAS ACCIONES DE MANEJO DEL FUEGO EN EL ANP', 'SE PARTICIPO DE MANERA PARCIAL EN LAS ACCIONES DE MANEJO INTEGRAL DEL FUEGO EN EL ANP', 'NO SE PARTICIPO EN NINGUNA DE LAS ACCIONES DE MANEJO INTEGRAL DEL FUEGO EN EL ANP', '90', 'PARTICIPAR EN LA OPERACIÓN DE PROGRAMAS DE SUBSIDIO', '04', '25', 'SE PARTICIPO EN EL TOTAL DE LOS PROGRAMAS DE SUBSIDIOS DENTRO DEL ÁREA DEL ANP', 'SE PARTICIPO EN LOS PROGRAMAS DE SUBSIDIOS DE MANERA PARCIAL EN EL ANP', 'NO SE PARTICIPO EN LOS PROGRAMAS DE SUBSIDIOS EN EL ANP', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (450, 'ROMS811215', 'VERIFICAR LA CORRECTA INTEGRACIÓN DE EXPEDIENTES DE LOS PROGRAMAS DE PROCODES Y PROREST EN EL ANP RESERVA DE LA BIÓSFERA SIERRA DE MANANTLÁN.', '10', '25', 'INTEGRACIÓN DE EXPEDIENTES DE PROCODES Y PROREST EN UN 90% A 100%.', 'INTEGRACIÓN DE EXPEDIENTES DE PROCODES Y PROREST EN UN 70% A 89%.', 'INTEGRACIÓN DE EXPEDIENTES DE PROCODES Y PROREST EN UN 0% A 69%.', '90', 'REGISTRAR MENSUAL Y TRIMESTRALMENTE EL AVANCE FÍSICO-FINANCIERO DE LOS PROGRAMAS DE PROCODES Y PROREST OPERADOS EN EL ANP RESERVA DE LA BIÓSFERA SIERRA DE MANANTLÁN.', '10', '25', 'REGISTRO DE AVANCES FÍSICO-FINANCIERO DE LOS PROGRAMAS DE PROCODES Y PROREST EN UN 90% A 100%.', 'REGISTRO DE AVANCES FÍSICO-FINANCIERO DE LOS PROGRAMAS DE PROCODES Y PROREST EN UN 70% A 89%.', 'REGISTRO DE AVANCES FÍSICO-FINANCIERO DE LOS PROGRAMAS DE PROCODES Y PROREST EN UN 0% A 69%.', '90', 'OPERAR Y DAR SEGUIMIENTO A PROYECTOS RELATIVOS AL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE (PROCODES) Y PROREST EN EL ANP RESERVA DE LA BIÓSFERA SIERRA DE MANANTLÁN.', '01', '20', 'OPERACIÓN Y SEGUIMIENTO A PROYECTOS DEL PROCODES Y PROREST EN UN 90% A 100%.', 'OPERACIÓN Y SEGUIMIENTO A PROYECTOS DEL PROCODES Y PROREST EN UN 70% A 89%.', 'OPERACIÓN Y SEGUIMIENTO A PROYECTOS DEL PROCODES Y PROREST EN UN 0% A 69%.', '90', 'OPERAR Y DAR SEGUIMIENTO AL SISTEMA DE CONTRALORÍA SOCIAL DEL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE (PROCODES) Y PROREST EN EL ANP RESERVA DE LA BIÓSFERA SIERRA DE MANANTLÁN.', '01', '15', 'OPERACIÓN Y SEGUIMIENTO DE TODOS LOS PROYECTOS AUTORIZADOS DEL PROCODES Y PROREST EN EL SISTEMA DE CONTRALORÍA SOCIAL EN UN 90% AL 100%.', 'OPERACIÓN Y SEGUIMIENTO DE TODOS LOS PROYECTOS AUTORIZADOS DEL PROCODES Y PROREST EN EL SISTEMA DE CONTRALORÍA SOCIAL EN UN 70% AL 89%.', 'OPERACIÓN Y SEGUIMIENTO DE TODOS LOS PROYECTOS AUTORIZADOS DEL PROCODES Y PROREST EN EL SISTEMA DE CONTRALORÍA SOCIAL EN UN 0% AL 69%.', '90', 'COORDINAR Y DAR SEGUIMIENTO AL ESTABLECIMIENTO Y MANEJO DE LA AGROBIODIVERSIDAD EN COMUNIDADES CON PROCESOS DE TRANSICIÓN AGROECOLÓGICA EN EL ANP RESERVA DE LA BIÓSFERA SIERRA DE MANANTLÁN.', '01', '15', 'SEGUIMIENTO Y COORDINACIÓN CON 4 A 5 COMUNIDADES PARA EL ESTABLECIMIENTO Y MANEJO DE LA AGROBIODIVERSIDAD.', 'SEGUIMIENTO Y COORDINACIÓN CON 2 A 3 COMUNIDADES PARA EL ESTABLECIMIENTO Y MANEJO DE LA AGROBIODIVERSIDAD.', 'SEGUIMIENTO Y COORDINACIÓN CON 0 A 1 COMUNIDADES PARA EL ESTABLECIMIENTO Y MANEJO DE LA AGROBIODIVERSIDAD.', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (451, 'ROPL700318', 'CONDUCIR LAS EMBARCACIONES DE LA CONANP DE MANERA RESPONSABLE Y MANTENER LA SUPERVISIÓN Y REGISTRO DEL ESTADO FÍSICO-MECÁNICO QUE GUARDAN LAS EMBARCACIONES, EQUIPO DE NAVEGACIÓN, REMOLQUES Y VEHÍCULOS; INFORMAR DE MANERA OPORTUNA, CLARA Y FORMAL CUALQUIER INCONVENIENTE IDENTIFICADO. PRESTANDO ESPECIAL ATENCIÓN AL CUMPLIMIENTO DE NORMATIVIDAD Y REGLAS QUE ESTABLEZCA LA AUTORIDAD MARÍTIMA NACIONAL, CON EL FIN DE CUMPLIR CON LAS MEDIDAS DE SEGURIDAD A LA TRIPULACIÓN DURANTE LA NAVEGACIÓN.', '01', '40', 'EL TRABAJADOR CUMPLIÓ SATISFACTORIAMENTE (DEL 80 AL 100%) CON SUS LABORES COMO CAPITÁN DE EMBARCACIÓN, CUMPLIENDO CON LA NORMATIVIDAD DE LA AUTORIDAD MARÍTIMA NACIONAL (LIBRETA DE MAR VIGENTE) Y NOTIFICANDO DE MANERA OPORTUNA TODO LOS TEMAS DE INTERÉS', 'EL TRABAJADOR CUMPLE PARCIALMENTE CON SUS LABORES COMO CAPITÁN DE EMBARCACIÓN, YA QUE NOTIFICA LAS EVENTUALIDADES Y TEMAS DE INTERÉS, SIN EMBARGO, NO DA CUMPLIMIENTO A LA NORMATIVIDAD ESTABLECIDA POR LA AUTORIDAD MARÍTIMA NACIONAL, YA QUE NO CUENTA CON LIBRETA DE MAR VIGENTE..', 'EL TRABAJADOR NO CUMPLE CON SUS LABORES (DEL 0 AL 29%) COMO CAPITÁN DE EMBARCACIÓN, NO NOTIFICA U OMITE INFORMACIÓN IMPORTANTE RESPECTO AL USO DE LAS EMBARCACIONES Y NO CUBRE LOS REQUERIMIENTOS NECESARIOS PARA DAR CUMPLIMIENTO A LO ESTABLECIDO POR LA AUTORIDAD MARÍTIMA NACIONAL PARA EL CUMPLIMIENTO DE SUS FUNCIONES.', '60', 'APOYAR DE MANERA PROACTIVA EN LAS ACCIONES DE SUPERVISIÓN, OPERATIVOS INTERINSTITUCIONALES, MONITOREO, RESTAURACIÓN, CAPACITACIÓN, INVESTIGACIÓN, EDUCACIÓN AMBIENTAL Y ATENCIÓN A LOS PROGRAMAS DE SUBSIDIOS Y EN CUALQUIER OTRA ACTIVIDAD QUE ASÍ LO REQUIERA Y QUE ABONE EN EL CUMPLIMIENTO DEL PROGRAMA OPERATIVO ANUAL DEL ANP.', '02', '20', 'EL TRABAJADOR APOYA DE MANERA SUSTANCIAL EN EL DESARROLLO DE LA MAYORÍA DE LAS ACTIVIDADES ENLISTADAS, APORTANDO IDEAS, PARTICIPANDO EN LA PLANEACIÓN Y DESARROLLO Y GENERA LOS INFORMES DE MANERA DETALLADA, CLARA Y OPORTUNA.', 'EL TRABAJADOR APOYA PARCIALMENTE A LAS ACTIVIDADES, SIN EMBARGO ESTE NO OFRECE UN APOYO SUSTANCIAL O ES MÍNIMO Y/O LIMITADO. LOS INFORMES SON ENTREGADOS FUERA DE TIEMPO O NO CUENTAN CON LA CALIDAD MÍNIMA NECESARIA.', 'EL TRABAJADOR NO APOYA EN LAS ACTIVIDADES O SU APOYO SIEMPRE ES LIMITADO, EVITA PARTICIPAR. NO ENTREGA INFORMES EN TIEMPO Y FORMA CUANDO LE SON REQUERIDOS.', '70', 'REALIZAR ACCIONES DE MANTENIMIENTO PREVENTIVO BÁSICO A EQUIPAMIENTO E INSTALACIONES QUE CONFORMAN LAS ESTACIONES DE CAMPO (LIMPIEZA, LUBRICACIÓN, CAMBIO DE CARTUCHOS, ETC.) QUE PERMITAN ALARGAR LA VIDA ÚTIL DEL PATRIMONIO INSTITUCIONAL, ASÍ COMO EL REGISTRO OPORTUNO DE LA OPERACIÓN Y MANTENIMIENTOS DE EMBARCACIONES Y VEHÍCULOS, Y EN SU CASO, INFORMAR DEBIDAMENTE MEDIANTE EL USO DE FORMATOS Y/O BITÁCORAS CORRESPONDIENTES.', '10', '10', 'EL TRABAJADOR POR INICIATIVA PROPIA COLABORA EN EL 80-100% DE LAS ACCIONES DE MANTENIMIENTO PREVENTIVO DE LA HERRAMIENTA, EQUIPO E INMUEBLES QUE SON PARTE DEL PATRIMONIO DE LA INSTITUCIÓN, REGISTRA DE MANERA CLARA Y OPORTUNA LA INFORMACIÓN NECESARIA EN BITÁCORAS Y FORMATOS.', 'EL TRABAJADOR APOYA DE MANERA PARCIAL (30-79%) EN ACCIONES DE MANTENIMIENTO PREVENTIVO DE LA HERRAMIENTA Y EQUIPO EQUIPO E INMUEBLES, SOLO CUANDO SE LE REQUIERE, AUNQUE ESTE IDENTIFIQUE DICHA NECESIDAD ANTICIPADAMENTE. RARA VEZ REGISTRA DE MANERA CLARA Y OPORTUNA LA INFORMACIÓN NECESARIA EN BITÁCORAS Y FORMATOS.', 'EL TRABAJADOR APOYA DE MANERA MÍNIMA O NULA (0-29%) EN ACCIONES DE MANTENIMIENTO PREVENTIVO DE LA HERRAMIENTA Y EQUIPO SOLO CUANDO SE LE REQUIERE, AUNQUE ESTE IDENTIFIQUE DICHA NECESIDAD ANTICIPADAMENTE. RARA VEZ REGISTRA DE MANERA CLARA Y OPORTUNA LA INFORMACIÓN NECESARIA EN BITÁCORAS Y FORMATOS.', '70', 'DESARROLLAR LAS HABILIDADES Y CAPACIDADES NECESARIAS PARA FAVORECER EL DESARROLLO ADECUADO DE SUS FUNCIONES (USO DE PROGRAMAS BÁSICOS DE CÓMPUTO, HERRAMIENTAS Y DISPOSITIVOS TECNOLÓGICOS, REDACCIÓN Y LECTO-COMPRENSIÓN, CONOCIMIENTO DE PROGRAMA DE MANEJO E INSTRUMENTOS NORMATIVOS) A TRAVÉS DE LA CAPACITACIÓN CONTINUA', '10', '20', 'EL TRABAJADOR DESARROLLO SATISFACTORIAMENTE LAS HABILIDADES Y CAPACIDADES NECESARIAS PARA UN ADECUADO DESARROLLO DE SUS FUNCIONES, OBTENIENDO CONSTANCIA DE AL MENOS 3 CURSOS DE CAPACITACIÓN EN TEMAS MENCIONADOS EN LA META', 'EL TRABAJADOR DESARROLLO PARCIALMENTE LAS HABILIDADES Y CAPACIDADES NECESARIAS PARA UN ADECUADO DESARROLLO DE SUS FUNCIONES, OBTENIENDO CONSTANCIA DE AL MENOS 1 CURSOS DE CAPACITACIÓN EN TEMAS MENCIONADOS EN LA META', 'EL TRABAJADOR NO MOSTRO INTERÉS EN DESARROLLAR LAS HABILIDADES Y CAPACIDADES NECESARIAS PARA UN ADECUADO DESARROLLO DE SUS FUNCIONES. NO PRESENTO CONSTANCIAS DE CURSO DE CAPACITACIÓN ALGUNO DE LOS TEMAS MENCIONADOS EN LA META', '50', 'APOYAR EN LA CONSERVACIÓN DE LOS ECOSISTEMAS MÁS REPRESENTATIVOS DE LAS ANP, MEDIANTE EL DESARROLLO Y SEGUIMIENTO A ACCIONES ALTERNATIVAS DE MANEJO Y APROVECHAMIENTO SUSTENTABLE DE LOS RECURSOS NATURALES PARA EL DESARROLLO DE LAS COMUNIDADES LOCALES COMO PUEDEN SER LOS PROGRAMAS DE SUBSIDIO DE LA CONANP O LA EDUCACIÓN AMBIENTAL.', '10', '10', 'EL TRABAJADOR APOYO SATISFACTORIAMENTE EN ACCIONES RELACIONADAS A LA CONSERVACIÓN DE ECOSISTEMAS, PARTICIPANDO DE MANERA ACTIVA EN EL SEGUIMIENTO DE PROYECTOS COMUNITARIOS APOYADOS POR LA CONANP.,', 'EL TRABAJADOR APOYO PARCIALMENTE EN AQUELLAS ACCIONES RELACIONADAS A LA CONSERVACIÓN DE ECOSISTEMAS Y EN EL SEGUIMIENTO DE PROYECTOS COMUNITARIOS APOYADOS POR LA CONANP.', 'EL TRABAJADOR NO SE INVOLUCRÓ EN AQUELLAS ACCIONES RELACIONADAS A LA CONSERVACIÓN DE ECOSISTEMAS Y/O EN PROYECTOS COMUNITARIOS APOYADOS POR LA CONANP.', '70', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (452, 'RORF691120', 'PARTICIPAR EN EL PROCESO ADMINISTRATIVO DE DIFUSIÓN, RECEPCIÓN E INTEGRACIÓN DE EXPEDIENTES, DICTAMINACIÓN ENTREGA DE OBRA Y FINIQUITO DE PROYECTOS DE LOS PROGRAMAS DE SUBSIDIOS DEL ANP', '01', '25', '1', '0.75', '0.5', '60', 'COORDINAR ACCIONES EN MATERIA FORESTAL Y DE MANEJO DE FUEGO EN EL ANP, ASÍ COMO PARTICIPAR EN REUNIONES DEL GRUPO TÉCNICO OPERATIVO(GTO), Y EQUIPO ESTATAL DE MANEJO DE INCIDENTES (EEMI)', '01', '25', '1', '0.75', '0.5', '90', 'COORDINAR LAS ACCIONES NECESARIAS PARA EL CUMPLIMIENTO DE LA NORMATIVIDAD AMBIENTAL QUE APLICA EN MATERIA DE ANP, CON RELACIÓN AL APROVECHAMIENTO DE RECURSOS NATURALES, TURISMO Y OTRAS ACTIVIDADES EXTRACTIVAS', '01', '25', '1', '0.75', '0.5', '70', 'APOYAR A LA DIRECCIÓN DEL ANP EN LAS ACCIONES DE CONCERTACIÓN QUE PROMUEVA LA PARTICIPACIÓN ACTIVA DE LA POBLACIÓN LOCAL, COMO PARTE DEL PROCESO DE ACTUALIZACIÓN DEL PROGRAMA DE MANEJO Y OPERACIÓN DEL ÁREA NATURAL PROTEGIDA', '01', '25', '1', '0.75', '0.5', '70', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (453, 'ROSF850903', 'APOYAR A ACTIVIDADES DE CAMPO, A INVESTIGADORES E INSTITUCIONES ACADEMICAS QUE REALIZAN ACTIVIDADES DE ESTUDIOS DE MONITOREO E INVESTIGACIÓN EN EL ANP, ASI COMO RECABAR LOS DATOS DE LAS ESPECIES A TRAVES DE PROTOCOLOS DE MONITOREO.', '01', '20', 'APOYO EN 5 ACTIVIDADES', 'APOYO EN 2 ACTIVIDADES', 'APOYO EN 0 ACTIVIDADES', '90', 'PARTICIPAR EN LA EJECUCIÓN DE LOS PROTOCOLOS DE MONITOREO BIOLÓGICO ESTABLECIDOS PARA ESPECIES CLAVES DEL ANP, DE ACUERDO A LAS NECESIDADES DETECTADAS.', '01', '20', '5', '2', '0', '90', 'APOYO EN LA ELABORACION DE OPINIONES TECNICAS SOLICITADAS AL ANP', '10', '20', 'APOYO EN EL 50% DE OPINIONES TECNICAS SOLICITADAS', 'APOYO EN EL 25% DE OPINIONES TECNICAS SOLICITADAS', 'APOYO EN EL 0% DE OPINIONES TECNICAS SOLICITADAS', '70', 'PARTICIPACIÓN EN LAS ACTIVIDADES DE SUPERVISION Y VIGILANCIA (PARTICIPACION EN OPERATIVOS)', '01', '20', 'PARTICIPACION EN 3 OPERATIVOS', 'PARTICIPACION EN 1 OPERATIVOS', 'PARTICIPACION EN 0 OPERATIVOS', '90', 'EJECUTAR PROTOCOLOS DE CONTROL DE ESPECIES INVASORAS EN EL ANP', '01', '20', 'EJECUTAR 2 PROTOCOLOS', 'EJECUTAR 1 PROTOCOLO', 'EJECUTAR 0 PROTOCOLOS', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (454, 'ROSJ710326', 'ADMINISTRAR LOS CONTRATOS DE MANTENIMIENTO DE EQUIPO DE TRANSPORTE TERRESTRE, A CARGO DE LA UNIDAD ADMINISTRATIVA, CONFORME A LAS CONDICIONES Y PRECIOS CONTRATADOS Y CON BASE AL CALENDARIO PRESUPUESTAL DISPONIBLE, CORRESPONDIENTE AL EJERCICIO FISCAL 2024.', '08', '30', 'QUE LOS SERVICIOS DE MANTENIMIENTO CORRECTIVO Y PREVENTIVO SE REALICEN EN UN RANGO DE OPORTUNIDAD Y SATISFACCIÓN DEL USUARIO, SUPERIOR AL 90%', 'QUE LOS SERVICIOS DE MANTENIMIENTO CORRECTIVO Y PREVENTIVO SE REALICEN EN UN RANGO DE OPORTUNIDAD Y SATISFACCIÓN DEL USUARIO, ENTRE EL 85 Y 90%.', 'QUE LOS SERVICIOS DE MANTENIMIENTO PREVENTIVO Y CORRECTIVO SE REALICEN EN UN RANGO DE OPORTUNIDAD Y SATISFACCIÓN DEL USUARIO, CON UN ÍNDICE MENOR AL 85%.', '90', 'ADMINISTRAR LOS CONTRATOS DE MANTENIMIENTO DE EQUIPO DE TRANSPORTE MARÍTIMO, A CARGO DE LA UNIDAD ADMINISTRATIVA, CONFORME A LAS CONDICIONES Y PRECIOS CONTRATADOS Y CON BASE AL CALENDARIO PRESUPUESTAL DISPONIBLE, CORRESPONDIENTE AL EJERCICIO 2024.', '08', '30', 'QUE LOS SERVICIOS DE MANTENIMIENTO CORRECTIVO Y PREVENTIVO SE REALICEN EN UN RANGO DE OPORTUNIDAD Y SATISFACCIÓN DEL USUARIO, SUPERIOR AL 90%.', 'QUE LOS SERVICIOS DE MANTENIMIENTO CORRECTIVO Y PREVENTIVO SE REALICEN EN UN RANGO DE OPORTUNIDAD Y SATISFACCIÓN DEL USUARIO, ENTRE EL 85 Y 90%.', 'QUE LOS SERVICIOS DE MANTENIMIENTO PREVENTIVO Y CORRECTIVO SE REALICEN EN UN RANGO DE OPORTUNIDAD Y SATISFACCIÓN DEL USUARIO, CON UN ÍNDICE MENOR AL 85%.', '90', 'COORDINAR Y ASESORAR LA ADMINISTRACIÓN DE LOS CONTRATOS DE MANTENIMIENTO DE EQUIPO DE TRANSPORTE TERRESTRE Y MARÍTIMO A CARGO DE LAS ANP\'S, EN LOS ESTADOS DE CAMPECHE Y YUCATÁN, CONFORME A LAS CONDICIONES Y PRECIOS CONTRATADOS Y CON BASE AL CALENDARIO PRESUPUESTAL DISPONIBLE, CORRESPONDIENTE AL EJERCICIO 2024.', '04', '20', 'PROMOVER Y BRINDAR EL APOYO INSTITUCIONAL A LAS ANP\'S, CON LA FINALIDAD DE QUE EL CUMPLIMIENTO DE SUS CONTRATOS FORMALIZADOS SE DESARROLLEN CONFORME A LAS CONDICIONES PACTADAS, Y EN UN RANGO DE CUMPLIMIENTO DEL 100% SE GENEREN LAS ORDENES DE TRABAJO Y LAS BITÁCORAS DE MANTENIMIENTO.', 'PROMOVER Y BRINDAR EL APOYO INSTITUCIONAL A LAS ANP\'S, CON LA FINALIDAD DE QUE EL CUMPLIMIENTO DE SUS CONTRATOS FORMALIZADOS SE DESARROLLEN CONFORME A LAS CONDICIONES PACTADAS, Y EN UN RANGO DE CUMPLIMIENTO ENTRE EL 95 Y EL 99.9% SE GENEREN LAS ORDENES DE TRABAJO Y LAS BITÁCORAS DE MANTENIMIENTO.', 'PROMOVER Y BRINDAR EL APOYO INSTITUCIONAL A LAS ANP\'S CON LA FINALIDAD DE QUE EL CUMPLIMIENTO DE SUS CONTRATOS FORMALIZADOS SE DESARROLLE CONFORME A LAS CONDICIONES PACTADAS Y EN UN RAGO DE CUMPLIMIENTO ENTRE EL 90 Y 94.99% SE GENEREN LAS ORDENES DE TRABAJO Y LAS BITÁCORAS DE MANTENIMIENTO.', '90', 'ASESORAR A LAS ANP\'S PARA LA INTEGRACIÓN Y TRÁMITE DE LOS EXPEDIENTES DE RECLAMACIÓN DE DAÑOS DE LOS BIENES MUEBLES ASEGURADOS PROPIEDAD DE LA CONANP.', '07', '20', 'TRAMITAR LA RECLAMACIÓN DE DAÑOS DE BIENES ASEGURADOS SINIESTRADOS, DENTRO DE LOS 10 DÍAS POSTERIORES A LA FECHA EN QUE ESTOS OCURRAN, Y SE RECIBAN DE LAS ANP AFECTADAS EL EXPEDIENTE DEBIDAMENTE INTEGRADO Y POR ESCRITO.', 'TRAMITAR LA RECLAMACIÓN DE DAÑOS DE BIENES ASEGURADOS SINIESTRADOS, DENTRO DE LOS 11 Y 20 DÍAS POSTERIORES A LA FECHA EN QUE ESTOS OCURRAN, Y SE RECIBAN DE LAS ANP AFECTADAS EL EXPEDIENTE DEBIDAMENTE INTEGRADO Y POR ESCRITO.', 'TRAMITAR LA RECLAMACION DE DAÑOS DE BIENES ASEGURADOS, DENTRO DE LOS 21 Y 30 DIAS POSTERIORES A LA FECHA EN LO QUE ESTOS OCURRAN Y SE RECIBAN DE LAS ANPS LOS EXPEDIENTES DEBIDAMENTE INTEGRADOS Y POR ESCRITO', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (455, 'ROVF780823', 'OPERAR EL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE (PROCODES) EN SU CONVOCATORIA ESPECÍFICA ESTATAL DE CONSERVACIÓN DE LA AGROBIODIVERSIDAD EN LAS COMUNIDADES DENTRO DEL APRN LA FRAILESCANA Y SU ZONA DE INFLUENCIA, LA INTEGRACIÓN DE EXPEDIENTES , SUPERVISIÓN DE ACTIVIDADES, ACTA-ENTREGA RECEPCIÓN Y EVALUACIÓN DE PROYECTOS.', '01', '20', 'OPERAR 5 PROYECTOS DEL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE (PROCODES) EN SU CONVOCATORIA ESPECÍFICA ESTATAL DE CONSERVACIÓN DE LA AGROBIODIVERSIDAD', 'OPERAR 3 PROYECTOS DEL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE (PROCODES) EN SU CONVOCATORIA ESPECÍFICA ESTATAL DE CONSERVACIÓN DE LA AGROBIODIVERSIDAD', 'OPERAR 1 PROYECTO DEL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE (PROCODES) EN SU CONVOCATORIA ESPECÍFICA ESTATAL DE CONSERVACIÓN DE LA AGROBIODIVERSIDAD', '90', 'OPERAR EL PROGRAMA PARA LA PROTECCIÓN Y RESTAURACIÓN DE ECOSISTEMAS Y ESPECIES PRIORITARIAS (PROREST) DENTRO DEL COMPONENTE VIGILANCIA Y MONITOREO COMUNITARIO EN LAS COMUNIDADES DENTRO DEL APRN LA FRAILESCANA Y SU ZONA DE INFLUENCIA, MEDIANTE LA INTEGRACIÓN DE EXPEDIENTES , SUPERVISIÓN DE ACTIVIDADES, ACTA-ENTREGA RECEPCIÓN Y EVALUACIÓN DE PROYECTOS.', '01', '20', 'OPERAR 3 PROYECTOS DEL PROGRAMA PARA LA PROTECCIÓN Y RESTAURACIÓN DE ECOSISTEMAS Y ESPECIES PRIORITARIAS (PROREST) – COMPONENTE VIGILANCIA Y MONITOREO COMUNITARIO', 'OPERAR 2 PROYECTOS DEL PROGRAMA PARA LA PROTECCIÓN Y RESTAURACIÓN DE ECOSISTEMAS Y ESPECIES PRIORITARIAS (PROREST) – COMPONENTE VIGILANCIA Y MONITOREO COMUNITARIO', 'OPERAR 1 PROYECTO DEL PROGRAMA PARA LA PROTECCIÓN Y RESTAURACIÓN DE ECOSISTEMAS Y ESPECIES PRIORITARIAS (PROREST) – COMPONENTE VIGILANCIA Y MONITOREO COMUNITARIO', '90', 'PARTICIPAR EN LA ELABORACIÓN DE OPINIONES TÉCNICAS EN MATERIA DE IMPACTO AMBIENTAL, APROVECHAMIENTOS, SOLICITUDES DE COLECTA, AVISOS DE INVESTIGACIÓN Y OTROS QUE PRETENDAN REALIZARSE DENTRO DEL APRN LA FRAILESCANA Y EN SU ZONA DE INFLUENCIA.', '01', '20', 'PARTICIPAR EN LA ELABORACIÓN DE 3 OPINIONES TÉCNICAS SOBRE PROYECTOS A REALIZARSE DENTRO DEL APRN LA FRAILESCANA Y EN SU ZONA DE INFLUENCIA.', 'PARTICIPAR EN LA ELABORACIÓN DE 2 OPINIONES TÉCNICAS SOBRE PROYECTOS A REALIZARSE DENTRO DEL APRN LA FRAILESCANA Y EN SU ZONA DE INFLUENCIA.', 'PARTICIPAR EN LA ELABORACIÓN DE 1 OPINIÓN TÉCNICA SOBRE PROYECTOS A REALIZARSE DENTRO DEL APRN LA FRAILESCANA Y EN SU ZONA DE INFLUENCIA.', '90', 'COLABORAR EN LA EVALUACIÓN DEL PROGRAMA DEL MANEJO DEL APRN LA FRAILESCANA A TRAVÉS DE LA RECOPILACIÓN, GENERACIÓN Y SISTEMATIZACIÓN DE INFORMACIÓN RELACIONADA CON SUS DIFERENTES SUBPROGRAMAS', '10', '20', 'COLABORAR EN LA EVALUACIÓN DEL PROGRAMA DE MANEJO DEL APRN LA FRAILESCANA EN TODOS LOS SUBPROGRAMAS SOLICITADOS.', 'COLABORAR EN LA EVALUACIÓN DEL PROGRAMA DE MANEJO DEL APRN LA FRAILESCANA DE MANERA PARCIAL.', 'NO COLABORAR EN LA EVALUACIÓN DEL PROGRAMA DE MANEJO DEL APRN LA FRAILESCANA.', '90', 'MANTENER ACTUALIZADAS BASES DE DATOS SOBRE DIFERENTES ASPECTOS DEL APRN LA FRAILESCANA (E.G. FÍSICOS, BIOLÓGICOS, SOCIOECONÓMICOS, ESTADO DE CONSERVACIÓN Y MANEJO DE LOS ECOSISTEMAS, SISTEMA SMART).', '01', '20', 'MANTENER ACTUALIZADAS DOS BASES DE DATOS SOBRE DIFERENTES ASPECTOS DEL APRN LA FRAILESCANA.', 'MANTENER ACTUALIZADA UNA BASE DE DATOS SOBRE DIFERENTES ASPECTOS DEL APRN LA FRAILESCANA.', 'NO MANTENER ACTUALIZADA NINGUNA BASE DE DATOS SOBRE DIFERENTES ASPECTOS DEL APRN LA FRAILESCANA.', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con eviden