INSERT INTO `sed_individuales` VALUES (474, 'SAPG730910', 'COORDINACIÒN Y SEGUIMIENTO A LAS ACCIONES DE PREVENCIÒN Y ATENCIÒN A INCENDIOS FORESTALES DENTRO DEL PN EL TEPOZTECO Y ZONA DE INFLUENCIA, ASÌ COMO SU REGISTRO EN EL SISTEMA INTEGRAL DE RESPUESTA CON CALIDAD (SIRCA).', '10', '20', 'SE ATIENDE EL 100% DE LAS ACCIONES ESTABLECIDAS PARA LA ATENCIÒN DE CONTINGENCIA AMBIENTAL (INCENDIO FORESTAL) PARA EL ANP Y ZONA DE INFLUENCIA', 'SE ATIENDE EL 70% AL 60% DE LAS ACCIONES ESTABLECIDAS PARA LA ATENCIÓN DE CONTINGENCIA AMBIENTAL (INCENDIO FORESTAL) EN LA POLIGONAL DEL ANP Y ZONA DE INFLUENCIA', 'SE ATIENDE EL 50% DE LAS ACCIONES ESTABLECIDAS PARA LA ATENCIÓN DE CONTINGENCIA AMBIENTAL (INCENDIO FORESTAL) EN LA POLIGONAL DEL ANP Y ZONA DE INFLUENCIA', '90', 'SEGUIMIENTO AL PROGRAMA PARA LA PROTECCIÒN Y RESTAURACIÒN DE ECOSISTEMAS Y ESPECIES PRIORITARIAS (PROREST), CONSERVACIÒN DE SIERRAS Y MONTAÑAS (COSMOS), ASÍ COMO A LAS ACTIVIDADES DE RESTAURACIÒN IMPLEMENTADAS EN ÀREAS AFECTADAS POR INCENDIOS Y PLAGAS FORESTALES, DENTRO DEL PN EL TEPOZTECO Y ZONA DE INFLUENCIA.', '10', '20', 'SEGUIMIENTO AL100% DE LOS PROYECTOS Y LAS ACTIVIDADES DE RESTAURACIÒN IMPLEMENTADAS', 'SEGUIMIENTO DEL 70% AL 60% DE LOS PROYECTOS Y LAS ACTIVIDADES DE RESTAURACIÒN IMPLEMENTADAS', 'SEGUIMIENTO AL 50% DE LOS PROYECTOS Y LAS ACTIVIDADES DE RESTAURACIÒN IMPLEMENTADAS', '90', 'ATENCIÒN DE OPINIONES TÉCNICAS EN MATERIA DE IMPACTO AMBIENTAL, SANIDAD FORESTAL Y DE INVESTIGACIÒN SOLICITADAS POR LA DIRECCIÒN REGIONAL, PARA EL PN EL TEPOZTECO, ASÍ COMO EL REGISTRO RESPECTIVO EN EL SISTEMA INTEGRAL DE RESPUESTA CON CALIDAD (SIRCA).', '10', '20', 'SE ELABORA EL 100% DE LAS OPINIONES TÈCNICAS', 'SE ELABORA EL 70% AL 60% DE LAS OPINIONES TÉCNICAS', 'SE ELABORA EL 50% DE LAS OPINIONES TÉCNICAS', '90', 'ATENCIÒN DE PROCEDIMIENTOS RELACIONADOS CON AUTORIZACIONES PARA REALIZAR ACTIVIDADES TURÌSTICO RECREATIVAS EN EL PN EL TEPOZTECO ASÌ COMO SU REGISTRO EN EL SIRCA Y LOS REGISTROS EN EL SICDE 2.0 DE LOS PAGOS 