INSERT INTO `sed_individuales` VALUES (496, 'TOAM860221', 'IMPLEMENTAR ACCIONES Y ESTRATEGIAS PARA LA PROTECCIÓN, MANEJO, RESTAURACIÓN, INVESTIGACIÓN Y GESTIÓN SOCIAL EN EL ÁREA NATURAL PROTEGIDA (ANP).', '04', '20', '95% DE LAS ACCIONES CONCLUIDAS.', '85% DE LAS ACCIONES CONCLUIDAS.', '80% DE LAS ACCIONES CONCLUIDAS.', '90', 'REVISAR Y ANALIZAR LA INFORMACIÓN BIOLÓGICA, GEOGRÁFICA Y SOCIAL DISPONIBLE DEL ANP (ÁREA NATURAL PROTEGIDA) PARA EVALUAR LAS PROPUESTAS DE PROYECTOS SOLICITADOS Y AUTORIZADOS, ASEGURANDO SU COMPATIBILIDAD CON LAS ESTRATEGIAS DE MANEJO DE LA ANP Y SU ALINEACIÓN CON LA NORMATIVA AMBIENTAL VIGENTE.', '08', '20', '95% DE LAS PROPUESTAS ANALIZADAS.', '85% DE LAS PROPUESTAS ANALIZADAS.', '80% DE LAS PROPUESTAS ANALIZADAS.', '90', 'BRINDAR ASESORÍA ESPECIALIZADA A LAS ENTIDADES CORRESPONDIENTES EN LAS ACTIVIDADES DE PLANIFICACIÓN, CONSERVACIÓN Y DESARROLLO DE LA ÁREA NATURAL PROTEGIDA.', '04', '20', '95 % DE SOLICITUDES DE ASESORÍA ATENDIDAS.', '85% DE SOLICITUDES DE ASESORÍAS ATENDIDAS.', '80% DE ASESORÍAS ATENDIDAS.', '90', 'BRINDAR APOYO EN LA IMPLEMENTACIÓN DE ESTRATEGIAS QUE CONTRIBUYAN A LA CREACIÓN DE PROCESOS PRODUCTIVOS SOSTENIBLES Y QUE SEAN COMPATIBLES CON EL PROGRAMA DE MANEJO DEL ÁREA NATURAL PROTEGIDA (ANP).', '04', '20', '95% DE LAS PROPUESTAS.', '85% DE LAS PROPUESTAS.', '80% DE LAS PROPUESTAS.', '90', 'LLEVAR A CABO ACTIVIDADES ADMINISTRATIVAS Y LOGÍSTICAS, ASÍ COMO LA GESTIÓN EFICAZ DE RECURSOS MATERIALES, HUMANOS, TECNOLÓGICOS Y FINANCIEROS NECESARIOS, DENTRO DE SU ÁMBITO DE COMPETENCIA, GARANTIZANDO EL CUMPLIMIENTO DE LAS NORMATIVAS Y LA EFICIENTE REALIZACIÓN DE LAS ACTIVIDADES PARA LA ÓPTIMA OPERACIÓN DEL ÁREA NATURAL PROTEGIDA (ANP).', '04', '20', '100 % DE LA META ESTABLECIDA PARA EL POA.', '90% DE LA META ESTABLECIDA PARA EL POA.', '85% DE LA META ESTABLECIDA PARA EL POA.', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido