INSERT INTO `sed_individuales` VALUES (502, 'TOPM691125', 'ATENCIÓN AL TURISMO NACIONAL Y EXTRANJERO PROPORCIONANDO INFORMACIÓN Y REVISIÓN DE BRAZALETES PARA EL INGRESO DEL ANP PARQUE NACIONAL PALENQUE.', '08', '30', 'DAR LA INFORMACIÓN AL TURISMO EN GENERAL PARA FACILITAR SU VISITA, ASÍ COMO EFECTUARLA REVISIÓN DE BRAZALETES DE LOS USUARIOS PARA EL ACCESO AL ANP. DICHAS ACTIVIDADES SE LE DEDICAN UN RANGO DEL 80% AL 100%.', ': DAR LA INFORMACIÓN AL TURISMO EN GENERAL PARA FACILITAR SU VISITA, ASÍ COMO EFECTUARLA REVISIÓN DE BRAZALETES DE LOS USUARIOS PARA EL ACCESO AL ANP. DICHAS ACTIVIDADES SE LE DEDICAN UN RANGO DEL 60% AL 70%.', 'DAR LA INFORMACIÓN AL TURISMO EN GENERAL PARA FACILITAR SU VISITA, ASÍ COMO EFECTUARLA REVISIÓN DE BRAZALETES DE LOS USUARIOS PARA EL ACCESO AL ANP. DICHAS ACTIVIDADES SE LE DEDICAN UN RANGO DEL 50% AL 60%.', '90', 'COLABORAR EN EL MANTENIMIENTO EN EL CENTRO DE CULTURA PARA LA CONSERVACIÓN (SALA DE INTERPRETACIÓN AMBIENTAL, ÁREA DE POLINIZADORES, MARIPOSARIO, PLANTAS MEDICINALES Y ANDADOS) ATENCIÓN, REGISTRO Y BRINDAR INFORMACIÓN A LAS VISITAS EN GENERAL.', '05', '30', 'REALIZAR ENTRE EL 90% Y 100% LAS LABORES PROGRAMADAS EN EL ÁREA.', 'REALIZAR ENTRE EL 80% Y 90% LAS LABORES PROGRAMADAS EN EL ÁREA.', 'EFECTUAR MENOS DEL 80% LAS LABORES PROGRAMADAS EN EL ÁREA.', '90', 'REALIZAR REGISTRO DEL TURISMO EN GENERAL Y VERIFICACIÓN DE LA PULSERA PARA EL ACCESO A LOS DIFERENTES PUNTOS DE ENTRADA AL SENDERO DEL ÁREA, ASÍ COMO REVISIÓN Y CAPTURA DE LAS ESTADÍSTICAS PARA SU REPORTE A LA DIRECCIÓN DEL ANP.', '07', '30', 'EFECTUAR LAS ACTIVIDADES ENTRE EL 90% Y 100%. REGISTRO, VERIFICAR, CAPTURA Y REPORTE DE DICHA INFORMACIÓN.', 'EFECTUAR LAS ACTIVIDADES ENTRE EL 80% Y 90%. REGISTRO, VERIFICAR, CAPTURA Y REPORTE DE DICHA INFORMACIÓN.', 'EFECTUAR MENOS DEL 80% DE LAS ACTIVIDADES EN EL ÁREA.', '90', 'EFECTUAR ACTIVIDADES DE INSPECCIÓN Y VIGILANCIA EN LAS ÁREAS NATURALES PROTEGIDAS CON LA FINALIDAD DE DETECTAR ILÍCITOS AMBIENTALES, MANTENIMIENTO DEL ANDADOR TURÍSTICO, ÁREAS ALEDAÑAS A LAS INSTALACIONES, ASÍ TAMBIÉN LOS SENDEROS DEL ÁREA Y RECOLECCIÓN DE BASURA.', '07', '10', 'CUMPLIR ENTRE EL 90% Y 100% LAS ACTIVIDADES EN EL ANP.', 'CUMPLIR ENTRE EL 80% Y 90% LAS ACTIVIDADES EN EL ANP.', 'EFECTUAR MENOS DEL 80% LAS ACTIVIDADES EN EL ANP.', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (503, 'TORH661026', 'ELABORAR LA EVALUACIÓN TÉCNICA DE LAS SOLICITUDES PARA REALIZAR ACTIVIDADES, EN COORDINACIÓN CON LA DIRECCIÓN DE LA RESERVA DE LA BIÓSFERA ISLAS DEL PACÍFICO DE LA PENÍNSULA DE BAJA CALIFORNIA, PARA LA AUTORIZACIÓN, MODIFICACIÓN O REVOCACIÓN EN TÉRMINOS DE LA LEGISLACIÓN APLICABLE DE LAS AUTORIZACIONES EN ÁREAS NATURALES PROTEGIDAS.', '05', '20', 'TENER PREPARADO EN TIEMPO Y FORMA ENTRE 85 AL 100% DE LOS DICTÁMENES DE EVALUACIÓN TÉCNICA DE LAS SOLICITUDES PARA LA REALIZACIÓN DE ACTIVIDADES DENTRO DE LA RESERVA DE LA BIÓSFERA ISLAS DEL PACÍFICO DE LA PENÍNSULA DE BAJA CALIFORNIA.', 'TENER PREPARADO EN TIEMPO Y FORMA ENTRE 60 AL 84% DE LOS DICTÁMENES DE EVALUACIÓN TÉCNICA DE LAS SOLICITUDES PARA LA REALIZACIÓN DE ACTIVIDADES DENTRO DE LA RESERVA DE LA BIÓSFERA ISLAS DEL PACÍFICO DE LA PENÍNSULA DE BAJA CALIFORNIA.', 'TENER PREPARADO EN TIEMPO Y FORMA MENOS DEL 59% DE LOS DICTÁMENES DE EVALUACIÓN TÉCNICA DE LAS SOLICITUDES PARA LA REALIZACIÓN DE ACTIVIDADES DENTRO DE LA RESERVA DE LA BIOSFERA ISLAS DEL PACÍFICO DE LA PENÍNSULA DE BAJA CALIFORNIA.', '90', 'ELABORAR LOS PROYECTOS DE AUTORIZACIONES, PARA SU POSTERIOR AUTORIZACIÓN EN LA RESERVA DE LA BIÓSFERA ISLAS DEL PACÍFICO DE LA PENÍNSULA DE BAJA CALIFORNIA.', '05', '20', 'TENER ELABORADO EN TIEMPO Y FORMA ENTRE EL 85 AL 100% DE LOS PROYECTOS DE AUTORIZACIONES DENTRO DE LA RESERVA DE LA BIÓSFERA ISLAS DEL PACÍFICO DE LA PENÍNSULA DE BAJA CALIFORNIA.', 'TENER ELABORADO EN TIEMPO Y FORMA ENTRE EL 60 AL 84% DE LOS PROYECTOS DE AUTORIZACIONES DENTRO DE LA RESERVA DE LA BIÓSFERA ISLAS DEL PACÍFICO DE LA PENÍNSULA DE BAJA CALIFORNIA.', 'TENER PREPARADO EN TIEMPO Y FORMA MENOS DEL 59% DE LOS PROYECTOS DE AUTORIZACIONES DENTRO DE LA RESERVA DE LA BIOSFERA ISLAS DEL PACÍFICO DE LA PENÍNSULA DE BAJA CALIFORNIA.', '90', 'REALIZAR DICTÁMENES TÉCNICOS SOBRE SOLICITUDES DE PROYECTOS DE INVESTIGACIONES Y COLECTA CIENTÍFICA EN LA RESERVA DE LA BIÓSFERA ISLAS DEL PACÍFICO DE LA PENÍNSULA DE BAJA CALIFORNIA EN COORDINACIÓN CON LA DIRECCIÓN DEL ANP, PARA LA PROTECCIÓN DE ECOSISTEMAS Y SUS ELEMENTOS DENTRO DEL ÁREA NATURAL PROTEGIDA.', '05', '20', 'TENER ELABORADO EN TIEMPO Y FORMA ENTRE EL 85 AL 100% DE LOS DICTÁMENES TÉCNICOS DE LOS PROYECTOS DE INVESTIGACIÓN Y COLECTA CIENTÍFICA DENTRO DE LA RESERVA DE LA BIÓSFERA ISLAS DEL PACÍFICO DE LA PENÍNSULA DE BAJA CALIFORNIA.', 'TENER ELABORADO EN TIEMPO Y FORMA ENTRE EL 60 AL 84% DE LOS DICTÁMENES TÉCNICOS DE LOS PROYECTOS DE INVESTIGACIÓN Y COLECTA CIENTÍFICA DENTRO DE LA RESERVA DE LA BIÓSFERA ISLAS DEL PACÍFICO DE LA PENÍNSULA DE BAJA CALIFORNIA.', 'TENER PREPARADO EN TIEMPO Y FORMA MENOS DEL 59% DE LOS DICTÁMENES TÉCNICOS DENTRO DE LA RESERVA DE LA BIOSFERA ISLAS DEL PACÍFICO DE LA PENÍNSULA DE BAJA CALIFORNIA.', '90', 'CONTRIBUIR EN LA IMPLEMENTACIÓN DE LOS PROGRAMAS DE SUBSIDIOS DE LA CONANP: PROCODES Y PROREST EN LA RESERVA DE LA BIÓSFERA ISLAS DEL PACÍFICO DE LA PENÍNSULA DE BAJA CALIFORNIA.', '04', '20', 'TENER INTEGRADO EN TIEMPO Y FORMA ENTRE EL 85 AL 100% DE LOS EXPEDIENTES DE LOS PROYECTOS DEL PROCODES Y PROREST APROBADOS PARA 2023 EN LA RESERVA DE LA BIÓSFERA ISLAS DEL PACÍFICO DE LA PENÍNSULA DE BAJA CALIFORNIA.', 'TENER INTEGRADO EN TIEMPO Y FORMA ENTRE EL 60 AL 84% DE LOS EXPEDIENTES DE LOS PROYECTOS DEL PROCODES Y PROREST APROBADOS PARA 2023 EN LA RESERVA DE LA BIÓSFERA ISLAS DEL PACÍFICO DE LA PENÍNSULA DE BAJA CALIFORNIA.', 'TENER INTEGRADO EN TIEMPO Y FORMA MENOS DEL 59% DE LOS EXPEDIENTES DE LOS PROYECTOS DEL PROCODES Y PROREST APROBADOS PARA 2023 EN LA RESERVA DE LA BIÓSFERA ISLAS DEL PACÍFICO DE LA PENÍNSULA DE BAJA CALIFORNIA.', '90', 'DAR SEGUIMIENTO Y SUPERVISIÓN EN CAMPO DE LA APLICACIÓN Y EJECUCIÓN DEL DECRETO DE CREACIÓN DE LA RESERVA DE LA BIÓSFERA ISLAS DEL PACÍFICO DE LA PENÍNSULA DE BAJA CALIFORNIA.', '04', '20', 'REALIZAR ENTRE EL 85 AL 100% DE LOS RECORRIDOS DE SUPERVISIÓN Y VIGILANCIA EN LA RESERVA DE LA BIÓSFERA ISLAS DEL PACÍFICO.', 'REALIZAR ENTRE EL 60 AL 84% DE LOS RECORRIDOS DE SUPERVISIÓN Y VIGILANCIA EN LA RESERVA DE LA BIÓSFERA ISLAS DEL PACÍFICO.', 'REALIZAR MENOS DEL 59% DE LOS RECORRIDOS DE SUPERVISIÓN Y VIGILANCIA EN LA RESERVA DE LA BIÓSFERA ISLAS DEL PACÍFICO.', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
