INSERT INTO `sed_individuales` VALUES (507, 'UCED840701', 'COORDINAR QUE LOS PROGRAMAS, PROYECTOS Y ACTIVIDADES QUE REALIZA EL PERSONAL DEL ANP CUMPLA CON EL PROGRAMA DE MANEJO DEL ÁREA.', '10', '25', 'EL 100% DE ACCIONES EN EL ANP SE REALIZAN EN CUMPLIMIENTO AL PROGRAMA DE MANEJO', 'EL 99 AL 90% DE ACCIONES EN EL ANP SE REALIZAN EN CUMPLIMIENTO AL PROGRAMA DE MANEJO', 'EL 89% O MENOS DE LAS ACCIONES EN EL ANP SE REALIZAN EN CUMPLIMIENTO AL PROGRAMA DE MANEJO', '90', 'OPINAR RESPECTO A LOS APROVECHAMIENTOS, SERVICIOS, OBRAS Y ACTIVIDADES QUE SE PRETENDAN AUTORIZAR POR PARTE DE LAS AUTORIDADES COMPETENTES EN EL ANP.', '10', '25', 'OPINAR RESPECTO AL 100% DE LOS APROVECHAMIENTOS, SERVICIOS, OBRAS Y ACTIVIDADES QUE SE PRETENDAN AUTORIZAR EN EL ANP', 'OPINAR RESPECTO AL 99 A 90% DE LOS APROVECHAMINETOS, SERVICIOS, OBRAS Y ACTIVIDADES QUE SE PRETENDAN AUTORIZAR EN EL ANP', 'OPINAR RESPECTO A MENOS DEL 89% DE LOS APROVECHAMIENTOS, SERVICIOS, OBRAS Y ACTIVIDADES QUE SE PRETENDAN AUTORIZAR EN EL ANP', '70', 'COORDINAR LA PROMOCIÓN Y EJECUCIÓN DE LOS RECURSOS AUTORIZADOS AL ÁREA NATURAL PROTEGIDA A TRAVÉS DE LOS PROGRAMAS DE SUBSIDIO', '10', '25', 'APLICAR ENTRE EL 100 AL 95% DE LOS RECURSOS AUTORIZADOS PARA LOS PROYECTOS DEL ANP', 'APLICAR ENTRE EL 94 AL 90% DE LOS RECURSOS AUTORIZADOS PARA LOS PROYECTOS DEL ANP', 'APLICAR MENOS DEL 89% DE LOS RECURSOS AUTORIZADOS PARA LOS PROYECTOS DEL ANP', '90', 'OPERAR Y ADMINISTRAR EFICAZMENTE LA INFRAESTRUCTURA, EQUIPO Y RECURSOS DEL ANP, PARA EL DESARROLLO DE LAS FUNCIONES DEL PUESTO.', '10', '25', 'OPERAR Y ADMINISTRAR EFICAZMENTE DEL 100 AL 95% DE LA INFRAESTRUCTURA, EQUIPO Y RECURSOS PARA LA CONSERVACIÓN DEL ANP', 'OPERAR Y ADMINISTRAR EFICAZMENTE DEL 94 AL 90% DE LA INFRAESTRUCTURA, EQUIPO Y RECURSOS PARA LA CONSERVACIÓN DEL ANP', 'OPERAR Y ADMINISTRAR EFICAZMENTE DEL 89 AL 85% DE LA INFRAESTRUCTURA, EQUIPO Y RECURSOS PARA LA CONSERVACIÓN DEL ANP', '70', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será estab