INSERT INTO `sed_individuales` VALUES (508, 'VAAJ750227', 'DAR SEGUIMIENTO A LA EJECUCIÓN DE LOS PROGRAMAS DE SUBSIDIO (PROREST Y PROCODES) MEDIANTE LA ASESORÍA, VERIFICACIÓN, INTEGRACIÓN, SUPERVISIÓN Y REVISIÓN DE PROYECTOS APROBADOS EN APEGO A LAS REGLAS DE OPERACIÓN Y LINEAMIENTOS ESTABLECIDOS Y CON ELLO CONTRIBUIR AL CUMPLIMIENTO DE OBJETIVOS Y METAS INSTITUCIONALES EN LA DIRECCIÓN REGIONAL.', '10', '40', 'MAYOR AL 90 %', '70 A 90 %', 'MENOR DE 70%', '90', 'REALIZAR VISITAS DE SUPERVISIÓN DE PROYECTOS DE PROGRAMAS DE SUBSIDIO EN LAS DIFERENTES ANPS DE LA DIRECCIÓN REGIONAL EN APOYO A LA UNIDAD DE SINERGIA INSTITUCIONAL; VISITAS DE CAMPO PARA VERIFICAR CONDICIONES DE LOS ECOSISTEMAS Y LA BIODIVERSIDAD PRESENTE EN ÁREAS CON INTENCIÓN DE REGISTRARSE COMO ÁREAS DESTINADAS VOLUNTARIAMENTE A LA CONSERVACIÓN EN APOYO A LA UNIDAD TÉCNICO DE LA DRNEYSMO, VISITAS DE CAMPO EN MATERIA DE VIDA SILVESTRE Y SANIDAD FORESTAL EN APOYO A LA UNIDAD DE IMPACTO AMBIENTAL. APOYO LOGÍSTICO EN INCENDIOS FORESTALES A LAS ANP DE LA REGIONAL.', '10', '30', 'MAYOR A 90 %', '70 A 90 %', 'MENOR A 70 %', '90', 'REALIZAR EL ANÁLISIS Y SUPERVISIÓN DE LOS PROGRAMAS OPERATIVOS ANUALES (POA) Y SUS INFORMES TRIMESTRALES DE LAS ÁREAS NATURALES PROTEGIDAS PERTENECIENTES A LA DIRECCIÓN REGIONAL NORESTE Y SIERRA MADRE ORIENTAL.', '10', '20', 'MAYOR A 90 %', '70 A 90 %', 'MENOR A 70 %', '90', 'PROPORCIONAR SOPORTE TÉCNICO (INFORMÁTICA) A LOS USUARIOS DE LA DIRECCIÓN REGIONAL NORESTE Y SIERRA MADRE ORIENTAL; ASÍ COMO ENLACE REGIONAL DE SERVICIOS INFORMÁTICOS CON OFICINAS CENTRALES, Y PROPORCIONAR APOYO TÉCNICO AL PERSONAL DE LAS DISTINTAS ÁREAS NATURALES PROTEGIDAS PERTENECIENTES A DICHA DIRECCIÓN REGIONAL.', '10', '5', 'MAYOR A 90 %', '70 A 90 %', 'MENOR A 70 %', '90', 'REALIZAR ACTIVIDADES ADMINISTRATIVAS, DE COORDINACIÓN DE PERSONAL OPERATIVO Y DE LOGÍSTICA, ASÍ COMO DE GESTIÓN DE RECURSOS MATERIALES, HUMANOS, TECNOLÓGICOS, FINANCIEROS Y/O JURÍDICOS QUE SE REQUIERAN, DENTRO DE SU ÁMBITO DE APLICACIÓN, ASEGURANDO EL CUMPLIMIENTO NORMATIVO Y LA CONSECUCIÓN DE LAS ACTIVIDADES Y LA ADECUADA OPERACIÓN DEL ANP Y LA DIRECCIÓN REGIONAL.', '10', '5', 'MAYOR A 90 %', '70 A 90 %', 'MENOR A 70 %', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (509, 'VACP851023', 'DAR SEGUIMIENTO A LA CORRECTA EJECUCIÓN DE LOS APOYOS DEL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE (PROCODES) A NIVEL REGIONAL, EN APEGO A LOS LINEAMIENTOS ESTABLECIDOS Y NORMATIVIDAD APLICABLE.', '10', '50', '85-100', '70-84', '50-69', '90', 'DAR APOYO Y ASESORAR EN EL PROCESO DE RECEPCIÓN DE SOLICITUDES, INTEGRACIÓN DE EXPEDIENTES Y DICTAMINACIÓN DE LOS APOYOS DEL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE (PROCODES) A NIVEL REGIONAL, EN APEGO A LOS LINEAMIENTOS ESTABLECIDOS Y NORMATIVIDAD APLICABLE.', '10', '25', '85-100', '70-84', '50-69', '90', 'REALIZAR VISITAS DE SUPERVISIÓN Y CONTROL A LAS ANP ADSCRITAS A LA DIRECCIÓN REGIONAL RESPECTO A LA EJECUCIÓN DEL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE (PROCODES) EN APEGO A LA NORMATIVIDAD VIGENTE EN APEGO AL PROGRAMA DE SUPERVISIÓN REGIONAL', '10', '25', '85-100', '70-84', '50-69', '70', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (510, 'VAFN831011', 'ELABORAR OPINIONES TÉCNICAS EN MATERIA DE ZONA FEDERAL MARÍTIMO TERRESTRE, ORGANISMOS GENÉTICAMENTE MODIFICADOS, IMPACTO AMBIENTAL, CAMBIO DE USO DE SUELO, FORESTAL, VIDA SILVESTRE Y UNIDADES DE MANEJO DE VIDA SILVESTRE, POR OBRAS Y ACTIVIDADES EN ANP DE LA REGIÓN PLANICIE COSTERA Y GOLFO DE MÉXICO.', '10', '70', 'ATENDER EL 100% DE LAS SOLICITUDES DE OPINIÓN TÉCNICA QUE ME SEAN ASIGNADAS.', 'ATENDER EL 80% DE LAS SOLICITUDES DE OPINIÓN TÉCNICA QUE ME SEAN ASIGNADAS.', 'ATENDER EL 70% DE LAS SOLICITUDES DE OPINIÓN TÉCNICA QUE ME SEAN ASIGNADAS.', '90', 'INTEGRAR LOS EXPEDIENTES DOCUMENTALES Y ELECTRÓNICOS DE LAS SOLICITUDES DE OPINIÓN TÉCNICA RECIBIDAS EN LA DIRECCIÓN REGIONAL PLANICIE COSTERA Y GOLFO DE MÉXICO.', '10', '10', '100% DE LOS EXPEDIENTES DOCUMENTALES Y ELECTRÓNICOS DE LAS OPINIONES TÉCNICAS QUE ME SEAN ASIGNADAS INTEGRADOS Y ACTUALIZADOS.', '80% DE LOS EXPEDIENTES DOCUMENTALES Y ELECTRÓNICOS DE LAS OPINIONES TÉCNICAS QUE ME SEAN ASIGNADAS INTEGRADOS Y ACTUALIZADOS.', '60% DE LOS EXPEDIENTES DOCUMENTALES Y ELECTRÓNICOS DE LAS OPINIONES TÉCNICAS QUE ME SEAN ASIGNADAS INTEGRADOS Y ACTUALIZADOS.', '90', 'ACTUALIZAR EL SISTEMA INTEGRAL DE RESPUESTA CON CALIDAD (SIRCA-OT) CON EL REGISTRO DE PROYECTOS Y OPINIONES TÉCNICAS DE OBRAS Y ACTIVIDADES QUE INCIDAN EN LAS ÁREAS NATURALES PROTEGIDAS, SITIOS RAMSAR Y REGIONES PRIORITARIAS PARA LA CONSERVACIÓN.', '10', '10', '100% DE LOS EXPEDIENTES DE LAS SOLICITUDES DE OPINIÓN QUE ME SEAN ASIGNADAS ACTUALIZADOS.', '80% DE LOS EXPEDIENTES DE LAS SOLICITUDES DE OPINIÓN QUE ME SEAN ASIGNADAS ACTUALIZADOS.', '60% DE LOS EXPEDIENTES DE LAS SOLICITUDES DE OPINIÓN QUE ME SEAN ASIGNADAS ACTUALIZADOS.', '90', 'APOYAR EN LA REVISIÓN E INTEGRACIÓN DE EXPEDIENTES DE SOLICITUDES DE CERTIFICACIÓN COMO ÁREAS DESTINADAS VOLUNTARIAMENTE A LA CONSERVACIÓN (ADVC) QUE INGRESEN A LA DRPCGM Y QUE ME SEAN ASIGNADOS.', '10', '10', '100% DE EXPEDIENTES REVISADOS E INTEGRADOS, QUE ME SEAN ASIGNADOS.', '80% DE EXPEDIENTES REVISADOS E INTEGRADOS, QUE ME SEAN ASIGNADOS.', '60% DE EXPEDIENTES REVISADOS E INTEGRADOS, QUE ME SEAN ASIGNADOS.', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (511, 'VAGV740707', 'COLABORAR EN LA INTEGRACION Y PLANEACION ESTRATEGICA DEL PROGRAMA OPERATIVO ANUAL DEL ANP E INTEGAR Y CAPTURAR EN LA PLATAFORMA SGPOA Y SISEP DE COSMOS EL POA E INFORMES TRIMESTRALES', '10', '20', '1', '0.8', '0.5', '90', 'PARTICIPAR EN EL PROCESO DE DIFUSIÓN, RECEPCIÓN DE SOLICITUDES, INTEGRACION DE EXPEDIENTES Y DICTAMINACION DE LOS PROGRAMAS DE SUBSIDIO PROCODES Y PROREST, ASI COMO EN LA EJECUCION DE LOS PROYECTOS EN APEGO A LA NORMATIVIDAD APLICABLE', '10', '20', '1', '0.8', '0.5', '90', 'SUPERVISION DE LAS ACTIVIDADES QUE LAS BRIGADAS DE CONTENGENCIA AMBIENTAL REALIZAN EN RELACION A LA PREVENCION, ATENCION DE LOS INCENDIOS FORESTALES Y LA RESTAURACION DE ECOSISTEMAS', '10', '20', '1', '0.8', '0.5', '90', 'COADYUVAR A LAS DENUNCIAS POPULARES POR PRESUNTOS ILICITOS AMBIENTALES E INTERPONER LA DENUNCIAS CORRESPONDIENTES; ASI COMO COADYUVAR CON LA PROFEPA EN SUS ACCINES DE INSPECCION Y VIGILANCIA DENTRO DEL PARQUE NACIONAL', '10', '15', '1', '0.8', '0.5', '90', 'COLABORAR EN LA ORGANIZACIÓN Y LOGÍSTICA PARA LAS REUNIONES DEL CONSEJO ASESOR Y SUBCONSEJOS DEL PNLM; Y EN LA FORMULACION DEL PROGRAMA DE MANEJO DEL ANP', '10', '25', '1', '0.8', '0.5', '70', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
