INSERT INTO `sed_individuales` VALUES (516, 'VASF670429', 'REALIZAR RECORRIDOS DE VIGILANCIA A TRAVÉS DEL POLÍGONO DEL ÁREA PROTEGIDA, A FIN DE IDENTIFICAR LA POSIBLE OCURRENCIA DE ACTOS ILICITOS, Y EN CASO DE PRESENTARSE, LEVANTAR LA DENUNCIA CORRESPONDIENTE. TAMBIÉN SE REALIZARÁN RECORRIDOS DE MOMITOREO BIOLÓGICO, DIFUNDIENDO EN NUESTROS DIVERSOS CANALES DE INFORMACIÓN LAS OBSERVACIONES QUE PODAMOS CONSIDERAR DE MAYOR INTERÉS.', '02', '30', '10 RECORRIDOS O MÁS', '6 A 9 RECORRIDOS', '5 RECORRIDOS O MENOS', '90', 'PARTICIPAR EN EVENTOS DE EDUCACIÓN AMBIENTAL Y DE DIFUSIÓN DEL ÁREA PROTEGIDA, COMO SON CHARLAS,, CONFERENCIAS Y VIDEOCONFERENCIAS, QUE CONTRIBUYAN A CONCIENTIZAR AL PÚBLICO EN GENERAL ACERCA DE LA IMPORTANCIA DE CONSERVAR UN AMBIENTE SANO Y LIMPIO. ASI COMO PROMOVER A LAS ÁREAS NATURALES PROTEGIDAS.', '01', '30', '10 O MÁS', '5-9 EVENTOS', '4 O MENOS', '90', 'DAR SEGUIMIENTO HASTA SU EXITOSA CONCLUSIÓN A LOS PROGRAMAS DE SUBSIDIO PROCODES Y PROREST, QUE SE OTORGAN A LOS MIEMBROS DE LA COMUNIDAD A FIN DE BRINDARLES LA OPORTUNIDAD DE DESARROLLAR ACTIVIDADES QUE LOS BENEFICIEN ECONÓMICAMENTE Y QUE NO CAUSEN DETERIORO AMBIENTAL ALGUNO.', '01', '20', '4 PROYECTOS O MÁS', '2 O 3 PROYECTOS', '1 PROYECTOS O MENOS', '70', 'ATENDER Y RESPONDER EN TIEMPO Y FORMA A LAS SOLICITUDES DE INFORMACIÓN, QUE, DE MANERA PERIODICA, NOS LLEGAN VIA INAI', '01', '20', '10 SOLICITUDES O MÁS', '6 A 9 SOLICITUDES', '5 SOLICITUDES O MENOS', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 0