INSERT INTO `sed_individuales` VALUES (522, 'VECM670415', 'CAPTURAR EN EL SISTEMA INFORMÁTICO DEL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE (PROCODES), PROCESO DE RECEPCIÓN, EVALUACIÓN Y DICTAMINACIÓN DE LAS SOLICITUDES DE APOYO, ASÍ COMO LOS DOCUMENTOS Y LAS ACCIONES REQUERIDAS PARA CONTRIBUIR EN LA GENERACIÓN E INTEGRACIÓN DE LOS EXPEDIENTES DE LOS DIFERENTES TIPOS DE APOYO DEL PROGRAMA DE INVERSIÓN DEL EJERCICIO FISCAL 2024 QUE SE EJECUTA EN EL ÁREA NATURAL PROTEGIDA.', '05', '30', 'REALIZAR 10 ACCIONES EN EL SISTEMA INFORMÁTICO DEL PROCODES DURANTE EL EJERCICIO FISCAL 2024 QUE CONTRIBUYA EN LA GENERACIÓN E INTEGRACIÓN DE LOS EXPEDIENTES DE LOS DIFERENTES TIPOS DE APOYO DEL PROGRAMA', 'REALIZAR 5 ACCIONES EN EL SISTEMA INFORMÁTICO DEL PROCODES DURANTE EL EJERCICIO FISCAL 2024 QUE CONTRIBUYA EN LA GENERACIÓN E INTEGRACIÓN DE LOS EXPEDIENTES DE LOS DIFERENTES TIPOS DE APOYO DEL PROGRAMA.', 'REALIZAR 3 ACCIONES EN EL SISTEMA INFORMÁTICO DEL PROCODES DURANTE EL EJERCICIO FISCAL 2024 QUE CONTRIBUYA EN LA GENERACIÓN E INTEGRACIÓN DE LOS EXPEDIENTES DE LOS DIFERENTES TIPOS DE APOYO DEL PROGRAMA.', '90', 'REGISTRAR EN EL SISTEMA LOS AVANCES FÍSICO FINANCIERO DE LOS DIFERENTES TIPOS DE APOYO DEL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE (PROCODES) DE LA CONANP DEL EJERCICIO FISCAL 2024 QUE SE EJECUTAN EN EL ÁREA NATURAL PROTEGIDA', '05', '20', 'GENERAR 3 REPORTES TRIMESTRALES DURANTE EL AÑO DE LOS AVANCES FÍSICO FINANCIERO DEL PROGRAMA PROCODES DE LA CONANP DEL EJERCICIO FISCAL 2024 QUE SE EJECUTAN EN EL ÁREA NATURAL PROTEGIDA', 'GENERAR 1 REPORTE TRIMESTRAL DURANTE EL AÑO DE LOS AVANCES FÍSICO FINANCIEROS DEL PROGRAMA PROCODES Y DEL EJERCICIO FISCAL 2023 QUE SE EJECUTAN EN EL ÁREA NATURAL PROTEGIDA', 'NO SE GENERA NINGÚN REPORTE TRIMESTRAL DURANTE EL AÑO DE LOS AVANCES FÍSICO FINANCIEROS DEL PROGRAMA PROCODES Y DEL EJERCICIO FISCAL 2023 QUE SE EJECUTAN EN EL ÁREA NATURAL PROTEGIDA', '90', 'REGISTRAR EN EL SISTEMA INFORMÁTICO DE CONTRALORÍA SOCIA