INSERT INTO `sed_individuales` VALUES (537, 'VISS580906', 'OPERAR EL 100 POR CIENTO DE PROYECTOS, CURSOS Y/O ESTUDIOS DESIGNADOS PARA EL SEGUIMIENTO POR MI SUPERIOR JERÁRQUICO DE LOS PROGRAMAS DE SUBSIDIO DEL EJERCICIO FISCAL 2024', '02', '30', '90 A 100', '60 A 89', 'MENOR A 60', '90', 'ATENDER EL 100 POR CIENTO LOS ASUNTOS EN MATERIA DE CONTRALORÍA SOCIAL, DEL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE PROCODES Y EL PROGRAMA PARA LA PROTECCIÓN Y RESTAURACIÓN DE ECOSISTEMAS Y ESPECIES PRIORITARIAS PROREST, CORRESPONDIENTE AL EJERCICIO FISCAL 2024 EN MI CARÁCTER DE ENLACE DEL SISTEMA INFORMÁTICO DE CONTRALORÍA SOCIAL SICS.', '02', '40', '90 A 100', '60 A 89', 'MENORA 60', '90', 'LOS DEMÁS QUE ME CONFIERE Y Y/O INSTRUYA MI JEFE INMEDIATO O EL DIRECTOR REGIONAL, UNIDAD ADMINISTRATIVA, LA UNIDAD TÉCNICA, O LA UNIDAD JURÍDICA DE LA DIRECCIÓN REGIONAL, ASÍ COMO LAS QUE SEÑALE LAS DISPOSICIONES LEGALES Y REGLAMENTARIAS VIGENTES DENTRO DE SU ALCANCE Y MARCO DE ACTUACIÓN, ORIENTADOS A ASEGURAR LA ADECUADA OPERACIÓN DEL ANP, DE LA DIRECCIÓN REGIONAL Y DE LA CONSERVACIÓN DEL MEDIO AMBIENTE.', '02', '30', '90 A 100', '60 A 89', 'MENOR A 60', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
