INSERT INTO `sed_individuales` VALUES (541, 'ZAGD790206', 'SUPERVISAR EL SEGUIMIENTO A OBJETIVOS Y METAS ANUALES ALINEADAS A LA PLANEACIÓN ESTRATÉGICA DEL ÁREA NATURAL PROTEGIDA', '10', '20', 'SUPERVISIÓN DE LAS ACCIONES REALIZADAS PARA EL SEGUIMIENTO DEL 100% DE LOS OBJETIVOS Y METAS ANUALES ALINEADAS A LA PLANEACIÓN ESTRATÉGICA DEL ANP', 'SUPERVISIÓN DE LAS ACCIONES REALIZADAS PARA EL SEGUIMIENTO DE MENOS DEL 50% DE LOS OBJETIVOS Y METAS ANUALES ALINEADAS A LA PLANEACIÓN ESTRATÉGICA DEL ANP', 'NO SUPERVISIÓN DE NINGUNA ACCIÓN PARA EL SEGUIMIENTO DE LOS OBJETIVOS Y METAS ANUALES ALINEADAS A LA PLANEACIÓN ESTRATÉGICA DEL ANP', '90', 'FUNGIR COMO SECRETARIO TÉCNICO EN LAS SESIONES DEL CONSEJO ASESOR DEL ÁREA NATURAL PROTEGIDA.', '10', '20', 'PARTICIPACIÓN COMO SECRETARIO TÉCNICO DEL CONSEJO ASESOR DEL ANP EN EL 100% DE LAS SESIONES CONVOCADAS.', 'PARTICIPACIÓN COMO SECRETARIO TÉCNICO DEL CONSEJO ASESOR DEL ANP EN EL 50% DE LAS SESIONES CONVOCADAS.', 'SIN PARTICIPACIÓN COMO SECRETARIO TÉCNICO DEL CONSEJO ASESOR DEL ANP EN NINGUNA DE LAS SESIONES CONVOCADAS.', '90', 'SUPERVISAR LA COORDINACIÓN INTERINSTITUCIONAL DE LA DIRECCIÓN DE ÁREA NATURAL PROTEGIDA CON INSTANCIAS GUBERNAMENTALES DEL SECTOR MEDIO AMBIENTE', '10', '20', 'SUPERVISIÓN DEL 90% DE ACCIONES DE COORDINACIÓN INTERINSTITUCIONAL CON INSTANCIAS GUBERNAMENTALES DEL SECTOR MEDIO AMBIENTE', 'SUPERVISIÓN DE MENOS DEL 50% DE ACCIONES DE COORDINACIÓN INTERINSTITUCIONAL CON INSTANCIAS GUBERNAMENTALES DEL SECTOR MEDIO AMBIENTE', 'SIN SUPERVISIÓN A NINGUNA DE LAS ACCIONES DE COORDINACIÓN INTERINSTITUCIONAL CON INSTANCIAS GUBERNAMENTALES DEL SECTOR MEDIO AMBIENTE', '90', 'FUNGIR COMO SECRETARIO TÉCNICO DE LOS DICTÁMENES TÉCNICO Y ECONÓMICO DE LOS PROGRAMAS DE SUBSIDIO QUE EJERCE LA DIRECCIÓN DE ANP EN EL PRESENTE EJERCICIO FISCAL.', '10', '20', 'FUNGIR COMO SECRETARIO TÉCNICO EN EL 100% DE LAS SESIONES DE DICTAMEN TÉCNICO Y ECONÓMICO DE LOS PROGRAMAS DE SUBSIDIO QUE EJERCE LA DIRECCIÓN DE ANP EN EL PRESENTE EJERCICIO FISCAL.', 'FUNGIR COMO SECRETARIO TÉCNICO EN MENOS DEL 50% DE LAS SESIONES DE DICTAMEN TÉCNICO Y ECONÓMICO DE LOS PROGRAMAS DE SUBSIDIO QUE EJERCE LA DIRECCIÓN DE ANP EN EL PRESENTE EJERCICIO FISCAL.', 'NO FUNGIR COMO SECRETARIO TÉCNICO EN NINGUNA DE LAS SESIONES DE DICTAMEN TÉCNICO Y ECONÓMICO DE LOS PROGRAMAS DE SUBSIDIO QUE EJERCE LA DIRECCIÓN DE ANP EN EL PRESENTE EJERCICIO FISCAL.', '90', 'PROMOVER EL FORTALECIMIENTO DEL EQUIPO QUE CONFORMA LA DIRECCIÓN DEL ÁREA NATURAL PROTEGIDA, CON EL PROPÓSITO DE INDUCIR LA MEJOR CONTINUA DE LOS PROCESOS LABORALES.', '10', '20', 'AL MENOS UNA ACCIÓN PROMOVIDA EXITOSAMENTE PARA EL FORTALECIMIENTO DEL EQUIPO QUE CONFORMA LA DIRECCIÓN DEL ÁREA NATURAL PROTEGIDA, QUE INCIDE EN LA MEJOR CONTINUA DE LOS PROCESOS LABORALES.', 'UNA SOLA ACCIÓN PROMOVIDA SIN ÉXITO EN EL FORTALECIMIENTO DEL EQUIPO QUE CONFORMA LA DIRECCIÓN DEL ÁREA NATURAL PROTEGIDA, Y QUE NO INCIDE EN LA MEJOR CONTINUA DE LOS PROCESOS LABORALES.', 'NINGUNA ACCIÓN PROMOVIDA EXITOSAMENTE PARA EL FORTALECIMIENTO DEL EQUIPO QUE CONFORMA LA DIRECCIÓN DEL ÁREA NATURAL PROTEGIDA, QUE INCIDIERA EN LA MEJOR CONTINUA DE LOS PROCESOS LABORALES.', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (542, 'ZAGJ800429', 'SUPERVISAR LAS ACCIONES QUE SE REALICEN DENTRO DEL ÁREA NATURAL PROTEGIDA SE AJUSTEN A LOS PROPÓSITOS DE LOS ORDENAMIENTOS LEGALES APLICABLES EN MATERIA DE PROTECCIÓN, MANEJO Y RESTAURACIÓN PARA LA CONSERVACIÓN DE LOS ECOSISTEMAS Y SU BIODIVERSIDAD.', '10', '25', '100-75', '74-50', '49-25', '90', 'PROMOVER EL DESARROLLO COMUNITARIO PARTICIPATIVO EN EL ÁREA EN LO RELATIVO A LOS PROGRAMAS DE SUBSIDIOS Y PROYECTOS DE CONSERVACIÓN PARA EL DESARROLLO, Y DE MANEJO PARA EL USO Y APROVECHAMIENTO DE LOS ECOSISTEMAS Y SU BIODIVERSIDAD. RECIBIR LAS SOLICITUDES E INTEGRAR LOS EXPEDIENTES PARA EL OTORGAMIENTO DE LICENCIAS, PERMISOS, AUTORIZACIONES Y CONCESIONES', '10', '25', '100-75', '74-50', '49-25', '90', 'INTERVENIR EN LA FORMULACIÓN Y EJECUCIÓN DE LOS PROGRAMAS DE ORDENAMIENTO ECOLÓGICO QUE INCIDAN EN EL ÁREA NATURAL PROTEGIDA Y SUS ZONAS DE INFLUENCIA, CONFORMAR EL SISTEMA DE INFORMACIÓN CON LOS DATOS BIOLÓGICOS, SOCIALES, ECONÓMICOS Y CARTOGRÁFICOS DEL ÁREA NATURAL PROTEGIDA CORRESPONDIENTE', '10', '25', '100-75', '74-50', '49-25', '90', 'PARTICIPAR EN LOS PROGRAMAS, PROYECTOS Y ACCIONES DE ESPECIES Y POBLACIONES CONSIDERADAS COMO PRIORITARIAS PARA LA CONSERVACIÓN, EN LAS ÁREAS NATURALES PROTEGIDAS DE SU COMPETENCIA. DIRIGIR Y EJECUTAR LOS PROGRAMAS PARA LA ATENCIÓN DE CONTINGENCIAS AMBIENTALES', '10', '25', '100-75', '74-50', '49-25', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (543, 'ZAMA800508', 'COADYUVAR EN LA FORMULACIÓN DEL PROGRAMA DE MANEJO DE LA RESERVA DE LA BIOSFERA SIERRA GORDA DE GUANAJUATO, DE CONFORMIDAD CON LOS LINEAMIENTOS QUE EMITA LA COMISIÓN Y DEMÁS DISPOSICIONES JURÍDICAS APLICABLES.', '10', '40', '1', '0.75', '0.5', '90', 'COADYUVAR EN LA EMISIÓN DE OPINIONES TÉCNICAS ANTE LA DIRECCIÓN REGIONAL PARA EL OTORGAMIENTO DE PERMISOS Y/O AUTORIZACIONES EN MATERIA DE EVALUACIÓN DEL IMPACTO AMBIENTAL, FORESTAL, CAMBIO DE USO DE SUELO EN TERRENOS FORESTALES Y EJECUCIÓN DE OBRAS Y ACTIVIDADES QUE SE PRETENDAN REALIZAR EN LA RESERVA DE LA BIOSFERA SIERRA GORDA DE GUANAJUATO.', '10', '20', '1', '0.75', '0.5', '90', 'ADMINISTRAR EL SISTEMA GENERAL DE PROGRAMAS OPERATIVOS ANUALES (SGPOA) REALIZANDO LA CAPTURA DE LOS PROYECTOS Y ACTIVIDADES DEL POA 2022 DE LA RB SIERRA GORDA DE GUANAJUATO; ASÍ COMO LOS INFORMES TRIMESTRALES CORRESPONDIENTES, CUMPLIENDO CON LOS PERIODOS DE CAPTURA Y ATENDIENDO LOS COMENTARIOS DEL PRESENTE POR PARTE DE LA DIRECCIÓN DE EVALUACIÓN Y SEGUIMIENTO.', '10', '15', '1', '0.75', '0.5', '90', 'ADMINISTRAR EL SISTEMA DE SEGUIMIENTO A PROYECTOS (SISEP) REALIZANDO LA CAPTURA DE INFORMACIÓN Y ELABORACIÓN DE REPORTES TÉCNICOS 2024 DE LA RB SIERRA GORDA DE GUANAJUATO, CUMPLIENDO CON LOS PERIODOS DE CAPTURA Y ATENDIENDO LAS OBSERVACIONES POR PARTE DEL PROYECTO COSMOS-FONDO MEXICANO PARA LA CONSERVACIÓN DE LA NATURALEZA.', '10', '15', '1', '0.75', '0.5', '90', 'FORTALECER LAS CAPACIDADES COMUNITARIAS DE LAS PERSONAS QUE PARTICIPAN EN LA IMPLEMENTACIÓN DE ESQUEMAS DE DESARROLLO SOSTENIBLE EN LAS ACTIVIDADES AGROPECUARIAS QUE SE REALIZAN EN LA RB SIERRA GORDA DE GUANAJUATO.', '10', '10', '1', '0.75', '0.5', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (544, 'ZAMD820327', 'DISEÑAR, GENERAR Y ELABORAR EL 100% DE MATERIAL IMPRESO O DIGITAL CON FINES DIDÁCTICOS E INTERPRETATIVOS QUE APOYEN EN LA DIFUSIÓN DE LOS OBJETOS DE CONSERVACIÓN DE LA ANP', '10', '20', '1', '0.75', 'GENERÓ 5 MATERIALES DE DIFUSIÓN - 50%', '90', 'ELABORAR 10 MATERIALES DE DIFUSIÓN - 100%', '10', '20', '1', '0.75', '0.5', '90', 'REALIZAR Y PARTICIPAR EN ACTIVIDADES DE EDUCACIÓN AMBIENTAL PRESENCIALES O EN LÍNEA CON LAS COMUNIDADES QUE INTEGRAN ESTA ANP, PARTICIPAR EN EVENTOS CULTURALES COORDINADAS CON INSTITUCIONES EDUCATIVAS PARA DIFUNDIR LA IMPORTANCIA DE LA ANP Y SUS OBJETOS DE CONSERVACIÓN.', '10', '20', '10 - 100%', '0.75', '5 - 50%', '90', 'COORDINAR LA OPERACIÓN DEL CENTRO DE VISITANTES Y MUSEO SCHUK TOAK Y MANTENERLO EN FUNCIONAMIENTO ÓPTIMO PARA EL LOGRO DE LOS OBJETIVOS DEL PROGRAMA DE EDUCACIÓN AMBIENTAL.', '10', '20', '1', '0.75', '0.5', '90', 'ATENDER LA TOTALIDAD DE TRAMITES DE PERMISOS Y AUTORIZACIONES DE LAS DISTINTAS ACTIVIDADES QUE SE REALIZAN EN EL ANP EN COORDINACIÓN CON LA DIRECCIÓN DEL ANP Y LA DIRECCIÓN REGIONAL', '10', '20', '1', '0.75', '0.5', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (545, 'ZAMM810821', 'APOYAR Y EJECUTAR LA PLANEACIÓN DEL PRESUPUESTO REGIONAL, PRESENTANDO INFORMES FINANCIEROS, PARA GARANTIZAR UN EFICIENTE CIERRE DE PERIODO ANUAL, MEDIANTE 22 ESTADOS DEL EJERCICIO DE LAS ANP´S Y LA DIRECCIÓN REGIONAL, CONSIDERANDO LOS TIEMPOS PRESUPUESTALES ASIGNADOS, EJERCIDOS, COMPROMETIDOS Y DISPONIBLES POR PARTIDA DE LOS PRESUPUESTOS FISCALES Y DE SUBSIDIOS.', '10', '20', '1', '0.75', '0.5', '90', 'CAPTURAR, CONCILIAR Y APOYAR EN LOS PROCESOS DE LA CONTABILIDAD GENERAL Y PRESUPUESTAL A TRAVÉS DE LAS DISTINTAS PLATAFORMAS (SAACG-SICOP-SIAFF), POR LOS RECURSOS FISCALES AUTORIZADOS A LA DIRECCIÓN REGIONAL CENTRO Y EJE NEOVOLCÁNICO, OBTENIENDO 36 CONCILIACIONES BANCARIAS.', '10', '20', '1', '0.75', '0.5', '70', 'RECIBIR Y VALIDAR LAS SUFICIENCIAS Y ADECUACIONES PRESUPUESTALES, ELABORADAS DE ACUERDO CON LA NORMATIVIDAD VIGENTE, DANDO SEGUIMIENTO PARA LA INTEGRACIÓN DE 650 EXPEDIENTES CORRECTOS Y PROCEDER AL PAGO POR MEDIO DE LOS SISTEMAS SICOP, SIAFF. COMPRANET, CADENAS PRODUCTIVAS.', '10', '20', '1', '0.75', '0.5', '70', 'CONCENTRAR Y ALIMENTAR BASE DE DATOS DE TODOS LOS PAGOS REALIZADOS MENSUALMENTE (PROYECTOS, GASTO CORRIENTE, VIÁTICOS, PASAJES, INTERESES, GASTOS DE OPERACIÓN, ETC.) PARA GENERAR CONCILIACIONES PRESUPUESTALES Y CONTABLES, DETERMINANDO LOS IMPUESTOS RETENIDOS Y ENTERADOS PARA POSTERIOR PROPORCIONAR LOS DATOS NECESARIOS PARA PRESENTACIÓN DE DECLARACIONES INFORMATIVAS Y CUMPLIR CON LAS OBLIGACIONES FISCALES A LAS QUE ESTAMOS SUJETOS.', '10', '20', '1', '0.75', '0.5', '90', 'LLEVAR CONTROL DE LA EJECUCIÓN PRESUPUESTAL DE RUBRO DE COMBUSTIBLE PARA LA OPERACIÓN DE LAS ANP´S DE MANERA MENSUAL.', '10', '20', '1', '0.75', '0.5', '70', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado