INSERT INTO `sed_individuales` VALUES (548, 'ZECH730920', 'EJECUTAR LAS ACCIONES PARA CONSERVAR LOS ECOSISTEMAS Y SU BIODIVERSIDAD, CONFORME A LOS OBJETIVOS Y LINEAMIENTOS ESTABLECIDOS EN EL DECRETO Y EL PROGRAMA DE MANEJO DEL ÁREA RESPECTIVA', '01', '20', '100 % DE LAS ACCIONES DEL ANP SE REALIZAN EN CUMPLIMIENTO AL PROGRAMA DE MANEJO', '90 % DE LAS ACCIONES DEL ANP SE REALIZAN EN CUMPLIMIENTO AL PROGRAMA DE MANEJO', '80 % DE LAS ACCIONES DEL ANP SE REALIZAN EN CUMPLIMIENTO AL PROGRAMA DE MANEJO', '90', 'SUPERVISAR QUE LAS ACCIONES QUE SE REALICEN DENTRO DEL ÁREA NATURAL PROTEGIDA SE AJUSTEN A LOS PROPÓSITOS DE LOS ORDENAMIENTOS LEGALES APLICABLES EN MATERIA DE PROTECCIÓN, MANEJO Y RESTAURACIÓN PARA LA CONSERVACIÓN DE LOS ECOSISTEMAS Y SU BIODIVERSIDAD.', '01', '20', 'SUPERVISION DEL 95 % A LAS ANP PARA VERIFICAR SU APLICACIÓN EN MATERIA DE CONSERVACION DE ECOSISITEMAS', 'SUPERVISION DEL 85 % A LAS ANP PARA VERIFICAR SU APLICACIÓN EN MATERIA DE CONSERVACION DE ECOSISITEMAS', 'SUPERVISION DEL 80 % A LAS ANP PARA VERIFICAR SU APLICACIÓN EN MATERIA DE CONSERVACION DE ECOSISITEMAS', '90', 'PROMOVER LOS PROGRAMAS DE SUBSIDIOS Y PROYECTOS DE CONSERVACIÓN PARA EL DESARROLLO DEL ÁREA NATURAL PROTEGIDA CORRESPONDIENTE, ASÍ COMO PARTICIPAR EN LOS PROGRAMAS, PROYECTOS Y ACCIONES DE ESPECIES Y POBLACIONES CONSIDERADAS COMO PRIORITARIAS PARA LA CONSERVACIÓN, EN LAS ÁREAS NATURALES PROTEGIDAS DE SU COMPETENCIA', '01', '20', 'ATENDER AL 100% LOS PROYECTOS AUTORIZADOS', 'ATENDER AL 80% LOS PROYECTOS AUTORIZADOS', 'ATENDER AL 70% LOS PROYECTOS AUTORIZADOS', '90', 'EMITIR DICTÁMENES TÉCNICOS DE SOPORTE ANTE EL COMISIONADO NACIONAL, LA DIRECCIÓN GENERAL DE OPERACIÓN REGIONAL O LA DIRECCIÓN REGIONAL QUE CORRESPONDA, PARA EL OTORGAMIENTO, MODIFICACIÓN, PRÓRROGA, RESCATE, SUSPENSIÓN, EXTINCIÓN, REVOCACIÓN O ANULACIÓN DE CONCESIONES, PERMISOS, LICENCIAS O AUTORIZACIONES EN MATERIA DE INVESTIGACIÓN, USO Y APROVECHAMIENTO DE LOS ECOSISTEMAS Y SU BIODIVERSIDAD, ASÍ COMO PARA EMITIR LA OPINIÓN QUE CORRESPONDA EN MATERIA DE EVALUACIÓN DEL IMPACTO AMBIENTAL, FORESTAL, ZONA FEDERAL MARÍTIMO TERRESTRE, VIDA SILVESTRE, CAMBIO DE USO DE SUELO EN TERRENOS FORESTALES, PRESTACIÓN DE SERVICIOS Y EJECUCIÓN DE OBRAS Y ACTIVIDADES QUE SE REALICEN EN EL ÁREA NATURAL PROTEGIDA, ASÍ COMO PARA EL ORDENAMIENTO ECOLÓGICO CORRESPONDIENTE', '01', '20', 'ATENDER AL 100% LOS DICTAMENES TECNICOS', 'ATENDER AL 90 % LOS DICTAMENES TECNICOS', 'ATENDER AL 80 % LOS DICTAMENES TECNICOS', '90', 'SUPERVISAR LAS OBRAS, ESTUDIOS Y SERVICIOS RELACIONADOS CON EL ÁREA NATURAL PROTEGIDA, EN COORDINACIÓN CON LA DIRECCIÓN REGIONAL QUE CORRESPONDA, SIGUIENDO LOS LINEAMIENTOS ESTABLECIDOS POR LA DIRECCIÓN EJECUTIVA DE ADMINISTRACIÓN Y EFECTIVIDAD INSTITUCIONAL', '01', '20', 'SUPERVISION DEL 95 % A LAS ANP PARA VER AVANCES DE LAS OBRAS, ESTUDIOS Y SERVICIOS', 'SUPERVISION DEL 85 % A LAS ANP PARA VER AVANCES DE LAS OBRAS, ESTUDIOS Y SERVICIOS', 'SUPERVISION DEL 80 % A LAS ANP PARA VER AVANCES DE LAS OBRAS, ESTUDIOS Y SERVICIOS', '90', NULL, NULL, 1, '2024', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', 'Será establecido y demostrado con evidencias documentales, al momento de la aplicación de la evaluación.', NULL, NULL, NULL, NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
