INSERT INTO `sed_individuales` VALUES (550, 'DUVJ740519', 'CONSOLIDAR LA OPERACIÓN Y MANEJO DE LAS ÁREAS NATURALES PROTEGIDAS DE LA REGIÓN NOROESTE Y ALTO GOLFO DE CALIFORNIA, MEDIANTE LA ATENCIÓN EN LA RADICACIÓN, RECEPCIÓN DE COMPROBACIONES Y CONSOLIDACIÓN DE LOS RECURSOS FINANCIEROS A LAS ANPS DE LA REGIÓN.', '08', '30', 'ATENCIÓN A TODAS LAS ANPS DE LA REGIÓN, EN LA RADICACIÓN ADMINISTRACIÓN Y EJERCICIO DE LOS RECURSOS FINANCIEROS AL 75%-100% CON CALIDAD.', 'ATENCIÓN A TODAS LAS ANPS DE LA REGIÓN, EN LA RADICACIÓN ADMINISTRACIÓN DEL EJERCICIO DE LOS RECURSOS FINANCIEROS AL 74%-60% CON CALIDAD.', '\"MENOS DEL 50% DE ATENCIÓN A LAS ANPS DE LA REGIÓN, EN LA RADICACIÓN ADMINISTRACIÓN Y EJERCICIO DE LOS RECURSOS FINANCIEROS CON CALIDAD', '90', 'CONSOLIDAR LA OPERACIÓN Y MANEJO DE LAS ÁREAS NATURALES PROTEGIDAS DE LA REGIÓN NOROESTE Y ALTO GOLFO DE CALIFORNIA, MEDIANTE LA ATENCIÓN EN LA ADMINISTRACIÓN Y CONTROL DE LOS RECURSOS MATERIALES A LAS ANPS DE LA REGIÓN.', '08', '30', 'ATENCIÓN A TODAS LAS ANPS DE LA REGIÓN, EN LA ADMINISTRACIÓN Y CONTROL DE LOS RECURSOS MATERIALES AL 75%-100% CON CALIDAD.', 'ATENCIÓN A TODAS LAS ANPS DE LA REGIÓN, EN LA ADMINISTRACIÓN Y CONTROL DE LOS RECURSOS MATERIALES AL 74%-60% CON CALIDAD.', 'MENOS DEL 50% DE ATENCIÓN A LAS ANPS DE LA REGIÓN, EN LA RADIACIÓN ADMINISTRACIÓN Y CONTROL DE LOS RECURSOS MATERIALES CON CALIDAD.', '90', 'CONSOLIDAR LA OPERACIÓN Y MANEJO DE LAS ÁREAS NATURALES PROTEGIDAS DE LA REGIÓN NOROESTE Y ALTO GOLFO DE CALIFORNIA, MEDIANTE LA ATENCIÓN EN LA ADMINISTRACIÓN Y CONTROL DE LOS RECURSOS HUMANOS A LAS ANPS DE LA REGIÓN.', '08', '20', 'ATENCIÓN A TODAS LAS ANPS DE LA REGIÓN, EN LA ADMINISTRACIÓN Y CONTROL DE LOS RECURSOS HUMANOS AL 75%-100% CON CALIDAD.', 'ATENCIÓN A TODAS LAS ANPS DE LA REGIÓN, EN LA ADMINISTRACIÓN Y CONTROL DE LOS RECURSOS HUMANOS AL 74%-60% CON CALIDAD.', 'MENOS DEL 50% DE ATENCIÓN A LAS ANPS, DE LA REGIÓN EN LA RADICACIÓN ADMINISTRACIÓN Y CONTROL DE LOS RECURSOS HUMANOS CON CALIDAD.', '90', 'O