INSERT INTO `sed_individuales` VALUES (568, 'PEHA971110', 'COLABORAR EN LA FORMULACIÓN DEL PROGRAMA DE MANEJO DEL PARQUE NACIONAL LOS MÁRMOLES, MEDIANTE LA REVISIÓN DOCUMENTAL, RECOPILACIÓN DE INFORMACIÓN Y LA ELABORACIÓN DE TABLAS Y MAPAS TEMÁTICOS. ', '10', '30', '90-100', '70-89', 'Menos del 50', NULL, 'PARTICIPAR EN EL PROCESO DE DIFUSIÓN, RECEPCIÓN DE SOLICITUDES, INTEGRACIÓN DE EXPEDIENTES, DICTAMINACIÓN DE LOS PROGRAMAS DE SUBSIDIOS PROCODES Y PROREST. ASÍ COMO EN LA EJECUCIÓN DE LOS PROYECTOS EN APEGO A LA NORMATIVIDAD APLICABLE E IMPULSANDO ACCIONES CON PERSPECTIVA DE GÉNERO.', '10', '20', '90-100', '70-89', 'Menos del 50', NULL, 'DAR SEGUIMIENTO A LAS ACTIVIDADES DE VIGILANCIA Y MONITOREO BIOLÓGICO COMUNITARIO; ASESORAR A LAS BRIGADAS EN EL USO CORRECTO DEL LAS HERRAMIENTAS, APLICACIONES MOVILES, APOYO EN LA IDENTIFICACIÓN DE ESPECIES DE FLORA Y FAUNA Y REPORTE EN CASO DE LA DETECCIÓN DE ALGÚN ILÍCITO AMBIENTAL.', '10', '20', '90-100', '70-89', 'Menos del 50', NULL, ' LLEVAR A CABO ACTIVIDADES DE EDUCACIÓN AMBIENTAL EN CORDINACIÓN CON LOS MIEMBROS DE LAS BRIGADAS DE VIGILANCIA Y MONITOREO BIOLÓGICO COMUNITARIO ASÍ COMO LOS GRUPOS QUE TRABAJEN EN CONSERVACIÓN DE ESPECIES, EN DIFERENTES LOCALIDADES DEL PARQUE, CON TEMATICAS SOBRE: CONSERVACIÓN, BIODIVERSIDAD, AMENAZAS A LA BIODIVERSIDAD Y ECOSISTEMAS.', '10', '15', '90-100', '70-89', 'Menos del 50', NULL, 'DAR ATENCIÓN EN LA RECECPCIÓN DE GRUPOS TURISTICOS O CON FINES DE INVESTIGACIÓN. APOYAR CON EL COBRO DE DERECHOS EN LAS DIFERENTES LOCALIDADES DENTRO DEL PNLM.  ', '10', '15', '90-100', '70-89', 'Menos del 50', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '50-69', '50-69', '50-69', '50-69', '50-69', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (569, 'CASF730430', 'LLEVAR A CABO EL CONTROL MENSUAL DEL PRESUPUESTO ASIGNADO A LA RESERVA DE LA BIÓSFERA MONTES AZULES, RB LACANTÚN, ÁREA DE PROTECCIÓN DE FLORA Y FAUNA CHAN-KIN, NAHÁ Y METZABOK, MONUMENTO NATURAL BONAMPAK Y YAXCHILÁN.', '10', '20', 'SE REALIZA MENSUALMENTE AL 100% EL CONTROL MENSUAL DEL PRESUPUESTO ASIGNADO A LA RESERVA DE LA BIÓSFERA MONTES AZULES, RB LACANTÚN, ÁREA DE PROTECCIÓN DE FLORA Y FAUNA CHAN-KIN, NAHÁ Y METZABOK, MONUMENTO NATURAL BONAMPAK Y YAXCHILÁN', 'SE REALIZA MENSUALMENTE AL 80% EL CONTROL MENSUAL DEL PRESUPUESTO ASIGNADO A LA RESERVA DE LA BIÓSFERA MONTES AZULES, RB LACANTÚN, ÁREA DE PROTECCIÓN DE FLORA Y FAUNA CHAN-KIN, NAHÁ Y METZABOK, MONUMENTO NATURAL BONAMPAK Y YAXCHILÁN', 'NO SE REALIZA MENSUALMENTE EL CONTROL MENSUAL DEL PRESUPUESTO ASIGNADO A LA RESERVA DE LA BIÓSFERA MONTES AZULES, RB LACANTÚN, ÁREA DE PROTECCIÓN DE FLORA Y FAUNA CHAN-KIN, NAHÁ Y METZABOK, MONUMENTO NATURAL BONAMPAK Y YAXCHILÁN', NULL, 'REALIZAR TRAMITES ADMINISTRATIVOS, SOLICITAR Y COMPROBAR COMBUSTIBLE DE LAS TARJETAS ELECTRONICAS PEMEX BIENESTAR Y EDENRED, SOLICITAR VIÁTICOS DEL PERSONAL, TRAMITAR EL REEMBOLSO DE VIÁTICOS Y GASTOS DE CAMPO, SOLICITAR COMPRAS, MANTENIMIENTO Y SERVICIO DEL PARQUE VEHÍCULAR Y DE LOS BIENES MUEBLES E INMUEBLES QUE REQUIERA EL PERSONAL PARA LLEVAR A CABO SUS ACTIVIDADES PROGRAMADAS EN EL POA.', '10', '20', 'EL 100% DE LOS TRÁMITES ADMINISTRATIVOS SE REALIZAN EN TIEMPO Y FORMA', 'EL 80% DE LOS TRÁMITES ADMINISTRATIVOS SE REALIZAN EN TIEMPO Y FORMA', 'MENOS DEL 50% DE LOS TRÁMITES ADMINISTRATIVOS SE REALIZAN EN TIEMPO Y FORMA', NULL, 'MANTENER ACTUALIZADO EL INVENTARIO DE LOS BIENES MUEBLES DE LA RESERVA DE LA BIÓSFERA MONTES AZULES, MONUMENTO NATURAL BONAMPAK Y ÁREA DE PROTECCIÓN NAHÁ Y METZABOK.', '10', '20', 'EL INVENTARIO DE LOS BIENES MUEBLES DE LA RESERVA DE LA BIÓSFERA MONTES AZULES, MONUMENTOS NATURAL BONAMPAK Y ÁREA DE PROTECCIÓN DE FLORA Y FAUNA NAHÁ Y METZABOK.SE ACTUALIZARÁ EN UN 100%', 'EL INVENTARIO DE LOS BIENES MUEBLES DE LA RESERVA DE LA BIÓSFERA MONTES AZULES, MONUMENTOS NATURAL BONAMPAK Y ÁREA DE PROTECCIÓN DE FLORA Y FAUNA NAHÁ Y METZABOK.SE ACTUALIZARÁ EN UN 80%', 'NO SE REALIZA EL INVENTARIO DE LOS BIRENES MUEBLES', NULL, 'CONTROLAR Y SOLICITAR EL PLAN SEMANAL DE RECURSOS DEL PRESUPUESTO DEL PROGRAMA GEF/FANP A TRAVÉS DE LA PLATAFORMA SESAMO Y SUBIRLA AL DRIVE. SUBIR A LA PLATAFORMA SESAMO LAS FACTURAS DE LAS COMPRAS Y GASTOS DEL PROGRAMA, ASÍ MISMO ENVIAR LOS INFORMES SEMESTRALES.', '10', '20', 'SE REALIZA AL 100% EL CONTROL Y LA SOLICITUD DE RECURSOS SEMANAL DEL PROGRAMA GEF/FANP $ 988,728.00 PARA EL MEJOR USO Y DISTRIBUCIÓN DE LOS RECURSOS.', 'SE REALIZA AL 80% EL CONTROL Y LA SOLICITUD DE RECURSOS SEMANAL DEL PROGRAMA GEF/FANP $ 988,728.00 PARA EL MEJOR USO Y DISTRIBUCIÓN DE LOS RECURSOS.', 'SE REALIZA MENOS DEL 50% EL CONTROL Y LA SOLICITUD DE RECURSOS SEMANAL DEL PROGRAMA GEF/FANP $ 988,728.00 PARA EL MEJOR USO Y DISTRIBUCIÓN DE LOS RECURSOS.', NULL, 'SOLICITAR Y VERIFICAR LA APLICACIÓN DE LOS GASTOS DE OPERACIÓN DE LOS PROGRAMAS DE SUBSIDIOS PROCODES Y PROREST', '10', '20', 'SE SOLICITAN AL 100% LOS PAGOS DE LOS GASTOS DE OPERACIÓN DE LOS PROGRAMAS DE SUBSIDIOS PROCODES Y PROREST.', 'SE SOLICITAN AL 80% LOS PAGOS DE LOS GASTOS DE OPERACIÓN DE LOS PROGRAMAS DE SUBSIDIOS PROCODES Y PROREST.', 'NO SE SOLICITAN LOS GASTOS DE OPERACION DE LOS PROGRAMAS DE SUBSIDIOS PROCODES Y PROREST.', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'SE REALIZA MENSUALMENTE AL 50% EL CONTROL MENSUAL DEL PRESUPUESTO ASIGNADO A LA RESERVA DE LA BIÓSFERA MONTES AZULES, RB LACANTÚN, ÁREA DE PROTECCIÓN DE FLORA Y FAUNA CHAN-KIN, NAHÁ Y METZABOK, MONUMENTO NATURAL BONAMPAK Y YAXCHILÁN', 'EL 60% DE LOS TRÁMITES ADMINISTRATIVOS SE REALIZAN EN TIEMPO Y FORMA', 'EL INVENTARIO DE LOS BIENES MUEBLES DE LA RESERVA DE LA BIÓSFERA MONTES AZULES, MONUMENTOS NATURAL BONAMPAK Y ÁREA DE PROTECCIÓN DE FLORA Y FAUNA NAHÁ Y METZABOK.SE ACTUALIZARÁ EN UN 60%', 'SE REALIZA AL 60% EL CONTROL Y LA SOLICITUD DE RECURSOS SEMANAL DEL PROGRAMA GEF/FANP $ 988,728.00 PARA EL MEJOR USO Y DISTRIBUCIÓN DE LOS RECURSOS.', 'SE SOLICITAN AL 60% LOS PAGOS DE LOS GASTOS DE OPERACIÓN DE LOS PROGRAMAS DE SUBSIDIOS PROCODES Y PROREST.', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (570, 'AAVK820417', 'Elaborar mapas para complementar respuestas a oficios que lo requieran en la Dirección Regional y direcciones de áreas protegidas, evaluando si hay predios o proyectos dentro de áreas de interés para la Conanp.', '10', '40', 'Se elaboran mapas del 90% de las solicitudes recibidas en tiempo y forma', 'entre el 89% y el 50%', 'entre el 49% y el 30%', NULL, 'revisar diariamente las publicaciones den el Diario Oficial de la Federación, sección SEDATU, con el fin de detectar en los avisos de deslinde presuntos terrenos nacionales que puedan ser de interés para la Conanp.', '10', '25', 'Se elaboran mapas del 90% de las solicitudes recibidas en tiempo y forma', 'entre el 89% y el 50%', 'entre el 49% y el 30%', NULL, 'Elaborar mapas de los presuntos terrenos nacionales que se publican en el Diario Oficial de la Federación de predios que se encuentran dentro de áreas de interés para la Conanp y avisar al área correspondiente para darle seguimiento ante la SEDATU.', '10', '25', 'Se elaboran mapas del 90% de las publicaciones de presuntos terrenos nacionales en tiempo y forma cuando involucran a un área de interés para la Conanp.', 'entre el 89% y el 50%', 'entre el 49% y el 30%', NULL, 'Recopilar y generar información digital que será utilizada en el proceso de elaboración de la cartografía, que ayude a la toma de decisiones técnicas en el ANP', '10', '5', 'Se descarga y genera el 70% de la información digital que se utiliza en la elaboración de mapas', 'entre el 69% y el 50%', '49%', NULL, 'Elaborar mapas y/o imágenes de apoyo para atender las necesidades de las ANP y de la Regional en cuanto a mapas temáticos, ubicación de coordenadas y asesoría cartográfica.', '10', '5', 'Elaboración de información digital del 90% de las solicitudes recibidas en tiempo y forma', 'entre el 89% y el 50%', '49 %', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'menos del 29%', 'menos del 29%', 'menos del 29%', 'menos del 48%', 'menos del 48%', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (571, 'VIEC990324', 'Llevar a cabo recorridos de supervisión en las islas del APFF-IGC Sinaloa zona Sur, ubicadas en la bahía de Mazatlán, así como en operativos donde participen otras autoridades (PROFEPA, SEMAR, entre otros), para verificar que las actividades realizadas en el área se ajusten al marco regulatorio en materia de área natural protegida, cuando se requiera participar contribuyendo a la conservación de los recursos naturales, las especies clave residentes y migratorias.', '1', '40', 'Llevar a cabo 7 a 10 recorridos de supervisión en las islas del APFF-IGC Sinaloa zona Sur, ubicadas en la bahía de Mazatlán	', 'Llevar a cabo  6 a 4 recorridos de supervisión en las islas del APFF-IGC Sinaloa zona Sur, ubicadas en la bahía de Mazatlán', 'Llevar a cabo 1 recorridos de supervisión y vigilancia en las islas del APFF-IGC Sinaloa zona Sur, ubicadas en la bahía de Mazatlán', '90', 'Realizar recorridos de monitoreo biológico de aves marinas en las islas del APPF IGC Sinaloa zona sur, localizadas en la bahía de Mazatlán.', '1', '40', 'Realizar 7 a 5 recorridos de monitoreo biológico en las islas del APPF IGC Sinaloa zona sur, ubicadas en la bahía de Mazatlán', 'Realizar 4 a 3 recorridos de monitoreo biológico en las islas del APPF IGC Sinaloa zona sur, ubicadas en la bahía de Mazatlán', 'Realizar 1 recorrido de monitoreo biológico en las islas del APPF IGC Sinaloa zona sur, ubicadas en la bahía de Mazatlán', '90', 'Elaborar y actualizar bases de datos del monitoreo biológico y de la actividad turística en las islas del APPF IGC Sinaloa zona sur, localizadas en la bahía de Mazatlán.', '10', '20', ' Actualizar en un 80% base de datos de especies monitoreadas en las islas del APPF IGC Sinaloa zona sur, localizadas frente al municipio de Mazatlán.', ' Actualizar en un 50% base de datos de especies monitoreadas en las islas del APPF IGC Sinaloa zona sur, localizadas frente al municipio de Mazatlán.', ' Actualizar en un 20% base de datos de especies monitoreadas en las islas del APPF IGC Sinaloa zona sur, localizadas frente al municipio de Mazatlán.', '90', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2024', NULL, NULL, NULL, NULL, NULL, 'Llevar a cabo  3 a 2  recorridos de supervisión en las islas del APFF-IGC Sinaloa zona Sur, ubicadas en la bahía de Mazatlán', 'Realizar 2 recorrido de monitoreo biológico en las islas del APPF IGC Sinaloa zona sur, ubicadas en la bahía de Mazatlán', ' Actualizar en un 40% base de datos de especies monitoreadas en las islas del APPF IGC Sinaloa zona sur, localizadas frente al municipio de Mazatlán.', NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (572, 'SAVV661102', 'DAR SEGUIMIENTO A LA ACTUALIZACIÓN Y ELABORACIÓN DE PLANOS OFICIALES Y TEMATICOS DE ANP', '10', '20', '80 A 90 %', '60 A 80 %', 'Menor del 59%', NULL, 'REVISIÓN, DISEÑO Y ACTUALIZACIÓN DE BASES DE DATOS Y ESTADISTICAS DE ANP', '10', '30', '80 A 90 %', '60 A 80 %', 'Menor del 59%', NULL, 'DAR ATENCIÓN A SOLICITUDES DE INFORMACIÓN ESPACIAL DE LAS ANP CON RESPECTO A PREDIOS PARTICULARES Y EJIDOS', '10', '20', '80 A 90 %', '60 A 80 %', 'Menor del 59%', NULL, 'ELABORACIÓN DE DICTAMENES TECNICOS DE ANP PARA LA VALIDACIÓN DE SUPERFICIE Y DELIMITACIÓN DEL POLÍGONO PARA LOS PROGRAMAS DE MANEJO', '10', '30', '80 A 90 %', '60 A 80 %', 'Menor del 59%', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Menor del 60%', 'Menor del 60%', 'Menor del 60%', 'Menor del 60%', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (588, 'MEGV790504', 'Recepción y seguimiento de los diferentes trámites que se atienden en el Área Natural Protegida, las cuales son: las solicitudes de autorizaciones, permisos y avisos para realizar actividades dentro de esta ANP.', '8', '30', 'Atender en tiempo y forma conforme a la normatividad aplicable, las solicitudes de las autorizaciones, los permisos y avisos para realizar actividades dentro del Área Natural Protegida 100%.', 'No atender en tiempo conforme a la normatividad aplicable, las solicitudes de las autorizaciones, los permisos y avisos para realizar actividades dentro del Área Natural Protegida 80%.', 'No atender las solicitudes de las solicitudes de las autorizaciones, los permisos y avisos para realizar actividades dentro del Área Natural Protegida 50%.', NULL, 'Seguimiento al tema de cobro de derechos conforme a la Ley Federal de Derechos (LFD) de los Artículos 194 facción C y 198 fracción II, conforme a la normatividad turística y otras actividades en Áreas Naturales Protegidas.', '10', '10', '100%.', '80%.', '50%.', NULL, 'Coadyuvar con la Dirección de Área Natural Protegida para la recepción y el seguimiento de oficialía de partes de asuntos contenciosos (para turnar a la Subdirección de Asuntos Contenciosos Regional), apoyar en la atención de solicitudes de información y enlace de concentración del tema de organización documental (archivonomía).\r\n\r\n', '8', '15', 'Atender en tiempo y forma los requerimientos de asuntos contenciosos, solicitudes de información y requerimientos de organización documental 100%.', 'No atender en tiempo los requerimientos de asuntos contenciosos, solicitudes de información y requerimientos de organización documental 80%.', 'No atender los requerimientos de asuntos contenciosos, solicitudes de información y requerimientos de organización documental 50%.', NULL, 'Operar proyectos de los programas de subsidios. Y atención y seguimiento de las versiones públicas del Sistema de Portales de Obligaciones de Transparencia de SIPOT de los programas de subsidios.', '8', '25', 'Atender en tiempo y forma de conformidad con la normatividad de los programas PROCODES y PROREST y conforme a la normatividad de la Ley Federal de transparencia 100%.', 'No atender en tiempo de conformidad con la normatividad de los programas PROCODES y PROREST y conforme a la normatividad de la Ley Federal de transparencia 80%.', 'No atender de conformidad con la normatividad de los programas PROCODES y PROREST y conforme a la normatividad de la Ley Federal de transparencia 50%.', NULL, 'Control y seguimiento de Recursos Humanos y la debida aplicación de controles, tales como: las incidencias del personal, metas, evaluaciones, gratificaciones, bonos, aguinaldos, uniformes, temas del sindicato, entro otros.', '8', '20', 'Atender en tiempo y forma el seguimiento de Recursos humanos 100%.', 'No atender en tiempo el seguimiento de Recursos humanos 80%.', 'No atender el seguimiento de Recursos humanos 50%.', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'No atender en tiempo y forma conforme a la normatividad aplicable, las solicitudes de las autorizaciones, los permisos y avisos para realizar actividades dentro del Área Natural Protegida 60%.', '60%.', 'No atender en tiempo y forma los requerimientos de asuntos contenciosos, solicitudes de información y requerimientos de organización documental 60%.', 'No atender en tiempo y forma de conformidad con la normatividad de los programas PROCODES y PROREST y conforme a la normatividad de la Ley Federal de transparencia 60%.', 'No atender en tiempo y forma el seguimiento de Recursos humanos 60%.', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (573, 'AEQG810724', 'Llevar el control, seguimiento y resguardo de Asistencia Quincenal del personal de oficina regional y ANP´S, así como de solicitudes de vacaciones 1er y 2do periodo, vacaciones extraordinarias, días económicos, licencias médicas, licencias de paternidad, maternidad, tolerancia de horario.', '10', '30', '100-85', '84-70', '49-0', NULL, 'Realizar  Campañas de Ahorro Solidario, Potenciación de Seguro de Vida Institucional, seguimiento de credencializacion 2025 de todo el personal, Altas de ISSSTE e Inscripción Fonac para personal de nuevo ingreso.', '10', '20', '100-85', '84-70', '49-0', NULL, 'Solicitar Cédulas de Identificación para el Programa de Servicio Social y/o Prácticas Profesionales 2025 en oficina regional y ANP´S, así como solicitud y seguimiento de recepción de cartas de inicio y termino para enviarse al prestador(a).', '10', '20', '100-85', '84-70', '49-0', NULL, 'Apoyar en las contrataciones del personal eventual y a través del procedimiento del Servicio Profesional de Carrera, así como actualizar y control de los expedientes del personal de oficina regional y ANP´S.', '10', '10', '100-85', '84-70', '49-0', NULL, 'Elaboración de actividades para Perspectiva de Género  y  seguimiento al  programa de Equidad de Género e Igualdad laboral recabando la documentación del personal de oficina regional y ANP´S, asi como persona consejera para el Protocolo para la prevención, atención y sanción del hostigamiento sexual y acoso sexual.', '10', '20', '100-85', '84-70', '49-0', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '69-50', '69-50', '69-50', '69-50', '69-50', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (574, 'HENJ600430', 'Coordinar y dar seguimiento al desarrollo de acciones y proyectos relacionados con tres POA 2025 y líneas estratégicas con la generación\r\n de;\r\n•	Un programa  de protección y vigilancia \r\n•	Un programa de educación ambiental\r\n•	Un programa de incendios forestales \r\n•	Un programa de monitoreo biológico\r\nPara el complejo selva lacandona\r\n(Reserva de la Biosfera Montes Azules, Lacan-tún, Área de Protección de Flora y Fauna Chankin,  Nahá y Metzabok, Monumento Natural Bonampak y Yaxchilán).\r\n', '10', '20', 'Se cumplió con el 90% la Coordinar y el seguimiento al desarrollo de acciones y proyectos relacionados con el POA 2025. Se generaron los programas y aplicaron: •	Protección y vigilancia •	Educación ambiental •	Incendios forestales •	Monitoreo Biológico  Para el complejo selva lacandona (Reserva de la Biosfera Montes Azules, Lacan-tún, Área de Protección de Flora y Fauna Chankin,  Nahá y Metzabok, Monumento Natural Bonampak y Yaxchilán).', 'Se cumplió con el 70 % la Coordinar y el seguimiento al desarrollo de acciones y proyectos relacionados con el POA 2025. Se generaron los programas y aplicaron: •	Protección y vigilancia •	Educación ambiental •	Incendios forestales •	Monitoreo Biológico  Para el complejo selva lacandona (Reserva de la Biosfera Montes Azules, Lacan-tún, Área de Protección de Flora y Fauna Chankin,  Nahá y Metzabok, Monumento Natural Bonampak y Yaxchilán).', 'Se cumplió con el 50% la Coordinar y el seguimiento al desarrollo de acciones y proyectos relacionados con el POA 2025. Se generaron los programas y aplicaron: •	Protección y vigilancia •	Restauración ecológica •	Educación ambiental •	Incendios forestales •	Monitoreo Biológico  Para el complejo selva lacandona (Reserva de la Biosfera Montes Azules, Lacan-tún, Área de Protección de Flora y Fauna Chankin,  Nahá y Metzabok, Monumento Natural Bonampak y Yaxchilán).', NULL, 'Evaluación de la efectividad de las áreas protegidas:\r\n•	Monumento Natural Bonampak\r\n•	Reserva de la Biosfera Montes Azules\r\n•	APFF Naha\r\n•	APFF Metzabok\r\nY dar seguimiento y atención a dos subconsejos asesores.\r\nPara el complejo selva lacandona\r\n(Reserva de la Biosfera Montes Azules, Lacan-tún, Área de Protección de Flora y Fauna Chankin,  Nahá y Metzabok, Monumento Natural Bonampak y Yaxchilán).\r\n\r\n', '10', '20', 'Se realizó el 90% la evaluación de la efectividad de las áreas protegidas: •	Monumento Natural Bonampak •	Reserva de la Biosfera Montes Azules •	APFF Naha •	APFF Metzabok y seguimiento y atención a dos subconsejos asesores. Para el complejo selva lacandona (Reserva de la Biosfera Montes Azules, Lacan-tún, Área de Protección de Flora y Fauna Chankin,  Nahá y Metzabok, Monumento Natural Bonampak y Yaxchilán).', 'Se realizó el 70% la evaluación de la efectividad de las áreas protegidas: •	Monumento Natural Bonampak •	Reserva de la Biosfera Montes Azules •	APFF Naha •	APFF Metzabok y seguimiento y atención a dos subconsejos asesores. Para el complejo selva lacandona (Reserva de la Biosfera Montes Azules, Lacan-tún, Área de Protección de Flora y Fauna Chankin,  Nahá y Metzabok, Monumento Natural Bonampak y Yaxchilán).', 'Se realizó el 50% la evaluación de la efectividad de las áreas protegidas: •	Monumento Natural Bonampak •	Reserva de la Biosfera Montes Azules •	APFF Naha •	APFF Metzabok y seguimiento y atención a dos subconsejos asesores. Para el complejo selva lacandona (Reserva de la Biosfera Montes Azules, Lacan-tún, Área de Protección de Flora y Fauna Chankin,  Nahá y Metzabok, Monumento Natural Bonampak y Yaxchilán).', NULL, 'Promover los programas de subsidios PROCODES y PROREST 2025, dar seguimiento aquellos proyectos aprobados de la Reserva de la Biosfera Montes Azules, Lacan-Tún, Área de Protección de Flora y Fauna Chankin, Nahá y Metzabok, Monumento Natural Bonampak y Yaxchilán.', '10', '20', 'Se promovi0 el 90% de los programas de subsidios PROCODES y PROREST 2025, Se dio seguimiento aquellos proyectos aprobados. Para el complejo selva lacandona (Reserva de la Biosfera Montes Azules, Lacan-tún, Área de Protección de Flora y Fauna Chankin,  Nahá y Metzabok, Monumento Natural Bonampak y Yaxchilán).', 'Se promovi0 el 70% de los programas de subsidios PROCODES y PROREST 2025, Se dio seguimiento aquellos proyectos aprobados. Para el complejo selva lacandona (Reserva de la Biosfera Montes Azules, Lacan-tún, Área de Protección de Flora y Fauna Chankin,  Nahá y Metzabok, Monumento Natural Bonampak y Yaxchilán).', 'Se promovi0 el 50% de los programas de subsidios PROCODES y PROREST 2025, Se dio seguimiento aquellos proyectos aprobados. Para el complejo selva lacandona (Reserva de la Biosfera Montes Azules, Lacan-tún, Área de Protección de Flora y Fauna Chankin,  Nahá y Metzabok, Monumento Natural Bonampak y Yaxchilán).', NULL, 'Elaboración del diagnóstico actualizado de deforestación e las invasiones a el Complejo Selva Lacandona\r\n•	Seguimiento a 4 denuncias interpuestas\r\n•	Elaboración de tres denuncian en proceso\r\nY gestión para la promoción de una mesa inetrinstitucional del Gobierno Federal para la atención a invasiones y demandas de las poblaciones al interior del complejo selva lacandona.\r\n', '10', '20', 'Se realizó el 90% dela elaboración del diagnóstico actualizado de deforestación y las invasiones a el Complejo Selva Lacandona •	Seguimiento a 4 denuncias interpuestas •	Elaboración de tres denuncian en proceso y de la gestión para la promoción de una mesa inetrinstitucional del Gobierno Federal para la atención a invasiones y demandas de las poblaciones al interior del complejo selva lacandona.', 'Se realizó el 70% dela elaboración del diagnóstico actualizado de deforestación y las invasiones a el Complejo Selva Lacandona •	Seguimiento a 4 denuncias interpuestas •	Elaboración de tres denuncian en proceso y de la gestión para la promoción de una mesa inetrinstitucional del Gobierno Federal para la atención a invasiones y demandas de las poblaciones al interior del complejo selva lacandona.', 'Se realizó el 500% dela elaboración del diagnóstico actualizado de deforestación y las invasiones a el Complejo Selva Lacandona •	Seguimiento a 4 denuncias interpuestas •	Elaboración de tres denuncian en proceso y de la gestión para la promoción de una mesa inetrinstitucional del Gobierno Federal para la atención a invasiones y demandas de las poblaciones al interior del complejo selva lacandona.', NULL, 'Número de dictámenes técnicos de soporte emitidos ante el Comisionado y la Dirección Regional, al respecto de los aprovechamientos, servicios, obras y actividades que se pretendan autorizar dentro del complejo selva lacandona\r\n(Reserva de la Biosfera Montes Azules, Lacan-tún, Área de Protección de Flora y Fauna Chankin,  Nahá y Metzabok, Monumento Natural Bonampak y Yaxchilán).\r\n\r\n', '10', '20', 'Se atendieron el 90% de dictámenes técnicos de soporte emitidos ante el Comisionado y la Dirección Regional, al respecto de los aprovechamientos, servicios, obras y actividades que se pretendan autorizar dentro del complejo selva lacandona (Reserva de la Biosfera Montes Azules, Lacan-tún, Área de Protección de Flora y Fauna Chankin,  Nahá y Metzabok, Monumento Natural Bonampak y Yaxchilán).', 'Se atendieron el 70% de dictámenes técnicos de soporte emitidos ante el Comisionado y la Dirección Regional, al respecto de los aprovechamientos, servicios, obras y actividades que se pretendan autorizar dentro del complejo selva lacandona (Reserva de la Biosfera Montes Azules, Lacan-tún, Área de Protección de Flora y Fauna Chankin,  Nahá y Metzabok, Monumento Natural Bonampak y Yaxchilán).', 'Se atendiera el 50% de dictámenes técnicos de soporte emitidos ante el Comisionado y la Dirección Regional, al respecto de los aprovechamientos, servicios, obras y actividades que se pretendan autorizar dentro del complejo selva lacandona (Reserva de la Biosfera Montes Azules, Lacan-tún, Área de Protección de Flora y Fauna Chankin,  Nahá y Metzabok, Monumento Natural Bonampak y Yaxchilán).', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Se cumplió con el 60% la Coordinar y el seguimiento al desarrollo de acciones y proyectos relacionados con el POA 2025. Se generaron los programas y aplicaron: •	Protección y vigilancia •	Educación ambiental •	Incendios forestales •	Monitoreo Biológico  Para el complejo selva lacandona (Reserva de la Biosfera Montes Azules, Lacan-tún, Área de Protección de Flora y Fauna Chankin,  Nahá y Metzabok, Monumento Natural Bonampak y Yaxchilán).', 'Se realizó el 60% la evaluación de la efectividad de las áreas protegidas: •	Monumento Natural Bonampak •	Reserva de la Biosfera Montes Azules •	APFF Naha •	APFF Metzabok y seguimiento y atención a dos subconsejos asesores. Para el complejo selva lacandona (Reserva de la Biosfera Montes Azules, Lacan-tún, Área de Protección de Flora y Fauna Chankin,  Nahá y Metzabok, Monumento Natural Bonampak y Yaxchilán).', 'Se promovi0 el 60% de los programas de subsidios PROCODES y PROREST 2025, Se dio seguimiento aquellos proyectos aprobados. Para el complejo selva lacandona (Reserva de la Biosfera Montes Azules, Lacan-tún, Área de Protección de Flora y Fauna Chankin,  Nahá y Metzabok, Monumento Natural Bonampak y Yaxchilán).', 'Se realizó el 60% dela elaboración del diagnóstico actualizado de deforestación y las invasiones a el Complejo Selva Lacandona •	Seguimiento a 4 denuncias interpuestas •	Elaboración de tres denuncian en proceso y de la gestión para la promoción de una mesa inetrinstitucional del Gobierno Federal para la atención a invasiones y demandas de las poblaciones al interior del complejo selva lacandona.', 'Se atendiera el 60% de dictámenes técnicos de soporte emitidos ante el Comisionado y la Dirección Regional, al respecto de los aprovechamientos, servicios, obras y actividades que se pretendan autorizar dentro del complejo selva lacandona (Reserva de la Biosfera Montes Azules, Lacan-tún, Área de Protección de Flora y Fauna Chankin,  Nahá y Metzabok, Monumento Natural Bonampak y Yaxchilán).', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (1042, 'GAGO670320', 'Establecer y asegurar durante el ejercicio 2025 las previsiones logísticas y administrativas a fin de llevar a cabo la ejecución y cumplimiento de las metas físico-financieras del Programa Operativo Anual (POA) del Parque Nacional Arrecife de Puerto Morelos.', '10', '5', 'Llevar a cabo el 100% de las acciones logísticas y administrativas para la ejecución y cumplimiento de las metas físico-financieras del POA.', 'Llevar a cabo el 80% de las acciones logísticas y administrativas para la ejecución y cumplimiento de las metas físico-financieras del POA.', 'Llevar a cabo sólo el 50% de las acciones logísticas y administrativas para la ejecución y cumplimiento de las metas físico-financieras del POA.', NULL, 'Establecer y asegurar durante el ejercicio 2025 las previsiones administrativas y operativas para la supervisión de actividades para el manejo de sargazo que se realiza dentro de los límites del Parque Nacional Arrecife de Puerto Morelos conforme a lineamientos, verificaciones en campo y reuniones de trabajo con los representantes de los sectores gubernamentales y hoteleros.', '10', '15', 'Coordinar y ejecutar el 100 por ciento de las acciones administrativas y operativas de la supervisión de actividades para el manejo de sargazo conforme a la normatividad establecida.', 'Coordinar y ejecutar el 80 por ciento de las acciones administrativas y operativas de la supervisión de actividades para el manejo de sargazo conforme a la normatividad establecida.', 'Coordinar y ejecutar sólo el 60 por ciento de las acciones administrativas y operativas de la supervisión de actividades para el manejo de sargazo conforme a la normatividad establecida.', NULL, 'Participar y coadyuvar durante el ejercicio 2025 para que se lleven a cabo las actividades de supervisión y vigilancia que realiza el personal del Parque Nacional Arrecife de Puerto Morelos dentro de los límites de protección.', '10', '20', 'Verificar y dar seguimiento al 100% de las acciones de supervisión y vigilancia que realiza el personal del Parque Nacional Arrecife de Puerto Morelos en campo.	', 'Verificar y dar seguimiento al 80% de las acciones de supervisión y vigilancia que realiza el personal del Parque Nacional Arrecife de Puerto Morelos en campo.', 'Verificar y dar seguimiento sólo al 60% de las acciones de supervisión y vigilancia que realiza el personal del Parque Nacional Arrecife de Puerto Morelos en campo.', NULL, 'Establecer y operar durante el ejercicio 2025 el Programa de Conservación para el Desarrollo Sostenible (PROCODES) así como el Programa para la Protección y Restauración de Ecosistemas y Especies Prioritarias (PROREST).	', '10', '50', 'Dar seguimiento al 100% de los programas de conservación y protección que se desarrollan en el PNAPM en coordinación con la Dirección del área natural protegida.', 'Dar seguimiento al 75% de los programas de conservación y protección que se desarrollan en el PNAPM en coordinación con la Dirección del área natural protegida.', 'Dar seguimiento sólo al 60% de los programas de conservación y protección que se desarrollan en el PNAPM en coordinación con la Dirección del área natural protegida.', NULL, 'Operar y alimentar oportunamente durante el ejercicio 2024 los sistemas de información para el seguimiento y control de los apoyos autorizados de los programas de subsidio: PROCODES, PROREST así como el SICS de la Secretaría de la Función Pública.', '10', '10', 'Alimentar con el 100% de información los sistemas SISPROCODES, SISPROREST y SICS de los proyectos autorizados en el ANP.', 'Alimentar con el 90% de información los sistemas SISPROCODES, SISPROREST y SICS de los proyectos autorizados en el ANP.', 'Cumplir con sólo el 80% de información los sistemas SISPROCODES, SISPROREST y SICS de los proyectos autorizados en el ANP.', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Llevar a cabo menos del 50% de las acciones logísticas y administrativas para la ejecución y cumplimiento de las metas físico-financieras del POA.', 'Coordinar y ejecutar menos del 60 por ciento de las acciones administrativas y operativas de la supervisión de actividades para el manejo de sargazo conforme a la normatividad establecida.', 'Verificar y dar seguimiento a menos del 60% de las acciones de supervisión y vigilancia que realiza el personal del Parque Nacional Arrecife de Puerto Morelos en campo.', 'Dar seguimiento a menos del 60% de los programas de conservación y protección que se desarrollan en el PNAPM en coordinación con la Dirección del área natural protegida.', 'Cumplir sólo con menos del 80% de información los sistemas SISPROCODES, SISPROREST y SICS de los proyectos autorizados en el ANP.', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
