INSERT INTO `sed_individuales` VALUES (612, 'LOME781106', 'ATENDER EL 100% DE LOS PROCEDIMIENTOS ADMINISTRATIVOS O JUDICIALES DONDE SEA PARTE LA DIRECCIÓN REGIONAL NOROESTE Y ALTO GOLFO DE CALIFORNIA O ALGUNA DE SUS DIRECCIONES DE ÁREA ADSCRITAS.', '10', '20', '100-75', '74-60', '49 O MENOS', NULL, 'REVISAR EL 100% DE LAS SOLICITUDES DE AUTORIZACIÓN PARA LA REALIZACIÓN DE ACTIVIDADES DENTRO DE LAS ÁREAS NATURALES PROTEGIDAS ADSCRITAS A LA DIRECCIÓN REGIONAL NOROESTE Y ALTO GOLFO DE CALIFORNIA.', '10', '20', '100-75', '74-60', '49 O MENOS', NULL, 'ELABORAR EL 100% DE LOS PROYECTOS DE CONVENIOS QUE SOLICITE LA DIRECCIÓN REGIONAL NOROESTE Y ALTO GOLFO DE CALIFORNIA O LAS DIRECCIONES DE ÁREAS NATURALES PROTEGIDAS ADSCRITAS A LA MISMA', '10', '20', '100-75', '74-60', '49 O MENOS', NULL, 'REVISAR EL 100% DE LOS PROYECTOS DE CONTRATOS QUE ELABOREN LAS UNIDADES ADMINISTRATIVAS DE LA DIRECCIÓN REGIONAL NOROESTE Y ALTO GOLFO DE CALIFORNIA.', '10', '20', '100-75', '74-60', '49 O MENOS', NULL, 'ATENDER EL 100% DE LAS SOLICITUDES DE ASESORÍA JURÍDICA QUE PRESENTEN LAS UNIDADES ADMINISTRATIVAS DE LA DIRECCIÓN REGIONAL NOROESTE Y ALTO GOLFO DE CALIFORNIA O LAS DIRECCIONES DE ÁREA NATURAL PROTEGIDA ADSCRITAS A LA MISMA', '10', '20', '100-75', '74-60', '49 O MENOS', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '59-50', '59-50', '59-50', '59-50', '59-50', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (613, 'ZAGJ800429', 'SUPERVISAR LAS ACCIONES QUE SE REALICEN DENTRO DEL ÁREA NATURAL PROTEGIDA SE AJUSTEN A LOS PROPÓSITOS DE LOS ORDENAMIENTOS LEGALES APLICABLES EN MATERIA DE PROTECCIÓN, MANEJO Y RESTAURACIÓN PARA LA CONSERVACIÓN DE LOS ECOSISTEMAS Y SU BIODIVERSIDAD.', '10', '25', '100-75', '74-50', '24-0', NULL, 'PROMOVER EL DESARROLLO COMUNITARIO PARTICIPATIVO EN EL ÁREA EN LO RELATIVO A LOS PROGRAMAS DE SUBSIDIOS Y PROYECTOS DE CONSERVACIÓN PARA EL DESARROLLO, Y DE MANEJO PARA EL USO Y APROVECHAMIENTO DE LOS ECOSISTEMAS Y SU BIODIVERSIDAD. RECIBIR LAS SOLICITUDES E INTEGRAR LOS EXPEDIENTES PARA EL OTORGAMIENTO DE LICENCIAS, PERMISOS, AUTORIZACIONES Y CONCESIONES', '10', '25', '100-75', '74-50', '24-0', NULL, 'INTERVENIR EN LA FORMULACIÓN Y EJECUCIÓN DE LOS PROGRAMAS DE ORDENAMIENTO ECOLÓGICO QUE INCIDAN EN EL ÁREA NATURAL PROTEGIDA Y SUS ZONAS DE INFLUENCIA, CONFORMAR EL SISTEMA DE INFORMACIÓN CON LOS DATOS BIOLÓGICOS, SOCIALES, ECONÓMICOS Y CARTOGRÁFICOS DEL ÁREA NATURAL PROTEGIDA CORRESPONDIENTE	', '10', '25', '100-75', '74-50', '24-0', NULL, ' PARTICIPAR EN LOS PROGRAMAS, PROYECTOS Y ACCIONES DE ESPECIES Y POBLACIONES CONSIDERADAS COMO PRIORITARIAS PARA LA CONSERVACIÓN, EN LAS ÁREAS NATURALES PROTEGIDAS DE SU COMPETENCIA.  DIRIGIR Y EJECUTAR LOS PROGRAMAS PARA LA ATENCIÓN DE CONTINGENCIAS AMBIENTALES', '10', '25', '100-75', '74-50', '24-0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '49-25', '49-25', '49-25', '49-25', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (614, 'NAAG920813', 'PARTICIPAR EN LA ATENCIÓN, CONTROL Y SEGUIMIENTO DEL 100% DE LOS PROCEDIMIENTOS JUDICIALES Y CONTENCIOSOS ADMINISTRATIVOS EN LOS QUE LA DIRECCIÓN REGIONAL NOROESTE Y ALTO GOLFO DE CALIFORNIA, Y/O LAS ÁREAS NATURALES PROTEGIDAS ADSCRITAS. ', '10', '25', '100-75', '74-50', '24-0', NULL, 'PARTICIPAR EN LA ATENCIÓN Y SEGUIMIENTO DE LOS DISTINTOS PROCEDIMIENTOS ADMINISTRADOS QUE SE DERIVEN DE LA OPERACIÓN DE LOS MÚLTIPLES PROGRAMAS PARA EL OTORGAMIENTO DE SUBSIDIOS, OPERADOS POR LA COMISIÓN A TRAVÉS DE LAS ÁREAS NATURALES PROTEGIDAS ADSCRITAS A LA DIRECCIÓN REGIONAL NOROESTE Y ALTO GOLFO DE CALIFORNIA.', '10', '25', '100-75', '74-50', '24-0', NULL, 'CONTRIBUIR EN LA ATENCIÓN A LAS SOLICITUDES DE ASESORÍA JURÍDICA QUE PRESENTE LA DIRECCIÓN REGIONAL NOROESTE Y ALTO GOLFO DE CALIFORNIA, Y/O LAS ÁREAS NATURALES PROTEGIDAS ADSCRITAS. ', '10', '25', '100-75', '74-50', '24-0', NULL, '\r\nINTERVENIR EN EL ANÁLISIS EN CUANTO A LA PROCEDENCIA DE LAS SOLICITUDES DE PERMISOS Y AUTORIZACIONES PARA REALIZAR ACTIVIDADES COMERCIALES, DE EXPLORACIÓN Y EXPLOTACIÓN DE RECURSOS MINEROS, PRESTACIÓN DE SERVICIOS TURÍSTICOS Y FILMACIONES COMERCIALES DENTRO DE LAS ÁREAS NATURALES PROTEGIDAS ADSCRITAS A LA DIRECCIÓN REGIONAL NOROESTE Y ALTO GOLFO DE CALIFORNIA.\r\n', '10', '25', '100-75', '74-50', '24-0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '49-25', '49-25', '49-25', '49-25', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (615, 'COML850817', 'Promover y operar proyectos de conservación y uso sustentable de los Recursos Naturales a través de Programas de Subsidios (PROCODES y PROREST).', '10', '25', 'Se llevó a cabo del 100 al 90% la promoción y operación de proyectos de conservación y uso sustentable de los Recursos Naturales a través de programas de subsidios (PROCODES y PROREST).', 'Se llevó a cabo del 89 al 70% la promoción y operación de proyectos de conservación y uso sustentable de los Recursos Naturales a través de programas de subsidios (PROCODES y PROREST).', 'Se llevó a cabo del 49 al 0% la promoción y operación de proyectos de conservación y uso sustentable de los Recursos Naturales a través de programas de subsidios (PROCODES y PROREST).', NULL, 'Promover el desarrollo comunitario y la realización de prácticas de manejo sustentable en el área natural protegida y su zona de influencia.', '10', '25', 'Se aplicaron del 100 al 90% prácticas de manejo sustentable en el área natural protegida y su zona de influencia.', 'Se aplicaron del 89 al 70% prácticas de manejo sustentable en el área natural protegida y su zona de influencia.', 'Se aplicaron del 49 al 0% prácticas de manejo sustentable en el área natural protegida y su zona de influencia.', NULL, 'Apoyar en la difusión sobre la importancia del ANP y la conservación del ecosistema insular y su biodiversidad entre los usuarios y la población de la zona de influencia mediante la generación y distribución de materiales de difusión.', '10', '25', 'Se distribuyó del 100 al 90% del material de difusión programado.', 'Se distribuyó del 89 al 70% del material de difusión programado.', 'Se distribuyó del 49 al 0% del material de difusión programado.', NULL, 'Participar en los programas, proyectos y acciones para la conservación de especies en poblaciones consideradas como prioritarias en el Área Natural Protegida.', '10', '25', 'Se realizaron del 100 al 90% de las acciones encomendadas.', 'Se realizaron del 89 al 70% de las acciones encomendadas.', 'Se realizaron del 49 al 0% de las acciones encomendadas.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Se llevó a cabo del 69 al 50% la promoción y operación de proyectos de conservación y uso sustentable de los Recursos Naturales a través de programas de subsidios (PROCODES y PROREST).', 'Se aplicaron del 69 al 50% prácticas de manejo sustentable en el área natural protegida y su zona de influencia.', 'Se distribuyó del 69 al 50% del material de difusión programado.', 'Se realizaron del 69 al 50% de las acciones encomendadas.', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (616, 'EIFH831201', 'Realizar recorridos de Supervisión y elaborar denuncias de los ilícitos detectados en el Área Natural Protegida, así como cuando se requiera, participar en operativos con otras autoridades (PROFEPA, SEMAR, PGR, etc.) para garantizar la protección y conservación del patrimonio natural del área protegida y sus procesos ecológicos ', '10', '30', 'Se elaboraron las denuncias del 100% de los ilícitos detectados en el Área Natural Protegida', 'Se elaboraron las denuncias del 99 al 80% de los ilícitos detectados en el Área Natural Protegida', 'Se elaboraron denuncias del 49 al 0% de los ilícitos detectados en el Área Natural Protegida', NULL, 'Mantener actualizada la base de datos de denuncias y dar seguimiento a las mismas.\r\n', '10', '10', 'Actualizar la base de datos  y dar seguimiento al 100% de las denuncias realizadas por el Área Natural Protegida', 'Actualizar y dar seguimiento del 99 - 80% de las denuncias realizadas por el Área Natural Protegida', 'Actualizar y dar seguimiento del 49 al 0% de las denuncias realizadas por el Área Natural Protegida', NULL, 'Llevar a cabo las acciones asignadas para la conservación y recuperación de especies prioritarias en el área protegida.\r\n', '10', '30', 'Se llevó a cabo del 100-90% de las acciones asignadas establecidas en los protocolos de monitoreo para la conservación de especies prioritarias en el área natural protegida', 'Se llevó a cabo del 89- 70% de las acciones asignadas establecidas en los protocolos de monitoreo para la conservación de especies prioritarias en el área protegida.', 'Se llevó a cabo del 49 al 0% de las acciones asignadas establecidas en los protocolos de monitoreos para la conservación de especies prioritarias en el área natural protegida', NULL, 'Fomentar en los usuarios y habitantes de las comunidades que inciden en el ANP, la conservación de sus recursos naturales a través de la integración de Comités de Vigilancia Comunitaria.\r\n', '1', '30', '4 comunidades involucradas en la formación de Comités de Vigilancia Comunitaria', '3 comunidades involucradas en la formación de Comités de Vigilancia Comunitaria', '1-0  comunidades involucradas en la formación de Comités de Vigilancia Comunitaria', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Se elaboraron las denuncias del 79 al 50% de los ilícitos detectados en el Área Natural Protegida', 'Actualizar y dar seguimiento del 79 - 50 % de las denuncias realizadas por el Área Natural Protegida', 'Se llevó a cabo del 69- 50% de las acciones asignadas establecidas en los protocolos de monitoreo para la conservación de especies prioritarias en el área protegida.', '2 comunidad involucrada en la formación de Comités de Vigilancia Comunitaria', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (617, 'SACK890728', 'Recopilación de variables climáticas en campo de las 2 estaciones meteorológicas pertenecientes a La Reserva de La Biosfera El Pinacate y Gran Desierto de Altar, para su posterior procesamiento de información y actualización de bases de datos correspondientes. ', '1', '20', 'Recopilación de variables climáticas y 2 bases de datos actualizadas', 'Recopilación de variables climáticas y 1 base de datos actualizada', 'Sin recopilación de variables y sin bases de datos actualizadas', NULL, 'Realizar pláticas, presentaciones y/o ponencias, ya sea en línea o de manera presencial, a grupos escolares y diferente público; con temas relativos a La Reserva de la Biosfera El Pinacate y Gran Desierto de Altar, ya sea dentro o fuera del ANP.', '1', '20', '16 pláticas impartidas durante el año', '10 pláticas impartidas durante el año', '0 pláticas impartidas durante el año', NULL, 'Realizar el registro y seguimiento de atención de las solicitudes del Instituto Nacional de Transparencia y Acceso a la Información Pública (INAI)  dirigidas a la dirección de La Reserva de La Biosfera El Pinacate y Gran Desierto de Altar, así como de los volantes de gestión que se deriven a esta ANP.\r\n', '10', '20', 'ATENCIÓN Y SEGUIMIENTO DE UN 100% DE SOLICITUDES', 'ATENCIÓN Y SEGUIMIENTO DE UN 80% DE SOLICITUDES', 'ATENCIÓN Y SEGUIMIENTO DE UN 30% DE SOLICITUDES', NULL, 'Promover y ejecutar acciones en sinergia con diferentes instituciones de las comunidades de los municipios de Puerto Peñasco, Plutarco Elías Calles y San Luis Rio Colorado, en materia de educación ambiental; resaltando las fechas ambientales del año.', '1', '20', '5 acciones realizadas', '2 acciones realizadas', '0 acciones realizadas', NULL, 'Mantener actualizados los insumos del programa de educación ambiental; cronograma de actividades, fechas Ambientales, presentaciones, directorio de escuelas e instituciones.\r\n', '10', '20', 'Insumos actualizados en un 100%', 'Insumos actualizados 50 %', 'Sin actualización', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Recopilación de variables climáticas y 0 bases actualizadas', '5 pláticas impartidas durante el año', 'ATENCIÓN Y SEGUIMIENTO DE UN 50% DE SOLICITUDES', '1 acción realizada', 'Insumos actualizados en un 30%', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (618, 'VIRM710221', 'Elaborar, registrar y mantener actualizada en una base de datos, los movimientos presupuestales, bancarios y del ejercicio de cada programa que se administra.', '8', '30', '100-85% ', '84-70% ', '39-0%', NULL, 'Tramitar sólo Solicitudes de Pago que cuenten con suficiencia presupuestal y cumplan con la normatividad aplicable, haciendo una correcta aplicación en SICOP, para los Gastos de Operación de cada programa, dando seguimiento a la recuperación de deudores diversos, generados durante el ejercicio.', '8', '20', '100-85% ', '84-70% ', '39-0%', NULL, 'Realizar el cálculo de Impuesto sobre Nómina para Sonora y Sinaloa, dando además seguimiento a los requerimientos de información relacionados', '8', '10', '100-85% ', '84-70% ', '39-0%', NULL, 'Reportar mensualmente a cada Región Prioritaria, la situación presupuestal y de su ejercicio, para cada programa.', '8', '20', '100-85% ', '84-70% ', '39-0%', NULL, 'Elaborar Reportes Anuales por programa, conciliados con Banco, SICOP y con cifras presentadas por la Unidad Técnica Regional, para obtener los Anexos de Devoluciones y realizar los reintegros que correspondan.', '8', '20', '100-85% ', '84-70% ', '39-0%', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '69-40% ', '69-40% ', '69-40% ', '69-40% ', '69-40% ', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
