INSERT INTO `sed_individuales` VALUES (619, 'DUPS790706', 'PROMOVER EL DESARROLLO COMUNITARIO PARTICIPATIVO EN EL ÁREA EN LO RELATIVO A LOS PROGRAMAS DE SUBSIDIOS Y PROYECTOS DE CONSERVACIÓN PARA EL DESARROLLO Y DE MANEJO PARA EL USO Y APROVECHAMIENTO DE LOS ECOSISTEMAS', '2', '20', '100% - 75%', '75% - 50%', '9% - 0%', NULL, 'ORGANIZAR, OPERAR, ADMINISTRAR, ASESORAR Y CULMINAR EN TIEMPO Y FORMA LOS PROYECTOS PROCODES QUE SE AUTORICEN EN EL ANP CONFORME A LAS REGLAS DE OPERACIÓN DEL PROCODES 2025', '1', '40', '100% - 75%', '74% - 50%', '9% - 0%', NULL, 'ORGANIZAR, OPERAR Y COORDINAR LA GESTIÓN DE GASTOS PARA OPERATIVOS EN CAMPO EN EL SISTEMA DE CONTABILIDAD Y PRESUPUESTO (SICOP) PARA QUE LAS ACTIVIDADES PROGRAMADAS POR LOS OPERADORES SE REALICEN EN TIEMPO Y FORMA. ', '2', '15', '100% - 75%', '74% - 50%', '9% - 0%', NULL, 'COADYUVAR, OPERAR Y ADMINISTRAR LAS ACCIONES CORRESPONDIENTES AL SISTEMA DE PORTALES DE OBLIGACIONES DE TRANSPARENCIA CORRESPONDIENTE A SUBSIDIOS Y  DE GASTOS PARA OPERATIVOS EN CAMPO Y DE  APOYO EN OTRA ÁREAS DENTRO DEL ANP', '2', '15', '100% - 75%', '74% - 50%', '9% - 0%', NULL, 'COADYUVAR EN LAS ACCIONES Y REALIZACIÓN DE LAS REUNIONES DE CONSEJO ASESOR DURANTE LOS TIEMPOS REQUERIDOS EN EL ANP ASÍ CÓMO LA PARTICIACIÓN DE LAS ACCIONES DE CONOCIMIENTO QUE SE SOLICITE DENTRO DEL ANP.', '2', '10', '100% - 75%', '74% - 50%', '9% - 0%', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '49% - 10%', '40% - 10%', '49% - 10%', '49% - 10%', ' 49% - 10', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (622, 'DOML790315', 'Generar y distribuir diversos materiales de difusión (señalizaciones, video cápsulas, souvenirs, entre otros) para mantener informados a los usuarios de la Reserva, sobre los valores de conservación del ANP ', '1', '20', '4 a 6 materiales de difusión', '2 a 3 materiales de difusión', '1 a 2 materiales de difusión', NULL, 'Exponer o difundir información relevante en eventos ambientales como foros, congresos, festivales, seminarios, simposios, ferias, entre otros.', '1', '15', '5 a 6 eventos', '3 a 4 eventos', '1 a 2 eventos', NULL, 'Realizar eventos, cursos de capacitación, talleres lúdicos multitemático ambiental, dirigido a un público diverso (infancia, juventudes, adultos, personas productoras, comunidades indígenas y mestizas, personal técnico, instituciones y organizaciones de la sociedad), en favor de la conservación y desarrollo sustentable de la Reserva.', '1', '30', '5 a 6 eventos', '3 a 4 eventos', '1 a 2 eventos', NULL, 'Diseñar y elaborar materiales impresos, artesanales o digitales para desarrollo de actividades de cultura ambiental.', '1', '15', '5 a 6 materiales', '3 a 4 materiales', '1 a 2 materiales', NULL, 'Capacitar a la población en diversos temas que fortalezcan las acciones de monitoreo ambiental, biológico y desarrollo sustentable.', '1', '20', '4 a 5 capacitaciones', '2 a 3 capacitaciones', '1 a 2 capacitaciones', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '0 a 1 materiales de difusión', '0 a 1 eventos', '0 a 1 eventos', '0 a 1 materiales', '0 a 1 capacitaciones', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
