INSERT INTO `sed_individuales` VALUES (684, 'BARM740227', 'Supervisar y apoyar la coordinación de las acciones para la formulación del programa de manejo en 3 áreas naturales protegidas adscritas a esta Regional Noreste y Sierra Madre Oriental.', '1', '25', '3', '2', '0', NULL, 'Supervisar y apoyar en la coordinación de las acciones para la formulación del proyecto de modificación del programa de manejo en 4 áreas naturales protegidas adscritas a esta Regional Noreste y Sierra Madre Oriental.', '1', '25', '4', '2', '0', NULL, 'Supervisar y apoyar en la coordinación de las acciones para el proceso de Revisión del programa de manejo en 6 áreas naturales protegidas adscritas a esta Regional Noreste y Sierra Madre Oriental conforme a lo dispuesto en el Artículo 77 del RLGEEPA en materia de ANP.', '1', '20', '6', '3', '1', NULL, 'Atender y dar seguimiento a el total de las solicitudes de información que se realicen a través del Portal Nacional de Transparencia turnadas a la regional Noreste y Sierra Madre Oriental.', '10', '15', '76 - 100', '51 - 75', '0 - 30', NULL, 'Atender y dar seguimiento a el total de las solicitudes para la certificación como Áreas Destinadas Voluntariamente a la Conservación (ADVC) que se pretenden establecer en la circunscripción territorial de la regional Noreste y Sierra Madre Oriental.', '10', '15', '76 - 100', '51 -75', '0 - 30', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '1', '1', '2', '31 - 50', '31 - 50', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (685, 'LOLI880428', 'DISEÑO, ELABORACIÓN Y DIFUSIÓN DE MATERIALES GRAFICOS ALUSIVOS A LA IMPORTANCIA DE LA CONSERVACIÓN DE LAS ÁREAS NATURALES PROTEGIDAS (FOLLETOS, POSTERS, FLYERS, LONAS, VIDEOS, FOTOGRAFÍAS) DE ACUERDO A LAS NECESIDADES DEL ANP', '10', '20', 'El 90 al 100% se mantiene la elaboración y difusión de materiales programados en el POA', 'El 80 al 89% se mantiene la elaboración y difusión de materiales programados en el POA', ' menos del 79% se mantiene la elaboración y difusión de materiales programados en el POA', NULL, 'PROGRAMACIÓN Y EJECUCIÓN DE ACTIVIDADES ENTORNO A EFEMÉRIDES AMBIENTALES, PARA PROMOVER LA CONSERVACIÓN DE LAS ESPECIES Y ECOSISTEMAS DEL ANP A LOS DIFERENTES SECTORES ENTORNO AL ANP ACORDE A LOS PROGRAMAS DE MANEJO, GENERAR LA INFORMACIÓN E INFORMES', '10', '20', 'El 90 al 100% se llevan acabo las actividades programadas en el POA', 'El 80 al 89% se llevan acabo las actividades programadas en el POA ', 'menos del 79% se llevan acabo las actividades programadas en el POA', NULL, 'PROGRAMAR Y ORGANIZAR CAMPAÑAS DE LIMPIEZA EN PLAYAS, SITIOS RAMSAR Y/O PRIORITARIOS PARA EL ANP, ASÍ COMO GENERAR UNA BASE DE DATOS CON LA INFORMACIÓN DE LOS RESIDUOS COLECTADOS Y SU RESPECTIVO INFORME.', '10', '20', 'PROYECTOS OPERADOS Y SUPERVISADOS  DEL 100 AL 90%', 'PROYECTOS OPERADOS Y SUPERVISADOS DEL 80 AL 89%', 'Menos del 79% se llevan a cabo se llevan las campañas de limpieza y su reporte anual', NULL, 'APOYO EN LA ELABORACIÓN DE INSUMOS DE DIFUSIÓN E IMPLEMENTACIÓN DE ACCIONES EDUCATIVAS Y DE SENSIBILIZACIÓN CON LOS GRUPOS COMUNITARIOS', '10', '20', 'Se apoya en las reuniones y se da seguimiento del 90 al 100%', 'Se apoya en las reuniones y se da seguimiento 75 al 89 %', 'Se apoya en las reuniones y se da seguimiento menos del 60 al 74', NULL, 'REALIZAR DIFUSIÓN DE LAS ACCIONES QUE SE REALIZAN EN LAS ANP EN MEDIOS IMPRESOS, DIGITALES Y REDES SOCIALES', '10', '20', 'Del 90 al 100% se difunden las acciones del ANP', 'Del 75 al 89 % se difunden las acciones del ANP', ' Menos del 60 al 74 se difunden las acciones del ANP', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Menos del 50% se mantiene la elaboración y difusión de materiales programados en el POA', 'Menos del 50% se llevan a cabo las actividades programadas en el POA y el informe anual', 'Menos del 50% se llevan a cabo las campañas de limpieza y su reporte anual', 'Se apoya en las reuniones y se da seguimiento menos del 50%', 'Menos del 50% se difunden las acciones del ANP', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (687, 'EIVV820208', 'Representar al director del ANP en reuniones o eventos en los municipios de Colima, Villa de Álvarez, Minatitlán y Comala en el Estado de Colima', '10', '20', 'Participar o representar a la Dirección del ANP del 90% al 100% de las veces que se me solicite.', 'Participar o representar a la Dirección del ANP del 89.9% al 75% de las veces que se me solicite.', 'Participar o representar a la Dirección del ANP en al menos el 59.9% de las veces que se me solicite.', NULL, 'Implementar el Programa anual de Educación Ambiental y Cultura para la Conservación de la Reserva de la Biósfera Sierra de Manantlán.', '10', '20', 'Cumplimiento del 95% al 100% de las actividades anuales programadas.', 'Cumplimiento del 89.9% al 75% de las actividades anuales programadas.', 'Cumplimiento de al menos el 59.9%de las actividades anuales programadas.', NULL, 'Implementar proyectos de programas de subsidios que fortalezcan las economías sociales y promuevan acciones de conservación de flora y fauna.', '1', '20', 'Ejecutar al menos tres proyectos dentro de los programas de apoyo social de la CONANP', 'Ejecutar al menos dos proyectos dentro de los programas de apoyo social de la CONANP', 'Ejecutar al menos un proyecto dentro de los programas de apoyo social de la CONANP', NULL, 'Implementar una estrategia para promover la regulación del turismo de naturaleza en el ANP. ', '10', '20', 'Cumplimiento del 95% al 100% de las actividades anuales programadas.', 'Cumplimiento del 89.9% al 75% de las actividades anuales programadas.', 'Cumplimiento de al menos el 59.9% de las actividades anuales programadas.', NULL, 'Implementar el programa de señalética en el ANP y su zona de influencia.', '10', '20', 'Cumplimiento del 95% al 100% de las actividades anuales programadas.', 'Cumplimiento del 89.9% al 75% de las actividades anuales programadas.', 'Cumplimiento de al menos el 59.9% de las actividades anuales programadas.', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Participar o representar a la Dirección del ANP del 74.9% al 60% de las veces que se me solicite.', 'Cumplimiento del 74.9% al 60% de las actividades anuales programadas.', 'No ejecutar ningún proyecto dentro de los programas de apoyo social de la CONANP', 'Cumplimiento del 74.9% al 60% de las actividades anuales programadas.', 'Cumplimiento del 74.9% al 60% de las actividades anuales programadas.', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (688, 'EOAA690902', 'PARTICIPAR EN LAS ACCIONES PARA PREVENIR, CONTROLAR Y COMBATIR LOS INCENDIOS FORESTALES QUE AFECTAN LOS ECOSISTEMAS EN EL ÁREA NATURAL PROTEGIDA.', '10', '40', 'SE ATIENDE AL 100% DE LOS INCENDIOS FORESTALES PRESENTADOS EN LAS REGIONES CENTRO Y COSTA DE LA RESERVA DE LA BIOSFERA LA SEPULTURA', 'SE ATIENDE AL 80% DE LOS INCENDIOS FORESTALES PRESENTADOS EN LAS REGIONES CENTRO Y COSTA DE LA RESERVA DE LA BIOSFERA LA SEPULTURA', 'SE ATIENDE AL 50% DE LOS INCENDIOS FORESTALES PRESENTADOS EN LAS REGIONES CENTRO Y COSTA DE LA RESERVA DE LA BIOSFERA LA SEPULTURA', NULL, 'SE REALIZAN ACCIONES DE PROTECCIÓN DE LOS RECURSOS NATURALES EN COORDINACIÓN CON LAS BRIGADAS DE PROCODES CONTINGENCIA AMBIENTAL DEL ANP.', '10', '30', 'SE COORDINA LAS ACCIONES DE PROTECCIÓN DE RECURSOS NATURALES DE 2 BRIGADAS DE CONTINGENCIA AMBIENTAL EN LAS REGIONES COSTA Y CENTRO DE LA RESERVA DE LA BIOSFERA LA SEPULTURA', 'SE COORDINA LAS ACCIONES DE PROTECCIÓN DE RECURSOS NATURALES DE UNA BRIGADA DE CONTINGENCIA AMBIENTAL EN LAS REGIONES COSTA Y CENTRO DE LA RESERVA DE LA BIOSFERA LA SEPULTURA.', 'SE COORDINA LAS ACCIONES DE PROTECCIÓN DE RECURSOS NATURALES DE NINGUNA BRIGADAS DE CONTINGENCIA AMBIENTAL EN LAS REGIONES COSTA Y CENTRO DE LA RESERVA DE LA BIOSFERA LA SEPULTURA.', NULL, 'REALIZAR RECORRIDOS DE INSPECCIÓN Y VIGILANCIA CON LA FINALIDAD DE DETECTAR ILÍCITOS AMBIENTALES EN EL ANP', '10', '10', 'SUPERVISAR 10,000 HECTÁREAS EN ÁREAS PRIORITARIAS DE LAS REGIONES COSTA Y CENTRO DE LA RESERVA DE LA BIOSFERA LA SEPULTURA, EN COORDINACIÓN CON LAS BRIGADAS DE LOS PROGRAMAS DE SUBSIDIOS DEL ANP.', 'SUPERVISAR 5,000 HECTÁREAS EN ÁREAS PRIORITARIAS DE LAS REGIONES COSTA Y CENTRO DE LA RESERVA DE LA BIOSFERA LA SEPULTURA, EN COORDINACIÓN CON LAS BRIGADAS DE LOS PROGRAMAS DE SUBSIDIOS DEL ANP.', 'SUPERVISAR 3,000 HECTÁREAS EN ÁREAS PRIORITARIAS DE LAS REGIONES COSTA Y CENTRO DE LA RESERVA DE LA BIOSFERA LA SEPULTURA, EN COORDINACIÓN CON LAS BRIGAD