INSERT INTO `sed_individuales` VALUES (692, 'MOLR821012', 'REALIZAR LOS PROCEDIMIENTOS PARA LA ADQUISICIÓN DE BIENES Y SERVICIOS, DE ACUERDO CON EL PRESUPUESTO ASIGNADO Y REQUERIMIENTOS POR PARTE DE LA ÁREAS NATURALES PROTEGIDAS A TRAVÉS DE LICITACIONES PÚBLICAS, INVITACIÓN A CUANDO MENOS TRES PERSONAS Y/O ADJUDICACIONES DIRECTAS, CUMPLIENDO NORMATIVAMENTE Y EN COORDINACIÓN CON EL JEFE DE DEPARTAMENTO DE ADQUISICIONES DE LA DIRECCIÓN REGIONAL PLANICIE COSTERA Y GOLFO DE MÉXICO', '8', '20', 'REALIZAR EL 100% DE LOS PROCEDIMIENTOS', 'REALIZAR EL 50% DE LOS PROCEDIMIENTOS', 'REALIZAR EL 20% DE LOS PROCEDIMIENTOS', NULL, 'COMO ADMINISTRADORA DE LOS CONTRATOS CELEBRADOS DURANTE EL EJERCICIO FISCAL 2025, SUPERVISAR, VERIFICAR Y COMPROBAR EL CUMPLIMIENTO DE ESTOS POR PARTE DE LOS PROVEEDORES, ACORDE A LOS TERMINOS DE REFERENCIA ESTABLECIDOS Y NORMATIVIDAD APLICABLE.', '8', '20', 'SUPERVISAR, VERIFICAR Y COMPROBAR EN UN 95% EL CUMPLIMIENTO DE LOS CONTRATOS CELEBRADOS', 'SUPERVISAR, VERIFICAR Y COMPROBAR EN UN 50% EL CUMPLIMIENTO DE LOS CONTRATOS CELEBRADOS', 'SUPERVISAR, VERIFICAR Y COMPROBAR EN UN 20% EL CUMPLIMIENTO DE LOS CONTRATOS CELEBRADOS', NULL, 'REVISAR LOS PAGOS DE ADQUISICIONES Y SERVICIOS CONTRATADOS, EL TRAMITE DE VIATICOS DEVENGADOS Y/O ANTICIPADOS, PAGO DE IMPUESTOS, EN LOS SISTEMAS SICOP Y SIAFF, ASSI MISMO REVISAR EN LA BANCA ELECTRONICA EL PAGO DE PROYECTOS DE LOS PROGRAMAS DE SUBSIDIOS.', '4', '20', 'REVISAR EL 100% DE LOS PAGOS EN LOS SISTEMAS SICOP, SIAFF Y BANCA ELECTRONICA', 'REVISAR EL 80% DE LOS PAGOS EN LOS SISTEMAS SICOP, SIAFF Y BANCA ELECTRONICA', 'REVISAR EL 30% DE LOS PAGOS EN LOS SISTEMAS SICOP, SIAFF Y BANCA ELECTRONICA', NULL, 'ACTUALIZAR EN COORDINACIÓN CON EL ÁREA CORRESPONDIENTE EL INVENTARIO GLOBAL, ASÍ COMO LLEVAR A CABO LOS INVENTARIOS ALEATORIOS Y GLOBAL DE LAS ÁREAS NATURALES PROTEGIDAS Y OFICINA DE LA DIRECCIÓN REGIONAL PLANICIE COSTERA Y GOLFO DE MÉXICO, CUMPLIENDO CON LOS PROCEDIMIENTOS Y NORMATIVIDAD ', NULL, '20', 'LLEVAR A CAB