INSERT INTO `sed_individuales` VALUES (693, 'HELB750330', 'APOYAR EN EL PROCESO DE DIFUSIÓN, RECEPCIÓN DE SOLICITUDES Y EJECUCIÓN DE PROYECTOS RELACIONADOS CON LOS PROGRAMAS DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE (PROCODES) Y PROGRAMA PARA LA PROTECCIÓN Y RESTAURACIÓN DE ECOSISTEMAS Y ESPECIES PRIORITARIAS (PROREST). ', '10', '30', '90 - 100', '70 - 89', 'menos de 50', NULL, 'SEGUIMIENTO Y ATENCIÓN DE REUNIONES DE TRABAJO Y RECORRIDOS DE CAMPO, PARA LA IDENTIFICACIÓN Y ATENCIÓN DE BROTES DE PLAGAS Y ENFERMEDADES FORESTALES EN COORDINACIÓN CON DUEÑOS y POSEEDORES DEL TERRITORIO, INSTANCIAS DE LOS TRES NIVELES DE GOBIERNO Y PRESTADORES DE SERVICIOS FORESTALES, DENTRO DEL APFF COBIO CHICHINAUTZIN Y SU ZONA DE INFLUENCIA.', '10', '20', '90 - 100', '70 - 89', 'menos de 50', NULL, 'PARTICIPAR EN ACTIVIDADES Y PROCESOS DE CAPACITACIÓN Y REGULACIÓN TURISTICA EN COORDINACIÓN CON PRESTADORES DE SERVICIOS TURISTICOS, AUTORIDADES COMUNALES E INSTANCIAS GUBERNAMENTALES.  ', '10', '10', '90 -100', '70 - 89', 'menos de 50', NULL, 'PREPARAR DOCUMENTACIÓN DE SOPORTE PARA LA EMISIÓN DE OPINIONES TÉCNICAS RESPECTO A APROVECHAMIENTOS, SERVICIOS, OBRAS, Y ACTIVIDADES QUE SE PRETENDAN EJECUTAR, DENTRO DE LA POLIGONAL DEL ANP APFF COBIO CHICHINAUTZIN.', '10', '30', '90 -100', '70 - 89', 'menos de 50', NULL, 'FOMENTAR LA PARTICIPACIÓN DE LA POBLACIÓN Y USUARIOS DEL ÁREA, EN ACTIVIDADES DE EDUCACIÓN AMBIENTAL QUE PROMUEVAN ACCIONES PARA EL DESARROLLO SUSTENTABLE Y LA CONSERVACIÓN DE LOS SERVICIOS ECOSISTÉMICOS.', '10', '10', '90 -100', '70 - 89', ' memos de 50', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '50 - 69', '50 - 69 ', '50 - 69', '50 - 69', '50 -69', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (694, 'GOPJ910301', 'OPERAR PROYECTOS CON LAS COMUNIDADES QUE ABONEN A LA CONSERVACIÓN DE LAS ESPECIES CONSIDERADAS COMO PRIORITARIAS PARA LA DRBSM Y SE ENCUENTREN EN ALGÚN ESTATUS DE RIESGO DE LA NOM-059-SEMARNAT-2010, ADEMÁS DE SUPERVISAR LAS ACCIONES DE VIGILANCIA Y MONITOREO.', '1', '40', '5- 4 PROYECTOS', '4 -3 PROYECTOS', '0 PROYECTOS', NULL, 'REALIZAR EL MONITOREO DE ESPECIES PRIORITARIAS PARA GENERAR INFORMACIÓN DE SU ESTADO POBLACIONAL Y QUE APOYEN EN LA TOMA DE DECISIONES EN ACCIONES DE PROTECCIÓN, CONSERVACIÓN Y MANEJO.', '1', '20', '10-8 ESPECIES', '7 - 5 ESPECIES', '1 - 0 ESPECIES', NULL, 'ELABORAR PROTOCOLOS DE MONITOREO DE ESPECIES Y MATERIAL DE DIFUSIÓN DE ESPECIES CLAVE', '1', '10', '2 PROTOCOLOS', '1 PROTOCOLOS', '0 PROTOCOLOS', NULL, 'REALIZAR PLATICAS Y TALLERES DE EDUCACIÓN AMBIENTALCON ACTORES CLAVES DEL ANP, CON EL FIN DE PROMOVER CONCIENCIACIÓN EN LA PROTECCIÓN DE LA FAUNA SILVESTRE ', '1', '15', '10 - 8 TALLERES', '7- 5 TALLERES', '1 -0 TALLERES', NULL, 'IMPLEMENTAR LA ESTRATEGIA DE CONSERVACIÓN DEL JAGUAR EN EL ANP Y SU ZONA DE INFLUENCIA', '1', '15', '3 PROYECTOS', '2 PROYECTOS', '0 PROYECTOS', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '2 -1 PROYECTOS', '4- 2 ESPECIES', '0 PROTOCOLOS', '4 - 2 TALLERES', '1 PROYECTOS', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (695, 'RICA971231', 'Diseñar y operar talleres de difusión y educación para la conservación, sobre  la importancia ecológica del ANP con énfasis en las islas localizadas en la zona sur de Sinaloa, frente a la bahía de Mazatlán , así  como temas medioambientales para que contribuyan a la conservación de ANP y sus zonas de influencia. ', '10', '40', 'Se diseñaron  y operaron de 12 a 10 talleres de difusión y educación para la conservación, sobre  la importancia ecológica del ANP con énfasis en las islas localizadas en la zona sur de Sinaloa, frente a la bahía de Mazatlán , así  como temas medioambientales que contribuyan a la conservación de ANP y sus zonas de influencia.', 'Se diseñaron  y operaron de 9 a 7 talleres de difusión y educación para la conservación, sobre  la importancia ecológica del ANP con énfasis en las islas localizadas en la zona sur de Sinaloa, frente a la bahía de Mazatlán , así  como temas medioambientales que contribuyan a la conservación de ANP y sus zonas de influencia.', 'Se diseñaron  y operaron de 4 a 0 talleres de difusión y educación para la conservación, sobre  la importancia ecológica del ANP con énfasis en las islas localizadas en la zona sur de Sinaloa, frente a la bahía de Mazatlán , así  como temas medioambientales que contribuyan a la conservación de ANP y sus zonas de influencia.', NULL, 'Proporcionar información a los diversos usuarios (visitantes, prestadores de servicios turísticos, investigadores, autoridades, sociedad en general) en las islas localizadas en la zona sur de Sinaloa, frente a la Bahía de Mazatlán, para que conozcan sobre el decreto, el programa de manejo del área natural protegida  y los ordenamientos legales aplicables en materia de protección, manejo y restauración para la conservación de los ecosistemas y su biodiversidad en el área natural protegida.', '10', '35', 'Se atendió del 100 % al 90% de los usuarios en las islas del área natural protegida localizadas en la zona sur de Sinaloa, proporcionando información sobre la normatividad y ordenamientos legales aplicables en materia de protección, manejo y restauración para la conservación de los ecosistemas y su biodiversidad en el área natural protegida.', 'Se atendió del 89 % al 70% de los usuarios en las islas del área natural protegida localizadas en la zona sur de Sinaloa, proporcionando infromación sobre la normatividad y ordenamientos legales aplicables en materia de protección, manejo y restauración para la conservación de los ecosistemas y su biodiversidad en el área natural protegida.', 'Se atendió del 49% al 0% de los usuarios en las islas del área natural protegida localizadas en la zona sur de Sinaloa, proporcionando infromación sobre la normatividad y ordenamientos legales aplicables en materia de protección, manejo y restauración para la conservación de los ecosistemas y su biodiversidad en el área natural protegida.	', NULL, 'Apoyar  en la recepción de solicitudes e integración de los expedientes para el otorgamiento de licencias, permisos y autorizaciones en las islas localizadas en la zona sur de Sinaloa, frente a la Bahía de Mazatlán, así como para notificar a los interesados las resoluciones emanadas de las unidades administrativas competentes de la Comisión. \r\n', '10', '25', 'Se atendió el 100 % de las solicitudes e integración de expedientes para licencias, permisos y autorizaciones solicitadas para las islas, dando respuesta de las mismas en tiempo y forma. ', 'Se atendió el 90% al 70% de las solicitudes e integracion de expedientes para licencias, permisos y autorizaciones solicitadas para las islas, dando respuesta de las mismas en tiempo y forma. ', 'Se atendió el 49% al 0% de las solicitudes e integración de expedientes para licencias, permisos y autorizaciones solicitadas para las islas, dando respuesta de las mismas en tiempo y forma. ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Se diseñaron  y operaron de 6 a 5 talleres de difusión y educación para la conservación, sobre  la importancia ecológica del ANP con énfasis en las islas localizadas en la zona sur de Sinaloa, frente a la bahía de Mazatlán , así  como temas medioambientales que contribuyan a la conservación de ANP y sus zonas de influencia.', 'Se atendió del 69% al 50% de los usuarios en las islas del área natural protegida localizadas en la zona sur de Sinaloa, proporcionando infromación sobre la normatividad y ordenamientos legales aplicables en materia de protección, manejo y restauración para la conservación de los ecosistemas y su biodiversidad en el área natural protegida.', 'Se atendió el 69% al 50% de las solicitudes e integración de expedientes para licencias, permisos y autorizaciones solicitadas para las islas, dando respuesta de las mismas en tiempo y forma. ', NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (696, 'AIAJ670428', 'Coordinar la elaboración de la normatividad específica para los programas de subsidio a cargo de la Dirección General de Operación Regional.', '1', '30', 'Se elaboran las Reglas de Operación del PROCODES y Lineamientos Internos para la ejecución de 2 programas de subsidio.', 'Se elaboran las Reglas de Operación del PROCODES y Lineamientos Internos para la ejecución de 1 programa de subsidio.', 'No se elabora ningún documento normativo ', NULL, 'Capacitar al personal técnico de las Áreas Naturales Protegidas y de las Direcciones Regionales sobre la normatividad y operación de los programas de subsidio.', '1', '10', 'Se realizan 2 cursos a nivel Nacional y 1 curso a nivel Regional para la capacitación del personal técnico de las Direcciones de Área Natural Protegida y Direcciones Regionales', 'Se realizan 1 curso a nivel Nacional y 1 curso a nivel Regional para la capacitación del personal técnico de las Direcciones de Área Natural Protegida y Direcciones Regionales', 'No se realizan cursos de capacitación al personal técnico de las ANP y de Direcciones Regionales.	', NULL, 'Elaborar las Matrices de Indicadores para Resultados de los programas de subsidio y se elaboran los reportes trimestrales de avance de los indicadores de los programas.\r\n', '1', '30', 'Se elaboran las Matrices de Indicadores para Resultados de dos programas de subsidio y se realizan tres reportes trimestrales de su avance. ', 'Se elaboran la Matriz de Indicadores para Resultados de un programa de subsidio y se realiza dos reportes trimestral de avance. 	', 'No se elaboran las Matrices de Indicadores para resultados de los programas de subsidio.', NULL, 'Coordinar y ejecutar el Programa Anual de Supervisión y Control de los programas de subsidio a cargo de la Dirección General de Operación Regional.', '1', '30', 'Se elabora el Programa Anual de Supervisión y Control de los programas de subsidio y se realizan dos visitas de supervisión.', 'Se elabora el Programa Anual de Supervisión y Control de los programas de subsidio y se realiza una visita de supervisión.	', 'No se elabora el Programa Anual de Supervisión y Control de los programas de subsidio y no se realizan visitas de supervisión.	', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Solo se elaboran las Reglas de Operación del PROCODES	', 'Se realizan 1 curso a nivel Nacional para la capacitación del personal técnico de las Direcciones de Área Natural Protegida y Direcciones Regionales', 'Se elaboran la Matriz de Indicadores para Resultados de un programa de subsidio y no se realizan los reportes trimestrales de avance.	', 'Se elabora el Programa Anual de Supervisión y Control de los programas de subsidio y no se realizan visitas de supervisión.	', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
