INSERT INTO `sed_individuales` VALUES (698, 'MAMF671012', 'CONTRIBUIR AL PROCESO DE PUBLICACIÓN DEL PROGRAMA DE MANEJO DEL ANP, INSTALACIÓN DE SU CONSEJO ASESOR Y CONFORMACIÓN DE OTROS DOS ESPACIOS DE PARTICIPACIÓN SOCIAL (SUBCONSEJOS).', '10', '20', '(90% a 100%)', '(70% a 89%)', '(menos del 50%)', NULL, 'IMPLEMENTAR TRES PROGRAMAS OPERATIVOS ANUALES (POA FISCAL, POA FANP Y POA COSMOS) EN EL APFF COBIO CHICHINAUTZIN EN APEGO A SU DECRETO DE CREACIÓN. ', '10', '25', '(90% a 100%)', '(70% a 89%)', '(menos del 50%)', NULL, 'CONTRIBUIR A LA EJECUCIÓN DE LOS INSTRUMENTOS DE PLANEACIÓN Y REGULACIÓN VIGENTES Y APLICABLES CONFORME AL DECRETO DE CREACIÓN DEL ÁREA NATURAL PROTEGIDA (ANP).  ', '10', '15', '(90% a 100%)', '(70% a 89%)', '(menos del 50%)', NULL, 'EMITIR OPINIÓNES TECNICAS, CONSULTAS Y ATENCIÓN DE OTRAS SOLICITUDES, RELACIONADAS CON LA POLIGONAL DEL ANP.', '10', '15', '(90% a 100%)', '(70% a 89%)', '(menos del 50%)', NULL, 'DIRIGIR DOS PROGRAMAS DE SUBSIDIOS EN EL APFF COBIO CHICHINAUTZIN Y SU ZONA DE INFLUENCIA.', '10', '25', '(90% a 100%)', '(70% a 89%)', '(menos del 50%)', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '(50% a 69%)', '(50% a 69%)', '(50% a 69%)', '(50% a 69%)', '(50% a 69%)', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (699, 'LOHO810712', 'Operar el Programa para la Protección y Restauración de Ecosistemas y Especies Prioritarias (PROREST).', '10', '45', 'Operar en tiempo y forma el 90% de los proyectos dictaminados en el PROREST 2025.', 'Operar en tiempo y forma el 80% de los proyectos dictaminados en el PROREST 2025.', 'Operar en tiempo y forma el 60% de los proyectos dictaminados en el PROREST 2025.', NULL, 'Operar el Programa de Conservación para el Desarrollo Sostenible (PROCODES).', '10', '50', 'Operar en tiempo y forma el 90% de los proyectos dictaminados en el PROCODES 2025.', 'Operar en tiempo y forma el 80% de los proyectos dictaminados en el PROCODES 2025.', 'Operar en tiempo y forma el 60% de los proyectos dictaminados en el PROCODES 2025.', NULL, 'Integrar los informes trimestrales del PROREST-PROCODES en el Programa Operativo Anual (POA).', '10', '5', 'Integrar el 90% de los informes trimestrales del POA.', 'Integrar el 80% de los informes trimestrales del POA.', 'Integrar el 60% de los informes trimestrales del POA.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Operar en tiempo y forma el 70% de los proyectos dictaminados en el PROREST 2025.', 'Operar en tiempo y forma el 70% de los proyectos dictaminados en el PROCODES 2025.', 'Integrar el 70% de los informes trimestrales del POA.', NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (700, 'HESA771214', 'REALIZAR ACCIONES DE CORTO PLAZO DE LOS DIFERENTES COMPONENTES DEL PROGRAMA DE MANEJO, PROGRAMA OPERATIVO ANUAL Y PLANEACION ESTRATEGICAS DEL ANP, CONFORME A LAS FUNCIONES DEL PUESTO', '8', '20', 'SE REALIZO ENTRE EL 99% Y EL 85% DE LAS ACCIONES EN TIEMPO Y FORMA', 'SE REALIZO ENTRE EL89% Y 75% DE LOS PROYECTOS SON OPERADOS EN TIEMPO Y FORMA ', 'NO SE REALIZAN LOS PROYECTOS ', NULL, 'REALIZAR ACCIONES DE MONITOREO DE ECOSISTEMAS Y LA BIODIVERSIDAD EN AMBIENTES MARINOS COSTEROS, CON FORME AL PROGRAMA DE MANEJO Y PROGRAMA OPERATIVO ANUAL DEL ANP ', '4', '20', 'SE REALIZO AL MENOS DOS ACCIONES DE MONITOREOS EN EL POLIGONO DEL ANP Y SU ZONA DE INFLUENCIA ', 'SE REALIZA AL MENOS UNA ACCIÓN DE MONITOREO  EN EL POLIGONO DEL ANP Y SU ZONA DE INFLUENCIA ', 'NO SE REALIZA ACCIONES DE MONITOREO', NULL, 'REALIZAR ACCIONES DE SUPERVISIÓN EN SITIOS ESTRATEGICOS PARA EL USO PÚBLICO Y ESPECIES PRIORITARIAS PARA LA CONSERVACION DE LOS RECURSOS NATURALES Y DAR CUMPLIMIENTO A LAS APLICACIONES DE LA LEY FEDERAL DE DERECHO', '4', '20', 'SE CUMPLE CON EL 99 Y 95% DE LAS ACCIONES DE SUPERVISIÓN ', 'SE CUMPLE CON EL 89 % DE LAS ACCIONES DE SUPERVISIÓN ', 'NO SE CUMPLE ACCIONES DE SUPERVISIÓN ', NULL, 'REALIZAR VERIFICACIONES EN CAMPO Y TOMA DE DATOS RESPECTO A LAS OBRAS Y ACTIVIDADES EN ZONAS MARINAS COSTERAS, PARA DAR SUSTENTO TÉCNICO A LAS DENUNCIAS Y/O DICTAMENES TÉCNICOS CORRESPONDIENTE PARA LA ATENCION DE AMENAZAS Y MANEJO DE RIESGOS EN EL ANP', '4', '20', 'SE CUMPLE CON EL 99%  Y EL 95% DE LAS ACTIVIDADES ASIGNADAS', 'SE CUMPLE CON EL 89% DE LAS ACTIVIDADES ASIGNADAS', 'NO SE CUMPLE LAS ACTIVIDADES ASIGNADAS ', NULL, 'REALIZAR ACCIONES DE GESTION, REPRESENTACION Y COORDINACION INSTITUCIONAL GUBERNAMENTALES EN MATERIA DE SEGURIDAD NACIONAL, SEGURIDAD MARITIMA, MEDIO AMBIENTE EN LA ZONA SUR DE LA RESERVA DE LA BIOSFERA CARIBE MEXICANO, ESTABLECIENDO CRITERIOS  DEL PROGRAMA DE MANEJO Y EL PROGRAMA OPERATIVO ANUAL ', '5', '20', 'SE ATIENDE EL 99% Y 95% DE LA GESTION', 'SE ATIENDE EL 89% DE LA GESTION ', 'N O SE ATIENDE LA GESTION ', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'SE REALIZA MENOS DEL 75% DE LOS PROYECTOS OPERADOS EN TIEMPO Y FORMA', 'SE REALIZA NINGUNA  ACCIÓN DE MONITOREO EN EL POLIGONO DEL ANP Y SU ZONA DE INFLUENCIA ', 'SE CUMPLE CON MENOS DEL 80% DE LAS ACCIONES DE SUPERVISIÓN ', 'SE CUMPLE CON MENOS DEL 80% DE LAS ACTIVIDADES ASIGNADAS', 'SE ATIENDE MENOS DEL 80% DE LA GESTION ', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (701, 'FEIA760206', 'Elaborar e implementar el Programa Operativo Anual de la Reserva de la Biosfera Mariposa Monarca, conforme a los objetivos y lineamientos establecidos en el decreto y el programa de manejo y otros ordenamientos legales aplicables.', '7', '20', '90% a 100%', '70% a 89%', 'menos del 50%', NULL, 'Promover y supervisar los programas de subsidios y proyectos de conservación para el desarrollo; y coadyuvar en la atención de contingencias ambientales en coordinación con las autoridades competentes.', '7', '20', '90% a 100%', '70% a 89%', 'menos del 50%', NULL, 'Formular el programa de manejo de la Reserva de la Biosfera Mariposa Monarca de conformidad con las disposiciones jurídicas aplicables.', '7', '20', '90% a 100%', '70% a 89%', 'menos del 50%', NULL, 'Coordinar y dar seguimiento al Consejo Asesor y otros esquemas de participación social.', '7', '20', '90% a 100%', '70% a 89%', 'menos del 50%', NULL, 'Emitir opiniones y/o dictámenes técnicos de soporte  para el otorgamiento, modificación, prórroga, rescate, suspensión, extinción, revocación o anulación de concesiones, permisos, licencias o autorizaciones en materia de investigación, uso y aprovechamiento de los ecosistemas y su biodiversidad, en materia de evaluación del impacto ambiental que se requieren para la ejecución de obras y actividades que se realicen en la Reserva de la Biosfera Mariposa Monarca', '7', '20', '90% a 100%', '70% a 89%', 'menos del 50%', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '50% a 69%', '50% a 69%', '50% a 69%', '50% a 69%', '50% a 69%', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (702, 'MOGS891101', 'Compilar y analizar información de especies en riesgo de flora y fauna de la reserva, para la generación de bases de datos así como sistematizar la información como una herramienta de manejo de la biodiversidad; además de monitorear y evaluar los cambios de uso de suelo y vegetación mediante los Sistemas de Información Geográfica. ', '10', '30', '80 a 100', '60 a 79', '59 ', NULL, 'Contribuir en el diseño y operación de la estrategia de educación para la conservación y comunicación social, con la finalidad de sensibilizar a los usuarios y habitantes de la zona de influencia de la reserva.  ', '10', '30', '80 a 100', '60 a 79', '59', NULL, 'Ejecutar actividades administrativas y de logística, así como la gestión de recursos materiales, humanos, tecnológicos, financieros y/o jurídicos, que se requieran dentro de su ámbito de aplicación asegurando el cumplimiento normativo y la consecución de las actividades y la adecuada operación del ANP y la dirección regional. ', '10', '20', '80 a 100', '60 a 79', '59', NULL, 'La demás que le confiera y/o instruya su jefe inmediato, el director del ANP, el director regional, la unidad administrativa, la unidad técnica  o la unidad jurídica de la dirección regional, así como las que señalen las disposiciones legales  y reglamentarias vigentes dentro de su alcance y marco de actuación orientadas a asegurar la adecuada operación del ANP, de la dirección regional  y de la conservación del medio ambiente. ', '10', '20', '80 a 100', '60 a 79', '59', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Menos de 59', 'Menos de 59', 'Menos de 59', 'Menos de 59', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (703, 'ZAMD820327', 'Diseñar, generar y elaborar el 100% de material impreso o digital con fines didácticos e interpretativos que apoyen en la difusión de los objetos de conservación de la ANP', '10', '20', 'Generó el 100% de materiales de difusión y didáctico.', 'Generó el 70% de materiales de difusión y didáctico.', 'Generó menos del 50% de materiales de difusión y didáctico.', NULL, 'Dar mantenimiento a la señalización informativa, interpretativa y/o restrictiva de la reserva y sus zonas de uso público.', '1', '20', 'Se dió mantenimiento a 50 señales de la reserva.', 'Se dió mantenimiento a 30 señales de la reserva.', 'Se dió mantenimiento a menos de 20 señales de la reserva.', NULL, 'Realizar y/o participar en actividades de educación ambiental presenciales o en línea con las comunidades que integran esta ANP  para difundir la importancia de la ANP y sus objetos de conservación.', '10', '20', 'Realizar y participar en el 100% de las actividades de educación ambiental.', 'Realizar y participar en el 70% de las actividades de educación ambiental.', 'Realizar y participar en menos del 60% de las actividades de educación ambiental.', NULL, 'Coordinar la operación del Centro de Visitantes y Museo Schuk Toak y mantenerlo en funcionamiento óptimo para el logro de los objetivos del programa de educación ambiental.', '10', '20', 'Coordinar el 100% las operaciones del Centro de visitantes.', 'Coordinar el 70% las operaciones del Centro de visitantes .', 'Coordinar 40% las operaciones del Centro de visitantes.', NULL, 'Atender la totalidad de tramites de permisos y autorizaciones de las distintas actividades que se realizan en el Anp en coordinación con la Dirección del Anp y la Dirección Regional.', '10', '20', 'Atendió el 100% de trámites de permisos y autorizaciones', 'Atendió el 70% de trámites de permisos y autorizaciones', 'Atendió menos del 50% de trámites de permisos y autorizaciones', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Generó el 50% de materiales de difusión y didáctico.', 'Se dió mantenimiento a 20 señales de la reserva.', 'Realizar y participar en el 50% de las actividades de educación ambiental.', 'Coordinar al 50% las operaciones del Centro de visitantes .', 'Atendió el 50% de trámites de permisos y autorizaciones', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
