INSERT INTO `sed_individuales` VALUES (707, 'MEFA870408', 'Integrar expedientes con la información disponible del ANP para analizar propuestas de manejo y conservación.', '10', '20', 'Integración del 100 al 90% de los expedientes con información disponible del ANP, para analizar propuestas de manejo y conservación.', 'Integración del 89 al 70% de los expedientes con información disponible del ANP, para analizar propuestas de manejo y conservación.', 'Integración del 49 al 0% de los expedientes con información disponible del ANP, para analizar propuestas de manejo y conservación.', NULL, 'Elaborar y mantener actualizadas las bases de datos asignadas de las especies monitoreadas.', '10', '20', 'Mantener actualizadas en un 100 a 90 % las bases de datos asignadas de las especies monitoreadas.', 'Mantener actualizadas en un 89 a 70 % las bases de datos asignadas de las especies monitoreadas.', 'Mantener actualizadas en un 40 a 0 % las bases de datos asignadas de las especies monitoreadas.', NULL, 'Promover la participación de la población local en proyectos de monitoreo biológico y ambiental, necesarios para el manejo de los recursos naturales en el área natural protegida.', '1', '20', '3 o mas comunidades participan en actividades de monitoreo.', '2 comunidades participan en actividades de monitoreo.', 'Ninguna comunidad local participa en actividades de monitoreo.', NULL, 'Promover, dar seguimiento e integrar expedientes de proyectos asignados para la protección, manejo y restauración de tortugas marinas.', '10', '20', 'Promover, dar seguimiento e integrar del 100 al 90% de los expedientes de proyectos asignados de protección, manejo y restauración de tortugas marinas.', 'Promover, dar seguimiento e integrar del 89 al 70% de los expedientes de proyectos asignados de protección, manejo y restauración de tortugas marinas.', 'Promover, dar seguimiento e integrar del 49 al 0% de los expedientes de proyectos asignados de protección, manejo y restauración de tortugas marinas.', NULL, 'Apoyar a la dirección del ANP en el seguimiento de las acciones formuladas en el Programa Operativo del Fondo de Áreas Naturales Protegidas (FANP).', '10', '20', 'Realizar del 100-90% de las acciones para el seguimiento de las acciones formuladas en el POA del FANP.', 'Realizar del 89-70% de las acciones para el seguimiento del cumplimiento de las acciones formuladas en el POA del FANP.', 'Realizar del 49-0% de las acciones para el seguimiento del cumplimiento de las acciones formuladas en el POA del FANP.', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Integración del 69 al 50% de los expedientes con información disponible del ANP, para analizar propuestas de manejo y conservación.', 'Mantener actualizadas en un 69 a 50 % las bases de datos asignadas de las especies monitoreadas.', '1 comunidad participando en actividades de monitoreo.', 'Promover, dar seguimiento e integrar del 69 al 50% de los expedientes de proyectos asignados de protección, manejo y restauración de tortugas marinas.', 'Realizar del 69-50% de las acciones para el seguimiento del cumplimiento de las acciones formuladas en el POA del FANP.', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
