INSERT INTO `sed_individuales` VALUES (709, 'SOOR580904', 'REVISAR, VALIDAR, Y VERIFICAR LA INFORMACIÓN RECIBIDA QUE ACTUALIZARÁ LA INFORMACIÓN QUE CONFORMA LA BASE DE DATOS DEL PADRÓN INMOBILIARIO DE LAS OFICINAS ADMINISTRATIVAS Y OPERATIVAS QUE ESTÁN A CARGO DE LA COMISIÓN NACIONAL DE ÁREAS NATURALES PROTEGIDAS EN SUS DIFERENTES FIGURAS JURÍDICAS.', '1', '20', 'REALIZAR EL 100 AL 95 % DE LAS ACTIVIDADES', 'REALIZAR DEL 94 AL 90 % DE LAS ACTIVIDADES', 'REALIZAR DEL 89 AL 85 % DE LAS ACTIVIDADES', NULL, 'REVISAR LA DOCUMENTACIÓN RECIBIDA EN OFICINAS CENTRALES DE OTRAS INSTITUCIONES QUE SOPORTARÁN LA ACREDITACIÓN DE LOS INMUEBLES DE LAS OFICINAS ADMINISTRATIVAS Y OPERATIVAS DE LA COMISIÓN NACIONAL DE ÁREAS NATURALES PROTEGIDAS, PARA LA CONFORMACIÓN DEL EXPEDIENTE CORRESPONDIENTE.', '1', '20', 'REALIZAR EL 100 AL 95 % DE LAS ACTIVIDADES', 'REALIZAR DEL 94 AL 90 % DE LAS ACTIVIDADES', 'REALIZAR DEL 89 AL 85 % DE LAS ACTIVIDADES', NULL, 'DAR ATENCIÓN Y REVISIÓN OPORTUNA A LAS SOLICITUDES DE NUEVOS ARRENDAMIENTOS, ENVIADAS POR LAS DIRECCIONES REGIONALES, APEGÁNDOSE A LOS LINEAMIENTOS QUE ESTABLECE EL INSTITUTO DE ADMINISTRACIÓN DE AVALÚOS DE BIENES NACIONALES.', '1', '20', 'REALIZAR EL 100 AL 95 % DE LAS ACTIVIDADES', 'REALIZAR DEL 94 AL 90 % DE LAS ACTIVIDADES', 'REALIZAR DEL 89 AL 85 % DE LAS ACTIVIDADES', NULL, 'PROPORCIONAR LA INFORMACIÓN PARA LA REALIZACIÓN DE REPORTES E INFORMES PERIÓDICOS, SOLICITADOS PARA DAR CUMPLIMIENTO A LA LEY FEDERAL DE AUSTERIDAD REPUBLICANA Y LINEAMIENTOS EN MATERIA DE AUSTERIDAD REPUBLICANA DE LA ADMINISTRACIÓN PÚBLICA FEDERAL.', '1', '20', 'REALIZAR EL 100 AL 95 % DE LAS ACTIVIDADES', 'REALIZAR DEL 94 AL 90 % DE LAS ACTIVIDADES', 'REALIZAR DEL 89 AL 85 % DE LAS ACTIVIDADES', NULL, 'LLEVAR A CABO LA ORGANIZACIÓN, CONSERVACIÓN, ADMINISTRACIÓN Y PRESERVACIÓN HOMOGÉNEA DE LOS ARCHIVOS DE ACUERDO CON LA LEY GENERAL DE ARCHIVO (ULTIMA REFORMA PUBLICADA EN EL DIARIO OFICIAL DE LA FEDERACIÓN EL 19 DE ENERO DE 2023), DE LOS INMUEBLES DE LAS OFICI