INSERT INTO `sed_individuales` VALUES (780, 'LURV710710', 'REVISION DE LA DOCUMENTACIÓN DE SUBSIDIOS ENVIADA POR PARTE DE LAS ANP, COMO SON SOLICITUDES DE PAGO, COMPROBACIONES, EXPEDIENTES TECNICOS Y DEMAS ANEXOS DE LOS PROYECTOS DE PROCODES Y PROREST, PARA QUE REALICEN UNA OPTIMA EJECUCION DE SUS OPERACIONES CORRESPONDIENTE A SUS FUNCIONES.	\r\n', '10', '25', '80% AL 100%', '61% AL 79%', ' -50%', NULL, 'LLEVAR EL CONTROL DE LOS GASTOS DE OPERACION DE LOS PROGRAMAS DE SUBSIDIOS DE CADA ANP, CON LA FINALIDAD DE CADA AREA LOGRE EL CUMPLIMIENTO DE LAS METAS QUE LE SON ESTABLECIDAS DENTRO DEL TIEMPO DETERMINADO EN CADA PROGRAMA	\r\n', '10', '25', '80% AL 100%', '61% AL 79%', ' -50%', NULL, 'ASISTENCIA A LOS PROGRAMAS DE SUPERVISION PARA LLEVAR EL CONTROL DE LOS RECURSOS ASIGNADOS A LOS DIFERENTES BENEFICIARIOS:\r\n- VISITAS A LOS BENEFICIARIOS PARA LA REVISION DE LAS ACCIONES APROBADAS Y VERIFICACION DE LOS AVANCES REALIZADOS\r\n- LLENADO DE FORMATO CON BASE EN LA REVISION DE LOS EXPEDIENTES TECNICOS IN SITU\r\n- ENTREVISTAS CON PERSONAS BENEFICIARIAS \r\n- PARTICIPACION EN EL LEVANTAMIENTO DE LA MINUTA FINAL.\r\n	\r\n', '10', '25', '80% AL 100%', '61% AL 79%', ' -50%', NULL, 'BRINDAR APOYO ADMINISTRATIVO CORRESPONDIENTE A LA UNIDAD DE SUBSIDIOS Y A LA DIRECCION REGIONAL, COMO ES LA ELABORACION DE SOLICITUDES DE PAGO, COMPROBACION DE FACTURAS, DESGLOSE DE GASTOS, INFORMES DE COMISION ENTRE OTRAS. ASI COMO EL APOYO A LAS ANP SOBRE LAS NECESIDADES QUE LE SEAN REQUERIDAS.	\r\n', '10', '25', '80% AL 100%', '61% AL 79%', ' -50%', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '51% AL 60%', '51% AL 60%', '51% AL 60%', '51% AL 60%', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (781, 'MAMX690720', '1)	CUMPLIR CON LAS METAS ESTABLECIDAS EN EL PROGRAMA OPERATIVO ANUAL 2024 DE LA RESERVA DE LA BIOSFERA SIERRA LA LAGUNA', '10', '25', 'CUMPLIR ENTRE EL 80 Y EL 100% DE LAS METAS ESTABLECIDAS EN EL PROGRAMA OPERATIVO ANUAL 2023 DE LA RESERVA DE LA BIOSFERA SIERRA LA LAGUNA', 'CUMPLIR MENOS DEL 80% DE LAS METAS ESTABLECIDAS EN EL PROGRAMA OPERATIVO ANUAL 2023 DE LA RESERVA DE LA BIOSFERA SIERRA LA LAGUNA', 'CUMPLIR MENOS DEL 60% DE LAS METAS ESTABLECIDAS EN EL PROGRAMA OPERATIVO ANUAL 2023 DE LA RESERVA DE LA BIOSFERA SIERRA LA LAGUNA', NULL, 'LLEVAR A CABO EL EJERCICIO DE SUBSIDIOS DE LOS PROYECTOS EN APOYO A LAS COMUNIDADES DENTRO DE LA RESERVA DE LA BIOSFERA SIERRA LA LAGUNA Y SU AREA DE INFLUENCIA DURANTE EL AÑO 2025', '10', '25', 'LLEVAR A CABO EL EJERCICIO DE SUBSIDIOS ENTRE UN 90 Y 100% DE LOS PROYECTOS EN APOYO A LAS COMUNIDADES DENTRO DE LA RESERVA DE LA BIOSFERA SIERRA LA LAGUNA Y SU AREA DE INFLUENCIA DURANTE EL AÑO 2025', 'LLEVAR A CABO EL EJERCICIO DE SUBSIDIOS ENTRE UN 70 Y 89% DE LOS PROYECTOS EN APOYO A LAS COMUNIDADES DENTRO DE LA RESERVA DE LA BIOSFERA SIERRA LA LAGUNA Y SU AREA DE INFLUENCIA DURANTE EL AÑO 2025', 'LLEVAR A CABO EL EJERCICIO DE SUBSIDIOS MENOS DEL 60% DE LOS PROYECTOS EN APOYO A LAS COMUNIDADES DENTRO DE LA RESERVA DE LA BIOSFERA SIERRA LA LAGUNA Y SU AREA DE INFLUENCIA DURANTE EL AÑO 2025', NULL, 'PREPARAR Y EMITIR RESPUESTA A SOLICITUDES DE INFORMACION CIUDADANA', '10', '25', 'PREPARAR Y EMITIR RESPUESTA A SOLICITUDES DE INFORMACION CIUDADANA ENTRE 95 Y 100% EN TIEMPO Y FORMA', 'PREPARAR Y EMITIR RESPUESTA A SOLICITUDES DE INFORMACION CIUDADANA ENTRE 85 Y 94% EN TIEMPO Y FORMA', 'PREPARAR Y EMITIR RESPUESTA A SOLICITUDES DE INFORMACION CIUDADANA MENOS DEL 79%', NULL, 'ATENDER Y EMITIR RESPUESTA A LAS SOLICITUDES DE OPINIONES TECNICAS EN MATERIA DE VIDA SILVESTRE, CAMBIO DE USO DE SUELO Y FORESTAL, IMPACTO AMBIENTAL EN TIEMPO Y FORMA A SOLICITUD DE LA DIRECCION REGIONAL O DE