INSERT INTO `sed_individuales` VALUES (782, 'AESD850527', 'Coadyuvar en la elaboración, implementación y seguimiento del Programa Operativo Anual del Complejo Xcalak- Chinchorro para fortalecer el proceso efectivo de la planeación y cumplimiento de sus objetivos.', '10', '20', 'Se cumplen en tiempo y forma al 100% las actividades programas en el POA del Complejo Xcalak-Chinchorro', 'Se cumplen en un 80% las actividades programadas en el POA del Complejo Xcalak-Chinchorro', 'Se cumplen en un 20% las actividades programadas en el POA del Complejo Xcalak-Chinchorro', NULL, 'Promover la observancia del programa de conservación  y manejo del Parque Nacional Arrecifes de Xcalak y de la Reserva de la Biosfera Banco Chinchorro, así como de las reglas administrativas del mismo para el cumplimiento de las disposiciones legales aplicables y garantizar la conservación de ambas ANP.', '10', '20', 'Se realizan en un 100% acciones que permitan el cumplimiento de las reglas administrativas de los programas de manejo de ambas ANP', 'Se realizan en un 80% acciones que permitan el cumplimiento de las reglas administrativas de los programas de manejo de ambas ANP', 'Se realizan en un 20% acciones que permitan el cumplimiento de las reglas administrativas de los programas de manejo de ambas ANP', NULL, 'Coordinar el desarrollo de acciones y proyectos relaciones con ordenamiento productivo, desarrollo comunitario y turísticos, supervisión y vigilancia, educación ambiental, comunicación, conservación, monitoreo, investigación científica y restauración de ambas ANP para cumplir con los objetivos planteados en las declaratorias correspondientes, así como en su programa de manejo.', '10', '20', 'Se coordinan al 100% diversas acciones y proyectos que permitan cumplir con los objetos de creación de ambas ANP.', 'Se coordinan al 80% diversas acciones y proyectos que permitan cumplir con los objetos de creación de ambas ANP.', 'Se coordinan al 20% diversas acciones y proyectos que permitan cumplir con los objetos de creación de ambas ANP.', NULL, 'Realizar acciones de conservación, protección y acciones de supervisión y vigilancia en coordinación con diversas instancias como PROFEPA, SEMAR, FGR, CONAPESCA para asegurar el cumplimiento de la normatividad vigente en ambas ANP.', '10', '20', 'Se realizan en un 100% diversas acciones de conservación, protección, supervisión y vigilancia en coordinación con otras instancias para el cumplimiento de la normatividad vigente de ambas ANP', 'Se realizan en un 80% diversas acciones de conservación, protección, supervisión y vigilancia en coordinación con otras instancias para el cumplimiento de la normatividad vigente de ambas ANP', 'Se realizan en un 20% diversas acciones de conservación, protección, supervisión y vigilancia en coordinación con otras instancias para el cumplimiento de la normatividad vigente de ambas ANP', NULL, 'Desarrollar con instituciones, organizaciones de la sociedad civil, actores locales, entre otros; la instrumentación de mecanismos de participación social, de acciones y proyectos de conservación, de aprovechamiento sustentable de los ecosistemas y especies silvestres para procurar la integralidad ecológica y el mejoramiento de la calidad de vida de los habitantes de ambas ANP.', '10', '20', 'Se desarrollan al 100% diversos mecanismos que ayudan a mantener la integralidad ecológica y mejoramiento de la calidad de vida de ambas ANP.', 'Se desarrollan al 80% diversos mecanismos que ayudan a mantener la integralidad ecológica y mejoramiento de la calidad de vida de ambas ANP.', 'Se desarrollan al 30% diversos mecanismos que ayudan a mantener la integralidad ecológica y mejoramiento de la calidad de vida de ambas ANP.', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Se cumplen en un 50% las actividades programadas en el POA del Complejo Xcalak-Chinchorro', 'Se realizan en un 50% acciones que permitan el cumplimiento de las reglas administrativas de los programas de manejo de ambas ANP', 'Se coordinan al 50% diversas acciones y proyectos que permitan cumplir con los objetos de creación de ambas ANP.', 'Se realizan en un 50% diversas acciones de conservación, protección, supervisión y vigilancia en coordinación con otras instancias para el cumplimiento de la normatividad vigente de ambas ANP', 'Se desarrollan al 50% diversos mecanismos que ayudan a mantener la integralidad ecológica y mejoramiento de la calidad de vida de ambas ANP.', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (783, 'AEEJ800826', 'OPERAR EL PROGRAMA DE SANIDAD FORESTAL, MANEJO INTEGRADO DEL FUEGO Y RESTAURACIÓN DEL ANP', '10', '25', '90% a 100%', '70% al 89%', 'Menor al 50%', NULL, 'OPERAR EL PROGRAMA DE SUBSIDIO PROREST: CONVOCATORIA, DIFUSIÓN, RECEPCIÓN, INTEGRACIÓN DE EXPEDIENTES, CONTRALORÍA SOCIAL, SUPERVISIÓN Y SEGUIMIENTO.', '10', '25', '90% a 100%', '70% al 89%', 'Menor al 50%', NULL, 'DAR SEGUIMIENTO A LOS TRABAJOS DE INVESTIGACIÓN REALIZADOS EN EL ANP, SISTEMATIZAR INFORMACIÓN Y RESULTADOS Y GENERAR INFORMES DE LOS MISMOS.', '10', '10', '90% a 100%', '70% al 89%', 'Menor al 50%', NULL, 'OPERAR EL PROGRAMA DE VIGILANCIA Y MONITOREO BIOLÓGICO EN EL ANP', '10', '25', '90% a 100%', '70% al 89%', 'Menor al 50%', NULL, 'AYUDAR EN EL PROCESO DE ACTUALIZACIÓN Y/O MODIFICACIÓN DEL PROGRAMA DE MANEJO DEL ANP', '10', '15', '90% a 100%', '70% al 89%', 'Menor al 50%', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '50% al 69%', '50% al 69%', '50% al 69%', '50% al 69%', '50% al 69%', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (1080, 'RAPB650618', 'Supervisar y coordinar el seguimiento a las acciones de restauración y conservación del pastizal halofito en predios con acuerdo de colaboración.', '4', '30', 'Se cuenta con informe y resultados de superficie con acciones de restauración del pastizal halofito mediante la siembra de pastos nativos.', 'Se cuenta con información sobre las areas susceptibles de restauración o rehabilitación del pastizal halofito', 'No se realiza la actividad', NULL, 'Promover y gestionar la estimación de la producción de materia seca en un terreno nacional para determinar la capacidad de carga animal y los tiempos de uso y tiempos de descanso.', '4', '30', 'Se lleva a cabo el monitoreo de materia seca y se cuenta con la información para determinar la capacidad de carga animal y tiempos de pastoreo rotacional.', 'Se lleva a cabo el monitoreo de materia seca en el terreno nacional ', 'Se cancela la actividad', NULL, 'Coordinar las actividades para el seguimiento, operación y supervisión de los programas de subsidio en el ANP.', '4', '40', 'Se supervisa y atiende efectivamente la integración de la totalidad de los expedientes de los programas de subsidio PROREST y PROCODES', 'Se supervisa y atiende efectivamente la integración del 70 por ciento de los expedientes de los programas de subsidio PROREST y PROCODES', 'No hay recursos para la operación del los programas', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'No se cuenta con información', 'No se llevo a cabo el monitoreo de materia seca en el terreno nacional', 'No se llevan a cabo las actividades para la operación de los programas de subsidio', NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (784, 'CAPM790407', 'APOYAR EN OFICINA AL PROGRAMA DE COMUNICACIÓN Y CULTURA PARA LA CONSERVACIÓN EN LAS DIFERENTES ACTIVIDADES QUE IMPLIQUEN ORGANIZACIÓN, GESTIÓN Y SEGUIMIENTO SOBRE ACTIVIDADES DE EDUCACIÓN AMBIENTAL, SEGUIMIENTO DE NOTAS PERIODÍSTICAS REFERENTES A TEMAS AMBIENTALES, DE CONSERVACIÓN, CONTAMINACIÓN, EXPLOTACIÓN Y USO DE RECURSOS NATURALES PRINCIPALMENTE EN LAS ANP`S QUE INTEGRAN LA REGIÓN PENÍNSULA DE BAJA CALIFORNIA Y PACIFICO NORTE.\r\n', '10', '30', 'Apoyar las actividades de oficina en un rango del 90 al 100%', 'Apoyar las actividades de oficina en un rango del 80 al 90%', 'Apoyar las actividades de oficina en un rango menor al 70%', NULL, 'APOYAR EN OFICINA AL DEPARTAMENTO DE RECURSOS FINANCIEROS EN LOS DIFERENTES TRAMITES RELACIONADOS CON ACTIVIDADES PROPIAS DEL DEPARTAMENTO QUE IMPLIQUE ORGANIZACIÓN, GESTIÓN Y SEGUIMIENTO DE DOCUMENTOS RELACIONADOS CON SOLICITUDES DE PAGO.\r\n', '10', '30', 'Apoyar las actividades de oficina en un rango del 95 al 100%', 'Apoyar las actividades de oficina en un rango del 90 al 95%', 'Apoyar las actividades de oficina en un rango menor al 85%', NULL, 'LLEVAR UN SEGUIMIENTO E INTEGRAR  LAS CUENTAS POR LIQUIDAR CERTIFICADAS QUE SE GENEREN DURANTE EL AÑO, LO CUAL IMPLIQUE ESCANEO Y ELABORACIÓN DE EXPEDIENTES PARA SU CONTROL\r\n', '10', '40', 'Integrar cuentas por liquidar certificadas en un rango del 95 al 100%', 'Integrar cuentas por liquidar certificadas en un rango del 90 al 95%', 'Integrar cuentas por liquidar certificadas en un rango menor al 85% ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Apoyar las actividades de oficina en un rango del 70 al 80%', 'Apoyar las actividades de oficina en un rango del 85 al 90%', 'Integrar cuentas por liquidar certificadas en un rango del 85 al 90% ', NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (785, 'RUOL890421', 'CAPACITAR A PROMOTORAS AMBIENTALES EN TEMAS DE EDUCACIÓN AMBIENTAL \"CUIDADOS DEL AGUA\"', '2', '30', 'Se imparte un curso en el tema de educación \"Cuidados del Agua\"', 'Se gestiona un curso en el tema de educación \"Cuidados del Agua\"', 'No se gestiona ningún curso para las Promotoras Ambientales', NULL, 'ELABORAR Y DISEÑAR MATERIAL DIGITAL PARA PROMOVER LOS VALORES DE CONSERVACIÓN DEL ANP MEDIANTE REDES SOCIALES\r\n', '2', '30', 'Se mantienen activas la redes sociales del ANP para promover los objetos de conservación', 'Se le da poca difusión a los objetos de conservación mediante redes sociales', 'No se mantienen activas las redes sociales del ANP', NULL, 'PROMOVER LA PARTICIPACIÓN DE ACTORES EXTERNOS EN ACTIVIDADES DE DIFUSIÓN Y COMUNICACIÓN AMBIENTAL', '2', '20', 'Se logra la participación de dos actores clave en las actividades de difusión y comunicación ambiental', 'Se logra la participación de un actor clave en las actividades de difusión y comunicación ambiental', 'No se concreta la participación de ningún actor clave en las actividades de difusión y participación ambiental', NULL, 'EVALUAR LA OPERACIÓN DEL AS RUTAS CRÍTICAS EN COORDINACIÓN CON ACTORES CLAVE', '2', '20', 'Se logra evaluar las rutas críticas con actores claves', 'Se realizan reuniones de planeación para con actores clave para revisar las rutas críticas', 'No se concreta la evaluación de las rutas críticas', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'No se realizó ninguna acción', 'No se realizó ninguna acción', 'No se realizó ninguna acción', 'No se realizó ninguna acción', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (789, 'QUGB851216', 'EJECUTAR LAS ACCIONES PROGRAMADAS PARA CONSERVAR LOS ECOSISTEMAS Y SU BIODIVERSIDAD, CONFORME A LOS OBJETIVOS Y LINEAMIENTOS ESTABLECIDOS EN EL DECRETO Y EL PROGRAMA DE MANEJO DE LAS ÁREA S NATURALES PROTEGIDAS DE COZUMEL', '10', '20', '80-100', '60-80', '20-40', NULL, 'PROMOVER LOS PROGRAMAS DE SUBSIDIOS Y PROYECTOS DE CONSERVACIÓN PARA EL DESARROLLO DEL ÁREA NATURAL PROTEGIDA', '10', '20', '80-100', '60-80', '20-40', NULL, 'EMITIR LA OPINIÓN QUE SE SOLICITE RESPECTO A LOS APROVECHAMIENTOS, SERVICIOS, OBRAS Y ACTIVIDADES DE LOS QUE SE PRETENDAN AUTORIZAR POR PARTE DE LAS AUTORIDADES COMPETENTES', '10', '20', '80-100', '60-80', '20-40', NULL, 'SUPERVISAR QUE LAS ACCIONES QUE SE REALICEN DENTRO DE LAS ÁREAS NATURALES PROTEGIDAS DE COZUMEL SE AJUSTEN A LOS PROPÓSITOS DE LOS ORDENAMIENTOS LEGALES APLICABLES EN MATERIA DE PROTECCIÓN, MANEJO Y RESTAURACIÓN PARA LA CONSERVACIÓN DE LOS ECOSISTEMAS Y SU BIODIVERSIDAD', '10', '20', '80-100', '60-80', '20-40', NULL, 'EN MI CARÁCTER DE SECRETARIO TÉCNICO DE LOS CONSEJOS ASESORES DE LAS ÁREAS NATURALES PROTEGIDAS DE COZUMEL, DAR SEGUIMIENTO A LAS ACTIVIDADES QUE SE DERIVEN DE LOS ACUERDOS DE LOS MISMOS', '10', '20', '80-100', '60-80', '20-40', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '40-60', '40-60', '40-60', '40-60', '40-60', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (790, 'JURA880609', 'LLEVAR A CABO, EN COORDINACIÓN CON LA DGOR Y LAS ANP, LAS ACTIVIDADES DE SEGUIMIENTO, CONTROL Y SUPERVISIÓN DE LA EJECUCIÓN DE LOS APOYOS AUTORIZADOS DEL PROCODES, A FIN DE VERIFICAR QUE SE SUJETEN A LOS REQUISITOS, TÉRMINOS Y CONDICIONES PREVISTAS EN LINEAMIENTOS INTERNOS Y REGLAS DE OPERACIÓN, A LAS DISPOSICIONES JURÍDICAS APLICABLES, Y QUE SEAN CONGRUENTES CON EL DECRETO O PROGRAMA DE MANEJO DE LAS ANP, A TRAVÉS DE LA REVISIÓN Y ANÁLISIS FÍSICO Y DOCUMENTAL PARA EL PRESENTE EJERCICIO FISCAL.\r\n\r\n', '5', '20', 'ACTIVACIÓN DE PROYECTOS Y CUMPLIMIENTO NORMATIVO - 95% AL 100%', 'ACTIVACIÓN DE PROYECTOS Y CUMPLIMIENTO NORMATIVO - 80% AL 94%', 'ACTIVACIÓN DE PROYECTOS Y CUMPLIMIENTO NORMATIVO - POR DEBAJO DEL 70%', NULL, 'LLEVAR A CABO, EN COORDINACIÓN CON LA DGOR Y RECURSOS FINANCIEROS DE LA DR, LAS ACTIVIDADES DE DISTRIBUCIÓN, CONTROL, GESTIÓN Y SEGUIMIENTO DEL EJERCICIO DE LOS RECURSOS AUTORIZADOS DEL PROCODES DE CADA UNA DE LAS ANP, A TRAVÉS DE BITÁCORAS, VERIFICACIÓN Y VALIDACIÓN DE LOS INFORMES DE AVANCES FÍSICOS Y FINANCIEROS MENSUALES Y TRIMESTRALES, ENTRE OTRAS.\r\n\r\n', '5', '20', 'CUMPLIMIENTO DE AVANCES FÍSICOS Y FINANCIEROS DEL 95% AL 100%', 'CUMPLIMIENTO DE AVANCES FÍSICOS Y FINANCIEROS DEL 90% AL 94%', 'CUMPLIMIENTO DE AVANCES FÍSICOS Y FINANCIEROS POR DEBAJO DEL 70%', NULL, 'ATENDER EN TIEMPO Y FORMA LOS REQUERIMIENTOS DE INFORMACIÓN Y AUDITORIAS CORRESPONDIENTES DEL PROCODES, ASÍ COMO APOYAR Y ACOMPAÑAR A LA DGOR EN LAS VISITAS DE SUPERVISIÓN ANUAL A LAS ANP EN ATENCIÓN AL PROGRAMA ANUAL DE SUPERVISIÓN Y CONTROL DE LOS PROGRAMAS DE SUBSIDIOS.', '5', '20', 'SE ATENDIERON LOS REQUERIMIENTOS Y VISITAS DE SUPERVISIÓN DEL 96% AL 100%', 'SE ATENDIERON LOS REQUERIMIENTOS Y VISITAS DE SUPERVISIÓN DEL 90% AL 95%', 'SE ATENDIERON LOS REQUERIMIENTOS Y VISITAS DE SUPERVISIÓN POR DEBAJO DEL 80%', NULL, 'BRINDAR ASISTENCIA TÉCNICA Y ASESORÍA A LAS ANP PARA LA EJECUCIÓN DE LOS APOYOS APROBADOS, SEGUIMIENTO A LAS CAPTURAS Y REQUERIMIENTOS DE LOS SISTEMAS DE INFORMACIÓN DEL PROCODES (SISP) Y SISTEMA INFORMÁTICO DE CONTRALORÍA SOCIAL (SICS) DE LA SECRETARÍA DE LA FUNCIÓN PÚBLICA, ENTRE OTRAS ACTIVIDADES QUE ASEGUREN EL CUMPLIMIENTO DE METAS Y ACCIONES COMPROMETIDAS EN EL PROGRAMA.', '5', '20', 'APOYO Y CUMPLIMIENTO DEL 96% AL 100% A LAS METAS DEL PROGRAMA', 'APOYO Y CUMPLIMIENTO DEL 91% AL 95% A LAS METAS DEL PROGRAMA', 'APOYO Y CUMPLIMIENTO POR DEBAJO DEL 80% A LAS METAS DEL PROGRAMA', NULL, 'ATENDER TRIMESTRALMENTE LA OBLIGACIÓN DE CARGAR LA INFORMACIÓN CORRESPONDIENTE A LA FRACCIÓN XXXIII \" CONVENIOS DE COORDINACIÓN, DE CONCERTACIÓN CON EL SECTOR SOCIAL O PRIVADO\" ,DEL ARTÍCULO 70 DE LA LEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA EN EL SISTEMA DE PORTALES DE OBLIGACIONES DE TRANSPARENCIA (SIPOT), DE LOS CONVENIOS FIRMADOS DE LOS PROGRAMAS DE SUBSIDIOS (PROCODES Y PROREST).', '5', '20', 'CUMPLIMIENTO DEL 96% AL 100% A LA CAPTURA DE CONVENIOS EN SIPOT', 'CUMPLIMIENTO DEL 91% AL 95% A LA CAPTURA DE CONVENIOS EN SIPOT', 'CUMPLIMIENTO POR DEBAJO DEL 80% A LA CAPTURA DE CONVENIOS EN SIPOT', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'ACTIVACIÓN DE PROYECTOS Y CUMPLIMIENTO NORMATIVO - POR DEBAJO DEL 80%', 'CUMPLIMIENTO DE AVANCES FÍSICOS Y FINANCIEROS POR DEBAJO DEL 89%', 'SE ATENDIERON LOS REQUERIMIENTOS Y VISITAS DE SUPERVISIÓN POR DEBAJO DEL 89%', 'APOYO Y CUMPLIMIENTO POR DEBAJO DEL 90% A LAS METAS DEL PROGRAMA', 'CUMPLIMIENTO POR DEBAJO DEL 90% A LA CAPTURA DE CONVENIOS EN SIPOT', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
