INSERT INTO `sed_individuales` VALUES (1144, 'GOSC840919', 'LLEVAR A CABO LAS GESTIONES DEL PROCESO DE ADMINISTRACIÓN DE RIESGOS (ARI) PARA LA CONFORMACIÓN DEL GRUPO DE TRABAJO Y EL ANÁLISIS E INTEGRACIÓN DEL PROGRAMA DE TRABAJO (MATRIZ, MAPA Y PTAR).', '8', '20', 'INTEGRAR Y PRESENTAR EN TIEMPO Y FORMA LA MATRIZ, EL MAPA Y EL PROGRAMA DE TRABAJO DE ADMINISTRACIÓN DE RIESGOS, Y SU PRESENTACIÓN EN LAS SESIONES DEL COCODI.', 'INTEGRAR Y PRESENTAR EN DESTIEMPO LA MATRIZ, EL MAPA Y EL PROGRAMA DE TRABAJO DE ADMINISTRACIÓN DE RIESGOS, Y SU PRESENTACIÓN EN LAS SESIONES DEL COCODI.', 'INTEGRAR Y PRESENTAR EN DESTIEMPO E  INADECUADAMENTE LA MATRIZ, EL MAPA Y EL PROGRAMA DE TRABAJO DE ADMINISTRACIÓN DE RIESGOS, Y SU PRESENTACIÓN EN LAS SESIONES DEL COCODI.', NULL, 'ELABORAR LOS REPORTES DE AVANCE TRIMESTRAL DEL PTAR , CARGARLOS EN EL SICOIN Y ELABORAR EL INFORME ANUAL DEL COMPORTAMIENTO DE RIESGOS PARA INFORMARLOS AL OIC.', '8', '20', 'ELABORAR, PRESENTAR Y CARGAR EN EL SICOIN EN TIEMPO Y FORMA LOS REPORTES DE AVANCE CON LA EVIDENCIA DOCUMENTAL CORRESPONDIENTE Y EL INFORME ANUAL.', 'ELABORAR, PRESENTAR Y CARGAR EN EL SICOIN EN DESTIEMPO LOS REPORTES DE AVANCE CON LA EVIDENCIA DOCUMENTAL CORRESPONDIENTE Y EL INFORME ANUAL.', 'ELABORAR, PRESENTAR Y CARGAR EN EL SICOIN EN DESTIEMPO E INADECUADAMENTE LOS REPORTES DE AVANCE CON LA EVIDENCIA DOCUMENTAL CORRESPONDIENTE Y EL INFORME ANUAL.', NULL, 'ELABORAR E INTEGRAR RESPUESTAS EN ATENCIÓN A REQUERIMIENTOS DEL OIC, DE AUDITORIAS DE LA ASF Y DE INFORMES DE DESEMPEÑO DE LA SECRETARIA ANTICORRUPCIÓN Y BUEN GOBIERNO, CON LA EVIDENCIA DOCUMENTAL CORRESPONDIENTE, ASÍ COMO EN LA INTEGRACIÓN DE LA CARPETA DEL COCODI.', '5', '20', 'ELABORAR E INTEGRAR RESPUESTAS EN TIEMPO Y FORMA CON LA EVIDENCIA DOCUMENTAL CORRESPONDIENTE, E INTEGRAR LA CARPETA DEL COCODI.', 'ELABORAR E INTEGRAR RESPUESTAS EN DESTIEMPO CON LA EVIDENCIA DOCUMENTAL CORRESPONDIENTE, E INTEGRAR LA CARPETA DEL COCODI.', 'ELABORAR E INTEGRAR RESPUESTAS EN DESTIEMPO E INADECUADAM