INSERT INTO `sed_individuales` VALUES (806, 'SILC681010', 'SUPERVISAR LA INSTRUMENTACIÓN FINANCIERA DEL 100 % DE LOS PROYECTOS DE PROGRAMAS DE SUBSIDIO AUTORIZADO PARA LA REGIÓN NORESTE Y SIERRA MADRE ORIENTAL', '10', '25', 'Supervisar la instrumentación financiera del 80% de los proyectos de programas de subsidio autorizados para la región Noreste y Sierra Madre Oriental.', 'Supervisar la instrumentación financiera del 60% de los proyectos de programas de subsidio autorizados para la región Noreste y Sierra Madre Oriental.', 'Supervisar la instrumentación financiera del 25% de los proyectos de programas de subsidio autorizados para la región Noreste y Sierra Madre Oriental.', NULL, 'SUPERVISAR LA OPERACIÓN FINANCIERA DE 17 PROGRAMAS OPERATIVOS ANUALES DE ÁREAS NATURALES PROTEGIDAS  EN LA REGIÓN NORESTE Y SIERRA MADRE ORIENTAL', '10', '25', 'Supervisar el 80% de la operación financiera de 17 programas operativos anuales de áreas naturales protegidas en la región Noreste y Sierra Madre Oriental.', 'Supervisar el 60% de la operación financiera de 17 programas operativos anuales de áreas naturales protegidas en la región Noreste y Sierra Madre Oriental.', 'Supervisar el 25% de la operación financiera de 17 programas operativos anuales de áreas naturales protegidas en la región Noreste y Sierra Madre Oriental.', NULL, 'REVISAR, VALORAR Y EMITIR EL 100 % DE LAS OPINIONES TÉCNICAS INGRESADAS EN MATERIA DE IMPACTO AMBIENTAL, CAMBIO DE USO DE SUELO Y VIDA SILVESTRE EN LA REGIÓN NORESTE Y SIERRA MADRE ORIENTAL', '10', '25', 'revisión, valoración y emisión del 80% de las opiniones técnicas ingresadas en materia de impacto ambiental, cambio de uso de suelo y vida silvestre en la Región Noreste y Sierra madre Oriental', 'revisión, valoración y emisión del 60% de las opiniones técnicas ingresadas en materia de impacto ambiental, cambio de uso de suelo y vida silvestre en la Región Noreste y Sierra madre Oriental', 'revisión, valoración y emisión del 25 % de las opiniones técnicas ingresadas en materia de impacto ambiental, cambio de uso de suelo y vida silvestre en la Región Noreste y Sierra madre Oriental80', NULL, 'REVISAR VALORAR Y DESAHOGAR EL 100 % DE LAS SOLICITUDES DE ASESORÍA, REQUERIMIENTOS DE AUTORIZACIONES JURISDICCIONALES, ASÍ COMO LA REPRESENTACIÓN DE LA DIRECCIÓN REGIONAL NORESTE Y SIERRA MADRE ORIENTAL ANTE JUZGADOS Y TRIBUNALES', '10', '25', 'Revisar , valorar y desahogar el 80 % de las solicitudes de asesoría, requerimientos de autorizaciones jurisdiccionales, así como la representación de la Dirección Regional Noreste y Sierra Madre Oriental ante Juzgados y tribunales.', 'Revisar , valorar y desahogar el 60 % de las solicitudes de asesoría, requerimientos de autorizaciones jurisdiccionales, así como la representación de la Dirección Regional Noreste y Sierra Madre Oriental ante Juzgados y tribunales.', 'Revisar , valorar y desahogar el 25 % de las solicitudes de asesoría, requerimientos de autorizaciones jurisdiccionales, así como la representación de la Dirección Regional Noreste y Sierra Madre Oriental ante Juzgados y tribunales.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Supervisar la instrumentación financiera del 50% de los proyectos de programas de subsidio autorizados para la región Noreste y Sierra Madre Oriental.', 'Supervisar el 50% de la operación financiera de 17 programas operativos anuales de áreas naturales protegidas en la región Noreste y Sierra Madre Oriental.', 'revisión, valoración y emisión del 50% de las opiniones técnicas ingresadas en materia de impacto ambiental, cambio de uso de suelo y vida silvestre en la Región Noreste y Sierra madre Oriental', 'Revisar , valorar y desahogar el 50 % de las solicitudes de asesoría, requerimientos de autorizaciones jurisdiccionales, así como la representación de la Dirección Regional Noreste y Sierra Madre Oriental ante Juzgados y tribunales.', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
