INSERT INTO `sed_individuales` VALUES (812, 'HONJ760413', 'Apoyar y dar seguimiento a 4 proyectos en las comunidades y localidades con los beneficiarios de los programas de subsidios, desde el inicio de actividades hasta concluir con el acta de entrega recepción de los trabajos realizados.', '1', '20', '4 proyectos', '3 proyectos', '2 proyectos', NULL, 'Realizar 16 informes de recorridos de vigilancia y en su caso las actas-circunstanciadas correspondientes, por ilícitos ambientales.', '1', '20', '16 recorridos', '14 recorridos', '12recorridos', NULL, 'Realizar 5 informes de reuniones de trabajo con el personal de la reserva de la biosfera, así como de usuarios de los programas de subsidio.', '1', '20', '5 reuniones', '4 reuniones', '3 reuniones', NULL, 'Realizar 4 platicas de educación ambiental y presentar un informe de cada una de ellos.', '1', '20', '4 platicas', '1 platicas', '2 platicas', NULL, 'participar en 4 acciones de manejo integral del fuego que se lleven a cabo en el ANP.', '1', '20', '4 acciones', '3 acciones', '2 acciones', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '1 proyectos', '10 recorridos', '2 reuniones', '3 platicas', '1 accion', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (813, 'AATR811127', 'APOYO EN COORDINARY SUPERVISAR LA EJECUCION DE LOS PROGRAMAS OPERATIVOS ANUALES (POA) Y PROYECTOS ESPECIFICOS DE CONSERVACIÓN Y APROVECHAMENTO DE LOS RECURSOS NATURALES DEL ANP CON BASE EN EL DECRETO Y EL PROGRAMA DE MANEJO', '10', '30', 'IMPLEMENTACIÓN Y SUPERVISIÓN DE LAS ACTIVIDADES DEL POA DEL 80% AL 100%', 'IMPLEMENTACIÓN Y SUPERVISIÓN DE LAS ACTIVIDADES DEL POA DEL 79% AL 70%', 'IMPLEMENTACIÓN Y SUPERVISIÓN DE LAS ACTIVIDADES DEL POA MENOS DEL 50', NULL, 'COORDINAR Y SUPERVISAR EL PROCESO REGISTRO, ANALISIS, Y ELABORACIÓN DE RESPUESTAS A OPINIONES TÉCNICAS EN MATERIA DE IMPACTO AMBIENTAL, ZONA FEDERAL MARITIMO TERRESTRE Y AMBIENTALES COSTEROS, DE INVESTIGACIÓN, Y OTROS QUE PRETENDAN REALIZARSE DENTRO DE LAS ANP, SITIOS RAMSAR Y OTRAS MODALIDADES DE CONSERVACIÓN BAJO LA JURISDICCIÓN DE LA DIRECCIÓN REGIONAL.', '10', '30', 'IMPLEMENTACIÓN Y SUPERVISIÓN DE LAS ACTIVIDADES DEL 90% AL 100%', 'IMPLEMENTACIÓN Y SUPERVISIÓN DE LAS ACTIVIDADES DEL 79% AL 70%', 'IMPLEMENTACIÓN Y SUPERVISIÓN DE LAS ACTIVIDADES MENOS DEL 50%', NULL, 'SUPERVISAR LA INTEGRACIÓN DE LOS EXPEDIENTES DE SUBSIDIOS ACORDE A LA NORMATIVIDAD VIGENTE', '10', '20', 'EXPEDIENTES INTEGRADOS DEL 100% AL 90%', 'EXPEDIENTES INTEGRADOS MENOR AL 90%', 'EXPEDIENTES INTEGRADOS MENOR AL 65%', NULL, 'COORDINAR ACCIONES PARA LA IMPLEMENTACIÓN DE ESTRATEGIAS QUE HAGAN COMPATIBLE CON EL APROVECHAMIENTO, LA CONSERVACIÓN Y LA PROTECCIÓN DE LOS RECURSOS NATURALES DEL ÁREA, ESTRATEGIAS CON PROYECTOS DE DIVERSIFICACIÓN PRODUCTIVA SUSTENTABLE, COMPATIBLES CON LAS ESTRATEGIAS DE MANEJO DEL ANP.', '10', '20', 'IMPLEMENTACIÓN Y SUPERVISIÓN DE LAS ACTIVIDADES 80% AL 100%', 'IMPLEMENTACIÓN Y SUPERVISIÓN DE LAS ACTIVIDADES DEL 79% AL 70%', 'IMPLEMENTACIÓN Y SUPERVISIÓN DE LAS ACTIVIDADES MENOS DEL 50%', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'IMPLEMENTACIÓN Y SUPERVISIÓN DE LAS ACTIVIDADES DEL POA MENOS DEL 70%', 'IMPLEMENTACIÓN Y SUPERVISIÓN DE LAS ACTIVIDADES MENOS DEL 70%', 'EXPEDIENTES INTEGRADOS MENOR AL 75%', 'IMPLEMENTACIÓN Y SUPERVISIÓN DE LAS ACTIVIDADES MENOS DEL 70%', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (814, 'CAHJ920627', 'Dar seguimiento a los compromisos derivados del ejercicio del Presupuesto Fiscal asignado a la Dirección Regional Centro y Eje Neovolcánico, así como a los recursos de los programas de subsidios autorizados, utilizando bases de datos de control presupuestal que reflejen los importes comprometidos.', '10', '20', ' 90 a 100 %', '70 a 89 %', 'Menor al 50%', NULL, 'Elaborar, integrar y ejecutar el Programa Anual de Adquisiciones y Servicios (PAAS) para garantizar que la Dirección Regional Centro y Eje Neovolcánico cuente con los recursos financieros, materiales y servicios generales necesarios para el adecuado funcionamiento de sus áreas, validando la suficiencia presupuestal de los recursos asignados y emplear los bienes muebles e inmuebles conforme a la normatividad aplicable.', '10', '20', ' 90 a 100 %', '70 a 89 %', 'Menor al 50%', NULL, 'Aplicar las disposiciones y políticas relativas a los servicios personales en las Áreas Naturales Protegidas, sirviendo como enlace con las oficinas centrales para informar sobre los movimientos de personal que ocurran en la región, empleando bases de datos que permitan controlar la recepción, clasificación y registro de la documentación que justifique la atención a los servicios personales.', '10', '20', '90 a 100 %', '70 a 89 %', 'Menor al 50%', NULL, 'Coadyuvar en la implementación de mecanismos de control y dar seguimiento a la recuperación del Cobro de Derechos en la Región Centro y Eje Neovolcánico, generando reportes de los sistemas de recaudación de forma mensual, trimestral y anual.', '10', '20', ' 90 a 100 %', '70 a 89 %', 'Menor al 50%', NULL, 'Supervisar y controlar los inventarios de bienes muebles e inmuebles asignados a la Dirección Regional Centro y Eje Neovolcánico, alimentando y vigilando los sistemas oficiales de inventarios con frecuencia mensual, trimestral y anual. Asimismo, elaborar reportes de las altas, bajas o modificaciones que se presenten con los movimientos de dichos bienes.', '10', '20', '90 a 100 %', '70 a 89 %', 'Menor al 50%', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, ' 50 a 69 %', '50 a 69 %', '50 a 69 %', '50 a 69 %', '50 a 69 %', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (815, 'MOGE950405', 'Orientar y dar seguimiento a los prestadores de servicios turísticos en coordinación con la Dirección de Turismo Municipal y/o manejadores de los sitios con PUP sobre la importancia de regularización, objetos de conservación y valores históricos culturales. ', '10', '20', '80-90%', '70-80%', '60-70%', NULL, 'Implementar proyectos o acciones para mejorar el manejo, disminuir impactos en los sitios de uso recreativo, educación ambiental y/o excluir de la actividad turística en sitios no autorizados. ', '10', '20', '80-90%', '70-80%', '60-70%', NULL, 'Realizar operativos en épocas de alta visitación y brigadas de vigilancia comunitaria en coordinación con PROFEPA, Protección Civil, SMA, SEDENA, Guardia Nacional y/o propietarios de los predios. ', '10', '30', '80-90%', '70-80%', '60-70%', NULL, 'Elaborar materiales de difusión para informar al visitante sobre las actividades que pueden realizar en el APFF, y contribuir a la actualización de la información existente en plataformas turísticas de la prestación de servicios. ', '10', '10', '80-90%', '70-80%', '60-70%', NULL, 'Realizar recorridos de vigilancia en coordinación con brigadas comunitarias y PROFEPA en predios que no cuentan con programa de uso público con el fin de identificar la actividad turística sin autorización. ', '10', '20', '80-90%', '70-80%', '60-70%', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'MENOR A 60%', 'MENOR A 60%', 'MENOR A 60%', 'MENOR A 60%', 'MENOR A 60%', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (816, 'CEBE880212', 'DAR SEGUIMIENTO A LA CORRECTA EJECUCIÓN DE LOS PROGRAMAS DE SUBSIDIOS MEDIANTE LA ASESORÍA, VERIFICACIÓN, INTEGRACIÓN Y REVISIÓN DE LOS ESPEDIENTES EN APEGO A LAS REGLAS DE OPERACIÓN Y LINEAMIENTOS ESTABLECIDOS Y CON ELLOS CONTRIBUIR AL CUMPLIMIENTO DE OBJETIVOS Y METAS INSTITUCIONALES', '10', '25', 'AL MENOS EL 70% DE EXPEDIENTES INTEGRADOS ', 'ENTRE EL 41 AL 60%  DE EXPEDIENTES INTEGRADOS ', 'NINGUN EXPEDIENTE INTEGRADO', NULL, 'REVISAR INFORMACIÓN BIOLÓGICA, GEOGRÁFICA Y SOCIAL DISPONIBLE DEL ANP PARA ANALIZAR LAS PROPUESTAS DE LOS PROYECTOS SOLICITADOS Y AUTORIZADOS, COMPATIBLES CON LAS ESTRATEGÍAS DE MANEJO DEL ANP, ALINEADOS A LA NORMATIVIDAD AMBIENTAL VIGENTE.', '10', '25', 'ENTRE 80 A 90% DE LAS PROPUESTAS DE LOS PROYECTOS SOLICITADOS ', 'ENTRE 60 A 79% DE LAS PROPUESTAS DE LOS PROYECTOS SOLICITADOS ', 'MENOS DEL 20 % DE LAS PROPUESTAS DE LOS PROYECTOS SOLICITADOS ', NULL, 'GENERAR INFORMACIÓN BIOLÓGICA Y BASES DE DATOS DE LAS ESPECIES MUESTREADAS, ASÍ COMO PROMOVER LA PARTICIPACIÓN DE COMUNIDADES LOCALES DEL ANP EN PROYECTOS DE MONITOREO NECESARIOS PARA EL MANEJO DE LOS RECURSOS NATURALES EN LA MISMA.', '1', '20', 'AL MENOS 2 INFORMES O BASES DE DATOS DEL ANÁLISIS DE INFORMACIÓN', 'AL MENOS 1 INFORME O BASE DE DATOS DEL ANÁLISIS DE INFORMACIÓN', '1 PROYECTOS O BASES GENERADOS', NULL, 'REALIZAR ACTIVIDADES ADMINISTRATIVAS Y DE LOGÍSTICA, ASÍ COMO DE GESTIÓN DE RECURSOS MATERIALES, HUMANOS, TECNOLÓGICOS, FINANCIEROS Y/O JURÍDICOS QUE SE REQUIERAN, DENTRO DE SU ÁMBITO DE APLICACIÓN, ASEGURANDO EL CUMPLIMIENTO NORMATIVO Y LA CONSECUCIÓN DE LAS ACTIVIDADES Y LA ADECUADA OPERACIÓN DEL ANP.', '1', '30', '4 O MÁS EXPEDIENTES INTEGRADOS ', '2 O MÁS EXPEDIENTES INTEGRADOS ', ' 0 EXPEDIENTES INTEGRADOS ', NULL, NULL, '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'ENTRE EL 5 AL 40%  DE EXPEDIENTES INTEGRADOS', 'MENOS DEL 50 % DE LAS PROPUESTAS DE LOS PROYECTOS SOLICITADOS ', 'NINGUN INFORME O BASE DE DATOS DEL ANÁLISIS DE INFORMACIÓN', '1 EXPEDIENTES INTEGRADOS ', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (887, 'AUAL660214', 'SUPERVISAR EL CONTROL PRESUPUESTAL DE LOS PROGRAMAS DE SUBSIDIOS EJECUTADOS POR LA DIRECCIÓN REGIONAL FRONTERA SUR DE LA CONANP.', '10', '30', '70% DEL CONTROL PRESUPUESTAL SUPERVISADO', '50%  DEL CONTROL PRESUPUESTAL SUPERVISADO', '30%  DEL CONTROL PRESUPUESTAL SUPERVISADO', NULL, 'EJECUTAR MANCOMUNADAMENTE TRANSFERENCIAS A BENEFICIARIOS DE LOS PROGRAMAS DE SUBSIDIOS ASIGNADOS A  LA DIRECCIÓN REGIONAL FRONTERA SUR DE LA CONANP.', '10', '40', '70% TRANSFERENCIAS EJECUTADAS', '50% TRANSFERENCIAS EJECUTADAS', '30% TRANSFERENCIAS EJECUTADAS', NULL, 'SEGUIMIENTO DEL PRESUPUESTO FISCAL DE LA DIRECCIÓN REGIONAL FRONTERA SUR DE LA CONANP.', '10', '10', '70% SEGUIMIENTO DEL PRESUPUESTO FISCAL', '50% SEGUIMIENTO DEL PRESUPUESTO FISCAL', '30% SEGUIMIENTO DEL PRESUPUESTO FISCAL', NULL, 'REVISAR PROCESOS DE PAGO EN EL SISTEMA DE CONTABILIDAD Y PRESUPUESTO(SICOP) CORRESPONDIENTES AL PRESUPUESTO FISCAL PP E16 Y PP U40  DE LA DIRECCIÓN REGIONAL FRONTERA SUR DE LA CONANP.', '10', '10', '70% PROCESOS ASIGNADOS REVISADOS', '50% PROCESOS ASIGNADOS REVISADOS', '30% PROCESOS ASIGNADOS REVISADOS', NULL, 'SUPERVISAR LOS REGISTROS EN EL SISTEMA DE CONTABILIDAD SACG.NET, CORRESPONDIENTES AL PRESUPUESTO FISCAL Y SUBSIDIOS, DE LA DIRECCIÓN REGIONAL FRONTERA SUR DE LA CONANP.', NULL, '10', '70% REGISTROS CONTABLES SUPERVISADOS', '50% REGISTROS CONTABLES SUPERVISADOS', '30% REGISTROS CONTABLES SUPERVISADOS', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '40%  DEL CONTROL PRESUPUESTAL SUPERVISADO', '40% TRANSFERENCIAS EJECUTADAS', '40% SEGUIMIENTO DEL PRESUPUESTO FISCAL', '40% PROCESOS ASIGNADOS REVISADOS', '40% REGISTROS CONTABLES SUPERVISADOS', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
