INSERT INTO `sed_individuales` VALUES (834, 'GOCE560908', 'Gestionar, ejercer y supervisar el correcto desempeño de los recursos, físicos y financieros asignados al Centro Mexicano de la Tortuga, así como dirigir la correcta ejecución, supervisión y reporte de los proyectos de protección, manejo, conocimiento, cultura y gestión programados para el año 2025.', '10', '20', 'Lograr la correcta ejecución y supervisión del 80% de los proyectos establecidos en el Programa de Trabajo Anual 2025. ', 'Lograr la correcta ejecución y supervisión del 60% de los proyectos establecidos en el Programa de Trabajo Anual del año 2025.', 'Lograr la correcta ejecución y supervisión de menos del 50% de los proyectos establecidos en el Programa de trabajo 2024 del Centro Mexicano de la Tortuga.', NULL, 'Dirigir actividades de supervisión en campo de los proyectos y acciones de conservación, uso sustentable y manejo de los recursos naturales de Centro Mexicano de la Tortuga y su área de Influencia.', '10', '20', 'Dirigir actividades de supervisión de campo del 90% de los proyectos relacionados con la conservación, uso sustentable y manejo de los recursos naturales del área de influencia y el Centro Mexicano de la Tortuga. ', 'Dirigir actividades de supervisión de campo del 70% de los proyectos relacionados con la conservación, uso sustentable y manejo de los recursos naturales del área de influencia y el Centro Mexicano de la Tortuga. ', 'Dirigir actividades de supervisión de campo de menos del 50% de los proyectos relacionados con la conservación, uso sustentable y manejo de los recursos naturales del área de influencia y el Centro Mexicano de la Tortuga.', NULL, 'Coordinar la ejecución de proyectos para el desarrollo sustentable del Centro Mexicano de la Tortuga y su área de Influencia e imlementar reuniones y talleres participativos con grupos comunitarios.', '10', '20', 'Coordinar la ejecución del 80% de los proyectos programados.', 'Coordinar la ejecución del 60% de los proyectos programados.', 'Coordinar la ejecución menos del 55% de los proyectos programados.', NULL, 'Gestionar el uso sustentable y la protección de los recursos naturales a través de buenas prácticas, por medio de talleres y reuniones de trabajo con usuarios, visitantes y prestadores de servicios turísticos del Centro Mexicano de la Tortuga y áreas de influencia.', '10', '20', 'Concretar el 80% de las reuniones y talleres programados con los prestadores de servicios turísticos y otras instancias involucradas.', 'Concretar el 60% de las reuniones y talleres programados con los prestadores de servicios turísticos y otras instancias involucradas.', 'Concretar menos del 55% de las reuniones y talleres programados con los prestadores de servicios turísticos y otras instancias involucradas.', NULL, 'Implementar campañas de difusión y capacitación para la conservación de la biodiversidad dirigida a usuarios, visitantes y prestadores de servicios turísticos a través de eventos y campañas al interior del Centro Mexicano de la Tortuga y su área de influencia.', '10', '20', 'Concretar el 80% de las reuniones y talleres programados con usuarios, visitantes, prestadores de servicios turísticos y otras instancias involucradas.', 'Lograr el 60% de las acciones de difusión y capacitación ambiental propuestas con usuarios, visitantes y prestadores de servicios turísticos y otras instancias involucradas.', 'Lograr menos del 55% de las acciones de difusión y capacitación ambiental propuestas.', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Lograr la correcta ejecución supervisión y reporte de menos del 60% de los proyectos establecidos en el Programa de Trabajo Anual del año 2025', 'Dirigir actividades de supervisión de campo de menos del 70% de los proyectos de conservación, uso sustentable y manejo de los recursos naturales programados para el año 2025', 'Coordinar la ejecución de menos del 60% de los proyectos programados.', 'Concretar menos del 60% de las reuniones y talleres programados con los prestadores de servicios turísticos y otras instancias involucradas.', 'Lograr menos del 60% de las acciones de difusión y capacitación ambiental propuestas con usuarios, visitantes y prestadores de servicios turísticos y otras instancias involucradas.', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
