INSERT INTO `sed_individuales` VALUES (847, 'PELG630318', 'EJECUTAR ACCIONES Y ESTRATEGIAS DE PROTECCIÓN, MANEJO, RESTAURACIÓN, INVESTIGACIÓN Y ACTIVIDADES HUMANAS EN EL ANP', '4', '20', 'EJECUCION POR LO MENOS DE 95 % DE ACCIONES CONCLUIDAS', 'EJECUTAR MENOS 85 % DE ACCIONES CONCLUIDAS', 'EJECUTAR MENOS DEL 80 % DE ACCIONES CONCLUIDAS	', NULL, 'DAR SEGUIMIENTO A LA EJECUCIÓN DE LOS PROGRAMAS DE SUBSIDIO MEDIANTE LA ASESORÍA, VERIFICACIÓN, INTEGRACIÓN Y REVISIÓN DE EXPEDIENTES EN APEGO A LAS REGLAS DE OPERACIÓN Y LINEAMIENTOS ESTABLECIDOS Y CON ELLO CONTRIBUIR AL CUMPLIMIENTO DE OBJETIVOS Y METAS INSTITUCIONALES EN LA DIRECCIÓN REGIONAL.	', '2', '20', '90 % DE ASESORIA A LOS GRUPOS  BENEFICIARIOS EM PROGRAMAS DE SUBSIDIOS	', '85 % DE ASESORÍA A LOS GRUPOS  BENEFICIARIOS EN PROGRAMAS DE SUBSIDIOS', '80 % DE ASESORIA A LOS GRUPOS  BENEFICIARIOS EM PROGRAMAS DE SUBSIDIOS	', NULL, 'REVISAR LA INFORMACIÓN BIOLÓGICA, GEOGRÁFICA Y SOCIAL DISPONIBLE DEL ANP PARA ANALIZAR LAS PROPUESTAS DE LOS PROYECTOS SOLICITADOS Y AUTORIZADOS, COMPATIBLES CON LAS ESTRATEGIAS DE MANEJO DEL ANP, ALINEADOS A LA NORMATIVIDAD AMBIENTAL VIGENTE.	\r\n', '8', '20', 'ANALIZAR EL 95% DE LA PROPUESTAS', 'ANALIZAR EL 85% DE LA PROPUESTAS', 'ANALIZAR EL 80% DE LA PROPUESTAS', NULL, 'REALIZAR ACCIONES DE ASESORARIA A LAS DEPENDENCIAS INVOLUCRADAS EN ACCIONES DE PLANEACIÓN, CONSERVACIÓN Y DESARROLLO DEL ÁREA NATURAL PROTEGIDA, ASEGURANDO QUE SE DISEÑEN Y AUTORICEN ACCIONES COMPATIBLES CON LAS ESTRATEGIAS DE MANEJO DEL ANP.', '8', '20', '\"95 % DE ASESORÍA EN LAS ESTRATEGIAS DE MANEJO DE ANP	\"	', '\"85 % DE ASESORÍA EN LAS ESTRATEGIAS DE MANEJO DE ANP	\"	', '75 % DE ASESORÍA EN LAS ESTRATEGIAS DE MANEJO DE ANP	', NULL, 'REALIZAR ACTIVIDADES ADMINISTRATIVAS, DE COORDINACIÓN DE PERSONAL OPERATIVO Y DE LOGÍSTICA, ASÍ COMO DE GESTIÓN DE RECURSOS MATERIALES, HUMANOS, TECNOLÓGICOS, FINANCIEROS Y/O JURÍDICOS QUE SE REQUIERAN, DENTRO DE SU ÁMBITO DE APLICACIÓN , ASEGURANDO EL CUMPLIMIENTO NORMATIVO Y LA CONSECU