INSERT INTO `sed_individuales` VALUES (848, 'CADD780219', '\"SUPERVISAR DURANTE EL EJERCICIO 2025 LAS ACTIVIDADES QUE REALIZAN LOS USUARIOS DENTRO DEL POLÍGONO DE PROTECCIÓN DEL PARQUE NACIONAL COSTA OCCIDENTAL DE ISLA MUJERES PUNTA CANCÚN PUNTA NIZÚC (PNCOIMPCPN) PARA VERIFICAR QUE CUMPLAN CON LAS REGLAS ESTABLECIDAS EN EL PROGRAMA DE MANEJO VIGENTE Y NORMATIVIDAD APLICABLE EN MATERIA DE ÁREAS NATURALES PROTEGIDAS (ANP). \"', '10', '40', 'Satisfactorio: \"\"\"QUE SE LLEVE A CABO EL 100% DE LOS RECORRIDOS DE SUPERVISIÓN DESIGNADOS DURANTE EL EJERCICIO 2025 DENTRO DEL POLÍGONO DE PROTECCIÓN DEL (PNCOIMPCPN) PARA VERIFICAR QUE LOS PRESTADORES DE SERVICIOS TURÍSTICOS, VISITANTES Y USUARIOS EN GENERAL CUMPLAN CON LAS REGLAS ESTABLECIDAS EN EL PROGRAMA DE MANEJO VIGENTE Y NORMATIVIDAD APLICABLE EN MATERIA DE ANPS \"\" \"', 'No Satisfactorio: \"\"\"QUE SE LLEVE A CABO EL 50% DE LOS RECORRIDOS DE SUPERVISIÓN DESIGNADOS DURANTE EL EJERCICIO 2025 DENTRO DEL POLÍGONO DE PROTECCIÓN DEL (PNCOIMPCPN) PARA VERIFICAR QUE LOS PRESTADORES DE SERVICIOS TURÍSTICOS, VISITANTES Y USUARIOS EN GENERAL CUMPLAN CON LAS REGLAS ESTABLECIDAS EN EL PROGRAMA DE MANEJO VIGENTE Y NORMATIVIDAD APLICABLE EN MATERIA DE ANPS \"\" \"', 'Deficiente: \"\"\"QUE SOLO SE LLEVE A CABO EL 30% DE LOS RECORRIDOS DE SUPERVISIÓN DESIGNADOS DURANTE EL EJERCICIO 2025 DENTRO DEL POLÍGONO DE PROTECCIÓN DEL (PNCOIMPCPN) PARA VERIFICAR QUE LOS PRESTADORES DE SERVICIOS TURÍSTICOS, VISITANTES Y USUARIOS EN GENERAL CUMPLAN CON LAS REGLAS ESTABLECIDAS EN EL PROGRAMA DE MANEJO VIGENTE Y NORMATIVIDAD APLICABLE EN MATERIA DE ANPS \"\" \"', NULL, '\"\"\"APOYAR DURANTE EL EJERCICIO 2025 LOS OPERATIVOS DE VIGILANCIA Y CONTROL QUE REALIZA EL PARQUE NACIONAL COSTA OCCIDENTAL DE ISLA MUJERES PUNTA CANCÚN PUNTA NIZÚC (PNCOIMPCPN) DENTRO DEL POLÍGONO DE PROTECCIÓN Y ÁREA DE INFLUENCIA EN COORDINACIÓN CON DEPENDENCIAS Y ENTIDADES GUBERNAMENTALES DE LOS DIFERENTES ÓRDENES DE GOBIERNO PARA DESALENTAR, PREVENIR Y SUSPENDER EN SU CASO LA COMISIÓN DE ILÍCITOS AMBIENTALES DENTRO DEL ANP. \"\" \"', '10', '30', 'Satisfactorio: \"\"\"QUE SE APOYE EL 100% DE LOS OPERATIVOS DE VIGILANCIA Y CONTROL DURANTE EL EJERCICIO 2025 QUE REALIZA EL (PNCOIMPCPN) DENTRO DEL POLÍGONO DE PROTECCIÓN Y ÁREA DE INFLUENCIA EN COORDINACIÓN CON DEPENDENCIAS Y ENTIDADES GUBERNAMENTALES DE LOS DIFERENTES ÓRDENES DE GOBIERNO PARA DESALENTAR, PREVENIR Y SUSPENDER EN SU CASO LA COMISIÓN DE ILÍCITOS AMBIENTALES DENTRO DEL ANP. \"\" \"', 'No Satisfactorio: \"\"\"QUE AL MENOS SE APOYE EL 50% DE LOS OPERATIVOS DE VIGILANCIA Y CONTROL DURANTE EL EJERCICIO 2025 QUE REALIZA EL (PNCOIMPCPN) DENTRO DEL POLÍGONO DE PROTECCIÓN Y ÁREA DE INFLUENCIA EN COORDINACIÓN CON DEPENDENCIAS Y ENTIDADES GUBERNAMENTALES DE LOS DIFERENTES ÓRDENES DE GOBIERNO PARA DESALENTAR, PREVENIR Y SUSPENDER EN SU CASO LA COMISIÓN DE ILÍCITOS AMBIENTALES DENTRO DEL ANP. \"\" \"', 'Deficiente: \"\"\"QUE SOLO SE APOYE EL 30% DE LOS OPERATIVOS DE VIGILANCIA Y CONTROL DURANTE EL EJERCICIO 2023 QUE REALIZA EL (PNCOIMPCPN) DENTRO DEL POLÍGONO DE PROTECCIÓN Y ÁREA DE INFLUENCIA EN COORDINACIÓN CON DEPENDENCIAS Y ENTIDADES GUBERNAMENTALES DE LOS DIFERENTES ÓRDENES DE GOBIERNO PARA DESALENTAR, PREVENIR Y SUSPENDER EN SU CASO LA COMISIÓN DE ILÍCITOS AMBIENTALES DENTRO DEL ANP. \"\" \"', NULL, '\"\"\"LLEVAR A CABO DURANTE EL EJERCICIO 2025 LA SUPERVISIÓN Y MANTENIMIENTO DE LAS BOYAS DE AMARRE DEL PARQUE NACIONAL COSTA OCCIDENTAL DE ISLA MUJERES PUNTA CANCÚN PUNTA NIZÚC PNCOIMPCPN QUE SE UTILIZA PARA LAS EMBARCACIONES QUE REALIZAN ACTIVIDADES TURÍSTICO - RECREATIVAS EN LAS UNIDADES ARRECIFALES AUTORIZADAS EN EL PROGRAMA DE MANEJO. \"\" \"', '10', '10', 'Satisfactorio: \"\"\"QUE SE LLEVE A CABO EL 100% LA SUPERVISIÓN Y MANTENIMIENTO DE LAS BOYAS DE AMARRE DEL PNCOIMPCPN PARA LAS EMBARCACIONES QUE REALIZAN ACTIVIDADES TURÍSTICO - RECREATIVAS EN LAS UNIDADES ARRECIFALES AUTORIZADAS EN EL PROGRAMA DE MANEJO. \"\" \"', 'No Satisfactorio: \"\"\"QUE SE LLEVE A CABO EL 50% LA SUPERVISIÓN Y MANTENIMIENTO DE LAS BOYAS DE AMARRE DEL PNCOIMPCPN PARA LAS EMBARCACIONES QUE REALIZAN ACTIVIDADES TURÍSTICO - RECREATIVAS EN LAS UNIDADES ARRECIFALES AUTORIZADAS EN EL PROGRAMA DE MANEJO. \"\" \"', 'Deficiente: \"\"\"QUE SE LLEVE A CABO EL 30% LA SUPERVISIÓN Y MANTENIMIENTO DE LAS BOYAS DE AMARRE DEL PNCOIMPCPN PARA LAS EMBARCACIONES QUE REALIZAN ACTIVIDADES TURÍSTICO - RECREATIVAS EN LAS UNIDADES ARRECIFALES AUTORIZADAS EN EL PROGRAMA DE MANEJO. \"\" \"', NULL, '\"\"\"VERIFICAR DURANTE EL EJERCICIO 2025 EL ESTADO FÍSICO, BUEN FUNCIONAMIENTO Y OPERACIÓN DE LOS VEHÍCULOS TERRESTRES Y EMBARCACIONES A CARGO DEL PNCOIMPC PARA GARANTIZAR LA OPERACIÓN DEL ANP. \"\" \"\r\n\r\n', '10', '20', 'Satisfactorio: \"\"\"QUE SE LLEVE A CABO EL 100% DE LAS ACCIONES ASIGNADAS PARA LA VERIFICACIÓN DEL ESTADO FÍSICO, BUEN FUNCIONAMIENTO Y OPERACIÓN DE LOS VEHÍCULOS TERRESTRES A CARGO DEL PNCOIMPCPN QUE PARA GARANTIZAR LA OPERACIÓN DEL ANP. \"\" \"', 'No Satisfactorio: \"\"\"QUE SOLO SE LLEVE A CABO EL 50% DE LAS ACCIONES ASIGNADAS PARA LA VERIFICACIÓN DEL ESTADO FÍSICO, BUEN FUNCIONAMIENTO Y OPERACIÓN DE LOS VEHÍCULOS TERRESTRES A CARGO DEL PNCOIMPCPN QUE PARA GARANTIZAR LA OPERACIÓN DEL ANP. \"\" \"', 'Deficiente: \"\"\"QUE ÚNICAMENTE SE LLEVE A CABO EL 30% DE LAS ACCIONES ASIGNADAS PARA LA VERIFICACIÓN DEL ESTADO FÍSICO, BUEN FUNCIONAMIENTO Y OPERACIÓN DE LOS VEHÍCULOS TERRESTRES A CARGO DEL PNCOIMPCPN QUE PARA GARANTIZAR LA OPERACIÓN DEL ANP. \"\" \"', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'No Aprobatorio: \"\"\"QUE SOLO SE LLEVE A CABO EL 40% DE LOS RECORRIDOS DE SUPERVISIÓN DESIGNADOS DURANTE EL EJERCICIO 2025 DENTRO DEL POLÍGONO DE PROTECCIÓN DEL (PNCOIMPCPN) PARA VERIFICAR QUE LOS PRESTADORES DE SERVICIOS TURÍSTICOS, VISITANTES Y USUARIOS EN GENERAL CUMPLAN CON LAS REGLAS ESTABLECIDAS EN EL PROGRAMA DE MANEJO VIGENTE Y NORMATIVIDAD APLICABLE EN MATERIA DE ANPS \"\" \"', 'No Aprobatorio \"\"\"QUE SOLO SE APOYE EL 40% DE LOS OPERATIVOS DE VIGILANCIA Y CONTROL DURANTE EL EJERCICIO 2023 QUE REALIZA EL (PNCOIMPCPN) DENTRO DEL POLÍGONO DE PROTECCIÓN Y ÁREA DE INFLUENCIA EN COORDINACIÓN CON DEPENDENCIAS Y ENTIDADES GUBERNAMENTALES DE LOS DIFERENTES ÓRDENES DE GOBIERNO PARA DESALENTAR, PREVENIR Y SUSPENDER EN SU CASO LA COMISIÓN DE ILÍCITOS AMBIENTALES DENTRO DEL ANP. \"\" \"', 'No Aprobatorio \"\"\"QUE SE LLEVE A CABO EL 40% LA SUPERVISIÓN Y MANTENIMIENTO DE LAS BOYAS DE AMARRE DEL PNCOIMPCPN PARA LAS EMBARCACIONES QUE REALIZAN ACTIVIDADES TURÍSTICO - RECREATIVAS EN LAS UNIDADES ARRECIFALES AUTORIZADAS EN EL PROGRAMA DE MANEJO. \"\" \"', 'No Aprobatorio \"\"\"QUE ÚNICAMENTE SE LLEVE A CABO EL 40% DE LAS ACCIONES ASIGNADAS PARA LA VERIFICACIÓN DEL ESTADO FÍSICO, BUEN FUNCIONAMIENTO Y OPERACIÓN DE LOS VEHÍCULOS TERRESTRES A CARGO DEL PNCOIMPCPN QUE PARA GARANTIZAR LA OPERACIÓN DEL ANP. \"\" \"', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (849, 'VEGE801101', 'Apoyar en los procedimientos administrativos para la adquisición de bienes y servicios, dar seguimiento a las solicitudes de pago de las mismas, así como llevar a cabo el control de los pagos a proveedores', '10', '25', 'Se atiende entre el 85 y 100% de los procedimientos', 'Se atiende entre el 84 y 60% de los procedimientos', 'No se atiende ninguno de los procedimientos', NULL, 'Dar seguimiento a los procesos relacionados a cobro de derechos y POAs administrativos de fuentes externas; así como, al gasto de operación de los programas de subsidios', '10', '25', 'Se atiende entre el 85 y 100% de los procesos ', 'Se atiende entre el 84 y 60% de los procesos', 'No se atiende ninguno de los procesos', NULL, 'Conciliación e integración de expedientes correspondientes a plantillas de vehículos, combustible, reemplazamiento, listas de asistencia, llamadas telefónicas y demás procesos generales administrativos para la operación del ANP', '10', '25', 'Se atiende entre el 85 y 100% de los procesos ', 'Se atiende entre el 84 y 60% de los procesos', 'No se atiende ninguno de los procesos', NULL, 'Atender la aplicación y ejecución de viáticos y pasajes nacionales internacionales, control de recepción, clasificación y registro de la documentación comprobatoria, así como coadyubar con la unidad administrativa regional en el seguimiento de los trámites administrativos generados por los pagos y comprobaciones', '10', '15', 'Se atiende entre el 85 y 100% de los procesos ', 'Se atiende entre el 84 y 60% de los procesos', 'No se atiende ninguno de los procesos', NULL, 'Realizar y/o actualizar inventarios de activos fijos, resguardos, noticias de movimiento, actas; así como, dar seguimiento al programa de destino final\r\n', '10', '10', 'Se atiende entre el 85 y 100% de los procesos ', 'Se atiende entre el 84 y 60% de los procesos', 'No se atiende ninguno de los procesos', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Se atiende menos del 59% de los procedimientos', 'Se atiende menos del 59% de los procesos', 'Se atiende menos del 59% de los procesos', 'Se atiende menos del 59% de los procesos', 'Se atiende menos del 59% de los procesos', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (850, 'GALA560212', 'IMPULSAR LA ELABORACIÓN, EVALUACIÓN O MODIFICACIÓN DE LOS PROGRAMAS DE MANEJO DE LAS ÁREAS NATURALES PROTEGIDAS DE LA REGIÓN OCCIDENTE PARA DOTARLAS DE UN INSTRUMENTO DE PLANEACIÓN Y REGULACIÓN ACORDES CON LA NORMATIVIDAD VIGENTE, PARA UNA ADECUADA OPERACIÓN Y ADMINISTRACIÓN DE LAS MISMAS', '10', '25', 'ATENDER DEL 85 AL 95% DE LOS COMPROMISOS REGIONALES DEL PROGRAMA DE TRABAJO PARA LA FORMULACIÓN, EVALUACIÓN O MODIFICACIÓN DE LOS PROGRAMAS DE MANEJO', 'ATENDER DEL 70 AL 84% DE LOS COMPROMISOS REGIONALES DEL PROGRAMA DE TRABAJO PARA LA FORMULACIÓN, EVALUACIÓN O MODIFICACIÓN DE LOS PROGRAMAS DE MANEJO', 'ATENDER MENOS DEL 49% DE LOS COMPROMISOS REGIONALES DEL PROGRAMA DE TRABAJO PARA LA FORMULACIÓN, EVALUACIÓN O MODIFICACIÓN DE LOS PROGRAMAS DE MANEJO ', NULL, 'ELABORAR Y COORDINAR LA EMISIÓN DE OPINIONES TÉCNICAS DE LAS OBRAS Y ACTIVIDADES QUE SE DESARROLLAN EN LAS ÁREAS NATURALES PROTEGIDAS Y REGIONES PRIORITARIAS PARA LA CONSERVACIÓN DENTRO DE LA JURISDICCIÓN DE LA REGIÓN OCCIDENTE, PARA EL ADECUADO MANEJO DE SUS RECURSOS NATURALES', '10', '15', 'ATENDER DEL 85 AL 95% DE LAS SOLICITUDES DE OPINIÓN TÉCNICA QUE SE RECIBAN EN LA REGIÓN OCCIDENTE', 'ATENDER DEL 70 AL 84% DE LAS SOLICITUDES DE OPINIÓN TÉCNICA QUE SE RECIBAN EN LA REGIÓN OCCIDENTE', 'ATENDER MENOS DEL 49% DE LAS SOLICITUDES DE OPINIÓN TÉCNICA QUE SE RECIBAN EN LA REGIÓN OCCIDENTE', NULL, 'ELABORAR Y COORDINAR LA EMISIÓN DE AUTORIZACIONES Y PERMISOS DE ACTIVIDADES REGULADAS POR LA COMISIÓN NACIONAL Y REGISTRADAS ANTE LA CONAMER PARA EL ADECUADO CONTROL DE LAS ACTIVIDADES DE USO Y DISFRUTE DE LOS RECURSOS NATURALES', '10', '15', 'ATENDER DEL 85 AL 95% DE LAS SOLICITUDES DE AUTORIZACIONES QUE SE RECIBAN EN LA REGIÓN OCCIDENTE ', 'ATENDER DEL 70 AL 84% DE LAS SOLICITUDES DE AUTORIZACIONES QUE SE RECIBAN EN LA REGIÓN OCCIDENTE', 'ATENDER MENOS DEL 49% DE LAS SOLICITUDES DE AUTORIZACIONES QUE SE RECIBEN EN LA REGIÓN OCCIDENTE', NULL, 'PARTICIPAR EN LA COORDINACIÓN DE LOS PROCESOS DE CONSULTAS PÚBLICAS DERIVADAS DE LOS PROCESOS DE CREACIÓN DE NUEVAS ANP O DE LA PUBLICACIÓN DE LOS PROGRAMAS DE MANEJO,  BASE PARA LA GESTIÓN Y GOBERNANZA DE LAS ÁREAS NATURALES PROTEGIDAS DE LA REGIÓN OCCIDENTE', '10', '20', 'PARTICIPAR EN EL 85 AL 95% DE LAS CONSULTAS PÚBLICAS DE LOS DECRETOS DE NUEVAS ANP Y DE AVISOS DE LOS PROGRAMAS DE MANEJO ', 'PARTICIPAR EN EL 70 AL 84%  DE LAS CONSULTAS PÚBLICAS DE LOS DECRETOS DE NUEVAS ANP Y DE AVISOS DE LOS PROGRAMAS DE MANEJO', 'PARTICIPAR EN MENOS DEL 49%  DE LAS CONSULTAS PÚBLICAS DE LOS DECRETOS DE NUEVAS ANP Y DE AVISOS DE LOS PROGRAMAS DE MANEJO', NULL, 'APOYAR LOS PROCESOS DE CREACIÓN DE NUEVAS ÁREAS NATURALES PROTEGIDAS EN CUALQUIERA DE SUS MODALIDADES ', '10', '25', 'ATENDER DEL 85 AL 95% DE LOS PROCESOS DE CREACIÓN DE ANP', 'ATENDER DEL 70 AL 84% DE LOS PROCESOS DE CREACIÓN DE ANP', 'ATENDER MENOS DEL 49% DE LOS PROCESOS DE CREACIÓN DE ANP', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'ATENDER DEL 69% al 50% DE LOS COMPROMISOS REGIONALES DEL PROGRAMA DE TRABAJO PARA LA FORMULACIÓN, EVALUACIÓN O MODIFICACIÓN DE LOS PROGRAMAS DE MANEJO ', 'ATENDER DEL 69% al 50% DE LAS SOLICITUDES DE OPINIÓN TÉCNICA QUE SE RECIBAN EN LA REGIÓN OCCIDENTE', 'ATENDER DEL 69% AL 50% DE LAS SOLICITUDES DE AUTORIZACIONES QUE SE RECIBEN EN LA REGIÓN OCCIDENTE', 'PARTICIPAR EN EL 69% AL 50% DE LAS CONSULTAS PÚBLICAS DE LOS DECRETOS DE NUEVAS ANP Y DE AVISOS DE LOS PROGRAMAS DE MANEJO', 'ATENDER DEL 69% AL 50% DE LOS PROCESOS DE CREACIÓN DE DECRETOS DE ANP', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (851, 'MUBC640922', 'SUPERVISAR QUE LA ADQUISICION DE BIENES Y SERVICIOS REQUERIDOS POR LAS ÁREAS DE LA REGIÓN OCCIDENTE Y PACIFICO CENTRO SE REALICEN EN APEGO A LAS LEYES, REGLAMENTOS Y NORMATIVIDAD VIGENTE ', '10', '20', 'SUPERVISAR QUE LA ADQUISICIÓN DE BIENES Y SERVICIOS REQUERIDOS POR LAS AREAS DE LA REGION OCCIDENTE Y PACIFICO CENTRO SE REALICEN EN APEGO A LAS LEYES, REGLAMENTOS Y NORMATIVIDAD VIGENTE ', 'REALIZAR LA SUPERVISION Y CONTROL DEL 80 AL 70%', 'NO REALIZAR LA SUPERVISIÓN Y CONTROL ', NULL, 'LLEVAR A CABO  LA REVISIÓN DE INVENTARIOS TRIMESTRALES Y ANUALES, PARA REALIZAR INTEGRACIÓN, SEGUIMIENTO Y CUMPLIMIENTO DEL PROGRAMA DE DESTINO FINAL DE BIENES MUEBLES DE LA DIRECCIÓN REGIONAL', '10', '20', 'LLEVAR A CABO DE INVENTARIOS TRIMESTRALES Y ANUALES, ASÍ COMO LA   INTEGRACIÓN DE PROGRAMA DE DESTINO FINAL DE BIENES PARA SU AUTORIZACIÓN Y EJECUCIÓN AL 95% 	', 'LLEVAR A CABO DE INVENTARIOS TRIMESTRALES Y ANUALES, ASÍ COMO LA   INTEGRACIÓN DE PROGRAMA DE DESTINO FINAL DE BIENES PARA SU AUTORIZACIÓN Y EJECUCIÓN AL 90% 	', 'NO LLEVAR A CABO LAS REVISIONES TRIMESTRALES Y ANUALES, ASÍ COMO LA INTEGRACIÓN DEL PROGRAMA DE DESTINO FINAL ', NULL, 'REALIZAR LOS PROCEDIMIENTOS NECESARIOS PARA LA CONTRATACIÓN DE SERVICIOS GENERALES NECESARIOS EN LA DIRECCIÓN REGIONAL OCCIDENTE Y PACIFICO, ASÍ COMO SUS ÁREAS ADSCRITAS MEDIANTE LOS MECANISMOS EN APEGO A LA NORMATIVIDAD VIGENTE EN TIEMPO Y FORMA.', '10', '20', 'LLEVAR A CABO LOS PROCEDIMIENTOS  PARA QUE LAS ÁREAS CUENTEN CON LOS SERVICIOS NECESARIOS PARA LA OPERACIÓN Y ADMINISTRACIÓN EN UN 95%', 'LLEVAR A CABO LOS PROCEDIMIENTOS DE MANERA PARCIAL, PARA QUE LAS ÁREAS CUENTEN CON LOS SERVICIOS NECESARIOS PARA LA OPERACIÓN Y ADMINISTRACIÓN EN UN 90%', 'NO LLEVAR A CABO LOS PROCEDIMIENTOS DE CONTRATACIÓN PARA QUE LAS ÁREAS CUENTEN CON LOS MATERIALES Y SERVICIOS NECESARIOS ', NULL, 'REALIZAR  LA ACTUALIZACIÓN DEL INVENTARIO DE BIENES MUEBLES E INMUEBLES DE LA DIRECCIÓN REGIONAL OCCIDENTE Y PACIFICO CENTRO, ASÍ COMO SUS ÁREAS ADSCRITAS, REALIZANDO REGISTRO DE CONTRATOS Y SOLICITUDES DE AVALUOS NECESARIOS. ', '10', '20', 'REALIZAR AL 95% LA ACTUALIZACIÓN DE LOS INVENTARIOS DE LOS BIENES MUEBLES E INMUEBLES EN LOS PLAZOS ESTABLECIDOS ', 'REALIZAR AL 85% LA ACTUALIZACIÓN DE LOS INVENTARIOS DE LOS BIENES MUEBLES E INMUEBLES ', 'NO REALIZAR LA ACTUALIZACIÓN DE LOS INVENTARIOS DE LOS BIENES MUEBLES E INMUEBLES ', NULL, 'SUPERVISAR QUE LOS PROCEDIMIENTOS EN MATERIA DE RECURSOS HUMANOS SE REALICEN CONFORME LA NORMATIVIDAD VIGENTE EN TIEMPO Y FORMA', '10', '20', 'SUPERVISAR AL 95% LOS PROCEDIMIENTOS EN MATERIA DE RECURSOS HUMANOS', 'SUPERVISAR AL 90% LOS PROCEDIMIENTOS EN MATERIA DE RECURSOS HUMANOS ', 'NO SUPERVISAR LOS PROCEDIMIENTOS EN MATERIA DE RECURSOS HUMANOS ', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'REALIZAR MENOS DEL 70% DE ACTIVIDADES DE SUPERVISIÓN Y CONTROL ', 'REALIZAR MENOS DEL 80% DE LAS ACTIVIDADES PROGRAMADAS PARA REVISIÓN DE INVENTARIOS ANUALES Y TRIMESTRALES ASÍ COMO LA INTEGRACIÓN DEL PROGRAMA DE DESTINO FINAL ', 'LLEVAR A CABO MENOS DEL 90%LOS PROCEDIMIENTOS, PARA QUE LAS ÁREAS CUENTEN CON LOS SERVICIOS NECESARIOS PARA LA OPERACIÓN Y ADMINISTRACIÓN DE LAS ÁREAS ', 'REALIZAR MENOS DEL 85% DE LA ACTUALIZACIÓN DE LOS INVENTARIOS DE BIENES  MUEBLES E INMUEBLES DE LA DIRECCIÓN REGIONAL ', 'REALIZAR MENOS DEL 90% LOS PROCEDIMIENTOS EN MATERIA DE RECURSOS HUMANOS ', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
