INSERT INTO `sed_individuales` VALUES (858, 'NUGE890825', 'Actualizar y ejecutar un programa de difusión y educación ambiental en el ANP.', '2', '25', 'Se actualiza y ejecuta un programa de difusión y educación ambiental en el ANP.', 'Se actualiza pero se ejecutar parcialmente un programa de difusión y educación ambiental en el ANP.', 'No se actualiza ni se ejecutar un programa de difusión y educación ambiental en el ANP.', NULL, 'Atender eventos de difusión y/o sensibilización convocados por distintos actores que colaboran con el ANP.', '10', '25', 'Se atiende entre el 85 y 100% de los eventos convocados.', 'Se atiende entre el 84 y 60% de los eventos convocados.', 'No se atiende ninguno de los eventos convocados.', NULL, 'Diseñar y elaborar materiales de difusión sobre el ANP.', '10', '25', 'Se diseña y elabora entre el 90 a 100% de los materiales de difusión requeridos.', 'Se diseña y elabora el 89 al 75% de los materiales de difusión requeridos.', 'No se diseñan ni elaboran materiales de difusión sobre el ANP.', NULL, 'Apoyar en la ejecución y seguimiento a proyectos aprobados mediante el PROREST y/o PROCODES que le sean asignados.', '10', '10', 'Cumplir con por lo menos un 90% en la ejecución y seguimiento a los proyectos asignados.', 'Cumplir con menos del 85% en la ejecución y seguimiento a los proyectos asignados.', 'Cumplir con menos del 50% en la ejecución y seguimiento a los proyectos asignados.', NULL, 'Dar seguimiento y atención a los procesos de registro de información requerida en el SIRCA.', '10', '15', 'Se atienden entre el 85 y 100% de los procesos de registro de información requerida en el SIRCA.', 'Se atienden entre el 84 y 60% de los procesos de registro de información requerida en el SIRCA.', 'No se atiende ningún proceso de registro de información en el SIRCA.', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Se actualiza pero no se ejecutar un programa de difusión y educación ambiental en el ANP.', 'Se atiende menos del 59% de los eventos convocados.', 'Se diseña y elabora menos del 74% de los materiales de difusión requeridos.', 'Cumplir con menos del 60% en la ejecución y seguimiento a los proyectos asignados.', 'Se atienden menos del 59% de los procesos de registro de información requerida en el SIRCA.', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
