INSERT INTO `sed_individuales` VALUES (862, 'AEHD810926', 'IMPLEMENTAR EL COBRO DE DERECHOS EN EL APFF NEVADO DE TOLUCA, ASI COMO REALIZAR Y EJECUTAR PROGRAMAS DE RESTAURACIÓN Y CONSERVACIOÓN DE LOS ECOSISTEMAS Y SU BIODIVERSIDAD EN LAS APFF NEVADO DE TOLUCA, APFF CIENEGAS DEL LERMA Y PN INSURGENTE MIGUEL HIDALGO Y COSTILLA.', '10', '20', '90% a 100%', '70% a 89%', 'MENOS DEL 50', NULL, 'EMITIR OPINIONES TECNICAS SOBRE LAS DIFERENTES SOLICITUDES DE ACTIVIDADES RELACIONADAS CON EL APFF NEVADO DE TOLUCA, APFF CIENEGAS DEL LERMA Y PN INSURGENTE MIGUEL HIDALGO Y COSTILLA A FIN DE QUE LA AUTORIDAD CORRESPONDIENTE, AUTORICE, CONDICIONE O NIEGUE LA REALIZACION DE DICHAS ACTIVIDADES CON BASE EN LA NORMATIVIDAD VIGENTE Y APLICABLE', '10', '20', '90% a 100%', '70% a 89%', 'MENOS DEL 50', NULL, 'ELABORAR E IMPLEMENTAR EL PROGRAMA OPERATIVO ANUAL (POA) PARA CUMPLIR CON LOS OBJETIVOS DE CREACION DE LAS AREAS NATURALES PROTEGIDAS EN APEGO A SU DECRETO Y PROGRAMAS DE MANEJO, ASI COMO DAR RESPUESTA A INAI, VOLANTES DE GESTION Y DEMAS SOLICITUDES CON RESPECTO A LAS ANP QUE ESTAN EN EL ENCARGO.', '10', '20', '90% a 100%', '70% a 89%', 'MENOS DEL 50', NULL, 'COORDINAR Y DAR SEGUIMIENTO A LA OPERACION DE LOS CONSEJOS ASESORES DEL APFF NEVADO DE TOLUCA Y APFF CIENEGAS DEL LERMA, CON LA FINALIDAD DE ASEGURAR QUE SEA UN ESPACIO DE PARTICIPACION SOCIAL.', '10', '20', '90% a 100%', '70% a 89%', 'MENOS DEL 50', NULL, 'SUPERVISAR Y COORDINAR LA OPERACIÓN, EJECUCION Y SEGUIMIENTO DE TODOS LOS PROYECTOS QUE SE AUTORICEN CONFORME A LAS REGLAS DE OPERACION Y LINEAMIENTOS DE LOS PROGRAMAS DE SUBSIDIO PROCODES Y PRORETS EN LAS APFF NEVADO DE TOLUCA, APFF CIENEGAS DEL LERMA Y PN INSURGENTE MIGUEL HIDALGO Y COSTILLA.', '10', '20', '90% a 100%', '70% a 89%', 'MENOS DE 50', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '50% a 69%', '50% a 69%', '50% a 69%', '50% a 69%', '50% a 69%', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (863, 'EICP761203', 'ELABORAR INFORME MENSUAL CORRESPONDIENTE A LAS ADJUDICACIONES A MIPYMES Y ENVIAR DURANTE LOS PRIMEROS DIEZ DIAS DEL MES SIGUIENTE A AQUEL QUE CORRESPONDA LA INFORMACION\r\n', '7', '15', 'ENVIAR DENTRO DE LOS PRIMEROS 10 DIAS Y EL INFORME ES CORRECTO ', 'ENVIAR DENTRO DE LOS PRIMEROS 10 DIAS Y EL INFORME ES INCORRECTO ', 'ENVIAR DESPUES DE 10 DIAS Y EL INFORME ES INCORRECTO ', NULL, 'ELABORAR INFORME MENSUAL CORRESPONDIENTE A GARANTÍAS Y ENVIAR DURANTE LOS PRIMEROS DIEZ DIAS DEL MES SIGUIENTE A AQUEL QUE CORRESPONDA LA INFORMACION\r\n', '7', '15', 'ENVIAR DENTRO DE LOS PRIMEROS 10 DIAS Y LA INFORMACION ES CORRECTA', 'ENVIAR DENTRO DE LOS PRIMEROS 10 DIAS Y LA INFORMACION ES INCORRECTA ', 'ENVIAR DESPUES DE 10 DIAS Y LA INFORMACION ES INCORRECTA ', NULL, 'FORMALIZAR TRES PROCEDIMIENTOS DE CONTRATACION DE SERVICIOS, DURANTE EL EJERCICIO FISCAL', '1', '30', 'FORMALIZAR TRES PROCEDIMIENTOS DE CONTRATACIÓN DE SERVICIOS DURANTE EL EJERCICIO FISCAL', 'FORMALIZAR DOS PROCEDIMIENTOS DE CONTRATACIÓN DE SERVICIOS DURANTE EL EJERCICIO FISCAL', 'NO FORMALIZAR NINGUN PROCEDIMIENTO DE CONTRATACIÓN DE SERVICIOS DURANTE EL EJERCICIO FISCAL', NULL, 'ELABORAR INFORME TRIMESTRAL CON LA INFORMACION EN MATERIA DE ADQUISICIONES Y ENVIAR DENTRO DE LOS PRIMEROS QUINCE DIAS DEL MES SIGUIENTE A AQUEL QUE CORRESPONDA LA INFORMACION\r\n', '7', '25', 'ENVIAR DENTRO DE LOS PRIMEROS QUINCE DIAS Y LA INFORMACION ES CORRECTA ', 'ENVIAR DENTRO DE LOS PRIMEROS QUINCE DIAS Y LA INFORMACION ES INCORRECTA ', 'ENVIAR DESPUES DE LOS PRIMEROS QUINCE DIAS Y LA INFORMACION ES INCORRECTA ', NULL, 'ELABORAR INFORME MENSUAL DE CONTRATACIONES FORMALIZADAS Y ENVIAR DURANTE LOS PRIMEROS DIEZ DIAS DEL MES SIGUIENTE A AQUEL QUE CORRESPONDA LA INFORMACION\r\n', '7', '15', 'ENVIAR DENTRO DE LOS PRIMEROS 10 DIAS Y EL INFORME ES CORRECTO ', 'ENVIAR DENTRO DE LOS PRIMEROS 10 DIAS Y EL INFORME ES INCORRECTO ', 'ENVIAR DESPUES DE 10 DIAS Y EL INFORME ES INCORRECTO ', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'ENVIAR DESPUES DE 10 DIAS Y EL INFORME ES CORRECTO ', 'ENVIAR DESPUES DE 10 DIAS Y LA INFORMACION ES CORRECTA', 'FORMALIZAR UN PROCEDIMIENTO DE CONTRATACIÓN DE SERVICIOS DURANTE EL EJERCICIO FISCAL', 'ENVIAR DESPUES DE LOS PRIMEROS QUINCE DIAS Y LA INFORMACION ES CORRECTA ', 'ENVIAR DESPUES DE 10 DIAS Y EL INFORME ES CORRECTO ', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (864, 'AABC900525', 'APOYAR A LA DIRECCIÓN DEL ÁREA EN EL SEGUIMIENTO ADMINISTRATIVO Y TÉCNICO DE PROYECTOS DE FINANCIAMIENTO EXTERNO EN EL ANP PARA CONTINUAR CON LAS ACCIONES DE PROTECCIÓN CONSERVACIÓN,  Y MANEJO DE SUS ECOSISTEMAS.', '10', '20', ' 90% a 100% ', '70% a 89% ', 'Menos del 50%', NULL, 'CONCENTRAR LA INFORMACIÓN TRIMESTRAL Y SUS MEDIOS DE VERIFICACIÓN, DEL PROGRAMA OPERATIVO ANUAL,  ASÍ COMO SU CAPTURA EN EL SISTEMA GENERAL DE PROGRAMAS OPERATIVOS ANUALES SGPOA.', '10', '20', '90% a 100% ', '70% a 89% ', 'Menos del 50%', NULL, 'IMPLEMENTAR RECORRIDOS DE VIGILANCIA EN COORDINACIÓN CON PROFEPA, POLICÍA DE MONTAÑA Y SEGURIDAD PUBLICA PARA TRATAR DE INHIBIR Y PREVENIR ILÍCITOS AMBIENTALES EN EL PARQUE NACIONAL IZTACCÍHUATL POPOCATÉPETL Y SU ZONA DE INFLUENCIA.', '10', '20', '90% a 100% ', '70% a 89% ', 'Menos del 50 %', NULL, 'REALIZAR OPINIONES TÉCNICAS Y DENUNCIAS AMBIENTALES POR ACTIVIDADES ILÍCITAS EN EL PARQUE NACIONAL IZTACCÍHUATL POPOCATÉPETL ANTE LAS INSTITUCIONES CORRESPONDIENTES.', '10', '20', '90% a 100% ', '70% a 89% ', 'Menos del 50 %', NULL, 'ATENDER LAS SOLICITUDES DE INFORMACIÓN, EVENTOS Y REUNIONES RELACIONADOS CON EL TEMA DE VIGILANCIA PARA LA ADECUADA OPERACIÓN Y EL CUMPLIMIENTO DEL PROGRAMA DE MANEJO Y NORMATIVIDAD APLICABLE EN EL ANP.', '10', '20', '90% a 100% ', '70% a 89% ', 'Menos del 50 %', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '50% a 69%', '50% a 69%', '50% a 69%', '50% a 69%', '50% a 69%', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (865, 'ROAI790404', 'Elaboración y Control de Listas de Asistencial del personal que labora en la Oficina de la Dirección Regional Occidente y Pacifico Centro, Consolidación de formatos de control de listas de asistencia e incidencias de áreas adscritas a la Dirección Regional Occidente y Pacífico Centro, envío de solicitudes ', '2', '20', 'Archivo de registro de listas de asistencia firmadas con incidencias identificadas al 95%, enviar las licencias médicas y formatos de vacaciones a tiempo.  ', 'Archivo de registro de listas de asistencia firmadas y con incidencias identificadas al 85 %, enviar las licencias médicas y solicitudes de vacaciones en fechas posteriores', 'Archivo de registro de lista de asistencia firmadas con incidencias al 60%, no enviar las licencias y solicitudes de vacaciones y días económicos a oficinas Centrales ', NULL, 'Dar seguimiento al programa de capacitación, mediante el  Reenvió de  correos electrónicos de capacitación, a cada uno de los trabajadores que labora en la Dirección Regional Occidente y Pacifico Centro, para que se inscriban algunos de los cursos que ofrecen algunas Instituciones y así puedan cumplir con sus 40 horas de capacitación, así mismo orientar al personal a quien deben de enviar sus constancias  de capacitación y de que las deben de registradas en el Sistema de Evaluación y desempeño para que queden registradas en el sistema . ', '2', '20', 'Reenviar los correos electrónicos de capacitación en tiempo al personal que labora en la Dirección Regional Occidente, para que verifiquen que curso pueden tomar, las fechas de inicio y termino, y cumplan con sus 40 horas de capacitación ', 'Reenviar los correos electrónicos fuera de tiempo en donde las fechas de los cursos haya paso y el personal no tenga opciones para capacitarse y no cumplan con 40 horas de capacitación. ', 'No atender los correos electrónicos entiempo del personal que este solicitando apoyo para ingresar alguna de las plataformas para registrarse algun curso, para su cumplimiento de las 40 horas de capacitación', NULL, 'Recepción y entrega de documentos como Constancias de Nombramiento, constancias de servicio activo y altas al ISSSTE, del personal que elabora en la Dirección Regional Occidente y Pacifico Centro, apoyo en la aplicación evaluaciones en los concursos de plazas que se están concursando y envió por correo electrónico y en físico de la documentación, control de los minutarios de oficios entrega de números de oficios y archivar acuses de recibido.  ', '2', '20', 'Entrega de documentación a interesados para firmar y envío a Oficinas Centrales con una antigüedad no mayor a 15 días, enviar por correo electrónico la documentación de los participantes en el mismo día que se presentan a realizar sus evaluaciones.', 'Entrega de documentación a los interesados para firmar y envío a Oficinas Centrales con una antigüedad no mayor a 10 días, enviar la documentación de los participantes dos días después de su participación.', 'Entrega de documentación a los interesados para firmar y envío a Oficinas Centrales con Una antigüedad mayor a 10 días, enviar la documentación de los participantes 3 días después de su participación.', NULL, 'Envío de  cedulas de metas y evaluación de desempeño del personal operativo niveles 5 al 11, y enlaces nivel de P12  a hasta nivel mandos medios, envío de cedulas  del empleado del mes, por semestres,  solicitudes de apoyo de lentes, envió de formatos de días económicos, solicitud de vacaciones ,  formatos del seguro de vida y designación de beneficiarios, envío de propuestas de premio de productividad, trimestrales y de puntualidad y asistencia,   acuses de la declaración patrimonial de modificación 2024, Elaboración y envío de formatos del padrón de  día del niño, día de la madre, día del padre y día de reyes, entrega de vales de dispensa o tarjetas de despensa por obsequio y festejo de fin de año, y vales por medidas de fin de año, enviar acuses de recibido a Oficinas Centrales ', '2', '20', 'Enviar las solicitudes del personal relacionadas al área a cargo, en las fechas establecidas o antes del vencimiento.', 'Enviar las solicitudes del personal relacionada al área a cargo, 2 días hábiles después de fecha establecida.', 'Tardar más de 5 días hábiles después de la fecha establecida.', NULL, 'Apoyo en la aplicación de evaluaciones gerenciales y de habilidades, de las personas   que están concursando alguna plaza para CONANP, así mismo recepción, revisión e integración de documentos relacionados con altas y promociones de personal en la Dirección Regional Occidente y Pacifico Centro, para su envío a Oficinas Centrales para el trámite correspondiente, así mismo envío de constancia de no adeudo con documentación soporte del personal que causo baja. y realizar el cálculo del 2% sobre nómina de los estados de Jalisco, Nayarit ', '2', '20', 'Integración de expediente y envío a Oficinas Centrales dentro de los tiempos establecidos para el alta de personal correspondiente.', 'Enviar expedientes fuera de tiempo', 'no enviar los expedientes vía correo electrónico en físico, no realizar los calculoos del 2% sobre nómina  y no enviar la información.', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'No elaborar las listas de asistencia para que el personal registre entreda y salida de sus labores en la Oficina ', 'No reenviar correo electrónico de capacitación, con los cursos disponibles al personal de la Dirección Regional Occidente y Pacifico Centro. ', 'No recbar las firmas de los y las interesadas en las constancias de nombramiento, y no enviar los expedientes de los participantes en tiempo vía correo electrónico y en físico a Oficinas Centrales. ', 'No enviar las documentación del personal de la Dirección Regional Occidente y Pacifico Centro  a Oficinas Centrales ', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (866, 'ROPL700318', ' Dominar el uso de plataformas digitales y programas de computo básicos para la gestión de datos y la comunicación interna. El trabajador debe dominar el uso de plataformas digitales y programas de computo básicos para la gestión de datos del ANP, la comunicación interna con el equipo de trabajo y la atención al público.', '10', '20', 'Entre 60% y 80% de las tareas se realizan a través de plataformas digitales.', 'Entre 40% y 60% de las tareas se realizan a través de plataformas digitales.', 'Menos del 20% de las tareas se realizan a través de plataformas digitales.', NULL, 'Participar activamente en la ejecución de proyectos de conservación, monitoreo, restauración y educación ambiental, incluyendo la planificación, la ejecución, el seguimiento y la evaluación de las actividades.', '1', '20', 'Participa en 3-5 proyectos, incluyendo la toma de decisiones y la coordinación de equipos de trabajo', 'Participa en 2-3 proyectos, incluyendo la toma de decisiones y la coordinación de equipos de trabajo', 'Participa en menos de 1 proyecto de manera parcial o indirecta.', NULL, 'Implementar prácticas de mantenimiento preventivo y uso eficiente de recursos, incluyendo la realización de inspecciones regulares de las embarcaciones, equipos de navegación, remolques y vehículos, así como en el mantenimiento básico a estaciones de campo, señalética, la optimización del consumo de combustible, agua y energía en las estaciones de campo, y la implementación de programas de reciclaje.', '10', '20', 'Cumplimiento  entre 80% y 90% de las acciones, siendo este el impulsor de las acciones. ', 'Cumplimiento entre 50% y 70%,, siendo este el impulsor de las acciones. ', 'Cumplimiento menor al 30%,  participando incipientemente en estas actividades.', NULL, 'Fortalecer las acciones de supervisión del ANP a través de recorridos terrestres con mayor frecuencia, la vigilancia del turismo, el fomento del uso de brazalete y el cumplimiento del programa de manejo del ANP.', '2', '20', 'Participa en  6 o más recorridos terrestres al mes y los registra en bitácora digital', 'Participa en 3-5 recorridos terrestres al mes y los registra en bitácora digital', 'Participa en menos de 2 recorridos terrestres al mes pero no lo registra en bitácora digital', NULL, 'Fortalecer las acciones de supervisión del ANP a través de recorridos marinos con mayor frecuencia, la vigilancia del turismo, el fomento del uso de brazalete y el cumplimiento del programa de manejo del ANP.', '1', '20', 'Participa 5 o más recorridos marinos al mes y los registra en bitácora digital', 'Participa en 3-4 recorridos marinos al mes y los registra en bitácora digital', 'Participa en menos de 2 recorridos marinos al mes pero no lo registra en bitácora digital', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Entre 20% y 40% de las tareas se realizan a través de plataformas digitales.', 'Participa en 1-2 proyectos de manera parcial o indirecta.', 'Cumplimiento entre 30% al 50%, participando de manera indirecta en las acciones.', 'Participa en  2-3 recorridos terrestres al mes pero no lo registra en bitácora digital', 'Participa en  2-3 recorridos marinos al mes pero no lo registra en bitácora digital', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (867, 'BEMG751206', 'Coordinar las actividades del Programa de Educación Ambiental para la Conservación en el Parque Nacional Iztaccíhuatl Popocatépetl, alineando a la Estrategia de la Región Centro y Eje Neovolcánico.', '10', '20', '90% a 100%', '70% a 89%', 'menos de 50%', NULL, 'Coadyuvar con la Dirección del Parque Nacional Iztaccíhuatl Popocatépetl en proceso de la actualización del Programa de Manejo', '10', '20', '90% a 100%', '70% a 89%', 'menos de 50%', NULL, 'Participar en la evaluación periódica del desempeño del personal operativo del ANP, realizando las recomendaciones pertinentes para una mayor eficiencia de su desempeño.', '10', '20', '90% a 100%', '70% a 89%', 'menos de 50%', NULL, 'Coordinar las acciones de participación social de los distintos órganos del Consejo Asesor.', '10', '20', '90% a 100%', '70% a 89%', 'menos de 50%', NULL, 'Supervisar las actividades turísticas recreativas del Parque Nacional Iztaccíhuatl Popocatépetl.', '10', '20', '90% a 100%', '70% a 89%', 'menos de 50%', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '50% a 69%', '50% a 69%', '50% a 69%', '50% a  69%', '50% a 69%', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (873, 'MAMC830602', 'ACTUALIZAR 13 MÓDULOS DEL SISTEMA DE INFORMACIÓN DEL PROCODES (SISP) DE ACUERDO A LOS CAMBIOS EN LAS REGLAS DE OPERACIÓN Y LINEAMIENTOS INTERNOS DEL PROCODES ASÍ COMO LOS MÓDULOS DE LAS CONSULTAS PARA LOS REPORTES MENSUALES A LAS DIFERENTES INSTANCIAS (INMUJERES, La Secretaría de Anticorrupción y Buen Gobierno, SEMARNAT, ETC.)\r\n1. REGISTRO DE SOLICITUDES, 2.- RECEPCIÓN DE SOLICITUDES, 3.- ASIGNACIÓN DE RECURSOS POR ANP, 4.- EVALUACIÓN DE SO LICITUDES, 5.- AUTORIZACIÓN DE SOLICITUDES, 6.- GENERACIÓN DEL ACTA DE DICTAMEN TÉCNICO Y ECONÓMICO, 7.- REGISTRO DEL PADRÓN DE LAS PERSONAS BENEFICIARIAS, 8.- ASIGNACIÓN DE RECURSO POR CONCEPTO DE LAS BRIGADAS DE CONTINGENCIA AMBIENTAL, 9.- REGISTRO DE LOS ANEXOS RO Y LI, 10.- RESGUARDO DE DOCUMENTOS, 11.- REGISTRO DEL AVANCE MENSUAL, 12.-  DESCARGA DE REPORTES Y 13.- ACTUALIZACIÓN DEL ANEXO PARA LAS VISITAS DE SUPERVISIÓN DEL PROCODES.', '1', '30', '13 módulos', '10 módulos', '4 módulos', NULL, 'GENERAR MENSUALMENTE EL LAYOUT DEL PADRÓN DE BENEFICIARIOS DEL PROCODES DE ACUERDO A LAS ESPECIFICACIONES DE CADA DEPENDENCIA QUE LO SOLICITA:\r\n\r\n1.- PARA INTEGRACIÓN AL PROGRAMA ESPECIAL CONCURRENTE (PEC) QUE EJECUTA LA SECRETARÍA DE AGRICULTURA Y DESARROLLO RURAL (SADER). (PERIODO MAYO - DICIEMBRE)\r\n2.- PARA VALIDAR EL RFC EN LA PÁGINA DEL SAT. (PERIODO MAYO - DICIEMBRE)', '1', '20', '16 layouts', '13 layouts', '7 layouts', NULL, 'GENERAR MÓDULO PARA LA AUTOMATIZACIÓN DEL LAYOUT DEL PADRÓN DE BENEFICIARIOS DEL PROCODES DE ACUERDO A LAS ESPECIFICACIONES DE CADA DEPENDENCIA QUE LO SOLICITA. ESTE MÓDULO INCLUIRÁ LA GENERACIÓN DE TRES LAYOUTS:\r\n\r\n1.- PARA LA INTEGRACIÓN AL SISTEMA INTEGRAL DE INFORMACIÓN DE PADRONES DE PROGRAMAS GUBERNAMENTALES (SIIPP-G) QUE EJECUTA LA SECRETARÍA DE ANTICORRUPCIÓN Y BUEN GOBIERNO.\r\n\r\n2.- PARA LA INTEGRACIÓN AL PADRÓN ÚNICO DE BENEFICIARIOS (PUB), EL CUAL ES SOLICITADO POR LA SECRETARÍA DE BIENESTAR.\r\n\r\n3.- PARA LA VALIDACIÓN DE LA CURP DE LAS PERSONAS BENEFICIARIAS, EL CUAL SERÁ ENVIADO A LA SEGOB.', '1', '20', '3  layouts', '2 layouts', '0 layouts', NULL, 'REALIZAR 2 RESPALDOS POR MES DE LA BASE DE DATOS DEL PROCODES PARA PRESERVACIÓN DE LA INFORMACIÓN.', '1', '15', '24 respaldos', '21 respaldos', '15 respaldos', NULL, 'GENERAR UN MÓDULO DE REPORTES HISTÓRICOS DEL PROCODES PARA EL PERÍODO 2017-2024. ESTE MÓDULO INCLUIRÁ TRES REPORTES DESCARGABLES EN FORMATO EXCEL, CON EL FIN DE FACILITAR LA CONSULTA Y ANÁLISIS DE LA INFORMACIÓN RELEVANTE. LOS REPORTES SERÁN: (SOLICITUDES REGISTRADAS, SOLICITUDES AUTORIZADAS Y PADRÓN DE PERSONAS BENEFICIARIAS).', '1', '15', '3 reportes', '2 reportes', '0 reportes', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '7 módulos', '10 layouts', '1 layouts', '18 respaldos', '1 reportes', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (868, 'VAMJ820201', 'Número de propuestas generadas para ADVC', '1', '25', 'Se generan 3 propuestas para ADVC', 'Se generan 3 propuestas', 'No se generan propuestas', NULL, 'Representación de las iniciativas comerciales de productos, apoyo a cooperativas a integrar sus productos a tienda UNAM, ferias, festivales, etc', '1', '25', '2 iniciativas logran distribuir sus productos, 2 reuniones en acompañamiento en las Redes de emprendimiento y negocios inclusivos', '2 iniciativas logran distribuir sus productos', 'Ninguna iniciativa logra distribuir sus productos', NULL, 'Integrar y dar seguimiento a proyectos de los programas de subsidio que opera la CONANP, a travès de la REBITRI', '1', '25', 'Se logra la integración del 100% de los expedientes de los programas de subsidio que se ejecuten de acuerdo a los lineamientos y RO de cada uno de los programas', 'No se logra la integración del 100% de los expedientes de los programas de subsidio que se ejecuten de acuerdo a los lineamientos y RO de cada uno de los programas', 'Se incumple con los sistemas de resguardo e integración de expedientes de algunos programas', NULL, 'Formar un grupo de especialistas para documentar productos necesarios para las estrategias de manejo de las ADVC\'s en proceso de creación', '1', '25', 'Se conforman 2 grupos de especialistas y acudenal levantamiento de información en las comunidades', 'Se conforman 2 grupos de especialistas', 'No se conforma ningún grupo de especialistas', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Se generan 2 propuestas', '1 iniciativa logra distribuir sus productos', 'Se logra la integración del 50% de los expedientes de los programas de subsidio que se ejecuten de acuerdo a los lineamientos y RO de cada uno de los programas', 'Se conforma 1 grupo de especialistas', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (869, 'MOHI951105', 'Supervisar el registro contable a nivel central y regional de conformidad con la Ley de Contabilidad Gubernamental y demás leyes aplicables.', '2', '20', 'Que los registros contables y la Información Financiera cumplan con las actualizaciones emitidas por la CONAC.', 'Que la información financiera y registros contables cumplan parcialmente con las actualizaciones emitidas por la CONAC.', 'Que la información financiera no cumpla, ni respete lo emitido por la CONAC.', NULL, 'Analizar y Verificar los resultados obtenidos mensualmente del proceso Contable-Presupuestal de la CONANP, para la emisión de los Estados Financieros.', '2', '20', 'la información contable y presupuestal se verifica mensualmente, y es confiable para la toma de decisiones.', 'La información contable y presupuestal se verifica trimestralmente, y es confiable para la toma de decisiones.', 'La información contable y presupuestal no se verifica, y no es confiable para la toma de decisiones.', NULL, 'Llevar a cabo programas de conciliación y depuración de cuentas contables y conciliaciones con las diferentes áreas de la CONANP.', '7', '20', 'Se realiza la depuración y análisis de las cuentas, así como la conciliación de forma mensual.', 'Se realiza la depuración y análisis de las cuentas, asi como la conciliación de forma trimestral.', 'Que la depuración y análisis de las cuentas, así como las conciliación no se lleve acabo.', NULL, 'Realizar y Revisar pólizas extra-presupuestales en el SICOP para la emisión de la cuenta Pública.', '8', '20', 'Llevar a cabo cada mes la captura de las Pólizas para SICOP conforme a la documentación recibida, así como la revisión y depuración de cuentas contables.', 'Llevar a cabo cada dos meses la captura de las Pólizas para SICOP conforme a la documentación recibida, así como la revisión y depuración de cuentas contables.', 'Llevar a cabo anualmente la captura de las Pólizas para SICOP conforme a la documentación recibida, así como la revisión y depuración de cuentas contables.', NULL, 'Identificar y Evaluar los riesgos (PTAR) de la Dirección de Área Financiera.', '2', '20', 'Realizar la evaluación de riesgo (PTAR) considerando el 100% de los controles.', 'Realizar la evaluación de riesgo (PTAR) considerando el 80% de los controles.', 'Realizar la evaluación de riesgo (PTAR) no considerando los controles.', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Que la información financiera y registros contables no sé encuentren actualizados.', 'La información contable y presupuestal se verifica anualmente, y es confiable para la toma de decisiones.', 'Se realiza la depuración y análisis de las cuentas, asi como la conciliación de forma anual', 'Llevar a cabo cada semestralmente la captura de las Pólizas para SICOP conforme a la documentación recibida, así como la revisión y depuración de cuentas contables.', 'Realizar la evaluación de riesgo (PTAR) considerando el 50% de los controles.', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (870, 'LEDR890615', 'REGISTRAR Y RECOPILAR INFORMACIÓN BIOLÓGICA DISPONIBLE PARA LA IMPLEMENTACIÓN DE PROYECTOS AUTORIZADOS COMPATIBLES CON LA PLANEACIÓN ESTRATÉGICA Y LA NORMATIVIDAD VIGENTE EN EL ANP.', '2', '15', 'Cumplir con al menos el 90% de las actividades asignadas.', 'Cumplir con menos del 85% de las actividades asignadas.', 'Cumplir con menos del 50% de las actividades asignadas.', NULL, 'Apoyar y dar seguimiento a la implementación de estrategias de conservación y aprovechamiento sostenible de los recursos naturales del ANP; así como, en la operatividad de proyectos de diversificación productiva.', '10', '25', 'Se atiende entre el 85 y 100% de las actividades.', 'Se atiende entre el 84 y 60% de las actividades.', 'No se atiende ninguna de las actividades.', NULL, 'APOYAR EN LA EJECUCIÓN DE EVENTOS DE EDUCACIÓN AMBIENTAL ENFOCADAS EN LA CONSERVACIÓN DE LOS ECOSISTEMAS, SU CONOCIMIENTO Y EL APROVECHAMIENTO SUSTENTABLE DE LOS RECURSOS NATURALES EN EL ANP.', '10', '15', 'Se atiende entre el 85 y 100% de los eventos.', 'Se atiende entre el 84 y 60% de los eventos.', 'No se atiende ninguno de los eventos.', NULL, 'APOYAR EN LA EJECUCIÓN Y SEGUIMIENTO DE PROYECTOS Y PROCESOS DE RESTAURACIÓN ECOLÓGICA, MONITOREO BIOLÓGICO, INCENDIOS Y SANIDAD FORESTAL; ASÍ COMO, EN LA EJECUCIÓN DEL PROGRAMA DE MANEJO DEL FUEGO EN EL ANP.', '10', '25', 'Atender por lo menos un 90% de los proyectos y procesos asignados.', 'Atender menos del 85% de los proyectos y procesos asignados.', 'Atender menos del 50% de los proyectos y procesos asignados.', NULL, 'APOYAR CON LA ELABORACIÓN Y/O INTEGRACIÓN DE INFORMACIÓN REQUERIDA SOBRE DIVERSOS TEMAS COMPETENCIA DEL ANP; ASÍ COMO, EN EL SEGUIMIENTO A LA CONTRALORÍA SOCIAL DE PROYECTOS PROCODES Y PROREST.', '10', '20', 'Se atienden entre el 85 y 100% de los requerimientos.', 'Se atienden entre el 84 y 60% de los requerimientos.', 'No se atiende ningún requerimiento.', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Cumplir con menos del 60% de las actividades asignadas.', 'Se atiende menos del 59% de las actividades.', 'Se atiende menos del 59% de los eventos.', 'Atender menos del 60% de los proyectos y procesos asignados.', 'Se atienden menos del 59% de los requerimientos.', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (871, 'AOMI821230', 'Administrar, manejar y ejecutar las acciones para conservar los ecosistemas y su biodiversidad, y permitir la continuidad de los procesos biológicos y ecológicos el Área de Protección de Flora y Fauna Islas del Golfo de California y Santuario Playa Ceuta, conforme a los objetivos y lineamientos establecidos en su decreto  o bien su programa de manejo.', '10', '20', 'Se cumplió el 90-76% de las metas de establecidas en el Programa Operativo Anual 2025 del  Área de Protección de Flora y Fauna Islas del Golfo de California y Santuario Playa Ceuta', 'Se cumplió el 75-60% de las metas de establecidas en el Programa Operativo Anual 2025 del  Área de Protección de Flora y Fauna Islas del Golfo de California y Santuario Playa Ceuta', 'Se cumplió el 49-0% de las metas de establecidas en el Programa Operativo Anual 2025 ddel  Área de Protección de Flora y Fauna Islas del Golfo de California y Santuario Playa Ceuta', NULL, 'Coordinar y fortalecer la operación del Área de Protección de Flora y Fauna Islas del Golfo de California (Sinaloa) y Santuario Playa Ceuta en materia de contingencias ambientales, permisos y autorizaciones, opiniones técnicas y adquisición de bienes nacionales (terrenos nacionales y zona federal marítimo terrestre).', '10', '20', 'Se atendió igual o mayor al 90% de las solicitudes recibidas para emitir permisos, autorizaciones, opiniones técnicas y adquisición de bienes nacionales en el  Area de Protección de Flora y Fauna Islas del Golfo de California (Sinaloa) y Santuario Playa Ceuta.', 'Se atendió del 70 al 89% de las solicitudes recibidas para emitir permisos, autorizaciones, opiniones técnicas y adquisición de bienes nacionales en el Area de Protección de Flora y Fauna Islas del Golfo de California (Sinaloa) y Santuario Playa Ceuta.', 'Se atendió menos del 60% de las solicitudes recibidas para emitir permisos, autorizaciones, opiniones técnicas y adquisición de bienes nacionales en el Area de Protección de Flora y Fauna Islas del Golfo de California (Sinaloa) y Santuario Playa Ceuta.', NULL, 'Coordinar la ejecución y seguimiento de los programas de subsidio en 2 Áreas Naturales Protegidas competencia de la Federación, de acuerdo a la normatividad vigente de cada programa.', '10', '20', 'Se coordinó la ejecución y seguimiento  del 90% o mas de las acciones aprobadas con los programas de subsidio a cargo de la Comisión Nacional en 2 Áreas Naturales Protegidas competencia de la Federación, de acuerdo a la normatividad vigente de cada programa.', 'Se coordinó la ejecución y seguimiento  del 85 al 70% de las acciones aprobadas con los programas de subsidio en 2 Áreas Naturales Protegidas competencia de la Federación, de acuerdo a la normatividad vigente de cada programa.', 'Se coordinó la ejecución y seguimiento  del 49 al 0% de las acciones aprobadas con los programas de subsidio en 2 Áreas Naturales Protegidas competencia de la Federación, de acuerdo a la normatividad vigente de cada programa', NULL, 'Coordinar el fortalecimiento de la participación social en las acciones de conservación y aprovechamiento sustentable en el Área de Protección de Flora y Fauna Islas del Golfo de California (Sinaloa) y El Santuario Playa Ceuta.', '10', '20', ' Se da seguimiento al 90-76% de las acciones derivadas de los Consejos Asesores del  Área de Protección de Flora y Fauna Islas del Golfo de California y Santuario Playa Ceuta.', 'Se da seguimiento al 75- 61% de las acciones derivadas de los Consejos Asesores del  Área de Protección de Flora y Fauna Islas del Golfo de California y Santuario Playa Ceuta.', 'Se da seguimiento al 49-0% de las acciones derivadas de los Consejos Asesores del  Área de Protección de Flora y Fauna Islas del Golfo de California y Santuario Playa Ceuta.', NULL, 'Coordinar y dirigir la participación institucional de la Comisión Nacional con los 3 órdenes de gobierno y las dependencias y entidades de la Administración Pública Federal en las diferentes