INSERT INTO `sed_individuales` VALUES (872, 'SAAD791221', 'REALIZAR RECORRIDOS MARINOS Y TERRESTRES DE SUPERVISIÓN Y VIGILANCIA EN EL ANP EN TEMA DE TURISMO', '10', '25', 'CUMPLIR  DEL 80 AL 100% DE LAS ACTIVIDADES', 'CUMPLIR  CON EL  70 AL 80% DE LAS ACTIVIDADES	', 'CUMPLIR CON MENOS DEL 50% DE LAS ACTIVIDADES', NULL, 'REALIZAR RECORRIDOS MARINOS Y TERRESTRES DE SUPERVISIÓN Y VIGILANCIA EN EL ANP EN TEMA DE PESCA', '10', '25', 'REALIZAR DEL 80 AL 100% DE LAS ACTIVIDADES DEL PROGRAMA DE MANEJO', 'REALIZAR DEL 70 AL 80% DE LAS ACTIVIDADES ', 'REALIZAR CON MENOS DEL 50% DE LAS ACTIVIDADES', NULL, 'APOYAR A LOS DEPARTAMENTOS DE INVESTIGACION Y DIFUSION EN ACTIVIDADES DE CAMPO ASI COMO EN OTRAS ACTIVIDADES SOLICITADAS', '10', '25', 'REALIZAR DEL 100 AL 80% DE LAS ACTIVIDADES DE LA ESTRATEGIA PARA EL FORTALECIMIENTO LA APLICACIÓN DE LA LFD', 'REALIZAR DEL 70 AL 80% DE LAS ACTIVIDADES ', 'REALIZAR CON MENOS DEL 50% DE LAS ACTIVIDADES DE LA ESTRATEGIA PARA EL FORTALECIMIENTO LA APLICACIÓN DE LA LFD', NULL, 'OPERAR Y ADMINISTRAR EFICAZMENTE EL EQUIPO Y RECURSOS DEL ANP PARA EL DESARROLLO DE LAS ACTIVIDADES DE BOYADO', '10', '25', 'OPERAR Y ADMINISTRAR EFICIENTEMENTE DEL 100 AL 80% DE LA INFRAESTRUCTURA, EQUIPOS Y RECURSOS PARA LA CONSERVACIÓN DEL ANP', 'REALIZAR DEL 70 AL 80% DE LAS ACTIVIDADES ', 'REALIZAR CON MENOS DEL 50% DE LAS ACTIVIDADES', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'NO CUMPLIR  CON MENOS  DEL  60 % DE LAS ACTIVIDADES	', 'NO CUMPLIR  CON MENOS  DEL  60 % DE LAS ACTIVIDADES	', 'REALIZAR CON MENOS DEL 60% DE LAS ACTIVIDADES DE LA ESTRATEGIA PARA EL FORTALECIMIENTO LA APLICACIÓN DE LA LFD', 'REALIZAR CON MENOS DEL 60% DE LAS ACTIVIDADES', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (883, 'FULA651027', 'Integración de grupos de trabajo en el marco del Programa para la Protección y Restauración de Ecosistemas y Especies en Riesgo, Componente Vigilancia y Monitoreo Comunitaria, localizados en el área de influencia del Parque Nacional, así como participar en la impartición de cursos de capacitación en materia ambiental para  4 comités. Realizar recorridos con cada uno de los comités.', '1', '15', 'Elaboración en tiempo y forma del POA del ANP, con 4 informes que integren todas las actividades realizadas dentro del PNPO.', 'Elaboración del POA del ANP, y sus 4 informes en tiempo pero fuera de forma.', 'Elaboración del POA del ANP y sus 4 informes fuera de tiempo y forma.', NULL, 'Instrumentar y brindar seguimiento al Programa Operativo Anual para asegurar el cumplimiento de los objetivos del mismo.', '2', '15', 'El POA fue elaborado en tiempo y forma y los objetivos y metas fueron cumplidos en un 90 %.', 'El POA fue elaborado en tiempo y forma y los objetivos y metas fueron cumplidos en un 70%.', 'El POA no fue elaborado en tiempo y forma y los objetivos y metas fueron cumplidos en un 50 %.', NULL, 'Integración de grupos de trabajo en el marco del Programa para la Protección y Restauración de Ecosistemas y Especies en Riesgo, Componente Vigilancia y Monitoreo Comunitario, localizados en el área de influencia del Parque Nacional, así como participar en la impartición de cursos de capacitación en materia ambiental para  4 comités. Realizar recorridos con cada uno de los comités.', '1', '20', 'Impartición de 4 talleres y/o pláticas sobre la importancia del los servicios ecosistémicos del Parque Nacional Pico de Orizaba.', 'Impartición de 3 talleres y/o pláticas sobre la importancia del los servicios ecosistémicos del Parque Nacional Pico de Orizaba.', 'Ningún taller y/o plática impartido sobre la importancia de los servicios ecosistémicos del Parque Nacional Pico de Orizaba.', NULL, 'Integración de grupos de trabajo en el marco del Programa para la Protección y Restauración de Ecosistemas y Especies en Riesgo, Componente Vigilancia y Monitoreo Comunitario, localizados en el área de influencia del Parque Nacional, así como participar en la impartición de cursos de capacitación en materia ambiental para  4 comités. Realizar recorridos con cada uno de los comités.', '1', '25', 'Integración de 3 grupos de vigilancia . Impartir cursos a estos grupos. Realizar 3 recorridos con cada uno de los grupos durante el año.', 'Integración de 2 grupos de vigilancia. Impartir cursos de capacitación únicamente a un grupo. Realizar 2 recorridos con cada uno de los grupos.', 'Ningún grupo de vigilancia integrado.', NULL, 'Coordinar y dar seguimiento al desarrollo del Programa Operativo Anual del programa \"Sierra y Mar - Conservación de Cuencas Costeras en el Contexto del Cambio Climático\",  de manera conjunta con Fondo Golfo de México A.C. ,y Fondo Mexicano para la Conservación de la Naturaleza AC,  para cumplir con los objetivos planteados en las declaratorias correspondientes y el Programa de Manejo.', '1', '25', 'Se da seguimiento a la operación del proyecto \"Sierra y Mar - Conservación de Cuencas Costeras en el Contexto de Cambio Climático\", cumpliendo los objetivos y metas en un 90%. ', 'Se da seguimiento a la operación del proyecto \"Conservación de Cuencas Costeras en el Contexto de Cambio Climático\", cumpliendo los objetivos y metas en un 70%.', 'Se da seguimiento a la operación del proyecto \"Conservación de Cuencas Costeras en el Contexto del Cambio Climático\" , cumpliendo los objetivos y metas en un 40%.', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Elaboración del ¨POA del ANP y sus 4 informes en forma pero fuera de tiempo', 'El PÖA fue elaborado en tiempo y forma y los objetivos y metas fueron cumplidos en un 50 %.', 'Impartición de 1 taller y/o plática sobre la importancia de los servicios ecosistémicos del Parque Nacional Pico de Orizaba', 'Integración de un grupo de vigilancia. No realizar ningún recorrido con los grupos', 'Se da seguimiento a la operación del proyecto \"Conservación de Cuencas Costeras en el Contexto del Cambio Climático\" , cumpliendo los objetivos y metas en un 50%.', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (874, 'ROZP770317', 'Apoyar en la integración y seguimiento del Programa Operativo Anual de las Áreas Naturales Protegidas incluyendo la captura de informes y evidencias en los sistemas correspondientes (SGPOA, SISEP)', '1', '25', '2 sistemas de seguimiento del cumplimiento del Programa Operativo Anual con informes y evidencias capturadas en su totalidad', '2 sistemas de seguimiento del cumplimiento del Programa Operativo Anual con informes y evidencias capturadas de manera parcial  ', '0 sistemas de seguimiento del Programa Operativo Anual', NULL, 'Apoyar en la capacitación de grupos comunitarios para el fortalecimiento de capacidades locales que promuevan el uso responsable de los recursos naturales', '1', '25', '3 talleres de capacitación', '2 talleres de capacitación', '0 talleres de capacitación', NULL, 'Dar seguimiento a la conformación de grupos comunitarios que contribuyan a generar información sobre las especies presentes en la RB Montes Azules', '1', '25', '1 brigada de monitoreo comunitario conformada y con seguimiento de sus acciones programadas', '1 brigada de monitoreo comunitario conformada con seguimiento parcial de sus acciones programadas', '0 brigadas de monitoreo comunitario conformadas ', NULL, 'Realizar recorridos terrestres/o fluviales en el Área Natural Protegida para el seguimiento del registro de especies de manera coordinada monitores comunitarios y/o guardaparques ', '1', '25', '30 recorridos terrestres y/o fluviales en el Área Natural Protegida', '10 recorridos terrestres y/o fluviales en el Área Natural Protegida', '3 recorridos terrestres y/o fluviales en el Área Natural Protegida', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '2 sistemas de seguimiento del Programa Operativo Anual sin informes, ni evidencias capturadas', '1 taller de capacitación impartido', '1 brigada de monitoreo comunitario sin seguimiento a sus acciones', '5 recorridos terrestres y/o fluviales en el Área Natural Protegida', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (875, 'VIPJ761003', 'INTEGRAR LA DOCUMENTACIÓN REQUERIDA EN REGLAS DE OPERACIÓN Y LINEAMIENTOS DE LOS PROYECTOS PROREST, PROCODES Y PROCODESCA ASIGNADOS, PARA LOGRAR LA CORRECTA APLICACIÓN DE LOS MISMOS, ASÍ COMO ASESORAR TÉCNICAMENTE A LOS BENEFICIARIOS DURANTE SU OPERACIÓN.', '8', '20', 'CUMPLIR CON LA META ESTABLECIDA EN UN 90-100%', 'CUMPLIR CON LA META ESTABLECIDA EN UN 80-89%', 'NO CUMPLIR CON LA META ESTABLECIDA', NULL, 'LOGRAR DURANTE LA OPERACIÓN DE PROYECTOS ASIGNADOS, LA PARTICIPACIÓN Y ORGANIZACIÓN DE LAS COMUNIDADES, PARA COORDINAR ACTIVIDADES DE CONSERVACIÓN, PROTECCIÓN DEL ECOSISTEMA Y ATENCIÓN DE CONTINGENCIAS AMBIENTALES DENTRO DEL ANP.', '8', '20', 'CUMPLIR CON LA META ESTABLECIDA EN UN 90-100%', 'CUMPLIR CON LA META ESTABLECIDA EN UN 80-89%', 'NO CUMPLIR CON LA META ESTABLECIDA', NULL, 'COORDINAR E IMPLEMENTAR ACCIONES DE PREVENCIÓN, CONTROL Y COMBATE DE INCENDIOS FORESTALES DENTRO DEL ÁREA, LOGRANDO CON ELLO LA CONSERVACIÓN DEL ECOSISTEMA A TRAVÉS DE LOS OBJETIVOS Y METAS PROGRAMADAS EN LOS PROYECTOS ASIGNADOS.', '8', '20', 'CUMPLIR CON LA META ESTABLECIDA EN UN 90-100%', 'CUMPLIR CON LA META ESTABLECIDA EN UN 80-89%', 'NO CUMPLIR CON LA META ESTABLECIDA', NULL, 'INTEGRAR EL INFORME DE LAS ACCIONES DESARROLLADAS DENTRO DEL ANP, CORRESPONDIENTE A LOS PROYECTOS ASIGNADOS.', '8', '20', 'CUMPLIR CON LA META ESTABLECIDA EN UN 90-100%', 'CUMPLIR CON LA META ESTABLECIDA EN UN 80-89%', 'NO CUMPLIR CON LA META ESTABLECIDA', NULL, 'IMPLANTAR EN LOS PROGRAMAS DE TRABAJO DE LA RESERVA, EL INTERÉS DE LOS USUARIOS Y LA IMPORTANCIA DE MANTENER UN EQUILIBRIO EN LA BIODIVERSIDAD, LA RESTAURACIÓN DE ÁREAS, EL MANEJO CON EQUIDAD DE GENERO Y EL DESARROLLO COMUNITARIO, OBTENIENDO COMO RESULTADO DE ESTAS LA CONSERVACIÓN DEL BOSQUE EN SIERRA LA LAGUNA.', '8', '20', 'CUMPLIR CON LA META ESTABLECIDA EN UN 90-100%', 'CUMPLIR CON LA META ESTABLECIDA EN UN 80-89%', 'NO CUMPLIR CON LA META ESTABLECIDA', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'CUMPLIR CON LA META ESTABLECIDA POR DEBAJO DE UN 79%', 'CUMPLIR CON LA META ESTABLECIDA POR DEBAJO DE UN 79%', 'CUMPLIR CON LA META ESTABLECIDA POR DEBAJO DE UN 79%', 'CUMPLIR CON LA META ESTABLECIDA POR DEBAJO DE UN 79%', 'CUMPLIR CON LA META ESTABLECIDA POR DEBAJO DE UN 79%', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (876, 'BEFA830909', 'REALIZAR LAS GESTIONES NECESARIAS PARA FOMENTAR LA PARTICIPACIÓN CIUDADANA EN .ACCIONES DE VIGILANCIA COMUNITARIA Y ESTRATEGIAS SIMILARES.', '4', '25', 'REALIZAR ENTRE EL 80% Y 100% DE GESTIONES PARA FOMENTAR  LA PARTICIPACIÓN CIUDADANA', 'REALIZAR ENTRE EL 70% Y 80% DE GESTIONES PARA FOMENTAR  LA PARTICIPACIÓN CIUDADANA', 'REALIZAR MENOS DEL 60% DE GESTIONES.', NULL, 'GENERAR E IMPLEMENTAR LAS  ACCIONES DE LA ESTRATEGIA DE SUPERVISIÓN Y VIGILANCIA DEL COMPLEJO DE ANP.', '4', '25', 'CUMPLIR  DEL 80% AL 100% DE LAS ACCIONES', 'CUMPLIR  DEL 70% AL 80% DE LAS ACCIONES', 'CUMPLIR MENOS DEL 60% DE LAS ACCIONES', NULL, 'ANALIZAR LA INFORMACIÓN GENERADA POR LAS ACCIONES DE SUPERVISIÓN PARA LA TOMA DE DECISIONES DE MANEJO.', '8', '25', 'ANALIZAR  DEL 80% AL 100% DE LA INFORMACIÓN GENERADA ', 'ANALIZAR  DEL 70% AL 80% DE LA INFORMACIÓN GENERADA ', 'ANALIZAR  MENOS DEL 60% DE LA INFORMACIÓN GENERADA ', NULL, 'COORDINAR LAS ACCIONES NECESARIAS PARA CONTAR CON UN SISTEMA DE SEÑALIZACIÓN TERRESTRE Y MARINA EN CORRECTO FUNCIONAMIENTO PARA LOS USUARIOS Y PRESTADORES DE SERVICIOS TURÍSTICOS QUE APROVECHAN LAS ÁREAS NATURALES PROTEGIDAS.', '4', '25', 'CONTAR CON UN SISTEMA DE SEÑALIZACIÓN OPERANDO ENTRE EL 80% AL 100% EN CORRECTO FUNCIONAMIENTO ', 'CONTAR CON UN SISTEMA DE SEÑALIZACIÓN OPERANDO ENTRE EL 70% AL 80% EN CORRECTO FUNCIONAMIENTO', 'CONTAR CON UN SISTEMA DE SEÑALIZACIÓN OPERANDO MENOS DEL 60% EN CORRECTO FUNCIONAMIENTO', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'REALIZAR ENTRE EL 60% Y 70% DE GESTIONES PARA FOMENTAR  LA PARTICIPACIÓN CIUDADANA', 'CUMPLIR DEL 60% AL 70% DE LAS ACCIONES ', 'ANALIZAR  DEL 60% AL 70% DE LA INFORMACIÓN GENERADA ', 'CONTAR CON UN SISTEMA DE SEÑALIZACIÓN OPERANDO ENTRE EL 60% AL 70% EN CORRECTO FUNCIONAMIENTO', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (877, 'MAGE930829', 'SUPERVISAR LAS ACCIONES QUE SE REALICEN DENTRO DEL ÁREA NATURAL PROTEGIDA SE AJUSTEN A LOS PROPÓSITOS DE LOS ORDENAMIENTOS LEGALES APLICABLES EN MATERIA DE PROTECCIÓN, MANEJO Y RESTAURACIÓN PARA LA CONSERVACIÓN DE LOS ECOSISTEMAS Y SU BIODIVERSIDAD.', '2', '40', '100 % al 75 %', '74 % al 50 %', '24 % al 0%', NULL, 'PROMOVER EL DESARROLLO COMUNITARIO EN EL ÁREA EN LO RELATIVO A LOS PROGRAMAS DE SUBSIDIOS Y PROYECTOS DE CONSERVACIÓN PARA EL DESARROLLO Y DE MANEJO PARA EL USO DE APROVECHAMIENTO DE LOS ECOSISTEMAS Y SU BIODIVERSIDAD. RECIBIR SOLICITUDES E INTEGRAR LOS EXPEDIENTES PARA EL OTORGAMIENTO DE LICENCIAS, PERMISOS, AUTORIZACIONES Y CONCESIONES.', '2', '30', '100 % al 75 %', '74 % al 50 %', '24 % al 0%', NULL, 'PARTICIPAR EN LOS PROGRAMAS, PROYECTOS Y ACCIONES DE ESPECIES Y POBLACIONES CONSIDERADAS COMO PRIORITARIAS PARA LA CONSERVACIÓN EN LAS ÁREAS NATURALES PROTEGIDAS DE SU COMPETENCIA. DIRIGIR Y EJECUTAR LOS PROGRAMAS PARA LA ATENCIÓN DE CONTINGENCIAS AMBIENTALES.', '2', '30', '100 % al 75 %', '74 % al 50 %', '24 % al 0%', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '49 % al 25%', '49 % al 25%', '49 % al 25%', NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (878, 'GOLM780115', 'Seguir los lineamientos de austeridad y control en las bitácoras de gasolina del parque vehicular de la Dirección APRN ZPFV Cuenca Hidrográfica del Rio Necaxa por medio de reportes de salidas y consumo de combustible de acuerdo a los formatos establecidos, lo cual ayuda a tener un control de las unidades que se usan.', '1', '20', '90', '50', '10', NULL, 'Utilizar los recursos externos que recibe el área natural protegida del Fondo Mexicano para la Conservación de la Naturaleza, (FANP), de acuerdo a la Planeación del presupuesto del ejercicio 2025, de acuerdo a los lineamientos establecidos en el POA, en el cumplimiento de formatos, reportes e informes que permite tener un control al momento de ejercer el recurso.', '9', '20', '90', '50', '10', NULL, 'Coadyuvar en las actividades de Monitoreo Biológico que se realiza en el área natural protegida, en temporada estacional, en las 4 presas del área que se considera sitio RAMSAR, al llenar los reportes, conteo de aves, identificación de especies.', '7', '20', '90', '50', '10', NULL, 'Realizar las actas de inventarios de bienes muebles cuando lo notifique la Dirección Regional, aplicando el control de inventario por medio del Reporte de SIREM, los resguardos de los bienes y una relacion de los bienes no encontrados en el reporte de SIREM, identificando la procedencia y el resguardo a quien corresponda.', '7', '20', '90', '50', '10', NULL, 'Llevar un control en el área de Recursos Humanos, en cuanto a las Vacaciones del personal adscrito al área natural protegida, documentación, licencias vigentes, control de guardias y reposición de días y uniformes.', '8', '20', '90', '50', '10', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '20', '20', '20', '20', '20', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (879, 'AERM910806', 'Implementar acciones de conservación en los ecosistemas; así como, generar y dar seguimiento a estrategias para la investigación y monitoreo de especies prioritarias en el ANP.', '10', '25', 'Se atiende entre el 85 y 100% de las actividades', 'Se atiende entre el 84 y 60% de las actividades', 'No se atiende ninguna de las actividades', NULL, 'Apoyar en el diseño y ejecución de eventos de difusión, sensibilización y/o educación ambiental en el ANP.', '10', '10', 'Se atiende entre el 85 y 100% de los eventos asignados', 'Se atiende entre el 84 y 60% de los eventos asignados', 'No se atiende ninguno de los eventos asignados', NULL, 'Apoyar en el seguimiento y atención de los procesos relacionados con proyectos e iniciativas que pretenden desarrollarse en el ANP, para emitir opiniones técnicas, permisos y autorizaciones u otros documentos de sustento biológico y ecosistémico.', '10', '20', 'Se atiende entre el 85 y 100% de los procesos', 'Se atiende entre el 84 y 60% de los procesos', 'No se atiende ninguno de los procesos', NULL, 'Apoyar en la ejecución y seguimiento de proyectos de conservación de especies prioritarias, vigilancia y monitoreo comunitario, atención a contingencias y/o proyectos productivos; así como promover y dar cumplimiento a las estrategias enfocadas en la reducción de la pérdida de la biodiversidad en el ANP.', '10', '25', 'Cumplir por lo menos con un 90%, en la ejecución y seguimiento a los proyectos asignados', 'Cumplir con menos del 85%, en la ejecución y seguimiento a los proyectos asignados', 'Cumplir con menos del 50%, en la ejecución y seguimiento a los proyectos asignados', NULL, 'Actualizar y/o elaborar la cartografía temática del ANP; así como, apoyo a las solicitudes de información recibidas.', '10', '20', 'Se atienden entre el 85 y 100% de las solicitudes', 'Se atiende entre el 84 y 60% de las solicitudes', 'No se atiende ninguna de las solicitudes', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Se atienden menos del 59% de las actividades', 'Se atienden menos del 59% de los eventos asignados', 'Se atienden en menos del 59% de los procesos', 'Cumplir con menos del 60%, en la ejecución y seguimiento a los proyectos asignados', 'Se atienden en menos del 59% de las solicitudes', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (880, 'ROAO790727', 'DAR SEGUIMIENTO A LA EJECUCIÓN DE LOS PROGRAMAS DE SUBSIDIOS MEDIANTE LA RECEPCIÓN DE SOLICITUDES,  ASESORÍA, VERIFICACIÓN, INTEGRACIÓN Y REVISIÓN DE EXPEDIENTES EN APEGO A LAS REGLAS DE OPERACIÓN Y LINEAMIENTOS ESTABLECIDOS, Y CON ELLO CONTRIBUIR AL CUMPLIMIENTO DE OBJETIVOS Y METAS INSTITUCIONALES EN LA DIRECCIÓN REGIONAL ', '4', '20', '95% DE ASESORÍA A LOS GRUPOS BENEFICIARIOS EN PROGRAMA ', '85% DE ASESORÍA A LOS GRUPOS BENEFICIARIOS EN PROGRAMA ', '70% DE ASESORÍA A LOS GRUPOS BENEFICIARIOS EN PROGRAMA ', NULL, 'REALIZAR ACCIONES DE SUPERVISIÓN DEL MANEJO Y DEL APROVECHAMIENTO FORESTAL EN UMAS DE MANGLE Y PALAPA DENTRO DEL ANP ', '4', '20', 'ACCIONES DE SUPERVISIÓN EN POR LO MENOS 70% DE LAS UMAS QUE SOLICITEN APROVECHAMIENTO DENTRO DEL ANP', 'ACCIONES DE SUPERVISIÓN EN POR LO MENOS 60% DE LAS UMAS QUE SOLICITEN APROVECHAMIENTO DENTRO DEL ANP', 'ACCIONES DE SUPERVISIÓN EN POR LO MENOS 40% DE LAS UMAS QUE SOLICITEN APROVECHAMIENTO DENTRO DEL ANP', NULL, 'REALIZAR OPINIONES TÉCNICAS RELATIVAS A LAS MANIFESTACIONES DE IMPACTO AMBIENTAL DENTRO DEL ANP Y SU ZONA DE INFLUENCIA ', '5', '20', 'ANALIZAR Y REALIZAR OPINIONES TÉCNICAS DEL 95% DE LAS MANIFESTACIONES DE IMPACTO ', 'ANALIZAR Y REALIZAR OPINIONES TÉCNICAS DEL 85% DE LAS MANIFESTACIONES DE IMPACTO ', 'ANALIZAR Y REALIZAR OPINIONES TÉCNICAS DEL 50% DE LAS MANIFESTACIONES DE IMPACTO ', NULL, 'IMPLEMENTAR Y COORDINAR PROYECTOS DE RESTAURACIÓN DE ECOSISTEMAS DE DIVERSIFICACIÓN PRODUCTIVA SUSTENTABLE COMPATIBLES CON LAS ESTRATEGIAS DE MANEJO DEL ANP', '5', '20', 'IMPLEMENTAR Y COORDINAR EL 95% DE LOS PROYECTOS ', 'IMPLEMENTAR Y COORDINAR EL 85% DE LOS PROYECTOS ', 'IMPLEMENTAR Y COORDINAR EL 50% DE LOS PROYECTOS ', NULL, 'REALIZAR ACTIVIDADES ADMINISTRATIVAS DE COORDINACIÓN DE PERSONAL OPERATIVO Y DE LOGÍSTICA, ASÍ COMO DE GESTIÓN DE RECURSOS MATERIALES, HUMANOS, TECNOLÓGICOS, FINANCIEROS Y/O JURÍDICOS QUE SE REQUIERAN DENTRO DE SU ÁMBITO DE APLICACIÓN, ASEGURANDO EL CUMPLIMIENTO NORMATIVO Y LA CONSECUCIÓN DE LAS ACTIVIDADES Y DE LA ADECUADA OPERACIÓN DEL ANP Y LA DIRECCIÓN REGIONAL ', '6', '20', 'CONTAR CON EL 95% DE LAS METAS ESTABLECIDAS EN EL POA ', 'CONTAR CON EL 85% DE LAS METAS ESTABLECIDAS EN EL POA ', 'CONTAR CON EL 50% DE LAS METAS ESTABLECIDAS EN EL POA ', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '80% DE ASESORÍA A LOS GRUPOS BENEFICIARIOS EN PROGRAMA ', 'ACCIONES DE SUPERVISIÓN EN POR LO MENOS 50% DE LAS UMAS QUE SOLICITEN APROVECHAMIENTO DENTRO DEL ANP', 'ANALIZAR Y REALIZAR OPINIONES TÉCNICAS DEL 75% DE LAS MANIFESTACIONES DE IMPACTO ', 'IMPLEMENTAR Y COORDINAR EL 75% DE LOS PROYECTOS ', 'CONTAR CON EL 75% DE LAS METAS ESTABLECIDAS EN EL POA ', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (881, 'VECL830817', 'SUPERVISAR LAS ACCIONES QUE SE REALICEN DENTRO DEL ÁREA NATURAL PROTEGIDA SE AJUSTEN A LOS PROPÓSITOS DE LOS ORDENAMIENTOS LEGALES APLICABLES EN MATERIA DE PROTECCIÓN, MANEJO Y RESTAURACIÓN PARA LA CONSERVACIÓN DE LOS ECOSISTEMAS Y SU BIODIVERSIDAD.', '4', '25', '100% AL 75%', '74% AL 50%', '24% AL 0%', NULL, 'PROMOVER EL DESARROLLO COMUNITARIO PARTICIPATIVO EN EL ÁREA EN LO RELATIVO A LOS PROGRAMAS DE SUBSIDIOS Y PROYECTOS DE CONSERVACIÓN PARA EL DESARROLLO, Y DE MANEJO PARA EL USO Y APROVECHAMIENTO DE LOS ECOSISTEMAS Y SU BIODIVERSIDAD. RECIBIR LAS SOLICITUDES E INTEGRAR LOS EXPEDIENTES PARA EL OTORGAMIENTO DE LICENCIAS, PERMISOS, AUTORIZACIONES Y CONCESIONES', '4', '25', '100% AL 75%', '74% AL 50%', '24% AL 0%', NULL, 'INTERVENIR EN LA FORMULACIÓN Y EJECUCIÓN DE LOS PROGRAMAS DE ORDENAMIENTO ECOLÓGICO QUE INCIDAN EN EL ÁREA NATURAL PROTEGIDA Y SUS ZONAS DE INFLUENCIA, CONFORMAR EL SISTEMA DE INFORMACIÓN CON LOS DATOS BIOLÓGICOS, SOCIALES, ECONÓMICOS Y CARTOGRÁFICOS DEL ÁREA NATURAL PROTEGIDA CORRESPONDIENTE', '4', '25', '100% AL 75%', '74% AL 50%', '24% AL 0%', NULL, 'PARTICIPAR EN LOS PROGRAMAS, PROYECTOS Y ACCIONES DE ESPECIES Y POBLACIONES CONSIDERADAS COMO PRIORITARIAS PARA LA CONSERVACIÓN, EN LAS ÁREAS NATURALES PROTEGIDAS DE SU COMPETENCIA. DIRIGIR Y EJECUTAR LOS PROGRAMAS PARA LA ATENCIÓN DE CONTINGENCIAS AMBIENTALES', '4', '25', '100% AL 75%', '74% AL 50%', '24% AL 0%', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '49% AL 25 %', '49% AL 25 %', '49% AL 25 %', '49% AL 25 %', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (882, 'CURM790117', 'Elaborar diseños gráficos para distintos materiales acorde a la identidad institucional, en solicitud y coordinación con la Dirección Regional y las Áreas Naturales Protegidas de la Región Frontera Sur, Istmo y Pacífico Sur, para su instrumentación en campañas de comunicación, señalización, difusión e información.', '10', '50', '100% a 60%', '59% a 40%', ' 19% a 0%', NULL, 'Producir y postproducir vídeos de carácter ilustrativo e informativo acorde a la identidad institucional, en solicitud y coordinación con la Dirección Regional y las Áreas Naturales Protegidas de la Región Frontera Sur, Istmo y Pacífico Sur, para su instrumentación en campañas de comunicación, difusión e información.', '10', '20', '100% a 60%', '59% a 40%', ' 19% a 0%', NULL, 'Hacer levantamientos fotográficos y de video para crear un banco de imágenes fotográficas de alta calidad y de vídeo en resolución 4K o FULL HD, en coordinación con las Áreas Naturales Protegidas de la Región Frontera Sur, Istmo y Pacífico Sur para su instrumentación en exposiciones y campañas de comunicación, difusión e información.', '10', '15', '100% a 50%', '49% a 30%', '9% a 0%', NULL, 'Actuar como enlace entre las distintas Áreas Naturales Protegidas de la Región Frontera Sur, Istmo y Pacífico Sur en coordinación con la Dirección Regional para la instrumentación en campañas de comunicación, señalización, difusión e información.', '10', '10', '100% a 50%', '49% a 30%', '9% a 0%', NULL, 'Capacitar y asesorar a distancia sobre cuáles son las mejores herramientas y como utilizarlas para hacer fotografías, videos, elaborar materiales gráficos, así como los lineamientos de la identidad gráfica oficial para reforzar el conocimiento con los enlaces de las Áreas Naturales Protegidas de la Región Frontera Sur, Istmo y Pacífico Sur.', '10', '5', '100% a 50%', '49% a 30%', '14% a 0%', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '39% a 20%', '39% a 20%', '29% a 10%', '29% a 10%', '29% a 15%', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (1090, 'PABB750823', 'Programar y Presupuestar las actividades del Programa Operativo Anual (POA) en su fase financiera, acorde con las actividades que se leven en el área, contribuyendo al mejoramiento de eficiencia operativa del ANP.', '2', '25', 'Gestionar y ejercer el recurso otorgado al Área, entre el 80% al 100%', 'Gestionar y ejercer el recurso otorgado al Área, entre el 79% al 60%', 'Gestionar y ejercer el recurso otorgado al Área, menos del 39%', NULL, 'Programar y Presupuestar los recursos FANP, en su fase administrativa y técnica, atendiento reportes semanales, mensuales, semestrales y anuales. Dar seguimiento oportuno para su desarrollo efectivo en las dos fases.', '5', '35', 'Realizar la programación de necesidades del área, para operar el recurso otorgado y atendiendo los reportes técnicos entre el 80% y el 100%', 'Realizar la programación de necesidades del área, para operar el recurso otorgado y atendiendo los reportes técnicos entre el 70% y el  60%.', 'Realizar la programación de necesidades del área para operar el recurso otorgado y atendiendo los reportes técnicos menos del 39%', NULL, 'Realizar y dar seguimiento a las bitácoras de vehículos y embarcaciones del área', '8', '20', 'Atender entre 12 y 11 meses las bitácoras de mantenimiento en tiempo y forma.', 'Atender 10 meses las bitácoras en tiempo y forma.', 'Atender 08 meses las bitácoras en tiempo y forma.', NULL, 'Ser el enlace administrativo del ANP,  verificar listas de asistencia, reportar en tiempo y forma.', '4', '20', 'Reportar entre 12 y  11 meses de listas de asistencia y entrega oportuna de documentos del RH.', 'Reportar 10 meses de listas de asistencia y entrega oportuna de documentos del RH.', 'Reportar menos de 08 meses de listas de asistencia y entrega oportuna de documentos del RH.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Gestionar y ejercer el recurso otorgado al Área, entre el 59% al 40%', 'Realizar la programación de necesidades del área, para operar el recurso otorgado y atendiendo los reportes técnicos entre el 59% y el  40%.', 'Atender 09 meses las bitácoras en tiempo y forma.', 'Reportar 09 meses de listas de asistencia y entrega oportuna de documentos del RH.', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (884, 'FORA810706', 'Apoyar en el diseño, operación y seguimiento del Sistema de Información de Participación Social (SIPAS):1) Incorporación de nuevas funcionalidades; 2) Monitoreo constante del SIPAS para abordar problemas técnicos de manera rápida y eficiente; 3) Capacitación y asesoría continua a usuarios del SIPAS; 4) Elaboración de reportes.', '5', '40', 'Apoyo en la atención de las cuatro actividades principales para el diseño, operación y seguimiento del SIPAS.', 'Apoyo en la atención de tres de las actividades principales para el diseño, operación y seguimiento del SIPAS.', 'No realiza ninguna de las actividades principales para el apoyo en el diseño, operación y seguimiento del SIPAS.', NULL, 'Auxiliar en la realización de capacitaciones sobre temas vinculados con la participación social en la Comisión Nacional', '1', '40', 'Se apoya en al menos tres capacitaciones en temas vinculados con la participación social en la Comisión Nacional', 'Se apoya en dos capacitaciones en temas vinculados con la participación social en la Comisión Nacional.', 'No se apoya en ninguna capacitación en temas vinculados con la participación social en la Comisión Nacional.', NULL, 'Apoyar en el diseño y evaluación de los Programas de Subsidio: 1) Integración y análisis de información; 2) Revisión y/o actualización de Poblaciones Potencial y Objetivo; 3) Revisión y propuesta de indicadores; 4) Integración de información, revisión y emisión de comentarios relativos a documentos técnicos relacionados con los programas.', '1', '20', 'Apoyo en la atención y seguimiento de las cuatro actividades principales para el cumplimiento del diseño y evaluación de los Programas de Subsidio', 'Apoyo para la atención y seguimiento de dos de las cuatro principales actividades para el cumplimiento del diseño y evaluación de los Programas de Subsidio', 'No se apoya en ninguna de las cuatro principales actividades para el cumplimiento del diseño y evaluación de los Programas de Subsidio.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Apoyo en la atención de una de las actividades principales para el diseño, operación y seguimiento del SIPAS.', 'Se apoya en al menos una capacitación en temas vinculados con la participación social en la Comisión Nacional', 'Apoyar en la atención y seguimiento de una de las cuatro principales actividades para el cumplimiento del diseño y evaluación de los Programas de Subsidio.', NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (885, 'DEQG830329', 'OPERAR EL PROGRAMA DE MONITOREO BIOLÓGICO DE 2 ESPECIES DE IMPORTANCIA BIOLÓGICA EN LA RESERVA DE LA BIOSFERA MARISMAS NACIONALES NAYARIT Y/O EN SU ZONA DE INFLUENCIA ', '10', '30', 'OPERAR AL 95% EL PROGRAMA DE MONITOREO DE 2 ESPECIES DE IMPORTANCIA BIOLÓGICA EN LA RESERVA DE LA BIOSFERA MARISMAS NACIONALES NAYARIT Y/O SU ZONA DE INFLUENCIA', 'OPERAR AL 85% EL PROGRAMA DE MONITOREO DE 2 ESPECIES DE IMPORTANCIA BIOLÓGICA EN LA RESERVA DE LA BIOSFERA MARISMAS NACIONALES NAYARIT Y/O SU ZONA DE INFLUENCIA', 'OPERAR AL 65% EL PROGRAMA DE MONITOREO DE 2 ESPECIES DE IMPORTANCIA BIOLÓGICA EN LA RESERVA DE LA BIOSFERA MARISMAS NACIONALES NAYARIT Y/O SU ZONA DE INFLUENCIA', NULL, 'DAR SEGUIMIENTO A 2 PROYECTOS RELACIONADOS CON LA PROTECCIÓN Y/O MONITOREO DE ESPECIES PACE EN LA RESERVA DE LA BIOSFERA MARISMAS NACIONALES NAYARIT Y/O EN SU ZONA DE INFLUENCIA', '10', '30', 'OPERAR AL 95% EL PROGRAMA DE MONITOREO DE 2 ESPECIES DE IMPORTANCIA BIOLÓGICA EN LA RESERVA DE LA BIOSFERA MARISMAS NACIONALES NAYARIT Y/O SU ZONA DE INFLUENCIA', 'OPERAR AL 85% EL PROGRAMA DE MONITOREO DE 2 ESPECIES DE IMPORTANCIA BIOLÓGICA EN LA RESERVA DE LA BIOSFERA MARISMAS NACIONALES NAYARIT Y/O SU ZONA DE INFLUENCIA', 'OPERAR AL 65% EL PROGRAMA DE MONITOREO DE 2 ESPECIES DE IMPORTANCIA BIOLÓGICA EN LA RESERVA DE LA BIOSFERA MARISMAS NACIONALES NAYARIT Y/O SU ZONA DE INFLUENCIA', NULL, 'REALIZAR ACCIONES DE MANEJO Y/O PROTECCIÓN, ENCAMINADOS A DISMINUIR EL CONFLICTO DEPREDADOR-GANADO EN LA RESERVA DE LA BIOSFERA MARISMAS NACIONALES NAYARIT Y SU ZONA DE INFLUENCIA', '1', '30', 'REALIZAR 5 ACCIONES DE MANEJO Y/O PROTECCIÓN, ENCAMINADOS A DISMINUIR EL CONFLICTO DEPREDADOR-GANADO EN LA RESERVA DE LA BIOSFERA MARISMAS NACIONALES NAYARIT Y SU ZONA DE INFLUENCIA', 'REALIZAR 4 ACCIONES DE MANEJO Y/O PROTECCIÓN, ENCAMINADOS A DISMINUIR EL CONFLICTO DEPREDADOR-GANADO EN LA RESERVA DE LA BIOSFERA MARISMAS NACIONALES NAYARIT Y SU ZONA DE INFLUENCIA', 'REALI