INSERT INTO `sed_individuales` VALUES (899, 'AUCS930727', 'RECEPCIÓN, INTEGRACIÓN, ANÁLISIS DE EXPEDIENTES, GENERACIÓN DE DICTÁMENTES TÉCNICOS Y REGISTRO EN PLATAFORMA SIRCA-PA, DE SOLICITUDES DE PERMISOS Y AUTORIZACIONES.', '1', '30', '15', '10', '0', '90', 'ANÁLISIS Y RESPUESTA TÉCNICO-AMBIENTAL, CONFORME A LA NORMATIVIDAD VIGENTE, A SOLICITUDES PRESENTADAS POR USUARIOS DEL PARQUE NACIONAL TULUM.\r\n', '1', '25', NULL, '10', '0', '90', 'ELABORAR Y APLICAR LA ESTRATEGIA DE EDUCACIÓN AMBIENTAL Y COMUNICACIÓN SOCIAL, CON LA FINALIDAD DE LOGRAR INTERIORIZAR LOS VALORES DE CONSERVACIÓN DEL ANP EN LA POBLACIÓN QUE HABITA EN SU INTERIOR Y ZONA DE INFLUENCIA, ASÍ COMO DE LA POBLACIÓN EN GENERAL (BRINDAR O COORDINAR PLÁTICAS, TALLERES, ACTIVIDADES DE LIMPIEZA, ETC).\r\n', '1', '20', '15', '10', '0', '90', 'CONFORMAR Y ADMINISTRAR LAS BASES DE DATOS DE COLABORADORES Y VEHÍCULOS UTILIZADOS POR LOS USUARIOS DE LA SUBZONA DE USO PÚBLICO CON INFRAESTRUCTURA TURÍSTICA QU, ASÍ COMO POR LOS PRESTADORES DE SERVICIOS TURÍSTICOS, PARA LA EMISIÓN DE CREDENCIALES Y TARJETONES. \r\n', '1', '15', NULL, NULL, NULL, '90', 'ANÁLISIS, LECTURA, REVISIÓN DE PROYECTOS, INTEGRACIÓN Y ELABORACIÓN DE OPINIONES TÉCNICAS EN MATERIA DE IMPACTO AMBIENTAL, ZONA FEDERAL MARÍTIMO TERRESTRE Y AMBIENTES COSTEROS Y TERRESTRES QUE PRETENDEN REALIZARSE DENTRO DEL ANP.\r\n', '1', '10', NULL, NULL, NULL, '90', NULL, NULL, 1, '2024', NULL, NULL, NULL, NULL, NULL, '05', '05', '05', NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
