INSERT INTO `sed_individuales` VALUES (910, 'LALM830125', 'VERIFICAR QUE LOS PROYECTOS Y ACCIONES DEL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE (PROCODES), EJERCICIO FISCAL 2025, SE APEGUEN A LA NORMATIVIDAD ESTABLECIDA EN LOS LINEAMIENTOS Y REGLAS DE OPERACIÓN MEDIANTE LA REVISIÓN Y ENTREGA OPORTUNA DE LA INTEGRACIÓN DE EXPEDIENTES; SOLICITUD, COMPILACIÓN, E INFORMES DE AVANCE FÍSICO FINANCIERO Y DE METAS (AIFFM)Y SEGUIMIENTO A LA ACTUALIZACIÓN Y REGISTRO DE INFORMACIÓN POR PARTE DE LOS TÉCNICOS OPERATIVOS EN EL SISTEMA DE INFORMACIÓN DEL PROCODES (SISP)', '10', '30', '81 AL 95% DE EXPEDIENTES INTEGRADOS CONFORME A LA NORMATIVIDAD DEL PROCODES Y EL REGISTRO EN EL SISP DEL IAFFM ENTREGADOS. ', '51 AL 80% DE EXPEDIENTES INTEGRADOS CONFORME A LA NORMATIVIDAD DEL PROCODES Y EL REGISTRO EN EL SISP DEL IAFFM ENTREGADOS. ', '24% o MENOS DE EXPEDIENTES INTEGRADOS CONFORME A LA NORMATIVIDAD DEL PROCODES Y EL REGISTRO EN EL SISP DEL IAFFM ENTREGADOS. ', NULL, 'VERIFICAR QUE LOS PROYECTOS Y ACCIONES DEL PROGRAMA DE PARA LA  PROTECCIÓN Y RESTAURACIÓN DE ECOSISTEMAS Y ESPECIES PRIORITARIAS (PROREST), EN SU COMPONENTE DE CONSERVACIÓN COMUNITARIA, EJERCICIO FISCAL 2025, SE APEGUEN A LA NORMATIVIDAD ESTABLECIDA EN LOS LINEAMIENTOS MEDIANTE LA REVISIÓN Y ENTREGA OPORTUNA DE LA INTEGRACIÓN DE EXPEDIENTES; SOLICITUD, COMPILACIÓN, E INFORMES DE AVANCE FÍSICO FINANCIERO Y DE METAS (AIFFM)Y SEGUIMIENTO A LA ACTUALIZACIÓN Y REGISTRO DE INFORMACIÓN POR PARTE DE LOS TÉCNICOS OPERATIVOS EN EL SISTEMA DE INFORMACIÓN DEL PROREST (SISP)	\r\n', '10', '30', '81 AL 95% DE EXPEDIENTES INTEGRADOS CONFORME A LA NORMATIVIDAD DEL PROREST Y EL REGISTRO EN EL SISP DEL IAFFM ENTREGADOS. ', '51 AL 80% DE EXPEDIENTES INTEGRADOS CONFORME A LA NORMATIVIDAD DEL PROREST Y EL REGISTRO EN EL SISP DEL IAFFM ENTREGADOS. 	', '24% o MENOS DE EXPEDIENTES INTEGRADOS CONFORME A LA NORMATIVIDAD DEL PROREST Y EL REGISTRO EN EL SISP DEL IAFFM ENTREGADOS. ', NULL, 'VERIFICAR LA IMPLEMENTACIÓN DE LA CONTRALORÍA