INSERT INTO `sed_individuales` VALUES (911, 'CAHJ710402', 'PROMOVER LA COORDINACIÓN INTERINSTITUCIONAL PARA LA APLICACIÓN DEL PLAN DE RESTAURACIÓN DE MANGLARES, EL PLAN DE SUSTITUCIÓN DE PLANTACIONES DE PALMA AFRICANA, EL PROTOCOLO DE CONTROL DE PALMA AFRICANA, Y LA REHABILITACIÓN DE SISTEMAS LAGUNARES EN SITIOS CRÍTICOS DE LA RESERVA DE LA BIOSFERA LA ENCRUCIJADA.', '4', '25', 'Se establecen acuerdos para la aplicación de acciones interinstitucionales en entre el 70 y el 90% de los sitios críticos.', 'Se establecen acuerdos para la aplicación de acciones interinstitucionales en entre el 60% y el 69% de los sitios críticos.', 'Se establecen acuerdos para la aplicación de acciones interinstitucionales en menos del 50% de los sitios críticos.', NULL, 'FOMENTAR EL FUNCIONAMIENTO DE LOS ÓRGANOS COLEGIADOS DE PARTICIPACIÓN: CONSEJO ASESOR, SUBCONSEJO CIENTÍFICO ACADÉMICO Y SUBCONSEJO DE PESCA RESPONSABLE DE LA RESERVA DE LA BIOSFERA LA ENCRUCIJADA, Y CONSEJO ASESOR DEL SANTUARIO PLAYA PUERTO ARISTA.', '4', '20', 'Se cumple entre el 70% y el 90% de los acuerdos de los órganos colegiados programados para 2025.', 'Se cumple entre el 60% y el 69% de los acuerdos de los órganos colegiados programados para 2025.', 'Se cumple menos del 60% de los acuerdos de los órganos colegiados programados para 2025.', NULL, 'COORDINAR LA EJECUCIÓN DE LOS PROGRAMAS DE SUBSIDIOS DE LA CONANP (PROCODES Y PROREST) CON EL FIN DE GARANTIZAR EFICIENCIA Y EFICACIA EN LA RESERVA DE LA BIOSFERA LA ENCRUCIJADA Y EL SANTUARIO PLAYA PUERTO ARISTA.', '4', '15', 'Se cumple entre el 70% y el 90% de los proyectos de subsidios de la CONANP de acuerdo con sus expedientes técnicos.', 'Se cumple entre el 60% y el 69% de los proyectos de subsidios de la CONANP de acuerdo con sus expedientes técnicos.', 'Se cumple con menos del 50% de los proyectos de subsidios de la CONANP de acuerdo con sus expedientes técnicos.', NULL, 'FACILITAR LA PLANEACIÓN Y OPERACIÓN DE LA RESERVA DE LA BIOSFERA LA ENCRUCIJADA Y EL SANTUARIO PLAYA PUERTO ARISTA.', '4', '15', 'Se cumple entre el 70% y el 90% de las metas de los Programas Operativos Anuales de La Encrucijada y Puerto Arista', 'Se cumple entre el 60% y el 69% de las metas de los Programas Operativos Anuales de La Encrucijada y Puerto Arista', 'Se cumple menos del 60% de las metas dde los Programas Operativos Anuales de La Encrucijada y Puerto Arista', NULL, 'FACILITAR LA INTEGRACIÓN DEL PROGRAMA DE MANEJO DEL SANTUARIO PLAYA PUERTO ARISTA.', '4', '25', 'Documento del Programa de Manejo autorizado por la Dirección General de Conservación.', 'Documento del Programa de Manejo en revisión por la Dirección General de Conservación.', 'Insumos compilados para el Programa de Manejo.', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Se establecen acuerdos para la aplicación de acciones interinstitucionales en entre el 50 y el 59% de los sitios críticos.', 'Se cumple entre el 59% y el 60% de los acuerdos de los órganos colegiados programados para 2025.', 'Se cumple entre el 50% y el 59% de los proyectos de subsidios de la CONANP de acuerdo con sus expedientes técnicos.', 'Se cumple entre 50% y 59% de las metas de los Programas Operativos Anuales de La Encrucijada y Puerto Arista', 'Borrador en preparación del Programa de Manejo.', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
