INSERT INTO `sed_individuales` VALUES (922, 'SAZO920322', 'IMPULSAR LA CULTURA DEL AGUA E IMPLEMENTAR TECNOLOGÍAS DE ADAPTACIÓN AL CAMBIO CLIMÁTICO EN COMUNIDADES RURALES DEL ANP	\r\n', '10', '35', 'DEL 70% AL 89%', 'DEL 60% AL 69%', 'MENOS DEL 50%', NULL, 'REALIZAR ACCIONES DE CONSERVACIÓN DE LOS ECOSISTEMAS Y SU BIODIVERSIDAD, ASI COMO DE APOYO LOGÍSTICO PARA LA INVESTIGACIÓN, MONITOREO DE ESPECIES,EDUCACIÓN PARA LA CONSERVACIÓN Y VIGILANCIA EN EL ÁREA NATURAL PROTEGIDA ASEGURANDO EL CUMPLIMIENTO A LA NORMATIVIDAD VIGENTE, EL PROGRAMAOPERATIVO ANUAL Y EL PROGRAMA DE MANEJO DEL ANP.', '10', '35', 'DEL 70% AL 89%', 'DEL 60% AL 69%', 'MENOS DEL 50%', NULL, 'DAR SEGUIMIENTO A LA EJECUCIÓN DE LOS PROGRAMAS DE SUBSIDIO MEDIANTE LA ASESORÍA, VERIFICACIÓN, INTEGRACIÓN Y REVISIÓN DE EXPEDIENTES EN APEGO A LASREGLAS DE OPERACIÓN Y LINEAMIENTOS ESTABLECIDOS Y CON ELLO CONTRIBUIR AL CUMPLIMIENTO DE OBJETIVOS Y METAS INSTITUCIONALES EN LA DIRECCIÓN REGIONAL', '10', '30', 'DEL 70% AL 89%', 'DEL 60% AL 69%', 'MENOS DEL 50%', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'DEL 50% AL 59%', 'DEL 50% AL 59%', 'DEL 50% AL 59%', NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (923, 'EALR640607', 'Implementar las actividades establecidas en el Programa Operativo Anual 2025 del Parque Nacional Palenque y del Área de Protección de Flora y Fauna Cascadas de Agua Azul.', '10', '30', 'Se implementa entre el 90 al 100 % de las actividades establecidas en el Programa Operativo Anual 2025.', 'Se implementa entre el 60 al 89 % de las actividades establecidas en el Programa Operativo Anual 2025.', 'Se implementa menos del 50% de las actividades establecidas en el Programa Operativo Anual 2025.', NULL, 'Se regula las diversas actividades relacionados con el turismo que se desarrolla dentro del Parque Nacional Palenque, principalmente lo referentes a los servicios de  guía de turismo, actividades comerciales y específicamente la actividad de turismo que desarrollan las agencias y tours operadores.', '10', '20', 'Se regula las actividades relacionados con el turismo al 50% en el Parque Nacional Palenque.', 'Se regula las actividades relacionados con el turismo al 40% en el Parque Nacional Palenque.', 'Se regula las actividades relacionados con el turismo al 20% en el Parque Nacional Palenque.', NULL, 'Seguimiento a las diversas actividades relacionados con la elaboración y publicación del programa de Manejo del Parque Nacional Palenque, de manera coordinada con las oficinas de la Dirección Regional y Oficinas Centrales de la CONANP.', '10', '20', 'Seguimiento del 100% de las acciones relacionados con la elaboracion y publicacion del Programa de Manejo.', 'Seguimiento del 80% de las acciones relacionados con la elaboracion y publicacion del Programa de Manejo.', 'Seguimiento de menos del 50% de las acciones relacionados con la elaboración y publicación del Programa de Manejo.', NULL, 'Se fortalece la operatividad y la presencia institucional en el Área de Protección de Flora y Fauna Cascadas de Agua Azul, retomando las actividades del Centro Turístico Cascadas de Agua Azul y mejorando la presencia del personal técnico en las comunidades asentadas dentro y en la zona de influencia del Área Natural Protegida.', '10', '10', 'Se fortalece la operatividad y la presencia institucional en un 80% en el Area de Proteccion de Flora y Fauna Cascadas de Agua Azul.', 'Se fortalece la operatividad y la presencia institucional en un 70% en el Area de Proteccion de Flora y Fauna Cascadas de Agua Azul.', 'Se fortalece la operatividad y la presencia institucional en un 50% en el Area de Proteccion de Flora y Fauna Cascadas de Agua Azul.', NULL, 'Atender la problemática ambiental y social con la participación de otras instituciones de gobierno y organizaciones no gubernamentales nacionales e internacionales del Parque Nacional Palenque y Área de Protección de Flora y Fauna Cascadas de Agua Azul.', '10', '20', 'Se atiende el 100% de la problematica ambiental y social que se presenten en el Parque Nacional Palenque y Area de Proteccion de Flora y Fauna Cascadas de Agua Azul.', 'Se atiende el 70% de la problematica ambiental y social que se presenten en el Parque Nacional Palenque y Area de Proteccion de Flora y Fauna Cascadas de Agua Azul.', 'Se atiende menos del 50% de la problemática ambiental y social que se presenten en el Parque Nacional Palenque y Area de Proteccion de Flora y Fauna Cascadas de Agua Azul.', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Se implementa entre el 50 y 59 % de las actividades establecidas en el Programa Operativo Anual 2025.', 'Se regula las actividades relacionados con el turismo al 30% en el Parque Nacional Palenque.', 'Seguimiento del 60 % de las acciones relacionados con la elaboracion y publicacion del Programa de Manejo.', 'Se fortalece la operatividad y la presencia institucional en un 60% en el Area de Proteccion de Flora y Fauna Cascadas de Agua Azul.', 'Se atiende el 50% de la problematica ambiental y social que se presenten en el Parque Nacional Palenque y Area de Proteccion de Flora y Fauna Cascadas de Agua Azul.', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (936, 'LOMJ810424', 'PARTICIPAR EN LA REALIZACIÓN Y CUMPLIMIENTO DEL PROGRAMA OPERATIVO ANUAL DEL ÁREA NATURAL PROTEGIDA', '10', '40', ' EL PROGRAMA OPERATIVO ANUAL FUE REALIZADO Y SE CUMPLIÓ EN TIEMPO Y FORMA EN SU TOTALIDAD Y/O SE JUSTICARON ADECUADAMENTE LAS ACTIVIDADES NO REALIZADAS', ' EL PROGRAMA OPERATIVO ANUAL SE REALIZO Y SE CUMPLIÓ EN TIEMPO Y FORMA EN UN 70 PORCIENTO Y NO SE JUSTICARON ADECUADAMENTE LAS ACTIVIDADES NO REALIZADAS', 'NO FUE REALIZADO Y NO SE CUMPLIÓ NADA EN TIEMPO Y FORMA CON LA PROGRAMACIÓN DEL EJERCICIO', NULL, 'COADYUVAR CON LA COMPLEMENTACIÓN DE LOS CONCEPTOS DE APOYO FINANCIADOS POR PROGRAMAS DE SUBSIDIO, EN LAS COMUNIDADES RURALES INVOLUCRADAS EN LAS ANPS Y LA CONSERVACIÓN DE LAS MISMAS, DENTRO DE SU ZONA DE INFLUENCIA.', '10', '30', 'LOS PROGRAMAS DE SUBSIDIO SE CUMPLIERON EN TIEMPO Y FORMA EN SU TOTALIDAD Y/O SE JUSTICARON ADECUADAMENTE LAS ACTIVIDADES NO REALIZADAS', 'LOS PROGRAMAS DE SUBSIDIO SE CUMPLIERON EN TIEMPO Y FORMA EN UN 70 PORCIENTO Y NO SE JUSTICARON ADECUADAMENTE LAS ACTIVIDADES NO REALIZADAS', 'NO FUE REALIZADO Y NO SE CUMPLIÓ NADA EN TIEMPO Y FORMA CON LA PROGRAMACIÓN DEL EJERCICIO', NULL, 'REALIZAR Y DAR SEGUIMIENTO A LAS ACTIVIDADES RELACIONADAS DE LOS SISTEMAS DE INFORMACIÓN GEOGRÁFICA DE SOPORTE DEL ANP.', '10', '10', 'LAS ACTIVIDADES DE SISTEMA DE INFORMACION GEOGRAFICA SE CUMPLIERON EN TIEMPO Y FORMA EN SU TOTALIDAD Y/O SE JUSTICARON ADECUADAMENTE LAS ACTIVIDADES NO REALIZADAS', 'LAS ACTIVIDADES DE SISTEMA DE INFORMACION GEOGRAFICA SE CUMPLIERON EN TIEMPO Y FORMA EN UN 70 PORCIENTO Y NO SE JUSTICARON ADECUADAMENTE LAS ACTIVIDADES NO REALIZADAS', 'NO FUE REALIZADO Y NO SE CUMPLIÓ NADA EN TIEMPO Y FORMA CON LA PROGRAMACIÓN DEL EJERCICIO', NULL, 'REALIZAR Y DAR SEGUIMIENTO A LAS ACTIVIDADES RELACIONADAS DE DICTÁMENES TÉCNICOS DE SOPORTE DEL ANP.', '10', '20', 'LAS ACTIVIDADES DE DICTAMENES TECNICOS SE CUMPLIERON EN TIEMPO Y FORMA EN SU TOTALIDAD Y/O SE JUSTICARON ADECUADAMENTE LAS ACTIVIDADES NO REALIZADAS', 'LAS ACTIVIDADES DE DICTAMENES TECNICOS SE CUMPLIERON EN TIEMPO Y FORMA EN UN 70 PORCIENTO Y NO SE JUSTICARON ADECUADAMENTE LAS ACTIVIDADES NO REALIZADAS', 'NO FUE REALIZADO Y NO SE CUMPLIÓ NADA EN TIEMPO Y FORMA CON LA PROGRAMACIÓN DEL EJERCICIO', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, ' EL PROGRAMA OPERATIVO ANUAL SE REALIZO Y SE CUMPLIÓ EN TIEMPO Y FORMA EN UN 50 PORCIENTO Y NO SE JUSTICARON ADECUADAMENTE LAS ACTIVIDADES NO REALIZADAS', 'LOS PROGRAMAS DE SUBSIDIO SE CUMPLIERON EN TIEMPO Y FORMA EN UN 50 PORCIENTO Y NO SE JUSTICARON ADECUADAMENTE LAS ACTIVIDADES NO REALIZADAS', 'LAS ACTIVIDADES DE SISTEMA DE INFORMACION GEOGRAFICA SE CUMPLIERON EN TIEMPO Y FORMA EN UN 50 PORCIENTO Y NO SE JUSTICARON ADECUADAMENTE LAS ACTIVIDADES NO REALIZADAS', 'LAS ACTIVIDADES DE DICTAMENES TECNICOS SE CUMPLIERON EN TIEMPO Y FORMA EN UN 50 PORCIENTO Y NO SE JUSTICARON ADECUADAMENTE LAS ACTIVIDADES NO REALIZADAS', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
