INSERT INTO `sed_individuales` VALUES (977, 'TIVJ801216', 'EMITIR EN TIEMPO Y FORMA DICTÁMENES TÉCNICOS EN RELACIÓN AL APROVECHAMIENTO, CONCESIONES, OBRAS, ACTIVIDADES Y PERMISOS QUE SOLICITEN AUTORIDADES COMPETENTES Y SU ACTUALIZACIÓN EN EL SIRCA', '10', '20', '100-80% DE DICTÁMENES EMITIDOS EN TIEMPO Y FORMA, E INCORPORADAS AL SIRCA', '<80% DICTÁMENES EMITIDOS SE EMITEN EN TIEMPO Y FORMA', '<50% DICTÁMENES EMITIDOS SE EMITEN EN TIEMPO Y FORMA', NULL, 'SUPERVISAR Y ASEGURAR LA CORRECTA APLICACIÓN DE RECURSOS ASIGNADOS AL ANP, ASÍ COMO ASEGURAR EL CORRESPONDIENTE PAGO DE DERECHOS POR PARTE DE LOS USUARIOS', '10', '20', '80-100% DE LOS USUARIOS CON ACTIVIDADES RECREATIVAS EN EL PARQUE NACIONAL CUBREN EL PAGO DE DERECHOS', '<80% DE LOS USUARIOS CON ACTIVIDADES RECREATIVAS EN EL PARQUE NACIONAL CUBREN EL PAGO DE DERECHOS', '<50% DE LOS USUARIOS CON ACTIVIDADES RECREATIVAS EN EL PARQUE NACIONAL CUBREN EL PAGO DE DERECHOS', NULL, 'PROMOVER Y FACILITAR EL ESTABLECIMIENTO DE PROGRAMAS DE TRABAJO ESPECÍFICOS PARA EL APOYO DE ACTIVIDADES MONITOREO BIOLÓGICO TERRESTRE Y MARINO, CONSERVACIÓN, CONTROL Y/O ERRADICACIÓN DE ESPECIES EXÓTICAS-INVASORAS', '10', '20', '80-100% DE PLANES DE TRABAJO FIRMAN ESPECÍFICOS CON ORGANIZACIONES DE LA SOCIEDAD CIVIL Y/O ACADEMIA', '<80% DE PLANES DE TRABAJO FIRMAN ESPECÍFICOS CON ORGANIZACIONES DE LA SOCIEDAD CIVIL Y/O ACADEMIA', '<50% DE PLANES DE TRABAJO FIRMAN ESPECÍFICOS CON ORGANIZACIONES DE LA SOCIEDAD CIVIL Y/O ACADEMIA', NULL, 'DAR SEGUIMIENTO A LAS ACTIVIDADES, PROYECTOS Y ESTUDIOS QUE SE REALICEN EN EL PARQUE NACIONAL', '10', '20', '100-80% DE LAS ACTIVIDADES, PROYECTOS Y ESTUDIOS ACOMPAÑADOS', '<80% DE LAS ACTIVIDADES, PROYECTOS Y ESTUDIOS ACOMPAÑADOS', '<50% DE LAS ACTIVIDADES, PROYECTOS Y ESTUDIOS ACOMPAÑADOS', NULL, 'FUNGIR COMO SECRETARIO Y ATENDER LAS REUNIONES DEL CONSEJO ASESOR DEL PARQUE NACIONAL REVILLAGIGEDO Y SUBCONSEJOS', '10', '20', 'SE ATIENDE EL 100% DE LAS REUNIONES CON EL CONSEJO ASESOR Y SUBCONSEJOS', '<80% SE ATIEN