INSERT INTO `sed_individuales` VALUES (949, 'SATJ701206', 'DAR SEGUIMIENTO A LA EJECUCIÓN DE LOS PROGRAMAS DE SUBSIDIO MEDIANTE LA ASESORÍA, VERIFICACIÓN, INTEGRACIÓN Y REVISIÓN DE EXPEDIENTES EN APEGO A LAS REGLAS DE OPERACIÓN Y LINEAMIENTOS ESTABLECIDOS Y CON ELLO CONTRIBUIR AL CUMPLIMIENTO DE OBJETIVOS Y METAS INSTITUCIONALES EN LA DIRECCIÓN REGIONAL.', '1', '30', '80 a 90 %', '65 a 80 %', 'menor a 60 %', NULL, 'REVISAR LA INFORMACIÓN BIOLÓGICA, GEOGRÁFICA Y SOCIAL DISPONIBLE DEL ANP PARA ANALIZAR LAS PROPUESTAS DE LOS PROYECTOS SOLICITADOS Y AUTORIZADOS, COMPATIBLES CON LAS ESTRATEGIAS DE MANEJO DEL ANP, ALINEADOS A LA NORMATIVIDAD AMBIENTAL VIGENTE.', '1', '30', '80 a 90 %', '65 a 80 %', 'menor a 60 %', NULL, 'REALIZAR ACTIVIDADES ADMINISTRATIVAS, DE COORDINACIÓN DE PERSONAL OPERATIVO Y DE LOGÍSTICA, ASÍ COMO DE GESTIÓN DE RECURSOS MATERIALES, HUMANOS, TECNOLÓGICOS, FINANCIEROS Y/O JURÍDICOS QUE SE REQUIERAN, DENTRO DE SU ÁMBITO DE APLICACIÓN , ASEGURANDO EL CUMPLIMIENTO NORMATIVO Y LA CONSECUCIÓN DE LAS ACTIVIDADES Y LA ADECUADA OPERACIÓN DEL ANP Y LA DIRECCIÓN REGIONAL.', '1', '20', '80 a 90 %', '65 a 80 %', 'Menor a 60 %', NULL, 'APOYAR EN LA REVISIÓN JURÍDICA DE CONCESIONES, PERMISOS, Y DEMÁS AUTORIZACIONES EN MATERIA DE ANP´s DE LA DRNSMO ', '1', '20', '80 a 90 %', '65 a 80 %', 'menor a 60 %', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '60 a 65 %', '60 a 65 %', '60 a 65 %', '60 a 65 %', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (950, 'GUDI811029', 'Revisión y análisis de viabilidad jurídica acordes a las Declaratorias de las Áreas Naturales Protegidas, los Programas de Manejos, y a la normatividad ambiental vigente para la emisión de autorizaciones y/o prórrogas por parte de la Dirección Regional, a favor de los promoventes a fin de realizar actividades dentro de la Áreas Naturales Protegidas adscritas a la Región Frontera Sur, Istmo y Pacifico Sur.', '4', '25', 'Se revisan y analizan al 100% las autorizaciones y/o prórrogas para ser emitidas por la Dirección Regional', 'Se revisan y analizan al 80% las autorizaciones y/o prórrogas para ser emitidas por la Dirección Regional', 'Se revisan y analizan al 60% las autorizaciones y/o prórrogas para ser emitidas por la Dirección Regional', '90', 'Revisar las Opiniones Técnicas y en su caso, incorporar la normatividad ambiental aplicable, tratándose de obras y/o actividades que se pretendan autorizar las autoridades competentes dentro de las Áreas Naturales Protegidas adscritas a la Dirección Regional Frontera Sur, Istmo y Pacifico Sur en materia de cambio uso de suelo, impacto ambiental, aprovechamiento forestal, zona federal marítimo terrestre y ambientes costeros, entre otros.', '4', '25', 'Se revisan el 100% de las Opiniones Técnicas elaboradas', 'Se revisan el 80% de las Opiniones Técnicas elaboradas', 'Se revisan el 60% de las Opiniones Técnicas elaboradas', '90', 'Atención y seguimiento a las solicitudes de acceso a la información pública realizadas a través de la Plataforma Nacional de Transparencia, que se reciban en relación con la circunscripción territorial de la Dirección Regional Frontera Sur, Istmo y Pacifico Sur.', '4', '30', 'Se atienden el 100% de las solicitudes recibidas en la Dirección Regional', 'Se atienden el 80% de las solicitudes recibidas en la Dirección Regional', 'Se atienden el 60% de las solicitudes recibidas en la Dirección Regional', '90', 'Asesoría legal a las Unidades Administrativas de la Dirección Regional Frontera Sur, Istmo y Pacifico Sur, en las actividades que se efectúen para el manejo y administración de las Áreas Naturales Protegidas.', '4', '10', 'Se atienden al 100% el apoyo legal solicitado a las Unidades Administrativas de la Dirección Regional', 'Se atienden al 80% el apoyo legal solicitado a las Unidades Administrativas de la Dirección Regional', 'Se atienden al 60% el apoyo legal solicitado a las Unidades Administrativas de la Dirección Regional', '90', 'Certificación de documentos que obren en las Unidades Administrativas de la Dirección Regional Frontera Sur, Istmo y Pacifico Sur, para su exhibición en procedimientos judiciales, contenciosos, administrativos, y en general, para cualquier proceso, procedimiento o carpetas de investigación.', '4', '10', 'Se certifican el 100% de los documentos solicitados ', 'Se certifican el 80% de los documentos solicitados ', 'Se certifican el 60% de los documentos solicitados ', '90', NULL, NULL, 1, '2024', NULL, NULL, NULL, NULL, NULL, 'Se revisan y analizan al 70% las autorizaciones y/o prórrogas para ser emitidas por la Dirección Regional', 'Se revisan el 70% de las Opiniones Técnicas elaboradas', 'Se atienden el 70% de las solicitudes recibidas en la Dirección Regional', 'Se atienden al 70% el apoyo legal solicitado a las Unidades Administrativas de la Dirección Regional', 'Se certifican el 70% de los documentos solicitados ', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
