INSERT INTO `sed_individuales` VALUES (955, 'BOVG550912', '•	COORDINAR EL PROGRAMA DE VIGILANCIA TURÍSTICA Y PESQUERA CON LA AUTORIDAD CORRESPONDIENTE, CON EL FIN DE VERIFICAR EL CUMPLIMIENTO DE LAS REGULACIONES EN EL ÁREA MARINA Y TERRESTRE DEL ANP.', '1', '20', 'REALIZAR DE ENTRE 100 A 90 RECORRIDOS DE VIGILANCIA EN EL ÁREA NATURAL PROTEGIDA', 'REALIZAR DE ENTRE 89 A 70 RECORRIDOS DE VIGILANCIA EN EL ÁREA NATURAL PROTEGIDA', 'MENOS DE 60 RECORRIDOS', NULL, '•	COORDINAR EL PROGRAMA DE VIGILANCIA TURÍSTICA Y PESQUERA EN COORDINACIÓN CON LAS AUTORIDADES CORRESPONDIENTES (PROFEPA-CONAPESCA-SEMAR), CON EL FIN DE VERIFICAR EL CUMPLIMIENTO DE LAS REGULACIONES EN EL AREA MARINA Y TERRESTRE DEL ANP.', '1', '20', 'REALIZAR DE ENTRE 7 A 5 OPERATIVOS EN COORDINACIÓN CON OTRAS INSTITUCIONES FEDERALES EN EL ANP.', 'REALIZAR DE ENTRE 4 A 3 OPERATIVOS EN COORDINACIÓN CON OTRAS INSTITUCIONES FEDERALES EN EL ANP.', 'REALIZAR DE ENTRE 2 A 1 OPERATIVOS EN COORDINACIÓN CON OTRAS INSTITUCIONES FEDERALES EN EL ANP.', NULL, '•	REVISAR, CAPTURAR Y DAR SEGUIMIENTO A LA ELABORACIÓN DEL PROGRAMA OPERATIVO ANUAL Y SUS INFORMES TRIMESTRALES DEL ÁREA DE PROTECCIÓN DE FLORA Y FAUNA BALANDRA\r\n\r\n', '1', '20', 'REVISAR, CAPTURAR Y DAR SEGUIMIENTO A LA ELABORACIÓN DE 4 INFORMES DEL PROGRAMA OPERATIVO ANUAL DEL ÁREA DE PROTECCIÓN DE FLORA Y FAUNA BALANDRA', 'REVISAR, CAPTURAR Y DAR SEGUIMIENTO A LA ELABORACIÓN DE 3 INFORMES DEL PROGRAMA OPERATIVO ANUAL DEL ÁREA DE PROTECCIÓN DE FLORA Y FAUNA BALANDRA', 'REVISAR, CAPTURAR Y DAR SEGUIMIENTO A LA ELABORACIÓN DE 1 INFORME DEL PROGRAMA OPERATIVO ANUAL DEL ÁREA DE PROTECCIÓN DE FLORA Y FAUNA BALANDRA', NULL, '•	COORDINAR LAS ACTIVIDADES DE VIGILANCIA Y MONITOREO COMUNITARIO QUE REALIZAN LOS GRUPOS COMUNITARIOS EN EL APFF BALANDRA', '10', '20', 'COORDINAR EL 80 AL 90 % DE LAS ACTIVIDADES DE VIGILANCIA Y MONITOREO COMUNITARIO QUE REALIZAN LOS GRUPOS COMUNITARIOS EN EL APFF BALANDRA', 'COORDINAR EL 60 AL 79 % DE LAS ACTIVIDADES DE VIGILANCIA Y MONITOREO COMUNITARIO QUE REALIZAN LOS GRUPOS COMUNITARIOS EN EL APFF BALANDRA', 'MENOS DEL 50 % DE LAS ACTIVIDADES DE VIGILANCIA Y MONITOREO COMUNITARIO QUE REALIZAN LOS GRUPOS COMUNITARIOS EN EL APFF BALANDRA', NULL, '•	COORDINAR LAS ACTIVIDADES DE RESTAURACIÓN ECOLÓGICA QUE REALIZAN LOS GRUPOS COMUNITARIOS EN EL APFF BALANDRA', '10', '20', 'COORDINAR EL 80 AL 90% DE LAS ACTIVIDADES DE RESTAURACIÓN ECOLÓGICA QUE REALIZAN LOS GRUPOS COMUNITARIOS EN EL APFF BALANDRA', 'COORDINAR EL 60 AL 79 % DE LAS ACTIVIDADES DE RESTAURACIÓN ECOLÓGICA QUE REALIZAN LOS GRUPOS COMUNITARIOS EN EL APFF BALANDRA', 'MENOS DEL 50 % COORDINAR EL 50 % DE LAS ACTIVIDADES DE RESTAURACIÓN ECOLÓGICA QUE REALIZAN LOS GRUPOS COMUNITARIOS EN EL APFF BALANDRA', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'REALIZAR DE ENTRE 69 A 60 RECORRIDOS DE VIGILANCIA EN EL ÁREA NATURAL PROTEGIDA', 'MENOS DE 3 OPERATIVOS', 'REVISAR, CAPTURAR Y DAR SEGUIMIENTO A LA ELABORACIÓN DE 2 INFORMES DEL PROGRAMA OPERATIVO ANUAL DEL ÁREA DE PROTECCIÓN DE FLORA Y FAUNA BALANDRA', 'COORDINAR EL 50 % DE LAS ACTIVIDADES DE VIGILANCIA Y MONITOREO COMUNITARIO QUE REALIZAN LOS GRUPOS COMUNITARIOS EN EL APFF BALANDRA', 'COORDINAR EL 50 % COORDINAR EL 50 % DE LAS ACTIVIDADES DE RESTAURACIÓN ECOLÓGICA QUE REALIZAN LOS GRUPOS COMUNITARIOS EN EL APFF BALANDRA', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
