INSERT INTO `sed_individuales` VALUES (959, 'TOMJ740303', 'Mantener actualizado los registros de los usuarios, altas, bajas y modificaciones, dentro de la plataforma del sistema de Directorio Activo y del sistema de Correo de la institución', '7', '30', 'Registros actualizados con una diferencia de movimientos de no mas de 15 dias', 'Registros actualizados con una diferencia de movimientos de no mas de 15 dias con errores de captura', 'Registros actualizados con una diferencia de movimientos de mas de 30 dias', NULL, 'Atender incidentes y movimientos de los servicios proporcionados por las plataformas de infraestructura de telecomunicaciones y de servidores actual, así como de su registro en la bitácora correspondiente.', '2', '30', 'Reportes atendidos con tiempo de resolución de menos de 1 hora a satisfacción del usuario', 'Reportes atendidos con tiempo de resolución de 2 a 3 horas con visto bueno del usuario.', 'Reportes atendidos con tiempo de resolución mayor a 12 horas con aceptacion del usuario', NULL, 'Atender y dar seguimiento a generación de respaldos de los activos de información crítica de la institución, su registro en bitácora, entrega de copia a las áreas solicitantes y/o resguardo de copia de los activos de respaldo.', '1', '25', 'Respaldos generados y/o entregados al 6 dias despues de lo calendarizado', 'Respaldos generados y/o entregados en los dias del 6 al 10 despues de lo calendarizado', 'Respaldos generados y/o entregados despues del dia 30 de lo calendarizado', NULL, 'Elaboración de documentos de técnicos de los servicios prestados por la infraestructura de servidores datos de la institución, para cumplimiento en los procesos Institucionales vigentes, para difusión y conocimiento general o por necesidades especificas del área que sean requeridas', '1', '15', 'Elaboración y entrega de todos los documentos encargados', 'Elaboración y entrega de todos los documentos encargados con erratas', 'La no elaboración y entrega de todos los documentos encargados', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Registros actualizados con una diferencia de movimientos de mas de 15 dias', 'Reportes atendidos con tiempo de resolución mayor a 3 horas con aceptacion del usuario', 'Respaldos generados y/o entregados despues del dia 10 de lo calendarizado', 'La elaboración y entrega de todos los documentos encargados con erratas y fuera del tiempo convenido', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (960, 'ZAVA910414', 'EJECUTAR Y DAR SEGUIMIENTO A PROYECTOS DE LOS PROGRAMAS DE SUBSIDIOS.', '10', '20', 'EJECUTAR Y DAR SEGUIMIENTO DEL 100% DE LOS PROYECTOS DE LOS PROGRAMAS DE SUBSIDIO.', 'EJECUTAR Y DAR SEGUIMIENTO DEL 95% DE LOS PROYECTOS DE LOS PROGRAMAS DE SUBSIDIO.', 'EJECUTAR Y DAR SEGUIMIENTO DEL 80% DE LOS PROYECTOS DE LOS PROGRAMAS DE SUBSIDIO.', NULL, 'RECOPILAR, VERIFICAR Y VALIDAR LA INFORMACIÓN TÉCNICA DE LOS PROYECTOS DE PROGRAMAS DE SUBSIDIOS PARA LA CORRECTA INTEGRACIÓN DE LOS EXPEDIENTES EN APEGOS A LAS REGLAS DE OPERACIÓN', '10', '30', 'REVISAR Y VALIDAR TÉCNICAMENTE DEL 100% DE LOS EXPEDIENTES INTEGRADOS DE PROYECTOS DE LOS PROGRAMAS DE SUBSIDIO AUTORIZADOS.', 'REVISAR Y VALIDAR TÉCNICAMENTE DEL 95% DE LOS EXPEDIENTES INTEGRADOS DE PROYECTOS DE LOS PROGRAMAS DE SUBSIDIO AUTORIZADOS.', 'REVISAR Y VALIDAR TÉCNICAMENTE DEL 80% DE LOS EXPEDIENTES INTEGRADOS DE PROYECTOS DE LOS PROGRAMAS DE SUBSIDIO AUTORIZADOS.', NULL, 'CAPTURAR Y DAR SEGUIMIENTO A LOS PROYECTOS DE PROGRAMAS DE SUBSIDIOS EN LOS SISTEMAS INFORMÁTICOS', '10', '30', 'CAPTURA Y SEGUIMIENTO DEL 100% DE LOS PROYECTOS EN LOS SISTEMAS INFORMÁTICOS DE LOS PROGRAMAS DE SUBSIDIO.', 'CAPTURA Y SEGUIMIENTO DEL 95% DE LOS PROYECTOS EN LOS SISTEMAS INFORMÁTICOS DE LOS PROGRAMAS DE SUBSIDIO.', 'CAPTURA Y SEGUIMIENTO DEL 80% DE LOS PROYECTOS EN LOS SISTEMAS INFORMÁTICOS DE LOS PROGRAMAS DE SUBSIDIO.', NULL, 'ELABORACIÓN DE INFORMES DE AVANCES FÍSICOS Y FINANCIEROS DE LOS PROGRAMAS DE SUBSIDIO', '10', '20', 'REALIZAR EL 100% DE INFORMES DE AVANCES FISICOS Y FINANCIEROS DE LOS PROGRAMAS DE SUBSIDIOS.', 'REALIZAR EL 95% DE INFORMES DE AVANCES FISICOS Y FINANCIEROS DE LOS PROGRAMAS DE SUBSIDIOS.', 'REALIZAR EL 80% DE INFORMES DE AVANCES FISICOS Y FINANCIEROS DE LOS PROGRAMAS DE SUBSIDIOS.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'EJECUTAR Y DAR SEGUIMIENTO DEL 50% DE LOS PROYECTOS DE LOS PROGRAMAS DE SUB