INSERT INTO `sed_individuales` VALUES (965, 'NAHE710812', 'Representar y asesorar legalmente a la Dirección Regional y sus Unidades Administrativas en el Desahogo de los procedimientos jurisdiccionales y administrativas.', '10', '50', 'Representar y asesorar legalmente a la Dirección Regional y sus Unidades Administrativas en el Desahogo de los procedimientos jurisdiccionales y administrativas.', 'Representar y asesorar legalmente a la Dirección Regional y sus Unidades Administrativas en el Desahogo de los procedimientos jurisdiccionales y administrativas en menos del 100 %', 'Representar y asesorar legalmente a la Dirección Regional y sus Unidades Administrativas en el Desahogo de los procedimientos jurisdiccionales y administrativas en menos del 60 %', NULL, 'Rendir opinión previa revisión jurídica sobre concesiones, permisos y demás autorizaciones en materia de ANP dentro de la circunscripción de la Dirección Regional', '10', '25', 'Rendir opinión previa revisión jurídica sobre concesiones, permisos y demás autorizaciones en materia de ANP dentro de la circunscripción de la Dirección Regional', 'Rendir opinión previa revisión jurídica sobre concesiones, permisos y demás autorizaciones en materia de ANP dentro de la circunscripción de la Dirección Regional en menos del 100 %', 'Rendir opinión previa revisión jurídica sobre concesiones, permisos y demás autorizaciones en materia de ANP dentro de la circunscripción de la Dirección Regional en menos del 60 %', NULL, 'Atender los requerimientos de asesorías de las diversas unidades administrativas en la elaboración de documentos e instrumentos jurídicos relacionados en el ámbito de su competencia.', '10', '25', 'Rendir opinión previa revisión jurídica sobre concesiones, permisos y demás autorizaciones en materia de ANP dentro de la circunscripción de la Dirección Regional', 'Rendir opinión previa revisión jurídica sobre concesiones, permisos y demás autorizaciones en materia de ANP dentro de la circunscripción de la Dirección Regional en menos del 100 %', 'Rendir opinión previa revisión jurídica sobre concesiones, permisos y demás autorizaciones en materia de ANP dentro de la circunscripción de la Dirección Regional en menos del 60 %', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Representar y asesorar legalmente a la Dirección Regional y sus Unidades Administrativas en el Desahogo de los procedimientos jurisdiccionales y administrativas en menos del 70 %', 'Rendir opinión previa revisión jurídica sobre concesiones, permisos y demás autorizaciones en materia de ANP dentro de la circunscripción de la Dirección Regional en menos del 70 %', 'Rendir opinión previa revisión jurídica sobre concesiones, permisos y demás autorizaciones en materia de ANP dentro de la circunscripción de la Dirección Regional en menos del 70 %', NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (966, 'GABC880503', 'PARTICIPAR EN LA ELABORACIÓN Y CUMPLIMENTO DEL PROGRAMA OPERATIVO ANUAL DEL ÁREA NATURAL PROTEGIDA', '10', '30', 'EL PROGRAMA OPERATIVO ANUAL FUE REALIZADO Y SE CUMPLIO EN TIEMPO Y FORMA EN LA PROGRAMACION DEL EJERCICIO EN SU TOTALIDAD	', 'EL PROGRAMA OPERATIVO ANUAL FUE ELABORADO Y SE CUMPLIO CON EL 50% AL 99% DE LA PROGRAMACION DEL EJERCICIO DE MANERA PARCIAL', 'EL PROGRAMA OPERATIVO ANUAL NO FUE ELABORADO PARA EL PRESENTE EJERCICIO	', NULL, 'CONTRIBUIR CON LA IMPLEMENTACION DE LOS CONCEPTOS DE APOYO FINANCIADOS POR PROGRAMAS DE SUBSIDIOS, EN LAS COMUNIDADES RURALES INVOLUCRADAS EN LAS ANPS Y LA CONSERVACION DE LAS MISMAS, DENTRO DE SU ZONA DE INFLUENCIA\r\n\r\n\r\n', '10', '40', 'DAR SEGUIMIENTO EN SU TOTALIDAD A LA EJECUCION DE PROYECTOS Y CONCEPTOS DE APOYO AUTORIZADOS EN LOS PROGRAMAS DE SUBSIDIO	', 'DAR SEGUIMIENTO A LA EJECUCION DE PROYECTOS Y CONCEPTOS DE APOYO AUTORIZADOS EN LOS PROGRAMAS DE SUBSIDIO DEL 50% AL 99%', 'NO DAR SEGUIMIENTO A LA EJECUCION DE PROYECTOS Y CONCEPTOS DE APOYO AUTORIZADOS EN LOS PROGRAMAS DE SUBSIDIO', NULL, 'PARTICIPAR EN RECORRIDOS DE VIGILANCIA DEL AREA NATURAL PROTEGIDA\r\n\r\n\r\n', '10', '10', 'SE PARTICIPO EN LA TOTALIDAD DE LOS RECORRIDOS DE VIGILANCIA REALIZADOS EN EL ANP	', 'SE PARTICIPO ENTRE EL 50% Y 99% DE LOS RECORRIDOS DE VIGILANCIA REALIZADOS EN EL ANP	', 'NO SE PARTICIPÓ EN LOS RECORRIDOS DE VIGILANCIA EN EL ANP', NULL, 'PARTICIPAR EN LAS ACCIONES DE MANEJO INTEGRAL DEL FUEGO REALIZADAS EN EL ANP	\r\n', '9', '10', 'SE PARTICIPO EN LA TOTALIDAD DE LAS ACCIONES DE MANEJO INTEGRAL DEL FUEGO REALIZADAS EN EL ANP	', 'SE PARTICIPO ENTRE EL 50% Y 99% DE LAS ACCIONES DE MANEJO INTEGRAL DEL FUEGO REALIZADAS EN EL ANP	', 'NO SE PARTICIPO EN LAS ACCIONES DE MANEJO INTEGRAL DEL FUEGO REALIZADAS EN EL ANP	', NULL, 'PARTICIPAR EN LAS ACCIONES DEL CONSEJO ASESOR DE LA RESERVA DE LA BIOSFERA LA MICHILIA', '10', '10', 'SE PARTICIPO EN LA TOTALIDAD DE LAS ACCIONES DEL CONSEJO ASESOR DE LA RESERVA DE LA BIOSFERA LA MICHILIA', 'SE PARTICIPO ENTRE EL 50% Y 99% DE LAS ACCIONES DEL CONSEJO ASESOR DE LA RESERVA DE LA BIOSFERA LA MICHILIA', 'NO SE TUBO PARTICIPACION EN LAS ACCIONES DEL CONSEJO ASESOR DE LA RESERVA DE LA BIOSFERA LA MICHILIA', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'EL PROGRAMA OPERATIVO ANUAL FUE ELABORADO Y SE CUMPLIO CON EL 1% AL 50% DE LA PROGRAMACION DEL EJERCICIO DE MANERA PARCIAL', 'DAR SEGUIMIENTO A LA EJECUCION DE PROYECTOS Y CONCEPTOS DE APOYO AUTORIZADOS EN LOS PROGRAMAS DE SUBSIDIO DEL 1% AL 50%', 'SE PARTICIPO ENTRE EL 1% Y 50% DE LOS RECORRIDOS DE VIGILANCIA REALIZADOS EN EL ANP	', 'SE PARTICIPO ENTRE EL 1% Y 50% DE LAS ACCIONES DE MANEJO INTEGRAL DEL FUEGO REALIZADAS EN EL ANP	', 'SE PARTICIPO ENTRE EL 1% Y 50% DE LAS ACCIONES DEL CONSEJO ASESOR DE LA RESERVA DE LA BIOSFERA LA MICHILIA', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (967, 'CEPE690714', 'GESTIONAR, EJERCER, Y SUPERVISAR LA CORRECTA APLICACIÓN DE LA LEY FEDERAL DE DERECHOS,  EN EL CENTRO MEXICANO DE LA TORTUGA. 	', '10', '20', '80% DE FORMAS VALORADAS (BRAZALETES) DEL COBRO DE DERECHOS REALIZADOS EN EL CENTRO MEXICANO DE LA TORTUGA.', '60% DE FORMAS VALORADAS (BRAZALETES) DEL COBRO DE DERECHOS REALIZADOS EN EL CENTRO MEXICANO DE LA TORTUGA.', 'NO SE LLEVAN A CABO EL COBRO DE FORMAS VALORADAS (BRAZALETES) DEL COBRO DE DERECHOS REALIZADOS EN EL CENTRO MEXICANO DE LA TORTUGA, EN EL SANTUARIO PLAYA ESCOBILLA. ', NULL, 'PROMOVER Y SUPERVISAR LOS LEVANTAMIENTOS DE LOS INVENTARIOS ALEATORIOS Y EL GENERAL DE TODOS LO BIENES MUEBLES ASIGNADOS AL CENTRO MEXICANO DE LA TORTUGA.\r\n\r\n\r\n', '10', '20', 'DIRIGIR Y COORDINAR LAS ACTIVIDADES DEL 90% PARA EL LEVANTAMIENTO DE LOS INVENTARIOS ALEATORIOS Y EL GENERAL DEL CENTRO MEXICANO DE LA TORTUGA. ', 'DIRIGIR Y COORDINAR LAS ACTIVIDADES DEL 70% PARA EL LEVANTAMIENTO DE LOS INVENTARIOS ALEATORIOS Y EL GENERAL DEL CENTRO MEXICANO DE LA TORTUGA. ', 'DIRIGIR Y COORDINAR LAS ACTIVIDADES MENOS DEL 50% PARA EL LEVANTAMIENTO DE LOS INVENTARIOS ALEATORIOS Y EL GENERAL DEL CENTRO MEXICANO DE LA TORTUGA. ', NULL, 'ELABORAR 4 INFORMES TRIMESTRALES, Y ACTUALIZAR EL PROGRAMA ANUAL DE ADQUISICIONES, ARRENDAMIENTOS Y SERVICIOS.\r\n\r\n', '10', '20', 'SE ELABORAN EL 90%  DE LOS INFORMES TRIMESTRALES  ', 'SE ELABORAN EL 80%  DE LOS INFORMES TRIMESTRALES ', 'SE ELABORAN EL 30%  DE LOS INFORMES TRIMESTRALES ', NULL, 'SE ELABORAN Y SE FORMALIZAN LAS CONTRATACIONES DE TODOS LOS BIENES Y SERVICIOS QUE REQUIERA EL CENTRO MEXICANO DE LA TORTUGA.\r\n', '10', '20', 'SE ELABORAN Y SE FORMALIZAN EL 80% DE LOS  CONTRATOS DE BIENES Y SERVICIOS DEL CENTRO MEXICANO DE LA TORTUGA. ', 'SE ELABORAN Y SE FORMALIZAN EL 60% DE LOS  CONTRATOS DE BIENES Y SERVICIOS DEL CENTRO MEXICANO DE LA TORTUGA. ', 'SE ELABORAN Y SE FORMALIZAN EL 20% DE LOS  CONTRATOS DE BIENES Y SERVICIOS DEL CENTRO MEXICANO DE LA TORTUGA. ', NULL, 'SUPERVISAR EL ESTADO Y USO CORRECTO DEL PARQUE VEHICULAR ASIGNADO AL CENTRO MEXICANO DE LA TORTUGA, ASÍ COMO EL SERVICIO DE MANTENIMIENTO PREVENTIVO Y CORRECTIVO.\r\n', '10', '20', 'SE VERIFICA 80% DEL ESTADO Y USO CORRECTO DE LOS VEHÍCULOS Y 1 MOTOR FUERA DE BORDA, ASIGNADOS AL CENTRO MEXICANO DE LA TORTUGA, ASÍ COMO EL SERVICIO DE MANTENIMIENTO PREVENTIVO Y CORRECTIVO.', 'SE VERIFICA 60% DEL ESTADO Y USO CORRECTO DE LOS VEHÍCULOS Y 1 MOTOR FUERA DE BORDA, ASIGNADOS AL CENTRO MEXICANO DE LA TORTUGA, ASÍ COMO EL SERVICIO DE MANTENIMIENTO PREVENTIVO Y CORRECTIVO.', 'SE VERIFICA 20% DEL ESTADO Y USO CORRECTO DE LOS VEHÍCULOS Y 1 MOTOR FUERA DE BORDA, ASIGNADOS AL CENTRO MEXICANO DE LA TORTUGA, ASÍ COMO EL SERVICIO DE MANTENIMIENTO PREVENTIVO Y CORRECTIVO.', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '30% DE FORMAS VALORADAS (BRAZALETES) DEL COBRO DE DERECHOS REALIZADOS EN EL CENTRO MEXICANO DE LA TORTUGA.', 'DIRIGIR Y COORDINAR LAS ACTIVIDADES DEL 50% PARA EL LEVANTAMIENTO DE LOS INVENTARIOS ALEATORIOS Y EL GENERAL DEL CENTRO MEXICANO DE LA TORTUGA. ', 'SE ELABORAN EL 50%  DE LOS INFORMES TRIMESTRALES ', 'SE ELABORAN Y SE FORMALIZAN EL 40% DE LOS  CONTRATOS DE BIENES Y SERVICIOS DEL CENTRO MEXICANO DE LA TORTUGA. ', 'SE VERIFICA 40% DEL ESTADO Y USO CORRECTO DE LOS VEHÍCULOS Y 1 MOTOR FUERA DE BORDA, ASIGNADOS AL CENTRO MEXICANO DE LA TORTUGA, ASÍ COMO EL SERVICIO DE MANTENIMIENTO PREVENTIVO Y CORRECTIVO.', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (968, 'ZAMM810821', '1.	Apoyar y ejecutar la planeación del presupuesto regional, presentando informes financieros, para garantizar un eficiente cierre de periodo anual, mediante 26 Estados del Ejercicio de las ANP´S y la Dirección Regional, considerando los tiempos presupuestales asignados, ejercidos, comprometidos y disponibles por partida de los presupuestos fiscales y de subsidios.', '10', '20', '90-100', '70-89', 'menos del 50', NULL, '2.	Capturar, conciliar y apoyar en los procesos de la contabilidad general y presupuestal a través de las distintas plataformas (SAACG-SICOP-SIAFF), por los recursos fiscales autorizados a la Dirección Regional Centro y Eje Neovolcánico, obteniendo 36 conciliaciones bancarias.', '10', '20', '90-100', '70-89', 'menos del 50', NULL, '3.	Recibir y validar las suficiencias y adecuaciones presupuestales, elaboradas de acuerdo con la normatividad vigente, dando seguimiento para la integración de 750 expedientes correctos y proceder al pago por medio de los sistemas SICOP, SIAFF. COMPRANET, CADENAS PRODUCTIVAS.', '10', '20', '90-100', '70-89', 'menos del 50', NULL, '4.	Concentrar y alimentar base de datos de todos los pagos realizados mensualmente (proyectos, gasto corriente, viáticos, pasajes, intereses, gastos de operación, etc.) para generar conciliaciones presupuestales y contables, determinando los impuestos retenidos y enterados para posterior proporcionar los datos necesarios para presentación de declaraciones informativas y cumplir con las obligaciones fiscales a las que estamos sujetos.', '10', '20', '90-100', '70-89', 'menos del 50', NULL, '5.	Llevar el procedimiento completo con la nueva normatividad de los compromisos en el sistema SICOP mediante contratos formalizados para una mejor ejecución presupuestal de las ANP´S de manera mensual. ', '10', '20', '90-100', '70-89', 'menos del 50', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '50-69', '50-69', '50-69', '50-69', '50-69', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (969, 'GODM840531', 'Revisar, validar y capturar los documentos soporte para la comprobación del gasto, así como la suficiencia presupuestal del rubro de viáticos y pasajes, tanto devengados como anticipados de los recursos autorizados para el gasto fiscal y de programas de subsidio para pago por las distintas plataformas contables y presupuestales (SAACG-SICOP-SIAFF).', '10', '20', '90-100', '70-89', 'menos del 50', NULL, 'Registrar y elaborar hojas de control con las solicitudes de pago y oficios de comisión del personal adscrito en las ANPs y oficina regional de la Dirección Regional Centro y Eje Neovolcánico en el rubro de viáticos y pasajes, tanto devengados como anticipados de los recursos autorizados para el gasto fiscal y de programas de subsidio. ', '10', '20', '90-100', '70-89', 'menos del 50', NULL, 'Elaborar tablas de los gastos de representación y viáticos de comisiones realizadas trimestralmente por el personal de la Dirección Regional Centro y Eje Neovolcánico para los informes presentados ante el Sistema de Portales de Transparencia.', '10', '20', '90-100', '70-89', 'menos del 50', NULL, 'Dar soporte para el mantenimiento de la infraestructura y dominio de los equipos de cómputo con los que cuenta la dependencia, así como a los usuarios en forma remota y presencial para instalación de software en los sistemas operativos, mediante la recabación de necesidades en Telecomunicaciones (voz IP, Líneas analógicas, digitales, servicios de internet, conmutadores, etc.) y de  consumibles de cómputo en las Áreas Naturales Protegidas de la Dirección Regional Centro y Eje Neovolcánico en coordinación con la subdirección de informática.', '10', '20', '90-100', '70-89', 'menos del 50', NULL, 'Actualizar y dar seguimiento a los reportes de resguardos de los equipos de cómputo arrendados 2025 correspondientes a multifuncionales y equipos de computo', '10', '20', '90-100', '70-89', 'menos del 50', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '50-69', '50-69', '50-69', '50-69', '50-69', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (970, 'JUFI680124', 'Apoyar en la recopilación e integración de información para atender solicitudes de información relativas a los Humedales de Importancia Internacional en ANP de competencia de la CONANP.', '4', '30', '80% o más de solicitudes atendidas', '50% de solicitudes atendidas', '20% de solicitudes atendidas', NULL, 'Contribuir en el proceso de actualización de Fichas Informativas Ramsar de las ANP de competencia de la CONANP.', '5', '20', 'Contribución en el 80% o más de las Fichas Informativas de los Sitios Ramsar actualizadas', 'Contribución en el 50% de las Fichas Informativas de los Sitios Ramsar actualizadas', 'Contribución en el 20% de las Fichas Informativas de los Sitios Ramsar actualizadas ', NULL, 'Colaborar en la organización de las Sesiones del Comité Nacional de Humedales y en las reuniones de los Grupos de Trabajo conformados en el marco de las sesiones ordinarias y/o extraordinarias.', '4', '20', 'Colaborar en la organización del 80% o más de las sesiones ', 'Colaborar en la organización del 50% de las sesiones', 'Colabora en la organización del 20% de las sesiones', NULL, 'Apoyar en la integración de información y organización para la participación de la CONANP en las reuniones nacionales e internacionales en el marco de la Convención Ramsar. ', '8', '30', 'Apoyar en 80% o  más en la integración de información y organización para la participación de la CONANP', 'Apoyar en 50% en la integración de información y organización para la participación de la CONANP', 'Apoyar en 20% en la integración de información y organización para la participación de la CONANP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '10% de solicitudes atendidas', 'Contribución en el 10% de las Fichas Informativas de los Sitios Ramsar actualizadas', 'Colaborar en la organización del 10% de las sesiones', 'Apoyar en 10% en la Integración de información y organización para la participación de la CONANP', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (1170, 'CAHJ790102', 'Administración, supervisión y seguimiento de proyectos de subsidio (aprobados) orientados al monitoreo biológico de especies prioritarias y/o en riesgo y grupos biológicos de interés con participación comunitaria.', '10', '30', 'Administración, supervisión y seguimiento del 100% de los proyectos orientados al monitoreo biológico de especies prioritarias y/o en riesgo y grupos biológicos de interés con participación comunitaria.', 'Administración, supervisión y seguimiento del 75% de los proyectos orientados al monitoreo biológico de especies prioritarias y/o en riesgo y grupos biológicos de interés con participación comunitaria.', 'Administración, supervisión y seguimiento del 25% de los proyectos orientados al monitoreo biológico de especies prioritarias y/o en riesgo y grupos biológicos de interés con participación comunitaria.', NULL, 'Atención y coadyuvancia de los conflictos entre los carnívoros silvestres y las actividades ganaderas en el ANP y su área de influencia, mediante el reporte oportuno y levantamiento de evidencias para aplicar al seguro de muerte por ataque de depredadores operado por FANCAMPO/FANVIDA.', '8', '20', 'Atención inmediata (dentro de 24 a 48 hrs a partir del evento) y levantamiento de evidencias suficientes y de calidad de cada evento de depredación o lesiones de ganados doméstico causado por el ataque de carnívoros silvestres.', 'Atención entre las 48 y 72 hrs a partir del evento y levantamiento de evidencias suficientes y de calidad de cada evento de depredación o lesiones de ganados doméstico causado por el ataque de carnívoros silvestres.', 'No se realizo la atención del evento de depredación o lesiones de ganados doméstico causado por el ataque de carnívoros silvestres, recibido', NULL, 'Facilitación de foros, talleres o cursos de capacitación orientados a la conservación de especies prioritarias, atención de amenazas y/o hábitat críticos.', '1', '20', 'Facilitación de tres (3) foros, talleres o cursos de capacitación orientados a la conservación de especies prioritarias, atención de amenazas y/o hábitat críticos.', 'Facilitación de dos (2) foros, talleres o cursos de capacitación orientados a la conservación de especies prioritarias, atención de amenazas y hábitat críticos. ', 'No se realizo ningún foro, talleres o cursos de capacitación orientados a la conservación de especies prioritarias, atención de amenazas y/o hábitat críticos', NULL, 'Promover la realización de prácticas de aprovechamiento/uso sustentable en el ANP.', '1', '20', 'Integrar un diagnóstico de oportunidades y desafíos para la observación de aves que impulse el desarrollo comunitario en tres (3) localidades.', 'Integrar un diagnóstico de oportunidades y desafíos para la observación de aves que impulse el desarrollo comunitario en dos (2) localidades.', 'No se integro ningún diagnóstico de oportunidades y desafíos para la observación de aves', NULL, 'Gestión y administración eficiente de los recursos financieros para el mantenimiento de la flota vehicular asignada al ANP, logrando el cumplimiento de las actividades programadas en campo.', '10', '10', 'Gestión y aplicación de los recursos de manera oportuna, contando con la funcionalidad del 80% de la flota vehicular.', 'Gestión y aplicación de los recursos de manera oportuna, contando con la funcionalidad del 60% de la flota vehicular.', 'Gestión y aplicación de los recursos de manera tardía, contando con la funcionalidad del 20% de la flota vehicular.', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Administración, supervisión y seguimiento del 50% de los proyectos orientados al monitoreo biológico de especies prioritarias y/o en riesgo y grupos biológicos de interés con participación comunitaria.', 'Atención después de 72 hrs a partir del evento y levantamiento de evidencias insuficientes y de baja calidad de cada evento de depredación o lesiones de ganados doméstico causado por el ataque de carnívoros silvestres.', 'Facilitación de uno (1) foros, taller o curso de capacitación orientado a la conservación de especies prioritarias, atención de amenazas y hábitat críticos.', 'Integrar un diagnóstico de oportunidades y desafíos para la observación de aves que impulse el desarrollo comunitario en una (1) localidad.', 'Gestión y aplicación de los recursos de manera tardía, contando con la funcionalidad del 40% de la flota vehicular.', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
