INSERT INTO `sed_individuales` VALUES (972, 'ZUMA670724', 'elaboración del programa operativo anual', '5', '30', 'se elabora el programa operativo y se cumple con el 100 porciento de las metas planteadas en el programa operativo anual', 'se elabora el programa operativo anual y no se alcanza el 80 porciento de las metas establecidas en el programa operativo anual', 'no se elabora el programa operativo anual', NULL, 'se realiza el cobro de derechos y se recauda 500 mil pesos', '1', '20', 'se recauda 800 mil pesos de cobro de derechos en el año', 'se recauda 700 mil pesos de cobro de derechos en el año', 'no existe la recaudación del cobro de derechos', NULL, 'se coordinan proyectos de investigación para el manejo y conservación de los ecosistemas en la RBCV, con centros de investigación ', '4', '20', '3 proyectos de investigación con 3 instituciones de investigacion y/o académicas', '1 proyecto de investigación y 1 institucion', 'ninguna investigación', NULL, 'se elaboran los informes trimestrales y anual en tiempo y forma, cumpliendo con las metas establecidas', '8', '15', '1 informe anual en tiempo y forma', '1 informe anual no enviado', 'no se elabora el informe', NULL, 'se ejecuta en tiempo y forma el presupuesto de subsidios asignado a la Reserva de la biosfera de Calakmul', '1', '15', 'se ejecuta en tiempo y forma del 71 al100 porciento del presupuesto de subsidios asignados a la Reserva de la Biosfera del  Calakmul', 'se ejecuta el 60 al 70 porciento del presupuesto de subsidios asignados a la Reserva de la Biosfera de calakmul', 'no se ejecuta el presupuesto asignado a subisidios a la RBC', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'se elabora el programa operativo anual  y se cumplen 60 porciento de las metas', 'se recauda 100 mil pesos de cobro de derecho en el año', '1 investigación sin ejecutar', '1 informe anual no concluido en el tiempo', 'se ejecuta menos del 60 porciento del presupuesto de subsidios asignado a la reserva de la Biosfera de Calakmul', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
