INSERT INTO `sed_individuales` VALUES (1078, 'DIQJ691001', 'Impulsar la implementación de actividades productivas sustentables en las comunidades mediante el fortalecimiento en la aplicación del Programa de Conservación para el Desarrollo Sostenible, PROCODES y Programa para la Protección y Restauración de Ecosistemas y Especies Prioritarias, PROREST en la zona de influencia y al interior del complejo Sian Ka\'an', '1', '25', '20 proyectos, 3 curso de capacitación', '10 proyectos, 2 cursos de capacitación', '5 proyecto, 1 curso de capacitación', NULL, 'Realizar reuniones de instalación de comités de contraloría social, comités de seguimiento, así como integrar los expedientes en tiempo y forma de los proyectos que se implementarán en el Complejo Sian Ka\'an, del Programa de Conservación para el Desarrollo Sostenible, PROCODES y del Programa para la Protección y Restauración de Ecosistemas y Especies Prioritarias, PROREST	', '1', '25', 'Integrar 20 comités de seguimiento y de contraloría social, integrar todos los expedientes de los proyectos que se implementarán en el complejo Sian Ka\'an del PROCODES y del PROREST', 'Integrar 10 comités de seguimiento y de contraloría social, integrar todos los expedientes de los proyectos que se implementarán en el complejo Sian Ka\'an del PROCODES y del PRORES', 'Integrar 5 comités de seguimiento y de contraloría social, integrar todos los expedientes de los proyectos que se implementarán en el complejo Sian Ka\'an del PROCODES y del PRORES', NULL, 'Realizar las respectivas visitas de supervisión y seguimiento en campo de los proyectos aprobados para su ejecución de Programa de Conservación para el Desarrollo Sostenible, PROCODES y del Programa para la Protección y Restauración de Ecosistemas y Especies Prioritarias, PROREST, y verificar su correcta ejecución de las acciones plasmadas en los expedientes técnicos y/o términos de referencia, así como realizar los avances tanto físicos y financieros.', '1', '25', 'Realizar 20 visitas de supervisión y seguimiento de los proyectos ', 'Realizar 10 visitas de supervisión y seguimiento de los proyectos ', 'Realizar 5 visitas de supervisión y seguimiento de los proyectos ', NULL, 'Brindar apoyo a los diversos programas que se llevan a cabo en complejo Sian Ka\'an, como son Supervisión y Vigilancia, Incendios forestales, Uso Público, Mantenimiento, Investigación y monitoreo, educación ambiental, entre otros.', '1', '25', 'Apoyar 6 programas', 'Apoyar 4 programas', 'Apoyar 1 programa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '8 proyectos, 1 curso de capacitación', 'Integrar 8 comités de seguimiento y de contraloría social, integrar todos los expedientes de los proyectos que se implementarán en el complejo Sian Ka\'an del PROCODES y del PRORES', 'Realizar 8 visitas de supervisión y seguimiento de los proyectos ', 'Apoyar 3 programas', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
