INSERT INTO `sed_individuales` VALUES (1063, 'VAVH640705', 'IMPLEMENTAR Y COORDINAR PROYECTOS DE RESTAURACIÓN DE ECOSISTEMAS, VIGILANCIA Y MONITOREO COMUNITARIO, COMPATIBLES CON LA ESTRATEGIA DE MANEJO DEL ANP', '4', '25', '90 % DE ACCIONES EJECUTADAS', '85 % DE ACCIONES EJECUTADAS', '50 % DE ACCIONES EJECUTADAS', NULL, 'REALIZAR RECORRIDOS DE VIGILANCIA PARA LA PREVENCIÓN, DETECCIÓN, ATENCIÓN, DENUNCIAS Y DISMINUCIÓN DE ILÍCITOS DENTRO DE LA RESERVA Y SU ZONA DE INFLUENCIA', '1', '25', '15', '10', '5', NULL, 'RENOVAR LA OPERACIÓN OFICIAL DE COMITÉS DE VIGILANCIA COMUNITARIA CON LA FINALIDAD DE QUE SE VIGILE LA RESERVA Y SU ZONA DE INFLUENCIA Y PREVENIR ILÍCITOS AMBIENTALES', '1', '25', '1', 'SE REALIZO EL COMITÉ SIN EMBARGO PROFEPA NO SE LOGRO  CREDENCIALIZAR', 'NO SE REALIZO LA GESTION', NULL, 'IMPULSAR REUNIONES DE CONSEJO ASESOR PARA CONSOLIDAR LA PARTICIPACIÓN DE SECTORES A FAVOR DE LA CONSERVACIÓN Y MANEJO DE LA RESERVA Y SU ZONA DE INFLUENCIA, COMUNIDADES Y EJIDOS DE LA RSERVA, GOBIERNO ESTATAL, MUNICIPAL, OSC´S, UNIVERSIDADES E INSTITUCIONES DE EDUCACIÓN', '2', '25', '1 REUNIÓN CON QUORUM LEGAL', '1 REUNIÓN  SIN QUORUM LEGAL', 'NO SE CONVOCA', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '70 % DE ACCIONES EJECUTADAS', '8', 'LOS BENEFICIARIOS RENUNCIARON AL PROYECTO', '1 REUNIÓN TIPO INFORMATIVA CON MENOS DE 8 CONSEJEROS', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (1064, 'PEOA790531', 'Se promoverán acciones para protección y conservación de las 3 especies de tortugas marinas que anidan en 25 km  del Santuario Playa de Mismaloya mediante la  colecta de nidos los cuales les dará protección en  los corrales  de incubación esperando hasta  su eclosión. ', '1', '20', 'Se realizaron  4  acciones de conservación mediante monitoreo, colecta, resembrado y liberación de  crías. ', 'Se realizaron  2 acciones ', 'No se realizo ninguna  acción ', NULL, 'Integrar comités o grupos comunitarios para  el monitoreo de especies', '1', '20', 'INTEGRACIÓN DE 3 GRUPOS', 'INTEGRACIÓN DE 2 GRUPO', 'NO SE INTEGRO NINGUN GRUPO', NULL, '.Organizar diversos eventos (talleres, grupos de enfoque, acciones locales) para socializar la importancia de la  conservación de los ecosistemas y su  biodiversidad, con otros sectoreS', '4', '20', '5 EVENTOS', '3  EVENTOS ', '1  EVENTO', NULL, 'ATENDER  SOLICITUDES DE PROREST Y PROCODES ', '10', '20', '100%  SOLICITUDES  ATENDIDAS', '75%  SOLICITUDES ATENDIDAS', '50% DE   SOLICITUDES  ATENDIDAS', NULL, 'APOYAR EN LA  OPERACIÓN   DE, PROYECTOS   PROREST Y PROCODES QUE HAGAN COMPATIBLE EL APROVECHAMIENTO, LA CONSERVACIÓN Y LA PROTECCIÓN DE LOS RECURSOS NATURALES DEL ÁREA. ESTRATEGIAS  ', '4', '20', '3 PROYECTOS ', '2 PROYECTOS', '0 PROYECTOS', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Se realizo 1  acción  ', 'INTEGRACIÓN DE 1 GRUPO', '2  EVENTO', '70%  SOLICITUDES  ATENDIDAS', '1 PROYECTO', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (1142, 'AUEX830920', 'COORDINAR ACCIONES DE GESTIÓN QUE FORTALECEN LAS ESTRATEGIAS DE LAS UNIDADES FUNCIONALES DE LA DIRECCIÓN REGIONAL FRONTERA SUR, ISTMO Y PACÍFICO SUR. ', '5', '20', 'SE CUMPLE DEL 90% AL 100% LAS ACTIVIDADES PROGRAMADAS PARA CADA UNA DE LAS ÁREAS FUNCIONALES DE LA DIRECCIÓN REGIONAL', 'SE CUMPLE DEL 80% AL 90% LAS ACTIVIDADES PROGRAMADAS PARA CADA UNA DE LAS ÁREAS FUNCIONALES DE LA DIRECCIÓN REGIONAL', 'SE CUMPLE AL MENOS EL 70% LAS ACTIVIDADES PROGRAMADAS PARA CADA UNA DE LAS ÁREAS FUNCIONALES DE LA DIRECCIÓN REGIONAL', NULL, 'APOYO Y GESTIÓN EN LA FORMULACIÓN DE PROYECTOS ESTRATÉGICOS INTERNOS Y RECURSOS QUE FORTALECEN EL MANEJO Y/O ADMINISTRACIÓN DE LAS ÁREAS NATURALES PROTEGIDAS Y SUS ZONAS DE INFLUENCIA DE LA DIRECCIÓN REGIONAL (CONABIO, FANP, ENTRE OTROS).', '4', '20', 'SE CUMPLE DEL 90% AL 100% EL APOYO Y GESTIÓN EN LA FORMULACIÓN DE PROYECTOS ESTRATÉGICOS INTERNOS Y RECURSOS QUE FORTALECEN EL MANEJO Y/O ADMINISTRACIÓN DE LAS ANP ', 'SE CUMPLE DEL 80% AL 90% EL APOYO Y GESTIÓN EN LA FORMULACIÓN DE PROYECTOS ESTRATÉGICOS INTERNOS Y RECURSOS QUE FORTALECEN EL MANEJO Y/O ADMINISTRACIÓN DE LAS ANP ', 'SE CUMPLE DEL 60% AL 70% EL APOYO Y GESTIÓN EN LA FORMULACIÓN DE PROYECTOS ESTRATÉGICOS INTERNOS Y RECURSOS QUE FORTALECEN EL MANEJO Y/O ADMINISTRACIÓN DE LAS ANP ', NULL, 'COORDINAR, APOYAR Y DAR SEGUIMIENTO A LAS ACTIVIDADES DE LA OFICINA DE LA DIRECCIÓN REGIONAL, REUNIONES INTERINSTITUCIONALES, ORGANIZACIONES NO GUBERNAMENTALES Y SOCIEDAD CIVIL.', '4', '20', 'SE APOYA Y/O COORDINA DEL 90% AL 100% LAS REUNIONES INTERINSTITUCIONALES, ORGANIZACIONES NO GUBERNAMENTALES Y SOCIEDAD CIVIL.', 'SE APOYA Y/O COORDINA DEL 70% AL 90% LAS REUNIONES INTERINSTITUCIONALES, ORGANIZACIONES NO GUBERNAMENTALES Y SOCIEDAD CIVIL.', 'SE APOYA Y/O COORDINA EL 60% AL 70% LAS REUNIONES INTERINSTITUCIONALES, ORGANIZACIONES NO GUBERNAMENTALES Y SOCIEDAD CIVIL.', NULL, 'COORDINAR Y DAR SEGUIMIENTO A RESPUESTAS DE VOLANTES DE GESTIÓN,