INSERT INTO `sed_individuales` VALUES (1067, 'OULC721213', 'ELABORAR Y COORDINAR LA EJECUCION DEL PROGRAMA OPERATIVO ANUAL (POA) DEL ANP CON BASE EN EL DECRETO, EN LAS METAS DE LA ESTRATEGIA REGIONAL Y PROGRAMA NACIONAL, ASI COMO ELABORAR Y ENTREGAR EN TIEMPO Y FORMA LOS INFORMES TRIMESTRALES DE LAS ACCIONES Y AVANCES OBTENIDOS DENTRO DEL ANP', '4', '25', 'EL POA Y LOS INFORMES TRIMESTRALES FUERON ELABORADOS Y ENTREGADOS EN TIEMPO Y FORMA, LOS OBJETIVOS Y METAS FUERON CUMPLIDOS EN UN 90-100%', 'EL POA Y LOS INFORMES FUERON ELABORADOS Y ENTREGADOS EN TIEMPO Y FORMA, LOS OBJETIVOS Y METAS FUERON CUMPLIDOS EN UN 80-89%', 'EL POA Y LOS INFORMES TRIMESTRALES FUERON ELABORADOS Y ENTREGADOS EN TIEMPO Y FORMA, LOS OBJETIVOS Y METAS FUERON CUMPLIDOS EN MENOS DEL 69%', NULL, 'SEGUIMIENTO A LOS RECURSOS ASIGNADOS PARA CADA ANP CORRESPONDIENTES A LOS PROGRAMAS ASISTENCIALES, PROCODES Y PROREST', '5', '25', 'MAS DE 90% DE LOS RECURSOS ASIGNADOS', 'DEL 80 A 89% DE LOS RECURSOS ASIGNADOS', 'MENOS DEL 69% DE LOS RECURSOS ASIGNADOS', NULL, 'DAR RESPUESTA A LAS SOLICITUDES DE OPINIONES TECNICAS SOBRE PROYECTOS, LICENCIAS, PERMISOS, AUTORIZACIONES Y DEMAS RESOLUCIONES ADMINISTRATIVAS EN EL AREA NATURAL PROTEGIDA A FIN DE CONTRIBUIR AL CUMPLIMIENTO DE LOS OBJETIVOS DE LA COMISION NACIONAL DE AREAS NATURALES PROTEGIDAS', '4', '20', 'ATENDER EN TIEMPO Y FORMA EL 90 AL 100% DE SOLICITUDES INGRESADAS', 'ATENDER EN TIEMPO Y FORMA EL 80 A 89% DE SOLICITUDES INGRESADAS', 'ATENDER EN TIEMPO Y FORMA MENOS DE 70% DE SOLICITUDES INGRESADAS', NULL, 'REALIZAR ACTIVIDADES ADMINISTRATIVAS, DE COORDINACIÓN DE PERSONAL OPERATIVO Y DE LOGÍSTICA, ASÍ COMO DE GESTIÓN DE RECURSOS MATERIALES, HUMANOS, TECNOLÓGICOS, FINANCIEROS Y/O JURÍDICOS QUE SE REQUIERAN, DENTRO DE SU ÁMBITO DE APLICACIÓN, ASEGURANDO EL CUMPLIMIENTO NORMATIVO Y LA CONSECUCIÓN DE LAS ACTIVIDADES Y LA ADECUADA OPERACIÓN DEL ANP.', '4', '20', '86 A 100%', '70 A 85%', 'MENOR DE 60%', NULL, 'LAS DEMÁS QUE LE CONFIERA Y/O INSTRUYA SU JEFE INME