INSERT INTO `sed_individuales` VALUES (1086, 'BOGN830101', 'Difundir, operar y dar seguimiento al Programa de Conservación para el Desarrollo Sostenible (PROCODES)	', '10', '35', 'Difundir, operar y dar seguimiento, entre un 80-100 %, al Programa de Conservación para el Desarrollo Sostenible (PROCODES)', 'Difundir, operar y dar seguimiento, entre un 50-79 %, al Programa de Conservación para el Desarrollo Sostenible (PROCODES)', 'Difundir, operar y dar seguimiento, entre un 0-24 %, al Programa de Conservación para el Desarrollo Sostenible (PROCODES)', NULL, 'Alimentar las bases de datos del sistema de información correspondiente al ejercicio de los recursos y cumplimiento de metas de los proyectos aprobados y ejecutados del PROCODES, así como al Sistema de Información de los Comités de Contraloría Social.', '10', '25', 'Alimentar entre el 80-100 % la base de datos del sistema de información correspondiente al ejercicio de los recursos y cumplimiento de metas de los proyectos aprobados y ejecutados del PROCODES, así como al Sistema de Información de los Comités de Contraloría Social.	', 'Alimentar entre el 50-79 % la base de datos del sistema de información correspondiente al ejercicio de los recursos y cumplimiento de metas de los proyectos aprobados y ejecutados del PROCODES, así como al Sistema de Información de los Comités de Contraloría Social.	', 'Alimentar entre el 0-24 % la base de datos del sistema de información correspondiente al ejercicio de los recursos y cumplimiento de metas de los proyectos aprobados y ejecutados del PROCODES, así como al Sistema de Información de los Comités de Contraloría Social.	', NULL, 'Dar respuesta a las solicitudes de información recibidas a través de la Plataforma Nacional de Transparencia.', '10', '20', 'Dar respuesta entre el 80-100 % de las solicitudes de información recibidas a través de la Plataforma Nacional de Transparencia	', 'Dar respuesta entre el 50-79 % de las solicitudes de información recibidas a través de la Plataforma Nacional de Transparencia	', 'Dar respuesta entre el 0-24 % de las solicitudes de información recibidas a través de la Plataforma Nacional de Transparencia	', NULL, 'Dar seguimiento a los tratados y acuerdos internacionales que la Dirección del ANP contraiga, y verificar el cumplimiento de metas y objetivos de los mismos.', '10', '20', 'Dar entre el 80-100 % de seguimiento a los tratados y acuerdos internacionales que la Dirección del ANP contraiga, y verificar el cumplimiento de metas y objetivos de los mismos.', 'Dar entre el 50-79 % de seguimiento a los tratados y acuerdos internacionales que la Dirección del ANP contraiga, y verificar el cumplimiento de metas y objetivos de los mismos.', 'Dar entre el 0-24 % de seguimiento a los tratados y acuerdos internacionales que la Dirección del ANP contraiga, y verificar el cumplimiento de metas y objetivos de los mismos.', NULL, NULL, '10', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Difundir, operar y dar seguimiento, entre un 25-49 %, al Programa de Conservación para el Desarrollo Sostenible (PROCODES)', 'Alimentar entre el 25-49 % la base de datos del sistema de información correspondiente al ejercicio de los recursos y cumplimiento de metas de los proyectos aprobados y ejecutados del PROCODES, así como al Sistema de Información de los Comités de Contraloría Social.	', 'Dar respuesta entre el 25-49 % de las solicitudes de información recibidas a través de la Plataforma Nacional de Transparencia	', 'Dar entre el 25-49 % de seguimiento a los tratados y acuerdos internacionales que la Dirección del ANP contraiga, y verificar el cumplimiento de metas y objetivos de los mismos.', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
