INSERT INTO `sed_individuales` VALUES (1095, 'LERF801116', 'Conjuntar la Información y realizar los informes trimestrales del departamento de vigilancia para el POA fiscal e informes semestrales para el POA FANP.', '1', '25', 'Conjuntar la información y realizar los informes del departamento de vigilancia en un 100% a un 80%.', 'Conjuntar la información y realizar los informes del departamento de vigilancia en menos del 80%', 'No conjuntar la información y no realizar ninguno de los informes del departamento de vigilancia.', NULL, 'Operar y dar seguimiento al Programa de Conservación para el Desarrollo Sostenible (PROREST) en los proyectos de Vigilancia y Monitoreo Comunitario para el concepto de apoyo de Vigilancia y Monitoreo Comunitario.', '1', '25', 'Operar y dar seguimiento al Programa de Conservación para el Desarrollo Sostenible (PROREST) vigilancia y monitoreo comunitario en un 100% a un 80%.', 'Operar y dar seguimiento a los Programa de Conservación para el Desarrollo Sostenible (PROREST) vigilancia y monitoreo comunitario en menos de un 80%.', 'NO operar y ni dar seguimiento a los Programa de Conservación para el Desarrollo Sostenible (PROREST) vigilancia y monitoreo comunitario.', NULL, 'Dar continuidad al proyecto de Señalización de Sitios de uso Público mediante la instalación y mantenimiento del sistema de boyas de amarre y señalización.', '1', '20', 'Dar continuidad al proyecto de señalización de sitios de uso público mediante la instalación y mantenimiento al Sistema de Boyas de Amarre y Señalización en un 100% a un 80%.', 'Dar continuidad al proyecto de señalización de sitios de uso público mediante la instalación y mantenimiento al Sistema de Boyas de Amarre y Señalización en menos de un 80%.', 'No dar continuidad al proyecto de señalización de sitios de uso público mediante la instalación y mantenimiento al Sistema de Boyas de Amarre y Señalización', NULL, 'Participar como guardaparque o capitán en las salidas de supervisión y vigilancia.', '1', '20', 'Participar entre el 100% y el 80% de las salidas comisionadas como guardaparque o capitán.', 'Participar en menos del 80% de las salidas comisionadas como guardaparque o capitán.', 'No participar como guardaparque o capitán en las salidas de supervisión y vigilancia.', NULL, 'Mantener actualizadas las bases de datos de actas y denuncias en formato físico y digital.', '1', '10', 'Mantener actualizadas las bases de datos de actas y denuncias con el 100% o 80% de las actas y denuncias. ', 'Mantener actualizadas las bases de datos de actas y denuncias con menos del 80% de las actas y denuncias. ', 'NO mantener actualizadas las bases de datos de actas y denuncias.	', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Conjuntar la información y realizar los informes del departamento de vigilancia en menos del 70%', 'Operar y dar seguimiento a los Programa de Conservación para el Desarrollo Sostenible (PROREST) vigilancia y monitoreo comunitario en menos de un 70%.', 'Dar continuidad al proyecto de señalización de sitios de uso público mediante la instalación y mantenimiento al Sistema de Boyas de Amarre y Señalización en menos un 70%.', 'Participar en menos del 70% de las salidas comisionadas como guardaparque o capitán.', 'Mantener actualizadas las bases de datos de actas y denuncias con menos del 70% de las actas y denuncias. ', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (1096, 'LEAC700718', 'Realizar recorrido de vigilancia, de pagos de derechos y recorridos nocturnos dentro del APFFIGC Y PNZMAES.', '2', '50', 'Realizar entre 20 y 24 recorridos dentro del APFFIGC Y PNZMAES para verificar el pago de derecho y recorridos nocturnos.', 'Realizar entre 16 y 19 recorridos dentro del APFFIGC Y PNZMAES para verificar el pago de derecho y recorridos nocturnos.', 'realizar menos de 10 recorridos dentro del APFF IGC Y PNZMAES', NULL, 'Apoyo administrativo a las bitácoras de combustible, vehículos, embarcaciones, cotizaciones, correspondencia, radio reporte. ', '10', '10', 'Se realiza el apoyo administrativo entre un 80% y 90%.', 'Se realiza el apoyo administrativo entre un 70% y 80%', 'se realiza el apoyo entre un 50%', NULL, 'se apoya en el monitoreo de tortuga marina, aves marinas (desenmalle de lobo) marino monitoreo de liebre negra.', '1', '20', 'Se apoya en el monitoreo 2 a 3 monitoreos al mes', 'se apoya en monitoreo 2 a 1 por mes', 'no se apoya en ningún monitoreo', NULL, 'Se realiza el mantenimiento preventivo básicos remolques, embarcaciones y/o vehículos.', '1', '20', 'Se realizan entre 8 y 10 mantenimientos anuales.', 'Se realizan entre 5 a 7 mantenimientos anuales.', 'no se realiza ningún mantenimiento .', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'realizar menos de 15 recorridos dentro del APFF IGC Y PNZMAES', 'se realiza el apoyo entre un 60%', 'se apoya de en monitoreo 1 al mes ', 'Se realizan entre 4 mantenimientos anuales.', NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
