INSERT INTO `sed_individuales` VALUES (1169, 'EEBA911221', 'Promover la conservación del Parque Nacional Cumbres de Monterrey y regularizar las actividades turísticas mediante la implementación del Cobro de Derechos, de conformidad con la Ley Federal de Derechos.', '1', '20', 'Más de 1000 brazaletes vendidos', 'Entre 500 y 1000 brazaletes vendidos', 'Menos de 100 brazaletes vendidos', NULL, 'Ordenamiento de las actividades turísticas a través de la regularización de los prestadores de servicios turísticos que operan al interior del Parque Nacional Cumbres de Monterrey.', '1', '20', 'Más de 20 prestadores regularizados', 'Entre 10 y 20 prestadores regularizados', 'Ningún prestador regularizado', NULL, 'Atención a presuntos ilícitos ambientales por cambio y uso de suelo forestal y/o actividades turísticas sin ordenamiento, mediante la realización de recorridos de vigilancia y denuncias turnadas ante las dependencias correspondientes.', '1', '20', '20 recorridos y 20 denuncias', '10 recorridos y 10 denuncias', 'sin recorridos y sin denuncias', NULL, 'Promover la conservación del Parque Nacional Cumbres de Monterrey a través de medidas que orienten las actividades turístico-recreativas hacia modelos sustentables.', '2', '20', 'La situación turística ha mejorado notoriamente', 'La situación turística ha mejorado poco', 'La situación turística se ha deteriorado', NULL, 'Atención y seguimiento a las actividades turísticas que se realizan al interior del Parque Nacional Cumbres de Monterrey, a través de reuniones de coordinación con dependencias gubernamentales, organizaciones no gubernamentales y usuarios. ', '1', '20', 'Más de cinco reuniones de coordinación', 'Entre dos y cuatro reuniones de coordinación', 'Ninguna reunión de coordinación', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'Entre 100 y 500 brazaletes vendidos', 'Entre uno y 10 prestadores regularizados', 'cinco recorridos y cinco denuncias', 'La situación turística no ha mejorado', 'Una reunión de coordinación', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
