INSERT INTO `sed_individuales` VALUES (1175, 'MUJL741026', 'Contribuir al seguimiento de la implementación de proyectos y/o actividades, promovidos por la UNESCO, en Reservas de la Biosfera MaB.', '10', '25', 'Se atienden más del 80% de los proyectos y/o actividades implementadas', 'Entre el 79% y el 70% de los proyectos y/o actividades son implementadas', 'Menos del 69% de los proyectos y/o actividades son implementadas', NULL, 'Apoyar en la revisión e integración de informes en atención a solicitudes remitidas a la Dirección.', '10', '35', 'Más del 80% de informes son revisados e integrados en tiempo y forma.', 'Entre el 79% y 70% de informes son revisados e integrados en tiempo y forma.', 'Menos del 69% de los informes son revisados e integrados en tiempo y forma', NULL, 'Supervisar, asesorar y proporcionar información necesaria, para atender los diferentes requerimientos y actividades solicitados a la Dirección en tiempo y forma.', '1', '40', ' Más del 80% de la información se supervisa y asesora para atender los requerimientos y actividades en tiempo y forma.', 'Entre el 79% y 70% de la información se supervisa y asesora para atender los requerimientos y actividades en tiempo y forma.', 'Menos del 69% de la información se supervisa y asesora para atender los requerimientos y actividades en tiempo y forma.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, 'El 69% de los proyectos y/o actividades son implementadas', 'El 69% de los informes son revisados e integrados en tiempo y forma.', 'El 69% de la información se supervisa y asesora para atender los requerimientos y actividades en tiempo y forma.', NULL, NULL, '2025-04-24 09:29:58', '2025-04-24 09:29:58');
