INSERT INTO `sed_individuales` VALUES (1182, 'KAFA590913', 'Colaborar en la participación en las reuniones de los Comités Estatales de Manejo de Fuego de la regional FSIPS.', '5', '10', 'Participar en al menos el 80 % de la reuniones de los comités de manejo del fuego', 'En al menos el 70 % de la reuniones de los comités de manejo del fuego', 'En al menos el 40 % de la reuniones de los comités de manejo del fuego', NULL, 'Fortalecer en la capacitación de manera presencial y/o distancia a guardaparques manejadores del fuego en los temas de Gestión de Riesgos y Manejo Integral del Fuego. ', '5', '20', 'Se capacitará del 90% al 80% del total de guardaparques manejadores del fuego de la RFSIPS', 'Se capacitará del 79% al 60% del total de guardaparques manejadores del fuego de la RFSIPS', 'Se capacitará del 49% al 30% del total de guardaparques manejadores del fuego de la RFSIPS', NULL, 'Apoyar en la formulación del Programa Regional de Manejo Intercultural del Fuego de la Región Frontera Sur.', '4', '20', 'Se elabora al 90% el programa regional de manejo intercultural del fuego ', 'Se elabora al 80% el programa regional de manejo intercultural del fuego ', 'Se elabora al 60% el programa regional de manejo intercultural del fuego ', NULL, 'Colaborar para la actualización de la infraestructura, equipo, herramienta para la atención a contingencias ambientales, así como de las capacidades de los guardaparques manejadores del fuego de las ANP y oficinas operativas Istmo Oaxaqueño y La Chinantla.', '5', '30', 'Se obtiene el 90% de información actualizada de campamentos y oficinas operativas de la Dirección Regional FSIPS y capacidades de los guardaparques manejadores del fuego', 'Se obtiene el 80% de información actualizada de campamentos y oficinas operativas de la Dirección Regional FSIPS y capacidades de los guardaparques manejadores del fuego', 'Se obtiene el 60% de información actualizada de campamentos y oficinas operativas de la Dirección Regional FSIPS y capacidades d