INSERT INTO `sed_individuales` VALUES (1185, 'CASK740709', 'ANALIZA LA INFORMACIÓN DE LOS DICTÁMENES TÉCNICOS DE SOPORTE QUE EMITEN LAS DIRECCIONES REGIONALES, PARA ELABORAR LAS OPINIONES TÉCNICAS EN MATERIA DE VIDA SILVESTRE Y CAMBIO DE USO DEL SUELO EN TERRENOS FORESTALES Y OTRAS REQUERIDAS EN LAS ANP COMPETENCIA DE LA FEDERACIÓN, CUANDO EL PROYECTO INCIDE EN MÁS DE UNA DIRECCIÓN REGIONAL Y ATENDIENDO AL TIEMPO ESTABLECIDO POR LA AUTORIDAD QUE SOLICITA', '1', '30', 'Elaborar de 4 a 5 propuestas de opiniones técnicas.', 'Elaborar de 2 a 3 propuestas de opiniones técnicas', 'Elaborar 0 propuestas de opiniones técnicas', NULL, 'PROPORCIONAR ASESORARÍA Y ORIENTACIÓN TÉCNICA, CUANDO LO REQUIERAN LAS DIRECCIONES REGIONALES Y DIRECCIONES DE ÁREAS NATURALES PROTEGIDAS, CON LA FINALIDAD DE QUE SE EMITAN OPINIONES TÉCNICAS EN MATERIA DE VIDA SILVESTRE Y CAMBIO DE USO DE SUELO, CON LA DEBIDA MOTIVACIÓN Y FUNDAMENTACIÓN', '1', '25', 'Proporcionar asesoría y/o asistencia técnica de 7 a 9 ocasiones', ' Proporcionar asesoría y/o asistencia técnica de 4 a 6 ocasiones', 'No proporcionar asesoría y/o asistencia técnica', NULL, 'PROPONER EL DISEÑO Y CONTENIDO DE LOS EVENTOS DE CAPACITACIÓN, QUE TENGAN QUE VER CON OPINIONES TÉCNICAS EN LAS MATERIAS DE VIDA SILVESTRE Y CAMBIO DE USO DE SUELO', '1', '10', 'Proporcionar apoyo para realizar  2 o mas eventos de capacitación con las especificaciones requeridas', 'Proporcionar el apoyo necesario para realizar de 2 talleres sin las especificaciones requeridas', 'No proporcionar apoyo para realizar talleres', NULL, 'ANALIZAR LA INFORMACIÓN QUE SE SOLICITA RESPECTO DE INICIATIVAS DE REFORMAS O MODIFICACIONES A DIFERENTES LEYES E INSTRUMENTOS NORMATIVOS Y EN SU CASO, PARTICIPAR EN REUNIONES DE TRABAJO, A FIN DE ELABORAR UNA PROPUESTA DE RESPUESTA CORRESPONDIENTE, DE ACUERDO CON EL PERÍODO REQUERIDO', '1', '10', 'Generar opiniones de 4 a 5 veces', 'Generar opiniones de  2 a 3 veces', 'No generar opiniones.', NULL, 'COORDINAR LOS TRABAJOS DE CLASIFICACIÓN, EXPURGO E INTEGRACIÓN DE LOS EXPEDIENTES QUE FORMAN PARTE DEL ÁREA, PARA DAR SEGUIMIENTO EN BASE A LOS PLAZOS DE CONSERVACIÓN ESTABLECIDOS EN LA NORMATIVIDAD', '10', '25', 'Avanzar con el 80 % de los expedientes', 'Avanzar con el 60 % de los expedientes', 'No tener avances', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, ' Elaborar solo 1 propuesta de opinion técnica', 'Proporcionar asesoría y/o asistencia técnica de 3 a 5 ocasiones', 'Proporcionar el apoyo necesario para realizar 1 taller sin las especificaciones requeridas', 'Generar opiniones en 1 ocasión', 'Avanzar con el 40 % de los expedientes', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
INSERT INTO `sed_individuales` VALUES (1186, 'NACP690819', 'ASESORAR LO NORMATIVO Y TÉCNICO LA IMPLEMENTACIÓN DEL PROGRAMA DE CONSERVACIÓN PARA EL DESARROLLO SOSTENIBLE (PROCODES) EN LAS ÁREAS NATURALES PROTEGIDAS Y ÁREAS DESTINADAS VOLUNTARIAMENTE A LA CONSERVACIÓN (ADVC) ADSCRITAS A LA DIRECCIÓN REGIONAL CENTRO Y EJE NEOVOLCANICO\r\n', '10', '25', '100', '75', '25', NULL, ' ASESORAR EN LO NORMATIVO Y TÉCNICO LA IMPLEMENTACIÓN DEL PROREST EN SUS COMPONENTES DE CONSERVACIÓN COMUNITARIO EN LAS ÁREAS NATURALES PROTEGIDAS Y ÁREAS DESTINADAS VOLUNTARIAMENTE A AL CONSERVACIÓN ADVC ADSCRITAS A LA DIRECCIÓN REGIONAL CENTRO Y EJE NEOVOLCANICO\r\n', '10', '20', '90', '75', '25', NULL, 'COORDINAR Y  ASESORAR A LAS AREAS NATURALES PROTEGIDAS Y ÁREAS DESTINADAS VOLUNTARIAMENTE A LA CONSERVACIÓN EN EL MANEJO INTEGRADO DEL FUEGO, ASÍ COMO EL ACOMPAÑAMIENTO EN LA ACTIVACIÓN DE BRIGADAS COMUNITARIAS CON RECURSOS INTERNOS Y EXTERNOS.\r\n', '10', '25', '90', '75', '25', NULL, 'ACOMPAÑAMIENTO Y ASESORÍA EN TEMAS DE SANIDAD FORESTAL EN LAS AREAS NATURALES PROTEGIDAS Y AREAS DESTINADAS VOLUNTARIAMENTE A LA CONSERVCIÓN QUE LO REQUIERAN EN LA ATENCIÓN PARA EL CONTROL DE PLAGAS Y ENFERMEDADES FORESTALES\r\n', '10', '15', '90', '75', '25', NULL, 'COORDINAR LAS ACCIONES DE RESTAURACIÓN ECOLÓGICA Y PRODUCTIVA MEDIANTE EL ASESORAMIENTO EN EL DISEÑO, IMPLEMENTACIÓN Y SEGUIMEINTO DE OBRAS EN LAS AREAS NATURALES PROTEGIDAS Y ÁREAS DESTINADAS VOLUNTARIAMENTE A LA CONSERVACIÓN.\r\n', '10', '15', '90', '75', '25', NULL, NULL, NULL, 1, '2025', NULL, NULL, NULL, NULL, NULL, '50', '50', '50', '50', '50', '2025-04-24 09:29:58', '2025-04-24 09:29:58');
